    /** Bytes after the first __halt_compiler(); in the compiled script, if any (#3479). */
    public function getHaltCompilerRemaining(): ?string
    {
        return $this->haltCompilerRemaining;
    }

    /** Byte offset of halt trailing data; null when the unit has no __halt_compiler() (#5455). */
    public function getHaltCompilerOffset(): ?int
    {
        return $this->haltCompilerOffset;
    }

    /**
     * Recompute halt offset from user script bytes when parse input was transformed (#4378).
     *
     * MCJIT embed prepends bootstrap classes (bin/jit.php); trailing payload is unchanged.
     */
    public function reconcileHaltCompilerOffsetFromSource(string $userSource): void
    {
        if (null === $this->haltCompilerRemaining) {
            return;
        }
        $this->haltCompilerOffset = strlen($userSource) - strlen($this->haltCompilerRemaining);
    }

    /**
     * Marks the CFG construct that halted compilation before throwing LogicException (#2642).
     *
     * @return never
     */
    protected function throwCompileLogic(string $detail): void
    {
        if (null === $this->compileAbortDetail) {
            $this->compileAbortDetail = $detail;
        }

        throw new \LogicException($detail);
    }

    /**
     * Like {@see throwCompileLogic} but enriches abort detail with CFG file/line (#2988).
     */
    protected function throwCompileLogicForOp(Op $op, string $detail): void
    {
        if (
            str_contains($detail, 'Unknown ')
            || str_contains($detail, 'Unsupported ')
        ) {
            $detail = Lint\Issue::fromOp($op, $detail)->formatHuman();
        }

        $this->throwCompileLogic($detail);
    }

    /**
     * Like throwCompileLogic for CompileError paths (#2642).
     *
     * @return never
     */
    protected function throwCompileError(string $detail, ?string $sourceFile = null, ?int $sourceLine = null): void
    {
        if (null === $this->compileAbortDetail) {
            $this->compileAbortDetail = $detail;
        }

        if (null !== $sourceFile) {
            throw new CompileFatal($sourceFile, max(1, $sourceLine ?? 1), $detail);
        }

        throw new \CompileError($detail);
    }

    public function compile(Script $script): ?Block {
        $this->resetCompileAbortDetail();
        $this->coalesceResultSlots = [];
        $this->coalesceMergeBlocks = [];
        $this->nullsafeResultSlots = [];
        $this->nullsafeMergeBlocks = [];
        $this->syncedCoalesceFuncCallArgSlots = [];
        $this->compileTimeEnumBackedTypes = [];
        $this->compileTimeEnumCaseConstNames = [];
        $this->compileTimeGlobalConsts = [];
        $this->haltCompilerRemaining = null;
        $this->haltCompilerOffset = null;
        $this->compiledClassStaticProperties = [];
        $this->currentClassStaticPropertyCompile = null;
        $this->neverFunctionNames = [];
        $this->userFunctionParamByRef = [];
        $this->scriptHasDnfTypedProperties = false;
        $this->classCompileRegistry = new ClassCompileRegistry();
        $this->attributeClassRegistry = new AttributeClassRegistry();
        $this->seen = new SplObjectStorage;
        $this->ternaryMergeVarSlots = new SplObjectStorage;
        $this->ternaryMergePhiRhsSlots = new SplObjectStorage;
        $this->rewrittenNeNullReturnJumpIf = new SplObjectStorage;
        $this->earlyBoundFunctionOps = new SplObjectStorage;
        $this->debugWriteLastPhase('Compiler::compile enter');

        Compiler\InheritanceVariance::validateScript(
            $script,
            function (string $detail): void {
                $this->throwCompileError($detail);
            }
        );

        // Const-expr context checks before compileCfgBlock / PHPTypes folding (#10106, #6549, #6580).
        ThrowInClassConstCompileCheck::validate($script);
        NewWithoutParensCompileCheck::validate($script, $this->compileSourceCode);
        FunctionStaticAnonymousClassCompileCheck::validate($script);
        NonAbstractMethodBodyCheck::validate($script);

        /** @var mixed $main */
        $main = $this->compileCfgBlock($script->main->cfg, $script->main->params, $script->main);
        if (!$main instanceof Block) {
            // Self-host AOT can surface unexpected stub returns as null; capture a stable diagnostic.
            if (null === $this->compileAbortDetail) {
                $this->compileAbortDetail = 'Compiler::compile: compileCfgBlock returned non-Block';
            }
            $this->seen = null;

            return null;
        }

        $this->seen = null;

        if ($this->scriptHasDnfTypedProperties) {
            $this->appendMcjitDnfPropertyTryEpilogue($main);
        }

        NonEnumBuiltinInterfaceCompileCheck::validate($script);
        InterfaceImplementationCheck::validate($script, $this->propertyHookRegistry);
        TraitCollisionCheck::validate($script, $this->propertyHookRegistry);
        FinalClassExtensionCheck::validate($script);
        ImplementsHierarchyCompileCheck::validate($script);
        FinalMethodOverrideCheck::validate($script);
        FinalPropertyOverrideCheck::validate($script, $this->propertyHookRegistry);
        TypedPropertyInheritCheck::validate($script);
        OverrideValidator::validateScript($script);
        FinalClassConstCheck::validate($script);
        TraitClassConstConflictCheck::validate($script);
        TypedClassConstInheritCheck::validate($script);
        ClassConstVisibilityInheritCheck::validate($script);
        PropertyVisibilityInheritCheck::validate($script);
        InterfaceConstVisibilityCheck::validate($script);
        InterfaceConstAmbiguityCheck::validate($script, $this->vmContext);
        InterfaceMethodVisibilityCheck::validate($script);
        InterfaceMethodFinalCheck::validate($script);
        InterfaceMethodBodyCheck::validate($script);
        AbstractMethodBodyCheck::validate($script);
        AbstractMethodVisibilityCheck::validate($script);
        MagicMethodArityCheck::validate($script);
        MagicMethodParamTypeCheck::validate($script);
        MagicMethodReturnTypeCheck::validate($script);
        MagicMethodStaticCheck::validate($script);
        EnumMagicMethodCheck::validate($script);
        EnumBuiltinMethodRedeclareCheck::validate($script);
        EnumAbstractMethodCompileCheck::validate($script);
        EnumParentCompileCheck::validate($script);
        EnumBackedCaseCheck::validate($script);
        ClassConstDuplicateCheck::validate($script);
        ReadonlyClassCompileCheck::validate($script, $this->knownClassReadonly, $this->propertyHookRegistry);
        AsymmetricVisibilityCompileCheck::validate($script);
        VariadicPromotedPropertyCompileCheck::validate($script);
        AbstractPromotedPropertyCompileCheck::validate($script);
        GeneratorStaticMethodCompileCheck::validate($script);
        GeneratorNeverReturnCompileCheck::validate($script);

        if (null !== $this->haltCompilerOffset) {
            $main->haltCompilerOffset = $this->haltCompilerOffset;
        }

        return $main;
    }

    /** M3 emit TU: trivial single-block sources without full seen-map compile (#1937). */
    public function compileEmitSmoke(Script $script): ?Block
    {
        $this->resetCompileAbortDetail();
        $this->coalesceResultSlots = [];
        $this->coalesceMergeBlocks = [];
        $this->nullsafeResultSlots = [];
        $this->nullsafeMergeBlocks = [];
        $this->syncedCoalesceFuncCallArgSlots = [];
        $this->classCompileRegistry = new ClassCompileRegistry();
        $this->attributeClassRegistry = new AttributeClassRegistry();
        // Inventory-scale sources declare user functions and/or class-like units; emit-smoke only needs {main}
        // — same as compile() without a compile() callee in the M3 emit TU (#2633, #2666).
        if ([] !== $script->functions || $this->emitSmokeScriptHasClassLike($script)) {
            $this->seen = new SplObjectStorage;
        }
        $this->ternaryMergeVarSlots = new SplObjectStorage;
        $this->ternaryMergePhiRhsSlots = new SplObjectStorage;
        $this->rewrittenNeNullReturnJumpIf = new SplObjectStorage;
        $this->earlyBoundFunctionOps = new SplObjectStorage;
        $block = $this->compileCfgBlock($script->main->cfg, $script->main->params, $script->main);
        $this->seen = null;
        if (null === $block && null !== $this->compileAbortDetail && '' !== $this->compileAbortDetail) {
            echo 'Compiler::compileEmitSmoke: '.$this->compileAbortDetail."\n";
        }

        return $block;
    }

    /**
     * Emit-smoke is intended for small scripts; class-like constructs are a strong signal that
     * we should run the full compile path (self-host M5, #2666).
     */
    private function emitSmokeScriptHasClassLike(Script $script): bool
    {
        foreach ($script->main->cfg->children as $child) {
            if (
                $child instanceof Op\Stmt\Class_
                || $child instanceof Op\Stmt\Interface_
                || $child instanceof Op\Stmt\Trait_
                || $child instanceof Op\Stmt\Enum_
            ) {
                return true;
            }
        }

        return false;
    }

    public function compileFunc(string $name, CfgFunc $func): Func {
        $this->resetCompileAbortDetail();
        $this->classCompileRegistry = new ClassCompileRegistry();
        $this->attributeClassRegistry = new AttributeClassRegistry();
        $this->seen = new SplObjectStorage;

        $funcBlock = $this->compileCfgBlock($func->cfg, $func->params, $func);
        $this->seen = null;
        return new Func\PHP($name, $funcBlock);
    }

    protected function applyReturnTypeFromFunc(Block $block, CfgFunc $func): void
    {
        // php-cfg marks file-level {main} as void; only enforce on user functions/methods (#205).
        if ('{main}' === $func->name && null === $func->class) {
            return;
        }
        $returnType = $func->returnType;
        // php-cfg represents “no return type” as null or Mixed_; Zend auto-declares `: string`
        // for untyped `__toString` (zend_compile.c / #26402).
        if (null === $returnType || $returnType instanceof Op\Type\Mixed_) {
            if ($this->applyImplicitToStringStringReturn($block, $func)) {
                return;
            }
            if (null === $returnType) {
                return;
            }
            // Untyped (Mixed_) non-__toString: no scalar constraint.
            $block->returnDeclaredType = $returnType;

            return;
        }
        $this->rejectPseudoClassTypeHintOutsideClassScope($returnType, $block, $func);
        $this->rejectParentTypeHintWithoutParent($returnType);
        $this->assertIntersectionTypeMembers($returnType);
        // void before never — Zend prefers "Void can only…" when both appear in a union (#26517).
        $this->assertFunctionSignatureVoidType($returnType);
        $this->assertFunctionSignatureNeverType($returnType);
        $this->assertMixedTypeRules($returnType);
        $block->returnDeclaredType = $returnType;
        if ($returnType instanceof Op\Type\Void_) {
            $block->returnTypeVoid = true;

            return;
        }
        if ($returnType instanceof Op\Type\Never_) {
            $block->returnTypeNever = true;

            return;
        }
        if ($returnType instanceof Op\Type\Reference) {
            $refName = $this->staticNameFromOperand($returnType->declaration);
            if ('static' === strtolower((string) $refName)) {
                $block->returnTypeStatic = true;

                return;
            }
            if (null !== $refName && '' !== $refName) {
                $resolved = $this->resolveTypeHintClassName($refName, $block);
                if (null !== $resolved && '' !== $resolved) {
                    $block->returnTypeConstraint = Variable::TYPE_OBJECT;
                    $block->returnClassConstraint = $resolved;
                    // Zend TypeError prints the resolved class for self/parent (zend_execute_API.c);
                    // keep unresolved trait `parent` as the keyword (#29911, #29912).
                    $block->returnDeclaredTypeLabel = ltrim($resolved, '\\');
                }

                return;
            }
        }
        if ($this->cfgTypeUsesDnfShape($returnType)) {
            $dnfArms = DnfType::armsFromCfgType(
                $returnType,
                fn (Op\Type\Intersection $t) => $this->intersectionNamesFromCfgType($t, $block),
                fn (Op\Type\Intersection $t) => $this->intersectionDisplayFromCfgType($t, $block),
                fn (Op\Type\Reference $t) => $this->resolvedDnfReferenceNameFromCfgType($t, $block)
            );
            if (DnfType::hasConstraints($dnfArms)) {
                $block->returnDnfConstraints = $dnfArms;

                return;
            }
        }
        if ($returnType instanceof Op\Type\Literal) {
            if ('void' === $returnType->name) {
                $block->returnTypeVoid = true;

                return;
            }
            if ('never' === $returnType->name) {
                $block->returnTypeNever = true;

                return;
            }
            if ('static' === $returnType->name) {
                $block->returnTypeStatic = true;

                return;
            }
            if ('mixed' === strtolower($returnType->name)) {
                // Explicit `: mixed` is not untyped — fall-off / bare `return;` must error (#26485).
                $block->returnTypeMixed = true;
                $block->returnDeclaredTypeLabel = 'mixed';

                return;
            }
            $returnLc = strtolower($returnType->name);
            if ('true' === $returnLc || 'false' === $returnLc) {
                $block->returnTypeConstraint = Variable::TYPE_BOOLEAN;
                $block->returnLiteralBoolType = $returnLc;

                return;
            }
            // Bare `: callable` — Variable::mapFromType has no TYPE_CALLABLE mapping, so
            // without DNF arms zend_verify_return_type is skipped (#29887). Reuse the same
            // literal-arm path as ?callable / callable|… unions (DnfCheck / DnfParamCheck).
            if ('callable' === $returnLc) {
                $block->returnDnfConstraints = [['kind' => 'literal', 'name' => 'callable']];

                return;
            }
            // Bare `: iterable` — mapFromType treats it as a class name, so returns reject
            // arrays and TypeError says "iterable". Use the iterable DNF arm (array|Traversable
            // match) with Zend TypeError display Traversable|array (#29888 / #4829 sibling).
            if ('iterable' === $returnLc) {
                $block->returnDnfConstraints = [
                    ['kind' => 'literal', 'name' => 'iterable', 'display' => 'Traversable|array'],
                ];
                $block->returnDeclaredTypeLabel = 'iterable';

                return;
            }
            $declType = Type::fromDecl($returnType->name);
            $mapped = Variable::mapFromType($declType);
            if (Variable::TYPE_OBJECT === $mapped) {
                $className = '' !== (string) $declType->userType ? $declType->userType : $returnType->name;
                $block->returnTypeConstraint = Variable::TYPE_OBJECT;
                $block->returnClassConstraint = $className;
                $block->returnDeclaredTypeLabel = ltrim($className, '\\');

                return;
            }
            if (Variable::TYPE_UNDEFINED !== $mapped) {
                $block->returnTypeConstraint = $mapped;
            }
        }
    }

    /**
     * php-src: Zend/zend_compile.c — untyped `__toString` is compiled as returning string.
     * Enables zend_verify_return_type under strict_types (#26402); Reflection sees `: string`.
     *
     * @return bool true when the implicit string return was applied
     */
    private function applyImplicitToStringStringReturn(Block $block, CfgFunc $func): bool
    {
        $stringType = $this->implicitToStringReturnType($func);
        if (null === $stringType) {
            return false;
        }
        $block->returnDeclaredType = $stringType;
        $block->returnTypeConstraint = Variable::TYPE_STRING;

        return true;
    }

    /**
     * Zend auto-declares `: string` when `__toString` has no user-written return type.
     * php-cfg represents that absence as {@see Op\Type\Mixed_}.
     */
    private function implicitToStringReturnType(CfgFunc $func): ?Op\Type\Literal
    {
        if ('__tostring' !== strtolower($func->name)) {
            return null;
        }
        $returnType = $func->returnType;
        if (null !== $returnType && !($returnType instanceof Op\Type\Mixed_)) {
            return null;
        }

        return new Op\Type\Literal('string');
    }

    /**
     * php-cfg appends a null Terminal_Return after exit(); skip it for :never (issue #1358).
     */
    protected function neverFunctionHasAbnormalExitBeforeReturn(CfgBlock $block, Op\Terminal\Return_ $return): bool
    {
        foreach ($block->children as $child) {
            if ($child === $return) {
                return false;
            }
            if ($child instanceof Op\Expr\Exit_) {
                return true;
            }
        }

        return false;
    }

    /**
     * Zend allows implicit fall-off on :never (runtime TypeError); explicit `return;` is compile fatal (#4206).
     * php-cfg synthetic trailing returns have no source attributes; user `return;` carries startLine.
     */
    protected function neverFunctionReturnIsImplicitFalloff(Op\Terminal\Return_ $return): bool
    {
        $attrs = $return->getAttributes();

        return [] === $attrs || !isset($attrs['startLine']);
    }

    /**
     * Arrow `fn(): never => expr` is not Zend's explicit-`return` compile fatal — expression bodies
     * TypeError at call time with "must not implicitly return" (zend_compile.c / #30020).
     */
    protected function neverFunctionIsArrowExpressionBody(Block $block): bool
    {
        $func = $block->func;
        if (null === $func) {
            return false;
        }

        return ($func->callableOp ?? null) instanceof Op\Expr\ArrowFunction;
    }

    /**
     * @param list<Op\Expr\Param> $params
     */
    protected function assertNoDuplicateParameterNames(array $params): void
    {
        $seen = [];
        foreach ($params as $param) {
            if (!($param->name instanceof Operand\Literal) || !is_string($param->name->value)) {
                continue;
            }
            $name = $param->name->value;
            if (isset($seen[$name])) {
                // Zend/zend_compile.c — file+line CompileFatal for CLI "Fatal error:" shape (#29979).
                $detail = sprintf('Redefinition of parameter $%s', $name);
                $sourceFile = $param->getFile();
                if ('' === $sourceFile) {
                    $sourceFile = 'unknown';
                }
                if (null === $this->compileAbortDetail) {
                    $this->compileAbortDetail = $detail;
                }
                throw new CompileFatal($sourceFile, max(1, $param->getLine()), $detail);
            }
            $seen[$name] = true;
        }
    }

    /**
     * @param list<Op\Expr\Param> $params
     */
    protected function assertVariadicParamIsLast(array $params): void
    {
        $seenVariadic = false;
        foreach ($params as $param) {
            if ($param->variadic) {
                $seenVariadic = true;
                continue;
            }
            if ($seenVariadic) {
                $this->throwCompileError('Only the last parameter can be variadic');
            }
        }
    }

    /**
     * @param list<Op\Expr\Param> $params
     */
    protected function assertNoDuplicateParameterAttributes(array $params, ?CfgFunc $func = null): void
    {
        AttributeConstantEvaluator::withUserlandConstContext(
            $this->userlandConstScalarsForAttributes(),
            $this->namespaceHintFromFunc($func),
            function () use ($params): void {
                foreach ($params as $param) {
                    $entries = AttributeMetadata::fromOp($param);
                    $names = AttributeEntry::namesFromList($entries);
                    AttributeNames::assertAllowDynamicPropertiesClassTargetOnly($names, 'parameter', $entries);
                    AttributeNames::assertAttributeMetaClassTargetOnly($names, 'parameter', $entries);
                    AttributeNames::assertOverrideMethodTargetOnly($names, 'parameter', $entries);
                    AttributeNames::assertCompileTimeConstTargetOnly($names, 'parameter', $entries);
                    AttributeNames::assertSensitiveParameterParamTargetOnly($names, 'parameter', $entries);
                    AttributeNames::assertReturnTypeWillChangeMethodTargetOnly($names, 'parameter', $entries);
                    AttributeNames::assertDeprecatedTargetAllowed($names, 'parameter', $entries);
                    AttributeNames::validateDuplicates($entries, $this->attributeClassRegistry);
                }
            }
        );
    }

    /**
     * php-src: Zend/zend_compile.c — readonly on parameters is only valid in __construct (#6291).
     *
     * @param list<Op\Expr\Param> $params
     */
    protected function assertReadonlyParamOnlyInConstructor(array $params, ?CfgFunc $func): void
    {
        if (null !== $func && '__construct' === $func->name && null !== $func->class) {
            return;
        }
        foreach ($params as $param) {
            if (!$this->isPromotedParamReadonly($param)) {
                continue;
            }
            $this->throwCompileError('Cannot declare promoted property outside a constructor');
        }
    }

    /**
     * @param list<Operand\BoundVariable> $closureUseVars
     */
    protected function registerClosureUseCapturesOnBlock(Block $funcBlock, array $closureUseVars): void
    {
        foreach ($closureUseVars as $useVar) {
            $name = $this->boundVariableName($useVar);
            $slot = $funcBlock->getVarSlot($useVar, false);
            $funcBlock->closureCaptureSlots[$slot] = true;
            $funcBlock->closureCaptureSlotNames[$slot] = $name;
            if ($useVar->byRef) {
                $funcBlock->closureCaptureByRef[$slot] = true;
            }
        }
    }

    /**
     * @param list<Operand\BoundVariable> $closureUseVars
     */
    protected function compileCfgBlock(
        CfgBlock $block,
        array $params = [],
        ?CfgFunc $func = null,
        array $closureUseVars = []
    ): Block {
        if (null === $this->seen) {
            $this->seen = new SplObjectStorage;
        }
        if (!$this->seen->contains($block)) {
            $savedDeferredArrayLiteralKeepSlots = $this->deferredArrayLiteralKeepSlots;
            $this->deferredArrayLiteralKeepSlots = [];
            $this->seen[$block] = $new = new Block($block);
            if ($this->compilingArrowAutoCapture) {
                $new->arrowAutoCapture = true;
            }
            if (null !== $func) {
                $new->func = $func;
                $new->strictTypes = isset($func->strictTypes) ? (bool) $func->strictTypes : false;
                $this->applyReturnTypeFromFunc($new, $func);
            }
            if ([] !== $params) {
                $this->assertNoDuplicateParameterNames($params);
                $this->assertNoDuplicateParameterAttributes($params, $func);
                $this->assertReadonlyParamOnlyInConstructor($params, $func);
                $this->assertVariadicParamIsLast($params);
            }
            $paramIdx = 0;
            foreach ($params as $param) {
                $new->addOpCode($this->compileParam($param, $new, $paramIdx++));
            }
            if (null !== $func && '__construct' === $func->name && null !== $func->class) {
                $this->compileCtorPromotionAssignments($new, $params);
            }
            if ([] !== $closureUseVars) {
                $this->registerClosureUseCapturesOnBlock($new, $closureUseVars);
            }
            // Zend early-binds top-level function decls in {main} for the whole compile unit
            // (not nested in if/try/switch/loop). php-cfg places those Stmt_Function in later
            // merge blocks after try/if, so per-block hoist alone misses call sites inside the
            // control-flow body that appear textually before the declaration (#24807).
            if (
                null !== $func
                && '{main}' === $func->name
                && null === $func->class
                && $block === $func->cfg
            ) {
                // Attribute args on early-bound FUNCDEFs fold userland consts; those consts are
                // otherwise prescanned only inside compileOps, which runs after this hoist (#26628).
                $this->prescanCompileTimeGlobalConsts($block->children, $new);
                $this->emitEarlyBoundFunctionDefs($block, $new);
            }
            $this->compileBlock($new);
            foreach ($this->deferredArrayLiteralKeepSlots as $slot => $_) {
                $new->deferredArrayLiteralKeepSlots[$slot] = true;
            }
            $this->deferredArrayLiteralKeepSlots = $savedDeferredArrayLiteralKeepSlots;
        }
        /** @var mixed $out */
        $out = $this->seen[$block] ?? null;
        if (!$out instanceof Block) {
            if (null === $this->compileAbortDetail) {
                $this->compileAbortDetail = 'Compiler::compileCfgBlock: seen map returned non-Block';
            }
            // Best effort: keep going with a fresh Block so callers can surface a meaningful abort later.
            $out = new Block($block);
            $this->seen[$block] = $out;
        }

        return $out;
    }

    /**
     * CFG branch target within the current function: inherit parent locals ($this, params).
     */
    protected function compileCfgBranch(CfgBlock $block, Block $parent): Block {
        if (!$this->seen->contains($block)) {
            $this->seen[$block] = $new = new Block($block);
            $new->inheritScopeFrom($parent);
            if (!$this->compilingSwitchJumpIfChain) {
                $this->inheritCfgVarSlotsFromSiblingCfgBranches($block, $new);
                $this->applyTernaryMergeVarSlots($block, $new);
            }
            if ($this->isErrorSuppressEndBlock($block)) {
                $this->inheritErrorSuppressExpressionSlots($parent, $new);
            }
            $this->inheritFuncFromParent($new, $parent);
            // Match/ternary branch blocks reuse unnamed temporaries (subject slot) from the parent (#4274).
            $new->inheritUndefinedLocals = true;
            if ($block instanceof ErrorSuppressBlock) {
                $new->addOpCode(new OpCode(OpCode::TYPE_BEGIN_SILENCE));
            }
            $this->compileBlock($new);
            if (!$this->compilingSwitchJumpIfChain) {
                $this->recordTernaryMergeVarSlots($block, $new);
            }
        } else {
            $child = $this->seen[$block];
            // Merge blocks already mapped on first branch; sibling inheritScopeFrom
            // adds duplicate slot indices and breaks ?: echo (#3790).
            // Try/catch end often has only one CFG parent (the catch), so the parents>=2
            // guard does not apply — re-inheriting from the catch aliases method-name /
            // "caught:" temps onto the merge echo slot and AFTER prints the wrong string
            // (#23930, #23641 AFTER regression). Skip once the merge already has opcodes.
            if (\count($block->parents) < 2 && 0 === $child->nOpCodes) {
                $child->inheritScopeFrom($parent);
                if ($this->isErrorSuppressEndBlock($block)) {
                    $this->inheritErrorSuppressExpressionSlots($parent, $child);
                }
            }
            $this->inheritFuncFromParent($child, $parent);
        }
        $child = $this->seen[$block];
        $child->parents[] = $parent;

        return $child;
    }

    /** Switch/if/loop targets need enclosing Func for JIT visibility (#210, #588). */
    private function inheritFuncFromParent(Block $child, Block $parent): void
    {
        if (null !== $parent->func) {
            $child->func = $parent->func;
            $child->strictTypes = $parent->strictTypes;
            // Merge blocks skip inheritScopeFrom when parents>=2 (#3790); still need
            // return-type flags so :never epilogue checks run on implicit fall-off (#9240).
            $child->returnTypeConstraint = $parent->returnTypeConstraint;
            $child->returnClassConstraint = $parent->returnClassConstraint;
            $child->returnDeclaredTypeLabel = $parent->returnDeclaredTypeLabel;
            $child->returnDnfConstraints = $parent->returnDnfConstraints;
            $child->returnTypeVoid = $parent->returnTypeVoid;
            $child->returnTypeNever = $parent->returnTypeNever;
            $child->returnTypeStatic = $parent->returnTypeStatic;
            $child->returnTypeMixed = $parent->returnTypeMixed;
            $child->returnDeclaredType = $parent->returnDeclaredType;
            $child->returnLiteralBoolType = $parent->returnLiteralBoolType;
        }
    }

    /**
     * ?: / if branches must assign the merge temporary in one scope slot (#3790, #137).
     */
    private function inheritCfgVarSlotsFromSiblingCfgBranches(CfgBlock $cfgBlock, Block $compiled): void
    {
        foreach ($cfgBlock->children as $child) {
            if (!$child instanceof Op\Stmt\Jump) {
                continue;
            }
            $merge = $child->target;
            if (\count($merge->parents) < 2) {
                continue;
            }
            foreach ($merge->parents as $siblingCfg) {
                if ($siblingCfg === $cfgBlock || !$this->seen->contains($siblingCfg)) {
                    continue;
                }
                $compiled->inheritCfgVarSlotsFrom($this->seen[$siblingCfg]);
            }
        }
    }

    /**
     * @return list<CfgBlock>
     */
    private function ternaryMergeTargets(CfgBlock $branchCfg): array
    {
        $merges = [];
        foreach ($branchCfg->children as $child) {
            if (!$child instanceof Op\Stmt\Jump) {
                continue;
            }
            $merge = $child->target;
            if (\count($merge->parents) >= 2) {
                $merges[] = $merge;
            }
        }

        return $merges;
    }

    /** CFG block jumped to at the end of a ?: / if branch (may have one parent while lowering). */
    private function branchJumpMergeTarget(CfgBlock $branchCfg): ?CfgBlock
    {
        foreach ($branchCfg->children as $child) {
            if ($child instanceof Op\Stmt\Jump) {
                return $child->target;
            }
        }

        return null;
    }

    /** Foreach loop heads use Iterator_Valid — not ?: merge blocks (#5657). */
    private function isForeachIteratorHeaderCfgBlock(CfgBlock $cfg): bool
    {
        foreach ($cfg->children as $child) {
            if ($child instanceof Op\Iterator\Valid) {
                return true;
            }
        }

        return false;
    }

    /** Both ?: arms jump to the same CFG merge block (echo/assign phi, #3790, #5510). */
    private function jumpIfTargetsTernaryMerge(Op\Stmt\JumpIf $stmt): bool
    {
        $ifMerge = $this->branchJumpMergeTarget($stmt->if);
        $elseMerge = $this->branchJumpMergeTarget($stmt->else);
        if (null === $ifMerge || $ifMerge !== $elseMerge) {
            return false;
        }
        if (\count($ifMerge->parents) < 2) {
            return false;
        }

        return $this->mergeCfgBlockUsesTernaryPhi($ifMerge);
    }

    /**
     * `||` short-circuit: php-cfg puts literal `true` on JumpIf->if and (bool) cast on ->else.
     * Lower else before if so the cast arm records the phi slot for the literal arm (#12745).
     */
    private function jumpIfTargetsLogicalOrShortCircuitLiteralIf(Op\Stmt\JumpIf $stmt): bool
    {
        $ifMerge = $this->branchJumpMergeTarget($stmt->if);
        $elseMerge = $this->branchJumpMergeTarget($stmt->else);
        if (null === $ifMerge || $ifMerge !== $elseMerge) {
            return false;
        }
        if (!$this->mergeCfgBlockUsesLogicalShortCircuit($ifMerge)) {
            return false;
        }
        $ifTail = $this->branchTailExprBeforeJump($stmt->if);
        $elseTail = $this->branchTailExprBeforeJump($stmt->else);

        return $ifTail instanceof Op\Expr\Assign
            && $ifTail->expr instanceof Operand\Literal
            && $elseTail instanceof Op\Expr\Cast\Bool_;
    }

    /**
     * `&&` short-circuit: php-cfg puts (bool) cast on JumpIf->if and literal `false` on ->else.
     * Lower if before else so the cast arm records the phi slot (#24506) — the opposite of `||`.
     */
    private function jumpIfTargetsLogicalAndShortCircuitCastIf(Op\Stmt\JumpIf $stmt): bool
    {
        $ifMerge = $this->branchJumpMergeTarget($stmt->if);
        $elseMerge = $this->branchJumpMergeTarget($stmt->else);
        if (null === $ifMerge || $ifMerge !== $elseMerge) {
            return false;
        }
        if (!$this->mergeCfgBlockUsesLogicalShortCircuit($ifMerge)) {
            return false;
        }
        $ifTail = $this->branchTailExprBeforeJump($stmt->if);
        $elseTail = $this->branchTailExprBeforeJump($stmt->else);

        return $ifTail instanceof Op\Expr\Cast\Bool_
            && $elseTail instanceof Op\Expr\Assign
            && $elseTail->expr instanceof Operand\Literal;
    }

    /** Both ?: arms jump to a merge block ending in RETURN (#4280, #8563). */
    private function jumpIfTargetsReturnMerge(Op\Stmt\JumpIf $stmt): bool
    {
        $ifMerge = $this->branchJumpMergeTarget($stmt->if);
        $elseMerge = $this->branchJumpMergeTarget($stmt->else);
        if (null === $ifMerge || $ifMerge !== $elseMerge) {
            return false;
        }
        foreach ($ifMerge->children as $child) {
            if ($child instanceof Op\Terminal\Return_) {
                return true;
            }
        }

        return false;
    }

    /**
     * `null !== $param ? $param : null` mis-lowers in AOT when the param arm is if-entry (#8563).
     * Rewrite to `null === $param ? null : $param` at compile time (php-src equivalent).
     */
    private function shouldRewriteNullableNeNullReturnTernary(
        Op\Stmt\JumpIf $stmt,
        ?Op\Expr\BinaryOp\NotIdentical $ne = null
    ): bool {
        if (!$this->jumpIfTargetsReturnMerge($stmt)) {
            return false;
        }
        if (null !== $ne) {
            return $this->branchCfgAssignsNullConst($stmt->else)
                && $this->branchCfgAssignsNonNullValue($stmt->if)
                && ($this->operandIsNull($ne->left) || $this->operandIsNull($ne->right));
        }
        $ne = $this->unwrapOperandToNotIdentical($stmt->cond);
        if (null === $ne) {
            return false;
        }

        return $this->branchCfgAssignsNullConst($stmt->else)
            && $this->branchCfgAssignsNonNullValue($stmt->if)
            && ($this->operandIsNull($ne->left) || $this->operandIsNull($ne->right));
    }

    private function operandIsNull(Operand $operand): bool
    {
        if ($operand->type instanceof Type && Type::TYPE_NULL === $operand->type->type) {
            return true;
        }

        return $this->exprIsNullConst($operand);
    }

    private function unwrapOperandToNotIdentical(Operand $operand): ?Op\Expr\BinaryOp\NotIdentical
    {
        while ($operand instanceof Operand\Temporary) {
            if ($operand->original instanceof Op\Expr\BinaryOp\NotIdentical) {
                return $operand->original;
            }
            if (null === $operand->original) {
                return null;
            }
            $operand = $operand->original;
        }

        return $operand instanceof Op\Expr\BinaryOp\NotIdentical ? $operand : null;
    }

    private function branchCfgAssignsNullConst(CfgBlock $branchCfg): bool
    {
        foreach ($branchCfg->children as $child) {
            if ($child instanceof Op\Expr\Assign && null !== $child->expr && $this->operandIsNull($child->expr)) {
                return true;
            }
        }

        return false;
    }

    private function exprIsNullConst(Operand $expr): bool
    {
        while ($expr instanceof Operand\Temporary && null !== $expr->original) {
            if ($expr->original instanceof Op\Expr\ConstFetch) {
                return $this->constFetchIsNull($expr->original);
            }
            $expr = $expr->original;
        }

        return $expr instanceof Op\Expr\ConstFetch && $this->constFetchIsNull($expr);
    }

    /** Explicit null literal in a call arg list — not a hoisted inline closure temp (#14893). */
    private function callArgIsNullLiteral(
        ?Operand $arg,
        ?Op $cfgCallOp = null,
        ?int $argIndex = null,
        ?Block $block = null
    ): bool {
        if (null === $arg) {
            return false;
        }
        if ($arg instanceof Operand\NullOperand) {
            return true;
        }
        if ($this->exprIsNullConst($arg)) {
            return true;
        }
        if ($arg instanceof Op\Expr\ConstFetch && $this->constFetchIsNull($arg)) {
            return true;
        }
        if (
            null !== $cfgCallOp
            && null !== $block
            && null !== $argIndex
            && $this->callArgIsDeadInlineTemporary($arg)
        ) {
            $prelude = $this->hoistedDeadInlinePreludeProducerForCallArgIndex($cfgCallOp, $argIndex, $block);
            if ($prelude instanceof Op\Expr\ConstFetch && $this->constFetchIsNull($prelude)) {
                return true;
            }
            // `new C(null, [...])` — Array_ sits between ConstFetch null and New_, so the
            // immediate-prelude walker misses null; use ordinal producer match (#22770).
            if (null !== $block->orig && property_exists($cfgCallOp, 'args') && \is_array($cfgCallOp->args)) {
                $producers = $this->precedingInlineCallArgProducersBeforeCfgOp(
                    $block->orig->children,
                    $cfgCallOp
                );
                if ([] !== $producers) {
                    $matched = $this->matchInlineCallArgProducer(
                        $producers,
                        $cfgCallOp->args,
                        $argIndex,
                        $cfgCallOp,
                        $block
                    );
                    if ($matched instanceof Op\Expr\ConstFetch && $this->constFetchIsNull($matched)) {
                        return true;
                    }
                }
            }
        }

        return false;
    }

    private function constFetchIsNull(Op\Expr\ConstFetch $fetch): bool
    {
        $name = $fetch->name;
        while ($name instanceof Operand\Temporary && null !== $name->original) {
            $name = $name->original;
        }

        return $name instanceof Operand\Literal
            && 'null' === strtolower((string) $name->value);
    }

    /**
     * Zend IS_CONST array-unpack of non-array (null/true/false/int/float/string) is
     * compile-time E_ERROR; named consts and variables are runtime catchable (#27952).
     */
    private function isCompileTimeNonTraversableArrayUnpackOperand(Operand $operand): bool
    {
        if ($operand instanceof Operand\Literal) {
            return !is_array($operand->value);
        }
        foreach ($operand->ops as $op) {
            if (!$op instanceof Op\Expr\ConstFetch) {
                continue;
            }
            $name = $op->name;
            while ($name instanceof Operand\Temporary && null !== $name->original) {
                $name = $name->original;
            }
            if (!$name instanceof Operand\Literal || !is_string($name->value)) {
                continue;
            }
            $lc = strtolower($name->value);
            if ('null' === $lc || 'true' === $lc || 'false' === $lc) {
                return true;
            }
        }

        return false;
    }

    /**
     * ADD_ARRAY_UNPACK compile-time Fatal message — PHP 8.4+ appends {@code , <type> given} (#30055).
     */
    private function arrayUnpackNonTraversableCompileMessage(Operand $operand): string
    {
        if ($operand instanceof Operand\Literal) {
            return VM\ArraySpread::nonTraversableMessageForPhpValue($operand->value);
        }
        foreach ($operand->ops as $op) {
            if (!$op instanceof Op\Expr\ConstFetch) {
                continue;
            }
            $name = $op->name;
            while ($name instanceof Operand\Temporary && null !== $name->original) {
                $name = $name->original;
            }
            if (!$name instanceof Operand\Literal || !is_string($name->value)) {
                continue;
            }
            $lc = strtolower($name->value);
            if ('null' === $lc) {
                return VM\ArraySpread::nonTraversableMessageForPhpValue(null);
            }
            if ('true' === $lc) {
                return VM\ArraySpread::nonTraversableMessageForPhpValue(true);
            }
            if ('false' === $lc) {
                return VM\ArraySpread::nonTraversableMessageForPhpValue(false);
            }
        }

        return VM\ArraySpread::NON_TRAVERSABLE_MESSAGE;
    }

    private function branchCfgAssignsNonNullValue(CfgBlock $branchCfg): bool
    {
        foreach ($branchCfg->children as $child) {
            if ($child instanceof Op\Expr\Assign && !$this->exprIsNullConst($child->expr)) {
                return true;
            }
        }

        return false;
    }

    private function funcReturnTypeIsNullableScalar(Block $block): bool
    {
        if (null === $block->func) {
            return false;
        }
        $returnType = $block->func->returnType;

        return $returnType instanceof Op\Type\Nullable;
    }

    private function operandIsImplicitNullableParam(Operand $operand, Block $block): bool
    {
        if (!$operand instanceof CfgVariable) {
            return false;
        }
        if (null === $block->func) {
            return false;
        }
        $varName = $operand->name;
        while ($varName instanceof Temporary && null !== $varName->original) {
            $varName = $varName->original;
        }
        if (!$varName instanceof Literal || !is_string($varName->value)) {
            return false;
        }
        foreach ($block->func->params as $param) {
            $paramName = $param->name;
            while ($paramName instanceof Temporary && null !== $paramName->original) {
                $paramName = $paramName->original;
            }
            if (!$paramName instanceof Literal || $paramName->value !== $varName->value) {
                continue;
            }
            if ($param->declaredType instanceof Op\Type\Nullable) {
                return true;
            }
            $slot = $block->slotForOperand($param->result);

            return null !== $slot && isset($block->paramImplicitNullable[$slot]);
        }

        return false;
    }

    /** `return (null ?… $param : null)` / `return (null !== $param ? $param : null)` → `$param ?? null` (#8563). */
    private function nullableParamFromReturnTernaryArms(Op\Stmt\JumpIf $stmt, Block $block): ?Operand
    {
        if (!$this->jumpIfTargetsReturnMerge($stmt) || !$this->funcReturnTypeIsNullableScalar($block)) {
            return null;
        }
        $ifNull = $this->branchCfgAssignsNullConst($stmt->if);
        $elseNull = $this->branchCfgAssignsNullConst($stmt->else);
        if ($ifNull === $elseNull) {
            return null;
        }
        $valueBranch = $ifNull ? $stmt->else : $stmt->if;
        foreach ($valueBranch->children as $child) {
            if (!$child instanceof Op\Expr\Assign || null === $child->expr || $this->exprIsNullConst($child->expr)) {
                continue;
            }
            $src = $child->expr;
            while ($src instanceof Temporary && null !== $src->original) {
                $src = $src->original;
            }
            if ($src instanceof CfgVariable && $this->operandIsImplicitNullableParam($src, $block)) {
                return $src;
            }
        }

        return null;
    }

    private function syntheticNullConstOperand(): Operand
    {
        $nullLit = new Literal(null);
        $nullLit->type = Type::null();

        return $nullLit;
    }

    /** AOT-safe lowering: implicit nullable param returns via ?? null (proven native ABI path). */
    private function emitImplicitNullableParamCoalesceReturn(Operand $paramOp, Block $block): void
    {
        $coalesce = new Op\Expr\BinaryOp\Coalesce($paramOp, $this->syntheticNullConstOperand());
        $endBlock = $this->compileCoalesce($coalesce, $block);
        $endBlock->addOpCode(new OpCode(
            OpCode::TYPE_RETURN,
            $this->compileOperand($coalesce->result, $endBlock, true)
        ));
    }

    /** `?:` in `echo`/concat merge uses echo phi slots; `return ?:` uses RETURN (#4280); `throw ?:` uses TYPE_THROW (#7037). */
    private function mergeCfgBlockUsesEchoPhi(CfgBlock $merge): bool
    {
        foreach ($merge->children as $child) {
            if ($child instanceof Op\Terminal\Echo_) {
                return true;
            }
            if ($child instanceof Op\Terminal\Throw_) {
                return true;
            }
        }

        return false;
    }

    /** `$s = $cond ? $a : $b` merge assigns a shared phi temporary into a named local (#9159). */
    private function mergeCfgBlockUsesAssignPhi(CfgBlock $merge): bool
    {
        if (\count($merge->parents) < 2) {
            return false;
        }
        foreach ($merge->children as $child) {
            if (!$child instanceof Op\Expr\Assign) {
                continue;
            }
            $destRoot = Block::cfgVarRoot($child->var);
            if (!$destRoot instanceof Operand\Variable) {
                continue;
            }
            $phiOperand = $child->expr;
            if (!$phiOperand instanceof Operand) {
                continue;
            }
            $matchedParents = 0;
            foreach ($merge->parents as $parent) {
                $armVar = $this->mergeBranchAssignVarOperand($parent);
                if (null === $armVar) {
                    continue;
                }
                if ($this->operandsReferToSameVariable($armVar, $phiOperand)) {
                    ++$matchedParents;
                }
            }
            if ($matchedParents >= 2) {
                return true;
            }
        }

        return false;
    }

    /**
     * ?: arms assign to a shared merge temporary (#15816, Zend/zend_compile.c).
     */
    private function mergeCfgBlockUsesTernaryBranchLiteralAssign(CfgBlock $merge): bool
    {
        if (\count($merge->parents) < 2) {
            return false;
        }
        $armVar = null;
        foreach ($merge->parents as $parent) {
            $tail = $this->branchTailExprBeforeJump($parent);
            if (!$tail instanceof Op\Expr\Assign) {
                return false;
            }
            if (null === $armVar) {
                $armVar = $tail->var;
            } elseif (!$this->operandsReferToSameVariable($tail->var, $armVar)) {
                return false;
            }
        }

        return null !== $armVar;
    }

    private function mergeCfgBlockUsesTernaryPhi(CfgBlock $merge): bool
    {
        return $this->mergeCfgBlockUsesEchoPhi($merge)
            || $this->mergeCfgBlockUsesAssignPhi($merge)
            || $this->mergeCfgBlockUsesTernaryBranchLiteralAssign($merge)
            || $this->mergeCfgBlockUsesLogicalShortCircuit($merge);
    }

    /** && / || merge: one arm ends in (bool) cast, sibling in literal assign (php-cfg parseShortCircuiting). */
    private function mergeCfgBlockUsesLogicalShortCircuit(CfgBlock $merge): bool
    {
        if (\count($merge->parents) < 2) {
            return false;
        }
        $hasBoolCastArm = false;
        $hasLiteralAssignArm = false;
        foreach ($merge->parents as $parent) {
            $tail = $this->branchTailExprBeforeJump($parent);
            if ($tail instanceof Op\Expr\Cast\Bool_) {
                $hasBoolCastArm = true;
            }
            if ($tail instanceof Op\Expr\Assign && $tail->expr instanceof Operand\Literal) {
                $hasLiteralAssignArm = true;
            }
        }

        return $hasBoolCastArm && $hasLiteralAssignArm;
    }

    private function branchTailExprBeforeJump(CfgBlock $branch): ?Op\Expr
    {
        $children = $branch->children;
        for ($i = \count($children) - 1; $i >= 0; --$i) {
            $child = $children[$i];
            if ($child instanceof Op\Stmt\Jump) {
                continue;
            }
            if ($child instanceof Op\Expr) {
                return $child;
            }

            break;
        }

        return null;
    }

    /** && / || merge-arm tail before JUMP — literal assign dest or long-arm (bool) cast result (#10626, #12745). */
    private function logicalShortCircuitTailPhiSlot(Block $branchBlock): ?int
    {
        for ($i = $branchBlock->nOpCodes - 1; $i >= 0; --$i) {
            $op = $branchBlock->opCodes[$i];
            if (OpCode::TYPE_JUMP === $op->type) {
                continue;
            }
            if (OpCode::TYPE_ASSIGN === $op->type) {
                return (int) $op->arg2;
            }
            if (OpCode::TYPE_CAST_BOOL === $op->type) {
                return (int) $op->arg1;
            }

            break;
        }

        return null;
    }

    /** && / || short-arm literal assign — phi slot from already-compiled sibling tail (#12745). */
    private function logicalShortCircuitSiblingPhiSlot(Block $branch): ?int
    {
        if (null === $branch->orig) {
            return null;
        }
        $mergeCfg = $this->branchJumpMergeTarget($branch->orig);
        if (null === $mergeCfg) {
            return null;
        }
        foreach ($mergeCfg->parents as $parentCfg) {
            if ($parentCfg === $branch->orig || !$this->seen->contains($parentCfg)) {
                continue;
            }
            $phi = $this->logicalShortCircuitTailPhiSlot($this->seen[$parentCfg]);
            if (null !== $phi) {
                return $phi;
            }
        }

        return null;
    }

    /**
     * Phi slot for a ||/&& merge reached by JUMP from this block (#25850).
     *
     * Used when a (bool) cast lives inside an inner short-circuit merge (e.g. &&) but feeds an
     * outer || merge — {@see logicalShortCircuitPhiMergeSlot} would otherwise return the inner phi.
     */
    private function logicalShortCircuitJumpTargetPhiMergeSlot(Block $branch): ?int
    {
        if (null === $branch->orig) {
            return null;
        }
        foreach ($this->ternaryMergeTargets($branch->orig) as $mergeCfg) {
            if (!$this->mergeCfgBlockUsesLogicalShortCircuit($mergeCfg)) {
                continue;
            }
            $recorded = $this->ternaryMergePhiRhsSlot($mergeCfg);
            if (null !== $recorded) {
                return $recorded;
            }
            foreach ($mergeCfg->parents as $parentCfg) {
                if ($parentCfg === $branch->orig || !$this->seen->contains($parentCfg)) {
                    continue;
                }
                $phi = $this->logicalShortCircuitTailPhiSlot($this->seen[$parentCfg]);
                if (null !== $phi) {
                    return $phi;
                }
            }
        }

        return null;
    }

    /** && / || long-arm bool cast must store into the recorded phi merge slot (#10626). */
    private function logicalShortCircuitPhiMergeSlot(Block $branch): ?int
    {
        if (null === $branch->orig) {
            return null;
        }
        if (
            $this->mergeCfgBlockUsesLogicalShortCircuit($branch->orig)
            && \count($branch->orig->parents) >= 2
        ) {
            $recorded = $this->ternaryMergePhiRhsSlot($branch->orig);
            if (null !== $recorded) {
                return $recorded;
            }
            foreach ($branch->orig->parents as $parentCfg) {
                if (!$this->seen->contains($parentCfg)) {
                    continue;
                }
                $phi = $this->logicalShortCircuitTailPhiSlot($this->seen[$parentCfg]);
                if (null !== $phi) {
                    return $phi;
                }
            }
        }
        $jumpTargetPhi = $this->logicalShortCircuitJumpTargetPhiMergeSlot($branch);
        if (null !== $jumpTargetPhi) {
            return $jumpTargetPhi;
        }

        return null;
    }

    /**
     * Reserve one phi slot for `||` / `&&` short-circuit merge before both arms are lowered (#12745).
     *
     * @return int|null slot index stored in {@see $ternaryMergePhiRhsSlots}
     */
    private function seedLogicalShortCircuitPhiSlot(CfgBlock $branchCfg, Block $branch, Operand $phiOperand): ?int
    {
        $mergeCfg = $this->branchJumpMergeTarget($branchCfg);
        if (null === $mergeCfg || !$this->mergeCfgBlockUsesLogicalShortCircuit($mergeCfg)) {
            return null;
        }
        if ($this->ternaryMergePhiRhsSlots->contains($mergeCfg)) {
            return $this->ternaryMergePhiRhsSlots[$mergeCfg];
        }
        $slot = $branch->forceFreshVarSlot($phiOperand);
        $this->ternaryMergePhiRhsSlots[$mergeCfg] = $slot;
        $root = Block::cfgVarRoot($phiOperand);
        if (null !== $root) {
            $rootName = Block::resolveVariableName($root);
            if (null === $rootName || '' === $rootName) {
                if (!$this->ternaryMergeVarSlots->contains($mergeCfg)) {
                    $this->ternaryMergeVarSlots[$mergeCfg] = new SplObjectStorage();
                }
                /** @var SplObjectStorage<CfgVariable, int> $map */
                $map = $this->ternaryMergeVarSlots[$mergeCfg];
                $map[$root] = $slot;
            }
        }

        return $slot;
    }

    /** `||`-only phi slot for dead call-arg temps (do not disturb `&&` merge wiring). */
    private function logicalShortCircuitOrPhiMergeSlot(Block $branch): ?int
    {
        if (null === $branch->orig) {
            return null;
        }
        foreach ($this->ternaryMergeTargets($branch->orig) as $mergeCfg) {
            if (!$this->mergeCfgUsesLogicalOrShortCircuit($mergeCfg)) {
                continue;
            }
            $recorded = $this->ternaryMergePhiRhsSlot($mergeCfg);
            if (null !== $recorded) {
                return $recorded;
            }
        }

        return null;
    }

    private function mergeCfgUsesLogicalOrShortCircuit(CfgBlock $mergeCfg): bool
    {
        if (!$this->mergeCfgBlockUsesLogicalShortCircuit($mergeCfg)) {
            return false;
        }
        foreach ($mergeCfg->parents as $parentCfg) {
            $tail = $this->branchTailExprBeforeJump($parentCfg);
            if (
                $tail instanceof Op\Expr\Assign
                && $tail->expr instanceof Operand\Literal
                && true === $tail->expr->value
            ) {
                return true;
            }
        }

        return false;
    }

    /** exit($a && $b) ? … — dead call-arg temp must use && phi / parent cast slot (#11592). */
    private function resolveExitLogicalShortCircuitCallArgSlot(Block $block): ?string
    {
        $phi = $this->logicalShortCircuitPhiMergeSlot($block);
        if (null !== $phi) {
            return (string) $phi;
        }
        if (null === $block->orig) {
            return null;
        }
        foreach ($block->orig->parents as $parentCfg) {
            if (!$this->seen->contains($parentCfg)) {
                continue;
            }
            $parentBlock = $this->seen[$parentCfg];
            for ($i = $parentBlock->nOpCodes - 1; $i >= 0; --$i) {
                $op = $parentBlock->opCodes[$i];
                if (OpCode::TYPE_JUMP === $op->type) {
                    continue;
                }
                if (OpCode::TYPE_CAST_BOOL === $op->type) {
                    return (string) $op->arg1;
                }
                if (OpCode::TYPE_ASSIGN === $op->type) {
                    return (string) $op->arg2;
                }
                break;
            }
        }

        return null;
    }

    private function recordTernaryMergeVarSlots(CfgBlock $branchCfg, Block $compiled): void
    {
        $jumpMerge = $this->branchJumpMergeTarget($branchCfg);
        if (null !== $jumpMerge && $this->mergeCfgBlockUsesLogicalShortCircuit($jumpMerge)) {
            $this->recordTernaryMergePhiRhsSlot($jumpMerge, $compiled);
        }
        foreach ($this->ternaryMergeTargets($branchCfg) as $mergeCfg) {
            if (!$this->ternaryMergeVarSlots->contains($mergeCfg)) {
                $this->ternaryMergeVarSlots[$mergeCfg] = new SplObjectStorage();
            }
            /** @var SplObjectStorage<CfgVariable, int> $map */
            $map = $this->ternaryMergeVarSlots[$mergeCfg];
            $phiRoot = $this->mergeBranchAssignVarRoot($branchCfg);
            $phiSlot = null;
            if (null !== $phiRoot) {
                foreach ($compiled->eachCfgVarRootSlot() as [$root, $slot]) {
                    if ($root === $phiRoot) {
                        $phiSlot = $slot;
                        break;
                    }
                }
            }
            if (null === $phiSlot && $this->seen->contains($mergeCfg)) {
                $phiSlot = $this->mergePhiResultSlot($this->seen[$mergeCfg]);
            }
            if (null !== $phiRoot && null !== $phiSlot) {
                $map[$phiRoot] = $phiSlot;

                continue;
            }
            $this->recordTernaryMergePhiRhsSlot($mergeCfg, $compiled);
            foreach ($compiled->eachCfgVarRootSlot() as [$root, $slot]) {
                if (!$map->contains($root)) {
                    // && / || long arms read named locals (e.g. str_contains($out, …)); do not
                    // remap those roots through the bool-cast phi merge map (#15183, #10626).
                    if ($this->mergeCfgBlockUsesLogicalShortCircuit($mergeCfg)) {
                        $rootName = Block::resolveVariableName($root);
                        if (null !== $rootName && '' !== $rootName) {
                            continue;
                        }
                    }
                    $map[$root] = $slot;
                }
            }
        }
    }

    private function mergeBranchAssignVarRoot(CfgBlock $branchCfg): ?Operand\Variable
    {
        $assignVar = $this->mergeBranchAssignVarOperand($branchCfg);
        if (null === $assignVar) {
            return null;
        }
        $root = Block::cfgVarRoot($assignVar);

        return $root instanceof Operand\Variable ? $root : null;
    }

    private function mergeBranchAssignVarOperand(CfgBlock $branchCfg): ?Operand
    {
        $children = $branchCfg->children;
        $jumpIdx = null;
        foreach ($children as $i => $child) {
            if ($child instanceof Op\Stmt\Jump) {
                $jumpIdx = $i;
                break;
            }
        }
        if (null === $jumpIdx) {
            return null;
        }
        for ($i = $jumpIdx - 1; $i >= 0; --$i) {
            $child = $children[$i];
            if ($child instanceof Op\Expr\Assign) {
                return $child->var;
            }
            // && / || long arm: (bool) cast writes the phi; earlier assigns are RHS side effects (#24506).
            if ($child instanceof Op\Expr\Cast\Bool_) {
                return null;
            }
            if (!$child instanceof Op\Expr) {
                break;
            }
        }

        return null;
    }

    private function applyTernaryMergeVarSlots(CfgBlock $branchCfg, Block $compiled): void
    {
        foreach ($this->ternaryMergeTargets($branchCfg) as $mergeCfg) {
            if (!$this->ternaryMergeVarSlots->contains($mergeCfg)) {
                continue;
            }
            /** @var SplObjectStorage<CfgVariable, int> $map */
            $map = $this->ternaryMergeVarSlots[$mergeCfg];
            foreach ($map as $root) {
                if ($this->mergeCfgBlockUsesLogicalShortCircuit($mergeCfg)) {
                    $rootName = Block::resolveVariableName($root);
                    if (null !== $rootName && '' !== $rootName) {
                        continue;
                    }
                }
                $compiled->prebindCfgVarRoot($root, $map[$root]);
            }
        }
    }

    /** When merge block is already lowered, ?: branch assigns must use its ECHO slot (#3790). */
    private function branchMergeAssignSlot(Block $branch, Op\Expr\Assign $assign): ?int
    {
        if ($this->compilingSwitchJumpIfChain) {
            return null;
        }
        if (null === $branch->orig) {
            return null;
        }
        if ($this->isPropertyWriteAssign($assign, $branch)) {
            return null;
        }
        if ($this->isArrayDimWriteAssign($assign, $branch)) {
            return null;
        }
        // Named CV assigns keep their own slots — never rebind to ?: / try-merge phi temps.
        // #17158 covered re-assigns that already had a named-assign dest; first assigns inside
        // try/catch (e.g. `$rhs = 123` before `$o instanceof $rhs`) were still classified as
        // merge-branch phi seeds and stole an outer local's slot (#26490, re-#4339).
        if (null !== Block::resolveVariableName($assign->var)) {
            return null;
        }
        $mergeCfg = $this->branchJumpMergeTarget($branch->orig);
        if (null !== $mergeCfg && $this->mergeCfgBlockUsesLogicalShortCircuit($mergeCfg)) {
            $tail = $this->branchTailExprBeforeJump($branch->orig);
            if (
                $tail === $assign
                && $assign->expr instanceof Operand\Literal
            ) {
                $phi = $this->logicalShortCircuitPhiMergeSlot($branch);
                if (null !== $phi) {
                    return $phi;
                }
            }
        }
        if (!$this->isMergeBranchAssign($branch, $assign)) {
            return null;
        }
        $mergeCfg = $this->branchJumpMergeTarget($branch->orig);
        if (null !== $mergeCfg && $this->mergeCfgBlockUsesLogicalShortCircuit($mergeCfg)) {
            $seeded = $this->seedLogicalShortCircuitPhiSlot($branch->orig, $branch, $assign->var);
            if (null !== $seeded) {
                return $seeded;
            }
        }
        if (null !== $mergeCfg) {
            $recordedPhi = $this->ternaryMergePhiRhsSlot($mergeCfg);
            if (null !== $recordedPhi) {
                return $recordedPhi;
            }
        }
        if (null !== $mergeCfg && $this->isForeachIteratorHeaderCfgBlock($mergeCfg)) {
            return null;
        }
        if (null !== $mergeCfg && $this->seen->contains($mergeCfg)) {
            // Echo/return ?: phi temporaries must still target the merge ECHO/RETURN slot (#3787, #4280, #5506).
            if ($assign->var instanceof Temporary && null === $this->mergeReturnSlot($this->seen[$mergeCfg])) {
                $phiSlot = $this->mergePhiResultSlot($this->seen[$mergeCfg]);
                if (null !== $phiSlot) {
                    return $phiSlot;
                }
            }
        }
        if (null === Block::cfgVarRoot($assign->var) && !$assign->var instanceof Temporary) {
            return null;
        }
        if (null !== $mergeCfg) {
            if ($this->seen->contains($mergeCfg)) {
                $phiSlot = $this->mergePhiResultSlot($this->seen[$mergeCfg]);
                if (null !== $phiSlot) {
                    return $phiSlot;
                }
            }
            $siblingSlot = $this->siblingMergeBranchAssignDestSlot($mergeCfg, $branch->orig);
            if (null !== $siblingSlot) {
                return $siblingSlot;
            }
        }
        foreach ($this->ternaryMergeTargets($branch->orig) as $mergeCfg) {
            if ($this->seen->contains($mergeCfg)) {
                $phiSlot = $this->mergePhiResultSlot($this->seen[$mergeCfg]);
                if (null !== $phiSlot) {
                    return $phiSlot;
                }
            }
            if ($this->ternaryMergeVarSlots->contains($mergeCfg)) {
                /** @var SplObjectStorage<CfgVariable, int> $map */
                $map = $this->ternaryMergeVarSlots[$mergeCfg];
                foreach ($map as $root) {
                    return $map[$root];
                }
            }
        }

        return null;
    }

    private function siblingMergeBranchAssignDestSlot(CfgBlock $mergeCfg, CfgBlock $currentBranch): ?int
    {
        foreach ($mergeCfg->parents as $parentCfg) {
            if ($parentCfg === $currentBranch || !$this->seen->contains($parentCfg)) {
                continue;
            }
            $phi = $this->logicalShortCircuitTailPhiSlot($this->seen[$parentCfg]);
            if (null !== $phi) {
                return $phi;
            }
        }

        return null;
    }

    private function isMergeBranchAssign(Block $branch, Op\Expr\Assign $assign): bool
    {
        if (null === $branch->orig) {
            return false;
        }
        $expectedVar = $this->mergeBranchAssignVarOperand($branch->orig);
        if (null === $expectedVar) {
            return false;
        }

        return $this->operandsReferToSameVariable($expectedVar, $assign->var);
    }

    private function mergeEchoSlot(Block $merge): ?int
    {
        foreach ($merge->opCodes as $op) {
            if (OpCode::TYPE_ECHO === $op->type) {
                return $op->arg1;
            }
        }

        return null;
    }

    /** `$dest = $phi` merge block carries the phi slot on the assign RHS (#9159). */
    private function mergeAssignPhiRhsSlot(Block $merge): ?int
    {
        foreach ($merge->opCodes as $op) {
            if (OpCode::TYPE_ASSIGN !== $op->type || null === $op->arg3) {
                continue;
            }
            // Consecutive match() in one merge block seeds later results with literal `''`;
            // constant RHS is not a phi temp slot (#9856).
            if (isset($merge->constants[$op->arg3])) {
                continue;
            }

            return (int) $op->arg3;
        }

        return null;
    }

    private function recordTernaryMergePhiRhsSlot(CfgBlock $mergeCfg, Block $compiled): void
    {
        if ($this->ternaryMergePhiRhsSlots->contains($mergeCfg)) {
            return;
        }
        $phi = $this->logicalShortCircuitTailPhiSlot($compiled);
        if (null !== $phi) {
            $this->ternaryMergePhiRhsSlots[$mergeCfg] = $phi;
        }
    }

    private function ternaryMergePhiRhsSlot(CfgBlock $mergeCfg): ?int
    {
        if (!$this->ternaryMergePhiRhsSlots->contains($mergeCfg)) {
            return null;
        }

        return $this->ternaryMergePhiRhsSlots[$mergeCfg];
    }

    /** `return $a ? $b : $c` merge block carries the phi slot on RETURN (#4280). */
    private function mergeReturnSlot(Block $merge): ?int
    {
        foreach ($merge->opCodes as $op) {
            if (OpCode::TYPE_RETURN === $op->type) {
                return $op->arg1;
            }
        }

        return null;
    }

    /** `throw $a ? $b : $c` merge block carries the phi slot on TYPE_THROW (#7037). */
    private function mergeThrowSlot(Block $merge): ?int
    {
        foreach ($merge->opCodes as $op) {
            if (OpCode::TYPE_THROW === $op->type) {
                return $op->arg1;
            }
        }

        return null;
    }

    private function mergePhiResultSlot(Block $merge): ?int
    {
        return $this->mergeEchoSlot($merge)
            ?? $this->mergeAssignPhiRhsSlot($merge)
            ?? $this->mergeReturnSlot($merge)
            ?? $this->mergeThrowSlot($merge);
    }

    /** ?: branch throw `new` must not reuse merge phi / echo slot (#3802). */
    private function mergeEchoSlotForBranch(Block $branch): ?int
    {
        if (null === $branch->orig) {
            return null;
        }
        foreach ($this->ternaryMergeTargets($branch->orig) as $mergeCfg) {
            if ($this->seen->contains($mergeCfg)) {
                $slot = $this->mergePhiResultSlot($this->seen[$mergeCfg]);
                if (null !== $slot) {
                    return $slot;
                }
            }
            if ($this->ternaryMergeVarSlots->contains($mergeCfg)) {
                /** @var SplObjectStorage<CfgVariable, int> $map */
                $map = $this->ternaryMergeVarSlots[$mergeCfg];
                foreach ($map as $root) {
                    return $map[$root];
                }
            }
        }

        return null;
    }

    protected function compileBlock(Block $block) {
        if (null !== $block->orig && $this->isErrorSuppressEndBlock($block->orig)) {
            $block->addOpCode(new OpCode(OpCode::TYPE_END_SILENCE));
        }
        $this->compileOps($block->orig->children, $block);
        // Do not auto-LEAVE at CFG block edges: file-level declare(ticks=N) and braced
        // bodies that span loops/jumps must keep the interval across successor blocks.
        // Braced scopes emit LeaveTickInterval explicitly from php-cfg (#22840, #23486).
    }

    private function emitTicksBeforeStatementIfNeeded(Op $op, Block $block, array $ops, int $index): void
    {
        if ($this->activeTickInterval <= 0) {
            return;
        }
        if ($op instanceof Op\Terminal\SetTickInterval || $op instanceof Op\Terminal\LeaveTickInterval) {
            return;
        }
        // for ($i=0; $i<n; $i++) init/increment exprs are not Zend statement boundaries (#23486, #25621).
        if ($op->hasAttribute('for_loop_increment') && $op->getAttribute('for_loop_increment')) {
            return;
        }
        if ($op->hasAttribute('for_loop_init') && $op->getAttribute('for_loop_init')) {
            return;
        }
        if (
            $op instanceof Op\Stmt\Function_
            || $op instanceof Op\Stmt\Class_
            || $op instanceof Op\Stmt\Interface_
            || $op instanceof Op\Stmt\Trait_
            || $op instanceof Op\Stmt\Enum_
            || $op instanceof Op\Stmt\Jump
            || $op instanceof Op\Stmt\JumpIf
            || $op instanceof Op\Terminal\Const_
            || $op instanceof Op\Terminal\Return_
        ) {
            return;
        }
        // php-cfg lowers `$x += 1` to BinaryOp + Assign — only the Assign is tickable (#22840).
        if ($op instanceof Op\Expr\BinaryOp) {
            return;
        }
        // echo "a$b" → ConcatList + Echo. Zend ticks at the statement start (before
        // interpolation). Tick before ConcatList; skip the following Echo (#23486).
        if ($op instanceof Op\Expr\ConcatList) {
            $next = $ops[$index + 1] ?? null;
            if ($next instanceof Op\Terminal && 'Terminal_Echo' === $next->getType()) {
                $block->addOpCode(new OpCode(OpCode::TYPE_TICKS));
            }

            return;
        }
        if ($op instanceof Op\Expr\Closure) {
            return;
        }
        // php-src places ZEND_TICKS before each ECHO opcode. `echo $a, $b` and
        // `echo "a"; echo "b"` both lower to consecutive Terminal_Echo — tick each
        // fragment. Skip only the Echo that follows ConcatList (already ticked) (#30010).
        if ($op instanceof Op\Terminal && 'Terminal_Echo' === $op->getType()) {
            $prev = $ops[$index - 1] ?? null;
            if ($prev instanceof Op\Expr\ConcatList) {
                return;
            }
        }
        // Arg evaluation feeding a following Echo (FuncCall/BinaryOp/…) is not a
        // separate Zend statement boundary — ZEND_TICKS sits on the ECHO (#30010).
        if ($this->isEchoArgEvaluationPrelude($op, $ops, $index)) {
            return;
        }
        $block->addOpCode(new OpCode(OpCode::TYPE_TICKS));
    }

    /**
     * True when $op only evaluates an argument of a following Terminal_Echo.
     *
     * Mirrors php-src: ZEND_TICKS is emitted with each ECHO, not with the arg-setup
     * ops php-cfg materializes ahead of it (`echo strtoupper("a"), "b"` / `echo foo(bar())`).
     *
     * Call-arg site clones often break Temporary identity (#8560), so this uses a
     * same-startLine window: producers sharing the echo statement's line are preludes,
     * except `foo(); echo …` where the call result is unused by the following Echo.
     *
     * @param Op[] $ops
     */
    private function isEchoArgEvaluationPrelude(Op $op, array $ops, int $index): bool
    {
        if (!($op instanceof Op\Expr) || !property_exists($op, 'result') || null === $op->result) {
            return false;
        }
        // Statement-level assign (`$a = 1; echo $a`) must tick; only `echo ($a = …)`
        // feeds the Echo expr directly.
        if (
            $op instanceof Op\Expr\Assign
            || $op instanceof Op\Expr\AssignRef
            || $op instanceof Op\Expr\AssignOp
        ) {
            $next = $ops[$index + 1] ?? null;
            if (!($next instanceof Op\Terminal) || 'Terminal_Echo' !== $next->getType()) {
                return false;
            }

            return $this->operandsChainEqual($next->expr, $op->result)
                || $this->operandsReferToSameVariable($next->expr, $op->result);
        }
        if (!$this->isInlineExprCallArgProducer($op)) {
            return false;
        }

        $line = $op->hasAttribute('startLine')
            ? (int) $op->getAttribute('startLine')
            : $op->getLine();
        if ($line <= 0) {
            return false;
        }

        $produced = $op->result;
        $sawEcho = false;
        $resultFeedsEcho = false;
        $immediate = $ops[$index + 1] ?? null;
        $n = \count($ops);
        for ($j = $index + 1; $j < $n; ++$j) {
            $next = $ops[$j];
            $nextLine = $next->hasAttribute('startLine')
                ? (int) $next->getAttribute('startLine')
                : $next->getLine();
            if ($nextLine !== $line) {
                break;
            }
            if ($next instanceof Op\Terminal && 'Terminal_Echo' === $next->getType()) {
                $sawEcho = true;
                if (
                    $this->operandsChainEqual($next->expr, $produced)
                    || $this->operandsReferToSameVariable($next->expr, $produced)
                ) {
                    $resultFeedsEcho = true;
                }
                continue;
            }
            if (
                !($next instanceof Op\Expr)
                || !property_exists($next, 'result')
                || null === $next->result
                || !$this->isInlineExprCallArgProducer($next)
            ) {
                break;
            }
        }
        if (!$sawEcho) {
            return false;
        }
        if ($resultFeedsEcho) {
            return true;
        }
        // Nested call arg: `echo foo(bar())` — bar sits before foo on the echo line.
        if (
            $immediate instanceof Op\Expr
            && $this->isInlineExprCallArgProducer($immediate)
            && !($immediate instanceof Op\Expr\Assign)
            && !($immediate instanceof Op\Expr\AssignRef)
            && !($immediate instanceof Op\Expr\AssignOp)
        ) {
            return true;
        }
        // `foo(); echo "a"` on one line — call result unused by Echo; still tickable.
        if ($immediate instanceof Op\Terminal && 'Terminal_Echo' === $immediate->getType()) {
            return false;
        }

        return true;
    }

    protected function compileOps(array $ops, Block $block): void {
        // Enum cases before global const / hoisted class bodies so E::A folds in
        // class const initializers when enum appears later in source (#15737, #5738).
        $this->prescanCompileTimeEnumCases($ops);
        // Register file-level `const` / literal define() before class bodies and
        // FUNCDEF defaults so zend_compile_default_value can fold ConstFetch (#6542).
        $this->prescanCompileTimeGlobalConsts($ops, $block);
        $this->rejectListDestructDefaultValueSlotsInOps($ops);

        // Hoist class-like definitions before functions so JIT/AOT see member
        // constants when compiling FUNCDEF bodies (issue #2215, MiniWebApp Router::CONST).
        // Interfaces before classes so same-file `class C implements I` / later `interface I`
        // resolves at DECLARE_CLASS like Zend early-binding (#25624).
        // Enums stay in source order so enum_exists() before declaration matches Zend (#5013).
        // Serializable / forbidden-implements / trait-use stay in source order for DECLARE
        // side effects (#18781, #25109, #25912). Subclasses of those classes stay in source
        // order too — hoisting them ahead leaves deferred parent inheritance pending across
        // preceding runtime opcodes, which finalize as Class "Parent" not found (#29552, #29566).
        $sourceOrderClassLcs = $this->sourceOrderClassRegistrationLcs($ops);
        foreach ($ops as $child) {
            if ($child instanceof Op\Stmt\Interface_) {
                $block->addOpCode($this->compileInterface($child, $block));
            }
        }
        foreach ($ops as $child) {
            if ($child instanceof Op\Stmt\Trait_) {
                $block->addOpCode($this->compileTrait($child, $block));
            }
        }
        foreach ($ops as $child) {
            if (!$child instanceof Op\Stmt\Class_) {
                continue;
            }
            if ($this->classIsSourceOrderRegistration($child, $sourceOrderClassLcs)) {
                continue;
            }
            $block->addOpCode($this->compileClassLike($child, $block));
        }
        foreach ($ops as $child) {
            switch (get_class($child)) {
                case Op\Stmt\Function_::class:
                    // Already emitted at {main} entry for Zend early-binding (#24807).
                    if ($this->earlyBoundFunctionOps->contains($child)) {
                        break;
                    }
                    $block->addOpCode($this->compileFunction($child, $block));
                    break;
                case Op\Terminal\Const_::class:
                    $block->addOpCode($this->compileGlobalConst($child, $block));
                    break;
            }
        }

        // php-cfg may linearize nullsafe-call arguments into eager temporaries:
        //
        //   $t = sideEffect();
        //   $c?->f($t);
        //
        // For PHP semantics, those argument temporaries must only be evaluated on the
        // non-null receiver branch (Zend `?->` short-circuit). We detect a small
        // producer slice that is used exclusively to feed a nullsafe method-call
        // argument and compile that slice into the nullsafe fetch block instead (#4394).
        $deferredNullsafePreludeOps = new SplObjectStorage();
        $deferredOpIndexes = [];
        $opCount = count($ops);
        for ($i = 0; $i < $opCount; ++$i) {
            $child = $ops[$i];
            if (!$child instanceof Op\Expr\NullsafeMethodCall) {
                continue;
            }

            $needed = [];
            foreach ($child->args as $arg) {
                if ($arg instanceof \PHPCfg\Operand\Temporary) {
                    $needed[spl_object_id($arg)] = $arg;
                }
            }
            if (empty($needed)) {
                continue;
            }

            $slice = [];
            for ($j = $i - 1; $j >= 0 && !empty($needed); --$j) {
                $candidate = $ops[$j] ?? null;
                if (!$candidate instanceof Op\Expr) {
                    break;
                }
                if ($candidate instanceof Op\Expr\Assign) {
                    break;
                }
                if (!property_exists($candidate, 'result') || !$candidate->result instanceof \PHPCfg\Operand\Temporary) {
                    break;
                }
                $resultVar = $candidate->result;
                // php-cfg parseArg() clones producer temps for call sites (#8560); match the
                // clone via shared ops, not only identical operand objects (#22660).
                $matchedArgId = null;
                if (isset($needed[spl_object_id($resultVar)])) {
                    $matchedArgId = spl_object_id($resultVar);
                } else {
                    foreach ($needed as $argId => $argTemp) {
                        if ($this->nullsafeCallArgTempFedByProducer($argTemp, $candidate)) {
                            $matchedArgId = $argId;
                            break;
                        }
                    }
                }
                if (null === $matchedArgId) {
                    continue;
                }

                $slice[] = $candidate;
                unset($needed[$matchedArgId]);
                $deferredOpIndexes[$j] = true;

                foreach ($this->nullsafePreludeOperandVars($candidate) as $dep) {
                    if ($dep instanceof \PHPCfg\Operand\Temporary) {
                        $needed[spl_object_id($dep)] = $dep;
                    }
                }
            }

            if (!empty($slice)) {
                $deferredNullsafePreludeOps[$child] = array_reverse($slice);
            } elseif ($i > 0) {
                // php-cfg may use a distinct arg temporary vs the immediately preceding
                // inline producer (IIFE FuncCall) — defer that prelude slice (#17186, #4394).
                $head = $ops[$i - 1] ?? null;
                if (
                    $head instanceof Op\Expr
                    && !$head instanceof Op\Expr\Assign
                    && property_exists($head, 'result')
                    && $this->isNullsafeMethodCallArgPreludeProducer($head)
                ) {
                    $adjacentSlice = [$head];
                    $deferredOpIndexes[$i - 1] = true;
                    $pendingDeps = [];
                    foreach ($this->nullsafePreludeOperandVars($head) as $dep) {
                        if ($dep instanceof \PHPCfg\Operand\Temporary) {
                            $pendingDeps[spl_object_id($dep)] = $dep;
                        }
                    }
                    for ($j = $i - 2; $j >= 0 && [] !== $pendingDeps; --$j) {
                        $candidate = $ops[$j] ?? null;
                        if (
                            !$candidate instanceof Op\Expr
                            || $candidate instanceof Op\Expr\Assign
                            || !property_exists($candidate, 'result')
                            || !$candidate->result instanceof \PHPCfg\Operand\Temporary
                        ) {
                            break;
                        }
                        $resultVar = $candidate->result;
                        $matchedDep = null;
                        foreach ($pendingDeps as $depId => $dep) {
                            if ($resultVar === $dep || $this->operandsReferToSameVariable($resultVar, $dep)) {
                                $matchedDep = $depId;
                                break;
                            }
                        }
                        if (null === $matchedDep) {
                            break;
                        }
                        unset($pendingDeps[$matchedDep]);
                        array_unshift($adjacentSlice, $candidate);
                        $deferredOpIndexes[$j] = true;
                        foreach ($this->nullsafePreludeOperandVars($candidate) as $dep) {
                            if ($dep instanceof \PHPCfg\Operand\Temporary) {
                                $pendingDeps[spl_object_id($dep)] = $dep;
                            }
                        }
                    }
                    if ([] !== $adjacentSlice) {
                        $deferredNullsafePreludeOps[$child] = $adjacentSlice;
                    }
                }
            }
        }
        for ($i = 0; $i < $opCount; ++$i) {
            if (isset($deferredOpIndexes[$i])) {
                continue;
            }
            $child = $ops[$i];
            if ($child instanceof Op\Expr\ArrayDimFetch) {
                $this->rejectArrayEmptyOffsetRead($child, $block);
            }
            $this->debugWriteLastPhase('Compiler::compileOps op', $block, $child);
            switch (get_class($child)) {
                case Op\Stmt\Function_::class:
                case Op\Terminal\Const_::class:
                case Op\Stmt\Interface_::class:
                case Op\Stmt\Trait_::class:
                    break;
                case Op\Stmt\Class_::class:
                    if ($this->classIsSourceOrderRegistration($child, $sourceOrderClassLcs)) {
                        $block->addOpCode($this->compileClassLike($child, $block));
                    }
                    break;
                case Op\Stmt\Enum_::class:
                    $block->addOpCode($this->compileEnum($child, $block));
                    break;
                default:
                    if ($child instanceof Op\Expr\Isset_ && count($child->vars) > 1) {
                        $block = $this->compileIssetMulti($child, $block);
                    } elseif (
                        $child instanceof Op\Expr\Isset_
                        && 1 === count($child->vars)
                        && [] !== ($nullsafeChain = $this->collectNullsafePropertyFetchChain($child->vars[0], $block))
                    ) {
                        $block = $this->compileIssetNullsafePropertyFetchChain($nullsafeChain, $child, $block);
                    } elseif (
                        $child instanceof Op\Expr\Empty_
                        && [] !== ($nullsafeChain = $this->collectNullsafePropertyFetchChainForEmpty($child, $block))
                    ) {
                        $block = $this->compileEmptyNullsafePropertyFetchChain($nullsafeChain, $child, $block);
                    } elseif ($child instanceof Op\Expr\BinaryOp\Coalesce) {
                        if ($this->isCoalesceChainInnerStmt($child, $ops, $i)) {
                            break;
                        }
                        if ($this->isCoalesceLoweredByFollowingEchoConcat($ops, $i)) {
                            break;
                        }
                        // php-cfg emits Coalesce before Throw when source is `throw … ?? …`; lower once inside compileThrowExpression (#15315).
                        if ($this->isCoalesceLoweredByFollowingThrow($ops, $i)) {
                            break;
                        }
                        $resultOverride = null;
                        if (
                            $i + 1 < $opCount
                            && $ops[$i + 1] instanceof Op\Expr\Assign
                            && $this->isCoalesceAssignTail($ops[$i + 1], $child)
                        ) {
                            /** @var Op\Expr\Assign $tailAssign */
                            $tailAssign = $ops[$i + 1];
                            $resultOverride = $tailAssign->var;
                        }
                        $block = null !== $resultOverride
                            ? $this->compileCoalesceForAssign($child, $block, $resultOverride)
                            : $this->compileCoalesce($child, $block);
                        if (null !== $resultOverride) {
                            ++$i;
                        }
                    } elseif (
                        $child instanceof Op\Expr\NullsafePropertyFetch
                        && (
                            $this->shouldSkipNullsafePropertyFetchForIssetOrEmpty($child, $ops, $i, $block)
                            || $this->shouldSkipNullsafePropertyFetchForCoalesce($child, $ops, $i, $block)
                        )
                    ) {
                        // Lowered by compileIssetNullsafePropertyFetchChain / compileEmptyNullsafePropertyFetchChain (#4980)
                        // or compileCoalesce nullsafe chain eval (#13747).
                        break;
                    } elseif ($child instanceof Op\Expr\NullsafePropertyFetch) {
                        if ($this->isNullsafePropertyFetchInWriteContext($ops, $i)) {
                            $this->throwCompileError("Can't use nullsafe operator in write context");
                        }
                        // Zend: &$a?->x / &$a?->x->y — AssignRef RHS, not write-context LHS (#26638).
                        if ($this->isNullsafeOperandUsedAsAssignRefRhs($ops, $i + 1, $child->result)) {
                            $this->throwCompileError('Cannot take reference of a nullsafe chain');
                        }
                        $block = $this->compileNullsafePropertyFetch($child, $block);
                        $this->syncNullsafePropertyFetchResultToFollowingFuncCallArg($child, $block);
                    } elseif (
                        $child instanceof Op\Expr\NullsafeMethodCall
                        && $this->shouldSkipNullsafeMethodCallForCoalesce($child, $ops, $i, $block)
                    ) {
                        // Lowered inside compileCoalesce nullsafe method eval (#19591).
                        break;
                    } elseif ($child instanceof Op\Expr\NullsafeMethodCall) {
                        // Zend: &$obj?->m() — AssignRef of nullsafe method result (#26638).
                        if ($this->isNullsafeOperandUsedAsAssignRefRhs($ops, $i + 1, $child->result)) {
                            $this->throwCompileError('Cannot take reference of a nullsafe chain');
                        }
                        $block = $this->compileNullsafeMethodCall(
                            $child,
                            $block,
                            $deferredNullsafePreludeOps->contains($child) ? $deferredNullsafePreludeOps[$child] : []
                        );
                    } elseif ($this->isNullsafeChainArrayDimFetch($ops, $i)) {
                        /** @var Op\Expr\ArrayDimFetch $child */
                        $block = $this->compileNullsafeArrayDimFetch($child, $block);
                    } elseif (
                        $child instanceof Op\Expr\PropertyFetch
                        && $i + 1 < $opCount
                        && ($ops[$i + 1] instanceof Op\Expr\FuncCall || $ops[$i + 1] instanceof Op\Expr\NsFuncCall)
                        && $this->isPropertyFetchOnlyCoalesceFuncCallArg($child, $ops[$i + 1], $block)
                    ) {
                        break;
                    } elseif (
                        $child instanceof Op\Expr\PropertyFetch
                        && $this->isPropertyFetchNullsafeReceiver($child, $ops, $i)
                    ) {
                        // Lowered inside compileNullsafePropertyFetch / coalesce chain eval (#16637).
                        break;
                    } elseif (
                        $child instanceof Op\Expr\PropertyFetch
                        && null !== ($coalesceMatch = $this->findCoalesceUsingPropertyFetchLeft($child, $ops, $i))
                    ) {
                        /** @var Op\Expr\BinaryOp\Coalesce $coalesce */
                        [$coalesce, $coalesceIndex] = $coalesceMatch;
                        $resultOverride = null;
                        if (
                            $coalesceIndex + 1 < $opCount
                            && $ops[$coalesceIndex + 1] instanceof Op\Expr\Assign
                            && $this->isCoalesceAssignTail($ops[$coalesceIndex + 1], $coalesce)
                            && $this->operandsChainEqual($ops[$coalesceIndex + 1]->var, $child->result)
                        ) {
                            /** @var Op\Expr\Assign $tailAssign */
                            $tailAssign = $ops[$coalesceIndex + 1];
                            $resultOverride = $tailAssign->var;
                        }
                        if ($this->isCoalesceLoweredByFollowingEchoConcat($ops, $coalesceIndex)) {
                            $i = $coalesceIndex;
                            break;
                        }
                        $block = null !== $resultOverride
                            ? $this->compileCoalesceForAssign($coalesce, $block, $resultOverride)
                            : $this->compileCoalesce($coalesce, $block);
                        $i = $coalesceIndex;
                        if (null !== $resultOverride) {
                            ++$i;
                        }
                        break;
                    } elseif (
                        $child instanceof Op\Expr\ArrayDimFetch
                        && $i + 1 < $opCount
                        && ($ops[$i + 1] instanceof Op\Expr\FuncCall || $ops[$i + 1] instanceof Op\Expr\NsFuncCall)
                        && $this->isArrayDimFetchOnlyCoalesceFuncCallArg($child, $ops[$i + 1], $block)
                    ) {
                        break;
                    } elseif (
                        $child instanceof Op\Expr\ArrayDimFetch
                        && $this->isArrayDimFetchSkippedForCoalesce($child, $ops, $i, $block)
                    ) {
                        // Nested `$a['x']['y'] ??…` / `??=` — intermediates lowered inside compileCoalesce (#28954).
                        break;
                    } elseif (
                        $child instanceof Op\Expr\ArrayDimFetch
                        && null !== ($coalesceMatch = $this->findCoalesceUsingArrayDimFetchLeft($child, $ops, $i))
                    ) {
                        /** @var Op\Expr\BinaryOp\Coalesce $coalesce */
                        [$coalesce, $coalesceIndex] = $coalesceMatch;
                        $resultOverride = null;
                        if (
                            $coalesceIndex + 1 < $opCount
                            && $ops[$coalesceIndex + 1] instanceof Op\Expr\Assign
                            && $this->isRedundantCoalesceTailAssign(
                                $ops[$coalesceIndex + 1],
                                $child,
                                $coalesce
                            )
                        ) {
                            /** @var Op\Expr\Assign $tailAssign */
                            $tailAssign = $ops[$coalesceIndex + 1];
                            $resultOverride = $tailAssign->var;
                        }
                        if ($this->isCoalesceLoweredByFollowingEchoConcat($ops, $coalesceIndex)) {
                            $i = $coalesceIndex;
                            break;
                        }
                        $block = $this->compileCoalesceForAssign($coalesce, $block, $resultOverride);
                        $i = $coalesceIndex;
                        if (null !== $resultOverride) {
                            ++$i;
                        }
                        break;
                    } elseif (
                        $child instanceof Op\Expr\ArrayDimFetch
                        && $this->isArrayDimFetchSkippedForIssetEmptyOrUnset($child, $ops, $i, $block)
                    ) {
                        // Lowered by compileIsset / Empty_ / Unset — including nested dim chains (#99, #21991).
                        break;
                    } elseif (
                        $child instanceof Op\Expr\PropertyFetch
                        && $i + 1 < $opCount
                        && $this->isPropertyFetchOnlyIssetVar($child, $ops[$i + 1])
                    ) {
                        // Lowered by compileIsset via TYPE_ISSET(container, name) (#3298).
                        break;
                    } elseif (
                        $child instanceof Op\Expr\StaticPropertyFetch
                        && $i + 1 < $opCount
                        && $this->isStaticPropertyFetchOnlyIssetVar($child, $ops[$i + 1])
                    ) {
                        // Lowered by compileIsset via TYPE_ISSET(class, name) (#15112).
                        break;
                    } elseif ($child instanceof Op\Terminal\StaticVar) {
                        [$staticOps, $nextBlock] = $this->compileFunctionStaticVar($child, $block);
                        foreach ($staticOps as $staticOp) {
                            $block->addOpCode($staticOp);
                        }
                        $block = $nextBlock;
                    } elseif (
                        $child instanceof Op\Expr\PropertyFetch
                        && $i + 1 < $opCount
                        && $this->isPropertyFetchOnlyUnsetVar($child, $ops[$i + 1])
                    ) {
                        break;
                    } elseif (
                        $child instanceof Op\Expr\PropertyFetch
                        && $i + 1 < $opCount
                        && $this->isPropertyFetchOnlyAssignVar($child, $ops[$i + 1])
                    ) {
                        // Lowered by compileExpr Assign via TYPE_PROPERTY_FETCH + TYPE_ASSIGN (#6834).
                        break;
                    } elseif (
                        $child instanceof Op\Expr\PropertyFetch
                        && $i + 1 < $opCount
                        && $this->isPropertyFetchLoweredByFollowingArrayLiteralByRefElement(
                            $child,
                            $ops[$i + 1]
                        )
                    ) {
                        // Lowered by compileArrayLiteral PROPERTY_FETCH_WRITE + ASSIGN_REF (#6426, #17353).
                        break;
                    } elseif ($this->isLoweredByFollowingCoalesce($child, $ops, $i)) {
                        break;
                    } elseif ($this->isLoweredByFollowingThrow($child, $ops, $i)) {
                        break;
                    } elseif (
                        $child instanceof Op\Expr\Throw_
                        && $this->throwResultFeedsFollowingIsset($child, $ops, $i)
                    ) {
                        // php-cfg emits Throw_ before Isset_ for isset(throw …); do not run the throw (#29086).
                        $this->throwCompileError(self::ISSET_EXPRESSION_COMPILE_ERROR);
                    } elseif ($this->isUnreachableAfterThrow($child, $ops, $i)) {
                        break;
                    } elseif ($this->isUnreachableAfterNeverCall($child, $ops, $i)) {
                        break;
                    } elseif (
                        $child instanceof Op\Expr\ClassConstFetch
                        && $this->isHoistedEnumCaseFetchOnlyForCaseClassPseudoConst($child, $ops, $i, $block)
                    ) {
                        // Lowered via following `Case::class` fold / call-arg compile-time value (#9426, #9518).
                        break;
                    } elseif ($this->isDeferredSiblingInlineCallArgProducer($child, $ops, $i)) {
                        // Hoisted sibling call-arg producers compile at the consumer via
                        // resolveSiblingInlineCallArgProducerSlot (#9463, #10981, #12421, #13788).
                        break;
                    } elseif ($this->isFuncCallLoweredByFollowingEchoConcat($child, $ops, $i)) {
                        break;
                    } elseif (
                        $child instanceof Op\Expr\ConstFetch
                        && $this->isDeferredLeadingConstFetchBeforeSiblingFuncCallConsumer($child, $ops, $i)
                    ) {
                        // explode(PATH_SEPARATOR, get_include_path()) — ConstFetch + sibling FuncCall (#15833).
                        break;
                    } elseif (
                        ($child instanceof Op\Expr\ConstFetch || $child instanceof Op\Expr\ClassConstFetch)
                        && $this->isConstFetchLoweredByFollowingEchoConcatFuncCall($ops, $i)
                    ) {
                        // echo var_export($arr['k'] ?? $d, true) . "\n" — hoisted true before deferred call (#18315).
                        break;
                    } elseif (
                        ($child instanceof Op\Expr\ConstFetch || $child instanceof Op\Expr\ClassConstFetch)
                        && $i + 1 < $opCount
                        && ($ops[$i + 1] instanceof Op\Expr\FuncCall || $ops[$i + 1] instanceof Op\Expr\NsFuncCall)
                        && $this->isDeferredHoistedConstFetchCallArgPrelude($child, $ops[$i + 1], $ops, $i)
                    ) {
                        // stream_supports($fp, STREAM_SUPPORT_READ) — FUNCCALL_INIT before const (#17697).
                        break;
                    } elseif ($this->isDeferredTrailingComparatorFirstClassCallable($child, $ops, $i)) {
                        // strcmp(...) trailing FCC with deferred sibling array_keys — emit at consumer (#15475).
                        break;
                    } elseif ($this->isForeachLoopVarAssignRefFusion($ops, $i)) {
                        /** @var Op\Iterator\Value $iter */
                        $iter = $ops[$i];
                        /** @var Op\Expr\AssignRef $assign */
                        $assign = $ops[$i + 1];
                        $destSlot = $this->compileOperand($assign->var, $block, false);
                        $this->registerForeachByRefLoopVarBindings($block, $assign, $iter, $destSlot);
                        $block->addOpCode(new OpCode(
                            OpCode::TYPE_ITER_VALUE,
                            $destSlot,
                            $this->compileOperand($iter->var, $block, true),
                            1
                        ));
                        ++$i;
                        break;
                    } elseif ($this->isForeachListDestructRefFusion($ops, $i, $block)) {
                        /** @var Op\Iterator\Value $iter */
                        $iter = $ops[$i];
                        // Live haystack element for by-ref destructuring slots (#16213, Zend FE_FETCH_R).
                        $block->addOpCode(new OpCode(
                            OpCode::TYPE_ITER_VALUE,
                            $this->compileOperand($iter->result, $block, false),
                            $this->compileOperand($iter->var, $block, true),
                            1
                        ));
                        ++$i;
                        [$block, $i] = $this->compileListDestructGroup($ops, $i, $block);
                        break;
                    } elseif (
                        $child instanceof Op\Expr\PropertyFetch
                        && $i + 1 < $opCount
                        && $this->isPropertyFetchOnlyEmptyVar($child, $ops[$i + 1], $block)
                    ) {
                        // Lowered by compileExpr Empty_ via TYPE_EMPTY_OBJECT_PROPERTY (#4912).
                        break;
                    } elseif (
                        $child instanceof Op\Expr\StaticPropertyFetch
                        && $i + 1 < $opCount
                        && $this->isStaticPropertyFetchOnlyEmptyVar($child, $ops[$i + 1], $block)
                    ) {
                        // Lowered by compileExpr Empty_ via TYPE_EMPTY_STATIC_PROPERTY (#15112, #23983).
                        break;
                    } elseif (
                        (
                            $child instanceof Op\Expr\ArrayDimFetch
                            || $this->isListSpreadAssignOp($child)
                        )
                        && $this->isListDestructGroupStart($ops, $i, $block)
                    ) {
                        [$block, $i] = $this->compileListDestructGroup($ops, $i, $block);
                    } else {
                        if ($this->needsCfgSplitBeforeStringDimFetch($child, $block, $ops, $i)) {
                            $block = $this->splitCfgBlockAfterStringKeyedArray($block);
                        }
                        $echoBlock = $this->compileEchoWithEmbeddedCoalesce($child, $block, $ops, $i);
                        if (null !== $echoBlock) {
                            $block = $echoBlock;
                            break;
                        }
                        if (
                            ($ops[$i + 1] ?? null) instanceof Op\Stmt\JumpIf
                            && null !== ($paramOp = $this->nullableParamFromReturnTernaryArms($ops[$i + 1], $block))
                            && (
                                $child instanceof Op\Expr\BinaryOp\NotIdentical
                                || $child instanceof Op\Expr\BinaryOp\Identical
                            )
                        ) {
                            $this->emitImplicitNullableParamCoalesceReturn($paramOp, $block);
                            break;
                        }
                        if (
                            $child instanceof Op\Expr\BinaryOp\Concat
                            && $this->isConcatLoweredByFollowingEcho($child, $ops, $i)
                        ) {
                            break;
                        }
                        $savedAssignRefFlags = $this->assignRefBindRefFlags;
                        if (
                            $child instanceof Op\Expr\AssignRef
                            && $this->isForeachPropertyHookAssignRefPair($ops, $i)
                        ) {
                            $this->assignRefBindRefFlags = OpCode::ASSIGN_REF_FOREACH_PROPERTY_HOOK;
                        }
                        $this->emitTicksBeforeStatementIfNeeded($child, $block, $ops, $i);
                        $this->compileOp($child, $block);
                        $this->assignRefBindRefFlags = $savedAssignRefFlags;
                    }
            }
        }
    }

    /**
     * String-key array writes and immediate dim fetch in one CFG block break AOT (#764, #783).
     * Keyed list destructuring (`["a" => $x] = …`) is excluded (#1234).
     *
     * @param Op[] $ops
     */
    private function needsCfgSplitBeforeStringDimFetch(Op $op, Block $block, array $ops, int $index): bool
    {
        if (!$op instanceof Op\Expr\ArrayDimFetch) {
            return false;
        }
        if (!$op->dim instanceof Literal || !is_string($op->dim->value)) {
            return false;
        }
        if ($this->isKeyedListDestructDimFetch($ops, $index, $block)) {
            return false;
        }
        // Zend materializes inline array literals before dim-fetch; splitting drops dead temps (#16462).
        if (
            null !== $op->var
            && (
                ($ops[$index - 1] ?? null) instanceof Op\Expr\Array_
                && $this->operandsReferToSameVariable($op->var, $ops[$index - 1]->result)
            )
            || null !== $this->unwrapArrayLiteralExpr($op->var)
            || null !== $this->findArrayExprForResult($op->var, $block)
        ) {
            return false;
        }
        foreach ($block->opCodes as $prev) {
            if (OpCode::TYPE_INIT_ARRAY === $prev->type && null !== $prev->arg3) {
                return true;
            }
            if (OpCode::TYPE_INCLUDE === $prev->type && null !== $prev->arg2) {
                return true;
            }
        }

        return false;
    }

    /**
     * foreach ($iterable as &$loopVar) — fuse Iterator\\Value + AssignRef into one ITER_VALUE (#4431).
     *
     * @param Op[] $ops
     */
    private function isForeachLoopVarAssignRefFusion(array $ops, int $index): bool
    {
        if (!isset($ops[$index + 1])) {
            return false;
        }
        if (!$ops[$index] instanceof Op\Iterator\Value) {
            return false;
        }
        if (!$ops[$index + 1] instanceof Op\Expr\AssignRef) {
            return false;
        }
        /** @var Op\Iterator\Value $iter */
        $iter = $ops[$index];
        /** @var Op\Expr\AssignRef $assign */
        $assign = $ops[$index + 1];

        return $iter->byRef
            && $iter->result === $assign->expr
            && !$this->operandIsPropertyWriteTarget($assign->var);
    }

    /**
     * foreach ($iterable as &$loopVar) fusion — CV slot must feed inline call-arg producers (#25302).
     */
    private function registerForeachByRefLoopVarBindings(
        Block $block,
        Op\Expr\AssignRef $assign,
        Op\Iterator\Value $iter,
        int $destSlot
    ): void {
        $varRoot = Block::cfgVarRoot($assign->var);
        if (null !== $varRoot) {
            $block->registerNamedAssignDest($varRoot, $destSlot);
        }
        if ($iter->result !== $assign->var && [] !== $iter->result->usages) {
            $block->registerAssignResultLvalue(
                $this->compileOperand($iter->result, $block, false),
                $destSlot
            );
        }
        if ($assign->result !== $assign->var && [] !== $assign->result->usages) {
            $block->registerAssignResultLvalue(
                $this->compileOperand($assign->result, $block, false),
                $destSlot
            );
        }
    }

    /**
     * foreach ($iterable as list(&$v)) / [$x, &$y] — by-ref slots need live iteration value (#16213).
     *
     * @param Op[] $ops
     */
    private function isForeachListDestructRefFusion(array $ops, int $index, ?Block $block = null): bool
    {
        if ($this->isForeachLoopVarAssignRefFusion($ops, $index)) {
            return false;
        }
        if (!$ops[$index] instanceof Op\Iterator\Value) {
            return false;
        }
        $next = $index + 1;
        if ($next >= count($ops) || !$this->isListDestructGroupStart($ops, $next, $block)) {
            return false;
        }

        return $this->listDestructGroupHasAssignRef($ops, $next, $block);
    }

    /**
     * @param Op[] $ops
     */
    private function listDestructGroupHasAssignRef(array $ops, int $start, ?Block $block = null): bool
    {
        $end = $this->listDestructGroupEndIndex($ops, $start, $block);
        for ($i = $start; $i <= $end; ++$i) {
            if ($ops[$i] instanceof Op\Expr\AssignRef) {
                return true;
            }
        }

        return false;
    }

    /**
     * foreach ($iterable as &$obj->hookedProp) — Iterator\\Value [, PropertyFetch] AssignRef (#6435).
     *
     * @param Op[] $ops
     */
    private function isForeachPropertyHookAssignRefPair(array $ops, int $assignIndex): bool
    {
        if (!isset($ops[$assignIndex]) || !$ops[$assignIndex] instanceof Op\Expr\AssignRef) {
            return false;
        }
        /** @var Op\Expr\AssignRef $assign */
        $assign = $ops[$assignIndex];
        $cursor = $assignIndex - 1;
        if ($cursor >= 0 && $this->isListDestructPropertyFetchStmt($ops[$cursor])) {
            --$cursor;
        }
        if ($cursor < 0 || !$ops[$cursor] instanceof Op\Iterator\Value) {
            return false;
        }
        /** @var Op\Iterator\Value $iter */
        $iter = $ops[$cursor];

        return $iter->byRef
            && $iter->result === $assign->expr
            && (
                $this->operandIsPropertyWriteTarget($assign->var)
                || ($assignIndex > 0 && $this->isListDestructPropertyFetchStmt($ops[$assignIndex - 1]))
            );
    }

    private function operandIsPropertyWriteTarget(Operand $operand): bool
    {
        while ($operand instanceof Operand\Temporary && null !== $operand->original) {
            $operand = $operand->original;
        }

        return $operand instanceof Op\Expr\PropertyFetch
            || $operand instanceof Op\Expr\StaticPropertyFetch;
    }

    /**
     * php-cfg may emit PropertyFetch before Assign for hooked list slots (#6434).
     */
    private function isListDestructPropertyFetchStmt(Op $op): bool
    {
        return $op instanceof Op\Expr\PropertyFetch || $op instanceof Op\Expr\StaticPropertyFetch;
    }

    /**
     * Assign/AssignRef index for one list slot after write-target prelude ops (#6434, #7286).
     *
     * @param Op[] $ops
     */
    private function listDestructSlotAssignIndex(array $ops, int $index): ?int
    {
        if (!$ops[$index] instanceof Op\Expr\ArrayDimFetch) {
            return null;
        }
        /** @var Op\Expr\ArrayDimFetch $fetch */
        $fetch = $ops[$index];
        for ($cursor = $index + 1, $count = count($ops); $cursor < $count; ++$cursor) {
            $op = $ops[$cursor];
            if ($op instanceof Op\Expr\Assign || $op instanceof Op\Expr\AssignRef) {
                return $op->expr === $fetch->result ? $cursor : null;
            }
            if (!$this->isListDestructWriteTargetPreludeOp($op)) {
                return null;
            }
        }

        return null;
    }

    /**
     * CFG ops between a list RHS dim fetch and its slot Assign when the write target is complex.
     */
    private function isListDestructWriteTargetPreludeOp(Op $op): bool
    {
        return $op instanceof Op\Expr\New_
            || $this->isListDestructPropertyFetchStmt($op)
            || $op instanceof Op\Expr\ArrayDimFetch;
    }

    /**
     * php-cfg lowers `["key" => $v] = $array` to array literal + dim fetch + assign pairs (#1234).
     *
     * @param Op[] $ops
     */
    private function isKeyedListDestructDimFetch(array $ops, int $index, ?Block $block = null): bool
    {
        if (!$ops[$index] instanceof Op\Expr\ArrayDimFetch) {
            return false;
        }
        /** @var Op\Expr\ArrayDimFetch $fetch */
        $fetch = $ops[$index];
        if (null === $fetch->var) {
            return false;
        }
        if (!$fetch->dim instanceof Literal || !is_string($fetch->dim->value)) {
            return false;
        }
        $assignIndex = $this->listDestructSlotAssignIndex($ops, $index);
        if (null === $assignIndex) {
            return false;
        }
        /** @var Op\Expr\Assign|Op\Expr\AssignRef $assign */
        $assign = $ops[$assignIndex];
        if ($assign->expr !== $fetch->result) {
            return false;
        }
        // Distinguish `["k" => $v] = $rhs` from `$v = $rhs["k"]` (#22646).
        if (!$this->isListAssignmentLoweredDimFetch($fetch, $assign)) {
            return false;
        }

        return $this->assignIsListDestructSlotTarget($assign->var, $block);
    }

    private function assignIsListSpread(Op\Expr\Assign $assign): bool
    {
        return property_exists($assign, 'listSpreadRhs')
            && null !== $assign->listSpreadRhs
            && property_exists($assign, 'listSpreadFromIndex')
            && null !== $assign->listSpreadFromIndex;
    }

    private function isListSpreadAssignOp(Op $op): bool
    {
        return $op instanceof Op\Expr\Assign && $this->assignIsListSpread($op);
    }

    /**
     * php-cfg lowers `list($a, …) = $rhs` to integer-key dim fetches (#4298).
     *
     * @param Op[] $ops
     */
    private function isListDestructGroupStart(array $ops, int $index, ?Block $block = null): bool
    {
        if ($this->isListSpreadAssignOp($ops[$index])) {
            return !$this->isListDestructSpreadTail($ops, $index, $block);
        }
        if (
            !$this->isPlainListDestructDimFetch($ops, $index, $block)
            && !$this->isKeyedListDestructDimFetch($ops, $index, $block)
        ) {
            return false;
        }
        /** @var Op\Expr\ArrayDimFetch $cur */
        $cur = $ops[$index];
        $p = $index - 1;
        while ($p >= 0) {
            $op = $ops[$p];
            if ($op instanceof Op\Expr\Assign || $op instanceof Op\Expr\AssignRef) {
                --$p;
                continue;
            }
            if (
                $op instanceof Op\Expr\ArrayDimFetch
                && ($this->isPlainListDestructDimFetch($ops, $p, $block) || $this->isKeyedListDestructDimFetch($ops, $p, $block))
                && $op->var === $cur->var
            ) {
                return false;
            }

            break;
        }

        return true;
    }

    /**
     * Spread arm at the end of `[$a, ...$rest] = $rhs` — not a separate group start (#4835).
     *
     * @param Op[] $ops
     */
    private function isListDestructSpreadTail(array $ops, int $index, ?Block $block = null): bool
    {
        if (!$this->isListSpreadAssignOp($ops[$index])) {
            return false;
        }
        if ($index < 1) {
            return false;
        }
        $p = $index - 1;
        if ($ops[$p] instanceof Op\Expr\Assign || $ops[$p] instanceof Op\Expr\AssignRef) {
            --$p;
        }

        return $p >= 0
            && ($this->isPlainListDestructDimFetch($ops, $p, $block) || $this->isKeyedListDestructDimFetch($ops, $p, $block));
    }

    /**
     * @param Op[] $ops
     */
    private function isPlainListDestructDimFetch(array $ops, int $index, ?Block $block = null): bool
    {
        if (!$ops[$index] instanceof Op\Expr\ArrayDimFetch) {
            return false;
        }
        if ($this->isKeyedListDestructDimFetch($ops, $index, $block)) {
            return false;
        }
        /** @var Op\Expr\ArrayDimFetch $fetch */
        $fetch = $ops[$index];
        if (null === $fetch->var) {
            return false;
        }
        if (!$fetch->dim instanceof Operand\Literal || !is_int($fetch->dim->value)) {
            return false;
        }

        return $this->isListDestructDimFetchConsumer($ops, $index, $block);
    }

    /**
     * @param Op[] $ops
     */
    private function isListDestructDimFetchConsumer(array $ops, int $index, ?Block $block = null): bool
    {
        if ($index + 1 >= count($ops)) {
            return false;
        }
        $fetch = $ops[$index];
        $assignIndex = $this->listDestructSlotAssignIndex($ops, $index);
        if (null !== $assignIndex) {
            /** @var Op\Expr\Assign|Op\Expr\AssignRef $assign */
            $assign = $ops[$assignIndex];
            if ($assign->expr !== $fetch->result) {
                return false;
            }
            // `$c = $s[0]` and `[$c] = $s` share the same CFG shape; only list/array
            // assignment lowering stamps shared attrs (or Array_ kind) onto the fetch (#22646).
            if (!$fetch instanceof Op\Expr\ArrayDimFetch
                || !$this->isListAssignmentLoweredDimFetch($fetch, $assign)) {
                return false;
            }

            return $this->assignIsListDestructSlotTarget($assign->var, $block);
        }
        $next = $ops[$index + 1];

        return $next instanceof Op\Expr\ArrayDimFetch
            && $next->var === $fetch->result
            && $this->isPlainListDestructDimFetch($ops, $index + 1, $block);
    }

    /**
     * True when php-cfg emitted this dim fetch from `list()` / `[] =` assignment, not `$x = $y[$i]`.
     *
     * Short-array destruct carries PhpParser Array_ `kind`; both `list()` and `[]` stamp the same
     * source span on the fetch and its slot assign. Ordinary `$c = $s[0]` uses a narrower fetch span.
     *
     * @see #22646
     */
    private function isListAssignmentLoweredDimFetch(Op\Expr\ArrayDimFetch $fetch, Op $assign): bool
    {
        // Explicit marker from php-cfg parseListAssignment (#22646). Prefer this: Runtime's
        // ParserFactory lexer omits startFilePos/endFilePos, so span equality is unreliable.
        if (true === $fetch->getAttribute('listAssignment') || true === $assign->getAttribute('listAssignment')) {
            return true;
        }
        // Short-array `[$a] = $rhs` also carries PhpParser Array_ kind onto the fetch.
        if (null !== $fetch->getAttribute('kind')) {
            return true;
        }
        $fetchStart = $fetch->getAttribute('startFilePos');
        $assignStart = $assign->getAttribute('startFilePos');
        $fetchEnd = $fetch->getAttribute('endFilePos');
        $assignEnd = $assign->getAttribute('endFilePos');
        if (null === $fetchStart || null === $assignStart || null === $fetchEnd || null === $assignEnd) {
            return false;
        }

        return $fetchStart === $assignStart && $fetchEnd === $assignEnd;
    }

    /**
     * Last CFG op index belonging to one top-level `list()` / `[]` destructuring group (#4325).
     *
     * @param Op[] $ops
     */
    private function listDestructGroupEndIndex(array $ops, int $start, ?Block $block = null): int
    {
        $i = $start;
        if ($this->isListSpreadAssignOp($ops[$i])) {
            return $i;
        }
        while (
            $i < count($ops)
            && ($this->isPlainListDestructDimFetch($ops, $i, $block) || $this->isKeyedListDestructDimFetch($ops, $i, $block))
        ) {
            $i = $this->listDestructOpEndIndex($ops, $i);
        }
        if ($i < count($ops) && $this->isListSpreadAssignOp($ops[$i])) {
            return $i;
        }

        return $i - 1;
    }

    /**
     * @param Op[] $ops
     */
    private function listDestructRhsOperand(array $ops, int $start): Operand
    {
        if ($this->isListSpreadAssignOp($ops[$start])) {
            /** @var Op\Expr\Assign $spread */
            $spread = $ops[$start];

            return $spread->listSpreadRhs;
        }
        /** @var Op\Expr\ArrayDimFetch $firstFetch */
        $firstFetch = $ops[$start];

        return $firstFetch->var;
    }

    /**
     * @param Op[] $ops
     */
    private function listDestructOpEndIndex(array $ops, int $index): int
    {
        /** @var Op\Expr\ArrayDimFetch $fetch */
        $fetch = $ops[$index];
        $assignIndex = $this->listDestructSlotAssignIndex($ops, $index);
        if (null !== $assignIndex) {
            /** @var Op\Expr\Assign|Op\Expr\AssignRef $assign */
            $assign = $ops[$assignIndex];
            if ($assign->expr === $fetch->result) {
                return $assignIndex + 1;
            }
        }
        if ($index + 1 < count($ops)) {
            $next = $ops[$index + 1];
            if ($next instanceof Op\Expr\ArrayDimFetch && $next->var === $fetch->result) {
                return $this->listDestructOpEndIndex($ops, $index + 1);
            }
        }

        return $index + 1;
    }

    /**
     * Guard list destructuring: skip slot assignments when RHS is not an array (#4325); string RHS TypeError (#7461).
     *
     * @param Op[] $ops
     *
     * @return array{0: Block, 1: int}
     */
    private function compileListDestructGroup(array $ops, int $start, Block $block): array
    {
        $this->rejectListDestructuringSpreadAssignProfile($ops, $start, $block);
        $end = $this->listDestructGroupEndIndex($ops, $start, $block);
        $this->rejectListDestructNonWritableWriteTargets($ops, $start, $end, $block);
        $rhs = $this->listDestructRhsOperand($ops, $start);

        $checkOp = new OpCode(
            OpCode::TYPE_LIST_UNPACK_CHECK,
            null,
            $this->compileOperand($rhs, $block, true),
        );
        $block->addOpCode($checkOp);

        for ($j = $start; $j <= $end; ++$j) {
            $this->compileOp($ops[$j], $block);
        }
        $checkOp->listUnpackNullInitSlots = $this->collectListDestructAssignTargetSlots($block, $checkOp);
        $checkOp->listUnpackHasByRef = $this->listDestructGroupHasAssignRef($ops, $start, $block);

        $mergeBlock = new Block($block->orig);
        $mergeBlock->inheritUndefinedLocals = true;
        $mergeBlock->inheritScopeFrom($block);
        $this->inheritFuncFromParent($mergeBlock, $block);
        $checkOp->block1 = $mergeBlock;

        $assignJump = new OpCode(OpCode::TYPE_JUMP);
        $assignJump->block1 = $mergeBlock;
        $block->addOpCode($assignJump);
        $mergeBlock->parents[] = $block;

        return [$mergeBlock, $end];
    }

    /**
     * Named local slots written by guarded list destruct when assign path is skipped (#10591, #10486).
     *
     * @return list<int>
     */
    private function collectListDestructAssignTargetSlots(Block $block, OpCode $checkOp): array
    {
        $slots = [];
        $found = false;
        foreach ($block->opCodes as $op) {
            if ($op === $checkOp) {
                $found = true;
                continue;
            }
            if (!$found) {
                continue;
            }
            if (OpCode::TYPE_JUMP === $op->type) {
                break;
            }
            if (OpCode::TYPE_ASSIGN === $op->type || OpCode::TYPE_ASSIGN_REF === $op->type) {
                if (null !== $op->arg2 && $block->isNamedVariableSlot((int) $op->arg2)) {
                    $slots[(int) $op->arg2] = (int) $op->arg2;
                }
                continue;
            }
            if (OpCode::TYPE_LIST_SPREAD_ASSIGN === $op->type) {
                if (null !== $op->arg1 && $block->isNamedVariableSlot((int) $op->arg1)) {
                    $slots[(int) $op->arg1] = (int) $op->arg1;
                }
            }
        }

        return array_values($slots);
    }

    private function splitCfgBlockAfterStringKeyedArray(Block $block): Block
    {
        $cont = new Block($block->orig);
        $cont->inheritScopeFrom($block);
        // Temporaries have no name, so findVariableInParentFrames() cannot carry them across the
        // jump; without slot inheritance every value computed before the split reads back empty
        // in the continuation (#23354).
        $cont->inheritUndefinedLocals = true;
        $this->inheritFuncFromParent($cont, $block);
        $jumpToCont = new OpCode(OpCode::TYPE_JUMP);
        $jumpToCont->block1 = $cont;
        $block->addOpCode($jumpToCont);
        $cont->parents[] = $block;

        return $cont;
    }

    /**
     * php-cfg emits ArrayDimFetch as its own stmt before Coalesce; skip duplicate lowering.
     */
    private function isArrayDimFetchOnlyCoalesceLeft(
        Op\Expr\ArrayDimFetch $fetch,
        Op $next
    ): bool {
        if (!$next instanceof Op\Expr\BinaryOp\Coalesce) {
            return false;
        }
        $left = $next->left;
        while ($left instanceof Temporary) {
            if ($left === $fetch->result) {
                return true;
            }
            if (null === $left->original) {
                break;
            }
            $left = $left->original;
        }

        return $left === $fetch->result;
    }

    private function isPropertyFetchOnlyCoalesceLeft(
        Op\Expr\PropertyFetch $fetch,
        Op $next
    ): bool {
        if (!$next instanceof Op\Expr\BinaryOp\Coalesce) {
            return false;
        }
        $left = $next->left;
        while ($left instanceof Temporary) {
            if ($left === $fetch->result) {
                return true;
            }
            if (null === $left->original) {
                break;
            }
            $left = $left->original;
        }

        return $left === $fetch->result;
    }

    /**
     * php-cfg may emit RHS expr stmts between PropertyFetch and Coalesce (#8902).
     *
     * @param Op[] $ops
     *
     * @return ?array{0: Op\Expr\BinaryOp\Coalesce, 1: int}
     */
    private function findCoalesceUsingPropertyFetchLeft(
        Op\Expr\PropertyFetch $fetch,
        array $ops,
        int $index
    ): ?array {
        $count = count($ops);
        for ($j = $index + 1; $j < $count; ++$j) {
            $next = $ops[$j];
            if ($next instanceof Op\Expr\BinaryOp\Coalesce) {
                if (!$this->isPropertyFetchOnlyCoalesceLeft($fetch, $next)) {
                    return null;
                }

                return [$next, $j];
            }
            if ($this->isLoweredByFollowingCoalesce($next, $ops, $j)) {
                continue;
            }

            return null;
        }

        return null;
    }

    private function isPropertyFetchOnlyCoalesceFuncCallArg(
        Op\Expr\PropertyFetch $fetch,
        Op $call,
        Block $block
    ): bool {
        if (!$call instanceof Op\Expr\FuncCall && !$call instanceof Op\Expr\NsFuncCall) {
            return false;
        }
        if (!property_exists($call, 'args') || !is_array($call->args)) {
            return false;
        }
        foreach ($call->args as $arg) {
            $coalesce = $this->findCoalesceStmtForCallArg($arg, $block);
            if (null !== $coalesce && $this->findCoalescePropertyFetch($coalesce->left, $block) === $fetch) {
                return true;
            }
        }

        return false;
    }

    private function isArrayDimFetchOnlyCoalesceFuncCallArg(
        Op\Expr\ArrayDimFetch $fetch,
        Op $call,
        Block $block
    ): bool {
        if (!$call instanceof Op\Expr\FuncCall && !$call instanceof Op\Expr\NsFuncCall) {
            return false;
        }
        if (!property_exists($call, 'args') || !is_array($call->args)) {
            return false;
        }
        foreach ($call->args as $arg) {
            $coalesce = $this->findCoalesceStmtForCallArg($arg, $block);
            if (null !== $coalesce && $this->findCoalesceArrayDimFetch($coalesce->left, $block) === $fetch) {
                return true;
            }
        }

        return false;
    }

    /**
     * php-cfg may emit RHS expr stmts (FuncCall, …) between ArrayDimFetch and Coalesce (#4416).
     *
     * @param Op[] $ops
     *
     * @return ?array{0: Op\Expr\BinaryOp\Coalesce, 1: int}
     */
    private function findCoalesceUsingArrayDimFetchLeft(
        Op\Expr\ArrayDimFetch $fetch,
        array $ops,
        int $index
    ): ?array {
        $count = count($ops);
        for ($j = $index + 1; $j < $count; ++$j) {
            $next = $ops[$j];
            if ($next instanceof Op\Expr\BinaryOp\Coalesce) {
                if (!$this->isArrayDimFetchOnlyCoalesceLeft($fetch, $next)) {
                    return null;
                }

                return [$next, $j];
            }
            if ($this->isLoweredByFollowingCoalesce($next, $ops, $j)) {
                continue;
            }

            return null;
        }

        return null;
    }

    /**
     * php-cfg: ArrayDimFetch; Coalesce; Assign $dst = fetch-temp after ?? already stored in $dst.
     */
    private function isRedundantCoalesceTailAssign(
        Op\Expr\Assign $assign,
        Op\Expr\ArrayDimFetch $fetch,
        Op\Expr\BinaryOp\Coalesce $coalesce
    ): bool {
        return $this->isCoalesceAssignTail($assign, $coalesce);
    }

    /**
     * php-cfg: Coalesce; Assign $dst = coalesce-result for ??= (issue #1235).
     */
    private function isCoalesceAssignTail(
        Op\Expr\Assign $assign,
        Op\Expr\BinaryOp\Coalesce $coalesce
    ): bool {
        return $this->operandsChainEqual($assign->expr, $coalesce->result);
    }

    /**
     * php-cfg emits inner ?? before outer for chains ($a ?? $b ?? $c); only lower the outer stmt (#3798).
     *
     * @param Op[] $ops
     */
    private function isCoalesceChainInnerStmt(
        Op\Expr\BinaryOp\Coalesce $inner,
        array $ops,
        int $index
    ): bool {
        if ($index + 1 >= count($ops)) {
            return false;
        }
        $next = $ops[$index + 1];
        if (!$next instanceof Op\Expr\BinaryOp\Coalesce) {
            return false;
        }

        return $this->operandsChainEqual($next->right, $inner->result);
    }

    /**
     * Echo with embedded ?? / ??= must use compileCoalesce and continue on the merge block (#99, #1960, #1980).
     *
     * @param Op[] $ops
     */
    private function compileEchoWithEmbeddedCoalesce(Op $op, Block $block, array $ops, int $echoIndex): ?Block
    {
        if (!$op instanceof Op\Terminal || 'Terminal_Echo' !== $op->getType()) {
            return null;
        }
        // php-cfg: BinaryOp\Coalesce child immediately before Terminal_Echo(expr=coalesce.result).
        if ($echoIndex >= 1) {
            $prior = $ops[$echoIndex - 1];
            if (
                $prior instanceof Op\Expr\BinaryOp\Coalesce
                && $this->operandsChainEqual($op->expr, $prior->result)
            ) {
                $var = $this->compileOperand($prior->result, $block, true);
                $line = $op->getLine();
                $block->addOpCode(new OpCode(OpCode::TYPE_ECHO, $var, $line > 0 ? $line : null));

                return $block;
            }
        }
        $echoAfterAssign = $this->resolveEchoAfterCoalesceAssign($ops, $echoIndex, $op->expr);
        if (null !== $echoAfterAssign && $this->isStmtCoalesceLoweredBeforeEcho($ops, $echoIndex)) {
            $var = $this->compileOperand($echoAfterAssign, $block, true);
            $line = $op->getLine();
            $block->addOpCode(new OpCode(OpCode::TYPE_ECHO, $var, $line > 0 ? $line : null));

            return $block;
        }
        $coalesces = $this->findEmbeddedCoalesces($op->expr);
        if ([] === $coalesces) {
            // Block-scan fallback: only pending ?? — already-merged ones rewind CFG to a
            // prior merge and strand later nullsafe/?? after TYPE_NULLSAFE (#19591 / #18455).
            foreach ($this->findBlockCoalescesBeforeIndex($ops, $echoIndex) as $candidate) {
                if (isset($this->coalesceMergeBlocks[spl_object_id($candidate)])) {
                    continue;
                }
                $coalesces[] = $candidate;
            }
        }
        if ([] === $coalesces) {
            return null;
        }
        $flattened = $this->flattenBinaryConcatFromBlockOps($ops, $echoIndex, $op->expr)
            ?? $this->unwrapConcatListExpr($op->expr)
            ?? $this->flattenBinaryConcatToConcatList($op->expr);
        $echoOperand = $op->expr;
        $coalesceSnapshots = [];
        foreach ($coalesces as $coalesce) {
            $resultOverride = $this->findCoalesceAssignTarget($ops, $coalesce)
                ?? $this->findEchoCoalesceAssignTarget($ops, $echoIndex, $coalesce);
            if (null === $this->slotForCoalesceResult($block, $coalesce)) {
                $block = $this->compileCoalesceForAssign($coalesce, $block, $resultOverride);
            }
            $coalesceId = spl_object_id($coalesce);
            if (isset($this->coalesceMergeBlocks[$coalesceId])) {
                $block = $this->coalesceMergeBlocks[$coalesceId];
            }
            if (null !== $resultOverride) {
                $coalesceSnapshots[] = [$coalesce, $resultOverride];
                continue;
            }
            $snapshot = new Operand\Temporary();
            $readSlot = $this->compileOperand($coalesce->result, $block, true);
            $writeSlot = $block->forceFreshVarSlot($snapshot);
            $block->addOpCode(new OpCode(
                OpCode::TYPE_ASSIGN,
                $writeSlot,
                $writeSlot,
                $readSlot
            ));
            $coalesceSnapshots[] = [$coalesce, $snapshot];
            if (
                null === $flattened
                && (
                    $this->operandsChainEqual($echoOperand, $coalesce->result)
                    || $echoOperand === $coalesce
                    || (
                        null !== ($embeddedCoalesce = $this->unwrapCoalesceExpr($echoOperand))
                        && $embeddedCoalesce === $coalesce
                    )
                )
            ) {
                $echoOperand = $snapshot;
            }
        }
        if (null !== $flattened) {
            $block = $this->compileEchoConcatFuncCallPreludes($ops, $echoIndex, $flattened, $block);
        }
        $concat = $flattened;
        if (null !== $concat) {
            $parts = [];
            foreach ($concat->list as $part) {
                $replaced = $part;
                foreach ($coalesceSnapshots as [$coalesce, $replacement]) {
                    if (
                        $this->operandsChainEqual($part, $coalesce->result)
                        || $this->operandsChainEqual($part, $replacement)
                        || $part === $coalesce
                        || (
                            null !== ($embeddedCoalesce = $this->unwrapCoalesceExpr($part))
                            && $embeddedCoalesce === $coalesce
                        )
                    ) {
                        $replaced = $replacement;
                        break;
                    }
                }
                $parts[] = $replaced;
            }
            $concat = new Op\Expr\ConcatList($parts);
            $concat->result = $flattened->result;
            $this->compileOp($concat, $block);
            $var = $this->compileOperand($concat->result, $block, true);
        } else {
            $var = $this->compileOperand($echoOperand, $block, true);
            $var = $this->resolveEchoEmitSlot($echoOperand, $block, $var);
        }
        $line = $op->getLine();
        $echoOpcode = new OpCode(OpCode::TYPE_ECHO, $var, $line > 0 ? $line : null);
        $this->attachEchoScriptGlobalName($echoOpcode, $echoOperand, $block);
        $block->addOpCode($echoOpcode);

        return $block;
    }

    /**
     * Compile FuncCall preludes that feed echo-concat operands after ?? merge blocks (#18315).
     *
     * @param Op[] $ops
     */
    private function compileEchoConcatFuncCallPreludes(
        array $ops,
        int $echoIndex,
        Op\Expr\ConcatList $flattened,
        Block $block
    ): Block {
        $neededResults = [];
        foreach ($flattened->list as $part) {
            if (null !== $part) {
                $neededResults[] = $part;
            }
        }
        for ($j = 0; $j < $echoIndex; ++$j) {
            $child = $ops[$j];
            if (
                !($child instanceof Op\Expr\FuncCall || $child instanceof Op\Expr\NsFuncCall)
                || !property_exists($child, 'result')
                || null === $child->result
            ) {
                continue;
            }
            $feedsConcat = false;
            foreach ($neededResults as $needed) {
                if (
                    $this->operandsChainEqual($needed, $child->result)
                    || $this->operandsReferToSameVariable($needed, $child->result)
                ) {
                    $feedsConcat = true;
                    break;
                }
            }
            if (!$feedsConcat || null !== $block->slotForOperand($child->result)) {
                continue;
            }
            for ($k = $j - 1; $k >= 0; --$k) {
                $prev = $ops[$k];
                if ($prev instanceof Op\Expr\BinaryOp\Coalesce) {
                    break;
                }
                if (
                    $prev instanceof Op\Expr
                    && $this->isInlineExprCallArgProducer($prev)
                    && null !== $prev->result
                    && null === $block->slotForOperand($prev->result)
                ) {
                    $this->compileOp($prev, $block);
                }
            }
            $this->compileOp($child, $block);
        }

        return $block;
    }

    /**
     * php-cfg: Coalesce; Assign; Terminal_Echo(expr=coalesce.result) — echo the ??= lvalue (#1980).
     *
     * @param Op[] $ops
     */
    private function resolveEchoAfterCoalesceAssign(array $ops, int $echoIndex, Operand $echoExpr): ?Operand
    {
        if ($echoIndex < 2) {
            return null;
        }
        $assign = $ops[$echoIndex - 1];
        $coalesce = $ops[$echoIndex - 2];
        if (!$assign instanceof Op\Expr\Assign || !$coalesce instanceof Op\Expr\BinaryOp\Coalesce) {
            if (
                $echoIndex >= 3
                && $ops[$echoIndex - 1] instanceof Op\Expr\Assign
                && $ops[$echoIndex - 2] instanceof Op\Expr\ArrayDimFetch
                && $ops[$echoIndex - 3] instanceof Op\Expr\BinaryOp\Coalesce
            ) {
                /** @var Op\Expr\Assign $assign */
                $assign = $ops[$echoIndex - 1];
                /** @var Op\Expr\ArrayDimFetch $fetch */
                $fetch = $ops[$echoIndex - 2];
                /** @var Op\Expr\BinaryOp\Coalesce $coalesce */
                $coalesce = $ops[$echoIndex - 3];
                if (
                    $this->isRedundantCoalesceTailAssign($assign, $fetch, $coalesce)
                    && $this->operandsChainEqual($echoExpr, $coalesce->result)
                ) {
                    return $assign->var;
                }
            }

            return null;
        }
        if (
            $this->isCoalesceAssignTail($assign, $coalesce)
            && (
                $this->operandsChainEqual($echoExpr, $coalesce->result)
                || $this->operandsChainEqual($echoExpr, $assign->var)
            )
        ) {
            return $assign->var;
        }

        return null;
    }

    /**
     * @param Op[] $ops
     */
    private function isStmtCoalesceLoweredBeforeEcho(array $ops, int $echoIndex): bool
    {
        if ($echoIndex >= 1 && $ops[$echoIndex - 1] instanceof Op\Expr\BinaryOp\Coalesce) {
            return true;
        }
        if ($echoIndex >= 2 && $ops[$echoIndex - 2] instanceof Op\Expr\BinaryOp\Coalesce) {
            return true;
        }
        if ($echoIndex >= 3 && $ops[$echoIndex - 3] instanceof Op\Expr\BinaryOp\Coalesce) {
            return true;
        }

        return false;
    }

    /**
     * php-cfg: Coalesce immediately followed by Assign(expr=coalesce.result).
     *
     * @param Op[] $ops
     */
    private function findCoalesceAssignTarget(array $ops, Op\Expr\BinaryOp\Coalesce $coalesce): ?Operand
    {
        $count = \count($ops);
        for ($j = 0; $j < $count - 1; ++$j) {
            if ($ops[$j] !== $coalesce) {
                continue;
            }
            $next = $ops[$j + 1];
            if ($next instanceof Op\Expr\Assign && $this->isCoalesceAssignTail($next, $coalesce)) {
                return $next->var;
            }

            return null;
        }

        return null;
    }

    /**
     * php-cfg: Coalesce; Assign; Terminal_Echo(expr=coalesce.result) for inline ??= (#1980).
     *
     * @param Op[] $ops
     */
    private function findEchoCoalesceAssignTarget(
        array $ops,
        int $echoIndex,
        Op\Expr\BinaryOp\Coalesce $coalesce
    ): ?Operand {
        $direct = $this->findCoalesceAssignTarget($ops, $coalesce);
        if (null !== $direct) {
            return $direct;
        }
        if ($echoIndex > 0) {
            $prev = $ops[$echoIndex - 1];
            if ($prev instanceof Op\Expr\Assign && $this->isCoalesceAssignTail($prev, $coalesce)) {
                return $prev->var;
            }
        }
        if (
            $echoIndex > 2
            && $ops[$echoIndex - 2] instanceof Op\Expr\Assign
            && $ops[$echoIndex - 3] instanceof Op\Expr\ArrayDimFetch
        ) {
            /** @var Op\Expr\Assign $assign */
            $assign = $ops[$echoIndex - 2];
            /** @var Op\Expr\ArrayDimFetch $fetch */
            $fetch = $ops[$echoIndex - 3];
            if ($this->isRedundantCoalesceTailAssign($assign, $fetch, $coalesce)) {
                return $assign->var;
            }
        }

        return null;
    }

    /**
     * @param Op[] $ops
     */
    private function isCoalesceLoweredBeforeEcho(
        array $ops,
        int $echoIndex,
        Op\Expr\BinaryOp\Coalesce $coalesce
    ): bool {
        for ($j = $echoIndex - 1; $j >= 0; --$j) {
            if ($ops[$j] === $coalesce) {
                return true;
            }
        }

        return false;
    }

    /**
     * @return list<Op\Expr\BinaryOp\Coalesce>
     */
    private function findEmbeddedCoalesces(Operand $operand): array
    {
        $found = [];
        $seen = [];
        $add = function (Op\Expr\BinaryOp\Coalesce $coalesce) use (&$found, &$seen): void {
            $id = spl_object_id($coalesce);
            if (isset($seen[$id])) {
                return;
            }
            $seen[$id] = true;
            $found[] = $coalesce;
        };
        $coalesce = $this->unwrapCoalesceExpr($operand);
        if (null !== $coalesce) {
            $add($coalesce);
        }
        $root = $this->unwrapOperandChain($operand);
        if ($root instanceof Op\Expr\BinaryOp\Coalesce) {
            $add($root);
        }
        $concat = $this->unwrapConcatListExpr($operand);
        if (null !== $concat) {
            foreach ($concat->list as $part) {
                foreach ($this->findEmbeddedCoalesces($part) as $nested) {
                    $add($nested);
                }
            }
        }
        $binaryConcat = $this->unwrapBinaryConcatExpr($operand);
        if (null !== $binaryConcat) {
            foreach ($this->findEmbeddedCoalesces($binaryConcat->left) as $nested) {
                $add($nested);
            }
            foreach ($this->findEmbeddedCoalesces($binaryConcat->right) as $nested) {
                $add($nested);
            }
        }

        return $found;
    }

    /**
     * Chained ?? call args: compile coalesce into a temp, then call on the merge block (#17380).
     *
     * @return ?list<OpCode>
     */
    private function compileFuncCallAfterChainedCoalesceArgs(Op\Expr\FuncCall $expr, Block $block): ?array
    {
        $newArgs = $expr->args;
        $changed = false;
        /** @var array<int, int> $chainedCoalesceArgTempSlots */
        $chainedCoalesceArgTempSlots = [];
        /** @var array<int, int> $chainedCoalesceArgMergeSources */
        $chainedCoalesceArgMergeSources = [];
        foreach ($expr->args as $i => $arg) {
            $coalesce = $this->findChainedCoalesceForCallArg($arg, $block, $expr, (int) $i);
            if (null === $coalesce) {
                continue;
            }
            $mergeSlot = $this->coalesceResultSlots[spl_object_id($coalesce)]
                ?? $this->slotForCoalesceResult($block, $coalesce);
            if (null === $mergeSlot) {
                continue;
            }
            $callArg = $expr->args[$i] ?? $arg;
            $callBlock = $this->coalesceMergeBlocks[spl_object_id($coalesce)] ?? $block;
            // Snapshot ?? merge into the php-cfg call-arg temp on the call block (#17590 AOT).
            $argSendSlot = $this->compileOperand($callArg, $callBlock, false);
            $this->registerSyncedCoalesceFuncCallArgSlot($arg, $argSendSlot);
            $this->registerSyncedCoalesceFuncCallArgSlot($callArg, $argSendSlot);
            $newArgs[$i] = $callArg;
            $chainedCoalesceArgTempSlots[(int) $i] = $argSendSlot;
            $chainedCoalesceArgMergeSources[(int) $i] = $mergeSlot;
            $changed = true;
        }
        if (!$changed) {
            return null;
        }
        $callBlock = $block;
        foreach ($expr->args as $i => $arg) {
            $coalesce = $this->findChainedCoalesceForCallArg($arg, $block, $expr, (int) $i);
            if (null !== $coalesce && isset($this->coalesceMergeBlocks[spl_object_id($coalesce)])) {
                $callBlock = $this->coalesceMergeBlocks[spl_object_id($coalesce)];
                break;
            }
        }
        $callOps = $this->compileFuncCall(
            $this->compileOperand($expr->name, $callBlock, true),
            $newArgs,
            $expr->result,
            $callBlock,
            max(0, $expr->getLine()),
            $expr
        );
        if ([] !== $chainedCoalesceArgTempSlots) {
            $callOps = $this->rewireChainedCoalesceFuncCallArgSends($callOps, $chainedCoalesceArgTempSlots);
        }
        foreach ($chainedCoalesceArgMergeSources as $argIdx => $mergeSlot) {
            $sendSlot = $chainedCoalesceArgTempSlots[(int) $argIdx];
            $callBlock->addOpCode(new OpCode(
                OpCode::TYPE_ASSIGN,
                $sendSlot,
                $sendSlot,
                $mergeSlot
            ));
        }
        foreach ($callOps as $op) {
            $callBlock->addOpCode($op);
        }
        foreach ($chainedCoalesceArgTempSlots as $argIdx => $tempSlot) {
            $this->patchBlockChainedCoalesceFuncCallArgSend($callBlock, (int) $argIdx, $tempSlot);
        }

        return [];
    }

    private function patchBlockChainedCoalesceFuncCallArgSend(Block $block, int $argIndex, int $tempSlot): void
    {
        $inCall = false;
        $sendIdx = 0;
        foreach ($block->opCodes as $op) {
            if (OpCode::TYPE_FUNCCALL_INIT === $op->type) {
                $inCall = true;
                $sendIdx = 0;
                continue;
            }
            if (!$inCall || OpCode::TYPE_ARG_SEND !== $op->type) {
                if (OpCode::TYPE_FUNCCALL_EXEC_NORETURN === $op->type || OpCode::TYPE_FUNCCALL_EXEC_RETURN === $op->type) {
                    $inCall = false;
                }
                continue;
            }
            if ($sendIdx === $argIndex) {
                $op->arg1 = (string) $tempSlot;
            }
            ++$sendIdx;
        }
    }

    /**
     * @param list<OpCode>     $callOps
     * @param array<int, int> $argTempSlots
     *
     * @return list<OpCode>
     */
    private function rewireChainedCoalesceFuncCallArgSends(array $callOps, array $argTempSlots): array
    {
        $inCall = false;
        $sendIdx = 0;
        foreach ($callOps as $op) {
            if (OpCode::TYPE_FUNCCALL_INIT === $op->type) {
                $inCall = true;
                $sendIdx = 0;
                continue;
            }
            if (!$inCall || OpCode::TYPE_ARG_SEND !== $op->type) {
                if (OpCode::TYPE_FUNCCALL_EXEC_NORETURN === $op->type || OpCode::TYPE_FUNCCALL_EXEC_RETURN === $op->type) {
                    $inCall = false;
                }
                continue;
            }
            if (isset($argTempSlots[$sendIdx])) {
                $op->arg1 = (string) $argTempSlots[$sendIdx];
            }
            ++$sendIdx;
        }

        return $callOps;
    }

    private function findChainedCoalesceForCallArg(
        Operand $arg,
        Block $block,
        ?Op $cfgCallOp,
        int $argIndex
    ): ?Op\Expr\BinaryOp\Coalesce {
        foreach ($this->findEmbeddedCoalesces($arg) as $coalesce) {
            if ($this->coalesceRhsIsNestedCoalesce($coalesce, $block)) {
                return $coalesce;
            }
        }
        if ($this->callArgReadsAssignLvalueNotInlineCoalesce($arg, $block)) {
            return null;
        }
        $stmtCoalesce = $this->findOutermostChainedCoalesceStmtForCallArg($arg, $block, $cfgCallOp, $argIndex);
        if (null !== $stmtCoalesce) {
            return $stmtCoalesce;
        }
        if (null !== $cfgCallOp && is_array($cfgCallOp->args ?? null)) {
            $cfgArg = $cfgCallOp->args[$argIndex] ?? null;
            if (null !== $cfgArg && $cfgArg !== $arg) {
                foreach ($this->findEmbeddedCoalesces($cfgArg) as $coalesce) {
                    if ($this->coalesceRhsIsNestedCoalesce($coalesce, $block)) {
                        return $coalesce;
                    }
                }
            }
        }

        return null;
    }

    private function findOutermostChainedCoalesceStmtForCallArg(
        Operand $arg,
        Block $block,
        ?Op $cfgCallOp,
        int $argIndex
    ): ?Op\Expr\BinaryOp\Coalesce {
        $inner = $this->findCoalesceStmtForCallArg($arg, $block);
        if (null === $inner && null !== $cfgCallOp && is_array($cfgCallOp->args ?? null)) {
            $cfgArg = $cfgCallOp->args[$argIndex] ?? null;
            if (null !== $cfgArg && $cfgArg !== $arg) {
                $inner = $this->findCoalesceStmtForCallArg($cfgArg, $block);
            }
        }
        if (null === $inner || null === $block->orig) {
            return null !== $inner && $this->coalesceRhsIsNestedCoalesce($inner, $block) ? $inner : null;
        }
        $outermost = $inner;
        foreach ($block->orig->children as $op) {
            if (!$op instanceof Op\Expr\BinaryOp\Coalesce) {
                continue;
            }
            if (!$this->coalesceRhsIsNestedCoalesce($op, $block)) {
                continue;
            }
            if (
                $this->operandsChainEqual($op->right, $inner->result)
                || $this->operandsReferToSameVariable($op->right, $inner->result)
                || $op->right === $inner
            ) {
                $outermost = $op;
            }
        }

        return $this->coalesceRhsIsNestedCoalesce($outermost, $block) ? $outermost : null;
    }

    private function coalesceRhsIsNestedCoalesce(Op\Expr\BinaryOp\Coalesce $coalesce, Block $block): bool
    {
        $rhsRoot = $this->unwrapOperandChain($coalesce->right);
        if ($rhsRoot instanceof Op\Expr\BinaryOp\Coalesce) {
            return true;
        }

        return $this->findOrigExprOpForOperand($coalesce->right, $block) instanceof Op\Expr\BinaryOp\Coalesce;
    }

    /**
     * True when $arg is an assign lvalue fed by a prior stmt-level ?? (#17590).
     *
     * compileFuncCallAfterChainedCoalesceArgs must not re-lower ?? for var_export($v) after $v = … ?? ….
     */
    private function callArgReadsAssignLvalueNotInlineCoalesce(Operand $arg, Block $block): bool
    {
        if ($this->callArgIsDirectChainedCoalesceMergeTarget($arg)) {
            return true;
        }
        if (null === $block->orig) {
            return false;
        }
        foreach ($block->orig->children as $i => $child) {
            if (
                !($child instanceof Op\Expr\Assign)
                || !$this->operandsReferToSameVariable($child->var, $arg)
            ) {
                continue;
            }
            if (
                0 === $i
                || !($block->orig->children[$i - 1] instanceof Op\Expr\BinaryOp\Coalesce)
            ) {
                continue;
            }
            /** @var Op\Expr\BinaryOp\Coalesce $priorCoalesce */
            $priorCoalesce = $block->orig->children[$i - 1];

            return $this->isCoalesceAssignTail($child, $priorCoalesce);
        }

        return false;
    }

    /** True when ?? was lowered with resultOverride = php-cfg call-arg temp (#17590). */
    private function callArgIsDirectChainedCoalesceMergeTarget(Operand $arg): bool
    {
        foreach ($this->coalesceAssignLvalues as $lvalue) {
            if (
                $this->operandsReferToSameVariable($lvalue, $arg)
                || $this->operandsChainEqual($lvalue, $arg)
            ) {
                return true;
            }
        }

        return false;
    }

    /**
     * php-cfg call-arg temp for chained ?? before FuncCall — mirror assign-then-call (#17590).
     */
    private function resolveChainedCoalesceCallArgOverride(
        Op\Expr\BinaryOp\Coalesce $coalesce,
        Block $block,
        int $coalesceIdx
    ): ?Operand {
        if (null === $block->orig || !$this->followingFuncCallHasChainedCoalesceArg($block, $coalesceIdx)) {
            return null;
        }
        $children = $block->orig->children;
        for ($j = $coalesceIdx + 1, $count = \count($children); $j < $count; ++$j) {
            $next = $children[$j];
            if ($next instanceof Op\Expr\FuncCall || $next instanceof Op\Expr\NsFuncCall) {
                if (!property_exists($next, 'args') || !\is_array($next->args)) {
                    return null;
                }
                foreach ($next->args as $argIndex => $arg) {
                    if (null === $arg) {
                        continue;
                    }
                    $outermost = $this->findOutermostChainedCoalesceStmtForCallArg(
                        $arg,
                        $block,
                        $next,
                        (int) $argIndex
                    );
                    if ($outermost === $coalesce) {
                        return $next->args[$argIndex];
                    }
                }

                return null;
            }
            if ($next instanceof Op\Expr && $this->isInlineExprCallArgProducer($next)) {
                continue;
            }

            return null;
        }

        return null;
    }

    private function coalesceStmtDeferredToChainedFuncCallArg(
        Op\Expr\BinaryOp\Coalesce $coalesce,
        Block $block
    ): bool {
        if (null === $block->orig) {
            return false;
        }
        $idx = array_search($coalesce, $block->orig->children, true);

        return \is_int($idx) && $this->followingFuncCallHasChainedCoalesceArg($block, $idx);
    }

    /**
     * Inner ?? stmt whose result feeds outer chained ?? deferred to FuncCall (#17590).
     */
    private function coalesceStmtFeedsDeferredChainedFuncCallArg(
        Op\Expr\BinaryOp\Coalesce $coalesce,
        Block $block
    ): bool {
        if (null === $block->orig) {
            return false;
        }
        $idx = array_search($coalesce, $block->orig->children, true);
        if (!\is_int($idx)) {
            return false;
        }
        $children = $block->orig->children;
        for ($j = $idx + 1, $count = \count($children); $j < $count; ++$j) {
            $next = $children[$j];
            if ($next instanceof Op\Expr\BinaryOp\Coalesce) {
                if (
                    $this->operandsChainEqual($next->right, $coalesce->result)
                    || $this->operandsReferToSameVariable($next->right, $coalesce->result)
                    || $next->right === $coalesce
                ) {
                    return $this->coalesceStmtDeferredToChainedFuncCallArg($next, $block);
                }

                return false;
            }
            if ($next instanceof Op\Expr && $this->isInlineExprCallArgProducer($next)) {
                continue;
            }

            return false;
        }

        return false;
    }

    private function followingFuncCallHasChainedCoalesceArg(Block $block, int $fromIdx): bool
    {
        if (null === $block->orig) {
            return false;
        }
        $children = $block->orig->children;
        for ($j = $fromIdx + 1, $count = \count($children); $j < $count; ++$j) {
            $next = $children[$j];
            if ($next instanceof Op\Expr\FuncCall || $next instanceof Op\Expr\NsFuncCall) {
                if (!property_exists($next, 'args') || !\is_array($next->args)) {
                    return false;
                }
                foreach ($next->args as $argIndex => $arg) {
                    if (null !== $arg
                        && null !== $this->findChainedCoalesceForCallArg($arg, $block, $next, (int) $argIndex)
                    ) {
                        return true;
                    }
                }

                return false;
            }
            if ($next instanceof Op\Expr && $this->isInlineExprCallArgProducer($next)) {
                continue;
            }

            return false;
        }

        return false;
    }

    private function compileCoalesceForAssign(
        Op\Expr\BinaryOp\Coalesce $coalesce,
        Block $block,
        ?Operand $resultOverride = null
    ): Block {
        if (null !== $resultOverride) {
            // ??= skips compileExpr(Assign); enforce the same write-context guards (#29247).
            $this->rejectNullsafeInWriteContext($resultOverride, $block);
            $this->rejectNewExprInWriteContext($resultOverride, $block, null, null, $coalesce);
            $this->rejectArrayLiteralInWriteContext($resultOverride, $block, $coalesce);
            $this->rejectGlobalConstInWriteContext($resultOverride, $block, $coalesce);
            $this->rejectCallReturnInWriteContext($resultOverride, $block, $coalesce);
        }
        if (null === $resultOverride) {
            $dimFetch = $this->findCoalesceArrayDimFetch($coalesce->left, $block);
            if (null !== $dimFetch && $this->operandsChainEqual($coalesce->result, $dimFetch->result)) {
                $resultOverride = $dimFetch->result;
            } elseif ($this->operandsChainEqual($coalesce->result, $coalesce->left)) {
                $resultOverride = $coalesce->left;
            }
        }

        if (
            null !== $resultOverride
            && !$this->operandsChainEqual($resultOverride, $coalesce->result)
        ) {
            $this->coalesceAssignLvalues[spl_object_id($coalesce)] = $resultOverride;
        }

        $block = $this->compileCoalesce($coalesce, $block, $resultOverride);

        // Tail `$local = $… ?? …` skips the Assign that would registerNamedAssignDest (#24540).
        // Without that CV binding, later SSA reads of $local (is_array ? … / if bodies) allocate
        // fresh undefined slots while the coalesce merge slot still holds the value.
        if (null !== $resultOverride) {
            $varRoot = Block::cfgVarRoot($resultOverride);
            $cvName = null !== $varRoot ? Block::resolveVariableName($varRoot) : null;
            if (null !== $varRoot && null !== $cvName && '' !== $cvName) {
                $cvSlot = $this->coalesceResultSlots[spl_object_id($coalesce)]
                    ?? $this->compileOperand($resultOverride, $block, false);
                $block->registerNamedAssignDest($varRoot, (int) $cvSlot);
            }
        }

        // php-cfg keeps a separate coalesce result temp when ??= is an expression (#5337, #17458).
        // Skip when echo reads resultOverride directly — syncing would null the override slot (TYPE_ASSIGN).
        if (
            $this->coalesceAssignNeedsResultTempSync($coalesce, $resultOverride, $block)
            || $this->coalesceAssignHasFollowingCallExpressionConsumer($coalesce, $resultOverride, $block)
        ) {
            $resultSlot = $this->compileOperand($coalesce->result, $block, false);
            $overrideSlot = $this->compileOperand($resultOverride, $block, false);
            $block->addOpCode(new OpCode(
                OpCode::TYPE_ASSIGN,
                $resultSlot,
                $resultSlot,
                $overrideSlot
            ));
        }

        $this->syncCoalesceResultToDistinctFuncCallArg($coalesce, $block, $resultOverride);

        return $block;
    }

    private function registerSyncedCoalesceFuncCallArgSlot(Operand $targetArg, int $slot): void
    {
        $this->syncedCoalesceFuncCallArgSlots['oid:' . spl_object_id($targetArg)] = $slot;
        $root = Block::cfgVarRoot($targetArg);
        if (null !== $root) {
            $this->syncedCoalesceFuncCallArgSlots[spl_object_id($root)] = $slot;
        }
    }

    private function resolveSyncedCoalesceFuncCallArgSlot(Operand $arg): ?int
    {
        $oidKey = 'oid:' . spl_object_id($arg);
        if (isset($this->syncedCoalesceFuncCallArgSlots[$oidKey])) {
            return $this->syncedCoalesceFuncCallArgSlots[$oidKey];
        }
        $root = Block::cfgVarRoot($arg);
        if (null !== $root && isset($this->syncedCoalesceFuncCallArgSlots[spl_object_id($root)])) {
            return $this->syncedCoalesceFuncCallArgSlots[spl_object_id($root)];
        }

        return null;
    }

    /** True when a call arg reads stmt-level or embedded ?? (merge block must keep coalesce slot, #16127). */
    private function callArgIsCoalesceMergeProducer(
        ?Operand $arg,
        Block $block,
        ?Op $cfgCallOp = null,
        ?int $argIndex = null
    ): bool {
        if (null === $arg) {
            return false;
        }
        if (
            null !== $this->resolveSyncedCoalesceFuncCallArgSlot($arg)
            || null !== $this->findCoalesceStmtForCallArg($arg, $block)
        ) {
            return true;
        }
        if (null !== $cfgCallOp && null !== $argIndex) {
            $probe = $cfgCallOp->args[$argIndex] ?? null;
            if (null !== $probe && $probe !== $arg) {
                return $this->callArgIsCoalesceMergeProducer($probe, $block);
            }
        }

        return false;
    }

    /**
     * Stmt-level ?? immediately before a FuncCall (only inline producers in between, #11601, #15915).
     */
    private function findStmtCoalesceImmediatelyBeforeFuncCall(Op $callOp, Block $block): ?Op\Expr\BinaryOp\Coalesce
    {
        if (null === $block->orig) {
            return null;
        }
        $children = $block->orig->children;
        $callIndex = null;
        foreach ($children as $i => $child) {
            if ($child === $callOp) {
                $callIndex = $i;
                break;
            }
        }
        if (
            null === $callIndex
            && property_exists($callOp, 'result')
            && null !== $callOp->result
        ) {
            foreach ($children as $i => $child) {
                if (
                    ($child instanceof Op\Expr\FuncCall || $child instanceof Op\Expr\NsFuncCall)
                    && null !== $child->result
                    && (
                        $child->result === $callOp->result
                        || $this->operandsReferToSameVariable($child->result, $callOp->result)
                    )
                ) {
                    $callIndex = $i;
                    break;
                }
            }
        }
        if (null === $callIndex) {
            return null;
        }
        for ($j = $callIndex - 1; $j >= 0; --$j) {
            $prev = $children[$j];
            if ($prev instanceof Op\Expr\BinaryOp\Coalesce) {
                return $prev;
            }
            // var_dump(array_keys($arr['k'] ?? [])) — ?? feeds the inner call only (#15946).
            if (
                $j === $callIndex - 1
                && ($prev instanceof Op\Expr\FuncCall || $prev instanceof Op\Expr\NsFuncCall)
            ) {
                return null;
            }
            if ($prev instanceof Op\Expr && $this->isInlineExprCallArgProducer($prev)) {
                continue;
            }

            break;
        }

        return null;
    }

    /**
     * Stmt-level ?? nodes immediately feeding a FuncCall, in execution order (#17981).
     *
     * @return list<Op\Expr\BinaryOp\Coalesce>
     */
    private function stmtLevelCoalescesBeforeFuncCall(Op $callOp, Block $block): array
    {
        if (null === $block->orig) {
            return [];
        }
        $children = $block->orig->children;
        $callIndex = null;
        foreach ($children as $i => $child) {
            if ($child === $callOp) {
                $callIndex = $i;
                break;
            }
        }
        if (
            null === $callIndex
            && property_exists($callOp, 'result')
            && null !== $callOp->result
        ) {
            foreach ($children as $i => $child) {
                if (
                    ($child instanceof Op\Expr\FuncCall || $child instanceof Op\Expr\NsFuncCall)
                    && null !== $child->result
                    && (
                        $child->result === $callOp->result
                        || $this->operandsReferToSameVariable($child->result, $callOp->result)
                    )
                ) {
                    $callIndex = $i;
                    break;
                }
            }
        }
        if (null === $callIndex) {
            return [];
        }
        $coalesces = [];
        for ($j = $callIndex - 1; $j >= 0; --$j) {
            $prev = $children[$j];
            if ($prev instanceof Op\Expr\BinaryOp\Coalesce) {
                array_unshift($coalesces, $prev);

                continue;
            }
            if (
                $prev instanceof Op\Expr\Assign
                && $j > 0
            ) {
                $maybeCoalesce = $children[$j - 1];
                if (
                    $maybeCoalesce instanceof Op\Expr\BinaryOp\Coalesce
                    && $this->isCoalesceAssignTail($prev, $maybeCoalesce)
                ) {
                    array_unshift($coalesces, $maybeCoalesce);
                    --$j;

                    continue;
                }
            }
            if ($prev instanceof Op\Expr && $this->isInlineExprCallArgProducer($prev)) {
                continue;
            }

            break;
        }

        return $coalesces;
    }

    /**
     * Call-arg indices fed by distinct stmt-level ?? temps (not embedded ?? or literals, #17981).
     *
     * @return list<int>
     */
    private function stmtCoalesceFedCallArgIndices(Op $callOp): array
    {
        if (!property_exists($callOp, 'args') || !\is_array($callOp->args)) {
            return [];
        }
        $fedArgIndices = [];
        foreach ($callOp->args as $idx => $callArg) {
            if (null === $callArg || $this->isCallArgUnrelatedToPriorStmtCoalesce($callArg)) {
                continue;
            }
            if ([] !== $this->findEmbeddedCoalesces($callArg)) {
                continue;
            }
            $fedArgIndices[] = (int) $idx;
        }

        return $fedArgIndices;
    }

    /**
     * Map a stmt-level ?? to its matching php-cfg call-arg temp when multiple ?? precede one call (#17981).
     */
    private function findCallArgForStmtCoalesce(
        Op $callOp,
        Op\Expr\BinaryOp\Coalesce $coalesce,
        Block $block
    ): ?Operand {
        $coalesces = $this->stmtLevelCoalescesBeforeFuncCall($callOp, $block);
        $coalesceIndex = array_search($coalesce, $coalesces, true);
        if (false === $coalesceIndex || \count($coalesces) < 2) {
            return null;
        }
        $fedArgIndices = $this->stmtCoalesceFedCallArgIndices($callOp);
        if (\count($fedArgIndices) !== \count($coalesces)) {
            return null;
        }

        return $callOp->args[$fedArgIndices[$coalesceIndex] ?? -1] ?? null;
    }

    /**
     * Map a php-cfg call-arg temp to its stmt-level ?? when multiple ?? precede one call (#17981).
     */
    private function findStmtCoalesceForOrdinalCallArg(
        Op $callOp,
        Operand $matchedCallArg,
        Block $block
    ): ?Op\Expr\BinaryOp\Coalesce {
        $coalesces = $this->stmtLevelCoalescesBeforeFuncCall($callOp, $block);
        if (\count($coalesces) < 2) {
            return null;
        }
        $fedArgIndices = $this->stmtCoalesceFedCallArgIndices($callOp);
        if (\count($fedArgIndices) !== \count($coalesces)) {
            return null;
        }
        foreach ($fedArgIndices as $ordinal => $argIdx) {
            $callArg = $callOp->args[$argIdx] ?? null;
            if (
                null !== $callArg
                && (
                    $callArg === $matchedCallArg
                    || $this->operandsReferToSameVariable($callArg, $matchedCallArg)
                )
            ) {
                return $coalesces[$ordinal] ?? null;
            }
        }

        return null;
    }

    private function callArgHasPriorStmtCoalesce(
        Operand $arg,
        Block $block,
        ?Op $cfgCallOp,
        int $argIndex
    ): bool {
        if (null !== $this->findCoalesceStmtForCallArg($arg, $block)) {
            return true;
        }
        if (null !== $this->resolveSyncedCoalesceFuncCallArgSlot($arg)) {
            return true;
        }
        if (
            0 === $argIndex
            && null !== $cfgCallOp
            && null !== ($stmtCoalesce = $this->findStmtCoalesceImmediatelyBeforeFuncCall($cfgCallOp, $block))
        ) {
            $firstArg = $cfgCallOp->args[0] ?? null;
            $resultOverride = $this->coalesceAssignLvalueOperand($stmtCoalesce);
            $hasOtherCoalesceFedArg = false;
            foreach ($cfgCallOp->args ?? [] as $idx => $otherArg) {
                if ((int) $idx === $argIndex || null === $otherArg) {
                    continue;
                }
                if (
                    [] !== $this->findEmbeddedCoalesces($otherArg)
                    || $this->callArgMatchesCoalesceExpressionValue($otherArg, $stmtCoalesce, $resultOverride)
                ) {
                    $hasOtherCoalesceFedArg = true;
                    break;
                }
            }
            // Named first args (gettype($a) after `$a['x'] ??…`) are containers, not the ?? value (#29112).
            if (
                !$hasOtherCoalesceFedArg
                && null !== $firstArg
                && !$this->isEmbeddedCallLiteralArg($arg)
                && (
                    $this->callArgMatchesCoalesceExpressionValue($arg, $stmtCoalesce, $resultOverride)
                    || (
                        $this->callArgIsDeadInlineTemporary($firstArg)
                        && $this->operandsReferToSameVariable($firstArg, $arg)
                    )
                )
            ) {
                return true;
            }
        }

        return false;
    }

    /**
     * Stmt-level ?? before multi-arg calls must win over hoisted dim-fetch producer slots (#11601, #15915).
     */
    private function finalizeStmtCoalesceCallArgSlot(
        Operand $arg,
        Block $block,
        ?Op $cfgCallOp,
        int $argIndex,
        ?string $valueSlot
    ): ?string {
        if ($this->isCallArgDirectArrayDimFetch($arg)) {
            return $valueSlot;
        }
        $callArg = (null !== $cfgCallOp && is_array($cfgCallOp->args ?? null))
            ? ($cfgCallOp->args[$argIndex] ?? null)
            : null;
        foreach (array_filter([$callArg, $arg]) as $probe) {
            $syncedSlot = $this->resolveSyncedCoalesceFuncCallArgSlot($probe);
            if (null !== $syncedSlot) {
                return (string) $syncedSlot;
            }
        }
        $coalesce = $this->findCoalesceStmtForCallArg($arg, $block);
        if (null === $coalesce && null !== $cfgCallOp && 0 === $argIndex) {
            $stmtCoalesce = $this->findStmtCoalesceImmediatelyBeforeFuncCall($cfgCallOp, $block);
            if (null !== $stmtCoalesce) {
                $firstArg = $cfgCallOp->args[0] ?? null;
                $resultOverride = $this->coalesceAssignLvalueOperand($stmtCoalesce);
                $hasOtherCoalesceFedArg = false;
                foreach ($cfgCallOp->args ?? [] as $idx => $otherArg) {
                    if ((int) $idx === $argIndex || null === $otherArg) {
                        continue;
                    }
                    if (
                        [] !== $this->findEmbeddedCoalesces($otherArg)
                        || $this->callArgMatchesCoalesceExpressionValue($otherArg, $stmtCoalesce, $resultOverride)
                    ) {
                        $hasOtherCoalesceFedArg = true;
                        break;
                    }
                }
                if (
                    !$hasOtherCoalesceFedArg
                    && null !== $firstArg
                    && !$this->isEmbeddedCallLiteralArg($arg)
                    && (
                        $this->callArgMatchesCoalesceExpressionValue($arg, $stmtCoalesce, $resultOverride)
                        || (
                            $this->callArgIsDeadInlineTemporary($firstArg)
                            && $this->operandsReferToSameVariable($firstArg, $arg)
                        )
                    )
                ) {
                    $coalesce = $stmtCoalesce;
                }
            }
        }
        if (null !== $coalesce) {
            $coalesceSlot = $this->slotForCoalesceResult($block, $coalesce);
            if (null !== $coalesceSlot) {
                return (string) $coalesceSlot;
            }
        }

        return $valueSlot;
    }

    /**
     * True when $callArg is the ?? / ??= expression value — not the dim/prop container (#29112).
     *
     * Matching coalesce->left is unsafe: for `$a['x'] ?? …` / `??=` the left is the element
     * temp, and a following `gettype($a)` / `json_encode($a)` must keep the array/object CV.
     */
    private function callArgMatchesCoalesceExpressionValue(
        Operand $callArg,
        Op\Expr\BinaryOp\Coalesce $coalesce,
        ?Operand $resultOverride
    ): bool {
        if (
            $this->operandsChainEqual($callArg, $coalesce->result)
            || $this->operandsReferToSameVariable($callArg, $coalesce->result)
        ) {
            return true;
        }
        if (
            null !== $resultOverride
            && (
                $this->operandsChainEqual($callArg, $resultOverride)
                || $this->operandsReferToSameVariable($callArg, $resultOverride)
            )
        ) {
            return true;
        }

        return false;
    }

    /**
     * Resolve ??= / `$dst = … ?? …` assign destination recorded for a coalesce stmt (#29112).
     */
    private function coalesceAssignLvalueOperand(Op\Expr\BinaryOp\Coalesce $coalesce): ?Operand
    {
        return $this->coalesceAssignLvalues[spl_object_id($coalesce)] ?? null;
    }

    /**
     * php-cfg may allocate a distinct temp for FuncCall args vs Coalesce->result (#9479, enum_int_cast_warning.phpt).
     */
    private function syncCoalesceResultToDistinctFuncCallArg(
        Op\Expr\BinaryOp\Coalesce $coalesce,
        Block $block,
        ?Operand $resultOverride
    ): void {
        if (null === $block->orig) {
            return;
        }
        $ops = $block->orig->children;
        $coalesceIdx = null;
        foreach ($ops as $idx => $op) {
            if ($op === $coalesce) {
                $coalesceIdx = $idx;
                break;
            }
        }
        if (null === $coalesceIdx) {
            return;
        }
        for ($j = $coalesceIdx + 1, $count = count($ops); $j < $count; ++$j) {
            $next = $ops[$j];
            if ($this->isLoweredByFollowingCoalesce($next, $ops, $j)) {
                continue;
            }
            // Only the ??= tail Assign may sit between coalesce and an immediate call.
            // Skipping general inline producers walked across later `$a["k"] ??= …` / `$a = …`
            // and froze a pre-mutation snapshot into the call arg (#29145, re-#28954 shape).
            if (
                $next instanceof Op\Expr\Assign
                && $this->isCoalesceAssignTail($next, $coalesce)
            ) {
                continue;
            }
            if (!$next instanceof Op\Expr\FuncCall && !$next instanceof Op\Expr\NsFuncCall) {
                return;
            }
            if (!property_exists($next, 'args') || !is_array($next->args) || [] === $next->args) {
                return;
            }
            foreach ($next->args as $embeddedArgProbe) {
                if (null === $embeddedArgProbe) {
                    continue;
                }
                foreach ($this->findEmbeddedCoalesces($embeddedArgProbe) as $embedded) {
                    if ($embedded === $coalesce) {
                        return;
                    }
                }
            }
            $targetArg = null;
            foreach ($next->args as $callArg) {
                if (
                    null === $callArg
                    || $this->isCallArgUnrelatedToPriorStmtCoalesce($callArg)
                ) {
                    continue;
                }
                if ($this->callArgMatchesCoalesceExpressionValue($callArg, $coalesce, $resultOverride)) {
                    $targetArg = $callArg;
                    break;
                }
            }
            if (null === $targetArg) {
                $ordinalTarget = $this->findCallArgForStmtCoalesce($next, $coalesce, $block);
                if (null !== $ordinalTarget) {
                    $targetArg = $ordinalTarget;
                } else {
                    // First-arg fallback is only for php-cfg dead expression temps
                    // (`foo($a['x'] ?? 'y')`), never named containers like gettype($a) (#29112).
                    $firstArg = $next->args[0] ?? null;
                    if (
                        null !== $firstArg
                        && !$this->isCallArgUnrelatedToPriorStmtCoalesce($firstArg)
                        && $this->onlyInlineCallArgProducersBetweenIndices($ops, $coalesceIdx, $j)
                        && (
                            $this->callArgMatchesCoalesceExpressionValue($firstArg, $coalesce, $resultOverride)
                            || $this->callArgIsDeadInlineTemporary($firstArg)
                        )
                    ) {
                        $targetArg = $firstArg;
                    }
                }
            }
            if (null === $targetArg) {
                return;
            }
            $syncReadOperand = $this->coalesceAssignHasFollowingCallExpressionConsumer(
                $coalesce,
                $resultOverride,
                $block
            )
                ? $coalesce->result
                : ($resultOverride ?? $coalesce->result);
            // Wire the post-?? merge result slot — not an inner dim-fetch temp (#10743, #15915).
            $this->registerSyncedCoalesceFuncCallArgSlot(
                $targetArg,
                $this->compileOperand($syncReadOperand, $block, true)
            );

            return;
        }
    }

    /**
     * Stmt-level ??= immediately before FuncCall — expression value lives in a dead arg temp (#5337, #17458).
     *
     * "Immediately" means only the ??= tail Assign may intervene. Do not skip ArrayDimFetch /
     * later ??= / other writes — those mutate the lvalue and the call must read the live CV (#29145).
     */
    private function coalesceAssignHasFollowingCallExpressionConsumer(
        Op\Expr\BinaryOp\Coalesce $coalesce,
        ?Operand $resultOverride,
        Block $block
    ): bool {
        if (
            null === $resultOverride
            || null === $block->orig
            || $this->operandsChainEqual($resultOverride, $coalesce->result)
        ) {
            return false;
        }
        $ops = $block->orig->children;
        $coalesceIdx = null;
        foreach ($ops as $idx => $op) {
            if ($op === $coalesce) {
                $coalesceIdx = $idx;
                break;
            }
        }
        if (null === $coalesceIdx) {
            return false;
        }
        for ($j = $coalesceIdx + 1, $count = \count($ops); $j < $count; ++$j) {
            $next = $ops[$j];
            if ($next instanceof Op\Expr\Assign && $this->isCoalesceAssignTail($next, $coalesce)) {
                continue;
            }
            if ($next instanceof Op\Expr\FuncCall || $next instanceof Op\Expr\NsFuncCall) {
                return true;
            }
            if ($next instanceof Op\Expr\MethodCall || $next instanceof Op\Expr\StaticCall) {
                return true;
            }
            // Echo / dim ??= / plain assign / anything else: not an expression-value call consumer.
            return false;
        }

        return false;
    }

    /**
     * True when ??= coalesce->result is read outside echo/tail-assign paths (#5337).
     */
    private function coalesceAssignNeedsResultTempSync(
        Op\Expr\BinaryOp\Coalesce $coalesce,
        ?Operand $resultOverride,
        Block $block
    ): bool {
        if (
            null === $resultOverride
            || $this->operandsChainEqual($resultOverride, $coalesce->result)
        ) {
            return false;
        }
        if (null === $block->orig) {
            return true;
        }

        $ops = $block->orig->children;
        $tailAssign = null;
        foreach ($ops as $idx => $op) {
            if ($op !== $coalesce) {
                continue;
            }
            if (
                isset($ops[$idx + 1])
                && $ops[$idx + 1] instanceof Op\Expr\Assign
                && $this->isCoalesceAssignTail($ops[$idx + 1], $coalesce)
            ) {
                $tailAssign = $ops[$idx + 1];
            }
            break;
        }

        foreach ($ops as $op) {
            if ($op instanceof Op\Expr\Assign) {
                if ($op === $tailAssign) {
                    continue;
                }
                if ($this->operandsChainEqual($op->expr, $coalesce->result)) {
                    return true;
                }
            }
            if ($op instanceof Op\Terminal\Echo) {
                if ($this->operandsChainEqual($op->expr, $coalesce->result)) {
                    continue;
                }
            }
            if ($op instanceof Op\Expr\FuncCall || $op instanceof Op\Expr\NsFuncCall) {
                foreach ($op->args as $arg) {
                    if ($this->operandsChainEqual($arg, $coalesce->result)) {
                        return true;
                    }
                }
            }
            if ($op instanceof Op\Expr\MethodCall || $op instanceof Op\Expr\StaticCall) {
                foreach ($op->args as $arg) {
                    if ($this->operandsChainEqual($arg, $coalesce->result)) {
                        return true;
                    }
                }
            }
            if ($op instanceof Op\Terminal\Return_ && null !== $op->expr) {
                if ($this->operandsChainEqual($op->expr, $coalesce->result)) {
                    return true;
                }
            }
            if ($op instanceof Op\Expr\BinaryOp\Coalesce && $op !== $coalesce) {
                if ($this->operandsChainEqual($op->right, $coalesce->result)) {
                    return true;
                }
            }
        }

        return false;
    }

    /**
     * @return ?Op\Expr\ConcatList
     */
    private function unwrapConcatListExpr(Operand $operand): ?Op\Expr\ConcatList
    {
        while ($operand instanceof Temporary) {
            if ($operand->original instanceof Op\Expr\ConcatList) {
                return $operand->original;
            }
            if (null === $operand->original) {
                return null;
            }
            $operand = $operand->original;
        }
        if ($operand instanceof Op\Expr\ConcatList) {
            return $operand;
        }

        return null;
    }

    private function unwrapBinaryConcatExpr(Operand $operand): ?Op\Expr\BinaryOp\Concat
    {
        while ($operand instanceof Temporary) {
            if ($operand->original instanceof Op\Expr\BinaryOp\Concat) {
                return $operand->original;
            }
            if (null === $operand->original) {
                return null;
            }
            $operand = $operand->original;
        }
        if ($operand instanceof Op\Expr\BinaryOp\Concat) {
            return $operand;
        }

        return null;
    }

    /**
     * @param Op[] $ops
     */
    private function resolveBinaryConcatForOperand(Operand $operand, array $ops): ?Op\Expr\BinaryOp\Concat
    {
        $concat = $this->unwrapBinaryConcatExpr($operand);
        if (null !== $concat) {
            return $concat;
        }
        foreach ($ops as $op) {
            if ($op instanceof Op\Expr\BinaryOp\Concat && $this->operandsChainEqual($op->result, $operand)) {
                return $op;
            }
        }

        return null;
    }

    /**
     * Flatten nested BinaryOp\Concat trees to one ConcatList so ?? branches do not split temps (#10430).
     *
     * @param Op[] $ops
     *
     * @return ?Op\Expr\ConcatList
     */
    private function flattenBinaryConcatFromBlockOps(array $ops, int $echoIndex, Operand $echoExpr): ?Op\Expr\ConcatList
    {
        $outer = null;
        for ($j = $echoIndex - 1; $j >= 0; --$j) {
            $candidate = $ops[$j] ?? null;
            if (
                $candidate instanceof Op\Expr\BinaryOp\Concat
                && $this->operandsChainEqual($candidate->result, $echoExpr)
            ) {
                $outer = $candidate;
                break;
            }
        }
        if (null === $outer) {
            return $this->flattenBinaryConcatToConcatList($echoExpr);
        }
        $parts = [];
        $current = $outer;
        while ($current instanceof Op\Expr\BinaryOp\Concat) {
            $parts[] = $current->right;
            $inner = $this->resolveBinaryConcatForOperand($current->left, $ops);
            if ($inner instanceof Op\Expr\BinaryOp\Concat) {
                $current = $inner;
                continue;
            }
            $parts[] = $current->left;
            break;
        }
        if (\count($parts) < 2) {
            return null;
        }
        $parts = array_reverse($parts);
        $list = new Op\Expr\ConcatList($parts);
        $list->result = $outer->result;

        return $list;
    }

    /**
     * @return ?Op\Expr\ConcatList
     */
    private function flattenBinaryConcatToConcatList(?Operand $operand): ?Op\Expr\ConcatList
    {
        if (null === $operand) {
            return null;
        }
        $parts = [];
        $current = $operand;
        $topConcat = null;
        while (null !== $current) {
            $concat = $this->unwrapBinaryConcatExpr($current);
            if (null === $concat) {
                $parts[] = $current;
                break;
            }
            if (null === $topConcat) {
                $topConcat = $concat;
            }
            $parts[] = $concat->right;
            $current = $concat->left;
        }
        if (\count($parts) < 2 || null === $topConcat) {
            return null;
        }
        $parts = array_reverse($parts);
        $list = new Op\Expr\ConcatList($parts);
        $list->result = $topConcat->result;

        return $list;
    }

    /**
     * @param Op[] $ops
     *
     * @return list<Op\Expr\BinaryOp\Coalesce>
     */
    private function findBlockCoalescesBeforeIndex(array $ops, int $endIndex): array
    {
        $found = [];
        for ($j = 0; $j < $endIndex; ++$j) {
            if ($ops[$j] instanceof Op\Expr\BinaryOp\Coalesce) {
                $found[] = $ops[$j];
            }
        }

        return $found;
    }

    /**
     * Defer BinaryOp\Concat only when a following echo will lower pending ?? into the
     * concat (compileEchoWithEmbeddedCoalesce). Already-merged coalesces must not count —
     * otherwise a later `echo "x".$obj->prop` after `$a?->b ?? …` skips CONCAT and echoes
     * an empty temp (#25525 / re-#18455).
     *
     * @param Op[] $ops
     */
    private function isConcatLoweredByFollowingEcho(Op\Expr\BinaryOp\Concat $concat, array $ops, int $index): bool
    {
        $count = \count($ops);
        for ($j = $index + 1; $j < $count; ++$j) {
            $next = $ops[$j];
            if ($next instanceof Op\Terminal\Echo_) {
                $coalesces = $this->findEmbeddedCoalesces($next->expr);
                if ([] === $coalesces) {
                    // Match compileEchoWithEmbeddedCoalesce: only pending ?? (#25525).
                    foreach ($this->findBlockCoalescesBeforeIndex($ops, $j) as $candidate) {
                        if (!isset($this->coalesceMergeBlocks[spl_object_id($candidate)])) {
                            $coalesces[] = $candidate;
                        }
                    }
                }
                if ([] === $coalesces) {
                    return false;
                }

                return null !== $this->flattenBinaryConcatFromBlockOps($ops, $j, $next->expr)
                    || null !== $this->unwrapConcatListExpr($next->expr)
                    || null !== $this->flattenBinaryConcatToConcatList($next->expr);
            }
            if ($next instanceof Op\Terminal\Return || $next instanceof Op\Expr\Assign) {
                return false;
            }
        }

        return false;
    }

    /**
     * @param Op[] $ops
     */
    private function isCoalesceLoweredByFollowingEchoConcat(array $ops, int $index): bool
    {
        for ($j = $index + 1; $j < \count($ops); ++$j) {
            if ($ops[$j] instanceof Op\Terminal\Echo_) {
                if (null !== $this->flattenBinaryConcatToConcatList($ops[$j]->expr)) {
                    return true;
                }
                if (null !== $this->flattenBinaryConcatFromBlockOps($ops, $j, $ops[$j]->expr)) {
                    return true;
                }

                return false;
            }
            if ($ops[$j] instanceof Op\Terminal\Return) {
                return false;
            }
        }

        return false;
    }

    /**
     * echo var_export($arr['k'] ?? $d, true) . "\n" — defer call until ?? merge + concat echo (#18315).
     *
     * @param Op[] $ops
     */
    private function isFuncCallLoweredByFollowingEchoConcat(Op $call, array $ops, int $index): bool
    {
        if (
            !($call instanceof Op\Expr\FuncCall || $call instanceof Op\Expr\NsFuncCall)
            || !property_exists($call, 'result')
            || null === $call->result
        ) {
            return false;
        }
        $concat = $ops[$index + 1] ?? null;
        if (
            !$concat instanceof Op\Expr\BinaryOp\Concat
            || !(
                $this->operandsChainEqual($concat->left, $call->result)
                || $this->operandsReferToSameVariable($concat->left, $call->result)
            )
        ) {
            return false;
        }
        for ($j = $index + 2; $j < \count($ops); ++$j) {
            $next = $ops[$j];
            if ($next instanceof Op\Terminal\Echo_) {
                $flattened = $this->flattenBinaryConcatFromBlockOps($ops, $j, $next->expr)
                    ?? $this->flattenBinaryConcatToConcatList($next->expr);
                if (null === $flattened) {
                    return false;
                }
                $feedsEchoConcat = false;
                foreach ($flattened->list as $part) {
                    if (
                        null !== $part
                        && (
                            $this->operandsChainEqual($part, $call->result)
                            || $this->operandsReferToSameVariable($part, $call->result)
                        )
                    ) {
                        $feedsEchoConcat = true;
                        break;
                    }
                }
                if (!$feedsEchoConcat) {
                    return false;
                }
                for ($k = $index - 1; $k >= 0; --$k) {
                    $prev = $ops[$k];
                    if ($prev instanceof Op\Expr\BinaryOp\Coalesce) {
                        return $this->isCoalesceLoweredByFollowingEchoConcat($ops, $k);
                    }
                    if (!$prev instanceof Op\Expr || !$this->isInlineExprCallArgProducer($prev)) {
                        break;
                    }
                }

                return false;
            }
            if ($next instanceof Op\Terminal\Return) {
                return false;
            }
        }

        return false;
    }

    /**
     * @param Op[] $ops
     */
    private function isConstFetchLoweredByFollowingEchoConcatFuncCall(array $ops, int $index): bool
    {
        $next = $ops[$index + 1] ?? null;
        if (!$next instanceof Op\Expr\FuncCall && !$next instanceof Op\Expr\NsFuncCall) {
            return false;
        }

        return $this->isFuncCallLoweredByFollowingEchoConcat($next, $ops, $index + 1);
    }

    /**
     * Stmt-level ?? consumed by a FuncCall before echo-concat lowering runs (#18315, re-#11601).
     *
     * @param Op[] $ops
     */
    private function stmtCoalesceFeedsFuncCallBeforeEcho(
        Op\Expr\BinaryOp\Coalesce $coalesce,
        Op $callOp,
        array $ops,
        int $coalesceIndex,
        int $callIndex
    ): bool {
        if (!property_exists($callOp, 'args') || !is_array($callOp->args)) {
            return false;
        }
        $resultOverride = $this->coalesceAssignLvalueOperand($coalesce);
        foreach ($callOp->args as $callArg) {
            if (
                null !== $callArg
                && !$this->isCallArgUnrelatedToPriorStmtCoalesce($callArg)
                && $this->callArgMatchesCoalesceExpressionValue($callArg, $coalesce, $resultOverride)
            ) {
                return true;
            }
        }
        $firstArg = $callOp->args[0] ?? null;
        if (
            null !== $firstArg
            && !$this->isCallArgUnrelatedToPriorStmtCoalesce($firstArg)
            && $this->onlyInlineCallArgProducersBetweenIndices($ops, $coalesceIndex, $callIndex)
            && (
                $this->callArgMatchesCoalesceExpressionValue($firstArg, $coalesce, $resultOverride)
                || $this->callArgIsDeadInlineTemporary($firstArg)
            )
        ) {
            return true;
        }

        return false;
    }

    /**
     * Copy ?? branch results into merge-block temps so concat reads live CVs (#10430, #9973).
     */
    private function materializeConcatListCoalesceParts(Op\Expr\ConcatList $concat, Block $block): Op\Expr\ConcatList
    {
        $parts = [];
        foreach ($concat->list as $part) {
            if ($part instanceof Operand\Literal) {
                $parts[] = $part;
                continue;
            }
            $readSlot = $this->compileOperand($part, $block, true);
            $fresh = new Operand\Temporary();
            $writeSlot = $block->forceFreshVarSlot($fresh);
            $block->addOpCode(new OpCode(
                OpCode::TYPE_ASSIGN,
                $writeSlot,
                $writeSlot,
                $readSlot
            ));
            $parts[] = $fresh;
        }
        $materialized = new Op\Expr\ConcatList($parts);
        $materialized->result = $concat->result;

        return $materialized;
    }

    /**
     * php-cfg may embed Expr (e.g. spaceship) only under ConcatList / echo without a separate block op (#3671).
     */
    private function isExprLoweredInBlock(Op\Expr $expr, Block $block): bool
    {
        if (null === $block->orig) {
            return false;
        }
        foreach ($block->orig->ops as $op) {
            if ($op === $expr) {
                return true;
            }
        }

        return false;
    }

    /**
     * Lower embedded expressions before reading operand slots (echo / concat paths).
     */
    private function compileEmbeddedExprForOperand(?Operand $operand, Block $block): void
    {
        if (null === $operand) {
            return;
        }
        if (!$operand instanceof Operand\Temporary || null === $operand->original) {
            return;
        }
        $original = $operand->original;
        if ($original instanceof Op\Expr && $this->isExprLoweredInBlock($original, $block)) {
            return;
        }
        if ($original instanceof Op\Expr\ConcatList) {
            $this->compileOp($original, $block);

            return;
        }
        if ($original instanceof Op\Expr) {
            $this->compileDeferredCoalesceBranchExpr($original, $block);
        }
    }

    private function compileConcatListPart(Operand $part, Block $block): int
    {
        $this->compileEmbeddedExprForOperand($part, $block);

        return $this->compileOperand($part, $block, true);
    }

    /** Concat destination must not alias an active catch variable slot (#17384). */
    private function concatResultSlotAliasesCatchVar(int $slot): bool
    {
        if ([] === $this->activeCatchVarSlotsByName) {
            return false;
        }

        return \in_array($slot, $this->activeCatchVarSlotsByName, true);
    }

    private function freshConcatResultSlotIfCatchAlias(int $slot, Block $block, Operand $result): int
    {
        if (!$this->concatResultSlotAliasesCatchVar($slot)) {
            return $slot;
        }

        return $block->forceFreshVarSlot($result);
    }

    /**
     * @return ?Op\Expr\BinaryOp\Coalesce
     */
    private function unwrapCoalesceExpr(Operand $operand): ?Op\Expr\BinaryOp\Coalesce
    {
        while ($operand instanceof Temporary) {
            if ($operand->original instanceof Op\Expr\BinaryOp\Coalesce) {
                return $operand->original;
            }
            if (null === $operand->original) {
                return null;
            }
            $operand = $operand->original;
        }
        if ($operand instanceof Op\Expr\BinaryOp\Coalesce) {
            return $operand;
        }

        return null;
    }

    private function operandsChainEqual(Operand $a, Operand $b): bool
    {
        while ($a instanceof Temporary) {
            if ($a === $b) {
                return true;
            }
            if (null === $a->original) {
                break;
            }
            $a = $a->original;
        }
        while ($b instanceof Temporary) {
            if ($b === $a) {
                return true;
            }
            if (null === $b->original) {
                break;
            }
            $b = $b->original;
        }

        return $a === $b;
    }

    /**
     * php-cfg emits ArrayDimFetch as its own stmt before Isset_; skip duplicate lowering.
     * Nested `$a['x']['y']` chains are skipped entirely and quiet-fetched from compileIsset (#21991).
     */
    private function isArrayDimFetchOnlyIssetVar(
        Op\Expr\ArrayDimFetch $fetch,
        Op $next
    ): bool {
        if (!$next instanceof Op\Expr\Isset_) {
            return false;
        }
        foreach ($next->vars as $var) {
            $target = $var;
            while ($target instanceof Temporary) {
                if ($target === $fetch->result) {
                    return true;
                }
                if (null === $target->original) {
                    break;
                }
                $target = $target->original;
            }
            if ($target === $fetch->result) {
                return true;
            }
        }

        return false;
    }

    /**
     * Skip ArrayDimFetch stmts consumed by isset()/empty()/unset(), including nested dim chains
     * (`$a['x']['y']`) where only the innermost is adjacent to isset/empty (#21991), and sibling
     * dims before multi-target unset (`unset($o->a[$k], $o->b[$k])`) (#24250).
     *
     * @param Op[] $ops
     */
    private function isArrayDimFetchSkippedForIssetEmptyOrUnset(
        Op\Expr\ArrayDimFetch $fetch,
        array $ops,
        int $i,
        Block $block
    ): bool {
        $opCount = count($ops);
        for ($j = $i + 1; $j < $opCount; ++$j) {
            $next = $ops[$j];
            if (
                $this->isArrayDimFetchOnlyIssetVar($fetch, $next)
                || $this->isArrayDimFetchOnlyEmptyVar($fetch, $next, $block)
                || $this->isArrayDimFetchOnlyUnsetVar($fetch, $next)
            ) {
                return true;
            }
            if ($next instanceof Op\Expr\ArrayDimFetch) {
                if ($this->arrayDimFetchConsumesPriorResult($next, $fetch)) {
                    return $this->isArrayDimFetchSkippedForIssetEmptyOrUnset($next, $ops, $j, $block);
                }
                // Sibling dim fetch before multi-target unset/isset/empty (#24250).
                continue;
            }
            if ($next instanceof Op\Expr\PropertyFetch) {
                // Property prelude for a later sibling dim (`$this->a[$k], $this->b[$k]`) (#24250).
                continue;
            }

            return false;
        }

        return false;
    }

    /**
     * Skip intermediate ArrayDimFetch stmts in a nested `$a['x']['y'] ??…` / `??=` chain (#28954).
     * The innermost dim is lowered via {@see findCoalesceUsingArrayDimFetchLeft}; intermediates must
     * not emit FETCH_DIM_R (Undefined array key) before coalesce quiet/write lowering.
     *
     * @param Op[] $ops
     */
    private function isArrayDimFetchSkippedForCoalesce(
        Op\Expr\ArrayDimFetch $fetch,
        array $ops,
        int $i,
        Block $block
    ): bool {
        $opCount = count($ops);
        for ($j = $i + 1; $j < $opCount; ++$j) {
            $next = $ops[$j];
            if ($next instanceof Op\Expr\ArrayDimFetch) {
                if (!$this->arrayDimFetchConsumesPriorResult($next, $fetch)) {
                    // Sibling dim before a later coalesce left — keep scanning.
                    continue;
                }
                if (null !== $this->findCoalesceUsingArrayDimFetchLeft($next, $ops, $j)) {
                    return true;
                }

                return $this->isArrayDimFetchSkippedForCoalesce($next, $ops, $j, $block);
            }
            if ($this->isLoweredByFollowingCoalesce($next, $ops, $j)) {
                continue;
            }

            return false;
        }

        return false;
    }

    private function arrayDimFetchConsumesPriorResult(
        Op\Expr\ArrayDimFetch $consumer,
        Op\Expr\ArrayDimFetch $producer
    ): bool {
        $var = $consumer->var;
        if ($var === $producer || $var === $producer->result) {
            return true;
        }
        while ($var instanceof Temporary) {
            if ($var === $producer->result) {
                return true;
            }
            if (null === $var->original) {
                break;
            }
            $var = $var->original;
        }

        return $var === $producer->result;
    }

    /**
     * Outermost-first ArrayDimFetch chain for isset()/empty() nested dims (#21991).
     *
     * @return list<Op\Expr\ArrayDimFetch>
     */
    protected function collectArrayDimFetchChain(Op\Expr\ArrayDimFetch $innermost, Block $block): array
    {
        $chain = [$innermost];
        $seen = [spl_object_id($innermost) => true];
        $var = $innermost->var;
        while (true) {
            $prev = $this->findCoalesceArrayDimFetch($var, $block);
            if (null === $prev || isset($seen[spl_object_id($prev)])) {
                break;
            }
            $seen[spl_object_id($prev)] = true;
            array_unshift($chain, $prev);
            $var = $prev->var;
        }

        return $chain;
    }

    /**
     * Quiet FETCH_DIM_IS for all but the last dim in an isset()/empty() chain (#21991).
     *
     * @param list<Op\Expr\ArrayDimFetch> $chain outermost first
     * @return array{0: list<OpCode>, 1: int} prefix opcodes + container slot for the final dim
     */
    private function emitQuietDimFetchChainPrefix(array $chain, Block $block): array
    {
        $first = $chain[0];
        $containerSlot = $this->compileOperand($first->var, $block, true);
        if (count($chain) < 2) {
            return [[], $containerSlot];
        }
        $opcodes = [];
        $prefixLen = count($chain) - 1;
        for ($i = 0; $i < $prefixLen; ++$i) {
            $fetch = $chain[$i];
            $this->rejectArrayEmptyOffsetRead($fetch, $block);
            $resultSlot = $this->compileOperand($fetch->result, $block, false);
            $dimSlot = null !== $fetch->dim
                ? $this->compileOperand($fetch->dim, $block, true)
                : null;
            $op = new OpCode(OpCode::TYPE_ARRAY_DIM_FETCH, $resultSlot, $containerSlot, $dimSlot);
            $op->arrayDimFetchIs = true;
            $opcodes[] = $op;
            $containerSlot = $resultSlot;
        }

        return [$opcodes, $containerSlot];
    }

    /**
     * php-cfg emits ArrayDimFetch as its own stmt before Terminal_Unset; skip duplicate lowering.
     */
    private function isArrayDimFetchOnlyUnsetVar(
        Op\Expr\ArrayDimFetch $fetch,
        Op $next
    ): bool {
        if (!$next instanceof Op\Terminal\Unset_) {
            return false;
        }
        foreach ($next->exprs as $var) {
            if ($var === $fetch) {
                return true;
            }
            $target = $var;
            while ($target instanceof Temporary) {
                if ($target === $fetch->result) {
                    return true;
                }
                if (null === $target->original) {
                    break;
                }
                $target = $target->original;
            }
            if ($target === $fetch->result) {
                return true;
            }
        }

        return false;
    }

