        return $target === $fetch->result;
    }

    private function staticPropertyFetchResultFeedsEmpty(Op\Expr\StaticPropertyFetch $fetch, ?Op $next): bool
    {
        if (!$next instanceof Op\Expr\Empty_) {
            return false;
        }
        $target = $next->expr;
        if ($target === $fetch || $target === $fetch->result) {
            return true;
