    /**
     * 0-based ordinal among hoisted sibling call-arg producers, skipping isset/empty preludes (#15646).
     *
     * @param list<Op> $cfgChildren
     */
    private function hoistedSiblingCallArgProducerOrdinal(
        int $producerIndex,
        int $firstSibling,
        int $consumerIndex,
        array $cfgChildren
    ): int {
        $ordinal = 0;
        for ($j = $firstSibling; $j < $consumerIndex; ++$j) {
            if ($j === $producerIndex) {
                return $ordinal;
            }
            $stmt = $cfgChildren[$j] ?? null;
            if (!$stmt instanceof Op\Expr || !$this->isInlineExprCallArgProducer($stmt)) {
                continue;
            }
            if ($this->isIssetOrEmptyInlineCallArgPreludeStmt($stmt, $j, $cfgChildren)) {
                continue;
            }
            ++$ordinal;
        }

        return $ordinal;
    }

    private function isPropertyFetchOnlyEmptyVar(
        Op\Expr\PropertyFetch $fetch,
        Op $next,
        Block $block
    ): bool {
        if ($next instanceof Op\Expr\Empty_) {
            $target = $next->expr;
            if ($target === $fetch || $target === $fetch->result) {
                return true;
            }
            while ($target instanceof Temporary) {
                if ($target === $fetch->result) {
                    return true;
                }
                if (null === $target->original) {
                    break;
                }
                $target = $target->original;
            }
            if ($target === $fetch->result) {
                return true;
            }

            return $this->findCoalescePropertyFetch($target, $block) === $fetch;
        }
        if ($this->isInlineExprCallArgConsumer($next)) {
            return $this->funcCallHasEmptyArgUsingPropertyFetch($next, $fetch, $block);
        }

        return false;
    }

    private function isStaticPropertyFetchOnlyEmptyVar(
        Op\Expr\StaticPropertyFetch $fetch,
        Op $next,
        Block $block
    ): bool {
        if ($next instanceof Op\Expr\Empty_) {
            $target = $next->expr;
            if ($target === $fetch || $target === $fetch->result) {
                return true;
            }
            while ($target instanceof Temporary) {
                if ($target === $fetch->result) {
                    return true;
                }
                if (null === $target->original) {
                    break;
                }
                $target = $target->original;
            }
            if ($target === $fetch->result) {
                return true;
            }

            return $this->findCoalesceStaticPropertyFetch($target, $block) === $fetch;
        }
        if ($this->isInlineExprCallArgConsumer($next)) {
            return $this->funcCallHasEmptyArgUsingStaticPropertyFetch($next, $fetch, $block);
        }

        return false;
    }

    private function funcCallHasEmptyArgUsingPropertyFetch(Op $call, Op\Expr\PropertyFetch $fetch, Block $block): bool
    {
        if (!property_exists($call, 'args') || !is_array($call->args)) {
            return false;
        }
        foreach ($call->args as $arg) {
            if (!$arg instanceof Operand\Temporary || !$arg->original instanceof Op\Expr\Empty_) {
                continue;
            }
            if ($this->emptyExprDependsOnOperand($arg->original, $fetch->result, $block)) {
                return true;
            }
        }

        return false;
    }

    private function funcCallHasEmptyArgUsingStaticPropertyFetch(
        Op $call,
        Op\Expr\StaticPropertyFetch $fetch,
        Block $block
    ): bool {
        if (!property_exists($call, 'args') || !is_array($call->args)) {
            return false;
        }
        foreach ($call->args as $arg) {
            if (!$arg instanceof Operand\Temporary || !$arg->original instanceof Op\Expr\Empty_) {
                continue;
            }
            if ($this->emptyExprDependsOnOperand($arg->original, $fetch->result, $block)) {
                return true;
            }
        }

        return false;
    }

    /**
     * php-cfg emits ArrayDimFetch as its own stmt before Empty_; skip duplicate lowering (#5307).
     */
    private function isArrayDimFetchOnlyEmptyVar(
        Op\Expr\ArrayDimFetch $fetch,
        Op $next,
        Block $block
    ): bool {
        if (!$next instanceof Op\Expr\Empty_) {
            return false;
        }
        $target = $next->expr;
        if ($target === $fetch || $target === $fetch->result) {
            return true;
        }
        while ($target instanceof Temporary) {
            if ($target === $fetch->result) {
                return true;
            }
            if (null === $target->original) {
                break;
            }
            $target = $target->original;
        }
        if ($target === $fetch->result) {
            return true;
        }

        return $this->findCoalesceArrayDimFetch($target, $block) === $fetch;
    }

    /**
     * @return list<Op\Expr\NullsafePropertyFetch>
     */
    protected function collectNullsafePropertyFetchChain(?Operand $operand, Block $block): array
    {
        $innermost = $this->findNullsafePropertyFetch($operand, $block);
        if (null === $innermost) {
            return [];
        }
        $chain = [$innermost];
        $var = $innermost->var;
        while (true) {
            $prev = $this->findNullsafePropertyFetchProducing($var, $block);
            if (null === $prev) {
                break;
            }
            array_unshift($chain, $prev);
            $var = $prev->var;
        }

        return $chain;
    }

    /**
     * @return list<Op\Expr\NullsafePropertyFetch>
     */
    protected function collectNullsafePropertyFetchChainForEmpty(Op\Expr\Empty_ $expr, Block $block): array
    {
        $operand = $this->unaryExprOperandForRead($expr, $block);
        if (null === $operand) {
            return [];
        }

        return $this->collectNullsafePropertyFetchChain($operand, $block);
    }

    /**
     * @return ?Op\Expr\NullsafePropertyFetch
     */
    protected function findNullsafePropertyFetch(?Operand $operand, Block $block): ?Op\Expr\NullsafePropertyFetch
    {
        if (null === $operand) {
            return null;
        }
        $candidates = [$operand];
        $seen = [];
        while ([] !== $candidates) {
            $current = array_shift($candidates);
            if (isset($seen[spl_object_id($current)])) {
                continue;
            }
            $seen[spl_object_id($current)] = true;
            foreach ($block->orig->children as $child) {
                if ($child instanceof Op\Expr\NullsafePropertyFetch && $child->result === $current) {
                    return $child;
                }
            }
            if ($current instanceof Temporary && null !== $current->original) {
                $candidates[] = $current->original;
            }
        }

        return null;
    }

    /**
     * @return ?Op\Expr\NullsafePropertyFetch
     */
    protected function findNullsafePropertyFetchProducing(?Operand $operand, Block $block): ?Op\Expr\NullsafePropertyFetch
    {
        if (null === $operand) {
            return null;
        }
        foreach ($block->orig->children as $child) {
            if ($child instanceof Op\Expr\NullsafePropertyFetch && $child->result === $operand) {
                return $child;
            }
        }
        if ($operand instanceof Temporary && null !== $operand->original) {
            return $this->findNullsafePropertyFetchProducing($operand->original, $block);
        }

        return null;
    }

    /**
     * php-cfg Temporary.original is often null; locate NullsafeMethodCall by result operand (#19591).
     *
     * @return ?Op\Expr\NullsafeMethodCall
     */
    protected function findNullsafeMethodCallProducing(?Operand $operand, Block $block): ?Op\Expr\NullsafeMethodCall
    {
        if (null === $operand || null === $block->orig) {
            return null;
        }
        foreach ($block->orig->children as $child) {
            if (
                $child instanceof Op\Expr\NullsafeMethodCall
                && (
                    $child->result === $operand
                    || $this->operandsChainEqual($child->result, $operand)
                )
            ) {
                return $child;
            }
        }
        if ($operand instanceof Temporary && null !== $operand->original) {
            if ($operand->original instanceof Op\Expr\NullsafeMethodCall) {
                return $operand->original;
            }

            return $this->findNullsafeMethodCallProducing($operand->original, $block);
        }

        return null;
    }

    /**
     * @param Op[] $ops
     */
    protected function shouldSkipNullsafePropertyFetchForIssetOrEmpty(
        Op\Expr\NullsafePropertyFetch $fetch,
        array $ops,
        int $index,
        Block $block
    ): bool {
        for ($j = $index + 1, $count = count($ops); $j < $count; ++$j) {
            $next = $ops[$j];
            if ($next instanceof Op\Expr\NullsafePropertyFetch) {
                continue;
            }
            if ($next instanceof Op\Expr\Isset_ && 1 === count($next->vars)) {
                $chain = $this->collectNullsafePropertyFetchChain($next->vars[0], $block);

                return [] !== $chain && in_array($fetch, $chain, true);
            }
            if ($next instanceof Op\Expr\Empty_) {
                $chain = $this->collectNullsafePropertyFetchChainForEmpty($next, $block);

                return [] !== $chain && in_array($fetch, $chain, true);
            }

            return false;
        }

        return false;
    }

    /**
     * @param Op[] $ops
     */
    protected function shouldSkipNullsafePropertyFetchForCoalesce(
        Op\Expr\NullsafePropertyFetch $fetch,
        array $ops,
        int $index,
        Block $block
    ): bool {
        for ($j = $index + 1, $count = count($ops); $j < $count; ++$j) {
            $next = $ops[$j];
            if ($next instanceof Op\Expr\NullsafePropertyFetch) {
                continue;
            }
            if ($next instanceof Op\Expr\BinaryOp\Coalesce) {
                $chain = $this->collectNullsafePropertyFetchChain($next->left, $block);

                return [] !== $chain && in_array($fetch, $chain, true);
            }

            return false;
        }

        return false;
    }

    /**
     * Defer $a->b?->m() when it feeds a following ?? so coalesce can continue on the
     * nullsafe merge block (#19591).
     *
     * @param Op[] $ops
     */
    protected function shouldSkipNullsafeMethodCallForCoalesce(
        Op\Expr\NullsafeMethodCall $call,
        array $ops,
        int $index,
        Block $block
    ): bool {
        for ($j = $index + 1, $count = count($ops); $j < $count; ++$j) {
            $next = $ops[$j];
            if ($next instanceof Op\Expr\BinaryOp\Coalesce) {
                return $this->operandsChainEqual($next->left, $call->result)
                    || $next->left === $call->result;
            }
            if ($next instanceof Op\Expr\NullsafePropertyFetch || $next instanceof Op\Expr\NullsafeMethodCall) {
                continue;
            }

            return false;
        }

        return false;
    }

    /**
     * php-cfg lowers $a->b?->v as PropertyFetch then NullsafePropertyFetch — skip eager fetch (#16637).
     *
     * @param Op[] $ops
     */
    private function isPropertyFetchNullsafeReceiver(
        Op\Expr\PropertyFetch $fetch,
        array $ops,
        int $index
    ): bool {
        if ($index + 1 >= count($ops)) {
            return false;
        }
        $next = $ops[$index + 1];

        if (
            $next instanceof Op\Expr\NullsafePropertyFetch
            && $this->operandsChainEqual($next->var, $fetch->result)
        ) {
            return true;
        }

        // $a->b?->m() — receiver fetch is emitted inside compileNullsafeMethodCall / coalesce (#19591).
        return $next instanceof Op\Expr\NullsafeMethodCall
            && $this->operandsChainEqual($next->var, $fetch->result);
    }

    private function isPropertyWriteAssign(Op\Expr\Assign $assign, Block $block): bool
    {
        if (null !== $this->unwrapPropertyFetch($assign->var)
            || null !== $this->findCoalescePropertyFetch($assign->var, $block)) {
            return true;
        }

        return null !== $this->unwrapStaticPropertyFetch($assign->var)
            || null !== $this->findStaticPropertyFetchForAssign($assign->var, $block);
    }

    /** While-loop ?: merge must not steal array-append write slots (#10702). */
    private function isArrayDimWriteAssign(Op\Expr\Assign $assign, Block $block): bool
    {
        if (null !== $this->unwrapArrayDimFetch($assign->var)) {
            return true;
        }

        return null !== $this->findArrayDimFetchForResult($assign->var, $block);
    }

    private function isPropertyFetchOnlyAssignVar(
        Op\Expr\PropertyFetch $fetch,
        Op $next
    ): bool {
        if (!$next instanceof Op\Expr\Assign) {
            return false;
        }
        $var = $next->var;
        if ($var === $fetch || $var === $fetch->result) {
            return true;
        }
        while ($var instanceof Temporary) {
            if ($var === $fetch->result || $var->original === $fetch) {
                return true;
            }
            if (null === $var->original) {
                break;
            }
            $var = $var->original;
        }

        return $var === $fetch->result;
    }

    /**
     * `[&$obj->hook]` — php-cfg emits PropertyFetch then Expr_Array; eager read fetch breaks ref (#17353).
     */
    private function isPropertyFetchLoweredByFollowingArrayLiteralByRefElement(
        Op\Expr\PropertyFetch $fetch,
        Op $next
    ): bool {
        if (!$next instanceof Op\Expr\Array_) {
            return false;
        }

        return $this->arrayLiteralHasByRefElementOperand($next, $fetch->result);
    }

    private function arrayLiteralHasByRefElementOperand(Op\Expr\Array_ $array, Operand $target): bool
    {
        $byRefFlags = property_exists($array, 'byRef') ? $array->byRef : [];
        foreach ($array->values as $i => $value) {
            if (empty($byRefFlags[$i])) {
                continue;
            }
            if ($value === $target) {
                return true;
            }
            $cursor = $value;
            while ($cursor instanceof Temporary) {
                if ($cursor === $target) {
                    return true;
                }
                if (null === $cursor->original) {
                    break;
                }
                $cursor = $cursor->original;
            }
        }

        return false;
    }

    private function isPropertyFetchOnlyUnsetVar(
        Op\Expr\PropertyFetch $fetch,
        Op $next
    ): bool {
        if (!$next instanceof Op\Terminal\Unset_) {
            return false;
        }
        foreach ($next->exprs as $var) {
            if ($var === $fetch) {
                return true;
            }
            $target = $var;
            while ($target instanceof Temporary) {
                if ($target === $fetch->result) {
                    return true;
                }
                if (null === $target->original) {
                    break;
                }
                $target = $target->original;
            }
            if ($target === $fetch->result) {
                return true;
            }
        }

        return false;
    }

    /**
     * @return array{0: int, 1: ?int, 2: bool}
     */
    protected function resolveUnsetTarget($expr, Block $block): array
    {
        if ($expr instanceof Op\Expr\ArrayDimFetch) {
            [$containerSlot, $dimSlot] = $this->resolveIssetTargetFromArrayDimFetch($expr, $block);

            return [$containerSlot, $dimSlot, false];
        }
        if ($expr instanceof Op\Expr\PropertyFetch) {
            return [
                $this->compileOperand($expr->var, $block, true),
                $this->compileOperand($expr->name, $block, true),
                true,
            ];
        }
        if ($expr instanceof Op\Expr\StaticPropertyFetch) {
            $this->throwCompileLogic(
                'StaticPropertyFetch unset must be lowered via TYPE_STATIC_PROPERTY_UNSET (#2256)'
            );
        }
        if ($expr instanceof Operand) {
            $dimFetch = $this->findCoalesceArrayDimFetch($expr, $block);
            if (null !== $dimFetch) {
                [$containerSlot, $dimSlot] = $this->resolveIssetTargetFromArrayDimFetch($dimFetch, $block);

                return [$containerSlot, $dimSlot, false];
            }
            foreach ($block->orig->children as $child) {
                if ($child instanceof Op\Expr\PropertyFetch && $child->result === $expr) {
                    return [
                        $this->compileOperand($child->var, $block, true),
                        $this->compileOperand($child->name, $block, true),
                        true,
                    ];
                }
            }
            [$containerSlot, $dimSlot] = $this->resolveIssetTarget($expr, $block);

            return [$containerSlot, $dimSlot, false];
        }

        $this->throwCompileLogic('Unsupported unset target: ' . (is_object($expr) ? $expr->getType() : gettype($expr)));
    }

    protected function compileInterface(Op\Stmt\Interface_ $iface, Block $block): OpCode
    {
        $name = $this->staticNameFromOperand($iface->name);
        if (null === $name) {
            $this->throwCompileError('Interface name must be a compile-time class reference');
        }
        $extends = $this->interfaceNamesFromOperands($iface->extends);
        $this->classCompileRegistry->registerInterface($name, $extends, $iface->stmts);

        $return = new OpCode(
            OpCode::TYPE_DECLARE_INTERFACE,
            $this->compileOperand($iface->name, $block, true)
        );
        $this->assignAttributeMetadata($return, $iface);
        AttributeNames::assertOverrideMethodTargetOnly($return->attributeNames, 'class', $return->attributeEntries);
        AttributeNames::assertCompileTimeConstTargetOnly($return->attributeNames, 'class', $return->attributeEntries);
        AttributeNames::assertSensitiveParameterParamTargetOnly($return->attributeNames, 'class', $return->attributeEntries);
        AttributeNames::assertReturnTypeWillChangeMethodTargetOnly($return->attributeNames, 'class', $return->attributeEntries);
        AttributeNames::assertDeprecatedTargetAllowed($return->attributeNames, 'class', $return->attributeEntries);
        $return->deprecatedMetadata = DeprecatedMetadata::fromOp($iface);
        AttributeNames::assertDeprecatedAllowedOnClassLike(
            $return->attributeNames,
            $return->deprecatedMetadata,
            'interface',
            $name,
            $return->attributeEntries
        );
        AttributeNames::assertAttributeMetaOnConcreteClassLike(
            $return->attributeEntries,
            'interface',
            $name
        );
        $this->registerAttributeClassFromEntries($name, $return->attributeEntries);
        $return->classImplements = $extends;
        $this->applySealedMetadataFromOp($iface, $return);
        $return->block1 = $this->compileClassBody(
            $iface->stmts,
            OpCode::TYPE_DECLARE_INTERFACE,
            $this->staticNameFromOperand($iface->name)
        );

        return $return;
    }

    protected function compileTrait(Op\Stmt\Trait_ $trait, Block $block): OpCode
    {
        $name = $this->staticNameFromOperand($trait->name);
        if (null === $name) {
            $this->throwCompileError('Trait name must be a compile-time class reference');
        }
        $this->classCompileRegistry->registerTrait($name, $trait->stmts);

        $return = new OpCode(
            OpCode::TYPE_DECLARE_TRAIT,
            $this->compileOperand($trait->name, $block, true)
        );
        $this->assignAttributeMetadata($return, $trait);
        AttributeNames::assertOverrideMethodTargetOnly($return->attributeNames, 'class', $return->attributeEntries);
        AttributeNames::assertCompileTimeConstTargetOnly($return->attributeNames, 'class', $return->attributeEntries);
        AttributeNames::assertSensitiveParameterParamTargetOnly($return->attributeNames, 'class', $return->attributeEntries);
        AttributeNames::assertReturnTypeWillChangeMethodTargetOnly($return->attributeNames, 'class', $return->attributeEntries);
        AttributeNames::assertDeprecatedTargetAllowed($return->attributeNames, 'class', $return->attributeEntries);
        $return->deprecatedMetadata = DeprecatedMetadata::fromOp($trait);
        AttributeNames::assertDeprecatedAllowedOnClassLike(
            $return->attributeNames,
            $return->deprecatedMetadata,
            'trait',
            $name,
            $return->attributeEntries
        );
        AttributeNames::assertAttributeMetaOnConcreteClassLike(
            $return->attributeEntries,
            'trait',
            $name
        );
        $this->registerAttributeClassFromEntries($name, $return->attributeEntries);
        $traitLc = strtolower(ltrim($name, '\\'));
        $this->compiledClassStaticProperties[$traitLc] = $this->compiledClassStaticProperties[$traitLc] ?? [];
        $prevClassStaticCompile = $this->currentClassStaticPropertyCompile;
        $this->currentClassStaticPropertyCompile = $traitLc;
        $return->block1 = $this->compileClassBody(
            $trait->stmts,
            OpCode::TYPE_DECLARE_TRAIT,
            $this->staticNameFromOperand($trait->name)
        );
        $this->currentClassStaticPropertyCompile = $prevClassStaticCompile;

        return $return;
    }

    protected function compileEnum(Op\Stmt\Enum_ $enum, Block $block): OpCode
    {
        $backedTypeSlot = null;
        if (null !== $enum->backedType && $enum->backedType instanceof Op\Type\Literal) {
            $backedVar = new Variable(Variable::TYPE_STRING);
            $backedVar->string($enum->backedType->name);
            $backedOperand = new Operand\Temporary;
            $backedOperand->type = Type::string();
            $backedTypeSlot = $block->registerConstant($backedOperand, $backedVar);
        }
        $return = new OpCode(
            OpCode::TYPE_DECLARE_ENUM,
            $this->compileOperand($enum->name, $block, true),
            $backedTypeSlot
        );
        $this->assignAttributeMetadata($return, $enum);
        $this->assignSourceMetadata($return, $enum);
        $return->deprecatedMetadata = DeprecatedMetadata::fromOp($enum);
        AttributeNames::assertOverrideMethodTargetOnly($return->attributeNames, 'class', $return->attributeEntries);
        AttributeNames::assertCompileTimeConstTargetOnly($return->attributeNames, 'class', $return->attributeEntries);
        AttributeNames::assertSensitiveParameterParamTargetOnly($return->attributeNames, 'class', $return->attributeEntries);
        AttributeNames::assertReturnTypeWillChangeMethodTargetOnly($return->attributeNames, 'class', $return->attributeEntries);
        AttributeNames::assertDeprecatedTargetAllowed($return->attributeNames, 'class', $return->attributeEntries);
        $enumName = $this->staticNameFromOperand($enum->name);
        if (null !== $enumName) {
            AttributeNames::assertDeprecatedAllowedOnClassLike(
                $return->attributeNames,
                $return->deprecatedMetadata,
                'enum',
                $enumName,
                $return->attributeEntries
            );
            AttributeNames::assertAllowDynamicPropertiesNotOnEnum($return->attributeNames, $enumName);
            AttributeNames::assertAttributeMetaOnConcreteClassLike(
                $return->attributeEntries,
                'enum',
                $enumName
            );
            $this->registerAttributeClassFromEntries($enumName, $return->attributeEntries);
        }
        [$enumIfaceLcs, $enumIfaceDisplays] = $this->interfaceLcAndDisplayFromOperands($enum->implements);
        $return->classImplements = $enumIfaceLcs;
        $return->classImplementsDisplay = $enumIfaceDisplays;
        $return->classIsAbstract = VM\ClassAbstract::fromClassFlags($enum->flags ?? 0);
        if (null !== $enumName) {
            $enumLc = strtolower(ltrim($enumName, '\\'));
            $backedTypeName = null;
            if (null !== $enum->backedType && $enum->backedType instanceof Op\Type\Literal) {
                $backedTypeName = $enum->backedType->name;
            }
            $this->compileTimeEnumBackedTypes[$enumLc] = $backedTypeName;
        }
        $return->block1 = $this->compileEnumBody($enum->stmts, $enumName);

        return $return;
    }

    protected function compileEnumBody(CfgBlock $block, ?string $enumName = null): Block
    {
        $result = new Block($block);
        $prevClassLc = $this->compilingClassLc;
        $prevClassDisplayName = $this->compilingClassDisplayName;
        $prevInstancePropertyNames = $this->compilingClassInstancePropertyNames;
        $prevMethodNames = $this->compilingClassMethodNames;
        $this->compilingClassInstancePropertyNames = [];
        $this->compilingClassMethodNames = [];
        if (null !== $enumName) {
            $this->compilingClassLc = strtolower(ltrim($enumName, '\\'));
            $this->compilingClassDisplayName = ltrim($enumName, '\\');
            if (!isset($this->compileTimeClassConsts[$this->compilingClassLc])) {
                $this->compileTimeClassConsts[$this->compilingClassLc] = [];
            }
            if (!isset($this->compileTimeClassConstVisibility[$this->compilingClassLc])) {
                $this->compileTimeClassConstVisibility[$this->compilingClassLc] = [];
            }
            if (!isset($this->compileTimeClassConstDeprecated[$this->compilingClassLc])) {
                $this->compileTimeClassConstDeprecated[$this->compilingClassLc] = [];
            }
            if (!isset($this->compileTimeEnumBackedTypes[$this->compilingClassLc])) {
                $this->compileTimeEnumBackedTypes[$this->compilingClassLc] = null;
            }
            if (!isset($this->compileTimeEnumCaseConstNames[$this->compilingClassLc])) {
                $this->compileTimeEnumCaseConstNames[$this->compilingClassLc] = [];
            }
        } else {
            $this->compilingClassDisplayName = null;
        }
        foreach ($block->children as $child) {
            if ($child instanceof Op\Terminal\Const_) {
                $this->compileClassConstDeclaration($child, $result);
                continue;
            }
            if ($child instanceof Op\Stmt\TraitUse) {
                foreach ($child->traits as $traitOperand) {
                    $result->addOpCode(new OpCode(
                        OpCode::TYPE_USE_TRAIT,
                        $this->compileOperand($traitOperand, $result, true)
                    ));
                }
                $adaptOp = new OpCode(OpCode::TYPE_TRAIT_USE_ADAPTATION);
                $adaptOp->traitAdaptations = [] !== $child->adaptations
                    ? $this->compileTraitAdaptations($child->adaptations)
                    : [];
                $result->addOpCode($adaptOp);
                continue;
            }
            if ($child instanceof Op\Stmt\ClassMethod) {
                $this->compileClassMethodDeclaration($child, $result);

                continue;
            }
            $this->throwCompileLogic('Unsupported enum body element: '.get_class($child));
        }
        $this->compilingClassLc = $prevClassLc;
        $this->compilingClassDisplayName = $prevClassDisplayName;
        $this->compilingClassInstancePropertyNames = $prevInstancePropertyNames;
        $this->compilingClassMethodNames = $prevMethodNames;

        return $result;
    }

    protected function compileClassMethodDeclaration(Op\Stmt\ClassMethod $child, Block $result, ?int $declaringType = null): void
    {
        $this->registerMethodDeclaration($child->func->name);
        // php-src Zend/zend_compile.c — duplicate params fatal before property promotion
        // registers (`Redefinition of parameter $name`, not `Cannot redeclare Class::$name`) (#29979).
        $this->assertNoDuplicateParameterNames($child->func->params);
        foreach ($child->func->params as $param) {
            $methodBlock = new Block(null);
            $methodBlock->func = $child->func;
            $this->assertParamDeclaredType($param->declaredType, $methodBlock, $child->func);
        }
        if ('__construct' === $child->func->name) {
            // php-src Zend/zend_compile.c — promotion requires a concrete constructor body (#26529).
            $abstractCtor = OpCode::TYPE_DECLARE_INTERFACE === $declaringType
                || 0 !== ($child->func->flags & CfgFunc::FLAG_ABSTRACT);
            foreach ($child->func->params as $param) {
                if ($this->isPromotedParam($param)) {
                    if ($abstractCtor) {
                        $sourceFile = $child->getFile();
                        if ('' === $sourceFile) {
                            $sourceFile = 'unknown';
                        }
                        throw new CompileFatal(
                            $sourceFile,
                            max(1, $child->getLine()),
                            AbstractPromotedPropertyCompileCheck::MESSAGE
                        );
                    }
                    $this->compilePromotedPropertyDeclaration($param, $result);
                }
            }
        }
        $methodName = new Operand\Literal($child->func->name);
        $methodName->type = Type::string();
        $visVar = new Variable(Variable::TYPE_INTEGER);
        $visFlags = MethodVisibility::mask($child->func->flags);
        if (($child->func->flags & \PHPCfg\Func::FLAG_STATIC) !== 0) {
            $visFlags |= \PHPCfg\Func::FLAG_STATIC;
        }
        if (($child->func->flags & CfgFunc::FLAG_FINAL) !== 0) {
            $visFlags |= CfgFunc::FLAG_FINAL;
        }
        $visVar->int($visFlags);
        $visOperand = new Operand\Temporary;
        $visOperand->type = Type::int();
        $visIdx = $result->registerConstant($visOperand, $visVar);
        $methodLine = max(0, $child->getLine());
        $declare = new OpCode(
            OpCode::TYPE_DECLARE_METHOD,
            $this->compileOperand($methodName, $result, true),
            $methodLine > 0 ? $methodLine : null,
            $visIdx
        );
        if (null !== $child->func->cfg) {
            $methodBlock = $this->compileCfgBlock($child->func->cfg, $child->func->params, $child->func);
            NoDiscardMetadata::applyToBlock($methodBlock, $child);
            DeprecatedMetadata::applyToBlock($methodBlock, $child);
            $this->markGeneratorIfNeeded($child, $methodBlock);
            $declare->block1 = $methodBlock;
        }
        // null cfg: abstract / interface methods — NonAbstractMethodBodyCheck rejects
        // non-abstract class/trait/enum `function f();` (#24906). Empty `{}` has cfg.
        $this->assignAttributeMetadata($declare, $child);
        $this->assignSourceMetadata($declare, $child);
        AttributeNames::assertAllowDynamicPropertiesClassTargetOnly($declare->attributeNames, 'method', $declare->attributeEntries);
        AttributeNames::assertAttributeMetaClassTargetOnly($declare->attributeNames, 'method', $declare->attributeEntries);
        AttributeNames::assertCompileTimeConstTargetOnly($declare->attributeNames, 'method', $declare->attributeEntries);
        AttributeNames::assertSensitiveParameterParamTargetOnly($declare->attributeNames, 'method', $declare->attributeEntries);
        AttributeNames::assertReturnTypeWillChangeMethodTargetOnly($declare->attributeNames, 'method', $declare->attributeEntries);
        AttributeNames::assertDeprecatedTargetAllowed($declare->attributeNames, 'method', $declare->attributeEntries);
        $declare->parameterMetadata = $this->parameterMetadataFromParams($child->func->params, $child->func);
        // Abstract/interface methods have no method body block — keep return AST for cross-file LSP (#25384).
        // Untyped `__toString` is `: string` for Reflection / LSP (zend_compile.c, #26402).
        $declare->returnDeclaredType = $this->implicitToStringReturnType($child->func)
            ?? $child->func->returnType;
        $declare->deprecatedMetadata = DeprecatedMetadata::fromOp($child);
        $result->addOpCode($declare);
    }

    /**
     * @param list<Op\Expr\Param> $params
     *
     * @return list<ParameterMetadata>
     */
    protected function parameterMetadataFromParams(array $params, ?CfgFunc $func = null): array
    {
        return AttributeConstantEvaluator::withUserlandConstContext(
            $this->userlandConstScalarsForAttributes(),
            $this->namespaceHintFromFunc($func),
            function () use ($params): array {
                $metadata = [];
                foreach ($params as $param) {
                    if (!($param->name instanceof Operand\Literal) || !is_string($param->name->value)) {
                        continue;
                    }
                    $isVariadic = (bool) $param->variadic;
                    $hasDefault = null !== $param->defaultVar || null !== $param->defaultBlock;
                    $metadata[] = new ParameterMetadata(
                        $param->name->value,
                        AttributeMetadata::fromOp($param),
                        $this->isPromotedParam($param),
                        $isVariadic || $hasDefault,
                        $isVariadic,
                        (bool) $param->byRef,
                        $this->parameterTypeStringForDump($param),
                        $this->parameterDefaultExportForDump($param),
                    );
                }

                return $metadata;
            }
        );
    }

    /**
     * Zend _function_string / parameter dump type label (#22522).
     *
     * Implicit nullable (`string $s = null`) dumps as `?string` for Reflection metadata (#26469).
     */
    protected function parameterTypeStringForDump(Op\Expr\Param $param): ?string
    {
        $type = $param->declaredType ?? null;
        if (null === $type || $type instanceof Op\Type\Mixed_) {
            return null;
        }
        if (
            !($type instanceof Op\Type\Nullable)
            && !$this->cfgTypeUsesDnfShape($type)
            && $this->paramAstDefaultIsNull($param)
        ) {
            $type = new Op\Type\Nullable($type);
        }

        return ReflectionTypeSupport::cfgTypeStringForDump($type);
    }

    /** AST-side `= null` default (literal null / null const) for Reflection dump labels (#26469). */
    protected function paramAstDefaultIsNull(Op\Expr\Param $param): bool
    {
        if ($param->defaultVar instanceof NullOperand) {
            return true;
        }
        if (null === $param->defaultVar) {
            return false;
        }
        $unwrapped = $this->unwrapOperandChain($param->defaultVar);
        if ($unwrapped instanceof Op\Expr\ConstFetch) {
            $name = $this->staticNameFromOperand($unwrapped->name);
            if (null !== $name && 'null' === strtolower(ltrim($name, '\\'))) {
                return true;
            }
        }
        $vm = $this->vmVariableFromCfgLiteralOperand($param->defaultVar);

        return null !== $vm && Variable::TYPE_NULL === $vm->type;
    }

    /**
     * Zend parameter default literal for Reflection*::__toString (#22522).
     */
    protected function parameterDefaultExportForDump(Op\Expr\Param $param): ?string
    {
        if ($param->variadic || (null === $param->defaultVar && null === $param->defaultBlock)) {
            return null;
        }
        if ($param->defaultVar instanceof NullOperand) {
            return 'NULL';
        }
        if (null === $param->defaultVar) {
            return null;
        }
        $vm = $this->vmVariableFromCfgLiteralOperand($param->defaultVar);
        if (null === $vm) {
            $unwrapped = $this->unwrapOperandChain($param->defaultVar);
            if ($unwrapped instanceof Op\Expr\ConstFetch) {
                $name = $this->staticNameFromOperand($unwrapped->name);
                if (null !== $name) {
                    $lc = strtolower(ltrim($name, '\\'));
                    if ('null' === $lc) {
                        return 'NULL';
                    }
                    if ('true' === $lc) {
                        return 'true';
                    }
                    if ('false' === $lc) {
                        return 'false';
                    }
                }
            }

            return null;
        }
        $vm = $vm->resolveIndirect();
        switch ($vm->type) {
            case Variable::TYPE_NULL:
                return 'NULL';
            case Variable::TYPE_BOOLEAN:
                return $vm->toBool() ? 'true' : 'false';
            case Variable::TYPE_INTEGER:
                return (string) $vm->toInt();
            case Variable::TYPE_FLOAT:
                return (string) $vm->toFloat();
            case Variable::TYPE_STRING:
                return var_export($vm->toString(), true);
            default:
                return null;
        }
    }

    protected function assignAttributeMetadata(OpCode $op, Op $cfgOp): void
    {
        $entries = AttributeConstantEvaluator::withUserlandConstContext(
            $this->userlandConstScalarsForAttributes(),
            $this->namespaceHintFromCfgOp($cfgOp),
            static fn (): array => AttributeMetadata::fromOp($cfgOp)
        );
        $op->attributeEntries = AttributeNames::validateDuplicates($entries, $this->attributeClassRegistry);
        $op->attributeNames = AttributeEntry::namesFromList($op->attributeEntries);
    }

    /**
     * Scalar map of file/namespace consts for attribute ConstFetch folding (#26628).
     *
     * @return array<string, mixed>
     */
    private function userlandConstScalarsForAttributes(): array
    {
        $out = [];
        foreach ($this->compileTimeGlobalConsts as $lc => $var) {
            try {
                $out[$lc] = AttributeConstantEvaluator::phpScalarFromVariable($var);
            } catch (\LogicException $e) {
                // Non-scalar compile-time values cannot appear in attribute args.
            }
        }

        return $out;
    }

    /** Declaring namespace for relative ConstFetch in attribute args (#26628). */
    private function namespaceHintFromCfgOp(Op $cfgOp): string
    {
        if ($cfgOp instanceof Op\Stmt\Function_) {
            return $this->namespaceHintFromFunc($cfgOp->func);
        }
        if ($cfgOp instanceof Op\Stmt\ClassMethod) {
            return $this->namespaceHintFromFunc($cfgOp->func);
        }
        if ($cfgOp instanceof Op\Stmt\ClassLike) {
            $name = $this->staticNameFromOperand($cfgOp->name);

            return null !== $name ? $this->namespaceFromFqcn($name) : '';
        }
        if ($cfgOp instanceof Op\Terminal\Const_) {
            $name = $this->staticNameFromOperand($cfgOp->name);

            return null !== $name ? $this->namespaceFromFqcn($name) : '';
        }
        if ($cfgOp instanceof Op\Expr\Param || $cfgOp instanceof Op\Expr\Closure || $cfgOp instanceof Op\Expr\ArrowFunction) {
            if (null !== $this->compilingClassDisplayName && '' !== $this->compilingClassDisplayName) {
                return $this->namespaceFromFqcn($this->compilingClassDisplayName);
            }
        }
        if (null !== $this->compilingClassDisplayName && '' !== $this->compilingClassDisplayName) {
            return $this->namespaceFromFqcn($this->compilingClassDisplayName);
        }

        return '';
    }

    private function namespaceHintFromFunc(?CfgFunc $func): string
    {
        if (null === $func) {
            if (null !== $this->compilingClassDisplayName && '' !== $this->compilingClassDisplayName) {
                return $this->namespaceFromFqcn($this->compilingClassDisplayName);
            }

            return '';
        }
        $className = $this->funcClassNameString($func);
        if (null !== $className && '' !== $className) {
            return $this->namespaceFromFqcn($className);
        }
        if ('{main}' === $func->name || '' === $func->name) {
            return '';
        }

        return $this->namespaceFromFqcn($func->name);
    }

    private function funcClassNameString(CfgFunc $func): ?string
    {
        if (!isset($func->class) || null === $func->class) {
            return null;
        }
        if (is_string($func->class)) {
            return $func->class;
        }
        if ($func->class instanceof Operand\Literal && is_string($func->class->value)) {
            return $func->class->value;
        }
        if ($func->class instanceof Operand) {
            return $this->staticNameFromOperand($func->class);
        }

        return null;
    }

    private function namespaceFromFqcn(string $fqcn): string
    {
        $fqcn = ltrim($fqcn, '\\');
        $pos = strrpos($fqcn, '\\');
        if (false === $pos) {
            return '';
        }

        return substr($fqcn, 0, $pos);
    }

    protected function assignSourceMetadata(OpCode $op, Op $cfgOp): void
    {
        $op->sourceLocation = SourceLocation::fromOp($cfgOp);
    }

    /**
     * @param list<AttributeEntry> $selfEntries
     */
    protected function registerAttributeClassFromEntries(string $className, array $selfEntries): void
    {
        $this->attributeClassRegistry->registerAttributeClass($className, $selfEntries);
    }

    protected function compileClassLike(Op\Stmt\ClassLike $class, Block $block): OpCode {
        $type = 0;
        if ($class instanceof Op\Stmt\Class_) {
            $type = OpCode::TYPE_DECLARE_CLASS;
        } else {
            $this->throwCompileLogic('Unsupported class type: ' . get_class($class));
        }
        $className = $this->staticNameFromOperand($class->name);
        if (null === $className) {
            $this->throwCompileError('Class name must be a compile-time class reference');
        }
        $parentLc = null;
        $parentName = null;
        if ($class instanceof Op\Stmt\Class_ && null !== $class->extends) {
            $parentName = $this->staticNameFromOperand($class->extends);
            if (null === $parentName) {
                $this->throwCompileError('Parent class name must be a compile-time class reference');
            }
            $parentLc = strtolower(ltrim($parentName, '\\'));
        }
        [$interfaceLcs, $interfaceDisplays] = $this->interfaceLcAndDisplayFromOperands($class->implements);
        $parentSlot = null;
        if ($class instanceof Op\Stmt\Class_ && null !== $class->extends) {
            $parentSlot = $this->compileOperand($class->extends, $block, true);
        }
        $classFlagsVar = new Variable(Variable::TYPE_INTEGER);
        $classFlagsVar->int(VM\ClassFlags::pack($class->flags));
        $classFlagsOperand = new Operand\Temporary;
        $classFlagsOperand->type = Type::int();
        $readonlySlot = $block->registerConstant($classFlagsOperand, $classFlagsVar);
        $return = new OpCode(
            $type,
            $this->compileOperand($class->name, $block, true),
            $parentSlot,
            $readonlySlot
        );
        $return->classImplements = $interfaceLcs;
        $return->classImplementsDisplay = $interfaceDisplays;
        if (VM\StringableSupport::requiresImplementation($return->classImplements)) {
            VM\StringableSupport::assertConcreteClassImplements($class, $className);
        }
        $this->assignAttributeMetadata($return, $class);
        $this->assignSourceMetadata($return, $class);
        $return->deprecatedMetadata = DeprecatedMetadata::fromOp($class);
        AttributeNames::assertOverrideMethodTargetOnly($return->attributeNames, 'class', $return->attributeEntries);
        AttributeNames::assertCompileTimeConstTargetOnly($return->attributeNames, 'class', $return->attributeEntries);
        AttributeNames::assertSensitiveParameterParamTargetOnly($return->attributeNames, 'class', $return->attributeEntries);
        AttributeNames::assertReturnTypeWillChangeMethodTargetOnly($return->attributeNames, 'class', $return->attributeEntries);
        AttributeNames::assertDeprecatedTargetAllowed($return->attributeNames, 'class', $return->attributeEntries);
        AttributeNames::assertDeprecatedAllowedOnClassLike(
            $return->attributeNames,
            $return->deprecatedMetadata,
            'class',
            $className,
            $return->attributeEntries
        );
        $this->applySealedMetadataFromOp($class, $return);
        $return->classIsAbstract = VM\ClassAbstract::fromClassFlags($class->flags);
        if ($return->classIsAbstract) {
            AttributeNames::assertAttributeMetaOnConcreteClassLike(
                $return->attributeEntries,
                'abstract class',
                $className
            );
        }
        $classLc = strtolower(ltrim($className, '\\'));
        $this->compiledClassStaticProperties[$classLc] = $this->compiledClassStaticProperties[$classLc] ?? [];
        if (null !== $parentLc) {
            $this->inheritCompileTimeClassConstsFromParent($classLc, $parentLc);
        }
        $prevClassStaticCompile = $this->currentClassStaticPropertyCompile;
        $this->currentClassStaticPropertyCompile = $classLc;
        $prevCompilingParentLc = $this->compilingClassParentLc;
        $prevCompilingParentName = $this->compilingClassParentName;
        $prevCompilingClassIsReadonly = $this->compilingClassIsReadonly;
        $this->compilingClassParentLc = $parentLc;
        $this->compilingClassParentName = null !== $parentLc
            ? ($parentName ?? $parentLc)
            : null;
        $this->compilingClassIsReadonly = ClassReadonly::fromClassFlags($class->flags);
        $return->block1 = $this->compileClassBody(
            $class->stmts,
            $type,
            $className
        );
        $this->compilingClassParentLc = $prevCompilingParentLc;
        $this->compilingClassParentName = $prevCompilingParentName;
        $this->compilingClassIsReadonly = $prevCompilingClassIsReadonly;
        $this->currentClassStaticPropertyCompile = $prevClassStaticCompile;
        $this->mergeTraitStaticPropertiesIntoClass($class->stmts, $classLc);
        $this->mergeTraitCompileTimeClassConstsIntoClass($class->stmts, $classLc);
        $this->mergeInterfaceCompileTimeClassConstsIntoClass($classLc, $interfaceLcs);
        if ($class instanceof Op\Stmt\Class_ && null !== $class->extends && null !== $parentLc) {
            foreach ($this->compiledClassStaticProperties[$parentLc] ?? [] as $prop => $_) {
                $this->compiledClassStaticProperties[$classLc][$prop] = true;
            }
        }
        $this->classCompileRegistry->registerClass($className, $parentLc, $interfaceLcs, $class->stmts);
        $this->registerAttributeClassFromEntries($className, $return->attributeEntries);

        return $return;
    }

    protected function mergeTraitStaticPropertiesIntoClass(CfgBlock $stmts, string $classLc): void
    {
        foreach ($stmts->children as $child) {
            if (!$child instanceof Op\Stmt\TraitUse) {
                continue;
            }
            foreach ($child->traits as $traitOperand) {
                $traitName = $this->staticNameFromOperand($traitOperand);
                if (null === $traitName) {
                    continue;
                }
                $traitLc = strtolower(ltrim($traitName, '\\'));
                foreach ($this->compiledClassStaticProperties[$traitLc] ?? [] as $prop => $_) {
                    $this->compiledClassStaticProperties[$classLc][$prop] = true;
                }
            }
        }
    }

    /**
     * Copy trait class constants into the composing class compile-time table (#9430, zend_traits.c).
     */
    protected function mergeTraitCompileTimeClassConstsIntoClass(CfgBlock $stmts, string $classLc): void
    {
        foreach ($stmts->children as $child) {
            if (!$child instanceof Op\Stmt\TraitUse) {
                continue;
            }
            foreach ($child->traits as $traitOperand) {
                $traitName = $this->staticNameFromOperand($traitOperand);
                if (null === $traitName) {
                    continue;
                }
                $this->inheritCompileTimeClassConstsFromTrait(
                    $classLc,
                    strtolower(ltrim($traitName, '\\'))
                );
            }
        }
    }

    /**
     * Copy interface class constants into implementor compile-time table (#9430, zend_constants.c).
     *
     * @param list<string> $interfaceLcs
     */
    protected function mergeInterfaceCompileTimeClassConstsIntoClass(string $classLc, array $interfaceLcs): void
    {
        foreach ($interfaceLcs as $ifaceLc) {
            $this->inheritCompileTimeClassConstsFromInterface($classLc, $ifaceLc);
        }
    }

    protected function inheritCompileTimeClassConstsFromTrait(string $classLc, string $traitLc): void
    {
        if (!isset($this->compileTimeClassConsts[$traitLc])) {
            return;
        }
        if (!isset($this->compileTimeClassConsts[$classLc])) {
            $this->compileTimeClassConsts[$classLc] = [];
        }
        if (!isset($this->compileTimeClassConstVisibility[$classLc])) {
            $this->compileTimeClassConstVisibility[$classLc] = [];
        }
        if (!isset($this->compileTimeClassConstDeprecated[$classLc])) {
            $this->compileTimeClassConstDeprecated[$classLc] = [];
        }
        if (!isset($this->compileTimeClassConstNames[$classLc])) {
            $this->compileTimeClassConstNames[$classLc] = [];
        }
        foreach ($this->compileTimeClassConsts[$traitLc] as $constLc => $value) {
            if (isset($this->compileTimeClassConsts[$classLc][$constLc])) {
                continue;
            }
            $stored = new Variable();
            $stored->copyFrom($value);
            $this->compileTimeClassConsts[$classLc][$constLc] = $stored;
            if (isset($this->compileTimeClassConstVisibility[$traitLc][$constLc])) {
                $this->compileTimeClassConstVisibility[$classLc][$constLc]
                    = $this->compileTimeClassConstVisibility[$traitLc][$constLc];
            }
            if (isset($this->compileTimeClassConstDeprecated[$traitLc][$constLc])) {
                $this->compileTimeClassConstDeprecated[$classLc][$constLc]
                    = $this->compileTimeClassConstDeprecated[$traitLc][$constLc];
            }
            if (isset($this->compileTimeClassConstNames[$traitLc][$constLc])) {
                $this->compileTimeClassConstNames[$classLc][$constLc]
                    = $this->compileTimeClassConstNames[$traitLc][$constLc];
            }
        }
    }

    protected function inheritCompileTimeClassConstsFromInterface(string $classLc, string $ifaceLc): void
    {
        if (!isset($this->compileTimeClassConsts[$ifaceLc])) {
            return;
        }
        if (!isset($this->compileTimeClassConsts[$classLc])) {
            $this->compileTimeClassConsts[$classLc] = [];
        }
        if (!isset($this->compileTimeClassConstVisibility[$classLc])) {
            $this->compileTimeClassConstVisibility[$classLc] = [];
        }
        if (!isset($this->compileTimeClassConstDeprecated[$classLc])) {
            $this->compileTimeClassConstDeprecated[$classLc] = [];
        }
        if (!isset($this->compileTimeClassConstNames[$classLc])) {
            $this->compileTimeClassConstNames[$classLc] = [];
        }
        foreach ($this->compileTimeClassConsts[$ifaceLc] as $constLc => $value) {
            if (isset($this->compileTimeClassConsts[$classLc][$constLc])) {
                continue;
            }
            $stored = new Variable();
            $stored->copyFrom($value);
            $this->compileTimeClassConsts[$classLc][$constLc] = $stored;
            if (isset($this->compileTimeClassConstVisibility[$ifaceLc][$constLc])) {
                $this->compileTimeClassConstVisibility[$classLc][$constLc]
                    = $this->compileTimeClassConstVisibility[$ifaceLc][$constLc];
            }
            // Keep #[\Deprecated] so implementor fetches are not constant-folded (#29380).
            if (isset($this->compileTimeClassConstDeprecated[$ifaceLc][$constLc])) {
                $this->compileTimeClassConstDeprecated[$classLc][$constLc]
                    = $this->compileTimeClassConstDeprecated[$ifaceLc][$constLc];
            }
            if (isset($this->compileTimeClassConstNames[$ifaceLc][$constLc])) {
                $this->compileTimeClassConstNames[$classLc][$constLc]
                    = $this->compileTimeClassConstNames[$ifaceLc][$constLc];
            }
        }
    }

    /**
     * Copy public/protected parent class constants for compile-time {@code self::} folding (#13532, zend_constants.c).
     */
    protected function inheritCompileTimeClassConstsFromParent(string $classLc, string $parentLc): void
    {
        if (!isset($this->compileTimeClassConsts[$parentLc])) {
            return;
        }
        if (!isset($this->compileTimeClassConsts[$classLc])) {
            $this->compileTimeClassConsts[$classLc] = [];
        }
        if (!isset($this->compileTimeClassConstVisibility[$classLc])) {
            $this->compileTimeClassConstVisibility[$classLc] = [];
        }
        if (!isset($this->compileTimeClassConstDeprecated[$classLc])) {
            $this->compileTimeClassConstDeprecated[$classLc] = [];
        }
        if (!isset($this->compileTimeClassConstNames[$classLc])) {
            $this->compileTimeClassConstNames[$classLc] = [];
        }
        foreach ($this->compileTimeClassConsts[$parentLc] as $constLc => $value) {
            if (isset($this->compileTimeClassConsts[$classLc][$constLc])) {
                continue;
            }
            $vis = $this->compileTimeClassConstVisibility[$parentLc][$constLc] ?? CfgFunc::FLAG_PUBLIC;
            if (($vis & CfgFunc::FLAG_PRIVATE) !== 0) {
                continue;
            }
            $stored = new Variable();
            $stored->copyFrom($value);
            $this->compileTimeClassConsts[$classLc][$constLc] = $stored;
            $this->compileTimeClassConstVisibility[$classLc][$constLc] = $vis;
            if (isset($this->compileTimeClassConstDeprecated[$parentLc][$constLc])) {
                $this->compileTimeClassConstDeprecated[$classLc][$constLc]
                    = $this->compileTimeClassConstDeprecated[$parentLc][$constLc];
            }
            if (isset($this->compileTimeClassConstNames[$parentLc][$constLc])) {
                $this->compileTimeClassConstNames[$classLc][$constLc]
                    = $this->compileTimeClassConstNames[$parentLc][$constLc];
            }
            if (isset($this->compileTimeEnumCaseConstNames[$parentLc][$constLc])) {
                $this->compileTimeEnumCaseConstNames[$classLc][$constLc] = true;
            }
        }
    }

    protected function applySealedMetadataFromOp(Op $op, OpCode $opcode): void
    {
        if (!$op->hasAttribute('compilerSealed')) {
            return;
        }
        $opcode->isSealed = true;
        $permits = $op->getAttribute('compilerSealedPermits');
        $opcode->sealedPermits = \is_array($permits) ? $permits : [];
    }

    /**
     * @param Operand[] $operands
     *
     * @return list<string>
     */
    protected function interfaceNamesFromOperands(array $operands): array
    {
        return $this->interfaceLcAndDisplayFromOperands($operands)[0];
    }

    /**
     * @param Operand[] $operands
     *
     * @return array{0: list<string>, 1: list<string>} lowercase names, source display names
     */
    protected function interfaceLcAndDisplayFromOperands(array $operands): array
    {
        $lcs = [];
        $displays = [];
        foreach ($operands as $operand) {
            $name = $this->staticNameFromOperand($operand);
            if (null === $name) {
                $this->throwCompileError('Interface name must be a compile-time class reference');
            }
            $display = ltrim($name, '\\');
            $displays[] = $display;
            $lcs[] = strtolower($display);
        }

        return [$lcs, $displays];
    }

    /**
     * Zend defers forbidden user-implement fatals to declaration site (#18781).
     */
    protected function defersRuntimeInterfaceImplementationCheck(Op\Stmt\ClassLike $class): bool
    {
        $className = $this->staticNameFromOperand($class->name);
        if (null === $className) {
            return false;
        }
        $parentLc = null;
        if ($class instanceof Op\Stmt\Class_ && null !== $class->extends) {
            $parentName = $this->staticNameFromOperand($class->extends);
            if (null !== $parentName) {
                $parentLc = strtolower(ltrim($parentName, '\\'));
            }
        }
        $isEnum = $class instanceof Op\Stmt\Enum_;

        return ImplementsHierarchyRuntimeCheck::requiresSourceOrderRegistration(
            ltrim($className, '\\'),
            $this->interfaceNamesFromOperands($class->implements),
            $parentLc,
            $isEnum
        );
    }

    /**
     * Classes whose DECLARE_CLASS must not be hoisted before preceding statements.
     *
     * - Forbidden implements (DateTimeInterface / reserved): fatals at DECLARE (#18781)
     * - Serializable: E_DEPRECATED + class_exists timing match Zend (#22000, #25109)
     * - Any implements: DECLARE must run after prior spl_autoload_register (#25624)
     * - Trait use: abstract residuals / trait bind fatals at DECLARE after prior stmts (#25912)
     */
    protected function requiresSourceOrderClassRegistration(Op\Stmt\ClassLike $class): bool
    {
        if ($this->defersRuntimeInterfaceImplementationCheck($class)) {
            return true;
        }

        if (\in_array('serializable', $this->interfaceNamesFromOperands($class->implements), true)) {
            return true;
        }

        // Keep trait-using classes in source order so preceding opcodes (echo, etc.) run
        // before zend_verify_abstract_class / trait bind fatals (#25912).
        if ($class instanceof Op\Stmt\Class_ && $this->classDeclaresTraitUse($class)) {
            return true;
        }

        // Keep implements classes in source order so autoload callbacks registered above
        // the declaration are visible (Zend early-binds types, not user autoload timing).
        return $class instanceof Op\Stmt\Class_ && [] !== $class->implements;
    }

    /**
     * Same-file classes that must DECLARE in source order, including subclasses of
     * those classes (#29552, #29566).
     *
     * @param list<Op> $ops
     * @return array<string, true> lowercase class names
     */
    protected function sourceOrderClassRegistrationLcs(array $ops): array
    {
        /** @var array<string, Op\Stmt\Class_> */
        $classes = [];
        /** @var array<string, ?string> child lc => parent lc when parent name is static */
        $extends = [];
        foreach ($ops as $child) {
            if (!$child instanceof Op\Stmt\Class_) {
                continue;
            }
            $name = $this->staticNameFromOperand($child->name);
            if (null === $name) {
                continue;
            }
            $lc = strtolower(ltrim($name, '\\'));
            $classes[$lc] = $child;
            $parentLc = null;
            if (null !== $child->extends) {
                $parentName = $this->staticNameFromOperand($child->extends);
                if (null !== $parentName) {
                    $parentLc = strtolower(ltrim($parentName, '\\'));
                }
            }
            $extends[$lc] = $parentLc;
        }

        $sourceOrder = [];
        foreach ($classes as $lc => $class) {
            if ($this->requiresSourceOrderClassRegistration($class)) {
                $sourceOrder[$lc] = true;
            }
        }

        // Propagate to same-file subclasses so they are not hoisted before the parent (#29552, #29566).
        $changed = true;
        while ($changed) {
            $changed = false;
            foreach ($extends as $lc => $parentLc) {
                if (isset($sourceOrder[$lc]) || null === $parentLc || !isset($sourceOrder[$parentLc])) {
                    continue;
                }
                $sourceOrder[$lc] = true;
                $changed = true;
            }
        }

        return $sourceOrder;
    }

    /**
     * @param array<string, true> $sourceOrderClassLcs
     */
    protected function classIsSourceOrderRegistration(Op\Stmt\Class_ $class, array $sourceOrderClassLcs): bool
    {
        $name = $this->staticNameFromOperand($class->name);
        if (null !== $name) {
            $lc = strtolower(ltrim($name, '\\'));
            if (isset($sourceOrderClassLcs[$lc])) {
                return true;
            }
        }

        return $this->requiresSourceOrderClassRegistration($class);
    }

    /**
     * True when the class body contains a `use Trait` statement (#25912).
     */
    protected function classDeclaresTraitUse(Op\Stmt\Class_ $class): bool
    {
        foreach ($class->stmts->children as $member) {
            if ($member instanceof Op\Stmt\TraitUse) {
                return true;
            }
        }

        return false;
    }

    protected function staticNameFromOperand(Operand $op): ?string
    {
        if ($op instanceof Operand\Literal && is_string($op->value)) {
            return $op->value;
        }
        if ($op instanceof Operand\Variable) {
            return $this->staticNameFromOperand($op->name);
        }

        return null;
    }

    /**
     * PHP 8.4: interfaces may declare static properties only with hook syntax (#9754, zend_compile.c).
     */
    protected function interfaceStaticPropertyHookAllowed(Operand $nameOperand): bool
    {
        $propName = $this->staticNameFromOperand($nameOperand);
        $classLc = $this->compilingClassLc;
        if (null === $propName || null === $classLc || '' === $classLc) {
            return false;
        }

        return isset($this->propertyHookRegistry[$classLc][$propName])
            || isset($this->propertyHookRegistry[$classLc][strtolower($propName)]);
    }

    protected function literalScopeClassName(Operand $class): ?string
    {
        if ($class instanceof Operand\Literal && is_string($class->value)) {
            return $class->value;
        }
        if ($class instanceof Operand\Variable) {
            return $this->literalScopeClassName($class->name);
        }
        if (null !== $class->original) {
            if ($class->original instanceof \PhpParser\Node\Name) {
                return $class->original->toString();
            }
            if ($class->original instanceof Operand) {
                return $this->literalScopeClassName($class->original);
            }
        }

        return $this->staticNameFromOperand($class);
    }

    /**
     * True when the enclosing function is a static method (no `$this`, #26252).
     *
     * `parent::staticMethod(...)` FCC must use the Class::method string path, not
     * `[$this, method]` — Zend/zend_compile.c ZEND_AST_CALLABLE_CONVERT.
     */
    protected function blockIsStaticMethodContext(Block $block): bool
    {
        $func = $block->func ?? null;
        if (null === $func) {
            return false;
        }
        if (null === ($func->class ?? null) || null === $func->class->value || '' === $func->class->value) {
            return false;
        }

        return 0 !== (($func->flags ?? 0) & \PHPCfg\Func::FLAG_STATIC);
    }

    /** True when StaticCall source class is the `parent` keyword (#6735, zend_compile.c). */
    protected function staticCallUsesParentScope(Operand $class): bool
    {
        return 'parent' === $this->firstClassCallableScopeKeyword($class);
    }

    /**
     * FCC / static-call scope keyword: `parent` / `self` / `static`, else null (#17655, #26630).
     *
     * @return null|'parent'|'self'|'static'
     */
    protected function firstClassCallableScopeKeyword(Operand $class): ?string
    {
        $name = $this->literalScopeClassName($class);
        if (null !== $name) {
            $lc = strtolower($name);
            if ('parent' === $lc || 'self' === $lc || 'static' === $lc) {
                return $lc;
            }
        }
        $current = $class;
        while (null !== $current) {
            if ($current instanceof Operand\Variable && $current->name instanceof Operand\Literal) {
                $lc = strtolower((string) $current->name->value);
                if ('parent' === $lc || 'self' === $lc || 'static' === $lc) {
                    return $lc;
                }
            }
            if (property_exists($current, 'original') && null !== $current->original) {
                if ($current->original instanceof \PhpParser\Node\Name) {
                    $parts = $current->original->getParts();
                    if (1 === \count($parts)) {
                        $lc = strtolower($parts[0]);
                        if ('parent' === $lc || 'self' === $lc || 'static' === $lc) {
                            return $lc;
                        }
                    }
                }
                if ($current->original instanceof Operand) {
                    $current = $current->original;
                    continue;
                }
            }

            break;
        }

        return null;
    }

    /**
     * True when the static fetch class operand is an instance (new expr or variable), not a class name (#5477).
     */
    protected function staticPropertyClassIsObjectExpression(Operand $class): bool
    {
        if ($class instanceof Operand\Literal && is_string($class->value)) {
            return false;
        }
        $current = $class;
        while (null !== $current) {
            if ($current instanceof Op\Expr\New_) {
                return true;
            }
            if ($current instanceof Operand\Temporary || $current instanceof Operand\Variable) {
                $next = $current->original;
                $current = $next instanceof Operand ? $next : null;

                continue;
            }

            break;
        }

        return $class instanceof Operand\Temporary || $class instanceof Operand\Variable;
    }

    /**
     * @return list<string>
     */
    protected function intersectionNamesFromCfgType(Op\Type\Intersection $type, ?Block $block = null): array
    {
        $names = [];
        foreach ($type->types as $member) {
            $name = null !== $block && $member instanceof Op\Type\Reference
                ? $this->resolvedDnfReferenceNameFromCfgType($member, $block)
                : $this->staticNameFromCfgType($member);
            if (null === $name) {
                $this->throwCompileError('Intersection type members must be interface names');
            }
            $names[] = strtolower(ltrim($name, '\\'));
        }

        return $names;
    }

    /**
     * True when declared type uses union/intersection/nullable DNF shape (#3094).
     * Plain scalars like `int` stay on paramTypeConstraints / typeConstraint paths.
     */
    /**
     * MCJIT execute for DNF typed property scripts needs at least one try/catch region
     * (empty body is enough — see compliance dnf_property* vs dnf_new_empty_try).
     */
    private function appendMcjitDnfPropertyTryEpilogue(Block $main): void
    {
        $merge = new Block($main->orig);
        $merge->func = $main->func;
        $merge->inheritUndefinedLocals = true;
        $merge->addOpCode(new OpCode(OpCode::TYPE_RETURN_VOID));

        $tryBody = new Block($main->orig);
        $tryBody->func = $main->func;
        $tryBody->inheritUndefinedLocals = true;
        $tryJump = new OpCode(OpCode::TYPE_JUMP);
        $tryJump->block1 = $merge;
        $tryBody->addOpCode($tryJump);

        $catchBody = new Block($main->orig);
        $catchBody->func = $main->func;
        $catchBody->inheritUndefinedLocals = true;
        $catchJump = new OpCode(OpCode::TYPE_JUMP);
        $catchJump->block1 = $merge;
        $catchBody->addOpCode($catchJump);

        $tryOp = new OpCode(OpCode::TYPE_TRY);
        $tryOp->block1 = $tryBody;
        $tryOp->block2 = $merge;
        $main->addOpCode($tryOp);

        $catchOp = new OpCode(OpCode::TYPE_CATCH);
        $catchOp->block1 = $catchBody;
        $catchOp->block2 = $merge;
        $catchOp->catchTypes = 'throwable';
        $main->addOpCode($catchOp);
    }

    protected function cfgTypeUsesDnfShape(?Op\Type $declared): bool
    {
        if (null === $declared) {
            return false;
        }
        if ($declared instanceof Op\Type\Union_ || $declared instanceof Op\Type\Intersection) {
            return true;
        }
        if ($declared instanceof Op\Type\Nullable) {
            return true;
        }

        return false;
    }

    protected function cfgTypeIsStandaloneNever(?Op\Type $type): bool
    {
        if (null === $type) {
            return false;
        }
        if ($type instanceof Op\Type\Never_) {
            return true;
        }

        return $type instanceof Op\Type\Literal && 'never' === strtolower($type->name);
    }

    /**
     * Zend void type node or literal — standalone only (returns / not properties).
     */
    protected function cfgTypeIsStandaloneVoid(?Op\Type $type): bool
    {
        if (null === $type) {
            return false;
        }
        if ($type instanceof Op\Type\Void_) {
            return true;
        }

        return $type instanceof Op\Type\Literal && 'void' === strtolower($type->name);
    }

    protected function cfgTypeContainsNever(?Op\Type $type): bool
    {
        if (null === $type) {
            return false;
        }
        if ($type instanceof Op\Type\Never_) {
            return true;
        }
        if ($type instanceof Op\Type\Literal && 'never' === strtolower($type->name)) {
            return true;
        }
        if ($type instanceof Op\Type\Union_) {
            foreach ($type->types as $member) {
                if ($this->cfgTypeContainsNever($member)) {
                    return true;
                }
            }
        }
        if ($type instanceof Op\Type\Intersection) {
            foreach ($type->types as $member) {
                if ($this->cfgTypeContainsNever($member)) {
                    return true;
                }
            }
        }
        if ($type instanceof Op\Type\Nullable) {
            return $this->cfgTypeContainsNever($type->subtype);
        }

        return false;
    }

    /**
     * True when void appears anywhere in a declared type tree (union / nullable / intersection).
     */
    protected function cfgTypeContainsVoid(?Op\Type $type): bool
    {
        if (null === $type) {
            return false;
        }
        if ($type instanceof Op\Type\Void_) {
            return true;
        }
        if ($type instanceof Op\Type\Literal && 'void' === strtolower($type->name)) {
            return true;
        }
        if ($type instanceof Op\Type\Union_) {
            foreach ($type->types as $member) {
                if ($this->cfgTypeContainsVoid($member)) {
                    return true;
                }
            }
        }
        if ($type instanceof Op\Type\Intersection) {
            foreach ($type->types as $member) {
                if ($this->cfgTypeContainsVoid($member)) {
                    return true;
                }
            }
        }
        if ($type instanceof Op\Type\Nullable) {
            return $this->cfgTypeContainsVoid($type->subtype);
        }

        return false;
    }

    /**
     * True when `never` appears inside an intersection (not a top-level union arm only).
     */
    protected function cfgTypeContainsNeverInIntersection(?Op\Type $type): bool
    {
        if (null === $type) {
            return false;
        }
        if ($type instanceof Op\Type\Intersection) {
            foreach ($type->types as $member) {
                if ($this->cfgTypeIsStandaloneNever($member)) {
                    return true;
                }
                if ($this->cfgTypeContainsNeverInIntersection($member)) {
                    return true;
                }
            }

            return false;
        }
        if ($type instanceof Op\Type\Union_) {
            foreach ($type->types as $member) {
                if ($this->cfgTypeContainsNeverInIntersection($member)) {
                    return true;
                }
            }

            return false;
        }
        if ($type instanceof Op\Type\Nullable) {
            return $this->cfgTypeContainsNeverInIntersection($type->subtype);
        }

        return false;
    }

    protected function cfgTypeIsNullLiteral(?Op\Type $type): bool
    {
        return $type instanceof Op\Type\Literal && 'null' === strtolower($type->name);
    }

    protected function cfgTypeIsLiteralBoolName(?Op\Type $type, string $name): bool
    {
        return $type instanceof Op\Type\Literal && $name === strtolower($type->name);
    }

    protected function cfgTypeContainsLiteralBool(?Op\Type $type, string $name): bool
    {
        if (null === $type) {
            return false;
        }
        if ($this->cfgTypeIsLiteralBoolName($type, $name)) {
            return true;
        }
        if ($type instanceof Op\Type\Union_) {
            foreach ($type->types as $member) {
                if ($this->cfgTypeContainsLiteralBool($member, $name)) {
                    return true;
                }
            }
        }
        if ($type instanceof Op\Type\Intersection) {
            foreach ($type->types as $member) {
                if ($this->cfgTypeContainsLiteralBool($member, $name)) {
                    return true;
                }
            }
        }
        if ($type instanceof Op\Type\Nullable) {
            return $this->cfgTypeContainsLiteralBool($type->subtype, $name);
        }

        return false;
    }

    protected function cfgTypeContainsNull(?Op\Type $type): bool
    {
        if (null === $type) {
            return false;
        }
        if ($this->cfgTypeIsNullLiteral($type)) {
            return true;
        }
        if ($type instanceof Op\Type\Union_) {
            foreach ($type->types as $member) {
                if ($this->cfgTypeContainsNull($member)) {
                    return true;
                }
            }
        }
        if ($type instanceof Op\Type\Intersection) {
            foreach ($type->types as $member) {
                if ($this->cfgTypeContainsNull($member)) {
                    return true;
                }
            }
        }
        if ($type instanceof Op\Type\Nullable) {
            return $this->cfgTypeContainsNull($type->subtype);
        }

        return false;
    }

    /**
     * Zend: only class/interface types may appear in intersection types (#26401);
     * duplicate intersection members are redundant (#26605); equivalent DNF arms
     * are redundant (#26606); duplicate union arms are redundant (#26556);
     * object + class/interface is redundant (#26563);
     * DNF intersection arm proper-subset is more restrictive (#26607).
     */
    protected function assertIntersectionTypeMembers(?Op\Type $type): void
    {
        $invalid = IntersectionTypeMemberCompileCheck::findInvalidMemberName($type);
        if (null !== $invalid) {
            $this->throwCompileError(IntersectionTypeMemberCompileCheck::messageFor($invalid));
        }
        $duplicate = IntersectionTypeMemberCompileCheck::findDuplicateMemberName($type);
        if (null !== $duplicate) {
            $this->throwCompileError(IntersectionTypeMemberCompileCheck::duplicateMessageFor($duplicate));
        }
        $dnfRedundant = RedundantDnfArmCompileCheck::findRedundantArmPair($type);
        if (null !== $dnfRedundant) {
            $this->throwCompileError(RedundantDnfArmCompileCheck::messageFor(
                $dnfRedundant[0],
                $dnfRedundant[1]
            ));
        }
        $unionDup = DuplicateUnionMemberCompileCheck::findDuplicateMemberName($type);
        if (null !== $unionDup) {
            $this->throwCompileError(DuplicateUnionMemberCompileCheck::duplicateMessageFor($unionDup));
        }
        $subsetMsg = RedundantDnfArmSubsetCompileCheck::findRedundantMessage($type);
        if (null !== $subsetMsg) {
            $this->throwCompileError($subsetMsg);
        }
        if (RedundantObjectClassUnionCompileCheck::isRedundant($type)) {
            $label = $this->dnfTypeLabelFromCfgType($type);
            $this->throwCompileError(RedundantObjectClassUnionCompileCheck::messageFor($label));
        }
    }

    /**
     * Zend zend_compile_type — void is only valid as a standalone return type (#26517).
     * Unions / nullable void → "Void can only be used as a standalone type" (capital V).
     * Intersection members are rejected earlier by {@see assertIntersectionTypeMembers}.
     */
    protected function assertFunctionSignatureVoidType(?Op\Type $type): void
    {
        if (!$this->cfgTypeContainsVoid($type)) {
            return;
        }
        if ($this->cfgTypeIsStandaloneVoid($type)) {
            return;
        }
        $this->throwCompileError('Void can only be used as a standalone type');
    }

    /**
     * Zend zend_handle_never_type — never is only valid as a standalone signature type (#14334).
     */
    protected function assertFunctionSignatureNeverType(?Op\Type $type): void
    {
        if (!$this->cfgTypeContainsNever($type)) {
            return;
        }
        if ($this->cfgTypeIsStandaloneNever($type)) {
            return;
        }
        // Prefer intersection-specific wording when never appears under `&` (#26401).
        if ($this->cfgTypeContainsNeverInIntersection($type)) {
            $this->throwCompileError(IntersectionTypeMemberCompileCheck::messageFor('never'));
        }
        $this->throwCompileError('never can only be used as a standalone type');
    }

    /**
     * Zend zend_compile_type — mixed already includes null; mixed is standalone-only (#26554).
     *
     * {@code ?mixed} → "Type mixed cannot be marked as nullable since mixed already includes null"
     * {@code mixed|null} / {@code mixed|T} → "Type mixed can only be used as a standalone type"
     * Bare {@code Mixed_} (php-cfg untyped) is not a user-written mixed hint — callers skip it.
     */
    protected function assertMixedTypeRules(?Op\Type $type): void
    {
        if (null === $type) {
            return;
        }
        if ($this->cfgTypeIsNullableMixed($type)) {
            $this->throwCompileError('Type mixed cannot be marked as nullable since mixed already includes null');
        }
        if ($this->cfgTypeContainsNonStandaloneMixed($type)) {
            $this->throwCompileError('Type mixed can only be used as a standalone type');
        }
    }

    protected function cfgTypeIsPureMixed(?Op\Type $type): bool
    {
        if ($type instanceof Op\Type\Literal && 'mixed' === strtolower($type->name)) {
            return true;
        }

        return $type instanceof Op\Type\Mixed_;
    }

    protected function cfgTypeIsNullableMixed(?Op\Type $type): bool
    {
        return $type instanceof Op\Type\Nullable && $this->cfgTypeIsPureMixed($type->subtype);
    }

    /**
     * True when user-written {@code mixed} appears in a union/intersection (not as a lone type).
     * Nullable-of-pure-mixed is handled by {@see cfgTypeIsNullableMixed} instead.
     */
    protected function cfgTypeContainsNonStandaloneMixed(?Op\Type $type): bool
    {
        if (null === $type || $this->cfgTypeIsPureMixed($type)) {
            return false;
        }
        if ($type instanceof Op\Type\Nullable) {
            if ($this->cfgTypeIsPureMixed($type->subtype)) {
                return false;
            }

            return $this->cfgTypeContainsNonStandaloneMixed($type->subtype);
        }
        if ($type instanceof Op\Type\Union_) {
            $hasMixed = false;
            $hasOther = false;
            foreach ($type->types as $member) {
                if ($this->cfgTypeIsPureMixed($member) || $this->cfgTypeContainsPureMixed($member)) {
                    $hasMixed = true;
                } else {
                    $hasOther = true;
                }
                if ($this->cfgTypeContainsNonStandaloneMixed($member)) {
                    return true;
                }
            }

            return $hasMixed && $hasOther;
        }
        if ($type instanceof Op\Type\Intersection) {
            foreach ($type->types as $member) {
                if ($this->cfgTypeIsPureMixed($member) || $this->cfgTypeContainsPureMixed($member)) {
                    return true;
                }
                if ($this->cfgTypeContainsNonStandaloneMixed($member)) {
                    return true;
                }
            }
        }

        return false;
    }

    protected function cfgTypeContainsPureMixed(?Op\Type $type): bool
    {
        if (null === $type) {
            return false;
        }
        if ($this->cfgTypeIsPureMixed($type)) {
            return true;
        }
        if ($type instanceof Op\Type\Union_ || $type instanceof Op\Type\Intersection) {
            foreach ($type->types as $member) {
                if ($this->cfgTypeContainsPureMixed($member)) {
                    return true;
                }
            }

            return false;
        }
        if ($type instanceof Op\Type\Nullable) {
            return $this->cfgTypeContainsPureMixed($type->subtype);
        }

        return false;
    }

    /**
     * True when callable appears anywhere in a declared type tree (union / nullable / intersection).
     */
    protected function cfgTypeContainsCallable(?Op\Type $type): bool
    {
        if (null === $type) {
            return false;
        }
        if ($type instanceof Op\Type\Literal && 'callable' === strtolower($type->name)) {
            return true;
        }
        if ($type instanceof Op\Type\Union_) {
            foreach ($type->types as $member) {
                if ($this->cfgTypeContainsCallable($member)) {
                    return true;
                }
            }
        }
        if ($type instanceof Op\Type\Intersection) {
            foreach ($type->types as $member) {
                if ($this->cfgTypeContainsCallable($member)) {
                    return true;
                }
            }
        }
        if ($type instanceof Op\Type\Nullable) {
            return $this->cfgTypeContainsCallable($type->subtype);
        }

        return false;
    }

    /**
     * Zend rejects `parent` type atoms when the current class/enum/interface has no parent (#26540).
     * Traits keep an unresolved `parent` keyword (skipped via {@see ClassCompileRegistry::isTrait}).
     */
    protected function rejectParentTypeHintWithoutParent(?Op\Type $type): void
    {
        if (!PseudoClassTypeHintCompileCheck::containsKeyword($type, 'parent')) {
            return;
        }
        $declaringLc = $this->compilingClassLc;
        if (null === $declaringLc || '' === $declaringLc) {
            return;
        }
        if ($this->classCompileRegistry->isTrait($declaringLc)) {
            return;
        }
        if (null !== $this->compilingClassParentLc && '' !== $this->compilingClassParentLc) {
            return;
        }
        $resolved = $this->classCompileRegistry->parentDisplayName($declaringLc);
        if (null !== $resolved && '' !== $resolved) {
            return;
        }
        $this->throwCompileError(EnumParentCompileCheck::MESSAGE);
    }

    /**
     * Zend zend_handle_property_type — void/never/callable invalid on properties, including unions
     * (#6967, #7052, #26518, #26516).
     */
    protected function assertPropertyDeclaredType(?Op\Type $type, string $propName): void
    {
        $this->rejectParentTypeHintWithoutParent($type);
        $this->assertIntersectionTypeMembers($type);
        $this->assertMixedTypeRules($type);
        // void before never — Zend capitalizes "Void" in the standalone-only message.
        if ($this->cfgTypeContainsVoid($type)) {
            if ($this->cfgTypeIsStandaloneVoid($type)) {
                $class = $this->compilingClassDisplayName ?? 'class';
                $this->throwCompileError(sprintf('Property %s::$%s cannot have type void', $class, $propName));
            }
            $this->throwCompileError('Void can only be used as a standalone type');
        }
        if ($this->cfgTypeContainsNever($type)) {
            if ($this->cfgTypeIsStandaloneNever($type)) {
                $class = $this->compilingClassDisplayName ?? 'class';
                $this->throwCompileError(sprintf('Property %s::$%s cannot have type never', $class, $propName));
            }
            if ($this->cfgTypeContainsNeverInIntersection($type)) {
                $this->throwCompileError(IntersectionTypeMemberCompileCheck::messageFor('never'));
            }
            $this->throwCompileError('never can only be used as a standalone type');
        }
        // callable (including ?callable / unions) — Zend prints the full type string (#26516).
        if ($this->cfgTypeContainsCallable($type)) {
            $class = $this->compilingClassDisplayName ?? 'class';
            $label = DnfType::zendTypeErrorLabel($this->dnfTypeLabelFromCfgType($type));
            $this->throwCompileError(sprintf('Property %s::$%s cannot have type %s', $class, $propName, $label));
        }
    }

    protected function dnfTypeLabelFromCfgType(?Op\Type $declared, ?Block $block = null): string
    {
        if (null === $declared) {
            return 'mixed';
        }

        return DnfType::labelFromCfgType(
            $declared,
            fn (Op\Type\Intersection $t) => $this->intersectionNamesFromCfgType($t, $block),
            fn (Op\Type\Intersection $t) => $this->intersectionDisplayFromCfgType($t, $block),
            null !== $block
                ? fn (Op\Type\Reference $t) => $this->resolvedDnfReferenceNameFromCfgType($t, $block)
                : fn (Op\Type\Reference $t) => $this->staticNameFromCfgType($t)
        );
    }

    protected function intersectionDisplayFromCfgType(Op\Type\Intersection $type, ?Block $block = null): string
    {
        $names = [];
        foreach ($type->types as $member) {
            $name = null !== $block && $member instanceof Op\Type\Reference
                ? $this->resolvedDnfReferenceNameFromCfgType($member, $block)
                : $this->staticNameFromCfgType($member);
            if (null === $name) {
                $this->throwCompileError('Intersection type members must be interface names');
            }
            $names[] = ltrim($name, '\\');
        }

        return implode('&', $names);
    }

    protected function staticNameFromCfgType(?Op\Type $type): ?string
    {
        if (null === $type) {
            return null;
        }
        if ($type instanceof Op\Type\Literal) {
            return $type->name;
        }
        if ($type instanceof Op\Type\Reference) {
            return $this->staticNameFromOperand($type->declaration);
        }

        return null;
    }

    /**
     * Resolve self/parent in DNF union/nullable arms to the declaring class (zend_compile.c).
     * Leave late-bound {@code static} unresolved so runtime LSB can apply (#25947).
     */
    protected function resolvedDnfReferenceNameFromCfgType(Op\Type\Reference $type, Block $block): ?string
    {
        $name = $this->staticNameFromCfgType($type);
        if (null === $name || '' === $name) {
            return null;
        }
        $lc = strtolower(ltrim($name, '\\'));
        if ('static' === $lc) {
            return $name;
        }
        if ('self' === $lc || 'parent' === $lc) {
            $resolved = $this->resolveTypeHintClassName($name, $block);

            return (null !== $resolved && '' !== $resolved) ? $resolved : $name;
        }

        return $name;
    }

    protected function resolveTypeHintClassName(string $className, Block $block): ?string
    {
        $lexical = ltrim($className, '\\');
        $lc = strtolower($lexical);
        if ('self' === $lc || 'static' === $lc) {
            return $this->declaringClassDisplayNameForTypeHint($block);
        }
        if ('parent' === $lc) {
            $declaringLc = $this->declaringClassLcForTypeHint($block);
            if (null === $declaringLc) {
                return $lexical;
            }
            // Traits keep unresolved `parent` (Zend Reflection shows the keyword) (#26540).
            if ($this->classCompileRegistry->isTrait($declaringLc)) {
                return $lexical;
            }
            $resolved = $this->classCompileRegistry->parentDisplayName($declaringLc);
            if ((null === $resolved || '' === $resolved)
                && $declaringLc === $this->compilingClassLc
                && null !== $this->compilingClassParentLc
                && '' !== $this->compilingClassParentLc) {
                $resolved = $this->classCompileRegistry->traitDisplayName($this->compilingClassParentLc);
            }
            if (null !== $resolved && '' !== $resolved) {
                return $resolved;
            }
            // Class/enum/interface/anonymous without a parent — Zend compile fatal (#26540).
            if ($declaringLc === $this->compilingClassLc) {
                $this->throwCompileError(EnumParentCompileCheck::MESSAGE);
            }

            return $lexical;
        }

        return $lexical;
    }

    protected function declaringClassDisplayNameForTypeHint(Block $block): ?string
    {
        if (null !== $this->compilingClassDisplayName) {
            return $this->compilingClassDisplayName;
        }
        if (null !== $block->func && null !== $block->func->class) {
            $name = $this->staticNameFromOperand($block->func->class);

            return null !== $name ? ltrim($name, '\\') : null;
        }

        return null;
    }

    protected function declaringClassLcForTypeHint(Block $block): ?string
    {
        if (null !== $this->compilingClassLc) {
            return $this->compilingClassLc;
        }
        if (null !== $block->func && null !== $block->func->class) {
            $name = $this->staticNameFromOperand($block->func->class);

            return null !== $name ? strtolower(ltrim($name, '\\')) : null;
        }

        return null;
    }

    protected function assertParamDeclaredType(?Op\Type $declared, Block $block, CfgFunc $func): void
    {
        $this->rejectPseudoClassTypeHintOutsideClassScope($declared, $block, $func);
        $this->rejectParentTypeHintWithoutParent($declared);
        $this->assertIntersectionTypeMembers($declared);
        // void before never — Zend prefers "Void can only…" for void|never params (#26517).
        $this->assertFunctionSignatureVoidType($declared);
        $this->assertFunctionSignatureNeverType($declared);
        $this->assertMixedTypeRules($declared);
        if ($this->cfgTypeIsStandaloneVoid($declared)) {
            $this->throwCompileError('void cannot be used as a parameter type');
        }
        if ($this->cfgTypeIsStandaloneNever($declared)) {
            $this->throwCompileError('never cannot be used as a parameter type');
        }
    }

    protected function applyParamDeclaredType(Op\Expr\Param $param, Block $block, int $slot, bool $variadicElement = false): void
    {
        $declared = $param->declaredType;
        if (null === $block->func) {
            throw new \LogicException('applyParamDeclaredType requires block func');
        }
        $this->assertParamDeclaredType($declared, $block, $block->func);
        if (null !== $declared) {
            $block->paramDeclaredTypes[$slot] = $declared;
        }
        if ($declared instanceof Op\Type\Reference) {
            $className = $this->staticNameFromCfgType($declared);
            if (null !== $className && '' !== $className) {
                $resolved = $this->resolveTypeHintClassName($className, $block);
                if (null !== $resolved && '' !== $resolved) {
                    if ($variadicElement) {
                        $block->paramVariadicElementTypeConstraints[$slot] = Variable::TYPE_OBJECT;
                    } else {
                        $block->paramTypeConstraints[$slot] = Variable::TYPE_OBJECT;
                        $block->paramClassConstraints[$slot] = $resolved;
                        // Zend TypeError prints the resolved class for self/parent (zend_execute_API.c);
                        // keep unresolved trait `parent` as the keyword (#29930; mirrors return #29911/#29912).
                        $block->paramDeclaredTypeLabels[$slot] = ltrim($resolved, '\\');
                    }
                }
            }

            return;
        }
        if ($declared instanceof Op\Type\Intersection) {
            $display = $this->intersectionDisplayFromCfgType($declared, $block);
            if ($variadicElement) {
                $block->paramVariadicElementTypeConstraints[$slot] = Variable::TYPE_OBJECT;
                $block->paramVariadicElementIntersectionConstraints[$slot] = $this->intersectionNamesFromCfgType($declared, $block);
                $block->paramVariadicElementIntersectionDisplayLabels[$slot] = $display;
            } else {
                $block->paramTypeConstraints[$slot] = Variable::TYPE_OBJECT;
                $block->paramIntersectionConstraints[$slot] = $this->intersectionNamesFromCfgType($declared, $block);
                $block->paramIntersectionDisplayLabels[$slot] = $display;
            }

            return;
        }
        $arraySpec = $this->genericArraySpecFromCfgType($declared);
        if (null !== $arraySpec) {
            if ($variadicElement) {
                $block->paramVariadicElementTypeConstraints[$slot] = Variable::TYPE_ARRAY;
                $block->paramVariadicElementGenericArrayTypeSpecs[$slot] = $arraySpec;
            } else {
                $block->paramTypeConstraints[$slot] = Variable::TYPE_ARRAY;
                $block->paramGenericArrayTypeSpecs[$slot] = $arraySpec;
            }

            return;
        }
        if ($this->cfgTypeUsesDnfShape($declared)) {
            $dnfArms = DnfType::armsFromCfgType(
                $declared,
                fn (Op\Type\Intersection $t) => $this->intersectionNamesFromCfgType($t, $block),
                fn (Op\Type\Intersection $t) => $this->intersectionDisplayFromCfgType($t, $block),
                fn (Op\Type\Reference $t) => $this->resolvedDnfReferenceNameFromCfgType($t, $block)
            );
            if (DnfType::hasConstraints($dnfArms)) {
                if ($variadicElement) {
                    $block->paramVariadicElementDnfConstraints[$slot] = $dnfArms;
                } else {
                    $block->paramDnfConstraints[$slot] = $dnfArms;
                }

                return;
            }
        }
        if ($declared instanceof Op\Type\Literal) {
            $declName = strtolower($declared->name);
            if ('true' === $declName || 'false' === $declName) {
                if ($variadicElement) {
                    $block->paramVariadicElementTypeConstraints[$slot] = Variable::TYPE_BOOLEAN;
                } else {
                    $block->paramTypeConstraints[$slot] = Variable::TYPE_BOOLEAN;
                    $block->paramLiteralBoolTypes[$slot] = $declName;
                }

                return;
            }
            if ('iterable' === $declName) {
                $block->paramIterableSlots[$slot] = true;

                return;
            }
            if ('callable' === $declName) {
                $block->paramCallableSlots[$slot] = true;

                return;
            }
            if ('mixed' !== $declName) {
                $rawType = Type::fromDecl($declared->name);
                $mapped = Variable::mapFromType($rawType);
                if ($mapped !== Variable::TYPE_UNDEFINED) {
                    if ($variadicElement) {
                        $block->paramVariadicElementTypeConstraints[$slot] = $mapped;
                    } else {
                        $block->paramTypeConstraints[$slot] = $mapped;
                    }
                    // php-cfg leaves Param result Temporary->type null; stamp the declared
                    // PHPTypes so JIT fromOp allocates a native slot (int/float/bool), not a
                    // __value__ box. Without this, constructor promotion stores a value-box
                    // pointer into a native-long property and reads back garbage (#24008).
                    $operand = $block->getOperand($slot);
                    if (null !== $operand && null === $operand->type) {
                        $operand->type = $rawType;
                    }
                }
            }
        }
    }

    protected function declNameFromCfgType(?Op\Type $declared): ?string
    {
        if ($declared instanceof Op\Type\Literal) {
            return $declared->name;
        }
        if ($declared instanceof Op\Type\Reference) {
            return $this->staticNameFromOperand($declared->declaration);
        }

        return null;
    }

    protected function genericArraySpecFromCfgType(?Op\Type $declared): ?GenericArrayTypeSpec
    {
        $name = $this->declNameFromCfgType($declared);

        return null !== $name ? GenericArrayTypeSpec::tryParseDeclName($name) : null;
    }

    protected function compileClassBody(CfgBlock $block, int $type, ?string $className = null): Block {
        $result = new Block($block);
        $prevClassLc = $this->compilingClassLc;
        $prevClassDisplayName = $this->compilingClassDisplayName;
        $prevInstancePropertyNames = $this->compilingClassInstancePropertyNames;
        $prevMethodNames = $this->compilingClassMethodNames;
        $this->compilingClassInstancePropertyNames = [];
        $this->compilingClassMethodNames = [];
        if (null !== $className) {
            $this->compilingClassLc = strtolower(ltrim($className, '\\'));
            $this->compilingClassDisplayName = ltrim($className, '\\');
            if (!isset($this->compileTimeClassConsts[$this->compilingClassLc])) {
                $this->compileTimeClassConsts[$this->compilingClassLc] = [];
            }
            if (!isset($this->compileTimeClassConstVisibility[$this->compilingClassLc])) {
                $this->compileTimeClassConstVisibility[$this->compilingClassLc] = [];
            }
            if (!isset($this->compileTimeClassConstDeprecated[$this->compilingClassLc])) {
                $this->compileTimeClassConstDeprecated[$this->compilingClassLc] = [];
            }
        } else {
            $this->compilingClassDisplayName = null;
        }
        foreach ($block->children as $child) {
            switch (get_class($child)) {
                case Op\Stmt\Property::class:
                    if (
                        OpCode::TYPE_DECLARE_CLASS !== $type
                        && OpCode::TYPE_DECLARE_INTERFACE !== $type
                        && OpCode::TYPE_DECLARE_TRAIT !== $type
                    ) {
                        $this->throwCompileLogic('Properties are only supported on classes, interfaces, and traits for now');
                    }
                    if (OpCode::TYPE_DECLARE_INTERFACE === $type) {
                        if ($child->static && !$this->interfaceStaticPropertyHookAllowed($child->name)) {
                            $this->throwCompileLogic('Interfaces cannot declare static properties');
                        }
                        if (!is_null($child->defaultBlock) || null !== $child->defaultVar) {
                            $this->throwCompileLogic('Interface properties cannot have default values');
                        }
                    }
                    if (
                        OpCode::TYPE_DECLARE_CLASS === $type
                        && !$child->static
                        && $child->name instanceof Operand\Literal
                        && is_string($child->name->value)
                    ) {
                        $this->registerInstancePropertyDeclaration($child->name->value);
                    }
                    $propName = '?';
                    if ($child->name instanceof Operand\Literal && is_string($child->name->value)) {
                        $propName = $child->name->value;
                    }
                    $this->assertPropertyDeclaredType($child->declaredType, $propName);
                    $propertyDeclName = $this->declNameFromCfgType($child->declaredType);
                    $declared = null !== $propertyDeclName
                        ? Type::fromDecl($propertyDeclName)
                        : $this->typeFromPropertyDecl($child);
                    if ($child->static && null !== $this->currentClassStaticPropertyCompile) {
                        $staticPropName = $this->staticNameFromOperand($child->name);
                        if (null !== $staticPropName) {
                            $this->compiledClassStaticProperties[$this->currentClassStaticPropertyCompile][strtolower($staticPropName)] = true;
                        }
                    }
                    $declareType = $child->static
                        ? OpCode::TYPE_DECLARE_STATIC_PROPERTY
                        : OpCode::TYPE_DECLARE_PROPERTY;
                    $defaultSlot = null;
                    if (null !== $child->defaultVar) {
                        $defaultSlot = $this->tryFoldPropertyDefaultSlot($child, $result);
                        if (null === $defaultSlot) {
                            if (null !== $child->defaultBlock) {
                                $this->compileDefaultBlockChildrenWithProducerCfg($child->defaultBlock, $result);
                            }
                            $defaultSlot = $this->compileOperand($child->defaultVar, $result, true);
                            if (!isset($result->constants[$defaultSlot])) {
                                if ($this->propertyDefaultIsRuntimeNew($child)) {
                                    // Per-instance `new` defaults: opcodes precede DECLARE_*; VM init at TYPE_NEW (#3391).
                                    $defaultSlot = null;
                                } else {
                                    $staticClassMsg = $this->propertyDefaultStaticClassRejectMessage($child);
                                    if (null !== $staticClassMsg) {
                                        $sourceFile = $child->getFile();
                                        if ('' === $sourceFile) {
                                            $sourceFile = 'unknown';
                                        }
                                        throw new CompileFatal(
                                            $sourceFile,
                                            max(1, $child->getLine()),
                                            $staticClassMsg
                                        );
                                    }
                                    $propName = '?';
                                    if ($child->name instanceof Operand\Literal && is_string($child->name->value)) {
                                        $propName = $child->name->value;
                                    }
                                    $this->throwCompileLogic(
                                        'Property default must be a compile-time constant (#3803): $'.$propName
                                    );
                                }
                            }
                        }
                    }
                    if (null !== $defaultSlot && null !== $child->declaredType) {
                        $defaultVm = $result->constants[$defaultSlot] ?? null;
                        if (null !== $defaultVm) {
                            $propName = '?';
                            if ($child->name instanceof Operand\Literal && is_string($child->name->value)) {
                                $propName = $child->name->value;
                            }
                            $classPrefix = $this->compilingClassDisplayName ?? 'class';
                            $targetName = ($child->static ? $classPrefix.'::' : '').'$'.$propName;
                            $this->assertCompileTimeDefaultMatchesDeclaredType(
                                $defaultVm,
                                $child->declaredType,
                                'property',
                                $targetName
                            );
                        }
                    }
                    $typeSlot = $this->compileTypeConstrainedVariable(
                        $result,
                        $declared,
                        null !== $propertyDeclName ? $propertyDeclName : $child->declaredType
                    );
                    if (
                        isset($result->constants[$typeSlot])
                        && null !== $result->constants[$typeSlot]->dnfArms
                    ) {
                        $this->scriptHasDnfTypedProperties = true;
                    }
                    $declare = new OpCode(
                        $declareType,
                        $this->compileOperand($child->name, $result, true),
                        $defaultSlot,
                        $typeSlot
                    );
                    $declare->cfgDeclaredType = $child->declaredType;
                    $declare->propertyVisibility = MethodVisibility::mask($child->visibility);
                    $declare->propertySetVisibility = $this->asymmetricSetVisibilityFromCfgOp($child);
                    $declare->propertyGetVisibility = $this->asymmetricGetVisibilityFromCfgOp($child);
                    $declare->propertyAsymmetricExplicitRead = Ast\AsymmetricVisibilityRewriter::hasExplicitReadModifierFromAttributes(
                        $child->getAttributes()
                    );
                    if (!$child->static) {
                        $declare->propertyReadonly = (property_exists($child, 'readonly') && $child->readonly)
                            || (property_exists($child, 'propertyFlags') && $this->isReadonlyPropertyFlags($child->propertyFlags))
                            || $this->isReadonlyPropertyFlags($child->visibility);
                        $declare->propertyLazy = (property_exists($child, 'propertyLazy') && $child->propertyLazy)
                            || LazyPropertyRewriter::isLazyFromAttributes($child->getAttributes());
                    }
                    $declare->propertySetVisibility = PropertyVisibility::withImplicitReadonlyProtectedSet(
                        $declare->propertyReadonly || $this->compilingClassIsReadonly,
                        MethodVisibility::mask($declare->propertyVisibility),
                        (int) $declare->propertySetVisibility
                    );
                    // Explicit `final` (instance + static) — recover from propertyFlags when CFG
                    // visibility is VISIBILITY_MODIFIER_MASK-stripped (#23403, re-#23036/#22308).
                    // php-src Zend 8.2 rejects all finals; 8.4 allows plain + static finals.
                    $explicitFinal = $this->isFinalPropertyDeclaration($child);
                    $declare->propertyFinal = $explicitFinal
                        || (
                            !$child->static
                            && PropertyVisibility::isImplicitlyFinalFromPrivateSet(
                                (int) $declare->propertySetVisibility
                            )
                        );
                    if ($explicitFinal && !CompilerVersion::supportsFinalProperties()) {
                        // php-src Zend/zend_compile.c — pre-8.4 (#25379, re-#24895/#24822/#22308).
                        // CompileFatal → Zend-shaped "Fatal error: … in file on line N" on CLI.
                        $classDisplay = $this->compilingClassDisplayName ?? '{unknown}';
                        $sourceFile = $child->getFile();
                        if ('' === $sourceFile) {
                            $sourceFile = 'unknown';
                        }
                        throw new CompileFatal(
                            $sourceFile,
                            max(1, $child->getLine()),
                            sprintf(
                                'Cannot declare property %s::$%s final, the final modifier is allowed only for methods, classes, and class constants',
                                $classDisplay,
                                $propName
                            )
                        );
                    }
                    // php-src zend_add_member_modifier — final + private read visibility (#29425).
                    // private(set) only sets asymmetric set-vis, not FLAG_PRIVATE on read vis.
                    if (
                        $explicitFinal
                        && 0 !== (MethodVisibility::mask((int) $child->visibility) & CfgFunc::FLAG_PRIVATE)
                    ) {
                        $sourceFile = $child->getFile();
                        if ('' === $sourceFile) {
                            $sourceFile = 'unknown';
                        }
                        throw new CompileFatal(
                            $sourceFile,
                            max(1, $child->getLine()),
                            SourcePreprocessor\PropertyHooks::FINAL_PRIVATE_PROPERTY_COMPILE_ERROR
                        );
                    }
                    $this->assignAttributeMetadata($declare, $child);
                    AttributeTargetValidator::assertEntriesForTarget(
                        $declare->attributeEntries,
                        AttributeSupport::TARGET_PROPERTY,
                        'property',
                        $this->attributeClassRegistry,
                        true
                    );
                    AttributeNames::assertAttributeMetaClassTargetOnly($declare->attributeNames, 'property', $declare->attributeEntries);
                    AttributeNames::assertOverrideMethodTargetOnly($declare->attributeNames, 'property', $declare->attributeEntries);
                    AttributeNames::assertCompileTimeConstTargetOnly($declare->attributeNames, 'property', $declare->attributeEntries);
                    AttributeNames::assertSensitiveParameterParamTargetOnly($declare->attributeNames, 'property', $declare->attributeEntries);
                    AttributeNames::assertReturnTypeWillChangeMethodTargetOnly($declare->attributeNames, 'property', $declare->attributeEntries);
                    AttributeNames::assertDeprecatedTargetAllowed($declare->attributeNames, 'property', $declare->attributeEntries);
                    $declare->deprecatedMetadata = DeprecatedMetadata::fromOp($child);
                    $this->assignSourceMetadata($declare, $child);
                    $result->addOpCode($declare);
                    break;
                case Op\Stmt\ClassMethod::class:
                    $this->compileClassMethodDeclaration($child, $result, $type);
                    break;
                case Op\Terminal\Const_::class:
                    if (
                        OpCode::TYPE_DECLARE_CLASS !== $type
                        && OpCode::TYPE_DECLARE_INTERFACE !== $type
                        && OpCode::TYPE_DECLARE_TRAIT !== $type
                    ) {
                        $this->throwCompileLogic('Class constants are only supported on classes, interfaces, and traits for now');
                    }
                    $this->compileClassConstDeclaration($child, $result);
                    break;
                case Op\Stmt\TraitUse::class:
                    if (
                        OpCode::TYPE_DECLARE_CLASS !== $type
                        && OpCode::TYPE_DECLARE_TRAIT !== $type
                    ) {
                        $this->throwCompileLogic('Trait use is only supported on classes and traits for now');
                    }
                    foreach ($child->traits as $traitOperand) {
                        $result->addOpCode(new OpCode(
                            OpCode::TYPE_USE_TRAIT,
                            $this->compileOperand($traitOperand, $result, true)
                        ));
                    }
                    $adaptOp = new OpCode(OpCode::TYPE_TRAIT_USE_ADAPTATION);
                    $adaptOp->traitAdaptations = [] !== $child->adaptations
                        ? $this->compileTraitAdaptations($child->adaptations)
                        : [];
                    $result->addOpCode($adaptOp);
                    break;
                default:
                    $this->throwCompileLogic('Unsupported class body element: ' . get_class($child));
            }
        }
        $this->compilingClassLc = $prevClassLc;
        $this->compilingClassDisplayName = $prevClassDisplayName;
        $this->compilingClassInstancePropertyNames = $prevInstancePropertyNames;
        $this->compilingClassMethodNames = $prevMethodNames;

        return $result;
    }

    protected function registerMethodDeclaration(string $methodName): void
    {
        $lc = strtolower($methodName);
        if (isset($this->compilingClassMethodNames[$lc])) {
            $class = $this->compilingClassDisplayName ?? 'class';
            $this->throwCompileError(sprintf('Cannot redeclare %s::%s()', $class, $methodName));
        }
        $this->compilingClassMethodNames[$lc] = true;
    }

    protected function registerInstancePropertyDeclaration(string $propName): void
    {
        if (isset($this->compilingClassInstancePropertyNames[$propName])) {
            $class = $this->compilingClassDisplayName ?? 'class';
            $this->throwCompileError(sprintf('Cannot redeclare %s::$%s', $class, $propName));
        }
        $this->compilingClassInstancePropertyNames[$propName] = true;
    }

    protected function compileClassConstDeclaration(Op\Terminal\Const_ $child, Block $result): void
    {
        $constName = $this->staticNameFromOperand($child->name);
        if (null !== $constName && null !== $this->compilingClassLc) {
            // Case-sensitive — const A and const a are distinct (#25929).
            $constKey = ClassConstName::key($constName);
            if (isset($this->compileTimeClassConstEmitted[$this->compilingClassLc][$constKey])) {
                // Idempotent re-parse when a JIT helper was already inlined from require_once (#9753, #1492).
                return;
            }
        }
        $valueSlot = $this->tryFoldClassConstValueSlot($child, $result);
        if (null === $valueSlot) {
            $this->compileOps($child->valueBlock->children, $result);
            $valueSlot = $this->compileOperand($child->value, $result, true);
        }
        $typeSlot = null;
        if (property_exists($child, 'declaredType') && null !== $child->declaredType) {
            if (null !== $constName) {
                $result->classConstDeclaredTypes[ClassConstName::key($constName)] = $child->declaredType;
            }
            if (!$this->cfgDeclaredTypeIsMixed($child->declaredType)) {
                $this->rejectTypedClassConstantIfUnsupported($child->name);
                $this->rejectTypedTraitConstantIfUnsupported($child->name);
                $this->rejectTypedInterfaceConstantIfUnsupported($child->name);
                $this->assertIntersectionTypeMembers($child->declaredType);
                $declared = $this->typeFromClassConstDecl($child);
                $typeSlot = $this->compileTypeConstrainedVariable($result, $declared, $child->declaredType);
                if (isset($result->constants[$valueSlot])) {
                    $this->verifyClassConstCompileTimeType(
                        $child->name,
                        $result->constants[$valueSlot],
                        $typeSlot,
                        $result
                    );
                }
            }
        }
        $constOp = new OpCode(
            OpCode::TYPE_DECLARE_CLASS_CONST,
            $this->compileOperand($child->name, $result, true),
            $valueSlot,
            $typeSlot
        );
        $constOp->classConstVisibilityFlags = property_exists($child, 'flags')
            ? (int) $child->flags
            : CfgFunc::FLAG_PUBLIC;
        if ($this->cfgTerminalConstIsEnumCase($child)) {
            $constOp->isEnumCaseDeclare = true;
            if (null !== $this->compilingClassLc) {
                $constName = $this->staticNameFromOperand($child->name);
                if (null !== $constName) {
                    $this->compileTimeEnumCaseConstNames[$this->compilingClassLc][ClassConstName::key($constName)] = true;
                }
            }
        }
        $constOp->deprecatedMetadata = DeprecatedMetadata::fromOp($child);
        $this->assignAttributeMetadata($constOp, $child);
        $this->assignSourceMetadata($constOp, $child);
        AttributeNames::assertAttributeMetaClassTargetOnly($constOp->attributeNames, 'class constant', $constOp->attributeEntries);
        AttributeNames::assertCompileTimeConstTargetOnly($constOp->attributeNames, 'class constant', $constOp->attributeEntries);
        AttributeNames::assertSensitiveParameterParamTargetOnly($constOp->attributeNames, 'class constant', $constOp->attributeEntries);
        AttributeNames::assertReturnTypeWillChangeMethodTargetOnly($constOp->attributeNames, 'class constant', $constOp->attributeEntries);
        AttributeNames::assertOverrideMethodTargetOnly($constOp->attributeNames, 'class constant', $constOp->attributeEntries);
        AttributeNames::assertDeprecatedTargetAllowed($constOp->attributeNames, 'class constant', $constOp->attributeEntries);
        $result->addOpCode($constOp);
        if (null !== $this->compilingClassLc && null !== $constName) {
            $this->compileTimeClassConstEmitted[$this->compilingClassLc][ClassConstName::key($constName)] = true;
        }
        if (null !== $this->compilingClassLc && isset($result->constants[$valueSlot])) {
            $constName = $this->staticNameFromOperand($child->name);
            if (null !== $constName) {
                $backing = new Variable();
                $backing->copyFrom($result->constants[$valueSlot]);
                if ($constOp->isEnumCaseDeclare) {
                    $stored = $this->compileTimeEnumCaseVar(
                        $this->compilingClassDisplayName ?? $this->compilingClassLc,
                        $constName,
                        $backing,
                        $this->compileTimeEnumBackedTypes[$this->compilingClassLc] ?? null
                    );
                } else {
                    $stored = new Variable();
                    $stored->copyFrom($backing);
                }
                // Case-sensitive storage key (#25910 fetch / #25929 declare).
                $constKey = ClassConstName::key($constName);
                $this->compileTimeClassConsts[$this->compilingClassLc][$constKey] = $stored;
                $this->compileTimeClassConstNames[$this->compilingClassLc][$constKey] = $constName;
                $this->compileTimeClassConstVisibility[$this->compilingClassLc][$constKey]
                    = ClassConstVisibility::mask($constOp->classConstVisibilityFlags);
                if (null !== $constOp->deprecatedMetadata) {
                    $this->compileTimeClassConstDeprecated[$this->compilingClassLc][$constKey]
                        = $constOp->deprecatedMetadata;
                }
            }
        }
    }

    /**
     * Distinguish enum `case` from user `const` when php-cfg isEnumCase is missing (#5832).
     * Bare `const` without visibility has flags=0 like cases; trust isEnumCase when set (#6878).
     */
    private function cfgTerminalConstIsEnumCase(Op\Terminal\Const_ $child): bool
    {
        if (property_exists($child, 'isEnumCase')) {
            return $child->isEnumCase;
        }
        if (null === $this->compilingClassLc
            || !array_key_exists($this->compilingClassLc, $this->compileTimeEnumBackedTypes)) {
            return false;
        }
        if (property_exists($child, 'declaredType') && null !== $child->declaredType) {
            return false;
        }
        $flags = property_exists($child, 'flags') ? (int) $child->flags : 0;
        // Enum cases cannot be protected/private/final; those must be user `const`.
        if (0 !== ($flags & (\PHPCfg\Func::FLAG_PROTECTED | \PHPCfg\Func::FLAG_PRIVATE | \PHPCfg\Func::FLAG_FINAL))) {
            return false;
        }

        // When php-cfg omits isEnumCase (#5832), try to distinguish backed enum `case` from user `const`.
        // Heuristic: backed enum cases must have a scalar literal backing value of the enum's backed type.
        $backedType = $this->compileTimeEnumBackedTypes[$this->compilingClassLc] ?? null;
        if (null === $backedType) {
            // Unit enums: enum cases have no backing scalar; default to legacy heuristic.
            return 0 === $flags;
        }
        $vm = $this->vmVariableFromCfgLiteralOperand($child->value);
        if (null === $vm) {
            return false;
        }
        if ('int' === $backedType) {
            return Variable::TYPE_INTEGER === $vm->type;
        }
        if ('string' === $backedType) {
            return Variable::TYPE_STRING === $vm->type;
        }

        return false;
    }

    /**
     * Compile-time enum case singleton for folds (default args, class const inits; #5514).
     */
    private function compileTimeEnumCaseVar(
        string $enumName,
        string $caseName,
        Variable $backing,
        ?string $backedType
    ): Variable {
        $entry = new ClassEntry(ltrim($enumName, '\\'));
        $entry->isEnum = true;
        $entry->backedType = $backedType;
        EnumSupport::ensureBuiltinEnumInterfaces($entry);

        return EnumCaseSupport::compileTimeCaseVariable($entry, $caseName, $backing);
    }

    private function compileTimeStoredValueIsEnumCaseBackingScalar(
        string $lcClass,
        string $lcConst,
        Variable $stored
    ): bool {
        if (!array_key_exists($lcClass, $this->compileTimeEnumBackedTypes)) {
            return false;
        }
        if (!isset($this->compileTimeEnumCaseConstNames[$lcClass][$lcConst])) {
            return false;
        }
        if (Variable::TYPE_OBJECT === $stored->type && EnumCaseSupport::isEnumCase($stored->toObject())) {
            return false;
        }

        return $stored->is(Variable::TYPE_INTEGER) || $stored->is(Variable::TYPE_STRING);
    }

    protected function tryFoldClassConstValueSlot(Op\Terminal\Const_ $terminal, Block $block): ?int
    {
        if (null !== $terminal->valueBlock && [] !== $terminal->valueBlock->children) {
            $children = $terminal->valueBlock->children;
            if (1 === \count($children) && $children[0] instanceof Op\Expr\Array_) {
                $vm = $this->tryBuildCompileTimeArrayFromExpr($children[0], $block, $children, true);
                if (null !== $vm) {
                    return $block->registerConstant(new Operand\Temporary(), $vm);
                }
            }
            if (1 === \count($children) && $children[0] instanceof Op\Expr\ClassConstFetch) {
                $vm = $this->tryFoldClassConstFetchDefault($children[0], $block, true);
                if (null !== $vm) {
                    return $block->registerConstant(new Operand\Temporary(), $vm);
                }
            }
            if (
                2 === \count($children)
                && $children[0] instanceof Op\Expr\ClassConstFetch
                && $children[1] instanceof Op\Expr\ArrayDimFetch
            ) {
                $vm = $this->tryFoldClassConstArraySubscriptExpr(
                    $children[0],
                    $children[1],
                    $block
                );
                if (null !== $vm) {
                    return $block->registerConstant(new Operand\Temporary(), $vm);
                }
            }
            if (1 === \count($children) && $children[0] instanceof Op\Expr) {
                $vm = $this->tryFoldCompileTimeExprDefault($children[0], $block, $children, true);
                if (null !== $vm) {
                    return $block->registerConstant(new Operand\Temporary(), $vm);
                }
            }
            // Multi-op const-expr (e.g. SCALE * 2, LABEL . "y", -A, A ?? 5): php-cfg
            // emits ConstFetch then the operator. Class bodies are hoisted before
            // DECLARE_GLOBAL_CONST, so runtime CONST_FETCH would miss the global (#23997).
            foreach ($children as $child) {
                if (!$child instanceof Op\Expr) {
                    continue;
                }
                if (!property_exists($child, 'result')
                    || !$this->operandsReferToSameVariable($child->result, $terminal->value)
                ) {
                    continue;
                }
                $vm = $this->tryFoldCompileTimeExprDefault($child, $block, $children, true);
                if (null !== $vm) {
                    return $block->registerConstant(new Operand\Temporary(), $vm);
                }
            }
            foreach ($children as $child) {
                if (!$child instanceof Op\Stmt\JumpIf) {
                    continue;
                }
                $vm = $this->tryFoldCompileTimeTernaryDefault(
                    $child,
                    $terminal->value,
                    $block,
                    $children,
                    true
                );
                if (null !== $vm) {
                    return $block->registerConstant(new Operand\Temporary(), $vm);
                }
            }
            $vm = $this->tryFoldClassConstMatchValueBlock(
                $terminal->valueBlock,
                $terminal->value,
                $block,
                $children
            );
            if (null !== $vm) {
                return $block->registerConstant(new Operand\Temporary(), $vm);
            }
        }
        $vm = $this->vmVariableFromCfgLiteralOperand($terminal->value);
        if (null === $vm) {
            return null;
        }

        return $block->registerConstant(new Operand\Temporary(), $vm);
    }

    /**
     * Historical fold for lowered match() in class constant initializers (#9987).
     *
     * Unreachable for honest php-src-strict: match is not a const-expr
     * ({@see ThrowInClassConstCompileCheck}, #24904). Kept so accidental CFG shapes
     * still resolve rather than silently emitting a wrong constant.
     *
     * @param list<Op> $defaultBlockChildren
     */
    protected function tryFoldClassConstMatchValueBlock(
        CfgBlock $entry,
        Operand $result,
        Block $block,
        array $defaultBlockChildren
    ): ?Variable {
        $subject = $this->extractClassConstMatchSubject($entry, $result, $block, $defaultBlockChildren);
        if (null === $subject) {
            return null;
        }

        return $this->evaluateClassConstMatchCfgBlock(
            $entry,
            $subject,
            $result,
            $block,
            $defaultBlockChildren,
            0
        );
    }

    private function extractClassConstMatchSubject(
        CfgBlock $entry,
        Operand $result,
        Block $block,
        array $defaultBlockChildren
    ): ?Variable {
        $start = 0;
        if (isset($entry->children[0]) && $this->isMatchSeedAssign($entry->children[0], $result)) {
            $start = 1;
        }
        $count = \count($entry->children);
        for ($i = $start; $i < $count; ++$i) {
            $child = $entry->children[$i];
            if (!$child instanceof Op\Expr\BinaryOp\Identical) {
                continue;
            }

            return $this->tryFoldCompileTimeOperandDefault(
                $child->left,
                $block,
                $defaultBlockChildren,
                true
            );
        }

        return null;
    }

    /**
     * @param list<Op> $defaultBlockChildren
     */
    private function evaluateClassConstMatchCfgBlock(
        CfgBlock $cfgBlock,
        Variable $subject,
        Operand $result,
        Block $block,
        array $defaultBlockChildren,
        int $startIndex
    ): ?Variable {
        $children = $cfgBlock->children;
        if (0 === $startIndex && isset($children[0]) && $this->isMatchSeedAssign($children[0], $result)) {
            $startIndex = 1;
        }
        $count = \count($children);
        for ($i = $startIndex; $i < $count; ++$i) {
            $child = $children[$i];
            if (
                $child instanceof Op\Expr\BinaryOp\Identical
                && isset($children[$i + 1])
                && $children[$i + 1] instanceof Op\Stmt\JumpIf
            ) {
                $jumpIf = $children[$i + 1];
                $pattern = $this->tryFoldCompileTimeOperandDefault(
                    $child->right,
                    $block,
                    $defaultBlockChildren,
                    true
                );
                if (null === $pattern) {
                    return null;
                }
                if ($subject->identicalTo($pattern)) {
                    return $this->evaluateClassConstMatchArmBlock(
                        $jumpIf->if,
                        $result,
                        $block,
                        $defaultBlockChildren
                    );
                }

                return $this->evaluateClassConstMatchCfgBlock(
                    $jumpIf->else,
                    $subject,
                    $result,
                    $block,
                    $defaultBlockChildren,
                    0
                );
            }
            if ($child instanceof Op\Terminal\Throw_) {
                return null;
            }
            if ($child instanceof Op\Expr\Assign && $this->operandsReferToSameVariable($child->var, $result)) {
                return $this->tryFoldCompileTimeOperandDefault(
                    $child->expr,
                    $block,
                    $defaultBlockChildren,
                    true
                );
            }
        }

        return null;
    }

    /**
     * @param list<Op> $defaultBlockChildren
     */
    private function evaluateClassConstMatchArmBlock(
        CfgBlock $armBlock,
        Operand $result,
        Block $block,
        array $defaultBlockChildren
    ): ?Variable {
        foreach ($armBlock->children as $child) {
            if ($child instanceof Op\Terminal\Throw_) {
                return null;
            }
            if ($child instanceof Op\Expr\Assign && $this->operandsReferToSameVariable($child->var, $result)) {
                return $this->tryFoldCompileTimeOperandDefault(
                    $child->expr,
                    $block,
                    $defaultBlockChildren,
                    true
                );
            }
        }

        return null;
    }

    private function isMatchSeedAssign(Op $op, Operand $result): bool
    {
        if (!$op instanceof Op\Expr\Assign) {
            return false;
        }
        if (!$this->operandsReferToSameVariable($op->var, $result)) {
            return false;
        }
        $lit = $this->vmVariableFromCfgLiteralOperand($op->expr);

        return null !== $lit && Variable::TYPE_STRING === $lit->type && '' === $lit->toString();
    }

    /**
     * Fold {@code self::ARR[1]} in class constant scalar expressions (#5465, zend_compile.c).
     */
    protected function tryFoldClassConstArraySubscriptExpr(
        Op\Expr\ClassConstFetch $fetch,
        Op\Expr\ArrayDimFetch $dimFetch,
        Block $block
    ): ?Variable {
        if (null === $dimFetch->dim) {
            return null;
        }
        $base = $this->tryFoldClassConstFetchDefault($fetch, $block);
        if (null === $base || !$base->is(Variable::TYPE_ARRAY)) {
            return null;
        }
        $dimVm = $this->vmVariableFromCfgLiteralOperand($dimFetch->dim);
        if (null === $dimVm) {
            return null;
        }
        $table = $base->toArray();
        if (!$table->keyExists($dimVm)) {
            return null;
        }
        $elem = $table->findVariable($dimVm, false);
        if (null === $elem) {
            return null;
        }
        $value = new Variable();
        $value->copyFrom($elem->resolveIndirect());

        return $value;
    }

    protected function typeFromClassConstDecl(Op\Terminal\Const_ $child): Type
    {
        if ($child->declaredType instanceof Op\Type\Literal) {
            return Type::fromDecl($child->declaredType->name);
        }
        if (null !== $child->declaredType) {
            return Type::fromTypeDecl($child->declaredType);
        }

        return Type::mixed();
    }

    protected function cfgDeclaredTypeIsMixed(?Op\Type $declaredType): bool
    {
        if (null === $declaredType) {
            return true;
        }
        if ($declaredType instanceof Op\Type\Mixed_) {
            return true;
        }

        return $declaredType instanceof Op\Type\Literal && 'mixed' === strtolower($declaredType->name);
    }

    protected function verifyClassConstCompileTimeType(
        Operand $nameOp,
        Variable $value,
        int $typeSlot,
        Block $block
    ): void {
        if (!isset($block->constants[$typeSlot])) {
            return;
        }
        $constName = $nameOp instanceof Operand\Literal ? (string) $nameOp->value : 'constant';
        $className = $this->compilingClassDisplayName;
        try {
            TypeCheck::assertClassConstantTypedValue(
                $value,
                $block->constants[$typeSlot],
                $constName,
                $className
            );
        } catch (\TypeError $e) {
            $this->throwCompileError($e->getMessage());
        }
    }

    protected function verifyGlobalConstCompileTimeType(
        Operand $nameOp,
        Variable $value,
        int $typeSlot,
        Block $block
    ): void {
        if (!isset($block->constants[$typeSlot])) {
            return;
        }
        $constName = $nameOp instanceof Operand\Literal ? (string) $nameOp->value : 'constant';
        try {
            TypeCheck::assertGlobalConstantTypedValue($value, $block->constants[$typeSlot], $constName);
        } catch (\TypeError $e) {
            $this->throwCompileError($e->getMessage());
        }
    }

    /**
     * Zend 8.2 rejects typed class constants at parse time; enable at 8.3+ forward/stable (#12798, #22705).
     */
    protected function rejectTypedClassConstantIfUnsupported(Operand $nameOp): void
    {
        if (CompilerVersion::supportsTypedClassConstants()) {
            return;
        }
        if (null === $this->compilingClassLc) {
            return;
        }
        if (
            $this->classCompileRegistry->isTrait($this->compilingClassLc)
            || $this->classCompileRegistry->isInterface($this->compilingClassLc)
        ) {
            return;
        }
        $constName = $this->staticNameFromOperand($nameOp) ?? 'constant';
        $this->throwCompileError(
            sprintf('syntax error, unexpected identifier "%s", expecting "="', $constName)
        );
    }

    /**
     * Zend 8.2 rejects typed trait constants at parse time; enable at 8.3+ (#5212).
     */
    protected function rejectTypedTraitConstantIfUnsupported(Operand $nameOp): void
    {
        if (CompilerVersion::supportsTypedTraitConstants()) {
            return;
        }
        if (
            null === $this->compilingClassLc
            || !$this->classCompileRegistry->isTrait($this->compilingClassLc)
        ) {
            return;
        }
        $constName = $this->staticNameFromOperand($nameOp) ?? 'constant';
        $this->throwCompileError(
            sprintf('syntax error, unexpected identifier "%s", expecting "="', $constName)
        );
    }

    /**
     * Zend 8.2 rejects typed interface constants at parse time; enable at 8.3+ forward/stable (#5980, #7042, #24917).
     */
    protected function rejectTypedInterfaceConstantIfUnsupported(Operand $nameOp): void
    {
        if (CompilerVersion::supportsInterfaceTypedConstants()) {
            return;
        }
        if (
            null === $this->compilingClassLc
            || !$this->classCompileRegistry->isInterface($this->compilingClassLc)
        ) {
            return;
        }
        $constName = $this->staticNameFromOperand($nameOp) ?? 'constant';
        $this->throwCompileError(
            sprintf('syntax error, unexpected identifier "%s", expecting "="', $constName)
        );
    }

    /**
     * @param list<\PhpParser\Node\Stmt\TraitUseAdaptation> $adaptations
     *
     * @return list<array<string, mixed>>
     */
    protected function compileTraitAdaptations(array $adaptations): array
    {
        $out = [];
        foreach ($adaptations as $adaptation) {
            if ($adaptation instanceof \PhpParser\Node\Stmt\TraitUseAdaptation\Alias) {
                $entry = [
                    'kind' => 'alias',
                    'trait' => null !== $adaptation->trait ? $adaptation->trait->toString() : null,
                    'method' => $adaptation->method->name,
                    'newName' => null !== $adaptation->newName ? $adaptation->newName->name : null,
                ];
                if (null !== $adaptation->newModifier) {
                    $entry['newModifier'] = MethodVisibility::mask((int) $adaptation->newModifier);
                }
                $out[] = $entry;
            } elseif ($adaptation instanceof \PhpParser\Node\Stmt\TraitUseAdaptation\Precedence) {
                $insteadof = [];
                foreach ($adaptation->insteadof as $name) {
                    $insteadof[] = $name->toString();
                }
                $out[] = [
                    'kind' => 'precedence',
                    'trait' => $adaptation->trait->toString(),
                    'method' => $adaptation->method->name,
                    'insteadof' => $insteadof,
                ];
            } else {
                $this->throwCompileLogic('Unsupported TraitUseAdaptation node: ' . get_class($adaptation));
            }
        }

        return $out;
    }

    protected function isPromotedParam(Op\Expr\Param $param): bool
    {
        return property_exists($param, 'promotionFlags') && 0 !== $param->promotionFlags;
    }

    protected function compilePromotedPropertyDeclaration(Op\Expr\Param $param, Block $result): void
    {
        // php-src Zend/zend_compile.c — variadic + promotion incompatible (#26515).
        if ($param->variadic) {
            $sourceFile = $param->getFile();
            if ('' === $sourceFile) {
                $sourceFile = 'unknown';
            }
            throw new CompileFatal(
                $sourceFile,
                max(1, $param->getLine()),
                VariadicPromotedPropertyCompileCheck::MESSAGE
            );
        }
        $propName = '?';
        if ($param->name instanceof Operand\Literal && is_string($param->name->value)) {
            $propName = $param->name->value;
            $this->registerInstancePropertyDeclaration($propName);
        }
        $this->assertPropertyDeclaredType($param->declaredType, $propName);
        $defaultSlot = $this->resolvePropertyOrParamDefaultSlot($param, $result);
        if (null !== $defaultSlot && null !== $param->declaredType) {
            $defaultVm = $result->constants[$defaultSlot] ?? null;
            if (null !== $defaultVm) {
                $propName = '?';
                if ($param->name instanceof Operand\Literal && is_string($param->name->value)) {
                    $propName = '$'.$param->name->value;
                }
                $this->assertCompileTimeDefaultMatchesDeclaredType(
                    $defaultVm,
                    $param->declaredType,
                    'property',
                    $propName
                );
            }
        }
        $declared = $this->typeFromParamDecl($param);
        $propName = new Operand\Literal($param->name->value);
        $propName->type = Type::string();
        $typeSlot = $this->compileTypeConstrainedVariable($result, $declared, $param->declaredType);
        if (isset($result->constants[$typeSlot]) && null !== $result->constants[$typeSlot]->dnfArms) {
            $this->scriptHasDnfTypedProperties = true;
        }
        $declare = new OpCode(
            OpCode::TYPE_DECLARE_PROPERTY,
            $this->compileOperand($propName, $result, true),
            $defaultSlot,
            $typeSlot
        );
        $declare->propertyReadonly = $this->isPromotedParamReadonly($param);
        $declare->propertyFromConstructorPromotion = true;
        $declare->propertyVisibility = MethodVisibility::mask($param->promotionFlags);
        $declare->propertySetVisibility = $this->asymmetricSetVisibilityFromCfgOp($param);
        $declare->propertyGetVisibility = $this->asymmetricGetVisibilityFromCfgOp($param);
        $declare->propertySetVisibility = PropertyVisibility::withImplicitReadonlyProtectedSet(
            $declare->propertyReadonly || $this->compilingClassIsReadonly,
            MethodVisibility::mask($declare->propertyVisibility),
            (int) $declare->propertySetVisibility
        );
        $explicitFinal = FinalPromotedPropertyRewriter::isFinalFromAttributes($param->getAttributes())
            || (property_exists($param, 'promotionFinal') && $param->promotionFinal);
        // php-src zend_API.c — private(set) promoted props are implicitly final (#23068).
        $declare->propertyFinal = $explicitFinal
            || PropertyVisibility::isImplicitlyFinalFromPrivateSet((int) $declare->propertySetVisibility);
        if ($explicitFinal && !CompilerVersion::supportsFinalPromotedProperties()) {
            // php-src Zend/zend_compile.c — final on parameter rejected until 8.5 (#27123).
            $sourceFile = $param->getFile();
            if ('' === $sourceFile) {
                $sourceFile = 'unknown';
            }
            throw new CompileFatal(
                $sourceFile,
                max(1, $param->getLine()),
                \PHPCompiler\Ast\FinalPromotedPropertyRewriter::REFERENCE_PROFILE_FINAL_ON_PARAMETER
            );
        }
        $declare->propertyAsymmetricExplicitRead = Ast\AsymmetricVisibilityRewriter::hasExplicitReadModifierFromAttributes(
            $param->getAttributes()
        );
        $declare->deprecatedMetadata = DeprecatedMetadata::fromOp($param);
        $this->assignAttributeMetadata($declare, $param);
        // GH-9420 / #9661: parameter-only internals (SensitiveParameter) stay on the param,
        // not ReflectionProperty (#26379, re-#20351). Param metadata still has the full list.
        $declare->attributeEntries = AttributeNames::filterPromotedPropertyAttributeEntries(
            $declare->attributeEntries
        );
        $declare->attributeNames = AttributeEntry::namesFromList($declare->attributeEntries);
        AttributeTargetValidator::assertPromotedParameterTargets($declare->attributeEntries, $this->attributeClassRegistry);
        AttributeNames::assertAttributeMetaClassTargetOnly($declare->attributeNames, 'property', $declare->attributeEntries);
        AttributeNames::assertOverrideMethodTargetOnly($declare->attributeNames, 'property', $declare->attributeEntries);
        AttributeNames::assertCompileTimeConstTargetOnly($declare->attributeNames, 'property', $declare->attributeEntries);
        AttributeNames::assertSensitiveParameterParamTargetOnly($declare->attributeNames, 'property', $declare->attributeEntries);
        AttributeNames::assertReturnTypeWillChangeMethodTargetOnly($declare->attributeNames, 'property', $declare->attributeEntries);
        // php-src zend_attributes.c — promotion is a parameter for #[\Deprecated] target checks (#29420).
        AttributeNames::assertDeprecatedTargetAllowed($declare->attributeNames, 'parameter', $declare->attributeEntries);
        $result->addOpCode($declare);
    }

    protected function isReadonlyPropertyFlags(int $flags): bool
    {
        return 0 !== ($flags & ClassReadonly::MODIFIER_READONLY);
    }

    /**
     * PHP 8.4 final property from php-parser MODIFIER_FINAL (#22241, #23403).
     *
     * CFG `visibility` is VISIBILITY_MODIFIER_MASK only — recover FINAL from `propertyFlags`.
     * Hooked finals strip `final` before parse and set registry finalProperty (#16799).
     */
    protected function isFinalPropertyDeclaration(Op\Stmt\Property $prop): bool
    {
        if (property_exists($prop, 'propertyFlags') && ClassFinal::fromClassFlags((int) $prop->propertyFlags)) {
            return true;
        }

        return ClassFinal::fromClassFlags((int) $prop->visibility);
    }

    protected function isPromotedParamReadonly(Op\Expr\Param $param): bool
    {
        return property_exists($param, 'promotionReadonly') && $param->promotionReadonly;
    }

    protected function asymmetricSetVisibilityFromCfgOp(Op $op): int
    {
        if (property_exists($op, 'setVisibility') && 0 !== (int) $op->setVisibility) {
            return (int) $op->setVisibility;
        }
        if (property_exists($op, 'promotionSetVisibility') && 0 !== (int) $op->promotionSetVisibility) {
            return (int) $op->promotionSetVisibility;
        }

        return AsymmetricVisibilityRewriter::extractSetVisibilityFromAttributes($op->getAttributes());
    }

    protected function asymmetricGetVisibilityFromCfgOp(Op $op): int
    {
        if (property_exists($op, 'getVisibility') && 0 !== (int) $op->getVisibility) {
            return (int) $op->getVisibility;
        }
        if (property_exists($op, 'promotionGetVisibility') && 0 !== (int) $op->promotionGetVisibility) {
            return (int) $op->promotionGetVisibility;
        }

        return AsymmetricVisibilityRewriter::extractGetVisibilityFromAttributes($op->getAttributes());
    }

    /**
     * @param list<Op\Expr\Param> $params
     */
    protected function compileCtorPromotionAssignments(Block $block, array $params): void
    {
        $thisVar = new Operand\Variable(new Operand\Literal('this'));
        $thisSlot = $block->getVarSlot($thisVar, true);

        foreach ($params as $param) {
            if (!$this->isPromotedParam($param)) {
                continue;
            }
            if (!($param->name instanceof Operand\Literal) || !is_string($param->name->value)) {
                $this->throwCompileLogic('Promoted constructor parameter must have a simple name');
            }
            $propName = new Operand\Literal($param->name->value);
            $propName->type = Type::string();
            $propSlot = $this->compileOperand($propName, $block, true);
            $fetchTmp = new Temporary();
            $fetchSlot = $block->getVarSlot($fetchTmp, false);
            // Param slot is already registered by compileParam(); do not mark as arg read or
            // getFrame fails on method entry (callArgs holds $this only) (#3816).
            $paramSlot = $this->compileOperand($param->result, $block, false);
            $block->addOpCode(new OpCode(
                OpCode::TYPE_PROPERTY_FETCH,
                $fetchSlot,
                $thisSlot,
                $propSlot
            ));
            $block->addOpCode(new OpCode(
                OpCode::TYPE_ASSIGN,
                $fetchSlot,
                $fetchSlot,
                $paramSlot
            ));
        }
    }

    protected function typeFromPropertyDecl(Op\Stmt\Property $child): Type
    {
        if ($child->declaredType instanceof Op\Type\Mixed_) {
            return Type::mixed();
        }
        if ($child->declaredType instanceof Op\Type\Literal && 'mixed' === strtolower($child->declaredType->name)) {
            return Type::mixed();
        }
        if ($child->declaredType instanceof Op\Type\Literal) {
            return Type::fromDecl($child->declaredType->name);
        }
        if (null !== $child->declaredType) {
            return Type::fromTypeDecl($child->declaredType);
        }

        return $child->type ?? Type::mixed();
    }

    protected function typeFromParamDecl(Op\Expr\Param $param): Type
    {
        if ($param->declaredType instanceof Op\Type\Mixed_) {
            return Type::mixed();
        }
        if ($param->declaredType instanceof Op\Type\Literal && 'mixed' === strtolower($param->declaredType->name)) {
            return Type::mixed();
        }
        if ($param->declaredType instanceof Op\Type\Literal) {
            return Type::fromDecl($param->declaredType->name);
        }
        if (null !== $param->declaredType) {
            return Type::fromTypeDecl($param->declaredType);
        }

        return Type::mixed();
    }

    protected function compileTypeConstrainedVariable(Block $block, Type $type, Op\Type|string|null $cfgTypeOrDeclName = null): int {
        $cfgType = $cfgTypeOrDeclName instanceof Op\Type ? $cfgTypeOrDeclName : null;
        $declName = is_string($cfgTypeOrDeclName) ? $cfgTypeOrDeclName : null;
        // Untyped (no source type / php-cfg Mixed_) → TYPE_NULL; typed incl. explicit mixed → UNDEFINED (#4240, #22021).
        $untypedPrototype = null === $cfgTypeOrDeclName || $cfgType instanceof Op\Type\Mixed_;
        $var = new Variable($untypedPrototype ? Variable::TYPE_NULL : Variable::TYPE_UNDEFINED);
        $operand = new Operand\Temporary;
        $operand->type = $type;
        $return = $block->registerConstant($operand, $var);
        $arraySpec = null !== $declName ? GenericArrayTypeSpec::tryParseDeclName($declName) : null;
        if (null !== $arraySpec) {
            $var->typeConstraint = Variable::TYPE_ARRAY;
            $var->genericArrayTypeSpec = $arraySpec;
            $var->declaredTypeLabel = $declName;

            return $return;
        }
        $literalBoolName = null;
        if ($cfgType instanceof Op\Type\Literal) {
            $literalBoolName = strtolower($cfgType->name);
        } elseif (null !== $declName) {
            $literalBoolName = strtolower($declName);
        }
        if ('true' === $literalBoolName || 'false' === $literalBoolName) {
            $var->typeConstraint = Variable::TYPE_BOOLEAN;
            $var->literalBoolType = $literalBoolName;
            $var->declaredTypeLabel = $literalBoolName;

            return $return;
        }
        if (null !== $cfgType && $this->cfgDeclaredTypeIsMixed($cfgType)) {
            // Op\Type\Mixed_ is php-cfg's untyped marker (already TYPE_NULL). Literal "mixed" stays UNDEFINED.
            return $return;
        }
        // PHPTypes Type::fromDecl('mixed') mis-parses as object userType mixed (#12348).
        if (Type::TYPE_OBJECT === $type->type && 'mixed' === strtolower((string) ($type->userType ?? ''))) {
            return $return;
        }
        if ($this->cfgTypeUsesDnfShape($cfgType)) {
            $dnfArms = DnfType::armsFromCfgType(
                $cfgType,
                fn (Op\Type\Intersection $t) => $this->intersectionNamesFromCfgType($t, $block),
                fn (Op\Type\Intersection $t) => $this->intersectionDisplayFromCfgType($t, $block),
                fn (Op\Type\Reference $t) => $this->resolvedDnfReferenceNameFromCfgType($t, $block)
            );
            if (DnfType::hasConstraints($dnfArms) && DnfType::requiresDnfLowering($dnfArms)) {
                $var->dnfArms = $dnfArms;
                $var->declaredTypeLabel = $this->dnfTypeLabelFromCfgType($cfgType, $block);

                return $return;
            }
        }
        if (Type::TYPE_UNION === $type->type) {
            // PHPTypes Type::mixed() — untyped properties and `mixed` hints must not coerce writes (#2256).
            if (str_contains($type->toString(), 'callable')) {
                return $return;
            }
            $members = [];
            foreach ($type->subTypes as $sub) {
                $mapped = Variable::mapFromType($sub);
                if (Variable::TYPE_UNDEFINED !== $mapped) {
                    $members[] = $mapped;
                }
            }
            if ([] !== $members) {
                $var->unionTypeConstraints = $members;
                $memberNames = [];
                foreach ($type->subTypes as $sub) {
                    $memberNames[] = $sub->toString();
                }
                $var->declaredTypeLabel = DnfType::zendCanonicalUnionLabel($memberNames);
            }

            return $return;
        }
        $mappedType = Variable::mapFromType($type);
        if ($mappedType === Variable::TYPE_UNDEFINED) {
            return $return;
        }
        if ($mappedType === Variable::TYPE_OBJECT) {
            $var->classConstraint = $type->userType;
        }
        $var->typeConstraint = $mappedType;
        $var->declaredTypeLabel = $type->toString();

        return $return;
    }


    /**
     * Fold parameter/property defaults to block constant slots (Zend zend_compile_default_value, #3803).
     */
    protected function resolvePropertyOrParamDefaultSlot(Op\Expr\Param $param, Block $block, ?int $paramIdx = null): ?int
    {
        if (null === $param->defaultVar) {
            return null;
        }
        $folded = $this->tryFoldParamDefaultSlot($param, $block);
        if (null !== $folded) {
            return $folded;
        }
        if ($this->paramDefaultUsesRuntimeInit($param)) {
            if (null === $paramIdx) {
                // Promoted property metadata: default applied via constructor param (#6652).
                return null;
            }
            $beforeCount = \count($block->opCodes);
            if (null !== $param->defaultBlock) {
                // Same Array_/New_ rematerialize as function statics (#22390, #8561).
                $this->compileDefaultBlockChildrenWithProducerCfg($param->defaultBlock, $block);
            }
            $resultSlot = $this->compileOperand($param->defaultVar, $block, true);
            $newOps = \array_slice($block->opCodes, $beforeCount);
            $block->opCodes = \array_slice($block->opCodes, 0, $beforeCount);
            $block->nOpCodes = \count($block->opCodes);
            $block->paramRuntimeDefaultInitBlocks[$paramIdx] = $block->fragmentForOpcodes($newOps);
            $block->paramRuntimeDefaultResultSlots[$paramIdx] = $resultSlot;

            return null;
        }
        if (null !== $param->defaultBlock) {
            $this->compileDefaultBlockChildrenWithProducerCfg($param->defaultBlock, $block);
        }
        $slot = $this->compileOperand($param->defaultVar, $block, true);
        if (!isset($block->constants[$slot])) {
            $paramName = '?';
            if ($param->name instanceof Operand\Literal && is_string($param->name->value)) {
                $paramName = $param->name->value;
            }
            $this->throwCompileLogic(
                'Parameter default must be a compile-time constant (#3803): $'.$paramName
            );
        }

        return $slot;
    }

    /**
     * Parameter defaults evaluated when the argument is omitted: `new Class()` (#6652).
     * Unresolved ConstFetch / ClassConstFetch defaults defer like Zend (zend_compile_default_value, #24138).
     * First-class callables are not constant expressions below PHP 8.5 (Zend/zend_compile.c, #9697);
     * on 8.5+ they are legal const-exprs and lower as runtime defaults (#26240).
     */
    protected function paramDefaultUsesRuntimeInit(Op\Expr\Param $param): bool
    {
        if ($this->paramDefaultIsRuntimeNew($param)) {
            return true;
        }
        if (null !== $this->paramDefaultFirstClassCallableExpr($param)) {
            if (!CompilerVersion::supportsClosuresInConstantExpressions()) {
                $this->throwCompileLogic(ThrowInClassConstCompileCheck::MESSAGE);
            }

            return true;
        }
        // tryFoldParamDefaultSlot already failed — keep the AST and resolve at call time (#24138).
        if (null !== $this->paramDefaultConstFetchExpr($param)) {
            return true;
        }

        return false;
    }

    /**
     * Parameter default `new Class()` — evaluated when the argument is omitted (#6652).
     */
    protected function paramDefaultIsRuntimeNew(Op\Expr\Param $param): bool
    {
        if (null === $param->defaultVar) {
            return false;
        }
        if (null !== $param->defaultBlock && [] !== $param->defaultBlock->children) {
            $last = $param->defaultBlock->children[\count($param->defaultBlock->children) - 1];
            if ($last instanceof Op\Expr\New_) {
                return true;
            }
        }

        return $this->unwrapOperandChain($param->defaultVar) instanceof Op\Expr\New_;
    }

    protected function paramDefaultFirstClassCallableExpr(Op\Expr\Param $param): ?Op\Expr\FirstClassCallable
    {
        if (null === $param->defaultVar) {
            return null;
        }
        if (null !== $param->defaultBlock && [] !== $param->defaultBlock->children) {
            $last = $param->defaultBlock->children[\count($param->defaultBlock->children) - 1];
            if ($last instanceof Op\Expr\FirstClassCallable) {
                return $last;
            }
        }

        $unwrapped = $this->unwrapOperandChain($param->defaultVar);

        return $unwrapped instanceof Op\Expr\FirstClassCallable ? $unwrapped : null;
    }

    /**
     * Property default `new Class()` — deferred to instance creation (Zend zend_objects.c, #3391).
     */
    protected function propertyDefaultIsRuntimeNew(Op\Stmt\Property $prop): bool
    {
        if (null === $prop->defaultVar) {
            return false;
        }
        if (null !== $prop->defaultBlock && [] !== $prop->defaultBlock->children) {
            $last = $prop->defaultBlock->children[\count($prop->defaultBlock->children) - 1];
            if ($last instanceof Op\Expr\New_) {
                return true;
            }
        }

        return $this->unwrapOperandChain($prop->defaultVar) instanceof Op\Expr\New_;
    }

    protected function tryFoldPropertyDefaultSlot(Op\Stmt\Property $prop, Block $block): ?int
    {
        if (null === $prop->defaultVar) {
            return null;
        }
        $propertyType = $prop->declaredType ?? new Op\Type\Literal('mixed');
        $pseudo = new Op\Expr\Param(
            new Operand\Literal(''),
            new Op\Type\Mixed_(),
            false,
            false,
            $prop->defaultVar,
            $prop->defaultBlock
        );

        return $this->tryFoldParamDefaultSlot($pseudo, $block);
    }

    protected function tryFoldParamDefaultSlot(Op\Expr\Param $param, Block $block): ?int
    {
        if (null === $param->defaultVar) {
            return null;
        }
        if ($param->defaultVar instanceof Operand\NullOperand) {
            return $this->registerNullConstantSlot($block, $param->defaultVar);
        }
        $vm = $this->vmVariableFromCfgLiteralOperand($param->defaultVar);
        if (null !== $vm) {
            return $block->registerConstant($param->defaultVar, $vm);
        }
        if (null === $param->defaultBlock || [] === $param->defaultBlock->children) {
            return null;
        }
        $children = $param->defaultBlock->children;
        if ([] === $children) {
            return null;
        }
        foreach ($children as $child) {
            if (!$child instanceof Op\Stmt\JumpIf) {
                continue;
            }
            $vm = $this->tryFoldCompileTimeTernaryDefault(
                $child,
                $param->defaultVar,
                $block,
                $children,
                true
            );
            if (null !== $vm) {
                return $block->registerConstant($param->defaultVar, $vm);
            }
        }
        $expr = $children[\count($children) - 1];
        if (!$expr instanceof Op\Expr) {
            return null;
        }
        if ($expr instanceof Op\Expr\ConstFetch) {
            $vm = $this->tryFoldGlobalConstFetch($expr);
            if (null !== $vm) {
                return $block->registerConstant($param->defaultVar, $vm);
            }
        }
        if ($expr instanceof Op\Expr\ClassConstFetch) {
            $vm = $this->tryFoldClassConstFetchDefault($expr, $block, true);
            if (null !== $vm) {
                return $block->registerConstant($param->defaultVar, $vm);
            }
        }
        if ($expr instanceof Op\Expr\Array_) {
            $vm = $this->tryBuildCompileTimeArrayFromExpr($expr, $block, $children);
            if (null !== $vm) {
                return $block->registerConstant($param->defaultVar, $vm);
            }
        }
        if ($expr instanceof Op\Expr\ArrayDimFetch) {
            $vm = $this->tryFoldArrayDimFetchCompileTimeDefault($expr, $block, $children, true);
            if (null !== $vm) {
                return $block->registerConstant($param->defaultVar, $vm);
            }
        }
        if ($expr instanceof Op\Expr\UnaryMinus || $expr instanceof Op\Expr\UnaryPlus) {
            $vm = $this->tryFoldUnaryLiteralDefault($expr);
            if (null !== $vm) {
                return $block->registerConstant($param->defaultVar, $vm);
            }
        }
        $vm = $this->tryFoldCompileTimeExprDefault($expr, $block, $children, true);
        if (null !== $vm) {
            return $block->registerConstant($param->defaultVar, $vm);
        }

        return null;
    }

    /**
     * Fold php-cfg ?: lowering (JumpIf + arm assigns) in param/static defaults (#12026).
     *
     * @param list<Op> $defaultBlockChildren
     */
    protected function tryFoldCompileTimeTernaryDefault(
        Op\Stmt\JumpIf $jumpIf,
        Operand $result,
        Block $block,
        array $defaultBlockChildren,
        bool $materializeEnumCase = false
    ): ?Variable {
        $ifMerge = $this->branchJumpMergeTarget($jumpIf->if);
        $elseMerge = $this->branchJumpMergeTarget($jumpIf->else);
        if (null === $ifMerge || $ifMerge !== $elseMerge) {
            return null;
        }
        $condVm = $this->tryFoldCompileTimeOperandDefault(
            $jumpIf->cond,
            $block,
            $defaultBlockChildren,
            $materializeEnumCase
        );
        if (null === $condVm) {
            return null;
        }
        $ifVm = $this->foldBranchCfgResultValue(
            $jumpIf->if,
            $result,
            $block,
            $defaultBlockChildren,
            $materializeEnumCase
        );
        $elseVm = $this->foldBranchCfgResultValue(
            $jumpIf->else,
            $result,
            $block,
            $defaultBlockChildren,
            $materializeEnumCase
        );
        if (null === $ifVm || null === $elseVm) {
            return null;
        }

        $chosen = $condVm->toBool() ? $ifVm : $elseVm;
        $folded = new Variable();
        $folded->copyFrom($chosen);

        return $folded;
    }

    /**
     * Fold a ternary / logical-short-circuit arm that assigns into the merge result (#17229).
     *
     * @param list<Op> $defaultBlockChildren
     */
    private function foldBranchCfgResultValue(
        CfgBlock $branchCfg,
        Operand $result,
        Block $block,
        array $defaultBlockChildren,
        bool $materializeEnumCase
    ): ?Variable {
        $branchChildren = array_merge($defaultBlockChildren, $branchCfg->children);
        foreach ($branchCfg->children as $child) {
            if (!$child instanceof Op\Expr) {
                continue;
            }
            if ($child instanceof Op\Expr\Assign && $this->operandsReferToSameVariable($child->var, $result)) {
                return $this->tryFoldCompileTimeOperandDefault(
                    $child->expr,
                    $block,
                    $branchChildren,
                    $materializeEnumCase
                );
            }
            if (
                property_exists($child, 'result')
                && $this->operandsReferToSameVariable($child->result, $result)
            ) {
                return $this->tryFoldCompileTimeExprDefault(
                    $child,
                    $block,
                    $branchChildren,
                    $materializeEnumCase
                );
            }
        }

        return null;
    }

    private function branchCfgAssignExprForResult(CfgBlock $branchCfg, Operand $result): ?Operand
    {
        $assignVar = $this->mergeBranchAssignVarOperand($branchCfg);
        if (null === $assignVar || !$this->operandsReferToSameVariable($assignVar, $result)) {
            return null;
        }
        foreach ($branchCfg->children as $child) {
            if ($child instanceof Op\Expr\Assign && $this->operandsReferToSameVariable($child->var, $result)) {
                return $child->expr;
            }
        }

        return null;
    }

    /**
     * @param list<Op> $defaultBlockChildren
     */
    protected function tryFoldCompileTimeExprDefault(
        Op\Expr $expr,
        Block $block,
        array $defaultBlockChildren = [],
        bool $materializeEnumCase = false
    ): ?Variable {
        if ($expr instanceof Op\Expr\ConstFetch) {
            return $this->tryFoldGlobalConstFetch($expr);
        }
        if ($expr instanceof Op\Expr\ClassConstFetch) {
            return $this->tryFoldClassConstFetchDefault($expr, $block, $materializeEnumCase);
        }
        if ($expr instanceof Op\Expr\Array_) {
            return $this->tryBuildCompileTimeArrayFromExpr($expr, $block, $defaultBlockChildren);
        }
        if ($expr instanceof Op\Expr\UnaryMinus || $expr instanceof Op\Expr\UnaryPlus) {
            $literal = $this->tryFoldUnaryLiteralDefault($expr);
            if (null !== $literal) {
                return $literal;
            }

            return $this->tryFoldCompileTimeUnaryMinusPlusDefault(
                $expr,
                $block,
                $defaultBlockChildren,
                $materializeEnumCase
            );
        }
        if ($expr instanceof Op\Expr\BitwiseNot || $expr instanceof Op\Expr\BooleanNot) {
            return $this->tryFoldCompileTimeUnaryExprDefault(
                $expr,
                $block,
                $defaultBlockChildren,
                $materializeEnumCase
            );
        }
        if ($expr instanceof Op\Expr\BinaryOp\Coalesce) {
            return $this->tryFoldCompileTimeCoalesceDefault(
                $expr,
                $block,
                $defaultBlockChildren,
                $materializeEnumCase
            );
        }
        if ($expr instanceof Op\Expr\BinaryOp) {
            return $this->tryFoldCompileTimeBinaryExprDefault(
                $expr,
                $block,
                $defaultBlockChildren,
                $materializeEnumCase
            );
        }
        if ($expr instanceof Op\Expr\PropertyFetch) {
            return $this->tryFoldEnumCasePropertyFetchDefault($expr, $block, $defaultBlockChildren);
        }
        if ($expr instanceof Op\Expr\ArrayDimFetch) {
            return $this->tryFoldArrayDimFetchCompileTimeDefault(
                $expr,
                $block,
                $defaultBlockChildren,
                $materializeEnumCase
            );
        }
        if ($expr instanceof Op\Expr\Cast) {
            return $this->tryFoldCompileTimeCastDefault(
                $expr,
                $block,
                $defaultBlockChildren,
                $materializeEnumCase
            );
        }
        if ($expr instanceof Op\Expr\MagicScriptConst) {
            return $this->tryFoldMagicScriptConst($expr, $block);
        }

        return null;
    }

    /**
     * Fold __DIR__ / __FILE__ / __LINE__ / __COMPILER_HALT_OFFSET__ in const-expr
     * (class const, property/param defaults) — Zend zend_compile.c ZEND_AST_MAGIC_CONST (#24929).
     */
    protected function tryFoldMagicScriptConst(Op\Expr\MagicScriptConst $expr, Block $block): ?Variable
    {
        if (Op\Expr\MagicScriptConst::KIND_LINE === $expr->kind) {
            $line = max(1, $expr->getLine());
            if (\PHPCompiler\ext\standard\VmEval::isEvalScriptPath($block->scriptPath())) {
                $line = \PHPCompiler\ext\standard\VmEval::unwrapEvalLine($line);
            }
            $value = new Variable(Variable::TYPE_INTEGER);
            $value->int($line);

            return $value;
        }
        if (Op\Expr\MagicScriptConst::KIND_HALT_OFFSET === $expr->kind) {
            $offset = $block->haltCompilerOffset ?? $this->haltCompilerOffset;
            if (null === $offset) {
                return null;
            }
            $value = new Variable(Variable::TYPE_INTEGER);
            $value->int($offset);

            return $value;
        }
        $path = $block->scriptPath();
        if ('' === $path) {
            return null;
        }
        if (Op\Expr\MagicScriptConst::KIND_DIR === $expr->kind) {
            $value = new Variable(Variable::TYPE_STRING);
            $value->string(dirname($path));

            return $value;
        }
        if (Op\Expr\MagicScriptConst::KIND_FILE === $expr->kind) {
            $value = new Variable(Variable::TYPE_STRING);
            $value->string($path);

            return $value;
        }

        return null;
    }

    /**
     * Fold literal-array subscript in const-expr defaults (static/param/property, #12025).
     *
     * @param list<Op> $defaultBlockChildren
     */
    protected function tryFoldArrayDimFetchCompileTimeDefault(
        Op\Expr\ArrayDimFetch $expr,
        Block $block,
        array $defaultBlockChildren = [],
        bool $materializeEnumCase = false
    ): ?Variable {
        if (null === $expr->dim) {
            return null;
        }
        $base = $this->tryFoldCompileTimeOperandDefault(
            $expr->var,
            $block,
            $defaultBlockChildren,
            $materializeEnumCase
        );
        if (null === $base || !$base->is(Variable::TYPE_ARRAY)) {
            return null;
        }
        $dimVm = $this->tryFoldCompileTimeOperandDefault(
            $expr->dim,
            $block,
            $defaultBlockChildren,
            $materializeEnumCase
        );
        if (null === $dimVm) {
            return null;
        }
        $table = $base->toArray();
        if (!$table->keyExists($dimVm)) {
            return null;
        }
        $elem = $table->findVariable($dimVm, false);
        if (null === $elem) {
            return null;
        }
        $value = new Variable();
        $value->copyFrom($elem->resolveIndirect());

        return $value;
    }

    /**
     * Fold compile-time scalar casts, including (string) NAN/INF (#10143, zend_operators.c).
     *
     * @param list<Op> $defaultBlockChildren
     */
    protected function tryFoldCompileTimeCastDefault(
        Op\Expr\Cast $expr,
        Block $block,
        array $defaultBlockChildren = [],
        bool $materializeEnumCase = false
    ): ?Variable {
        $operand = $this->tryFoldCompileTimeOperandDefault(
            $expr->expr,
            $block,
            $defaultBlockChildren,
            $materializeEnumCase
        );
        if (null === $operand) {
            return null;
        }
        $castOpcode = $this->getOpCodeTypeFromCastOp($expr);
        if (OpCode::TYPE_CAST_OBJECT === $castOpcode) {
            return $this->tryFoldCompileTimeObjectCastOperand($operand);
        }
        $targetType = match ($castOpcode) {
            OpCode::TYPE_CAST_STRING => Variable::TYPE_STRING,
            OpCode::TYPE_CAST_INT => Variable::TYPE_INTEGER,
            OpCode::TYPE_CAST_FLOAT => Variable::TYPE_FLOAT,
            OpCode::TYPE_CAST_BOOL => Variable::TYPE_BOOLEAN,
            default => null,
        };
        if (null === $targetType) {
            return null;
        }
        $result = new Variable();
        try {
            $result->castFrom($targetType, $operand);
        } catch (\Throwable) {
            return null;
        }

        return $result;
    }

    /**
     * Fold (object) array-literal casts for define() prescan / const folding (#17676, zend_operators.c cast_object).
     */
    protected function tryFoldCompileTimeObjectCastOperand(Variable $operand): ?Variable
    {
        if ($operand->is(Variable::TYPE_OBJECT)) {
            $copy = new Variable();
            $copy->copyFrom($operand);

            return ClassConstMaterializer::detachConstantValue($copy);
        }
        if (!$operand->is(Variable::TYPE_ARRAY)) {
            return null;
        }
        $class = new ClassEntry('stdClass');
        $class->allowsDynamicProperties = true;
        $object = new ObjectEntry($class);
        $object->constructed = true;
        foreach ($operand->toArray()->iterateKeyed(true) as [$keyVar, $valueVar]) {
            $propName = $keyVar->is(Variable::TYPE_INTEGER)
                ? (string) $keyVar->toInt()
                : $keyVar->toString();
            $object->allocateProperty($propName)->copyFrom(
                ClassConstMaterializer::detachConstantValue($valueVar)
            );
        }
        $result = new Variable(Variable::TYPE_OBJECT);
        $result->object($object);

        return ClassConstMaterializer::detachConstantValue($result);
    }

    /**
     * define('NAME', (object)[...]) — prescan must not register the inner array (#17676).
     */
    protected function cfgArrayIsObjectCastSourceForOperand(
        Operand $arrayResult,
        Operand $valueRoot,
        Block $block
    ): bool {
        if (null === $block->orig) {
            return false;
        }
        foreach ($block->orig->children as $child) {
            if (!$child instanceof Op\Expr\Cast\Object_) {
                continue;
            }
            if (!$this->operandsReferToSameVariable($child->result, $valueRoot)) {
                continue;
            }
            if ($this->operandsReferToSameVariable($child->expr, $arrayResult)) {
                return true;
            }
        }

        return false;
    }

    /**
     * Fold unary const-expr operators in parameter/property defaults (#5166, zend_const_expr_to_zval).
     *
     * @param list<Op> $defaultBlockChildren
     */
    protected function tryFoldCompileTimeUnaryExprDefault(
        Op\Expr $expr,
        Block $block,
        array $defaultBlockChildren = [],
        bool $materializeEnumCase = false
    ): ?Variable {
        if (!$expr instanceof Op\Expr\BitwiseNot && !$expr instanceof Op\Expr\BooleanNot) {
            return null;
        }
        $opCode = $this->getOpCodeTypeFromUnaryOp($expr);
        if (!ClassConstExpr::isSupportedOpcode($opCode)) {
            return null;
        }
        $operand = $this->tryFoldCompileTimeOperandDefault(
            $expr->expr,
            $block,
            $defaultBlockChildren,
            $materializeEnumCase
        );
        if (null === $operand) {
            return null;
        }
        $result = new Variable();
        try {
            $result->unaryOp($opCode, $operand);
        } catch (\Throwable) {
            return null;
        }

        return $result;
    }

    /**
     * Fold {@code -CONST}/{@code +CONST} when the operand is a ConstFetch prelude (#23997).
     *
     * @param list<Op> $defaultBlockChildren
     */
    protected function tryFoldCompileTimeUnaryMinusPlusDefault(
        Op\Expr\UnaryMinus|Op\Expr\UnaryPlus $expr,
        Block $block,
        array $defaultBlockChildren = [],
        bool $materializeEnumCase = false
    ): ?Variable {
        $operand = $this->tryFoldCompileTimeOperandDefault(
            $expr->expr,
            $block,
            $defaultBlockChildren,
            $materializeEnumCase
        );
        if (null === $operand) {
            return null;
        }
        $opCode = $expr instanceof Op\Expr\UnaryMinus
            ? OpCode::TYPE_UNARY_MINUS
            : OpCode::TYPE_UNARY_PLUS;
        $result = new Variable();
        try {
            $result->unaryOp($opCode, $operand);
        } catch (\Throwable) {
            return null;
        }

        return $result;
    }

    /**
     * Fold {@code left ?? right} in const-expr defaults (#23997, zend_const_expr_to_zval).
     *
     * @param list<Op> $defaultBlockChildren
     */
    protected function tryFoldCompileTimeCoalesceDefault(
        Op\Expr\BinaryOp\Coalesce $expr,
        Block $block,
        array $defaultBlockChildren = [],
        bool $materializeEnumCase = false
    ): ?Variable {
        $left = $this->tryFoldCompileTimeOperandDefault(
            $expr->left,
            $block,
            $defaultBlockChildren,
            $materializeEnumCase
        );
        if (null === $left) {
            return null;
        }
        if (!$left->is(Variable::TYPE_NULL)) {
            $kept = new Variable();
            $kept->copyFrom($left);

            return $kept;
        }
        $right = $this->tryFoldCompileTimeOperandDefault(
            $expr->right,
            $block,
            $defaultBlockChildren,
            $materializeEnumCase
        );
        if (null === $right) {
            return null;
        }
        $result = new Variable();
        $result->copyFrom($right);

        return $result;
    }

    /**
     * Fold binary const-expr operators in parameter/property defaults (#5166, zend_const_expr_to_zval).
     *
     * @param list<Op> $defaultBlockChildren
     */
    protected function tryFoldCompileTimeBinaryExprDefault(
        Op\Expr\BinaryOp $expr,
        Block $block,
        array $defaultBlockChildren = [],
        bool $materializeEnumCase = false
    ): ?Variable {
        if ($expr instanceof Op\Expr\BinaryOp\Coalesce) {
            return $this->tryFoldCompileTimeCoalesceDefault(
                $expr,
                $block,
                $defaultBlockChildren,
                $materializeEnumCase
            );
        }
        $opCode = $this->getOpCodeTypeFromBinaryOp($expr);
        if (!ClassConstExpr::isSupportedOpcode($opCode)) {
            return null;
        }
        $left = $this->tryFoldCompileTimeOperandDefault(
            $expr->left,
            $block,
            $defaultBlockChildren,
            $materializeEnumCase
        );
        $right = $this->tryFoldCompileTimeOperandDefault(
            $expr->right,
            $block,
            $defaultBlockChildren,
            $materializeEnumCase
        );
        if (null === $left || null === $right) {
            return null;
        }
        if (OpCode::TYPE_CONCAT === $opCode) {
            $result = new Variable(Variable::TYPE_STRING);
            $result->string($left->toString().$right->toString());

            return $result;
        }
        $result = new Variable();
        try {
            if (\in_array($opCode, [
                OpCode::TYPE_PLUS,
                OpCode::TYPE_MINUS,
                OpCode::TYPE_MUL,
                OpCode::TYPE_DIV,
                OpCode::TYPE_MODULO,
                OpCode::TYPE_POW,
            ], true)) {
                $result->numericOp($opCode, $left, $right);
            } elseif (\in_array($opCode, [
                OpCode::TYPE_SMALLER,
                OpCode::TYPE_GREATER,
                OpCode::TYPE_SMALLER_OR_EQUAL,
                OpCode::TYPE_GREATER_OR_EQUAL,
            ], true)) {
                $result->compareOp($opCode, $left, $right);
            } elseif (OpCode::TYPE_SPACESHIP === $opCode) {
                // Class/file const `<=>` — zend_const_expr_to_zval (#24928).
                $result->spaceshipOp($left, $right);
            } elseif (OpCode::TYPE_IDENTICAL === $opCode) {
                $result->bool($left->identicalTo($right));
            } elseif (OpCode::TYPE_NOT_IDENTICAL === $opCode) {
                $result->bool(!$left->identicalTo($right));
            } elseif (OpCode::TYPE_EQUAL === $opCode) {
                $result->bool($left->equals($right));
            } elseif (OpCode::TYPE_NOT_EQUAL === $opCode) {
                $result->bool(!$left->equals($right));
            } elseif (OpCode::TYPE_LOGICAL_XOR === $opCode) {
                $result->bool($left->toBool() !== $right->toBool());
            } else {
                $result->bitwiseOp($opCode, $left, $right);
            }
        } catch (\Throwable) {
            return null;
        }

        return $result;
    }

    /**
     * Fold {@code E::Case->name}/{@code ->value} in parameter/property defaults (#7399, zend_compile.c).
     *
     * @param list<Op> $defaultBlockChildren
     */
    protected function tryFoldEnumCasePropertyFetchDefault(
        Op\Expr\PropertyFetch $expr,
        Block $block,
        array $defaultBlockChildren
    ): ?Variable {
        $propName = $this->staticNameFromOperand($expr->name);
        if (null === $propName) {
            return null;
        }
        $receiver = $this->tryFoldCompileTimeOperandDefault(
            $expr->var,
            $block,
            $defaultBlockChildren,
            true
        );
        if (null === $receiver) {
            return null;
        }
        if (Variable::TYPE_ENUM_CASE === $receiver->type) {
            return $receiver->toEnumCase()->fetchProperty($propName);
        }
        if (Variable::TYPE_OBJECT === $receiver->type && EnumCaseSupport::isEnumCase($receiver->toObject())) {
            return EnumCaseSupport::getProperty($receiver->toObject(), $propName);
        }

        return null;
    }

    /**
     * @param list<Op> $defaultBlockChildren
     */
    protected function tryFoldCompileTimeOperandDefault(
        ?Operand $operand,
        Block $block,
        array $defaultBlockChildren = [],
        bool $materializeEnumCase = false
    ): ?Variable {
        if (null === $operand) {
            return null;
        }
        $vm = $this->vmVariableFromCfgLiteralOperand($operand);
        if (null !== $vm) {
            return $vm;
        }
        foreach ($defaultBlockChildren as $child) {
            if (!$child instanceof Op\Expr) {
                continue;
            }
            if (!property_exists($child, 'result') || !$this->operandsReferToSameVariable($child->result, $operand)) {
                continue;
            }
            $vm = $this->tryFoldCompileTimeExprDefault(
                $child,
                $block,
                $defaultBlockChildren,
                $materializeEnumCase
            );
            if (null !== $vm) {
                return $vm;
            }
        }

        return null;
    }

    protected function tryFoldUnaryLiteralDefault(Op\Expr\UnaryMinus|Op\Expr\UnaryPlus $expr): ?Variable
    {
        $vm = $this->vmVariableFromCfgLiteralOperand($expr->expr);
        if (null === $vm) {
            return null;
        }
        if ($vm->is(Variable::TYPE_INTEGER)) {
            $value = new Variable(Variable::TYPE_INTEGER);
            $n = $vm->toInt();
            $value->int($expr instanceof Op\Expr\UnaryMinus ? -$n : $n);

            return $value;
        }
        if ($vm->is(Variable::TYPE_FLOAT)) {
            $value = new Variable(Variable::TYPE_FLOAT);
            $n = $vm->toFloat();
            $value->float($expr instanceof Op\Expr\UnaryMinus ? -$n : $n);

            return $value;
        }

        return null;
    }

    protected function registerNullConstantSlot(Block $block, Operand $operand): int
    {
        return $block->registerConstant($operand, new Variable(Variable::TYPE_NULL));
    }

    protected function tryFoldGlobalConstFetch(Op\Expr\ConstFetch $expr): ?Variable
    {
        $name = $this->staticNameFromOperand($expr->name);
        if (null === $name) {
            return null;
        }
        $vm = \PHPCompiler\ext\standard\VmPhpCoreConstants::fetch($name);
        if (null !== $vm) {
            return $vm;
        }
        $lc = strtolower($name);
        if ('null' === $lc) {
            return new Variable(Variable::TYPE_NULL);
        }
        if ('true' === $lc) {
            $v = new Variable(Variable::TYPE_BOOLEAN);
            $v->bool(true);

            return $v;
        }
        if ('false' === $lc) {
            $v = new Variable(Variable::TYPE_BOOLEAN);
            $v->bool(false);

            return $v;
        }
        $errorInt = \PHPCompiler\VM\Context::errorReportingConstant($name);
        if (null !== $errorInt) {
            $v = new Variable(Variable::TYPE_INTEGER);
            $v->int($errorInt);

            return $v;
        }
        $lc = strtolower($name);
        if ('inf' === $lc) {
            $v = new Variable(Variable::TYPE_FLOAT);
            $v->float(INF);

            return $v;
        }
        if ('nan' === $lc) {
            $v = new Variable(Variable::TYPE_FLOAT);
            $v->float(NAN);

            return $v;
        }
        if (isset($this->compileTimeGlobalConsts[$lc])) {
            $value = new Variable();
            $value->copyFrom($this->compileTimeGlobalConsts[$lc]);

            return $value;
        }
        $stdlibInt = \PHPCompiler\ext\standard\StdlibConstants::coreIntByName($lc);
        if (null !== $stdlibInt) {
            $v = new Variable(Variable::TYPE_INTEGER);
            $v->int($stdlibInt);

            return $v;
        }
        // M_PI / M_E / … — same map as VM\Context::constantFetch (#27249).
        $stdlibFloat = \PHPCompiler\ext\standard\StdlibConstants::CORE_FLOAT_BY_NAME[$lc] ?? null;
        if (null !== $stdlibFloat) {
            $v = new Variable(Variable::TYPE_FLOAT);
            $v->float($stdlibFloat);

            return $v;
        }
        $dateStr = \PHPCompiler\ext\standard\DateConstants::CORE_STRING_BY_NAME[$lc] ?? null;
        if (null !== $dateStr) {
            $v = new Variable(Variable::TYPE_STRING);
            $v->string($dateStr);

            return $v;
        }
        $stdlibStr = \PHPCompiler\ext\standard\StdlibConstants::CORE_STRING_BY_NAME[$lc] ?? null;
        if (null !== $stdlibStr) {
            $v = new Variable(Variable::TYPE_STRING);
            $v->string($stdlibStr);

            return $v;
        }

        return null;
    }

    /**
     * Pre-register enum `case` singletons for class/global const folding (#15737).
     *
     * Class/interface/trait bodies are hoisted before enum DECLARE opcodes; prescan
     * mirrors {@see compileEnum} metadata so {@code E::A} folds when enum is later in source.
     *
     * @param list<Op> $ops
     */
    protected function prescanCompileTimeEnumCases(array $ops): void
    {
        foreach ($ops as $child) {
            if ($child instanceof Op\Stmt\Enum_) {
                $this->prescanEnumCaseConstants($child);
            }
        }
    }

    protected function prescanEnumCaseConstants(Op\Stmt\Enum_ $enum): void
    {
        $enumName = $this->staticNameFromOperand($enum->name);
        if (null === $enumName) {
            return;
        }
        $enumLc = strtolower(ltrim($enumName, '\\'));
        $displayName = ltrim($enumName, '\\');
        $backedTypeName = null;
        if (null !== $enum->backedType && $enum->backedType instanceof Op\Type\Literal) {
            $backedTypeName = $enum->backedType->name;
        }
        if (!isset($this->compileTimeEnumBackedTypes[$enumLc])) {
            $this->compileTimeEnumBackedTypes[$enumLc] = $backedTypeName;
        }
        if (!isset($this->compileTimeEnumCaseConstNames[$enumLc])) {
            $this->compileTimeEnumCaseConstNames[$enumLc] = [];
        }
        if (!isset($this->runtimeEnumCaseConsts[$enumLc])) {
            $this->runtimeEnumCaseConsts[$enumLc] = [];
        }

        $prevClassLc = $this->compilingClassLc;
        $prevDisplay = $this->compilingClassDisplayName;
        $this->compilingClassLc = $enumLc;
        $this->compilingClassDisplayName = $displayName;

        foreach ($enum->stmts->children as $stmt) {
            if (!$stmt instanceof Op\Terminal\Const_ || !$this->cfgTerminalConstIsEnumCase($stmt)) {
                continue;
            }
            $caseName = $this->staticNameFromOperand($stmt->name);
            if (null === $caseName) {
                continue;
            }
            $lcCase = ClassConstName::key($caseName);
            if (isset($this->runtimeEnumCaseConsts[$enumLc][$lcCase])) {
                continue;
            }
            $backing = $this->vmVariableFromCfgLiteralOperand($stmt->value);
            if (null === $backing) {
                if (null !== $backedTypeName) {
                    continue;
                }
                $backing = new Variable(Variable::TYPE_NULL);
                $backing->null();
            }
            $this->runtimeEnumCaseConsts[$enumLc][$lcCase] = $this->compileTimeEnumCaseVar(
                $displayName,
                $caseName,
                $backing,
                $backedTypeName
            );
            $this->compileTimeEnumCaseConstNames[$enumLc][$lcCase] = true;
        }

        $this->compilingClassLc = $prevClassLc;
        $this->compilingClassDisplayName = $prevDisplay;
    }

    /**
     * Pre-register global `const` and literal define() for default-value folding (#6542).
     *
     * @param list<Op> $ops
     */
    protected function prescanCompileTimeGlobalConsts(array $ops, Block $block): void
    {
        foreach ($ops as $child) {
            if ($child instanceof Op\Terminal\Const_) {
                $this->prescanGlobalConstTerminal($child, $block);
                continue;
            }
            if ($child instanceof Op\Expr\FuncCall) {
                $this->prescanDefineFuncCall($child, $block);
            }
        }
    }

    protected function prescanGlobalConstTerminal(Op\Terminal\Const_ $const, Block $block): void
    {
        $name = $this->staticNameFromOperand($const->name);
        if (null === $name) {
            return;
        }
        $valueSlot = $this->tryFoldGlobalConstValueSlot($const, $block);
        if (null === $valueSlot || !isset($block->constants[$valueSlot])) {
            return;
        }
        $this->storeCompileTimeGlobalConst($name, $block->constants[$valueSlot]);
    }

    protected function prescanDefineFuncCall(Op\Expr\FuncCall $expr, Block $block): void
    {
        $fnName = $this->staticNameFromOperand($expr->name);
        if (null === $fnName || 'define' !== strtolower($fnName)) {
            return;
        }
        if (count($expr->args) < 2 || count($expr->args) > 3) {
            return;
        }
        $constNameArg = $expr->args[0];
        $valueArg = $expr->args[1];
        if (!$constNameArg instanceof Operand\Literal) {
            return;
        }
        if (Variable::TYPE_STRING !== Variable::mapFromType($constNameArg->type)) {
            return;
        }
        // Runtime define('NAME', expr) must not seed compileTimeGlobalConsts (#17676).
        if (!$valueArg instanceof Operand\Literal) {
            return;
        }
        $constName = $constNameArg->value;
        if (!is_string($constName) || '' === $constName || str_contains($constName, '::')) {
            return;
        }
        if ($this->defineValueRequiresRuntimeEvaluation($valueArg, $block)) {
            return;
        }
        $vm = $this->tryFoldDefineValueOperand($valueArg, $block);
        if (null === $vm) {
            return;
        }
        $this->storeCompileTimeGlobalConst($constName, $vm);
    }

    /**
     * Fold define('NAME', expr) value operands for compile-time const registration (#5409).
     */
    protected function tryFoldDefineValueOperand(Operand $valueArg, Block $block): ?Variable
    {
        $vm = $this->vmVariableFromCfgLiteralOperand($valueArg);
        if (null !== $vm) {
            return $vm;
        }
        if (null === $block->orig) {
            return null;
        }
        $root = $this->unwrapOperandChain($valueArg);
        foreach ($block->orig->children as $child) {
            if ($child instanceof Op\Expr\Array_
                && $this->operandsReferToSameVariable($child->result, $root)
            ) {
                if ($this->cfgArrayIsObjectCastSourceForOperand($child->result, $root, $block)) {
                    continue;
                }
                return $this->tryBuildCompileTimeArrayFromExpr($child);
            }
            if (!$child instanceof Op\Expr || !$this->operandsReferToSameVariable($child->result, $root)) {
                continue;
            }
            $vm = $this->tryFoldCompileTimeExprDefault($child, $block, [$child], true);
            if (null !== $vm) {
                return $vm;
            }
        }

        return null;
    }

    /** define('N', (object)[...]) and other runtime-only values must not prescan (#17676). */
    protected function defineValueRequiresRuntimeEvaluation(Operand $valueArg, Block $block): bool
    {
        if (null === $block->orig) {
            return false;
        }
        $root = $this->unwrapOperandChain($valueArg);
        foreach ($block->orig->children as $child) {
            if (!$child instanceof Op\Expr) {
                continue;
            }
            if (!$this->operandsReferToSameVariable($child->result, $root)) {
                continue;
            }
            if ($child instanceof Op\Expr\Cast) {
                return true;
            }
        }

        return false;
    }

    protected function storeCompileTimeGlobalConst(string $name, Variable $value): void
    {
        $lc = strtolower($name);
        if (isset($this->compileTimeGlobalConsts[$lc])) {
            return;
        }
        $stored = new Variable();
        $stored->copyFrom($value);
        $this->compileTimeGlobalConsts[$lc] = $stored;
    }

    protected function tryFoldClassConstFetchDefault(
        Op\Expr\ClassConstFetch $expr,
        Block $block,
        bool $materializeEnumCase = false
    ): ?Variable {
        $constName = $this->staticNameFromOperand($expr->name);
        if (null !== $constName && 'class' === strtolower($constName)) {
            $enumFqcn = $this->tryFoldEnumCaseClassPseudoConstFqcn($expr->class, $block);
            if (null !== $enumFqcn) {
                $value = new Variable(Variable::TYPE_STRING);
                $value->string($enumFqcn);

                return $value;
            }
            $builtinClass = $this->staticNameFromOperand($expr->class);
            if (null !== $builtinClass) {
                $builtinName = BuiltinTypeClassConstant::classNameForTypeOperand($builtinClass);
                if (null !== $builtinName) {
                    $value = new Variable(Variable::TYPE_STRING);
                    $value->string($builtinName);

                    return $value;
                }
                $builtinFn = BuiltinFunctionClassConstant::functionNameForClassOperand($builtinClass);
                if (null !== $builtinFn) {
                    $value = new Variable(Variable::TYPE_STRING);
                    $value->string($builtinFn);

                    return $value;
                }
                // self/parent/Named::class — compile-time string (zend_compile.c, #26629 / #3803).
                // static::class stays unfolded so LSB call sites keep the runtime opcode (#19614).
                $pseudoFqcn = $this->resolveCompileTimeClassPseudoConstFqcn($builtinClass, $block);
                if (null !== $pseudoFqcn) {
                    $value = new Variable(Variable::TYPE_STRING);
                    $value->string($pseudoFqcn);

                    return $value;
                }
            }
        }
        $className = $this->staticNameFromOperand($expr->class);
        if (null === $constName || null === $className) {
            return null;
        }
        // static::CONST / static::class need the called class at runtime (LSB).
        // Folding via the declaring class is self::-equivalent and wrong (#19614, zend_execute.c).
        if ('static' === strtolower($className)) {
            return null;
        }
        $lcClass = $this->resolveDefaultClassConstScope($className, $block);
        if (null === $lcClass) {
            return null;
        }
        if ($this->classCompileRegistry->isTrait($lcClass)) {
            return null;
        }
        $constKey = ClassConstName::key($constName);
        if (isset($this->compileTimeClassConsts[$lcClass][$constKey])) {
            // Class constants are case-sensitive — do not fold wrong casing (#25910, #25929).
            $declared = $this->compileTimeClassConstNames[$lcClass][$constKey] ?? null;
            if (!ClassConstName::matchesDeclared($constName, $declared)) {
                return null;
            }
            if (!$this->compileTimeClassConstFetchAllowed($lcClass, $constKey, $block)) {
                return null;
            }
            // Deprecated constants must fetch at runtime so E_USER_DEPRECATED fires (#6962).
            if (isset($this->compileTimeClassConstDeprecated[$lcClass][$constKey])) {
                return null;
            }
            $stored = $this->compileTimeClassConsts[$lcClass][$constKey];
            // Enum case fetches defer to runtime unless folding defaults/const-expr (#8767, #7399).
            if ($this->isCompileTimeEnumCaseConstantMember($lcClass, $constKey) && !$materializeEnumCase) {
                return null;
            }
            if ($this->compileTimeStoredValueIsEnumCaseBackingScalar($lcClass, $constKey, $stored)) {
                return $this->compileTimeEnumCaseVar(
                    $className,
                    $constName,
                    $stored,
                    $this->compileTimeEnumBackedTypes[$lcClass] ?? null
                );
            }
            // Non-literal duplicate backing falls back to runtime ensureBackedEnumValuesUnique (#5773).
            if (Variable::TYPE_OBJECT === $stored->type && EnumCaseSupport::isEnumCase($stored->toObject())) {
                if (!$materializeEnumCase) {
                    return null;
                }
                $value = new Variable();
                $value->copyFrom($stored);

                return $value;
            }
            if ($materializeEnumCase && Variable::TYPE_ENUM_CASE === $stored->type) {
                $value = new Variable();
                $value->copyFrom($stored);

                return $value;
            }
            if ($this->isCompileTimeEnumCaseConstantMember($lcClass, $constKey)) {
                return $this->materializeCompileTimeEnumCaseConstant(
                    $className,
                    $constName,
                    $stored,
                    $this->compileTimeEnumBackedTypes[$lcClass] ?? null
                );
            }
            $value = new Variable();
            $value->copyFrom($stored);

            return $value;
        }
        if (isset($this->runtimeEnumCaseConsts[$lcClass][$constKey])) {
            $stored = $this->runtimeEnumCaseConsts[$lcClass][$constKey];
            if ($this->isCompileTimeEnumCaseConstantMember($lcClass, $constKey) && !$materializeEnumCase) {
                return null;
            }
            if (Variable::TYPE_OBJECT === $stored->type && EnumCaseSupport::isEnumCase($stored->toObject())) {
                if (!$materializeEnumCase) {
                    return null;
                }
                $value = new Variable();
                $value->copyFrom($stored);

                return $value;
            }
            if ($materializeEnumCase && Variable::TYPE_ENUM_CASE === $stored->type) {
                $value = new Variable();
                $value->copyFrom($stored);

                return $value;
            }
            if ($this->isCompileTimeEnumCaseConstantMember($lcClass, $constKey)) {
                return $this->materializeCompileTimeEnumCaseConstant(
                    $className,
                    $constName,
                    $stored,
                    $this->compileTimeEnumBackedTypes[$lcClass] ?? null
                );
            }
            $value = new Variable();
            $value->copyFrom($stored);

            return $value;
        }

        return $this->tryFoldExternalClassConstFetch($className, $constName);
    }

    private function isCompileTimeEnumCaseConstantMember(string $lcClass, string $lcConst): bool
    {
        if (isset($this->compileTimeEnumCaseConstNames[$lcClass][$lcConst])) {
            return true;
        }
        if (!isset($this->runtimeEnumCaseConsts[$lcClass][$lcConst])) {
            return false;
        }
        $stored = $this->runtimeEnumCaseConsts[$lcClass][$lcConst];

        return Variable::TYPE_ENUM_CASE === $stored->type
            || (Variable::TYPE_OBJECT === $stored->type && EnumCaseSupport::isEnumCase($stored->toObject()));
    }

    /**
     * Fold enum `case` fetches to enum case objects — never expose backing scalars (#5933, #5858).
     */
    private function materializeCompileTimeEnumCaseConstant(
        string $enumName,
        string $caseName,
        Variable $stored,
        ?string $backedType
    ): Variable {
        if (Variable::TYPE_OBJECT === $stored->type && EnumCaseSupport::isEnumCase($stored->toObject())) {
            $value = new Variable();
            $value->copyFrom($stored);

            return $value;
        }
        if (Variable::TYPE_ENUM_CASE === $stored->type) {
            $value = new Variable();
            $value->copyFrom($stored);

            return $value;
        }
        $backing = new Variable();
        $backing->copyFrom($stored);

        return $this->compileTimeEnumCaseVar($enumName, $caseName, $backing, $backedType);
    }

    /**
     * Fold {@code EnumCase::class} to the enum type FQCN (Zend zend_compile.c; #5662).
     */
    protected function tryFoldEnumCaseClassPseudoConstFqcn(Operand $classOperand, Block $block): ?string
    {
        if ($classOperand instanceof Op\Expr\ClassConstFetch) {
            $inner = $this->tryFoldClassConstFetchDefault($classOperand, $block, true);
            if (null !== $inner) {
                $fqcn = $this->enumFqcnFromEnumCaseVariable($inner);
                if (null !== $fqcn) {
                    return $fqcn;
                }
            }
            $className = $this->staticNameFromOperand($classOperand->class);
            $caseName = $this->staticNameFromOperand($classOperand->name);
            if (null !== $className && null !== $caseName) {
                $lcClass = $this->resolveDefaultClassConstScope($className, $block);
                if (null !== $lcClass
                    && $this->isCompileTimeEnumCaseConstantMember($lcClass, ClassConstName::key($caseName))
                ) {
                    return ltrim($className, '\\');
                }
            }

            return null;
        }
        if (!$classOperand instanceof Operand\Variable && !$classOperand instanceof Temporary) {
            return null;
        }
        if (null === $block->orig) {
            return null;
        }
        foreach ($block->orig->children as $child) {
            if (!$child instanceof Op\Expr\ClassConstFetch
                || !$this->operandsReferToSameVariable($child->result, $classOperand)
            ) {
                continue;
            }
            $className = $this->staticNameFromOperand($child->class);
            $caseName = $this->staticNameFromOperand($child->name);
            if (null === $className || null === $caseName) {
                continue;
            }
            $lcClass = $this->resolveDefaultClassConstScope($className, $block);
            $lcConst = ClassConstName::key($caseName);
            if (null === $lcClass || !$this->isCompileTimeEnumCaseConstantMember($lcClass, $lcConst)) {
                continue;
            }
            $stored = $this->compileTimeClassConsts[$lcClass][$lcConst]
                ?? $this->runtimeEnumCaseConsts[$lcClass][$lcConst]
                ?? null;
            if (null !== $stored) {
                $fqcn = $this->enumFqcnFromEnumCaseVariable($stored);
                if (null !== $fqcn) {
                    return $fqcn;
                }
            }

            return ltrim($className, '\\');
        }

        return null;
    }

    protected function enumFqcnFromEnumCaseVariable(Variable $var): ?string
    {
        $var = $var->resolveIndirect();
        if (Variable::TYPE_ENUM_CASE === $var->type) {
            return $var->toEnumCase()->enumClass->name;
        }
        if (Variable::TYPE_OBJECT === $var->type && EnumCaseSupport::isEnumCase($var->toObject())) {
            return $var->toObject()->class->name;
        }

        return null;
    }

    protected function tryFoldExternalClassConstFetch(string $className, string $constName): ?Variable
    {
        $lcClass = strtolower(ltrim($className, '\\'));
        // Attribute::* from compiler profile — never host \Attribute (#20727).
        // Leave Attribute::class to the ::class / native paths (not a TARGET_* bit).
        if ('attribute' === $lcClass && 'class' !== strtolower($constName)) {
            $folded = AttributeSupport::builtinConstValue(strtolower($constName));
            if (null === $folded) {
                return null;
            }
            $value = new Variable(Variable::TYPE_INTEGER);
            $value->int($folded);

            return $value;
        }
        if ('phpcfg\\func' === $lcClass) {
            $flags = [
                'FLAG_PUBLIC' => \PHPCfg\Func::FLAG_PUBLIC,
                'FLAG_PROTECTED' => \PHPCfg\Func::FLAG_PROTECTED,
                'FLAG_PRIVATE' => \PHPCfg\Func::FLAG_PRIVATE,
                'FLAG_STATIC' => \PHPCfg\Func::FLAG_STATIC,
                'FLAG_ABSTRACT' => \PHPCfg\Func::FLAG_ABSTRACT,
                'FLAG_FINAL' => \PHPCfg\Func::FLAG_FINAL,
                'FLAG_RETURNS_REF' => \PHPCfg\Func::FLAG_RETURNS_REF,
                'FLAG_CLOSURE' => \PHPCfg\Func::FLAG_CLOSURE,
            ];
            $lcConst = strtoupper($constName);
            if (!isset($flags[$lcConst])) {
                return null;
            }
            $value = new Variable(Variable::TYPE_INTEGER);
            $value->int($flags[$lcConst]);

            return $value;
        }

        return $this->tryFoldNativePhpClassConstFetch(ltrim($className, '\\'), $constName);
    }

    /**
     * Fold class constants from already-loaded native PHP classes (bootstrap spine; #6221).
     */
    protected function tryFoldNativePhpClassConstFetch(string $className, string $constName): ?Variable
    {
        // ::class on bootstrap Internal handlers may not be loaded yet (#1492 spine compile).
        $autoload = 'class' === strtolower($constName);
        if (!class_exists($className, $autoload)) {
            return null;
        }
        // Host PHP may still expose the constant while our PROFILE marks it #[\Deprecated]
        // (e.g. DATE path DateTime::RFC7231 under PROFILE=8.5 on a Zend 8.2 host). Refuse
        // fold so VM/JIT emit E_USER_DEPRECATED at fetch (#28134).
        if ($this->vmClassConstFetchIsDeprecated($className, $constName)) {
            return null;
        }
        try {
            $ref = new \ReflectionClassConstant($className, $constName);
        } catch (\ReflectionException) {
            return null;
        }
        $raw = $ref->getValue();
        if (\is_int($raw)) {
            $value = new Variable(Variable::TYPE_INTEGER);
            $value->int($raw);

            return $value;
        }
        if (\is_bool($raw)) {
            $value = new Variable(Variable::TYPE_BOOLEAN);
            $value->bool($raw);

            return $value;
        }
        if (\is_float($raw)) {
            $value = new Variable(Variable::TYPE_FLOAT);
            $value->float($raw);

            return $value;
        }
        if (\is_string($raw)) {
            $value = new Variable(Variable::TYPE_STRING);
            $value->string($raw);

            return $value;
        }

        return null;
    }

    /** True when VM ClassEntry marks the constant #[\Deprecated] for the active profile. */
    private function vmClassConstFetchIsDeprecated(string $className, string $constName): bool
    {
        if (null === $this->vmContext) {
            return false;
        }
        $lc = strtolower(ltrim($className, '\\'));
        $entry = $this->vmContext->classes[$lc] ?? null;
        if (null === $entry) {
            return false;
        }
        $key = ClassConstName::key($constName);
        $meta = $entry->constDeprecated[$key] ?? null;
        if (null === $meta) {
            return false;
        }

        return $meta->emitsRuntimeNotice();
    }

    protected function pseudoClassInCompileScope(string $className, Block $block): bool
    {
        $lc = strtolower($className);
        if (!in_array($lc, ['self', 'parent', 'static'], true)) {
            return true;
        }
        if (null !== $this->compilingClassLc) {
            return true;
        }

        return null !== $block->func && null !== $block->func->class;
    }

    /**
     * Zend zend_compile.c — self/parent/static return & parameter types require class scope (#17480).
     *
     * @return never
     */
    protected function rejectPseudoClassTypeHintOutsideClassScope(?Op\Type $type, Block $block, CfgFunc $func): void
    {
        $keyword = PseudoClassTypeHintCompileCheck::findKeyword($type);
        if (null === $keyword) {
            return;
        }
        if ($this->pseudoClassInCompileScope($keyword, $block)) {
            return;
        }
        $callable = $func->callableOp;
        throw new CompileFatal(
            $callable instanceof Op ? ($callable->getFile() ?: 'unknown') : 'unknown',
            $callable instanceof Op ? max(1, $callable->getLine()) : 1,
            PseudoClassTypeHintCompileCheck::messageFor($keyword)
        );
    }

    protected function resolveDefaultClassConstScope(string $className, Block $block): ?string
    {
        $lc = strtolower($className);
        if ('self' === $lc || 'static' === $lc) {
            if (null !== $this->compilingClassLc) {
                return $this->compilingClassLc;
            }
            if (null !== $block->func && null !== $block->func->class) {
                $name = $this->staticNameFromOperand($block->func->class);

                return null !== $name ? strtolower(ltrim($name, '\\')) : null;
            }

            return null;
        }
        if ('parent' === $lc) {
            return null;
        }

        return strtolower(ltrim($className, '\\'));
    }

    /**
     * Fold {@code self::class} / {@code parent::class} / {@code Named::class} to the FQCN string
     * (Zend zend_compile.c class name resolution; #26629, #3803).
     *
     * {@code static::class} returns null — late-static binding needs the runtime opcode (#19614).
     * Trait {@code self::class} / {@code parent::class} also return null — Zend retargets them to
     * the composing class at use-time (#26659, #19629, Zend/zend_traits.c); folding the trait
     * name would bake the wrong string into method bodies (regression from #26629).
     */
    protected function resolveCompileTimeClassPseudoConstFqcn(string $className, Block $block): ?string
    {
        $lc = strtolower(ltrim($className, '\\'));
        if ('static' === $lc) {
            return null;
        }
        if ('self' === $lc) {
            $declLc = $this->declaringClassLcForTypeHint($block);
            if (null !== $declLc && $this->classCompileRegistry->isTrait($declLc)) {
                return null;
            }
            $display = $this->declaringClassDisplayNameForTypeHint($block);

            return null !== $display && '' !== $display ? $display : null;
        }
        if ('parent' === $lc) {
            $declLc = $this->declaringClassLcForTypeHint($block);
            if (null !== $declLc && $this->classCompileRegistry->isTrait($declLc)) {
                return null;
            }
            if (null !== $this->compilingClassLc) {
                $parent = $this->compilingClassParentDisplayName();
                if (null === $parent || '' === $parent) {
                    throw new CompileFatal(
                        'unknown',
                        1,
                        EnumParentCompileCheck::MESSAGE
                    );
                }

                return $parent;
            }

            return null;
        }

        return ltrim($className, '\\');
    }

    /**
     * Zend message when {@code static::class} appears in a property default (#26629).
     */
    protected function propertyDefaultStaticClassRejectMessage(Op\Stmt\Property $prop): ?string
    {
        $expr = null;
        if (null !== $prop->defaultBlock && [] !== $prop->defaultBlock->children) {
            $last = $prop->defaultBlock->children[\count($prop->defaultBlock->children) - 1];
            if ($last instanceof Op\Expr\ClassConstFetch) {
                $expr = $last;
            }
        }
        if (null === $expr) {
            $root = null !== $prop->defaultVar ? $this->unwrapOperandChain($prop->defaultVar) : null;
            if ($root instanceof Op\Expr\ClassConstFetch) {
                $expr = $root;
            }
        }
        if (null === $expr) {
            return null;
        }
        $constName = $this->staticNameFromOperand($expr->name);
        $className = $this->staticNameFromOperand($expr->class);
        if (null === $constName || null === $className) {
            return null;
        }
        if ('class' !== strtolower($constName) || 'static' !== strtolower($className)) {
            return null;
        }

        return 'static::class cannot be used for compile-time class name resolution';
    }

    protected function compileTimeClassConstFetchCallerLc(Block $block): ?string
    {
        if (null !== $this->compilingClassLc) {
            return $this->compilingClassLc;
        }
        if (null !== $block->func && null !== $block->func->class) {
            $name = $this->staticNameFromOperand($block->func->class);

            return null !== $name ? strtolower(ltrim($name, '\\')) : null;
        }

        return null;
    }

    /**
     * Whether a compile-time class const value may be constant-folded at this site (#6784).
     */
    protected function compileTimeClassConstFetchAllowed(
        string $declaringClassLc,
        string $constLc,
        Block $block
    ): bool {
        $vis = $this->compileTimeClassConstVisibility[$declaringClassLc][$constLc] ?? CfgFunc::FLAG_PUBLIC;
        if (MethodVisibility::isPublic($vis)) {
            return true;
        }
        try {
            ClassConstVisibility::assertAccessible(
                $vis,
                $this->compileTimeClassConstFetchCallerLc($block),
                $declaringClassLc,
                $this->classCompileRegistry->traitDisplayName($declaringClassLc),
                $constLc,
                fn (string $callerLc, string $ancestorLc): bool => $this->classCompileRegistry->isClassSubtypeOf(
                    $callerLc,
                    $ancestorLc
                )
            );
        } catch (\LogicException) {
            return false;
        }

        return true;
    }

    /**
     * Non-nullable declared type with `= null` default (php-src implicit nullable, #4449).
     */
    protected function paramIsImplicitNullable(Op\Expr\Param $param, ?int $defaultSlot, Block $block): bool
    {
        if (null === $defaultSlot || null === $param->declaredType) {
            return false;
        }
        if ($param->declaredType instanceof Op\Type\Nullable) {
            return false;
        }
        if ($this->cfgTypeUsesDnfShape($param->declaredType)) {
            return false;
        }
        $default = $block->constants[$defaultSlot] ?? null;

        return null !== $default && Variable::TYPE_NULL === $default->type;
    }

    /**
     * Zend 8.4 compile-time deprecation for implicit nullable typed parameters (#21390, #22987, #29274).
     *
     * Emits during CFG compile for both eval (VM running) and file-level parseAndCompile
     * (VM not running yet — use {@see $vmContext} from Runtime). Message is prefixed with the
     * Zend zend_error callable label ({@see displayCallableNameForCompileDeprecation()}).
     */
    protected function maybeEmitImplicitNullableParamDeprecation(
        Op\Expr\Param $param,
        ?int $defaultSlot,
        Block $block
    ): void {
        if (!CompilerVersion::supportsImplicitNullableParameterDeprecation()) {
            return;
        }
        if (!$this->paramIsImplicitNullable($param, $defaultSlot, $block)) {
            return;
        }

        $vm = VM::running();
        $context = $vm instanceof VM ? $vm->context : $this->vmContext;
        if (!$context instanceof VMContext) {
            return;
        }

        $paramName = $this->displayParamName($param);
        $callableName = $this->displayCallableNameForCompileDeprecation($block);
        $line = max(0, $param->getLine());
        $file = $block->scriptPath();
        if ('' === $file) {
            $file = $this->debugLastPhaseInputFile;
        }
        if (null === $file || '' === $file) {
            $file = null;
        }
        $frame = null;
        if ($vm instanceof VM) {
            $frame = $vm->builtinHandlerFrame();
            if (null === $frame) {
                $frames = $context->runStackFrames();
                $frame = [] !== $frames ? $frames[0] : null;
            }
        }
        if (null === $frame) {
            $frame = new Frame(null, $block, null);
            $frame->vmContext = $context;
            if (null !== $file) {
                $frame->scriptPath = $file;
            }
        }

        // Zend zend_compile.c / zend_error: "{func}(): Implicitly marking parameter $x …" (#29274).
        $context->errors->internalDeprecated(
            sprintf(
                '%s(): Implicitly marking parameter %s as nullable is deprecated, the explicit nullable type must be used instead',
                $callableName,
                $paramName
            ),
            $context,
            $frame,
            $file,
            $line
        );
    }

    /**
     * Zend zend_error-style callable label for compile-time deprecations (#29274).
     *
     * Named function → {@code f}; method → {@code C::m}; closure/arrow on PROFILE≥8.4 →
     * {@code {closure:file:line}} (same shape as Closure::__debugInfo); else {@code {closure}}.
     */
    protected function displayCallableNameForCompileDeprecation(Block $block): string
    {
        $func = $block->func;
        if (null === $func || !\is_string($func->name) || '' === $func->name || '{main}' === $func->name) {
            return '{closure}';
        }
        $name = $func->name;
        if (str_starts_with($name, '{anonymous}') || str_starts_with($name, '{closure}')) {
            if (CompilerVersion::supportsClosureRichDebugInfo()) {
                $callable = $func->callableOp ?? null;
                if ($callable instanceof Op) {
                    $file = $callable->getFile();
                    $line = max(0, (int) $callable->getLine());
                    if (\is_string($file) && '' !== $file && $line > 0) {
                        return '{closure:'.$file.':'.$line.'}';
                    }
                }
            }

            return '{closure}';
        }
        if (null !== $func->class) {
            $class = $this->staticNameFromOperand($func->class);
            if ((null === $class || '' === $class) && null !== $this->compilingClassDisplayName) {
                $class = $this->compilingClassDisplayName;
            }
            if (null !== $class && '' !== $class) {
                return ltrim($class, '\\').'::'.$name;
            }
        }

        return $name;
    }

    private function displayParamName(Op\Expr\Param $param): string
    {
        if ($param->name instanceof Operand\Literal && is_string($param->name->value) && '' !== $param->name->value) {
            return '$'.$param->name->value;
        }

        return '$?';
    }

    /**
     * Zend zend_compile.c: property/param defaults must match declared type (#5347, #6558).
     */
    protected function assertParamDefaultMatchesDeclaredType(Op\Expr\Param $param, ?int $defaultSlot, Block $block): void
    {
        if (null === $defaultSlot || null === $param->declaredType) {
            return;
        }
        $default = $block->constants[$defaultSlot] ?? null;
        if (null === $default) {
            return;
        }
        $paramName = '?';
        if ($param->name instanceof Operand\Literal && is_string($param->name->value)) {
            $paramName = '$'.$param->name->value;
        }
        $this->assertCompileTimeDefaultMatchesDeclaredType(
            $default,
            $param->declaredType,
            'parameter',
            $paramName,
            $block,
            $defaultSlot,
            $param
        );
    }

    /**
     * Zend zend_compile.c — zend_verify_const_expr_type() for property/param defaults (#6558).
     */
    protected function assertCompileTimeDefaultMatchesDeclaredType(
        Variable $default,
        ?Op\Type $declaredType,
        string $kind,
        string $targetName,
        ?Block $block = null,
        ?int $defaultSlot = null,
        ?Op\Expr\Param $param = null
    ): void {
        if (null === $declaredType) {
            return;
        }

        $value = $default->resolveIndirect();

        if ($declaredType instanceof Op\Type\Mixed_) {
            return;
        }
        if ($declaredType instanceof Op\Type\Literal && 'mixed' === strtolower($declaredType->name)) {
            return;
        }

        if (
            'parameter' === $kind
            && null !== $param
            && null !== $defaultSlot
            && null !== $block
            && $this->paramIsImplicitNullable($param, $defaultSlot, $block)
        ) {
            return;
        }

        $checkType = $declaredType;
        if ($declaredType instanceof Op\Type\Nullable) {
            if (Variable::TYPE_NULL === $value->type) {
                return;
            }
            $checkType = $declaredType->subtype;
        }

        if (
            $this->cfgTypeUsesDnfShape($checkType)
            || $checkType instanceof Op\Type\Union
            || $checkType instanceof Op\Type\Intersection
        ) {
            return;
        }

        $typeLabel = $this->declNameFromCfgType($checkType) ?? 'mixed';

        if ($checkType instanceof Op\Type\Literal) {
            $nameLc = strtolower($checkType->name);
            if ('true' === $nameLc || 'false' === $nameLc) {
                if (Variable::TYPE_BOOLEAN === $value->type && $value->toBool() === ('true' === $nameLc)) {
                    return;
                }
                $given = TypeCheck::typeNameForConstraint($value->type);
                $this->throwTypedDefaultMismatch($given, $kind, $targetName, $nameLc);

                return;
            }
        }

        if ($value->is(Variable::TYPE_ARRAY)) {
            if ($checkType instanceof Op\Type\Literal) {
                $nameLc = strtolower($checkType->name);
                if ('array' === $nameLc || 'iterable' === $nameLc) {
                    return;
                }
            }
            if (null !== $this->genericArraySpecFromCfgType($checkType)) {
                return;
            }
            $this->throwTypedDefaultMismatch('array', $kind, $targetName, $typeLabel);

            return;
        }

        if ($checkType instanceof Op\Type\Literal && $this->compileTimeDefaultMatchesLiteralType($value, strtolower($checkType->name))) {
            return;
        }

        $classOrScalarName = $this->declNameFromCfgType($checkType);
        if (null !== $classOrScalarName && null !== $block) {
            $resolvedClass = $this->resolveTypeHintClassName($classOrScalarName, $block);
            if (null !== $resolvedClass && '' !== $resolvedClass) {
                $classOrScalarName = $resolvedClass;
            }
        }
        if (
            null !== $classOrScalarName
            && $this->compileTimeDefaultMatchesLiteralType($value, strtolower($classOrScalarName))
        ) {
            return;
        }

        $given = TypeCheck::typeNameForConstraint($value->type);
        $this->throwTypedDefaultMismatch($given, $kind, $targetName, $typeLabel);
    }

    protected function throwTypedDefaultMismatch(string $given, string $kind, string $targetName, string $typeLabel): void
    {
        $this->throwCompileError(
            "Cannot use {$given} as default value for {$kind} {$targetName} of type {$typeLabel}"
        );
    }

    protected function compileTimeDefaultMatchesLiteralType(Variable $value, string $typeNameLc): bool
    {
        switch ($typeNameLc) {
            case 'int':
                return $value->is(Variable::TYPE_INTEGER);
            case 'float':
                return $value->is(Variable::TYPE_FLOAT) || $value->is(Variable::TYPE_INTEGER);
            case 'string':
                return $value->is(Variable::TYPE_STRING);
            case 'bool':
                return $value->is(Variable::TYPE_BOOLEAN);
            case 'array':
                return $value->is(Variable::TYPE_ARRAY);
            case 'iterable':
                return $value->is(Variable::TYPE_ARRAY);
            case 'null':
                return $value->is(Variable::TYPE_NULL);
            default:
                return $this->compileTimeDefaultMatchesClassType($value, $typeNameLc);
        }
    }

    protected function compileTimeDefaultMatchesClassType(Variable $value, string $expectedClassLc): bool
    {
        $value = $value->resolveIndirect();
        $expectedClassLc = strtolower(ltrim($expectedClassLc, '\\'));

        if (Variable::TYPE_ENUM_CASE === $value->type) {
            return strtolower(ltrim($value->toEnumCase()->enumClass->name, '\\')) === $expectedClassLc;
        }
        if (Variable::TYPE_OBJECT === $value->type) {
            $obj = $value->toObject();
            if (EnumCaseSupport::isEnumCase($obj)) {
                return strtolower(ltrim($obj->class->name, '\\')) === $expectedClassLc;
            }

            return strtolower(ltrim($obj->class->name, '\\')) === $expectedClassLc;
        }

        return false;
    }

    protected function compileParam(Op\Expr\Param $param, Block $block, int $paramIdx): OpCode {
        if ($param->byRef) {
            $block->paramByRef[$paramIdx] = true;
        }
        if ($param->variadic) {
            assert(null === $param->defaultVar);
            if (null !== $block->variadicParamIndex) {
                $this->throwCompileLogic('Only one variadic parameter is allowed per function');
            }
            $block->variadicParamIndex = $paramIdx;
        }
        $defaultConst = $this->resolvePropertyOrParamDefaultSlot($param, $block, $paramIdx);
        $slot = $this->compileOperand($param->result, $block, false);
        if ($param->name instanceof Operand\Literal && is_string($param->name->value)) {
            $block->paramNames[$paramIdx] = $param->name->value;
        }
        if (AttributeNames::isSensitiveParameter(AttributeNames::fromOp($param))) {
            $block->paramSensitive[$paramIdx] = true;
        }
        $defaultConstantName = $this->paramDefaultConstantName($param);
        if (null !== $defaultConstantName) {
            $block->paramDefaultConstantNames[$paramIdx] = $defaultConstantName;
        }
        $this->applyParamDeclaredType($param, $block, $slot, $param->variadic);
        $this->assertParamDefaultMatchesDeclaredType($param, $defaultConst, $block);
        if ($this->paramIsImplicitNullable($param, $defaultConst, $block)) {
            $block->paramImplicitNullable[$slot] = true;
        }
        $this->maybeEmitImplicitNullableParamDeprecation($param, $defaultConst, $block);

        $recv = new OpCode(
            OpCode::TYPE_ARG_RECV,
            $slot,
            $paramIdx,
            $defaultConst
        );
        // Param declaration line for user-arg TypeError Exception::$line (#29023).
        $recv->sourceLocation = SourceLocation::fromOp($param);

        return $recv;
    }

    /**
     * Constant-fetch default name for ReflectionParameter (#22026, zim_reflection_parameter_*).
     * true/false/null and ::class are not constant defaults (php-src).
     */
    protected function paramDefaultConstantName(Op\Expr\Param $param): ?string
    {
        $expr = $this->paramDefaultConstFetchExpr($param);
        if ($expr instanceof Op\Expr\ConstFetch) {
            $name = $this->staticNameFromOperand($expr->name);
            if (null === $name || '' === $name) {
                return null;
            }
            $name = ltrim($name, '\\');
            $lc = strtolower($name);
            if ('true' === $lc || 'false' === $lc || 'null' === $lc) {
                return null;
            }

            return $name;
        }
        if ($expr instanceof Op\Expr\ClassConstFetch) {
            $constName = $this->staticNameFromOperand($expr->name);
            $className = $this->staticNameFromOperand($expr->class);
            if (null === $constName || null === $className || '' === $constName || '' === $className) {
                return null;
            }
            if ('class' === strtolower($constName)) {
                return null;
            }

            return ltrim($className, '\\').'::'.$constName;
        }

        return null;
    }

    /**
     * @return Op\Expr\ConstFetch|Op\Expr\ClassConstFetch|null
     */
    protected function paramDefaultConstFetchExpr(Op\Expr\Param $param): ?Op\Expr
    {
        if (null !== $param->defaultBlock && [] !== $param->defaultBlock->children) {
            $last = $param->defaultBlock->children[\count($param->defaultBlock->children) - 1];
            if ($last instanceof Op\Expr\ConstFetch || $last instanceof Op\Expr\ClassConstFetch) {
                return $last;
            }
            if ($last instanceof Op\Expr\Assign
                && ($last->expr instanceof Op\Expr\ConstFetch || $last->expr instanceof Op\Expr\ClassConstFetch)
            ) {
                return $last->expr;
            }
        }
        $unwrapped = null !== $param->defaultVar ? $this->unwrapOperandChain($param->defaultVar) : null;
        if ($unwrapped instanceof Op\Expr\ConstFetch || $unwrapped instanceof Op\Expr\ClassConstFetch) {
            return $unwrapped;
        }

        return null;
    }

    protected function compileFunction(Op\Stmt\Function_ $function, Block $block): OpCode {
        $funcBlock = $this->compileCfgBlock($function->func->cfg, $function->func->params, $function->func);
        NoDiscardMetadata::applyToBlock($funcBlock, $function);
        DeprecatedMetadata::applyToBlock($funcBlock, $function);
        $this->markGeneratorIfNeeded($function, $funcBlock);
        $funcLc = strtolower($function->func->name);
        if ($this->funcDeclReturnTypeIsNever($function->func)) {
            $this->neverFunctionNames[$funcLc] = true;
        }
        foreach ($function->func->params as $paramIdx => $param) {
            if ($param->byRef) {
                $this->userFunctionParamByRef[$funcLc][(int) $paramIdx] = true;
            }
        }
        $operand = new Operand\Literal($function->func->name);
        $operand->type = Type::string();
        $return = new OpCode(
            OpCode::TYPE_FUNCDEF,
            $this->compileOperand($operand, $block, true)
        );
        $return->block1 = $funcBlock;
        $return->deprecatedMetadata = DeprecatedMetadata::fromOp($function);
        $return->parameterMetadata = $this->parameterMetadataFromParams($function->func->params, $function->func);
        $this->assignAttributeMetadata($return, $function);
        $this->assignSourceMetadata($return, $function);
        AttributeNames::assertAllowDynamicPropertiesClassTargetOnly($return->attributeNames, 'function', $return->attributeEntries);
        AttributeNames::assertAttributeMetaClassTargetOnly($return->attributeNames, 'function', $return->attributeEntries);
        AttributeNames::assertCompileTimeConstTargetOnly($return->attributeNames, 'function', $return->attributeEntries);
        AttributeNames::assertSensitiveParameterParamTargetOnly($return->attributeNames, 'function', $return->attributeEntries);
        AttributeNames::assertReturnTypeWillChangeMethodTargetOnly($return->attributeNames, 'function', $return->attributeEntries);
        AttributeNames::assertDeprecatedTargetAllowed($return->attributeNames, 'function', $return->attributeEntries);
        return $return;
    }

    /**
     * Emit FUNCDEF for Zend early-bound file-level decls at {main} entry (#24807).
     *
     * Declarations nested in if/else/try/catch/finally/switch/loop stay at their CFG site
     * (runtime registration when that path runs). Merge blocks after try/if that hold a
     * top-level `function` are early-bound — matching zend_compile.c for non-conditional decls.
     *
     * php-cfg's ClassMethod extends Function_, and ClassLike::getSubBlocks() exposes the
     * class stmts block — so a naive instanceof Function_ walk also picks up interface/abstract
     * methods (null cfg) and concrete methods. Exact-class match only; methods stay on the
     * DECLARE_METHOD path (#24836 TypeError / prior SIGSEGV on ext/spl spine chunks).
     */
    private function emitEarlyBoundFunctionDefs(CfgBlock $entry, Block $dest): void
    {
        $delayed = $this->collectDelayedDeclarationCfgBlocks($entry);
        /** @var list<Op\Stmt\Function_> $funcs */
        $funcs = [];
        $seenBlocks = new SplObjectStorage();
        $queue = [$entry];
        while ([] !== $queue) {
            $cfg = array_shift($queue);
            if ($seenBlocks->contains($cfg)) {
                continue;
            }
            $seenBlocks[$cfg] = true;
            foreach ($cfg->children as $child) {
                // ClassMethod extends Function_ — do not early-bind methods as FUNCDEF (#24836).
                if (
                    Op\Stmt\Function_::class === \get_class($child)
                    && !$delayed->contains($cfg)
                ) {
                    $funcs[] = $child;
                }
                // Do not walk into class/interface/trait/enum bodies — only file-level decls.
                if ($child instanceof Op\Stmt\ClassLike) {
                    continue;
                }
                foreach ($this->cfgOpSuccessorBlocks($child) as $succ) {
                    $queue[] = $succ;
                }
            }
        }
        usort(
            $funcs,
            static function (Op\Stmt\Function_ $a, Op\Stmt\Function_ $b): int {
                return ((int) ($a->getAttribute('startLine') ?? 0))
                    <=> ((int) ($b->getAttribute('startLine') ?? 0));
            }
        );
        foreach ($funcs as $fn) {
            $this->earlyBoundFunctionOps[$fn] = true;
            $dest->addOpCode($this->compileFunction($fn, $dest));
        }
    }

    /**
     * CFG blocks that are exclusive bodies of delayed declaration contexts (Zend: not early-bound).
     *
     * @return SplObjectStorage
     */
    private function collectDelayedDeclarationCfgBlocks(CfgBlock $entry): SplObjectStorage
    {
        $delayed = new SplObjectStorage();
        $seenBlocks = new SplObjectStorage();
        $queue = [$entry];
        while ([] !== $queue) {
            $cfg = array_shift($queue);
            if ($seenBlocks->contains($cfg)) {
                continue;
            }
            $seenBlocks[$cfg] = true;
            foreach ($cfg->children as $child) {
                if ($child instanceof Op\Stmt\JumpIf) {
                    $this->markDelayedDeclBlockIfExclusiveArm($delayed, $child->if);
                    $this->markDelayedDeclBlockIfExclusiveArm($delayed, $child->else);
                } elseif ($child instanceof Op\Stmt\TryCatch) {
                    $delayed[$child->try] = true;
                    foreach ($child->catches as $catchBlock) {
                        if ($catchBlock instanceof CfgBlock) {
                            $delayed[$catchBlock] = true;
                        }
                    }
                    if ($child->finally instanceof CfgBlock) {
                        $delayed[$child->finally] = true;
                    }
                    if ($child->else instanceof CfgBlock) {
                        $delayed[$child->else] = true;
                    }
                } elseif ($child instanceof Op\Stmt\Switch_) {
                    foreach ($child->targets as $target) {
                        $this->markDelayedDeclBlockIfExclusiveArm($delayed, $target);
                    }
                    $this->markDelayedDeclBlockIfExclusiveArm($delayed, $child->default);
                }
                foreach ($this->cfgOpSuccessorBlocks($child) as $succ) {
                    $queue[] = $succ;
                }
            }
        }

        return $delayed;
    }

    /**
     * Exclusive branch/case arm (single CFG parent) — not a merge that also continues top-level code.
     *
     * @param SplObjectStorage $delayed
     */
    private function markDelayedDeclBlockIfExclusiveArm(SplObjectStorage $delayed, ?CfgBlock $arm): void
    {
        if (!$arm instanceof CfgBlock) {
            return;
        }
        if (\count($arm->parents) < 2) {
            $delayed[$arm] = true;
        }
    }

    /** @return list<CfgBlock> */
    private function cfgOpSuccessorBlocks(Op $op): array
    {
        if (!method_exists($op, 'getSubBlocks')) {
            return [];
        }
        $out = [];
        foreach ($op->getSubBlocks() as $name) {
            // Gen-0/nikic rejects variable-property syntax — use OpSubBlockAccess (re-#10067 / #24877).
            $val = OpSubBlockAccess::propertyValue($op, $name);
            if ($val instanceof CfgBlock) {
                $out[] = $val;
            } elseif (\is_array($val)) {
                foreach ($val as $block) {
                    if ($block instanceof CfgBlock) {
                        $out[] = $block;
                    }
                }
            }
        }

        return $out;
    }

    protected function compileOp(Op $op, Block $block) {
        if ($op instanceof Op\Expr\ConcatList) {
            $total = count($op->list);
            $return = $this->freshConcatResultSlotIfCatchAlias(
                $this->compileOperand($op->result, $block, false),
                $block,
                $op->result
            );
            if (0 === $total) {
                $empty = new Operand\Literal('');
                $empty->type = Type::string();
                $emptySlot = $this->compileOperand($empty, $block, true);
                $block->addOpCode(new OpCode(
                    OpCode::TYPE_ASSIGN,
                    $return,
                    $return,
                    $emptySlot
                ));
            } elseif (1 === $total) {
                // Zend string context for a lone encapsed variable (#4785) — not a plain assign.
                $part = $this->compileConcatListPart($op->list[0], $block);
                $block->addOpCode(new OpCode(
                    OpCode::TYPE_CAST_STRING,
                    $return,
                    $part
                ));
            } else {
                // Encapsed ConcatList used to emit in-place CONCAT($return, $return, $right).
                // Reusing one dead-temp slot for every link intermittently heap-corrupts under
                // AOT once three or more variables are interpolated (#23842). Match explicit
                // `$a . " " . $b . …`: a fresh destination per link.
                $acc = $this->compileConcatListPart($op->list[0], $block);
                for ($i = 1; $i < $total; $i++) {
                    $right = $this->compileConcatListPart($op->list[$i], $block);
                    $isLast = ($i === $total - 1);
                    $dest = $isLast
                        ? $return
                        : $block->forceFreshVarSlot(new Temporary());
                    $block->addOpCode(new OpCode(
                        OpCode::TYPE_CONCAT,
                        $dest,
                        $acc,
                        $right
                    ));
                    $acc = $dest;
                }
            }
        } elseif ($op instanceof Op\Expr) {
            $block->addOpCode(...$this->compileExpr($op, $block));
            if (
                $op instanceof Op\Expr\PropertyFetch
                && !$this->isPropertyFetchForWrite($op, $block)
            ) {
                $this->syncPropertyFetchResultToFollowingFuncCallArg($op, $block);
            }
        } elseif ($op instanceof Op\Stmt) {
            $this->compileStmt($op, $block);
        } elseif ($op instanceof Op\Terminal) {
            $terminalOps = $this->compileTerminal($op, $block);
            foreach ($terminalOps as $terminalOp) {
                $block->addOpCode($terminalOp);
            }
        } else {
            $this->throwCompileLogicForOp($op, 'Unknown Op Type: '.opcode_type_name($op->type));
        }
    }

    protected function compileStmt(Op\Stmt $stmt, Block $block) {
        if ($stmt instanceof Op\Stmt\Jump) {
            $target = $this->compileCfgBranch($stmt->target, $block);
            if (!$this->isRedundantTryEntryJump($block, $target)) {
                $op = new OpCode(OpCode::TYPE_JUMP);
                $op->block1 = $target;
                $block->addOpCode($op);
            }
        } elseif ($stmt instanceof Op\Stmt\JumpIf) {
            if (null !== ($paramOp = $this->nullableParamFromReturnTernaryArms($stmt, $block))) {
                $this->emitImplicitNullableParamCoalesceReturn($paramOp, $block);

                return;
            }
            $rewriteNeNull = $this->rewrittenNeNullReturnJumpIf->contains($stmt);
            // Capture before compiling arms: braced declare attaches LeaveTickInterval to the
            // while/for exit block, which would clear activeTickInterval (#25621).
            $emitLoopExitTick = $this->activeTickInterval > 0
                && $stmt->hasAttribute('zend_loop_exit_tick')
                && $stmt->getAttribute('zend_loop_exit_tick');
            $op = new OpCode(OpCode::TYPE_JUMPIF, $this->compileOperand($stmt->cond, $block, true));
            if ($rewriteNeNull) {
                $op->block1 = $this->compileCfgBranch($stmt->else, $block);
                $op->block2 = $this->compileCfgBranch($stmt->if, $block);
            } elseif ($this->jumpIfTargetsLogicalOrShortCircuitLiteralIf($stmt)) {
                // `||` literal-true arm must reuse bool-cast phi slot from the long arm (#12745).
                $op->block2 = $this->compileCfgBranch($stmt->else, $block);
                $op->block1 = $this->compileCfgBranch($stmt->if, $block);
            } elseif ($this->jumpIfTargetsLogicalAndShortCircuitCastIf($stmt)) {
                // `&&` literal-false arm must reuse bool-cast phi from the long (if) arm (#24506).
                // Do not take ternary else-first order — that seeds phi before `$x = …` and aliases slots.
                $op->block1 = $this->compileCfgBranch($stmt->if, $block);
                $op->block2 = $this->compileCfgBranch($stmt->else, $block);
            } elseif ($this->jumpIfTargetsTernaryMerge($stmt)) {
                // Lower else before if so merge blocks record both branch phi slots (#3790, #5510).
                $op->block2 = $this->compileCfgBranch($stmt->else, $block);
                $op->block1 = $this->compileCfgBranch($stmt->if, $block);
            } else {
                $op->block1 = $this->compileCfgBranch($stmt->if, $block);
                $op->block2 = $this->compileCfgBranch($stmt->else, $block);
            }
            // Zend zend_compile_stmt emits ZEND_TICKS after while/for/do-while on the
            // fallthrough (loop exit) path — php-src Zend/zend_compile.c (#25621).
            if ($emitLoopExitTick) {
                $elseCompiled = $this->seen[$stmt->else] ?? null;
                if ($elseCompiled instanceof Block) {
                    $wrapped = $this->wrapBlockWithLoopExitTick($elseCompiled);
                    if ($op->block1 === $elseCompiled) {
                        $op->block1 = $wrapped;
                    }
                    if ($op->block2 === $elseCompiled) {
                        $op->block2 = $wrapped;
                    }
                }
            }
            $block->addOpCode($op);
        } elseif ($stmt instanceof Op\Stmt\TryCatch) {
            // Reserve catch \$e slots before merge lowering allocates sibling temps (#9887).
            $reservedCatchVarSlots = [];
            foreach ($stmt->catches as $i => $catchBlock) {
                $catchVar = $stmt->catchVars[$i] ?? null;
                if (null !== $catchVar && null !== $this->resolveCatchVariableName($catchVar)) {
                    $reservedCatchVarSlots[$i] = $block->getVarSlot($catchVar, false);
                }
            }
            $merge = $this->compileCfgBranch($stmt->end, $block);
            $merge = $this->splitMergeBeforeNestedTry($merge);
            // Merge block is entered via TYPE_CATCH before catch locals exist (#195, #2084).
            $merge->inheritUndefinedLocals = true;
            // Lower catch bodies before try so sibling ?: merge prebind cannot clobber try locals (#6411).
            $compiledCatches = [];
            $savedCatchVarSlots = $this->activeCatchVarSlotsByName;
            $savedCatchVarRoots = $this->activeCatchVarRoots;
            $this->activeCatchVarSlotsByName = [];
            $this->activeCatchVarRoots = [];
            foreach ($stmt->catches as $i => $catchBlock) {
                $catchVar = $stmt->catchVars[$i] ?? null;
                $catchName = $this->resolveCatchVariableName($catchVar);
                if (null !== $catchName && isset($reservedCatchVarSlots[$i])) {
                    $lc = strtolower($catchName);
                    $this->activeCatchVarSlotsByName[$lc] = $reservedCatchVarSlots[$i];
                    $root = Block::cfgVarRoot($catchVar);
                    if (null !== $root) {
                        $this->activeCatchVarRoots[] = $root;
                    }
                }
            }
            foreach ($stmt->catches as $i => $catchBlock) {
                $compiledCatch = $this->compileCfgBranch($catchBlock, $block);
                $compiledCatch->inheritUndefinedLocals = true;
                $compiledCatches[] = $compiledCatch;
            }
            $this->activeCatchVarSlotsByName = $savedCatchVarSlots;
            $this->activeCatchVarRoots = $savedCatchVarRoots;
            $try = $this->compileCfgBranch($stmt->try, $block);
            $try->inheritUndefinedLocals = true;
            $tryOp = new OpCode(OpCode::TYPE_TRY);
            $tryOp->block1 = $try;
            $tryOp->block2 = $merge;
            $block->addOpCode($tryOp);
            foreach ($compiledCatches as $i => $compiledCatch) {
                $catchOp = new OpCode(OpCode::TYPE_CATCH);
                $catchOp->block1 = $compiledCatch;
                $catchOp->block2 = $merge;
                $catchOp->catchTypes = $this->encodeCatchTypeList($stmt->catchTypes[$i] ?? []);
                $catchOp->arg3 = $this->resolveCatchVarSlot(
                    $compiledCatch,
                    $stmt->catchVars[$i] ?? null
                ) ?? ($reservedCatchVarSlots[$i] ?? null);
                $block->addOpCode($catchOp);
            }
            if (null !== $stmt->finally) {
                $compiledFinally = $this->compileCfgBranch($stmt->finally, $block);
                // Catch runs before finally on throw; finally block must not inherit catch locals (#195).
                $compiledFinally->inheritUndefinedLocals = true;
                $finallyOp = new OpCode(OpCode::TYPE_FINALLY);
                $finallyOp->block1 = $compiledFinally;
                $finallyOp->block2 = $merge;
                $block->addOpCode($finallyOp);
                $this->rewriteMergeJumpsToFinally($try, $merge, $compiledFinally);
                if (property_exists($stmt, 'else')
                    && null !== $stmt->else
                    && isset($this->seen[$stmt->else])) {
                    $this->rewriteMergeJumpsToFinally($this->seen[$stmt->else], $merge, $compiledFinally);
                }
            }
        } elseif ($stmt instanceof Op\Stmt\Switch_) {
            $this->compileSwitchAsJumpIfChain($stmt, $block);
        } elseif ($stmt instanceof Op\Stmt\HaltCompiler) {
            if (null === $this->haltCompilerRemaining) {
                $this->haltCompilerRemaining = $stmt->remaining;
                $this->haltCompilerOffset = $stmt->haltOffset;
            }
            $block->addOpCode(new OpCode(OpCode::TYPE_RETURN_VOID));
        } else {
            $this->throwCompileLogicForOp($stmt, 'Unknown Stmt Type: '.$stmt->getType());
        }
    }

    /** php-cfg: {@see ErrorSuppressBlock} jump target where silenced reads are lowered (#3546). */
    private function isErrorSuppressEndBlock(CfgBlock $block): bool
    {
        if (1 !== \count($block->parents)) {
            return false;
        }
        $parent = $block->parents[0];

        return $parent instanceof ErrorSuppressBlock;
    }

    /**
     * php-cfg {@see ErrorSuppressBlock}: inner expr result is produced in the suppress branch but
     * consumed in the post-suppress block; inheritScopeFrom alone can miss unnamed SSA temps (#10336).
     */
    private function inheritErrorSuppressExpressionSlots(Block $suppressCompiled, Block $endCompiled): void
    {
        $suppressCfg = $suppressCompiled->orig;
        if (!$suppressCfg instanceof ErrorSuppressBlock) {
            return;
        }
        $endCfg = $endCompiled->orig;
        $primary = $this->findErrorSuppressPrimaryInnerExpr($suppressCfg);
        if (null === $primary || !isset($primary->result)) {
            return;
        }
        $this->inheritErrorSuppressByRefCallArgSlots($suppressCompiled, $endCompiled, $primary);
        $slot = $suppressCompiled->slotForOperand($primary->result);
        if (null === $slot) {
            $slot = $this->findFuncCallExecReturnSlot($suppressCompiled);
        }
        if (null === $slot) {
            $slot = $this->findIncludeReturnSlot($suppressCompiled);
        }
        if (null === $slot && $primary instanceof Op\Expr\ArrayDimFetch) {
            $slot = $this->compiledArrayDimFetchResultSlotBeforePendingFuncCall($suppressCompiled, 0);
        }
        if (null === $slot && ($primary instanceof Op\Expr\Isset_ || $primary instanceof Op\Expr\Empty_)) {
            $slot = $this->slotForEmittedIssetOrEmptyProducer($suppressCompiled, $primary);
        }
        if (null === $slot) {
            return;
        }
        $suppressResult = $primary->result;
        if ($this->errorSuppressEndBlockDiscardsInnerResultForErrorGetLast($endCompiled)) {
            return;
        }
        if (!$this->endBlockAssignsErrorGetLastAfterSuppress($endCfg)) {
            $endCompiled->forceBindScopeSlot($suppressResult, $slot);
        }
        $root = Block::cfgVarRoot($suppressResult);
        if (
            null !== $root
            && !$this->endBlockAssignsErrorGetLastAfterSuppress($endCfg)
            && !$this->shouldSkipPrebindCfgVarRootForSuppressResult($endCompiled, $endCfg, $suppressResult)
        ) {
            $endCompiled->prebindCfgVarRoot($root, $slot);
        }
        foreach ($suppressResult->usages as $usage) {
            if (
                !$usage instanceof Op\Expr\FuncCall
                && !$usage instanceof Op\Expr\NsFuncCall
                && !$usage instanceof Op\Expr\MethodCall
                && !$usage instanceof Op\Expr\StaticCall
                && !$usage instanceof Op\Expr\New_
            ) {
                continue;
            }
            if (property_exists($usage, 'args') && is_array($usage->args)) {
                foreach ($usage->args as $arg) {
                    if ($arg instanceof Operand) {
                        $endCompiled->forceBindScopeSlot($arg, $slot);
                    }
                }
            }
        }
        if (null !== $endCfg) {
            foreach ($endCfg->children as $endChild) {
                if (
                    !$endChild instanceof Op\Expr\FuncCall
                    && !$endChild instanceof Op\Expr\NsFuncCall
                    && !$endChild instanceof Op\Expr\MethodCall
                    && !$endChild instanceof Op\Expr\StaticCall
                ) {
                    continue;
                }
                if (!property_exists($endChild, 'args') || !is_array($endChild->args)) {
                    continue;
                }
                foreach ($endChild->args as $arg) {
                    if (
                        !$arg instanceof Operand
                        || $arg instanceof Operand\Literal
                        || $arg instanceof Operand\NullOperand
                    ) {
                        continue;
                    }
                    if (null !== Block::cfgVarRoot($arg)) {
                        if ($this->operandsReferToSameVariable($arg, $suppressResult)) {
                            $endCompiled->forceBindScopeSlot($arg, $slot);
                        }

                        continue;
                    }
                    // PhiResolver can replace the suppress inner result with an unrelated temp (#10336).
                    if (
                        $this->callInErrorSuppressEndBlockUsesInnerResultAsArg($endCompiled, $endChild)
                        && $this->callArgIsErrorSuppressForwardedResult($arg, $endCompiled)
                    ) {
                        $endCompiled->forceBindScopeSlot($arg, $slot);
                    }
                }
            }
            foreach ($endCfg->children as $endChild) {
                $this->bindErrorSuppressResultOperandUsages($endChild, $endCompiled, $suppressResult, $slot);
            }
            foreach ($endCfg->children as $endChild) {
                if (
                    !$endChild instanceof Op\Expr\FuncCall
                    && !$endChild instanceof Op\Expr\NsFuncCall
                ) {
                    continue;
                }
                if (!property_exists($endChild, 'args') || !is_array($endChild->args)) {
                    continue;
                }
                foreach ($endChild->args as $argIndex => $arg) {
                    if (
                        !$arg instanceof Operand
                        || $this->isEmbeddedCallLiteralArg($arg)
                        || !$this->callArgIsDeadInlineTemporary($arg)
                        || $this->callArgOpsContainInlineClosure($arg)
                    ) {
                        continue;
                    }
                    if (
                        $this->errorSuppressEndBlockCallArgHasTrailingIncludeProducer($endCompiled, $endChild, (int) $argIndex)
                        || $this->errorSuppressEndBlockCallArgHasTrailingHoistedScalarProducer($endCompiled, $endChild, (int) $argIndex)
                        || $this->errorSuppressEndBlockCallArgHasTrailingHoistedArrayProducer($endCompiled, $endChild, (int) $argIndex)
                        || $this->errorSuppressEndBlockCallArgHasTrailingArrayDimFetchProducer($endCompiled, $endChild, (int) $argIndex)
                        || $this->errorSuppressEndBlockCallArgHasAdjacentNestedFuncCallProducer($endCompiled, $endChild, (int) $argIndex)
                        || $this->errorSuppressEndBlockCallArgHasAdjacentNestedNewProducer($endCompiled, $endChild, (int) $argIndex)
                        || $this->callArgInlineProducerIsNew($endChild, (int) $argIndex, $endCompiled)
                        || $this->errorSuppressEndBlockCallArgHasTrailingComparisonProducer($endCompiled, $endChild, (int) $argIndex)
                        || $this->errorSuppressEndBlockCallArgHasTrailingConcatProducer($endCompiled, $endChild, (int) $argIndex)
                        || $this->errorSuppressEndBlockCallArgHasTrailingClosureProducer($endCompiled, $endChild, (int) $argIndex)
                        || $this->errorSuppressEndBlockCallArgHasTrailingBitmaskProducer($endCompiled, $endChild, (int) $argIndex)
                    ) {
                        continue;
                    }
                    // First dead temp in the outer call is the @ inner value (#15916, #10302).
                    $endCompiled->forceBindScopeSlot($arg, $slot);
                    break;
                }
            }
        }
    }

    /**
     * `@` on builtins with by-ref out args must keep errno/errstr slots after END_SILENCE (#9320, #10336).
     */
    private function inheritErrorSuppressByRefCallArgSlots(
        Block $suppressCompiled,
        Block $endCompiled,
        Op $primary
    ): void {
        if (
            !$primary instanceof Op\Expr\FuncCall
            && !$primary instanceof Op\Expr\NsFuncCall
        ) {
            return;
        }
        if (!property_exists($primary, 'args') || !\is_array($primary->args)) {
            return;
        }
        $name = $this->resolveCfgFuncCallName($primary);
        if (null === $name) {
            return;
        }
        foreach (BuiltinByRefParams::forFunction($name) as $argIndex) {
            $arg = $primary->args[$argIndex] ?? null;
            if (!$arg instanceof Operand) {
                continue;
            }
            $slot = $this->errorSuppressByRefArgSendSlot($suppressCompiled, $primary, (int) $argIndex)
                ?? $suppressCompiled->slotForOperand($arg);
            if (null === $slot) {
                continue;
            }
            $endCompiled->forceBindScopeSlot($arg, $slot);
            $root = Block::cfgVarRoot($arg);
            if (null !== $root) {
                $endCompiled->forceBindScopeSlot($root, $slot);
            }
        }
    }

    /**
     * ARG_SEND slot for a by-ref callee arg inside an {@see ErrorSuppressBlock} (#9320).
     */
    private function errorSuppressByRefArgSendSlot(
        Block $suppressCompiled,
        Op $primary,
        int $argIndex
    ): ?int {
        unset($primary);
        $inCall = false;
        $sendOrdinal = -1;
        $funcCallInits = 0;
        foreach ($suppressCompiled->opCodes as $op) {
            if (OpCode::TYPE_FUNCCALL_INIT === $op->type) {
                ++$funcCallInits;
                if (1 === $funcCallInits) {
                    $inCall = true;
                    $sendOrdinal = -1;
                }
                continue;
            }
            if (!$inCall) {
                continue;
            }
            if (OpCode::TYPE_ARG_SEND === $op->type) {
                ++$sendOrdinal;
                if ($sendOrdinal === $argIndex) {
                    return (int) $op->arg1;
                }
                continue;
            }
            if (OpCode::TYPE_FUNCCALL_EXEC_RETURN === $op->type || OpCode::TYPE_FUNCCALL_EXEC_NORETURN === $op->type) {
                break;
            }
        }

        return null;
    }

    /**
     * Outermost `@` expression in php-cfg (last call/new/include before the jump).
     * Nested arg-eval calls are hoisted as earlier siblings and must not steal the return slot (#9332).
     */
    private function findErrorSuppressPrimaryInnerExpr(ErrorSuppressBlock $block): ?Op
    {
        $primary = null;
        foreach ($block->children as $child) {
            if ($this->isErrorSuppressInnerExpr($child)) {
                $primary = $child;
            }
        }

        return $primary;
    }

    private function isErrorSuppressInnerExpr(Op $child): bool
    {
        return $child instanceof Op\Expr\FuncCall
            || $child instanceof Op\Expr\NsFuncCall
            || $child instanceof Op\Expr\MethodCall
            || $child instanceof Op\Expr\StaticCall
            || $child instanceof Op\Expr\New_
            || $child instanceof Op\Expr\Include_
            || $child instanceof Op\Expr\ArrayDimFetch
            || $child instanceof Op\Expr\Isset_
            || $child instanceof Op\Expr\Empty_
            // `@$cv` materializes via Assign under silence (#13587 / #29132).
            || $child instanceof Op\Expr\Assign;
    }

    /**
     * php-cfg may leave include result usages empty when the value feeds a FuncCall arg
     * (distinct Temporary for the call arg) or an {@see ErrorSuppressBlock} exit (#12163, #10336, #21938).
     */
    private function includeNeedsReturnSlot(Operand $result, Block $block): bool
    {
        if (!empty($result->usages)) {
            return true;
        }
        if ($block->callResultFeedsReturn($result) || $block->callResultFeedsEcho($result)) {
            return true;
        }
        if ($block->callResultFeedsErrorSuppressExit($result)) {
            return true;
        }
        if (null !== $block->orig && $block->orig instanceof ErrorSuppressBlock) {
            return true;
        }

        // var_export(require $f) / strlen(include $f): php-cfg usages stay empty (#21938).
        return $this->callResultFeedsInlineCallArg($result, $block);
    }

    private function findFuncCallExecReturnSlot(Block $block): ?int
    {
        $last = null;
        foreach ($block->opCodes as $op) {
            if (OpCode::TYPE_FUNCCALL_EXEC_RETURN === $op->type) {
                $last = (int) $op->arg1;
            }
        }

        return $last;
    }

    /** TYPE_INCLUDE result slot (arg2) — `@include` / `@require` expression value (#21938). */
    private function findIncludeReturnSlot(Block $block): ?int
    {
        $last = null;
        foreach ($block->opCodes as $op) {
            if (OpCode::TYPE_INCLUDE === $op->type && null !== $op->arg2) {
                $last = (int) $op->arg2;
            }
        }

        return $last;
    }

    private function bindErrorSuppressResultOperandUsages(
        Op $cfgOp,
        Block $endCompiled,
        Operand $suppressResult,
        int $slot
    ): void {
        if ($cfgOp instanceof Op\Expr\Assign && $this->assignIsPostSuppressIndependent($cfgOp, $endCompiled->orig)) {
            if ($cfgOp->expr instanceof Op) {
                $this->bindErrorSuppressResultOperandUsages($cfgOp->expr, $endCompiled, $suppressResult, $slot);
            }
            foreach ($cfgOp->children ?? [] as $child) {
                if ($child instanceof Op) {
                    $this->bindErrorSuppressResultOperandUsages($child, $endCompiled, $suppressResult, $slot);
                }
            }

            return;
        }
        if ($cfgOp instanceof Op\Expr) {
            if (property_exists($cfgOp, 'args') && is_array($cfgOp->args)) {
                foreach ($cfgOp->args as $arg) {
                    if ($arg instanceof Operand && $this->operandsReferToSameVariable($suppressResult, $arg)) {
                        $endCompiled->bindScopeSlot($arg, $slot);
                    }
                }
            }
            if (property_exists($cfgOp, 'var') && $cfgOp->var instanceof Operand) {
                if ($this->operandsReferToSameVariable($suppressResult, $cfgOp->var)) {
                    $endCompiled->bindScopeSlot($cfgOp->var, $slot);
                }
            }
            if (property_exists($cfgOp, 'expr') && $cfgOp->expr instanceof Operand) {
                if ($this->operandsReferToSameVariable($suppressResult, $cfgOp->expr)) {
                    $endCompiled->bindScopeSlot($cfgOp->expr, $slot);
                }
            }
        }
        foreach ($cfgOp->children ?? [] as $child) {
            if ($child instanceof Op) {
                $this->bindErrorSuppressResultOperandUsages($child, $endCompiled, $suppressResult, $slot);
            }
        }
    }

    /**
     * Assign from error_get_last() after END_SILENCE must not alias @ inner return slot (#16223).
     */
    private function assignRhsIsPostSuppressIndependentCall(Op\Expr\Assign $assign): bool
    {
        $expr = $assign->expr ?? null;
        if (!$expr instanceof Op\Expr\FuncCall && !$expr instanceof Op\Expr\NsFuncCall) {
            return false;
        }

        return $this->cfgOpIsPostSuppressIndependentCall($expr);
    }

    private function cfgOpIsPostSuppressIndependentCall(Op $op): bool
    {
        if (!$op instanceof Op\Expr\FuncCall && !$op instanceof Op\Expr\NsFuncCall) {
            return false;
        }

        return \in_array(
            $this->resolveCfgFuncCallName($op),
            [
                'error_get_last',
                'error_clear_last',
            ],
            true
        );
    }

    /**
     * php-cfg may hoist {@see error_get_last}() as a sibling stmt before the Assign (#16223).
     */
    private function assignIsPostSuppressIndependent(Op\Expr\Assign $assign, ?CfgBlock $endCfg): bool
    {
        if ($this->assignRhsIsPostSuppressIndependentCall($assign)) {
            return true;
        }
        if (null === $endCfg) {
            return false;
        }
        $expr = $assign->expr ?? null;
        if (!$expr instanceof Operand) {
            return false;
        }
        foreach ($endCfg->children as $child) {
            if (!$this->cfgOpIsPostSuppressIndependentCall($child) || !isset($child->result)) {
                continue;
            }
            if ($this->operandsReferToSameVariable($expr, $child->result)) {
                return true;
            }
        }

        return false;
    }

    /** True when END_SILENCE block assigns error_get_last() immediately after @ (#16223). */
    private function endBlockAssignsErrorGetLastAfterSuppress(?CfgBlock $endCfg): bool
    {
        if (null === $endCfg) {
            return false;
        }
        foreach ($endCfg->children as $child) {
            if ($child instanceof Op\Expr\Assign && $this->assignIsPostSuppressIndependent($child, $endCfg)) {
                return true;
            }
        }

        return false;
    }

    /**
     * True when no call in the post-@ block consumes the suppressed inner expression (#16223).
     *
     * Standalone `@f(); $x = error_get_last();` discards the @ return; slot inheritance must not
     * poison later statements still in the same php-cfg END_SILENCE block.
     */
    private function errorSuppressEndBlockInnerResultUnused(
        ?CfgBlock $endCfg,
        Block $endCompiled,
        Operand $suppressResult
    ): bool {
        if (null === $endCfg) {
            return false;
        }
        foreach ($endCfg->children as $child) {
            if (
                ($child instanceof Op\Expr\FuncCall || $child instanceof Op\Expr\NsFuncCall)
                && $this->callInErrorSuppressEndBlockUsesInnerResultAsArg($endCompiled, $child)
            ) {
                return false;
            }
        }
        foreach ($suppressResult->usages as $usage) {
            if (
                ($usage instanceof Op\Expr\FuncCall || $usage instanceof Op\Expr\NsFuncCall)
                && \in_array($usage, $endCfg->children, true)
            ) {
                return false;
            }
        }

        return true;
    }

    /** True when END_SILENCE block reassigns the suppress result via error_get_last() (#16223). */
    private function endBlockHasPostSuppressIndependentAssign(?CfgBlock $endCfg, Operand $suppressResult): bool
    {
        if (null === $endCfg) {
            return false;
        }
        foreach ($endCfg->children as $child) {
            if (!$child instanceof Op\Expr\Assign || !$this->assignIsPostSuppressIndependent($child, $endCfg)) {
                continue;
            }
            if ($this->operandsReferToSameVariable($suppressResult, $child->var)) {
                return true;
            }
        }

        return false;
    }

    /**
     * Skip cfg-root prebind when END_SILENCE immediately assigns error_get_last() to the suppress SSA (#16223).
     *
     * Keep prebind for nested `@f()` inside a sibling call (var_export(@get_cfg_var(...), true)).
     */
    private function shouldSkipPrebindCfgVarRootForSuppressResult(
        Block $endCompiled,
        ?CfgBlock $endCfg,
        Operand $suppressResult
    ): bool {
        if (null === $endCfg || !$this->endBlockHasPostSuppressIndependentAssign($endCfg, $suppressResult)) {
            return false;
        }
        foreach ($endCfg->children as $child) {
            if (
                ($child instanceof Op\Expr\FuncCall || $child instanceof Op\Expr\NsFuncCall)
                && $this->callInErrorSuppressEndBlockUsesInnerResultAsArg($endCompiled, $child)
            ) {
                return false;
            }
        }

        return true;
    }

    /**
     * Standalone `@f(); $x = error_get_last();` — @ return is discarded; skip slot inheritance (#16223).
     */
    private function errorSuppressEndBlockDiscardsInnerResultForErrorGetLast(Block $block): bool
    {
        $endCfg = $block->orig;
        if (null === $endCfg || !$this->isErrorSuppressEndBlock($endCfg)) {
            return false;
        }
        $parentCfg = $endCfg->parents[0];
        if (!$parentCfg instanceof ErrorSuppressBlock) {
            return false;
        }
        $primary = $this->findErrorSuppressPrimaryInnerExpr($parentCfg);
        if (null === $primary || !isset($primary->result)) {
            return false;
        }

        return $this->endBlockAssignsErrorGetLastAfterSuppress($endCfg)
            && $this->errorSuppressEndBlockInnerResultUnused($endCfg, $block, $primary->result);
    }

    /**
     * Lower CFG switch to JUMPIF/EQUAL chain (JIT-safe; TYPE_CASE branchIf needs bool #96).
     */
    protected function compileSwitchAsJumpIfChain(Op\Stmt\Switch_ $switch, Block $block): void
    {
        if (!isset($switch->cond)) {
            $this->throwCompileLogic('Switch missing condition operand');
        }
        $condSlot = $this->requireOperandSlot(
            $this->compileOperand($switch->cond, $block, true),
            'switch condition'
        );
        $caseCount = count($switch->cases);
        if (0 === $caseCount) {
            $defaultOp = new OpCode(OpCode::TYPE_JUMP);
            $defaultOp->block1 = $this->compileCfgBranch($switch->default, $block);
            $block->addOpCode($defaultOp);

            return;
        }

        $current = $block;
        $savedSwitchJumpIfChain = $this->compilingSwitchJumpIfChain;
        $this->compilingSwitchJumpIfChain = true;
        for ($i = 0; $i < $caseCount; ++$i) {
            $eqSlot = $this->requireOperandSlot(
                $this->compileBoolTemporary($current),
                'switch equality temporary'
            );
            $caseSlot = $this->requireOperandSlot(
                $this->compileSwitchCaseOperand($switch->cases[$i], $current),
                'switch case #'.$i
            );
            $current->addOpCode(new OpCode(
                OpCode::TYPE_EQUAL,
                $eqSlot,
                $condSlot,
                $caseSlot
            ));

            $caseTarget = $this->compileCfgBranch($switch->targets[$i], $block);
            $isLast = $i === $caseCount - 1;
            if ($isLast) {
                $elseTarget = $this->compileCfgBranch($switch->default, $block);
            } else {
                $elseTarget = new Block($block->orig);
                $elseTarget->syntheticCfgBranch = true;
                $elseTarget->inheritUndefinedLocals = true;
                $elseTarget->inheritScopeFrom($current);
                $this->inheritFuncFromParent($elseTarget, $block);
            }

            $jump = new OpCode(OpCode::TYPE_JUMPIF, $eqSlot);
            $jump->block1 = $caseTarget;
            $jump->block2 = $elseTarget;
            $current->addOpCode($jump);
            $caseTarget->parents[] = $current;
            $elseTarget->parents[] = $current;
            if (!$isLast) {
                $current = $elseTarget;
            }
        }
        $this->compilingSwitchJumpIfChain = $savedSwitchJumpIfChain;
    }

    /**
     * Materialize switch case labels at runtime — php-cfg Switch_ cases may lack preceding fetches (#8767).
     */
    protected function compileSwitchCaseOperand(Operand $caseOperand, Block $block): ?int
    {
        if (null !== $block->orig) {
            foreach ($block->orig->children as $child) {
                if (!$child instanceof Op\Expr\ClassConstFetch) {
                    continue;
                }
                if ($child->result !== $caseOperand && !$this->operandsReferToSameVariable($child->result, $caseOperand)) {
                    continue;
                }
                foreach ($this->compileClassConstFetch($child, $block) as $op) {
                    $block->addOpCode($op);
                }

                return $this->compileOperand($caseOperand, $block, true);
            }
        }

        return $this->compileOperand($caseOperand, $block, true);
    }

    protected function getOpCodeTypeFromBinaryOp(Op\Expr\BinaryOp $expr): int {
        if ($expr instanceof Op\Expr\BinaryOp\Concat) {
            return OpCode::TYPE_CONCAT;
        } elseif ($expr instanceof Op\Expr\BinaryOp\Plus) {
            return OpCode::TYPE_PLUS;
        } elseif ($expr instanceof Op\Expr\BinaryOp\Smaller) {
            return OpCode::TYPE_SMALLER;
        } elseif ($expr instanceof Op\Expr\BinaryOp\Greater) {
            return OpCode::TYPE_GREATER;
        } elseif ($expr instanceof Op\Expr\BinaryOp\SmallerOrEqual) {
            return OpCode::TYPE_SMALLER_OR_EQUAL;
        } elseif ($expr instanceof Op\Expr\BinaryOp\GreaterOrEqual) {
            return OpCode::TYPE_GREATER_OR_EQUAL;
        } elseif ($expr instanceof Op\Expr\BinaryOp\Equal) {
            return OpCode::TYPE_EQUAL;
        } elseif ($expr instanceof Op\Expr\BinaryOp\NotEqual) {
            return OpCode::TYPE_NOT_EQUAL;
        } elseif ($expr instanceof Op\Expr\BinaryOp\Identical) {
            return OpCode::TYPE_IDENTICAL;
        } elseif ($expr instanceof Op\Expr\BinaryOp\NotIdentical) {
            return OpCode::TYPE_NOT_IDENTICAL;
        } elseif ($expr instanceof Op\Expr\BinaryOp\Spaceship) {
            return OpCode::TYPE_SPACESHIP;
        } elseif ($expr instanceof Op\Expr\BinaryOp\Minus) {
            return OpCode::TYPE_MINUS;
        } elseif ($expr instanceof Op\Expr\BinaryOp\Mul) {
            return OpCode::TYPE_MUL;
        } elseif ($expr instanceof Op\Expr\BinaryOp\Div) {
            return OpCode::TYPE_DIV;
        } elseif ($expr instanceof Op\Expr\BinaryOp\Mod) {
            return OpCode::TYPE_MODULO;
        } elseif ($expr instanceof Op\Expr\BinaryOp\Pow) {
            return OpCode::TYPE_POW;
        } elseif ($expr instanceof Op\Expr\BinaryOp\BitwiseAnd) {
            return OpCode::TYPE_BITWISE_AND;
        } elseif ($expr instanceof Op\Expr\BinaryOp\BitwiseOr) {
            return OpCode::TYPE_BITWISE_OR;
        } elseif ($expr instanceof Op\Expr\BinaryOp\BitwiseXor) {
            return OpCode::TYPE_BITWISE_XOR;
        } elseif ($expr instanceof Op\Expr\BinaryOp\ShiftLeft) {
            return OpCode::TYPE_SHIFT_LEFT;
        } elseif ($expr instanceof Op\Expr\BinaryOp\ShiftRight) {
            return OpCode::TYPE_SHIFT_RIGHT;
        } elseif ($expr instanceof Op\Expr\BinaryOp\LogicalXor) {
            return OpCode::TYPE_LOGICAL_XOR;
        }
        $this->throwCompileLogic("Unknown BinaryOp Type: " . $expr->getType());
    }

    protected function getOpCodeTypeFromCastOp(Op\Expr\Cast $expr): int {
        if ($expr instanceof Op\Expr\Cast\Array_) {
            return OpCode::TYPE_CAST_ARRAY;
        } elseif ($expr instanceof Op\Expr\Cast\Bool_) {
            return OpCode::TYPE_CAST_BOOL;
        } elseif ($expr instanceof Op\Expr\Cast\Double) {
            return OpCode::TYPE_CAST_FLOAT;
        } elseif ($expr instanceof Op\Expr\Cast\Int_) {
            return OpCode::TYPE_CAST_INT;
        } elseif ($expr instanceof Op\Expr\Cast\Object_) {
            return OpCode::TYPE_CAST_OBJECT;
        } elseif ($expr instanceof Op\Expr\Cast\String_) {
            return OpCode::TYPE_CAST_STRING;
        } elseif ($expr instanceof Op\Expr\Cast\Unset_) {
            return OpCode::TYPE_CAST_UNSET;
        } elseif ($expr instanceof Op\Expr\Cast\Void_) {
            return OpCode::TYPE_CAST_VOID;
        }
        $this->throwCompileLogic("Unknown CastOp Type: " . $expr->getType());
    }

    protected function compileIncDecExpr(Op\Expr $expr, Block $block, int $opcode): array
    {
        // php-cfg may clear write after SSA replace; read still names the lvalue (#4946).
        $write = $expr->write ?? $expr->read;
        $this->rejectThisReassignment($write);
        $this->rejectNullsafeInWriteContext($write, $block);
        $this->rejectNewExprInWriteContext($write, $block, null, null, $expr);
        $this->rejectArrayLiteralInWriteContext($write, $block, $expr);
        $this->rejectGlobalConstInWriteContext($write, $block, $expr);
        $this->rejectCallReturnInWriteContext($write, $block, $expr);

        return [new OpCode(
            $opcode,
            $this->compileOperand($expr->result, $block, false),
            $this->compileOperand($expr->read, $block, true),
            $this->compileOperand($write, $block, false),
        )];
    }

    protected function getOpCodeTypeFromUnaryOp(Op\Expr $expr): int {
        if ($expr instanceof Op\Expr\UnaryMinus) {
            return OpCode::TYPE_UNARY_MINUS;
        } elseif ($expr instanceof Op\Expr\UnaryPlus) {
            return OpCode::TYPE_UNARY_PLUS;
        } elseif ($expr instanceof Op\Expr\BitwiseNot) {
            return OpCode::TYPE_BITWISE_NOT;
        } elseif ($expr instanceof Op\Expr\BooleanNot) {
            return OpCode::TYPE_BOOLEAN_NOT;
        } elseif ($expr instanceof Op\Expr\Clone_) {
            return OpCode::TYPE_CLONE;
        } elseif ($expr instanceof Op\Expr\Empty_) {
            return OpCode::TYPE_EMPTY;
        } elseif ($expr instanceof Op\Expr\Eval_) {
            return OpCode::TYPE_EVAL;
        } elseif ($expr instanceof Op\Expr\Exit_) {
            return OpCode::TYPE_EXIT;
        } elseif ($expr instanceof Op\Expr\Print_) {
            return OpCode::TYPE_PRINT;
        }
        $this->throwCompileLogic("Unknown UnaryOp Type: " . $expr->getType());
    }

    protected function compileExpr(Op\Expr $expr, Block $block): array {
        if ($expr instanceof Op\Expr\BinaryOp\Coalesce) {
            $this->compileCoalesce($expr, $block);

            return [];
        }
        if ($expr instanceof Op\Expr\BinaryOp) {
            if (null !== $expr->left) {
                $this->compileEmbeddedExprForOperand($expr->left, $block);
            }
            if (null !== $expr->right) {
                $this->compileEmbeddedExprForOperand($expr->right, $block);
            }
            $resultSlot = $block->inheritUndefinedLocals
                ? $block->forceFreshVarSlot($expr->result)
                : $this->compileOperand($expr->result, $block, false);
            if (!$block->closureCaptureSlotWritableForOperand($resultSlot, $expr->result)) {
                $resultSlot = $block->forceFreshVarSlot($expr->result);
            }
            $opcode = new OpCode(
                $this->getOpCodeTypeFromBinaryOp($expr),
                $resultSlot,
                null !== $expr->left ? $this->compileOperand($expr->left, $block, true) : null,
                null !== $expr->right ? $this->compileOperand($expr->right, $block, true) : null,
            );
            if ($this->isIncDecBinaryOp($expr)) {
                $opcode->isIncDec = true;
            }
            $this->assignSourceMetadata($opcode, $expr);

            return [$opcode];
        } elseif ($expr instanceof Op\Expr\Cast) {
            if ($expr instanceof Op\Expr\Cast\Unset_) {
                $this->throwCompileError('The (unset) cast is no longer supported');
            }
            $line = $expr->getLine();
            // Seed jump-target ||/&& phi before lowering the cast. Prefer that seeded slot over
            // logicalShortCircuitPhiMergeSlot when the cast sits *inside* an inner && merge that
            // jumps to an outer || merge — otherwise the cast assigns the inner phi and the outer
            // phi keeps a leftover callee-name string (#25850, re-#10626).
            $seededPhiSlot = null;
            if (null !== $block->orig) {
                $seededPhiSlot = $this->seedLogicalShortCircuitPhiSlot($block->orig, $block, $expr->result);
            }
            $castResultSlot = $this->compileOperand($expr->result, $block, false);
            $ops = [new OpCode(
                $this->getOpCodeTypeFromCastOp($expr),
                $castResultSlot,
                $this->compileOperand($expr->expr, $block, true),
                $line > 0 ? $line : null,
            )];
            if ($expr instanceof Op\Expr\Cast\Bool_) {
                $phiSlot = $seededPhiSlot
                    ?? $this->logicalShortCircuitJumpTargetPhiMergeSlot($block)
                    ?? $this->logicalShortCircuitPhiMergeSlot($block);
                if (null !== $phiSlot) {
                    if ($block->isNamedVariableSlot($phiSlot)) {
                        $phiSlot = $block->forceFreshVarSlot($expr->result, $phiSlot);
                        if (null !== $block->orig) {
                            $mergeCfg = $this->branchJumpMergeTarget($block->orig);
                            if (null !== $mergeCfg) {
                                $this->ternaryMergePhiRhsSlots[$mergeCfg] = $phiSlot;
                            }
                        }
                    }
                    if ($castResultSlot !== $phiSlot) {
                        $ops[] = new OpCode(
                            OpCode::TYPE_ASSIGN,
                            $phiSlot,
                            $phiSlot,
                            $castResultSlot
                        );
                    }
                }
            }

            return $ops;
        }
        switch (get_class($expr)) {
            case Op\Expr\ArrowFunction::class:
                return $this->compileAnonymousFunctionExpr($expr, $block);
            case Op\Expr\Closure::class:
                return $this->compileAnonymousFunctionExpr($expr, $block);
            case Op\Expr\Assertion::class:
                if ($expr->result instanceof Operand\Literal) {
                    //short circuit
                    return [];
                } elseif ($expr->expr === $expr->result) {
                    return [];
                }
                return [new OpCode(
                    OpCode::TYPE_TYPE_ASSERT,
                    $this->compileOperand($expr->result, $block, false),   
                    $this->compileOperand($expr->expr, $block, true) 
                )];
            case Op\Expr\Assign::class:
                if (!$this->assignIsListSpread($expr)) {
                    $this->rejectThisReassignment($expr->var);
                    $this->rejectNullsafeInWriteContext($expr->var, $block);
                    $this->rejectNewExprInWriteContext($expr->var, $block, $expr->expr, $expr);
                    $this->rejectArrayLiteralInWriteContext($expr->var, $block, $expr);
                    $this->rejectGlobalConstInWriteContext($expr->var, $block, $expr);
                    $this->rejectCallReturnInWriteContext($expr->var, $block, $expr);
                }
                if ($this->assignIsListSpread($expr)) {
                    $this->rejectListSpreadAssignExpr($expr);
                    $fromIndex = new Operand\Literal($expr->listSpreadFromIndex);
                    $spreadOp = new OpCode(
                        OpCode::TYPE_LIST_SPREAD_ASSIGN,
                        $this->compileOperand($expr->var, $block, false),
                        $this->compileOperand($expr->listSpreadRhs, $block, true),
                        $this->compileOperand($fromIndex, $block, true),
                    );
                    $spreadOp->listSpreadExcludedKeys = $expr->listSpreadExcludedKeys ?? [];

                    return [$spreadOp];
                }
                $staticPropertyFetch = $this->unwrapStaticPropertyFetch($expr->var);
                $emitStaticPropertyFetch = true;
                if (null === $staticPropertyFetch) {
                    $staticPropertyFetch = $this->findStaticPropertyFetchForAssign($expr->var, $block);
                    $emitStaticPropertyFetch = false;
                }
                if (null !== $staticPropertyFetch) {
                    $fetchSlot = $this->compileOperand($staticPropertyFetch->result, $block, false);
                    $rhsSlot = $this->compileOperand($expr->expr, $block, true);
                    $ops = [];
                    if ($emitStaticPropertyFetch) {
                        $ops[] = new OpCode(
                            OpCode::TYPE_STATIC_PROPERTY_FETCH,
                            $fetchSlot,
                            $this->compileOperand($staticPropertyFetch->class, $block, true),
                            $this->compileStaticPropertyNameSlot($staticPropertyFetch->name, $staticPropertyFetch->class, $block)
                        );
                    }
                    // One property write; publish used result without re-writing the slot (#29194).
                    // Stamp ASSIGN (not only the fetch) so JIT private(set) Errors cite the write (#29665).
                    $writeOp = new OpCode(
                        OpCode::TYPE_ASSIGN,
                        $fetchSlot,
                        $fetchSlot,
                        $rhsSlot
                    );
                    $this->assignSourceMetadata($writeOp, $expr);
                    $ops[] = $writeOp;
                    if ([] !== $expr->result->usages) {
                        $resultSlot = $this->compileOperand($expr->result, $block, false);
                        $ops[] = new OpCode(
                            OpCode::TYPE_ASSIGN,
                            $resultSlot,
                            $resultSlot,
                            $rhsSlot
                        );
                    }

                    return $ops;
                }
                $propertyFetch = $this->unwrapPropertyFetch($expr->var)
                    ?? $this->findCoalescePropertyFetch($expr->var, $block);
                if (null !== $propertyFetch) {
                    $fetchSlot = $this->compileOperand($propertyFetch->result, $block, false);
                    $rhsSlot = $this->compileOperand($expr->expr, $block, true);
                    $fetchOp = new OpCode(
                        OpCode::TYPE_PROPERTY_FETCH,
                        $fetchSlot,
                        $this->compileOperand($propertyFetch->var, $block, true),
                        $this->compileOperand($propertyFetch->name, $block, true)
                    );
                    // Assign-lowered property writes skip compileExpr(PropertyFetch); stamp line here (#21953).
                    $this->assignSourceMetadata($fetchOp, $propertyFetch);
                    // Write the property once. A follow-up ASSIGN must not use fetchSlot as dest —
                    // that re-invokes __set for `$r = ($obj->prop = $v)` (#29194). Publish the
                    // expression value into resultSlot only (dest=resultSlot).
                    // Stamp the ASSIGN with the Assign expr so mid-method private(set) Errors
                    // report the write line, not a stale callSiteLine (#29665 / zend_object_handlers.c).
                    $writeOp = new OpCode(
                        OpCode::TYPE_ASSIGN,
                        $fetchSlot,
                        $fetchSlot,
                        $rhsSlot
                    );
                    $this->assignSourceMetadata($writeOp, $expr);
                    $ops = [
                        $fetchOp,
                        $writeOp,
                    ];
                    if ([] !== $expr->result->usages) {
                        $resultSlot = $this->compileOperand($expr->result, $block, false);
                        $ops[] = new OpCode(
                            OpCode::TYPE_ASSIGN,
                            $resultSlot,
                            $resultSlot,
                            $rhsSlot
                        );
                    }

                    return $ops;
                }

                $mergeAssignSlot = $this->branchMergeAssignSlot($block, $expr);
                if ($expr->expr instanceof Operand\Literal && null !== $block->orig) {
                    $literalMerge = $this->branchJumpMergeTarget($block->orig);
                    if (
                        null !== $literalMerge
                        && $this->mergeCfgBlockUsesLogicalShortCircuit($literalMerge)
                    ) {
                        $tail = $this->branchTailExprBeforeJump($block->orig);
                        if ($tail === $expr) {
                            $literalPhi = $this->logicalShortCircuitSiblingPhiSlot($block)
                                ?? $this->logicalShortCircuitPhiMergeSlot($block);
                            if (null !== $literalPhi) {
                                $mergeAssignSlot = $literalPhi;
                            }
                        }
                    }
                }
                // Named CV assigns keep their own slots across try/catch merge (#29482).
                // Catch lowers before try (#6411); without this guard, catch's CV is recorded
                // as ternary echo-phi and the try-body assign is forced onto that sibling
                // slot — same class as #26490 (branchMergeAssignSlot) but this override path
                // previously bypassed the named-CV check.
                $assignIsNamedCv = null !== Block::resolveVariableName($expr->var);
                if (null !== $block->orig && $this->isMergeBranchAssign($block, $expr)) {
                    $mergeCfg = $this->branchJumpMergeTarget($block->orig);
                    if (
                        null !== $mergeCfg
                        && $this->mergeCfgBlockUsesTernaryPhi($mergeCfg)
                        && !$assignIsNamedCv
                    ) {
                        $recordedPhi = $this->ternaryMergePhiRhsSlot($mergeCfg);
                        if (null !== $recordedPhi) {
                            $mergeAssignSlot = $recordedPhi;
                        }
                    }
                }
                if (null !== $mergeAssignSlot) {
                    $root = Block::cfgVarRoot($expr->var);
                    if ($root instanceof Operand\Variable) {
                        $block->prebindCfgVarRoot($root, $mergeAssignSlot);
                    } else {
                        $block->bindScopeSlot($expr->var, $mergeAssignSlot);
                    }
                }
                $destSlot = null !== $mergeAssignSlot
                    ? $mergeAssignSlot
                    : $this->compileOperand($expr->var, $block, false);
                if (null !== $block->orig && $this->isMergeBranchAssign($block, $expr)) {
                    $mergeCfg = $this->branchJumpMergeTarget($block->orig);
                    if (
                        null !== $mergeCfg
                        && $this->mergeCfgBlockUsesTernaryPhi($mergeCfg)
                        && !$assignIsNamedCv
                    ) {
                        if (!$this->ternaryMergePhiRhsSlots->contains($mergeCfg)) {
                            $this->ternaryMergePhiRhsSlots[$mergeCfg] = (int) $destSlot;
                        }
                    }
                }
                $rhsSlot = $this->compileOperand($expr->expr, $block, true);
                $this->reconcileEncapsedConcatListAssignSlots($expr, $block, $destSlot, $rhsSlot);
                $resultSlot = $this->compileOperand($expr->result, $block, false);
                $varRoot = Block::cfgVarRoot($expr->var);
                if (null !== $varRoot) {
                    // Register the CV lvalue slot — assign.result temps diverge after $a[] writes (#12712).
                    $block->registerNamedAssignDest($varRoot, (int) $destSlot);
                }

                $assignOp = new OpCode(
                    OpCode::TYPE_ASSIGN,
                    $resultSlot,
                    $destSlot,
                    $rhsSlot
                );
                $block->registerAssignResultLvalue((int) $resultSlot, (int) $destSlot);
                $this->assignSourceMetadata($assignOp, $expr);

                return [$assignOp];
            case Op\Expr\Exit_::class:
                $exitExpr = null !== $expr->expr
                    ? $this->compileOperand($expr->expr, $block, true)
                    : null;
                $resultSlot = null;
                if ([] !== $expr->result->usages || $block->callResultFeedsReturn($expr->result)) {
                    $resultSlot = $this->compileOperand($expr->result, $block, false);
                }

                $exitOp = new OpCode(
                    OpCode::TYPE_EXIT,
                    $resultSlot,
                    $exitExpr,
                    max(0, $expr->getLine())
                );
                if (null !== $expr->message) {
                    $exitOp->exitMessageSlot = $this->compileOperand($expr->message, $block, true);
                }

                return [$exitOp];
            case Op\Expr\PostInc::class:
                return $this->compileIncDecExpr($expr, $block, OpCode::TYPE_POST_INC);
            case Op\Expr\PreInc::class:
                return $this->compileIncDecExpr($expr, $block, OpCode::TYPE_PRE_INC);
            case Op\Expr\PostDec::class:
                return $this->compileIncDecExpr($expr, $block, OpCode::TYPE_POST_DEC);
            case Op\Expr\PreDec::class:
                return $this->compileIncDecExpr($expr, $block, OpCode::TYPE_PRE_DEC);
            case Op\Expr\UnaryMinus::class:
            case Op\Expr\UnaryPlus::class:
                $foldedUnaryLiteral = $this->tryFoldUnaryLiteralDefault($expr);
                if (null !== $foldedUnaryLiteral) {
                    $block->registerConstant($expr->result, $foldedUnaryLiteral);

                    return [];
                }

                return [new OpCode(
                    $this->getOpCodeTypeFromUnaryOp($expr),
                    $this->compileOperand($expr->result, $block, false),
                    $this->compileUnaryExprReadOperand($expr, $block)
                )];
            case Op\Expr\BitwiseNot::class:
            case Op\Expr\BooleanNot::class:
            case Op\Expr\Clone_::class:
                return [new OpCode(
                    $this->getOpCodeTypeFromUnaryOp($expr),
                    $this->compileOperand($expr->result, $block, false),
                    $this->compileUnaryExprReadOperand($expr, $block)
                )];
            case Op\Expr\Empty_::class:
                if ([] !== ($nullsafeChain = $this->collectNullsafePropertyFetchChainForEmpty($expr, $block))) {
                    $this->compileEmptyNullsafePropertyFetchChain($nullsafeChain, $expr, $block);

                    return [];
                }
                $emptyOperand = $this->recoverEmptyExprOperand($expr, $block)
                    ?? $this->unaryExprOperandForRead($expr, $block);
                $propFetch = null !== $emptyOperand
                    ? $this->findCoalescePropertyFetch($emptyOperand, $block)
                    : null;
                if (null === $propFetch && null !== $emptyOperand) {
                    $propFetch = $this->unwrapPropertyFetch($emptyOperand);
                }
                if (null !== $propFetch) {
                    return [new OpCode(
                        OpCode::TYPE_EMPTY_OBJECT_PROPERTY,
                        $this->compileOperand($expr->result, $block, false),
                        $this->compileOperand($propFetch->var, $block, true),
                        $this->compileOperand($propFetch->name, $block, true),
                    )];
                }
                $staticPropFetch = null !== $emptyOperand
                    ? $this->findCoalesceStaticPropertyFetch($emptyOperand, $block)
                    : null;
                if (null === $staticPropFetch && null !== $emptyOperand) {
                    $staticPropFetch = $this->unwrapStaticPropertyFetch($emptyOperand);
                }
                if (null !== $staticPropFetch) {
                    $resultSlot = $this->compileOperand($expr->result, $block, false);
                    [$classSlot, $nameSlot] = $this->resolveIssetTargetFromStaticPropertyFetch($staticPropFetch, $block);

                    return [new OpCode(
                        OpCode::TYPE_EMPTY_STATIC_PROPERTY,
                        $resultSlot,
                        $classSlot,
                        $nameSlot
                    )];
                }
                $dimFetch = null !== $emptyOperand
                    ? $this->findCoalesceArrayDimFetch($emptyOperand, $block)
                    : null;
                if (null !== $dimFetch) {
                    $chain = $this->collectArrayDimFetchChain($dimFetch, $block);
                    foreach ($chain as $chainFetch) {
                        $this->rejectArrayEmptyOffsetRead($chainFetch, $block);
                    }
                    $resultSlot = $this->compileOperand($expr->result, $block, false);
                    [$prefixOps, $containerSlot] = $this->emitQuietDimFetchChainPrefix($chain, $block);
                    $lastFetch = $chain[count($chain) - 1];
                    $dimSlot = null !== $lastFetch->dim
                        ? $this->compileOperand($lastFetch->dim, $block, true)
                        : null;
                    if (null !== $containerSlot) {
                        $prefixOps[] = new OpCode(
                            OpCode::TYPE_EMPTY_DIMENSION,
                            $resultSlot,
                            $containerSlot,
                            $dimSlot
                        );

                        return $prefixOps;
                    }
                }

                $op = new OpCode(
                    OpCode::TYPE_EMPTY,
                    $this->compileOperand($expr->result, $block, false),
                    $this->compileUnaryExprReadOperand($expr, $block)
                );
                $this->assignSourceMetadata($op, $expr);

                return [$op];
            case Op\Expr\Eval_::class:
                $evalOp = new OpCode(
                    $this->getOpCodeTypeFromUnaryOp($expr),
                    $this->compileOperand($expr->result, $block, false),
                    $this->compileOperand($expr->expr, $block, true)
                );
                // Call-site line for Zend eval __FILE__ / fatals: parent(line) : eval()'d code (#25809, #4410).
                $this->assignSourceMetadata($evalOp, $expr);

                return [$evalOp];
            case Op\Expr\Print_::class:
                $line = $expr->getLine();

                return [new OpCode(
                    $this->getOpCodeTypeFromUnaryOp($expr),
                    $this->compileOperand($expr->result, $block, false),
                    $this->compileOperand($expr->expr, $block, true),
                    $line > 0 ? $line : null
                )];
            case Op\Expr\ArrayDimFetch::class:
                $this->rejectArrayEmptyOffsetRead($expr, $block);
                $mergeEcho = $this->mergeEchoSlotForBranch($block);
                $dimForWrite = $this->isArrayDimFetchForWrite($expr, $block);
                // By-ref call args also use FETCH_DIM_W — reject temporary bases (#29522 / #29247).
                if ($dimForWrite) {
                    $this->rejectTemporaryExpressionInWriteContext($expr->result, $block, $expr);
                }
                if (null !== $mergeEcho && !$dimForWrite) {
                    $block->forceFreshVarSlot($expr->result, $mergeEcho);
                }
                $prefix = [];
                $dimSlot = null !== $expr->dim
                    ? $this->compileOperand($expr->dim, $block, true)
                    : null;
                $resultSlot = $this->compileOperand($expr->result, $block, false);
                // Echo/ternary merge phi must not share a slot with dim keys (#3790 / #5506).
                // Literals: rematerialize the constant. Non-literals (e.g. `new T()` result):
                // copy into a fresh temp — never forceFreshVarSlot the live producer operand,
                // which remaps TYPE_NEW's result away from the object and turns the key into
                // null→"" (#29532, zend_hash Illegal offset type).
                if (null !== $mergeEcho && null !== $dimSlot && $dimSlot === $mergeEcho && null !== $expr->dim) {
                    if ($expr->dim instanceof Operand\Literal) {
                        $dimSlot = $this->freshLiteralConstantSlot($expr->dim, $block);
                    } else {
                        $dimTemp = new Operand\Temporary();
                        $srcOp = $block->getOperand($dimSlot);
                        if (null !== $srcOp?->type) {
                            $dimTemp->type = $srcOp->type;
                        }
                        $freshDim = $block->forceFreshVarSlot($dimTemp);
                        $prefix[] = new OpCode(OpCode::TYPE_ASSIGN, $freshDim, $freshDim, $dimSlot);
                        $dimSlot = $freshDim;
                    }
                }
                if (null !== $dimSlot && $resultSlot === $dimSlot) {
                    $block->forceFreshVarSlot($expr->result);
                    $resultSlot = $this->compileOperand($expr->result, $block, false);
                }
                $fetchType = $dimForWrite
                    ? OpCode::TYPE_ARRAY_DIM_FETCH_WRITE
                    : OpCode::TYPE_ARRAY_DIM_FETCH;

                return array_merge($prefix, [new OpCode(
                    $fetchType,
                    $resultSlot,
                    $this->compileArrayDimFetchContainerSlot($expr, $block),
                    $dimSlot
                )]);
            case Op\Expr\ConstFetch::class:
                $nsName = null;
                if (!is_null($expr->nsName)) {
                    $nsName = $this->compileOperand($expr->nsName, $block, true);
                }
                $op = new OpCode(
                    OpCode::TYPE_CONST_FETCH,
                    $this->compileOperand($expr->result, $block, false),
                    $this->compileOperand($expr->name, $block, true),
                    $nsName
                );
                $this->assignSourceMetadata($op, $expr);

                return [$op];
            case Op\Expr\ClassConstFetch::class:
                return $this->compileClassConstFetch($expr, $block);
            case Op\Expr\StaticPropertyFetch::class:
                return [new OpCode(
                    OpCode::TYPE_STATIC_PROPERTY_FETCH,
                    $this->compileOperand($expr->result, $block, false),
                    $this->compileOperand($expr->class, $block, true),
                    $this->compileStaticPropertyNameSlot($expr->name, $expr->class, $block)
                )];
            case Op\Expr\FirstClassCallable::class:
                return $this->compileFirstClassCallable($expr, $block);
            case Op\Expr\FuncCall::class:
                if ($this->parensNewCallSkippedWithoutInvoke($expr->name, $block)) {
                    return [];
                }
                if ($this->operandIsInvokableReceiver($expr->name, $block)) {
                    return $this->compileMethodCallOpcodes(
                        $this->compileOperand($expr->name, $block, true),
                        $this->compileOperand(new Operand\Literal('__invoke'), $block, true),
                        $expr->args,
                        $expr->result,
                        $block,
                        max(0, $expr->getLine()),
                        $expr,
                        true
                    );
                }

                $splitCall = $this->compileFuncCallAfterChainedCoalesceArgs($expr, $block);
                if (null !== $splitCall) {
                    return $splitCall;
                }

                return $this->compileFuncCall(
                    $this->compileOperand($expr->name, $block, true),
                    $expr->args,
                    $expr->result,
                    $block,
                    max(0, $expr->getLine()),
                    $expr
                );
            case Op\Expr\NsFuncCall::class:
                if ($this->parensNewCallSkippedWithoutInvoke($expr->nsName, $block)) {
                    return [];
                }
                if ($this->operandIsInvokableReceiver($expr->nsName, $block)) {
                    return $this->compileMethodCallOpcodes(
                        $this->compileOperand($expr->nsName, $block, true),
                        $this->compileOperand(new Operand\Literal('__invoke'), $block, true),
                        $expr->args,
                        $expr->result,
                        $block,
                        max(0, $expr->getLine()),
                        $expr,
                        true
                    );
                }

                return $this->compileFuncCall(
                    $this->compileOperand($expr->nsName, $block, true),
                    $expr->args,
                    $expr->result,
                    $block,
                    max(0, $expr->getLine()),
                    $expr
                );
            case Op\Expr\StaticCall::class:
                $fromCallableFcc = $this->tryCompileClosureFromCallableAsFcc($expr, $block);
                if (null !== $fromCallableFcc) {
                    return $fromCallableFcc;
                }
                $parentScope = $this->staticCallUsesParentScope($expr->class);
                $classSlot = $parentScope
                    ? $this->compileOperand(new Operand\Literal('parent'), $block, true)
                    : $this->compileOperand($expr->class, $block, true);
                $init = new OpCode(
                    OpCode::TYPE_STATICCALL_INIT,
                    $classSlot,
                    $this->compileOperand($expr->name, $block, true)
                );
                $init->staticCallParentScope = $parentScope;
                $className = $this->literalScopeClassName($expr->class)
                    ?? $this->staticNameFromOperand($expr->class);
                $methodName = $this->staticNameFromOperand($expr->name);
                $calleeName = null;
                if (null !== $className && null !== $methodName) {
                    $calleeName = ltrim($className, '\\').'::'.$methodName;
                }

                return $this->compileStaticCallOpcodes(
                    $init,
                    $expr->args,
                    $expr->result,
                    $block,
                    max(0, $expr->getLine()),
                    $expr,
                    $calleeName
                );
            case Op\Expr\New_::class:
                // Abstract/enum `new` is a runtime Error when NEW executes (Zend zend_execute.c),
                // not a unit-wide compile fatal — dead `if (false) { new Abstract; }` must load (#25787 / re-#3385).
                $className = $this->literalScopeClassName($expr->class);
                $resultSlot = $this->compileOperand($expr->result, $block, false);
                $line = $expr->getLine();
                $return = [
                    new OpCode(
                        OpCode::TYPE_NEW,
                        $resultSlot,
                        $this->compileOperand($expr->class, $block, true),
                        $line > 0 ? $line : null
                    )
                ];
                foreach ($this->compileCallArgSends($expr->args, $block, $className, $expr) as $send) {
                    $return[] = $send;
                }
                $return[] = $this->compileFuncCallExecOpcode(
                    $expr->result,
                    $block,
                    $line > 0 ? $line : 0,
                    $expr
                );
                $this->markInlineNewProducerKeepSlotForSiblingConsumer($expr, $block, (int) $resultSlot);

                return $return;
            case Op\Expr\MethodCall::class:
                $mergeEcho = $this->mergeEchoSlotForBranch($block);
                $catchReceiverSlot = $this->slotForActiveCatchVariable($expr->var);
                $receiverSlot = null !== $catchReceiverSlot
                    ? $catchReceiverSlot
                    : $this->compileOperand($expr->var, $block, true);
                $nameSlot = $this->compileOperand($expr->name, $block, true);
                $prefix = [];
                if (null !== $mergeEcho && $nameSlot === $mergeEcho) {
                    $nameSlot = $this->freshLiteralConstantSlot($expr->name, $block);
                }
                if (null !== $mergeEcho && null === $catchReceiverSlot) {
                    $resultSlot = $this->compileOperand($expr->result, $block, false);
                    if ($resultSlot === $mergeEcho) {
                        $block->forceFreshVarSlot($expr->result);
                    }
                    // Receiver must not alias ?: echo phi (condition var is often reused, #5506).
                    // Copy PHPCfg type so __call / method resolution keep the class (#26427 try+echo).
                    $recvTemp = new Operand\Temporary();
                    $srcOp = $block->getOperand($receiverSlot);
                    if (null !== $srcOp?->type) {
                        $recvTemp->type = $srcOp->type;
                    }
                    $recvSlot = $block->forceFreshVarSlot($recvTemp);
                    $prefix[] = new OpCode(OpCode::TYPE_ASSIGN, $recvSlot, $recvSlot, $receiverSlot);
                    $receiverSlot = $recvSlot;
                }

                return array_merge(
                    $prefix,
                    $this->compileMethodCallOpcodes(
                        $receiverSlot,
                        $nameSlot,
                        $expr->args,
                        $expr->result,
                        $block,
                        max(0, $expr->getLine()),
                        $expr
                    )
                );
            case Op\Expr\PropertyFetch::class:
                $propForWrite = $this->isPropertyFetchForWrite($expr, $block);
                // By-ref call args use FETCH_OBJ_W — reject (new …)->prop temps (#29522 / #29247).
                if ($propForWrite) {
                    $this->rejectTemporaryExpressionInWriteContext($expr->result, $block, $expr);
                }
                $fetchType = $propForWrite
                    ? OpCode::TYPE_PROPERTY_FETCH_WRITE
                    : OpCode::TYPE_PROPERTY_FETCH;

                $fetchOp = new OpCode(
                    $fetchType,
                    $this->compileOperand($expr->result, $block, false),
                    $this->compileOperand($expr->var, $block, true),
                    $this->compileOperand($expr->name, $block, true)
                );
                // Zend attributes dynamic-property E_DEPRECATED to the fetch/write site (#21953).
                $this->assignSourceMetadata($fetchOp, $expr);

                return [$fetchOp];
            case Op\Expr\Array_::class:
                return $this->compileArrayLiteral($expr, $block);
            case Op\Expr\MagicScriptConst::class:
                $line = null;
                if (Op\Expr\MagicScriptConst::KIND_LINE === $expr->kind) {
                    $line = max(1, $expr->getLine());
                    // wrapEvalCode prepends "<?php\n" — Zend __LINE__ is 1-based in the eval string (#25809).
                    if (\PHPCompiler\ext\standard\VmEval::isEvalScriptPath($block->scriptPath())) {
                        $line = \PHPCompiler\ext\standard\VmEval::unwrapEvalLine($line);
                    }
                }

                return [new OpCode(
                    OpCode::TYPE_SCRIPT_MAGIC,
                    $this->compileOperand($expr->result, $block, false),
                    $line,
                    Op\Expr\MagicScriptConst::KIND_HALT_OFFSET === $expr->kind
                        ? OpCode::SCRIPT_MAGIC_HALT_OFFSET
                        : $expr->kind,
                )];
            case Op\Expr\Include_::class:
                // Re-lowering the same Include_ (CFG walk + call-arg compileExpr) re-runs once-skip
                // and overwrites the first-load int(1) with bool(true) (#25852).
                if (isset($block->emittedIncludeOrEvalExprIds[spl_object_id($expr)])) {
                    return [];
                }

                return [$this->compileIncludeOp($expr, $block)];
            case Op\Expr\Isset_::class:
                return $this->compileIsset($expr, $block);
            case Op\Expr\Throw_::class:
                return $this->compileThrowExpression($expr, $block);
            case Op\Iterator\Valid::class:
                $iterValid = new OpCode(
                    OpCode::TYPE_ITER_VALID,
                    $this->compileOperand($expr->result, $block, false),
                    $this->compileOperand($expr->var, $block, true)
                );
                $this->assignSourceMetadata($iterValid, $expr);

                return [$iterValid];
            case Op\Iterator\Key::class:
                $iterKey = new OpCode(
                    OpCode::TYPE_ITER_KEY,
                    $this->compileOperand($expr->result, $block, false),
                    $this->compileOperand($expr->var, $block, true)
                );
                $this->assignSourceMetadata($iterKey, $expr);

                return [$iterKey];
            case Op\Iterator\Value::class:
                $iterValue = new OpCode(
                    OpCode::TYPE_ITER_VALUE,
                    $this->compileOperand($expr->result, $block, false),
                    $this->compileOperand($expr->var, $block, true),
                    $expr->byRef ? 1 : 0
                );
                $this->assignSourceMetadata($iterValue, $expr);

                return [$iterValue];
            case Op\Expr\InstanceOf_::class:
                return $this->compileInstanceOf($expr, $block);
            case Op\Expr\In_::class:
                return $this->compileIn($expr, $block);
            case Op\Expr\AssignRef::class:
                $this->rejectThisReassignment($expr->var);
                $this->rejectNullsafeInWriteContext($expr->var, $block);
                $this->rejectNewExprInWriteContext($expr->var, $block, null, null, $expr);
                $this->rejectArrayLiteralInWriteContext($expr->var, $block, $expr);
                $this->rejectGlobalConstInWriteContext($expr->var, $block, $expr);
                $this->rejectCallReturnInWriteContext($expr->var, $block, $expr);
                // Zend zend_compile.c: cannot acquire a reference to $GLOBALS (#15627).
                $this->rejectGlobalsReferenceAcquisition($expr->expr);
                // Zend zend_compile.c: &$a?->x / &$a?->m() (#26638).
                $this->rejectNullsafeReferenceAcquisition($expr->expr, $block);
                // Zend zend_compile.c: ref-binding to const/class-const array element (#5409).
                $this->rejectGlobalConstInWriteContext($expr->expr, $block, $expr);
                $bindRefFlags = 0;
                $dimFetch = $this->unwrapArrayDimFetch($expr->expr)
                    ?? $this->findArrayDimFetchForResult($expr->expr, $block);
                $arrayLiteral = null !== $dimFetch
                    ? ($this->unwrapArrayLiteralExpr($dimFetch->var)
                        ?? $this->findArrayExprForResult($dimFetch->var, $block))
                    : null;
                if (null !== $arrayLiteral) {
                    // Zend zend_compile_list_assign: ref target from inline array literal (#3799).
                    $bindRefFlags = 1;
                } elseif (0 !== $this->assignRefBindRefFlags) {
                    $bindRefFlags = $this->assignRefBindRefFlags;
                }
                $ops = [new OpCode(
                    OpCode::TYPE_ASSIGN_REF,
                    $this->compileOperand($expr->var, $block, false),
                    $this->compileOperand($expr->expr, $block, true),
                    $bindRefFlags ?: null
                )];
                if ([] !== $expr->result->usages) {
                    $ops[] = new OpCode(
                        OpCode::TYPE_ASSIGN,
                        $this->compileOperand($expr->result, $block, false),
                        $this->compileOperand($expr->var, $block, false),
                        $this->compileOperand($expr->expr, $block, true)
                    );
                }
                return $ops;
            case Op\Expr\Yield_::class:
                $this->markFunctionGenerator($block);

                $yieldOp = new OpCode(
                    OpCode::TYPE_YIELD,
                    [] !== $expr->result->usages
                        ? $this->compileOperand($expr->result, $block, false)
                        : null,
                    null !== $expr->value
                        ? $this->compileOperand($expr->value, $block, true)
                        : (null !== $expr->key
                            ? $this->compileOperand($expr->key, $block, true)
                            : null),
                    null !== $expr->value && null !== $expr->key
                        ? $this->compileOperand($expr->key, $block, true)
                        : null,
                );
                $this->assignSourceMetadata($yieldOp, $expr);

                return [$yieldOp];
            case Op\Expr\YieldFrom::class:
                $this->markFunctionGenerator($block);
                $yieldFromOp = new OpCode(
                    OpCode::TYPE_YIELD_FROM,
                    [] !== $expr->result->usages
                        ? $this->compileOperand($expr->result, $block, false)
                        : null,
                    $this->compileOperand($expr->expr, $block, true),
                );
                $this->assignSourceMetadata($yieldFromOp, $expr);

                return [$yieldFromOp];
            case Op\Expr\NullsafePropertyFetch::class:
                if (null !== $this->slotForNullsafeResult($block, $expr)) {
                    return [];
                }
                $this->compileNullsafePropertyFetch($expr, $block);

                return [];
            case Op\Expr\NullsafeMethodCall::class:
                if (null !== $this->slotForNullsafeResult($block, $expr)) {
                    return [];
                }
                $this->compileNullsafeMethodCall($expr, $block);

                return [];
        }
        $this->throwCompileLogicForOp($expr, 'Unsupported expression: '.$expr->getType());
    }

    /**
     * @param Op\Expr\ArrowFunction|Op\Expr\Closure $expr
     *
     * @return OpCode[]
     */
    protected function compileAnonymousFunctionExpr($expr, Block $block): array
    {
        if ($this->shouldStubClosureForBootstrap()) {
            $resultSlot = $this->compileOperand($expr->result, $block, false);
            $nullSlot = $this->compileOperand(new Operand\Literal(null), $block, true);

            return [new OpCode(
                OpCode::TYPE_ASSIGN,
                $resultSlot,
                $resultSlot,
                $nullSlot
            )];
        }
        $func = $expr->func;
        $wasArrowAutoCapture = $this->compilingArrowAutoCapture;
        // Nested closure/arrow bodies must bind catch CVs through closureCaptures, not the
        // outer catch-handler slot map. Rewriting reads to the handler slot made use($e) /
        // fn() => $e appear to work only when that CV happened to be slot 0 (#25897).
        $savedCatchVarSlots = $this->activeCatchVarSlotsByName;
        $savedCatchVarRoots = $this->activeCatchVarRoots;
        $this->activeCatchVarSlotsByName = [];
        $this->activeCatchVarRoots = [];
        if ($expr instanceof Op\Expr\ArrowFunction) {
            $this->compilingArrowAutoCapture = true;
        }
        $closureUseVars = [];
        if ($expr instanceof Op\Expr\Closure) {
            foreach ($expr->useVars as $useVar) {
                if ($useVar instanceof Operand\BoundVariable) {
                    $closureUseVars[] = $useVar;
                }
            }
        }
        try {
            $funcBlock = $this->compileCfgBlock($func->cfg, $func->params, $func, $closureUseVars);
            $funcBlock->parents[] = $block;
        } finally {
            $this->compilingArrowAutoCapture = $wasArrowAutoCapture;
            $this->activeCatchVarSlotsByName = $savedCatchVarSlots;
            $this->activeCatchVarRoots = $savedCatchVarRoots;
        }
        $this->markGeneratorIfNeeded($expr, $funcBlock);
        $op = new OpCode(
            OpCode::TYPE_CLOSURE,
            $this->compileOperand($expr->result, $block, false),
        );
        $op->block1 = $funcBlock;
        $op->parameterMetadata = $this->parameterMetadataFromParams($func->params, $func);
        $this->assignAttributeMetadata($op, $expr);
        $this->assignSourceMetadata($op, $expr);
        AttributeNames::assertAllowDynamicPropertiesClassTargetOnly($op->attributeNames, 'function', $op->attributeEntries);
        AttributeNames::assertAttributeMetaClassTargetOnly($op->attributeNames, 'function', $op->attributeEntries);
        AttributeNames::assertCompileTimeConstTargetOnly($op->attributeNames, 'function', $op->attributeEntries);
        AttributeNames::assertSensitiveParameterParamTargetOnly($op->attributeNames, 'function', $op->attributeEntries);
        AttributeNames::assertReturnTypeWillChangeMethodTargetOnly($op->attributeNames, 'function', $op->attributeEntries);
        AttributeNames::assertDeprecatedTargetAllowed($op->attributeNames, 'function', $op->attributeEntries);
        if ($expr instanceof Op\Expr\Closure) {
            foreach ($closureUseVars as $useVar) {
                $name = $this->boundVariableName($useVar);
                $slot = $funcBlock->getVarSlot($useVar, false);
                $op->closureCaptures[] = [
                    'name' => $name,
                    'slot' => $slot,
                    'byRef' => $useVar->byRef,
                ];
            }
        } elseif ($expr instanceof Op\Expr\ArrowFunction) {
            // Zend auto-captures outer locals/parameters (zend_compile.c); nested fn-in-fn needs
            // explicit closureCaptures so VM/JIT bind at creation time (#4944, #4952).
            $seenCaptureSlots = [];
            $seenCaptureNames = [];
            foreach ($funcBlock->args as $captureOperand) {
                $slot = (int) $funcBlock->args[$captureOperand];
                if (isset($seenCaptureSlots[$slot])) {
                    continue;
                }
                $name = Block::resolveVariableName($captureOperand);
                if (null === $name || '' === $name) {
                    continue;
                }
                if (in_array($name, $funcBlock->paramNames, true)) {
                    continue;
                }
                // $this is bound via Closure::$this / LLVM __object__*, not use()-style capture
                // (zend_closures.c). Auto-capturing it made AOT emit (object, value) ABI + an
                // unreachable assign-from-capture that segfaulted on invoke (#28612).
                if ('this' === $name) {
                    continue;
                }
                $seenCaptureSlots[$slot] = true;
                $seenCaptureNames[$name] = true;
                $funcBlock->closureCaptureSlots[$slot] = true;
                $funcBlock->closureCaptureSlotNames[$slot] = $name;
                $op->closureCaptures[] = [
                    'name' => $name,
                    'slot' => $slot,
                    'byRef' => false,
                ];
            }
            // Transitive capture: nested arrow functions may reference variables from
            // grandparent+ scopes that this arrow function doesn't directly use. Propagate
            // those captures upward so the VM can bind them at creation time (#24690).
            foreach ($funcBlock->opCodes as $innerOp) {
                if (OpCode::TYPE_CLOSURE !== $innerOp->type || [] === $innerOp->closureCaptures) {
                    continue;
                }
                foreach ($innerOp->closureCaptures as $innerCapture) {
                    $capName = $innerCapture['name'];
                    if (isset($seenCaptureNames[$capName])) {
                        continue;
                    }
                    if (in_array($capName, $funcBlock->paramNames, true)) {
                        continue;
                    }
                    if ('this' === $capName) {
                        continue;
                    }
                    $seenCaptureNames[$capName] = true;
                    $syntheticOp = new \PHPCfg\Operand\Variable(
                        new \PHPCfg\Operand\Literal($capName)
                    );
                    $slot = $funcBlock->getVarSlot($syntheticOp, true);
                    if (isset($seenCaptureSlots[$slot])) {
                        continue;
                    }
                    $seenCaptureSlots[$slot] = true;
                    $funcBlock->closureCaptureSlots[$slot] = true;
                    $funcBlock->closureCaptureSlotNames[$slot] = $capName;
                    $op->closureCaptures[] = [
                        'name' => $capName,
                        'slot' => $slot,
                        'byRef' => $innerCapture['byRef'],
                    ];
                }
            }
        }

        return [$op];
    }

    private function boundVariableName(Operand\BoundVariable $useVar): string
    {
        if ($useVar->name instanceof Operand\Literal && is_string($useVar->name->value)) {
            return $useVar->name->value;
        }
        $this->throwCompileLogic('Closure use() variable name must be a literal');
    }

    protected function shouldStubClosureForBootstrap(): bool
    {
        $userScript = getenv('PHP_COMPILER_AOT_USER_SCRIPT');
        if ('1' === $userScript || 'true' === strtolower((string) $userScript)) {
            return false;
        }

        return '1' === (string) getenv('PHP_COMPILER_VENDOR_PRELINK')
            || '1' === (string) getenv('PHP_COMPILER_SELFHOST_AOT');
    }

    protected function markFunctionGenerator(Block $block): void
    {
        if (null === $block->func || null === $this->seen) {
            return;
        }
        foreach ($this->seen as $cfgBlock) {
            $compiled = $this->seen[$cfgBlock];
            if ($compiled->func === $block->func) {
                $compiled->isGenerator = true;
            }
        }
    }

    protected function markGeneratorIfNeeded(Op\CallableOp $callable, Block $funcBlock): void
    {
        if (Block::containsGeneratorOpcodesInCallableBody($funcBlock) || $this->callableOpHasSourceYield($callable)) {
            $this->markFunctionGenerator($funcBlock);
        }
    }

    protected function callableOpHasSourceYield(Op\CallableOp $callable): bool
    {
        if (!$callable instanceof Op) {
            return false;
        }
        $attrs = $callable->getAttributes();

        return isset($attrs[GeneratorYieldSourceMarker::ATTRIBUTE])
            && $attrs[GeneratorYieldSourceMarker::ATTRIBUTE];
    }

    protected function funcDeclReturnTypeIsGenerator(CfgFunc $func): bool
    {
        $returnType = $func->returnType;
        if ($returnType instanceof Op\Type\Literal) {
            return 'Generator' === $returnType->name;
        }
        if ($returnType instanceof Op\Type\Reference) {
            $decl = $returnType->declaration;

            return $decl instanceof Operand\Literal
                && is_string($decl->value)
                && 'Generator' === $decl->value;
        }

        return false;
    }

    protected function funcDeclReturnTypeIsNever(CfgFunc $func): bool
    {
        $returnType = $func->returnType;
        if ($returnType instanceof Op\Type\Never_) {
            return true;
        }
        if ($returnType instanceof Op\Type\Literal && 'never' === strtolower($returnType->name)) {
            return true;
        }

        return false;
    }

    private function isNeverFunctionCallOp(Op $op): bool
    {
        if ($op instanceof Op\Expr\FuncCall) {
            $name = $this->staticNameFromOperand($op->name);
        } elseif ($op instanceof Op\Expr\NsFuncCall) {
            $name = $this->staticNameFromOperand($op->nsName);
        } else {
            return false;
        }
        if (null === $name) {
            return false;
        }

        return isset($this->neverFunctionNames[strtolower($name)]);
    }

    /**
     * Ops after a call to a `: never` function in the same CFG block are unreachable (#4117).
     *
     * @param Op[] $ops
     */
    private function isUnreachableAfterNeverCall(Op $op, array $ops, int $index): bool
    {
        for ($j = $index - 1; $j >= 0; --$j) {
            if ($this->isNeverFunctionCallOp($ops[$j])) {
                return true;
            }
            if (!$ops[$j] instanceof Op\Expr) {
                return false;
            }
        }

        return false;
    }

    private const ISSET_EXPRESSION_COMPILE_ERROR =
        'Cannot use isset() on the result of an expression (you can use "null !== expression" instead)';

    /** Empty `[]` offset in read context — Zend/zend_language_parser.y (#12303). */
    private const ARRAY_EMPTY_OFFSET_READ_COMPILE_ERROR = 'Cannot use [] for reading';

    /**
     * Zend zend_compile.c zend_is_variable(): isset() operands must be variables, dims, or properties (#8802).
     */
    protected function assertIssetVariableOperand(Operand $operand, Block $block): void
    {
        if (null !== $this->findCoalescePropertyFetch($operand, $block)) {
            return;
        }
        if (null !== $this->findCoalesceStaticPropertyFetch($operand, $block)) {
            return;
        }
        if (null !== $this->findCoalesceArrayDimFetch($operand, $block)) {
            return;
        }
        if (null !== $this->unwrapVariableOperand($operand)) {
            return;
        }
        if (null !== $this->unwrapStaticPropertyFetch($operand)) {
            return;
        }

        $this->throwCompileError(self::ISSET_EXPRESSION_COMPILE_ERROR);
    }

    /**
     * @return OpCode[]
     */
    protected function compileIsset(Op\Expr\Isset_ $expr, Block $block): array
    {
        assert(1 === count($expr->vars));
        $nullsafeChain = $this->collectNullsafePropertyFetchChain($expr->vars[0], $block);
        if ([] !== $nullsafeChain) {
            $this->compileIssetNullsafePropertyFetchChain($nullsafeChain, $expr, $block);

            return [];
        }
        $this->assertIssetVariableOperand($expr->vars[0], $block);
        $resultSlot = $this->compileOperand($expr->result, $block, false);
        $propFetch = $this->findCoalescePropertyFetch($expr->vars[0], $block);
        $staticPropFetch = null !== $propFetch
            ? null
            : $this->findCoalesceStaticPropertyFetch($expr->vars[0], $block);
        $dimFetch = null !== $propFetch || null !== $staticPropFetch
            ? null
            : $this->findCoalesceArrayDimFetch($expr->vars[0], $block);
        if (null !== $dimFetch) {
            $chain = $this->collectArrayDimFetchChain($dimFetch, $block);
            foreach ($chain as $chainFetch) {
                $this->rejectArrayEmptyOffsetRead($chainFetch, $block);
            }
            [$prefixOps, $containerSlot] = $this->emitQuietDimFetchChainPrefix($chain, $block);
            $lastFetch = $chain[count($chain) - 1];
            $dimSlot = null !== $lastFetch->dim
                ? $this->compileOperand($lastFetch->dim, $block, true)
                : null;
            $issetOp = $this->makeIssetOpCode($resultSlot, $containerSlot, $dimSlot, false);
            $prefixOps[] = $issetOp;

            return $prefixOps;
        }
        [$containerSlot, $dimSlot] = null !== $propFetch
            ? $this->resolveIssetTargetFromPropertyFetch($propFetch, $block)
            : (null !== $staticPropFetch
                ? $this->resolveIssetTargetFromStaticPropertyFetch($staticPropFetch, $block)
                : $this->resolveIssetTarget($expr->vars[0], $block));
        if (null === $containerSlot) {
            $varSlot = $this->compileOperand($expr->vars[0], $block, true);

            return [new OpCode(OpCode::TYPE_ISSET, $resultSlot, $varSlot, null)];
        }

        $issetOp = $this->makeIssetOpCode($resultSlot, $containerSlot, $dimSlot, null !== $propFetch);
        if (null !== $staticPropFetch) {
            $issetOp->issetOnStaticProperty = true;
        }

        return [$issetOp];
    }

    protected function compileIncludeOp(Op\Expr\Include_ $expr, Block $block): OpCode
    {
        // Include expression value is independent of the enclosing function return type
        // (void/never blocks must still materialize require/include results for call args) (#21938).
        $resultSlot = null;
        if (isset($expr->result) && $this->includeNeedsReturnSlot($expr->result, $block)) {
            $resultSlot = $this->compileOperand($expr->result, $block, false);
        }

        $sourceFile = $expr->getFile() ?? '';
        $includeKind = match ($expr->type) {
            Op\Expr\Include_::TYPE_INCLUDE => OpCode::INCLUDE_KIND_INCLUDE,
            Op\Expr\Include_::TYPE_INCLUDE_ONCE => OpCode::INCLUDE_KIND_INCLUDE_ONCE,
            Op\Expr\Include_::TYPE_REQUIRE => OpCode::INCLUDE_KIND_REQUIRE,
            Op\Expr\Include_::TYPE_REQUIRE_ONCE => OpCode::INCLUDE_KIND_REQUIRE_ONCE,
            default => OpCode::INCLUDE_KIND_INCLUDE_ONCE,
        };

        $deploySpec = ConstStringFolder::tryParseDeployInclude($block->orig, $expr->expr, $sourceFile);
        if (null !== $deploySpec) {
            $pathIndex = count($block->deployIncludePaths);
            $block->deployIncludePaths[$pathIndex] = $deploySpec;
            $compilePath = $deploySpec['compile'] ?? '';
            $pathOperand = new Operand\Literal('' !== $compilePath ? $compilePath : ' ');
            $pathOperand->type = Type::string();

            $op = new OpCode(
                OpCode::TYPE_INCLUDE,
                $this->compileOperand($pathOperand, $block, true),
                $resultSlot,
                $pathIndex,
            );
            $op->includeKind = $includeKind;
            $block->emittedIncludeOrEvalExprIds[spl_object_id($expr)] = true;

            return $op;
        }

        $includePath = ConstStringFolder::foldForInclude($block->orig, $expr->expr, $sourceFile);
        if (null !== $includePath) {
            $resolved = IncludePathResolver::resolve($includePath, $expr->getFile());
            if (null !== $resolved) {
                $this->markCallerLocalsUsedByLiteralInclude($resolved, $block);
                $literal = new Operand\Literal($resolved);
                $literal->type = Type::string();
                $pathIndex = count($block->literalIncludePaths);
                $block->literalIncludePaths[$pathIndex] = $resolved;

                $op = new OpCode(
                    OpCode::TYPE_INCLUDE,
                    $this->compileOperand($literal, $block, true),
                    $resultSlot,
                    $pathIndex,
                );
                $op->includeKind = $includeKind;
                $block->emittedIncludeOrEvalExprIds[spl_object_id($expr)] = true;

                return $op;
            }
        }

        $op = new OpCode(
            OpCode::TYPE_INCLUDE,
            $this->compileOperand($expr->expr, $block, true),
            $resultSlot,
        );
        $op->includeKind = $includeKind;
        $block->emittedIncludeOrEvalExprIds[spl_object_id($expr)] = true;

        return $op;
    }

    /**
     * ?? right branch: evaluate RHS expr ops only when the left is null (#3462, #3798).
     *
     * @return array{0: ?int, 1: Block} value slot and block that must receive the outer ?? assign
     */
    private function compileCoalesceRhsValue(Operand $rhs, Block $targetBlock, Block $entryBlock): array
    {
        $exprOp = $this->findOrigExprOpForOperand($rhs, $entryBlock);
        if ($exprOp instanceof Op\Expr\BinaryOp\Coalesce) {
            $afterCoalesce = $this->compileCoalesce($exprOp, $targetBlock);

            return [$this->compileCoalesceRhsResultSlot($exprOp, $afterCoalesce), $afterCoalesce];
        }
        if (null !== $exprOp) {
            if ($exprOp instanceof Op\Expr\Throw_) {
                foreach ($this->compileThrowExpression($exprOp, $targetBlock, $entryBlock) as $op) {
                    $targetBlock->addOpCode($op);
                }

                return [null, $targetBlock];
            }
            $afterExpr = $this->compileDeferredCoalesceBranchExpr($exprOp, $targetBlock);

            return [$afterExpr[1], $afterExpr[0]];
        }

        return [$this->compileOperand($rhs, $targetBlock, true), $targetBlock];
    }

    /**
     * Stmt-deferred ?? RHS ops are lowered with compileOperand(..., isRead: false); read the same slot (#11801).
     */
    private function compileCoalesceRhsResultSlot(Op\Expr $exprOp, Block $block): ?int
    {
        return $this->compileOperand($exprOp->result, $block, false);
    }

    /**
     * Lower stmt-deferred expr ops on a ?? branch (#3462, #5263).
     *
     * @return array{0: Block, 1: ?int} block and result slot for the deferred expr
     */
    private function compileDeferredCoalesceBranchExpr(Op\Expr $exprOp, Block $targetBlock): array
    {
        if ($exprOp instanceof Op\Expr\NullsafePropertyFetch) {
            $after = $this->compileNullsafePropertyFetch($exprOp, $targetBlock);

            return [$after, $this->compileCoalesceRhsResultSlot($exprOp, $after)];
        }
        if ($exprOp instanceof Op\Expr\NullsafeMethodCall) {
            $after = $this->compileNullsafeMethodCall($exprOp, $targetBlock);

            return [$after, $this->compileCoalesceRhsResultSlot($exprOp, $after)];
        }
        // Lower expr on the ?? branch; read the producer dest from emitted opcodes (#11801, #16206).
        $ops = $this->compileExpr($exprOp, $targetBlock);
        $resultSlot = null;
        foreach ($ops as $op) {
            $targetBlock->addOpCode($op);
            if (null !== $op->arg1) {
                $resultSlot = $op->arg1;
            }
        }
        if (null === $resultSlot) {
            $resultSlot = $this->compileCoalesceRhsResultSlot($exprOp, $targetBlock);
        }

        return [$targetBlock, $resultSlot];
    }

    /**
     * php-cfg emits RHS expr ops (New_, Throw_, …) before Coalesce; lower them on the ?? branch (#3462).
     *
     * @param Op[] $ops
     */
    private function isLoweredByFollowingCoalesce(Op $op, array $ops, int $index): bool
    {
        if (!$op instanceof Op\Expr) {
            return false;
        }
        $count = count($ops);
        for ($j = $index + 1; $j < $count; ++$j) {
            $next = $ops[$j];
            if ($next instanceof Op\Expr\BinaryOp\Coalesce) {
                return $this->exprOpFeedsCoalesceRhs($op, $next);
            }
            if (!$next instanceof Op\Expr\Throw_) {
                return false;
            }
        }

        return false;
    }

    private function exprOpFeedsCoalesceRhs(Op\Expr $op, Op\Expr\BinaryOp\Coalesce $coalesce): bool
    {
        if ($this->operandsChainEqual($op->result, $coalesce->right)) {
            return true;
        }
        $rhsRoot = $this->unwrapOperandChain($coalesce->right);
        if ($rhsRoot instanceof Op\Expr\Throw_ && $this->operandsChainEqual($op->result, $rhsRoot->expr)) {
            return true;
        }

        return false;
    }

    /**
     * php-cfg emits `Coalesce` then `Throw_(coalesce.result)` for `throw $lhs ?? $rhs` (#15315).
     *
     * @param Op[] $ops
     */
    private function isCoalesceLoweredByFollowingThrow(array $ops, int $index): bool
    {
        $op = $ops[$index] ?? null;
        if (!$op instanceof Op\Expr\BinaryOp\Coalesce) {
            return false;
        }
        $count = count($ops);
        for ($j = $index + 1; $j < $count; ++$j) {
            $next = $ops[$j];
            if ($next instanceof Op\Expr\Throw_) {
                return $this->operandsChainEqual($next->expr, $op->result);
            }
            if (!$next instanceof Op\Expr) {
                return false;
            }
        }

        return false;
    }

    /**
     * php-cfg emits inner expr ops (New_, …) before Throw_; lower them inside compileExpr(Throw_) (#3802).
     *
     * @param Op[] $ops
     */
    private function isLoweredByFollowingThrow(Op $op, array $ops, int $index): bool
    {
        if (!$op instanceof Op\Expr) {
            return false;
        }
        $count = count($ops);
        for ($j = $index + 1; $j < $count; ++$j) {
            $next = $ops[$j];
            if ($next instanceof Op\Expr\Throw_) {
                return $this->exprOpFeedsThrowOperand($op, $next);
            }
            if (!$next instanceof Op\Expr) {
                return false;
            }
        }

        return false;
    }

    private function exprOpFeedsThrowOperand(Op\Expr $op, Op\Expr\Throw_ $throw): bool
    {
        return $this->operandsChainEqual($op->result, $throw->expr);
    }

    /**
     * Ops after throw-expr in the same CFG block are unreachable (?: arm, &&/|| RHS, = throw …) (#3802).
     *
     * @param Op[] $ops
     */
    private function isUnreachableAfterThrow(Op $op, array $ops, int $index): bool
    {
        for ($j = $index - 1; $j >= 0; --$j) {
            if ($ops[$j] instanceof Op\Expr\BinaryOp\Coalesce) {
                // ?? RHS throw is lowered on the coalesce branch; following stmts stay reachable (#9447).
                return false;
            }
            if ($ops[$j] instanceof Op\Expr\Throw_) {
                return true;
            }
            if (!$ops[$j] instanceof Op\Expr) {
                return false;
            }
        }

        return false;
    }

    /**
     * php-cfg emits `Throw_` then `Isset_(throw.result)` for `isset(throw …)`.
     * Without a look-ahead, isUnreachableAfterThrow skips Isset_ and the throw runs (#29086).
     *
     * @param Op[] $ops
     */
    private function throwResultFeedsFollowingIsset(Op\Expr\Throw_ $throw, array $ops, int $index): bool
    {
        $count = count($ops);
        for ($j = $index + 1; $j < $count; ++$j) {
            $next = $ops[$j];
            if ($next instanceof Op\Expr\Isset_) {
                foreach ($next->vars as $var) {
                    if ($this->operandsChainEqual($throw->result, $var)) {
                        return true;
                    }
                }

                return false;
            }
            if (!$next instanceof Op\Expr) {
                return false;
            }
        }

        return false;
    }

    private function findThrowInnerExprOp(Op\Expr\Throw_ $throw, Block $block): ?Op\Expr
    {
        $root = $this->unwrapOperandChain($throw->expr);
        if ($root instanceof Op\Expr) {
            return $root;
        }

        return $this->findOrigExprOpForOperand($throw->expr, $block);
    }

    /**
     * @return list<OpCode>
     */
    private function compileThrowExpression(Op\Expr\Throw_ $expr, Block $block, Block ...$extraSearchBlocks): array
    {
        if ($this->isBareRethrowExpression($expr, $block, ...$extraSearchBlocks)) {
            return [new OpCode(OpCode::TYPE_RETHROW)];
        }

        $newOp = $this->findNewExprForThrowOperand($expr, $block, ...$extraSearchBlocks);
        $ops = [];
        $throwSlot = null;
        $throwEmitBlock = null;
        if (null !== $newOp) {
            foreach ($this->compileNewExprForThrow($newOp, $block) as $innerOpcode) {
                $ops[] = $innerOpcode;
            }
            $throwSlot = $this->compileOperand($newOp->result, $block, true);
        } else {
            $innerOp = $this->findThrowInnerExprOp($expr, $block);
            if (null !== $innerOp) {
                if ($innerOp instanceof Op\Expr\BinaryOp\Coalesce) {
                    // ?? merge must complete before TYPE_THROW; compileExpr(Coalesce) leaves throw on entry block (#15315).
                    $throwEmitBlock = $this->compileCoalesce($innerOp, $block);
                } else {
                    foreach ($this->compileExpr($innerOp, $block) as $innerOpcode) {
                        $ops[] = $innerOpcode;
                    }
                }
            }
        }
        $slotBlock = $throwEmitBlock ?? $block;
        if (null === $throwSlot) {
            $throwSlot = $this->compileOperand($expr->expr, $slotBlock, true);
        }
        $line = $expr->getLine();
        $throwOp = new OpCode(
            OpCode::TYPE_THROW,
            $throwSlot,
            $line > 0 ? $line : null
        );
        if (null !== $throwEmitBlock) {
            $throwEmitBlock->addOpCode($throwOp);

            return [];
        }
        $ops[] = $throwOp;

        return $ops;
    }

    private function findNewExprForThrowOperand(Op\Expr\Throw_ $throw, Block ...$searchBlocks): ?Op\Expr\New_
    {
        foreach ($searchBlocks as $searchBlock) {
            if (null === $searchBlock->orig) {
                continue;
            }
            foreach ($searchBlock->orig->children as $child) {
                if ($child instanceof Op\Expr\New_ && $this->operandsChainEqual($child->result, $throw->expr)) {
                    return $child;
                }
            }
        }

        return null;
    }

    /**
     * @return list<OpCode>
     */
    private function compileNewExprForThrow(Op\Expr\New_ $expr, Block $block): array
    {
        // Same as Op\Expr\New_:: class path — defer abstract/enum instantiate to runtime (#25787).
        $className = $this->literalScopeClassName($expr->class);
        $resultSlot = $block->forceFreshVarSlot($expr->result);
        $mergeEcho = $this->mergeEchoSlotForBranch($block);
        if (null !== $mergeEcho && $resultSlot === $mergeEcho) {
            $resultSlot = $block->forceFreshVarSlot($expr->result);
        }
        $line = $expr->getLine();
        $return = [
            new OpCode(
                OpCode::TYPE_NEW,
                $resultSlot,
                $this->compileOperand($expr->class, $block, true),
                $line > 0 ? $line : null
            ),
        ];
        foreach ($this->compileCallArgSends($expr->args, $block, $className, $expr) as $send) {
            $return[] = $send;
        }
        $return[] = $this->compileFuncCallExecOpcode(
            $expr->result,
            $block,
            $line > 0 ? $line : 0
        );

        return $return;
    }

    private function compileOrigExprForOperand(Operand $operand, Block $block): void
    {
        $exprOp = $this->findOrigExprOpForOperand($operand, $block);
        if (null === $exprOp) {
            return;
        }
        $this->compileDeferredCoalesceBranchExpr($exprOp, $block);
    }

    private function findOrigExprOpForOperand(Operand $operand, Block $block): ?Op\Expr
    {
        $root = $this->unwrapOperandChain($operand);
        if ($root instanceof Op\Expr) {
            return $root;
        }
        if (null === $block->orig) {
            return null;
        }
        foreach ($block->orig->children as $child) {
            if ($child instanceof Op\Expr && $this->operandsChainEqual($child->result, $operand)) {
                return $child;
            }
        }

        return null;
    }

    protected function compileCoalesce(
        Op\Expr\BinaryOp\Coalesce $expr,
        Block $block,
        ?Operand $resultOverride = null
    ): Block {
        $resultOperand = $resultOverride ?? $expr->result;
        $nullsafeChain = null !== $expr->left
            ? $this->collectNullsafePropertyFetchChain($expr->left, $block)
            : [];
        $preEvaluatedNullsafeChain = [] !== $nullsafeChain;
        $preEvaluatedNullsafeMethod = null;
        if ($preEvaluatedNullsafeChain) {
            $block = $this->compileNullsafePropertyFetchChainEval($nullsafeChain, $block, true);
        } else {
            $nullsafeMethod = null !== $expr->left
                ? $this->findNullsafeMethodCallProducing($expr->left, $block)
                : null;
            if (null !== $nullsafeMethod) {
                $nullsafeId = spl_object_id($nullsafeMethod);
                if (!isset($this->nullsafeResultSlots[$nullsafeId])) {
                    $block = $this->compileNullsafeMethodCall($nullsafeMethod, $block);
                } elseif (isset($this->nullsafeMergeBlocks[$nullsafeId])) {
                    $block = $this->nullsafeMergeBlocks[$nullsafeId];
                }
                $preEvaluatedNullsafeMethod = $nullsafeMethod;
            }
        }
        // php-cfg may mark the ?? result dead while it is still assigned on branch blocks (#99).
        if ($resultOperand instanceof Operand\Temporary && [] === $resultOperand->usages) {
            $resultOperand->usages[] = $resultOperand;
        }
        if (null === $expr->left || $preEvaluatedNullsafeChain || null !== $preEvaluatedNullsafeMethod) {
            $propFetch = null;
            $staticPropFetch = null;
            $dimFetch = null;
        } else {
            $propFetch = $this->findCoalescePropertyFetch($expr->left, $block);
            $staticPropFetch = null !== $propFetch
                ? null
                : $this->findCoalesceStaticPropertyFetch($expr->left, $block);
            $dimFetch = null !== $propFetch || null !== $staticPropFetch
                ? null
                : $this->findCoalesceArrayDimFetch($expr->left, $block);
        }
        $dimFetchChain = null !== $dimFetch
            ? $this->collectArrayDimFetchChain($dimFetch, $block)
            : [];
        if ([] !== $dimFetchChain) {
            foreach ($dimFetchChain as $chainFetch) {
                $this->rejectArrayEmptyOffsetRead($chainFetch, $block);
            }
        } elseif (null !== $dimFetch) {
            $this->rejectArrayEmptyOffsetRead($dimFetch, $block);
        }
        // ??= on $arr['key']: dim fetch temp is read on the left branch (#3792).
        if (
            null !== $dimFetch
            && $dimFetch->result instanceof Operand\Temporary
            && [] === $dimFetch->result->usages
        ) {
            $dimFetch->result->usages[] = $dimFetch->result;
        }
        $resultSlot = $this->compileOperand($resultOperand, $block, false);

        $checkSlot = $this->compileBoolTemporary($block);
        $nestedDimCoalesce = null !== $dimFetch && count($dimFetchChain) >= 2;
        $issetTarget = null !== $propFetch
            ? $this->resolveIssetTargetFromPropertyFetch($propFetch, $block)
            : (null !== $staticPropFetch
                ? $this->resolveIssetTargetFromStaticPropertyFetch($staticPropFetch, $block)
                : ($nestedDimCoalesce
                    ? null
                    : (null !== $dimFetch
                        ? $this->resolveIssetTargetFromArrayDimFetch($dimFetch, $block)
                        : (null !== $expr->left
                            ? $this->resolveCoalesceIssetTarget($expr->left, $block)
                            : null))));
        $useContainerIsset = null !== $issetTarget || $nestedDimCoalesce;
        if ($useContainerIsset && null !== $issetTarget) {
            [$containerSlot, $dimSlot] = $issetTarget;
            if (null === $containerSlot) {
                $useContainerIsset = false;
            }
        }
        $evaluatedLeftSlot = null;
        if ($useContainerIsset && $nestedDimCoalesce) {
            // Nested `$a['x']['y'] ??…` / `??=`: quiet FETCH_DIM_IS for intermediates (#28954).
            [$prefixOps, $containerSlot] = $this->emitQuietDimFetchChainPrefix($dimFetchChain, $block);
            foreach ($prefixOps as $prefixOp) {
                $block->addOpCode($prefixOp);
            }
            $lastFetch = $dimFetchChain[count($dimFetchChain) - 1];
            $dimSlot = null !== $lastFetch->dim
                ? $this->compileOperand($lastFetch->dim, $block, true)
                : null;
            $block->addOpCode($this->makeIssetOpCode($checkSlot, $containerSlot, $dimSlot, false));
        } elseif ($useContainerIsset && null !== $propFetch) {
            // Instance prop ?? / ??= : fetch once (hook backing / magic IS-mode), then isset on
            // the value. Container isset alone skips __get and treats null-as-set (#29228).
            $this->compilePropertyFetchRead($propFetch, $block, true);
            $evaluatedLeftSlot = $this->compileOperand($propFetch->result, $block, true);
            $block->addOpCode(new OpCode(
                OpCode::TYPE_ISSET,
                $checkSlot,
                $evaluatedLeftSlot,
                null
            ));
            $useContainerIsset = false;
        } elseif ($useContainerIsset) {
            $issetOp = $this->makeIssetOpCode(
                $checkSlot,
                $containerSlot,
                $dimSlot,
                false
            );
            if (null !== $staticPropFetch) {
                $issetOp->issetOnStaticProperty = true;
                $issetOp->issetForCoalesceAssign = true;
            }
            $block->addOpCode($issetOp);
        } elseif (null !== $expr->left) {
            if ($preEvaluatedNullsafeChain) {
                $lastFetch = $nullsafeChain[count($nullsafeChain) - 1];
                $evaluatedLeftSlot = $this->compileOperand($lastFetch->result, $block, false);
            } elseif (null !== $preEvaluatedNullsafeMethod) {
                $evaluatedLeftSlot = $this->compileOperand($preEvaluatedNullsafeMethod->result, $block, false);
            } else {
                $evaluatedLeftSlot = $this->compileOperand($expr->left, $block, true);
            }
            $block->addOpCode(new OpCode(
                OpCode::TYPE_ISSET,
                $checkSlot,
                $evaluatedLeftSlot,
                null
            ));
        } else {
            $block->addOpCode(new OpCode(
                OpCode::TYPE_ISSET,
                $checkSlot,
                $resultSlot,
                null
            ));
        }

        $endBlock = new Block($block->orig);
        $endBlock->inheritUndefinedLocals = true;
        $endBlock->inheritScopeFrom($block);

        $rightBlock = new Block($block->orig);
        $rightBlock->syntheticCfgBranch = true;
        $rightBlock->inheritUndefinedLocals = true;
        $rightBlock->inheritScopeFrom($block);
        [$rightSlot, $rightEmitBlock] = $this->compileCoalesceRhsValue($expr->right, $rightBlock, $block);
        $coalesceAssignTarget = $resultOverride ?? $expr->result;
        if (
            null !== $dimFetch
            && $this->operandsChainEqual($coalesceAssignTarget, $dimFetch->result)
        ) {
            // Nested ??= must FETCH_DIM_W the whole chain so intermediates auto-vivify (#28954).
            if (count($dimFetchChain) >= 2) {
                $this->compileArrayDimFetchWriteChain($dimFetchChain, $rightEmitBlock);
            } else {
                $this->compileArrayDimFetchWrite($dimFetch, $rightEmitBlock);
            }
        }
        if (
            null !== $propFetch
            && $this->operandsChainEqual($coalesceAssignTarget, $propFetch->result)
        ) {
            $this->compilePropertyFetchWrite($propFetch, $rightEmitBlock);
        }
        if (
            null !== $staticPropFetch
            && $this->operandsChainEqual($coalesceAssignTarget, $staticPropFetch->result)
        ) {
            $this->compileStaticPropertyFetchWrite($staticPropFetch, $rightEmitBlock);
        }
        if (null !== $rightSlot && $rightSlot !== $resultSlot) {
            $rightEmitBlock->addOpCode(new OpCode(
                OpCode::TYPE_ASSIGN,
                $resultSlot,
                $resultSlot,
                $rightSlot
            ));
        }

        $leftBlock = new Block($block->orig);
        $leftBlock->syntheticCfgBranch = true;
        $leftBlock->inheritUndefinedLocals = true;
        $leftBlock->inheritScopeFrom($block);
        if ($useContainerIsset) {
            if (null !== $dimFetch) {
                // Container isset already emitted float→int DEP; left read must not (#29664).
                if (count($dimFetchChain) >= 2) {
                    $this->compileArrayDimFetchReadChain($dimFetchChain, $leftBlock, true);
                } else {
                    $this->compileArrayDimFetchRead($dimFetch, $leftBlock, true);
                }
                $leftSlot = $this->compileOperand($dimFetch->result, $leftBlock, true);
                // ??= left branch: skip store when result is the assign lvalue (php-src: no write when set).
                if (null !== $expr->left && !$this->operandsChainEqual($resultOperand, $expr->left)) {
                    $leftBlock->addOpCode(new OpCode(
                        OpCode::TYPE_ASSIGN,
                        $resultSlot,
                        $resultSlot,
                        $leftSlot
                    ));
                }
            } elseif (null !== $propFetch) {
                $this->compilePropertyFetchRead($propFetch, $leftBlock, true);
                $leftSlot = $this->compileOperand($propFetch->result, $leftBlock, true);
                if (!$this->operandsChainEqual($resultOperand, $expr->left)) {
                    $leftBlock->addOpCode(new OpCode(
                        OpCode::TYPE_ASSIGN,
                        $resultSlot,
                        $resultSlot,
                        $leftSlot
                    ));
                }
            } elseif (null !== $staticPropFetch) {
                $this->compileStaticPropertyFetchRead($staticPropFetch, $leftBlock, true);
                $leftSlot = $this->compileOperand($staticPropFetch->result, $leftBlock, true);
                if (!$this->operandsChainEqual($resultOperand, $expr->left)) {
                    $leftBlock->addOpCode(new OpCode(
                        OpCode::TYPE_ASSIGN,
                        $resultSlot,
                        $resultSlot,
                        $leftSlot
                    ));
                }
            } elseif (null !== $expr->left) {
                $leftSlot = $this->compileOperand($expr->left, $leftBlock, true);
                if (!$this->operandsChainEqual($resultOperand, $expr->left)) {
                    $leftBlock->addOpCode(new OpCode(
                        OpCode::TYPE_ASSIGN,
                        $resultSlot,
                        $resultSlot,
                        $leftSlot
                    ));
                }
            }
        } elseif (null !== $evaluatedLeftSlot) {
            // Nullsafe and other pre-evaluated ?? left operands: reuse entry-block temp (#9744).
            if (!$this->operandsChainEqual($resultOperand, $expr->left)) {
                $leftBlock->addOpCode(new OpCode(
                    OpCode::TYPE_ASSIGN,
                    $resultSlot,
                    $resultSlot,
                    $evaluatedLeftSlot
                ));
            }
        }

        $leftJump = new OpCode(OpCode::TYPE_JUMP);
        $leftJump->block1 = $endBlock;
        $leftBlock->addOpCode($leftJump);
        $rightJump = new OpCode(OpCode::TYPE_JUMP);
        $rightJump->block1 = $endBlock;
        $rightEmitBlock->addOpCode($rightJump);
        $endBlock->parents[] = $leftBlock;
        $endBlock->parents[] = $rightEmitBlock;
        $endBlock->inheritScopeFrom($leftBlock);
        $endBlock->inheritScopeFrom($rightEmitBlock);

        $this->coalesceResultSlots[spl_object_id($expr)] = $resultSlot;
        $this->coalesceMergeBlocks[spl_object_id($expr)] = $endBlock;

        $coalesceOp = new OpCode(
            OpCode::TYPE_COALESCE,
            $resultSlot,
            $checkSlot
        );
        $coalesceOp->block1 = $leftBlock;
        $coalesceOp->block2 = $rightBlock;
        $coalesceOp->block3 = $endBlock;
        $block->addOpCode($coalesceOp);

        return $endBlock;
    }

    /**
     * Emit a read fetch in $block (used by ?? left branch when the stmt fetch was skipped).
     */
    private function compilePropertyFetchRead(
        Op\Expr\PropertyFetch $fetch,
        Block $block,
        bool $propertyHookCoalesceRead = false
    ): void {
        $op = new OpCode(
            OpCode::TYPE_PROPERTY_FETCH,
            $this->compileOperand($fetch->result, $block, false),
            $this->compileOperand($fetch->var, $block, true),
            $this->compileOperand($fetch->name, $block, true)
        );
        if ($propertyHookCoalesceRead) {
            $op->propertyHookCoalesceRead = true;
        }
        $block->addOpCode($op);
        if (null !== $op->arg1) {
            $fetchSlot = (int) $op->arg1;
            if (null !== $fetch->result) {
                $block->bindOperandScopeSlot($fetch->result, $fetchSlot);
            }
        }
        $this->syncPropertyFetchResultToFollowingFuncCallArg($fetch, $block);
    }

    /**
     * trim($obj->prop) — php-cfg hoists PropertyFetch as its own stmt with a dead arg temp (#14467, libxml).
     */
    private function syncPropertyFetchResultToFollowingFuncCallArg(
        Op\Expr\PropertyFetch $fetch,
        Block $block
    ): void {
        if (null === $block->orig) {
            return;
        }
        $fetchIndex = array_search($fetch, $block->orig->children, true);
        if (!is_int($fetchIndex)) {
            return;
        }
        $next = $block->orig->children[$fetchIndex + 1] ?? null;
        if (!$next instanceof Op\Expr\FuncCall && !$next instanceof Op\Expr\NsFuncCall) {
            return;
        }
        $fetchSlot = $this->compiledExpressionPreludeResultSlotBeforePendingFuncCall($block, $fetch);
        if (null === $fetchSlot) {
            foreach (array_reverse($block->opCodes) as $opCode) {
                if (OpCode::TYPE_PROPERTY_FETCH === $opCode->type && null !== $opCode->arg1) {
                    $fetchSlot = (int) $opCode->arg1;
                    break;
                }
            }
        }
        if (null === $fetchSlot) {
            $fetchSlot = $block->slotForOperand($fetch->result);
        }
        if (null === $fetchSlot) {
            return;
        }
        if (null !== $fetch->result) {
            $block->bindOperandScopeSlot($fetch->result, $fetchSlot);
        }
        if (!property_exists($next, 'args') || !is_array($next->args)) {
            return;
        }
        foreach ($next->args as $argIndex => $arg) {
            if (!$arg instanceof Operand) {
                continue;
            }
            if (!$this->propertyFetchFuncCallArgUsesHoistedFetch($arg, (int) $argIndex, $fetch, $next)) {
                continue;
            }
            $block->bindOperandScopeSlot($arg, $fetchSlot);
            $this->registerSyncedCoalesceFuncCallArgSlot($arg, $fetchSlot);
        }
        if (null !== $fetch->result) {
            $this->registerSyncedCoalesceFuncCallArgSlot($fetch->result, $fetchSlot);
        }
    }

    /**
     * var_export($o?->prop) — php-cfg hoists NullsafePropertyFetch before FuncCall (#18455).
     */
    private function syncNullsafePropertyFetchResultToFollowingFuncCallArg(
        Op\Expr\NullsafePropertyFetch $fetch,
        Block $block
    ): void {
        if (null === $block->orig) {
            return;
        }
        $fetchIndex = array_search($fetch, $block->orig->children, true);
        if (!is_int($fetchIndex)) {
            return;
        }
        $next = $block->orig->children[$fetchIndex + 1] ?? null;
        if (!$next instanceof Op\Expr\FuncCall && !$next instanceof Op\Expr\NsFuncCall) {
            return;
        }
        $fetchSlot = $this->compiledExpressionPreludeResultSlotBeforePendingFuncCall($block, $fetch);
        if (null === $fetchSlot) {
            $fetchSlot = $this->slotForNullsafeResult($block, $fetch);
        }
        if (null === $fetchSlot) {
            $fetchSlot = $block->slotForOperand($fetch->result);
        }
        if (null === $fetchSlot) {
            return;
        }
        if (null !== $fetch->result) {
            $block->bindOperandScopeSlot($fetch->result, $fetchSlot);
        }
        if (!property_exists($next, 'args') || !is_array($next->args)) {
            return;
        }
        foreach ($next->args as $argIndex => $arg) {
            if (!$arg instanceof Operand) {
                continue;
            }
            if (null !== $fetch->result && $this->operandsReferToSameVariable($arg, $fetch->result)) {
                $block->bindOperandScopeSlot($arg, $fetchSlot);
                $this->registerSyncedCoalesceFuncCallArgSlot($arg, $fetchSlot);
                continue;
            }
            if (!$this->callArgIsDeadInlineTemporary($arg)) {
                continue;
            }
            $deadTempIndices = [];
            foreach ($next->args as $i => $candidate) {
                if (!$candidate instanceof Operand || $this->isEmbeddedCallLiteralArg($candidate)) {
                    continue;
                }
                if ($this->callArgIsDeadInlineTemporary($candidate)) {
                    $deadTempIndices[] = (int) $i;
                }
            }
            if (1 === \count($deadTempIndices) && (int) $argIndex === $deadTempIndices[0]) {
                $block->bindOperandScopeSlot($arg, $fetchSlot);
                $this->registerSyncedCoalesceFuncCallArgSlot($arg, $fetchSlot);
            }
        }
        if (null !== $fetch->result) {
            $this->registerSyncedCoalesceFuncCallArgSlot($fetch->result, $fetchSlot);
        }
    }

    /**
     * Hoisted PropertyFetch before FuncCall — only the consumer arg gets the fetch slot (#14467, #18427).
     *
     * implode(',', $obj->items) must not rewire the separator literal to the property temp.
     */
    private function propertyFetchFuncCallArgUsesHoistedFetch(
        Operand $arg,
        int $argIndex,
        Op\Expr\PropertyFetch $fetch,
        Op $callOp
    ): bool {
        if ($this->isEmbeddedCallLiteralArg($arg)) {
            return false;
        }
        if (null !== $fetch->result && $this->operandsReferToSameVariable($arg, $fetch->result)) {
            return true;
        }
        if (!$this->callArgIsDeadInlineTemporary($arg)) {
            return false;
        }
        if (!property_exists($callOp, 'args') || !is_array($callOp->args)) {
            return false;
        }
        $deadTempIndices = [];
        foreach ($callOp->args as $i => $candidate) {
            if (!$candidate instanceof Operand || $this->isEmbeddedCallLiteralArg($candidate)) {
                continue;
            }
            if ($this->callArgIsDeadInlineTemporary($candidate)) {
                $deadTempIndices[] = (int) $i;
            }
        }

        return 1 === \count($deadTempIndices) && (int) $argIndex === $deadTempIndices[0];
    }

    /** Last hoisted TYPE_PROPERTY_FETCH result slot in $block (trim($obj->prop) dead-arg wiring). */
    private function lastPropertyFetchResultSlotBeforePendingCall(Block $block): ?string
    {
        foreach (array_reverse($block->opCodes) as $opCode) {
            if (OpCode::TYPE_PROPERTY_FETCH === $opCode->type && null !== $opCode->arg1) {
                return (string) $opCode->arg1;
            }
        }

        return null;
    }

    /**
     * Hoisted PropertyFetch before MethodCall/FuncCall when scalar preludes sit between (#18860).
     *
     * importNode($doc->documentElement->firstChild, true) — ConstFetch between chain and call.
     *
     * @return Op\Expr\PropertyFetch|Op\Expr\NullsafePropertyFetch|null
     */
    private function propertyFetchPreludeMatchingCallArg(
        Block $block,
        Op $cfgCallOp,
        int $callIndex,
        int $argIndex,
        Operand $arg
    ): Op\Expr\PropertyFetch|Op\Expr\NullsafePropertyFetch|null {
        if (null === $block->orig || $callIndex < 1 || !property_exists($cfgCallOp, 'args')) {
            return null;
        }
        $callArgs = $cfgCallOp->args;
        if (!\is_array($callArgs) || !$this->callArgIsDeadInlineTemporary($arg)) {
            return null;
        }
        // importNode($doc->documentElement->firstChild, true) — hoisted true is not a PropertyFetch arg (#18860, re-open).
        if (null !== $this->tryFoldHoistedBoolNullLiteralCallArg($arg, $block, $cfgCallOp, $argIndex)) {
            return null;
        }
        $nonLiteralArgCount = 0;
        foreach ($callArgs as $callArg) {
            if (null !== $callArg && !$this->isEmbeddedCallLiteralArg($callArg)) {
                ++$nonLiteralArgCount;
            }
        }
        $trailingScalarPreludeCount = 0;
        $scalarProbeIndex = $callIndex - 1;
        while ($scalarProbeIndex >= 0) {
            $scalarProbe = $block->orig->children[$scalarProbeIndex] ?? null;
            if ($scalarProbe instanceof Op\Expr\ConstFetch || $scalarProbe instanceof Op\Expr\ClassConstFetch) {
                ++$trailingScalarPreludeCount;
                --$scalarProbeIndex;
                continue;
            }
            break;
        }
        $propertyArgCount = max(0, $nonLiteralArgCount - $trailingScalarPreludeCount);
        $fetches = [];
        $probeIndex = $callIndex - 1;
        while ($probeIndex >= 0) {
            $probe = $block->orig->children[$probeIndex] ?? null;
            if ($probe instanceof Op\Expr\ConstFetch || $probe instanceof Op\Expr\ClassConstFetch) {
                --$probeIndex;
                continue;
            }
            if (
                $probe instanceof Op\Expr\PropertyFetch
                || $probe instanceof Op\Expr\NullsafePropertyFetch
            ) {
                $fetches[] = $probe;
                --$probeIndex;
                continue;
            }
            break;
        }
        if ([] === $fetches) {
            return null;
        }
        // Chained $obj->a->b hoists intermediate PropertyFetches that feed the next
        // fetch's receiver, not call args. Keep only leaf fetches (#19719, #18860).
        $leafFetches = [];
        foreach ($fetches as $i => $fetch) {
            $feedsNearerFetch = false;
            for ($j = 0; $j < $i; ++$j) {
                $nearer = $fetches[$j];
                if (
                    null !== $fetch->result
                    && property_exists($nearer, 'var')
                    && null !== $nearer->var
                    && $this->operandsReferToSameVariable($fetch->result, $nearer->var)
                ) {
                    $feedsNearerFetch = true;
                    break;
                }
            }
            if (!$feedsNearerFetch) {
                $leafFetches[] = $fetch;
            }
        }
        $fetches = $leafFetches;
        // MethodCall receiver PropertyFetch is hoisted with arg fetches but is not a call arg
        // (documentElement->insertBefore($d2->…->firstChild, $d1->…->firstChild)) (#22710).
        if ($cfgCallOp instanceof Op\Expr\MethodCall && null !== $cfgCallOp->var) {
            $receiverVar = $cfgCallOp->var;
            $fetches = \array_values(\array_filter(
                $fetches,
                function ($fetch) use ($receiverVar): bool {
                    return null === $fetch->result
                        || !$this->operandsReferToSameVariable($receiverVar, $fetch->result);
                }
            ));
        }
        // $a->parentNode->replaceChild($b->cloneNode(true), $a) — parentNode feeds the *outer*
        // MethodCall receiver, not cloneNode's bool arg. Drop PropertyFetches consumed as
        // later sibling MethodCall receivers (#25876).
        if (\is_int($callIndex) && null !== $block->orig) {
            $laterReceiverVars = [];
            for ($later = $callIndex + 1, $nChildren = \count($block->orig->children); $later < $nChildren; ++$later) {
                $laterOp = $block->orig->children[$later] ?? null;
                if (
                    $laterOp instanceof Op\Expr\MethodCall
                    && null !== $laterOp->var
                ) {
                    $laterReceiverVars[] = $laterOp->var;
                }
            }
            if ([] !== $laterReceiverVars) {
                $fetches = \array_values(\array_filter(
                    $fetches,
                    function ($fetch) use ($laterReceiverVars): bool {
                        if (null === $fetch->result) {
                            return true;
                        }
                        foreach ($laterReceiverVars as $laterVar) {
                            if ($this->operandsReferToSameVariable($laterVar, $fetch->result)) {
                                return false;
                            }
                        }

                        return true;
                    }
                ));
            }
        }
        if ([] === $fetches) {
            return null;
        }
        if (\count($fetches) > $propertyArgCount) {
            // Extra leaf is usually the MethodCall receiver (documentElement->C14NFile($tmp)).
            // When every non-literal arg is a scalar ConstFetch (propertyArgCount===0), leftovers
            // are outer receivers — not this call's args (#25876 nested cloneNode(true/false)).
            if (0 !== $argIndex || 0 === $propertyArgCount) {
                return null;
            }

            return $fetches[0];
        }
        // Map leaf PropertyFetches onto dead-temp arg indices (skip embedded literals).
        // two('L', $el->tagName) after @$doc->loadXML() — raw argIndex 1 must match the
        // sole dead-temp slot, not firstPropertyArgIndex=0 (#21439, re-#19719/#18860).
        $deadTempArgIndices = [];
        foreach ($callArgs as $i => $callArg) {
            if (
                $callArg instanceof Operand
                && !$this->isEmbeddedCallLiteralArg($callArg)
                && $this->callArgIsDeadInlineTemporary($callArg)
            ) {
                $deadTempArgIndices[] = (int) $i;
            }
        }
        $propertyDeadTempArgIndices = [];
        foreach ($deadTempArgIndices as $deadIdx) {
            $deadArg = $callArgs[$deadIdx] ?? null;
            if (
                $deadArg instanceof Operand
                && null !== $this->tryFoldHoistedBoolNullLiteralCallArg($deadArg, $block, $cfgCallOp, $deadIdx)
            ) {
                continue;
            }
            $propertyDeadTempArgIndices[] = $deadIdx;
        }
        // trailingScalarPreludeCount already subtracts ConstFetch/ClassConstFetch (incl. LIBXML_*),
        // but tryFold only drops true/false/null — trim so saveXML($el->prop, LIBXML_*) does not
        // bind the PropertyFetch slot to the options arg (#25292).
        if (\count($propertyDeadTempArgIndices) > $propertyArgCount) {
            $propertyDeadTempArgIndices = \array_slice($propertyDeadTempArgIndices, 0, $propertyArgCount);
        }
        $deadOrdinal = array_search($argIndex, $propertyDeadTempArgIndices, true);
        if (!\is_int($deadOrdinal)) {
            return null;
        }
        // MethodCall/FuncCall producers fill leading dead-temp args; PropertyFetch
        // leaves map to the trailing propertyArgCount slots (#19719):
        // insertBefore($d->createElement('x'), $r->lastChild).
        $fetchCount = \count($fetches);
        $firstFetchDeadOrdinal = \count($propertyDeadTempArgIndices) - $fetchCount;
        if ($deadOrdinal < $firstFetchDeadOrdinal) {
            return null;
        }
        $ordinal = $fetchCount - 1 - ($deadOrdinal - $firstFetchDeadOrdinal);
        if ($ordinal < 0 || $ordinal >= $fetchCount) {
            return null;
        }

        return $fetches[$ordinal];
    }

    /**
     * @return ?string scope slot for a hoisted PropertyFetch call arg (#18860)
     */
    private function propertyFetchPreludeResultSlot(
        Block $block,
        Op\Expr\PropertyFetch|Op\Expr\NullsafePropertyFetch $prelude,
        Op $cfgCallOp
    ): ?string {
        if (null === $block->slotForOperand($prelude->result)) {
            foreach ($this->compileExpr($prelude, $block) as $op) {
                $block->addOpCode($op);
            }
        }

        // Prefer this prelude's operand slot. Looking back for the last TYPE_PROPERTY_FETCH
        // collapses distinct PropertyFetch call args onto one temp — e.g. peek($a->x, $b->x)
        // and insertBefore($d2->documentElement->firstChild, $d1->…->firstChild) (#22710).
        $operandSlot = $block->slotForOperand($prelude->result);
        if (null !== $operandSlot) {
            return (string) $operandSlot;
        }

        return $this->compiledExpressionPreludeResultSlotBeforePendingFuncCall($block, $prelude)
            ?? $this->slotForInlineCallArgProducerResult(
                $block,
                $prelude,
                $cfgCallOp,
                null !== $block->orig ? $block->orig->children : null
            );
    }

    private function compileStaticPropertyFetchRead(
        Op\Expr\StaticPropertyFetch $fetch,
        Block $block,
        bool $propertyHookCoalesceRead = false
    ): void {
        $op = new OpCode(
            OpCode::TYPE_STATIC_PROPERTY_FETCH,
            $this->compileOperand($fetch->result, $block, false),
            $this->compileOperand($fetch->class, $block, true),
            $this->compileStaticPropertyNameSlot($fetch->name, $fetch->class, $block)
        );
        if ($propertyHookCoalesceRead) {
            $op->propertyHookCoalesceRead = true;
        }
        $block->addOpCode($op);
    }

    /**
     * Emit a write fetch in $block (used by ??= right branch when backing is null, #6472).
     */
    private function compilePropertyFetchWrite(Op\Expr\PropertyFetch $fetch, Block $block): void
    {
        $this->rejectTemporaryExpressionInWriteContext($fetch->result, $block, $fetch);
        $block->addOpCode(new OpCode(
            OpCode::TYPE_PROPERTY_FETCH_WRITE,
            $this->compileOperand($fetch->result, $block, false),
            $this->compileOperand($fetch->var, $block, true),
            $this->compileOperand($fetch->name, $block, true)
        ));
    }

    private function compileStaticPropertyFetchWrite(Op\Expr\StaticPropertyFetch $fetch, Block $block): void
    {
        $block->addOpCode(new OpCode(
            OpCode::TYPE_STATIC_PROPERTY_FETCH,
            $this->compileOperand($fetch->result, $block, false),
            $this->compileOperand($fetch->class, $block, true),
            $this->compileStaticPropertyNameSlot($fetch->name, $fetch->class, $block)
        ));
    }

    /**
     * Emit a read fetch in $block (used by ?? left branch when the stmt fetch was skipped).
     *
     * @param bool $skipFloatKeyDeprecation When true, isset already warned for this dim (#29664).
     */
    private function compileArrayDimFetchRead(
        Op\Expr\ArrayDimFetch $fetch,
        Block $block,
        bool $skipFloatKeyDeprecation = false
    ): void {
        $this->rejectArrayEmptyOffsetRead($fetch, $block);
        $op = new OpCode(
            OpCode::TYPE_ARRAY_DIM_FETCH,
            $this->compileOperand($fetch->result, $block, false),
            $this->compileArrayDimFetchContainerSlot($fetch, $block),
            null !== $fetch->dim ? $this->compileOperand($fetch->dim, $block, true) : null
        );
        $op->arrayDimFetchSkipFloatKeyDeprecation = $skipFloatKeyDeprecation;
        $block->addOpCode($op);
    }

    /**
     * Emit a write fetch in $block (used by ??= right branch when the key is absent, issue #1235).
     */
    private function compileArrayDimFetchWrite(Op\Expr\ArrayDimFetch $fetch, Block $block): void
    {
        $this->rejectTemporaryExpressionInWriteContext($fetch->result, $block, $fetch);
        $block->addOpCode(new OpCode(
            OpCode::TYPE_ARRAY_DIM_FETCH_WRITE,
            $this->compileOperand($fetch->result, $block, false),
            $this->compileArrayDimFetchContainerSlot($fetch, $block),
            null !== $fetch->dim ? $this->compileOperand($fetch->dim, $block, true) : null
        ));
    }

    /**
     * FETCH_DIM_W for each dim in an outermost-first nested ??= write chain (#28954).
     *
     * @param list<Op\Expr\ArrayDimFetch> $chain
     */
    private function compileArrayDimFetchWriteChain(array $chain, Block $block): void
    {
        foreach ($chain as $fetch) {
            $this->compileArrayDimFetchWrite($fetch, $block);
        }
    }

    /**
     * Read each dim in an outermost-first nested ?? / ??= left branch (#28954).
     *
     * @param list<Op\Expr\ArrayDimFetch> $chain
     * @param bool                        $skipFloatKeyDeprecation Last-dim isset already warned (#29664).
     */
    private function compileArrayDimFetchReadChain(
        array $chain,
        Block $block,
        bool $skipFloatKeyDeprecation = false
    ): void {
        $last = count($chain) - 1;
        foreach ($chain as $i => $fetch) {
            // Only the final dim shares the coalesce isset probe; prefixes used quiet FETCH_DIM_IS.
            $this->compileArrayDimFetchRead(
                $fetch,
                $block,
                $skipFloatKeyDeprecation && $i === $last
            );
        }
    }

    /**
     * Compile dim-fetch for call-arg wiring — force write fetch for by-ref builtins (#4512).
     */
    private function compileArrayDimFetchForCallArg(
        Op\Expr\ArrayDimFetch $fetch,
        Block $block,
        ?Op $cfgCallOp,
        int $argIndex
    ): void {
        $forWrite = false;
        if (null !== $cfgCallOp) {
            $calleeName = $this->funcCallExprCalleeName($cfgCallOp);
            if (null !== $calleeName && $this->callArgRequiresByRef($calleeName, $argIndex, $fetch->result, $block)) {
                $forWrite = true;
            }
        }
        if (!$forWrite) {
            $forWrite = $this->isArrayDimFetchForWrite($fetch, $block);
        }
        if ($forWrite) {
            $this->compileArrayDimFetchWrite($fetch, $block);
        } else {
            foreach ($this->compileExpr($fetch, $block) as $op) {
                $block->addOpCode($op);
            }
        }
    }

    /**
     * Container slot for array dim fetch/write opcodes.
     *
     * PhiResolver may clear {@see Op\Expr\ArrayDimFetch::$var} after param phi merge in large
     * compilation units (PackEngine.parseFormat, #13092). Recover from typed parameters.
     */
    protected function compileArrayDimFetchContainerSlot(Op\Expr\ArrayDimFetch $fetch, Block $block): int
    {
        if (null !== $fetch->var) {
            $slot = $this->compileOperand($fetch->var, $block, true);
            if (null !== $slot) {
                return $slot;
            }
        }

        $recovered = $this->recoverPhiClearedArrayDimFetchContainer($fetch, $block);
        if (null !== $recovered) {
            return $recovered;
        }

        $this->throwCompileLogic('ArrayDimFetch missing container operand');
    }

    /**
     * PhiResolver postprocessor can leave ArrayDimFetch.var null while the container CV remains
     * a typed parameter (php-cfg/Visitor/PhiResolver.php, #13092).
     */
    private function recoverPhiClearedArrayDimFetchContainer(
        Op\Expr\ArrayDimFetch $fetch,
        Block $block
    ): ?int {
        if (null !== $fetch->var || null === $block->func || [] === $block->func->params) {
            return null;
        }

        $preferred = $this->isArrayAppendDim($fetch->dim) ? 'array' : 'string';
        foreach ($block->func->params as $param) {
            if (null === $param->result) {
                continue;
            }
            $decl = $this->declNameFromCfgType($param->declaredType ?? null);
            if ('array' === $preferred) {
                if ('array' !== $decl && null === $this->genericArraySpecFromCfgType($param->declaredType ?? null)) {
                    continue;
                }
            } elseif ('string' !== $decl) {
                continue;
            }
            $slot = $this->compileOperand($param->result, $block, true);
            if (null !== $slot) {
                return $slot;
            }
        }

        foreach ($block->func->params as $param) {
            if (null === $param->result) {
                continue;
            }
            $slot = $this->compileOperand($param->result, $block, true);
            if (null !== $slot) {
                return $slot;
            }
        }

        if ($this->isArrayAppendDim($fetch->dim) || null === $fetch->dim) {
            $emptyInit = $this->recoverEmptyArrayInitLocalOperand($block->func);
            if (null !== $emptyInit) {
                $slot = $this->compileOperand($emptyInit, $block, true);
                if (null !== $slot) {
                    return $slot;
                }
            }
        }

        if (null !== $fetch->dim) {
            $dimRoot = Block::cfgVarRoot($fetch->dim);
            $dimName = null !== $dimRoot ? Block::resolveVariableName($dimRoot) : null;
            $call = 'currentArg' === $dimName
                ? $this->findFuncCallFirstArgOperand($block->func, 'count')
                : $this->findFuncCallFirstArgOperand($block->func, 'strlen');
            if (null !== $call) {
                $slot = $this->compileOperand($call, $block, true);
                if (null !== $slot) {
                    return $slot;
                }
            }
        }

        return null;
    }

    private function recoverEmptyArrayInitLocalOperand(CfgFunc $func): ?Operand
    {
        if (null === $func->cfg) {
            return null;
        }
        $emptyInits = [];
        $walk = function ($node) use (&$walk, &$emptyInits): void {
            if ($node instanceof CfgBlock) {
                $children = $node->children;
                foreach ($children as $i => $child) {
                    if (
                        $child instanceof Op\Expr\Assign
                        && $i > 0
                        && $children[$i - 1] instanceof Op\Expr\Array_
                    ) {
                        $arr = $children[$i - 1];
                        if ([] === $arr->keys && [] === $arr->values && $arr->result === $child->expr) {
                            $emptyInits[] = $child->var;
                        }
                    }
                    $walk($child);
                }
            }
            if ($node instanceof Op\Stmt\JumpIf) {
                $walk($node->if);
                $walk($node->else);
            }
            if ($node instanceof Op\Stmt\Loop) {
                $walk($node->loop);
            }
            if ($node instanceof Op\Stmt\Foreach_) {
                $walk($node->loop);
            }
        };
        $walk($func->cfg);

        return 1 === count($emptyInits) ? $emptyInits[0] : null;
    }

    private function findFuncCallFirstArgOperand(CfgFunc $func, string $name): ?Operand
    {
        $found = null;
        $walk = function ($node) use (&$walk, $name, &$found): void {
            if (null !== $found) {
                return;
            }
            if ($node instanceof Op\Expr\FuncCall) {
                $fn = $node->name;
                if ($fn instanceof Literal && $name === $fn->value && isset($node->args[0])) {
                    $found = $node->args[0];

                    return;
                }
            }
            if ($node instanceof CfgBlock) {
                foreach ($node->children as $child) {
                    $walk($child);
                }
            }
            if ($node instanceof Op\Stmt\JumpIf) {
                $walk($node->if);
                $walk($node->else);
            }
            if ($node instanceof Op\Stmt\Loop) {
                $walk($node->loop);
            }
            if ($node instanceof Op\Stmt\Foreach_) {
                $walk($node->loop);
            }
        };
        $walk($func->cfg);

        return $found;
    }

    /**
     * Array offset immediately after ?-> property/method fetch (issue #3516).
     *
     * @param Op[] $ops
     */
    private function isNullsafeChainArrayDimFetch(array $ops, int $index): bool
    {
        if ($index < 1) {
            return false;
        }
        $fetch = $ops[$index];
        if (!$fetch instanceof Op\Expr\ArrayDimFetch) {
            return false;
        }
        $prev = $ops[$index - 1];
        if (!$prev instanceof Op\Expr\NullsafePropertyFetch && !$prev instanceof Op\Expr\NullsafeMethodCall) {
            return false;
        }

        return $prev->result === $fetch->var;
    }

    protected function compileNullsafeArrayDimFetch(Op\Expr\ArrayDimFetch $expr, Block $block): Block
    {
        $this->rejectArrayEmptyOffsetRead($expr, $block);
        $resultSlot = $this->compileOperand($expr->result, $block, false);
        $containerSlot = $this->compileOperand($expr->var, $block, true);
        $dimSlot = null !== $expr->dim ? $this->compileOperand($expr->dim, $block, true) : null;

        $endBlock = new Block($block->orig);
        $endBlock->inheritUndefinedLocals = true;
        $endBlock->inheritScopeFrom($block);

        $nullBlock = new Block($block->orig);
        $nullBlock->inheritUndefinedLocals = true;
        $nullBlock->inheritScopeFrom($block);
        $nullLiteral = new Operand\Literal(null);
        $nullLiteral->type = Type::null();
        $nullValueSlot = $this->compileOperand($nullLiteral, $nullBlock, true);
        $nullBlock->addOpCode(new OpCode(
            OpCode::TYPE_ASSIGN,
            $resultSlot,
            $resultSlot,
            $nullValueSlot
        ));
        $nullJump = new OpCode(OpCode::TYPE_JUMP);
        $nullJump->block1 = $endBlock;
        $nullBlock->addOpCode($nullJump);

        $fetchBlock = new Block($block->orig);
        $fetchBlock->inheritUndefinedLocals = true;
        $fetchBlock->inheritScopeFrom($block);
        $fetchBlock->addOpCode(new OpCode(
            OpCode::TYPE_ARRAY_DIM_FETCH,
            $this->compileOperand($expr->result, $fetchBlock, false),
            $this->compileArrayDimFetchContainerSlot($expr, $fetchBlock),
            $dimSlot
        ));
        $fetchJump = new OpCode(OpCode::TYPE_JUMP);
        $fetchJump->block1 = $endBlock;
        $fetchBlock->addOpCode($fetchJump);
        $endBlock->parents[] = $nullBlock;
        $endBlock->parents[] = $fetchBlock;

        $nullsafeOp = new OpCode(
            OpCode::TYPE_NULLSAFE,
            $resultSlot,
            $containerSlot
        );
        $nullsafeOp->block1 = $nullBlock;
        $nullsafeOp->block2 = $fetchBlock;
        $nullsafeOp->block3 = $endBlock;
        $block->addOpCode($nullsafeOp);

        return $endBlock;
    }

    protected function compileNullsafePropertyFetch(
        Op\Expr\NullsafePropertyFetch $expr,
        Block $block,
        bool $allowUninitNullableShortCircuit = false
    ): Block {
        $resultSlot = $this->compileOperand($expr->result, $block, false);
        $receiverSlot = $this->compileNullsafeReceiverSlot($expr->var, $block, $allowUninitNullableShortCircuit);

        $endBlock = new Block($block->orig);
        $endBlock->inheritUndefinedLocals = true;
        $endBlock->inheritScopeFrom($block);

        $nullBlock = new Block($block->orig);
        $nullBlock->inheritUndefinedLocals = true;
        $nullBlock->inheritScopeFrom($block);
        $nullLiteral = new Operand\Literal(null);
        $nullLiteral->type = Type::null();
        $nullValueSlot = $this->compileOperand($nullLiteral, $nullBlock, true);
        $nullBlock->addOpCode(new OpCode(
            OpCode::TYPE_ASSIGN,
            $resultSlot,
            $resultSlot,
            $nullValueSlot
        ));
        $nullJump = new OpCode(OpCode::TYPE_JUMP);
        $nullJump->block1 = $endBlock;
        $nullBlock->addOpCode($nullJump);

        $fetchBlock = new Block($block->orig);
        $fetchBlock->inheritUndefinedLocals = true;
        $fetchBlock->inheritScopeFrom($block);
        // Use the same receiver slot NULLSAFE branched on — Temporary.original is often
        // null after type passes, so re-compileOperand($expr->var) can bind a dead slot (#19591).
        $nullsafePropertyFetch = new OpCode(
            OpCode::TYPE_PROPERTY_FETCH,
            $this->compileOperand($expr->result, $fetchBlock, false),
            $receiverSlot,
            $this->compileOperand($expr->name, $fetchBlock, true)
        );
        $nullsafePropertyFetch->nullsafeFetchPropertyRead = true;
        $nullsafePropertyFetch->nullsafeUninitNullableToNull = $allowUninitNullableShortCircuit;
        $fetchBlock->addOpCode($nullsafePropertyFetch);
        $fetchJump = new OpCode(OpCode::TYPE_JUMP);
        $fetchJump->block1 = $endBlock;
        $fetchBlock->addOpCode($fetchJump);
        $endBlock->parents[] = $nullBlock;
        $endBlock->parents[] = $fetchBlock;
        $nullBlock->parents[] = $block;
        $fetchBlock->parents[] = $block;

        $nullsafeOp = new OpCode(
            OpCode::TYPE_NULLSAFE,
            $resultSlot,
            $receiverSlot
        );
        $nullsafeOp->block1 = $nullBlock;
        $nullsafeOp->block2 = $fetchBlock;
        $nullsafeOp->block3 = $endBlock;
        $block->addOpCode($nullsafeOp);

        $this->nullsafeResultSlots[spl_object_id($expr)] = $resultSlot;
        $this->nullsafeMergeBlocks[spl_object_id($expr)] = $endBlock;

        return $endBlock;
    }

    /**
     * @param list<Op\Expr\NullsafePropertyFetch> $chain
     */
    protected function compileNullsafePropertyFetchChainEval(
        array $chain,
        Block $block,
        bool $allowUninitNullableShortCircuit
    ): Block {
        foreach ($chain as $fetch) {
            $block = $this->compileNullsafePropertyFetch($fetch, $block, $allowUninitNullableShortCircuit);
        }

        return $block;
    }

    /**
     * Bind a ?-> receiver without reading typed slots (#5220, $a->b?->v).
     *
     * php-cfg Temporary.original is often cleared by type reconstruction; when the preceding
     * PropertyFetch was skipped (#16637), recover it from the CFG block (#19591).
     */
    private function compileNullsafeReceiverSlot(
        ?Operand $var,
        Block $block,
        bool $allowUninitNullableShortCircuit = false
    ): int {
        if (null === $var) {
            throw new \LogicException('Nullsafe property fetch requires a receiver operand');
        }
        $propFetch = $this->unwrapPropertyFetch($var);
        if (null === $propFetch) {
            $propFetch = $this->findCoalescePropertyFetch($var, $block);
        }
        if (null !== $propFetch) {
            $receiverSlot = $this->compileOperand($propFetch->result, $block, false);
            $receiverFetch = new OpCode(
                OpCode::TYPE_PROPERTY_FETCH,
                $receiverSlot,
                $this->compileOperand($propFetch->var, $block, true),
                $this->compileOperand($propFetch->name, $block, true)
            );
            if ($allowUninitNullableShortCircuit) {
                $receiverFetch->nullsafeFetchPropertyRead = true;
                $receiverFetch->nullsafeUninitNullableToNull = true;
            }
            $block->addOpCode($receiverFetch);

            return $receiverSlot;
        }

        return $this->compileOperand($var, $block, true);
    }

    /**
     * @param list<Op\Expr\NullsafePropertyFetch> $chain
     */
    protected function compileIssetNullsafePropertyFetchChain(
        array $chain,
        Op\Expr\Isset_ $isset,
        Block $block
    ): Block {
        $resultSlot = $this->compileOperand($isset->result, $block, false);
        $endBlock = new Block($block->orig);
        $endBlock->inheritUndefinedLocals = true;
        $endBlock->inheritScopeFrom($block);
        $this->compileIssetNullsafeChainLink($chain, 0, $block, $resultSlot, $endBlock);

        return $endBlock;
    }

    /**
     * @param list<Op\Expr\NullsafePropertyFetch> $chain
     */
    protected function compileEmptyNullsafePropertyFetchChain(
        array $chain,
        Op\Expr\Empty_ $empty,
        Block $block
    ): Block {
        $resultSlot = $this->compileOperand($empty->result, $block, false);
        $endBlock = new Block($block->orig);
        $endBlock->inheritUndefinedLocals = true;
        $endBlock->inheritScopeFrom($block);
        $this->compileEmptyNullsafeChainLink($chain, 0, $block, $resultSlot, $endBlock);

        return $endBlock;
    }

    /**
     * @param list<Op\Expr\NullsafePropertyFetch> $chain
     */
    protected function compileIssetNullsafeChainLink(
        array $chain,
        int $index,
        Block $block,
        int $resultSlot,
        Block $endBlock
    ): void {
        $fetch = $chain[$index];
        $isLast = $index === count($chain) - 1;
        $receiverSlot = $this->compileNullsafeReceiverSlot($fetch->var, $block, true);

        $nullBlock = new Block($block->orig);
        $nullBlock->inheritUndefinedLocals = true;
        $nullBlock->inheritScopeFrom($block);
        $falseSlot = $this->compileBoolConstant($nullBlock, false);
        $nullBlock->addOpCode(new OpCode(
            OpCode::TYPE_ASSIGN,
            $resultSlot,
            $resultSlot,
            $falseSlot
        ));
        $nullJump = new OpCode(OpCode::TYPE_JUMP);
        $nullJump->block1 = $endBlock;
        $nullBlock->addOpCode($nullJump);

        $fetchBlock = new Block($block->orig);
        $fetchBlock->inheritUndefinedLocals = true;
        $fetchBlock->inheritScopeFrom($block);
        if ($isLast) {
            $fetchBlock->addOpCode($this->makeIssetOpCode(
                $resultSlot,
                $this->compileOperand($fetch->var, $fetchBlock, true),
                $this->compileOperand($fetch->name, $fetchBlock, true),
                true
            ));
            $fetchJump = new OpCode(OpCode::TYPE_JUMP);
            $fetchJump->block1 = $endBlock;
            $fetchBlock->addOpCode($fetchJump);
        } else {
            $intermediateSlot = $this->compileOperand($fetch->result, $fetchBlock, false);
            $propFetch = new OpCode(
                OpCode::TYPE_PROPERTY_FETCH,
                $intermediateSlot,
                $this->compileOperand($fetch->var, $fetchBlock, true),
                $this->compileOperand($fetch->name, $fetchBlock, true)
            );
            $propFetch->nullsafeFetchPropertyRead = true;
            $propFetch->nullsafeUninitNullableToNull = true;
            $fetchBlock->addOpCode($propFetch);
            $this->compileIssetNullsafeChainLink($chain, $index + 1, $fetchBlock, $resultSlot, $endBlock);
        }

        $endBlock->parents[] = $nullBlock;
        $endBlock->parents[] = $fetchBlock;

        $nullsafeOp = new OpCode(
            OpCode::TYPE_NULLSAFE,
            $isLast ? $resultSlot : $this->compileOperand($fetch->result, $block, false),
            $receiverSlot
        );
        $nullsafeOp->block1 = $nullBlock;
        $nullsafeOp->block2 = $fetchBlock;
        $nullsafeOp->block3 = $endBlock;
        $block->addOpCode($nullsafeOp);
    }

    /**
     * @param list<Op\Expr\NullsafePropertyFetch> $chain
     */
    protected function compileEmptyNullsafeChainLink(
        array $chain,
        int $index,
        Block $block,
        int $resultSlot,
        Block $endBlock
    ): void {
        $fetch = $chain[$index];
        $isLast = $index === count($chain) - 1;
        $receiverSlot = $this->compileNullsafeReceiverSlot($fetch->var, $block, true);

        $nullBlock = new Block($block->orig);
        $nullBlock->inheritUndefinedLocals = true;
        $nullBlock->inheritScopeFrom($block);
        $trueSlot = $this->compileBoolConstant($nullBlock, true);
        $nullBlock->addOpCode(new OpCode(
            OpCode::TYPE_ASSIGN,
            $resultSlot,
            $resultSlot,
            $trueSlot
        ));
        $nullJump = new OpCode(OpCode::TYPE_JUMP);
        $nullJump->block1 = $endBlock;
        $nullBlock->addOpCode($nullJump);

        $fetchBlock = new Block($block->orig);
        $fetchBlock->inheritUndefinedLocals = true;
        $fetchBlock->inheritScopeFrom($block);
        if ($isLast) {
            $fetchBlock->addOpCode(new OpCode(
                OpCode::TYPE_EMPTY_OBJECT_PROPERTY,
                $resultSlot,
                $this->compileOperand($fetch->var, $fetchBlock, true),
                $this->compileOperand($fetch->name, $fetchBlock, true),
            ));
            $fetchJump = new OpCode(OpCode::TYPE_JUMP);
            $fetchJump->block1 = $endBlock;
            $fetchBlock->addOpCode($fetchJump);
        } else {
            $intermediateSlot = $this->compileOperand($fetch->result, $fetchBlock, false);
            $propFetch = new OpCode(
                OpCode::TYPE_PROPERTY_FETCH,
                $intermediateSlot,
                $this->compileOperand($fetch->var, $fetchBlock, true),
                $this->compileOperand($fetch->name, $fetchBlock, true)
            );
            $propFetch->nullsafeFetchPropertyRead = true;
            $propFetch->nullsafeUninitNullableToNull = true;
            $fetchBlock->addOpCode($propFetch);
            $this->compileEmptyNullsafeChainLink($chain, $index + 1, $fetchBlock, $resultSlot, $endBlock);
        }

        $endBlock->parents[] = $nullBlock;
        $endBlock->parents[] = $fetchBlock;

        $nullsafeOp = new OpCode(
            OpCode::TYPE_NULLSAFE,
            $isLast ? $resultSlot : $this->compileOperand($fetch->result, $block, false),
            $receiverSlot
        );
        $nullsafeOp->block1 = $nullBlock;
        $nullsafeOp->block2 = $fetchBlock;
        $nullsafeOp->block3 = $endBlock;
        $block->addOpCode($nullsafeOp);
    }

    /**
     * @param list<Op> $deferredPreludeOps
     */
    protected function compileNullsafeMethodCall(
        Op\Expr\NullsafeMethodCall $expr,
        Block $block,
        array $deferredPreludeOps = []
    ): Block
    {
        $resultSlot = $this->compileOperand($expr->result, $block, false);
        // Same receiver binding as nullsafe property — Temporary.original is often null (#19591).
        $receiverSlot = $this->compileNullsafeReceiverSlot($expr->var, $block, false);

        $endBlock = new Block($block->orig);
        $endBlock->inheritUndefinedLocals = true;
        $endBlock->inheritScopeFrom($block);

        $nullBlock = new Block($block->orig);
        $nullBlock->inheritUndefinedLocals = true;
        $nullBlock->inheritScopeFrom($block);
        $nullLiteral = new Operand\Literal(null);
        $nullLiteral->type = Type::null();
        $nullValueSlot = $this->compileOperand($nullLiteral, $nullBlock, true);
        $nullBlock->addOpCode(new OpCode(
            OpCode::TYPE_ASSIGN,
            $resultSlot,
            $resultSlot,
            $nullValueSlot
        ));
        $nullJump = new OpCode(OpCode::TYPE_JUMP);
        $nullJump->block1 = $endBlock;
        $nullBlock->addOpCode($nullJump);

        $fetchBlock = new Block($block->orig);
        $fetchBlock->inheritUndefinedLocals = true;
        $fetchBlock->inheritScopeFrom($block);
        if (!empty($deferredPreludeOps)) {
            // parseArg clones leave producer->result usages empty and NullsafeMethodCall is
            // not in fetchBlock->orig, so bare compileOps would emit EXEC_NORETURN and
            // ARG_SEND would allocate a fresh empty slot for the clone (#22660 / #8560).
            foreach ($expr->args as $arg) {
                if (!$arg instanceof Operand\Temporary) {
                    continue;
                }
                foreach ($deferredPreludeOps as $preludeOp) {
                    if (
                        !$preludeOp instanceof Op\Expr
                        || null === $preludeOp->result
                        || !$this->nullsafeCallArgTempFedByProducer($arg, $preludeOp)
                    ) {
                        continue;
                    }
                    $sharedSlot = $fetchBlock->getVarSlot($preludeOp->result, false);
                    $fetchBlock->bindOperandScopeSlot($arg, $sharedSlot);
                    break;
                }
            }
            $prevForceReturn = $this->forceDeferredSiblingCallReturnSlot;
            $this->forceDeferredSiblingCallReturnSlot = true;
            try {
                $this->compileOps($deferredPreludeOps, $fetchBlock);
            } finally {
                $this->forceDeferredSiblingCallReturnSlot = $prevForceReturn;
            }
        }
        $fetchBlock->addOpCode(new OpCode(
            OpCode::TYPE_METHODCALL_INIT,
            $receiverSlot,
            $this->compileOperand($expr->name, $fetchBlock, true)
        ));
        foreach ($this->compileCallArgSends($expr->args, $fetchBlock, null, $expr) as $send) {
            $fetchBlock->addOpCode($send);
        }
        $fetchBlock->addOpCode($this->compileFuncCallExecOpcode(
            $expr->result,
            $fetchBlock,
            max(0, $expr->getLine())
        ));
        $fetchJump = new OpCode(OpCode::TYPE_JUMP);
        $fetchJump->block1 = $endBlock;
        $fetchBlock->addOpCode($fetchJump);
        $endBlock->parents[] = $nullBlock;
        $endBlock->parents[] = $fetchBlock;
        $nullBlock->parents[] = $block;
        $fetchBlock->parents[] = $block;

        $nullsafeOp = new OpCode(
            OpCode::TYPE_NULLSAFE,
            $resultSlot,
            $receiverSlot
        );
        $nullsafeOp->nullsafeMethodCall = true;
        $nullsafeOp->block1 = $nullBlock;
        $nullsafeOp->block2 = $fetchBlock;
        $nullsafeOp->block3 = $endBlock;
        $block->addOpCode($nullsafeOp);

        $this->nullsafeResultSlots[spl_object_id($expr)] = $resultSlot;
        $this->nullsafeMergeBlocks[spl_object_id($expr)] = $endBlock;

        return $endBlock;
    }

    /**
     * @return list<\PHPCfg\Operand>
     */
    private function nullsafePreludeOperandVars(Op\Expr $expr): array
    {
        // Minimal dependency extraction for nullsafe argument prelude sinking (#4394).
        // Extend carefully; keep conservative (only single-use temporaries are eligible).
        return match (get_class($expr)) {
            Op\Expr\FuncCall::class => array_merge([$expr->name], $expr->args),
            Op\Expr\Closure::class => [],
            default => [],
        };
    }

    /**
     * True when a nullsafe call-arg temporary is the producer result or a parseArg clone
     * whose ops still reference that producer (#8560, #22660).
     */
    private function nullsafeCallArgTempFedByProducer(Operand $argTemp, Op\Expr $producer): bool
    {
        if ($argTemp === $producer->result || $this->operandsReferToSameVariable($argTemp, $producer->result)) {
            return true;
        }
        if (!$argTemp instanceof Operand\Temporary) {
            return false;
        }
        foreach ($argTemp->ops ?? [] as $embedded) {
            if ($embedded === $producer) {
                return true;
            }
        }

        return false;
    }

    private function isNullsafeMethodCallArgPreludeProducer(Op\Expr $expr): bool
    {
        return $expr instanceof Op\Expr\FuncCall
            || $expr instanceof Op\Expr\NsFuncCall
            || $expr instanceof Op\Expr\Closure
            || $expr instanceof Op\Expr\New_
            || $expr instanceof Op\Expr\MethodCall
            || $expr instanceof Op\Expr\StaticCall;
    }

    protected function functionStaticStorageKey(\PHPCfg\Func $func, string $varName): string
    {
        if (((int) ($func->flags ?? 0)) & \PHPCfg\Func::FLAG_CLOSURE) {
            return $varName;
        }

        return $this->resolveFuncDisplayName($func)."\0".$varName;
    }

    protected function resolveFuncDisplayName(\PHPCfg\Func $func): string
    {
        $name = $func->name;
        if ($name instanceof Operand\Literal && is_string($name->value)) {
            $name = $name->value;
        }
        if (!is_string($name)) {
            $this->throwCompileLogic('Function name must be a string literal for static storage key (#2286)');
        }
        $class = $func->class;
        if ($class instanceof Operand\Literal && is_string($class->value)) {
            $class = $class->value;
        }
        if (null !== $class && !is_string($class)) {
            $this->throwCompileLogic('Function class must be a string literal for static storage key (#2286)');
        }

        return null !== $class ? $class.'::'.$name : $name;
    }

    /**
     * @param Op\Terminal\StaticVar $terminal
     *
     * @return array{0: list<OpCode>, 1: Block}
     */
    protected function compileFunctionStaticVar(Op\Terminal $terminal, Block $block): array
    {
        if (null === $block->func) {
            $this->throwCompileLogic('Function-local static requires a function context');
        }
        $varName = $this->resolveSimpleVariableName($terminal->var);
        $storageKey = $this->functionStaticStorageKey($block->func, $varName);
        $keyVar = new Variable(Variable::TYPE_STRING);
        $keyVar->string($storageKey);
        $keyOperand = new Operand\Literal($storageKey);
        $keyOperand->type = Type::string();
        $keySlot = $block->registerConstant($keyOperand, $keyVar);
        $localSlot = $this->compileOperand($terminal->var, $block, false);
        $declaredType = $this->staticVarDeclaredType($terminal);
        $typeSlot = null;
        if (null !== $declaredType) {
            $declType = $this->typeFromStaticVarDecl($terminal, $declaredType);
            $typeSlot = $this->compileTypeConstrainedVariable($block, $declType, $declaredType);
        }

        if (null === $terminal->defaultVar) {
            return [[$this->makeDeclareFunctionStaticOp(
                $localSlot,
                $keySlot,
                null,
                $typeSlot,
                $varName
            )], $block];
        }

        $defaultSlot = $this->tryFoldFunctionStaticDefaultSlot($terminal, $block);
        if (null !== $defaultSlot) {
            $defaultVm = $block->constants[$defaultSlot];
            if (!$this->isAllowedFunctionStaticDefaultType($defaultVm->type)) {
                $this->throwCompileLogic(
                    'Function-local static initializer must be a compile-time literal in v1 (#2286)'
                );
            }
            if (null !== $declaredType) {
                $this->assertCompileTimeDefaultMatchesDeclaredType(
                    $defaultVm,
                    $declaredType,
                    'static variable',
                    '$'.$varName,
                    $block,
                    $defaultSlot
                );
            }

            return [[$this->makeDeclareFunctionStaticOp(
                $localSlot,
                $keySlot,
                $defaultSlot,
                $typeSlot,
                $varName
            )], $block];
        }

        $this->assertFunctionStaticRuntimeInitAllowed($terminal);

        $continueBlock = new Block($block->orig);
        $continueBlock->func = $block->func;
        $continueBlock->inheritScopeFrom($block);

        // JUMPIF must precede New_/Array_ rematerialization. Compiling the defaultBlock first
        // left TYPE_NEW ahead of the initialized check, so every call allocated a discarded object
        // (#28040 companion — wastes work; frame-teardown refcount fix is in VM.php).
        $skipOp = new OpCode(
            OpCode::TYPE_JUMPIF_FUNCTION_STATIC_INITIALIZED,
            null,
            $keySlot
        );
        $skipOp->block1 = $continueBlock;
        $block->addOpCode($skipOp);

        if (null !== $terminal->defaultBlock) {
            // php-cfg places Array_/New_ in defaultBlock, not the function body. Rematerialize
            // so TYPE_ARG_SEND wires the INIT_ARRAY slot (not a dead mixed temp) (#22390, #8561).
            $this->compileDefaultBlockChildrenWithProducerCfg($terminal->defaultBlock, $block);
        }
        $initSlot = $this->compileOperand($terminal->defaultVar, $block, true);

        $storeOp = new OpCode(
            OpCode::TYPE_FUNCTION_STATIC_INIT_STORE,
            null,
            $keySlot,
            $initSlot
        );
        $storeOp->functionStaticTypeSlot = $typeSlot;
        $storeOp->functionStaticVarName = $varName;
        $jumpOp = new OpCode(OpCode::TYPE_JUMP);
        $jumpOp->block1 = $continueBlock;

        $continueBlock->addOpCode($this->makeDeclareFunctionStaticOp(
            $localSlot,
            $keySlot,
            null,
            $typeSlot,
            $varName
        ));
        $continueBlock->parents[] = $block;

        return [[$storeOp, $jumpOp], $continueBlock];
    }

    protected function staticVarDeclaredType(Op\Terminal\StaticVar $terminal): ?Op\Type
    {
        if (!property_exists($terminal, 'declaredType')) {
            return null;
        }

        return $terminal->declaredType;
    }

    protected function typeFromStaticVarDecl(Op\Terminal\StaticVar $terminal, ?Op\Type $declaredType = null): Type
    {
        $declaredType ??= $this->staticVarDeclaredType($terminal);
        if (null === $declaredType) {
            return Type::mixed();
        }
        if ($declaredType instanceof Op\Type\Literal) {
            return Type::fromDecl($declaredType->name);
        }

        return Type::fromTypeDecl($declaredType);
    }

    protected function makeDeclareFunctionStaticOp(
        int $localSlot,
        int $keySlot,
        ?int $defaultSlot,
        ?int $typeSlot,
        string $varName
    ): OpCode {
        $op = new OpCode(
            OpCode::TYPE_DECLARE_FUNCTION_STATIC,
            $localSlot,
            $keySlot,
            $defaultSlot
        );
        $op->functionStaticTypeSlot = $typeSlot;
        $op->functionStaticVarName = $varName;

        return $op;
    }

    /**
     * Reject non-constant function-static initializers on PHP &lt; 8.3 (#22923, #4352, #5478).
     *
     * php-cfg often places a bare `$param` on {@see Op\Terminal\StaticVar::$defaultVar} with an
     * empty {@see $defaultBlock}; walking children alone missed that shape and accepted it as a
     * runtime init (undefined-constant → string) on the 8.2 reference profile.
     *
     * @param Op\Terminal\StaticVar $terminal
     */
    protected function assertFunctionStaticRuntimeInitAllowed(Op\Terminal $terminal): void
    {
        // PHP 8.3+ RFC: arbitrary static variable initializers (Zend/zend_compile.c).
        if (CompilerVersion::supportsArbitraryStaticVariableInitializers()) {
            return;
        }
        if (
            null !== $terminal->defaultVar
            && $this->functionStaticInitOperandReferencesLocal($terminal->defaultVar)
        ) {
            $this->throwCompileLogic(
                'Constant expression contains invalid operations'
            );
        }
        if (null === $terminal->defaultBlock) {
            return;
        }
        foreach ($terminal->defaultBlock->children as $child) {
            if ($this->functionStaticInitReferencesLocal($child)) {
                $this->throwCompileLogic(
                    'Constant expression contains invalid operations'
                );
            }
        }
    }

    protected function functionStaticInitReferencesLocal(Op $op): bool
    {
        if ($op instanceof Op\Expr\Closure || $op instanceof Op\Expr\ArrowFunction) {
            return true;
        }
        if ($op instanceof Op\Expr\FuncCall || $op instanceof Op\Expr\MethodCall) {
            return true;
        }
        if ($op instanceof Op\Expr\Variable) {
            return true;
        }
        if ($op instanceof Op\Expr\ArrayDimFetch) {
            return $this->functionStaticInitExprOrOperandReferencesLocal($op->var)
                || (null !== $op->dim && $this->functionStaticInitOperandReferencesLocal($op->dim));
        }
        if ($op instanceof Op\Expr\PropertyFetch) {
            return $this->functionStaticInitExprOrOperandReferencesLocal($op->var)
                || $this->functionStaticInitOperandReferencesLocal($op->name);
        }
        if ($op instanceof Op\Expr\BinaryOp) {
            return $this->functionStaticInitOperandReferencesLocal($op->left)
                || $this->functionStaticInitOperandReferencesLocal($op->right);
        }
        if ($op instanceof Op\Expr\UnaryMinus || $op instanceof Op\Expr\UnaryPlus || $op instanceof Op\Expr\UnaryOp\BitwiseNot) {
            return $this->functionStaticInitOperandReferencesLocal($op->expr);
        }
        if ($op instanceof Op\Expr\New_) {
            foreach ($op->args as $arg) {
                if ($this->functionStaticInitOperandReferencesLocal($arg)) {
                    return true;
                }
            }

            return false;
        }
        if ($op instanceof Op\Expr\Array_) {
            $n = \count($op->values);
            for ($i = 0; $i < $n; ++$i) {
                if ($this->functionStaticInitOperandReferencesLocal($op->values[$i])) {
                    return true;
                }
                $key = $op->keys[$i] ?? null;
                if (null !== $key && $this->functionStaticInitOperandReferencesLocal($key)) {
                    return true;
                }
            }

            return false;
        }
        if ($op instanceof Op\Expr\ConstFetch || $op instanceof Op\Expr\ClassConstFetch) {
            return false;
        }

        return false;
    }

    protected function functionStaticInitExprOrOperandReferencesLocal(Op|Operand $node): bool
    {
        if ($node instanceof Op) {
            return $this->functionStaticInitReferencesLocal($node);
        }

        return $this->functionStaticInitOperandReferencesLocal($node);
    }

    protected function functionStaticInitOperandReferencesLocal(Operand $operand): bool
    {
        if ($operand instanceof Operand\Variable) {
            return true;
        }
        if ($operand instanceof Operand\Literal || $operand instanceof Operand\NullOperand) {
            return false;
        }
        if ($operand instanceof Operand\Temporary) {
            return false;
        }

        return false;
    }

    private function isAllowedFunctionStaticDefaultType(int $type): bool
    {
        return \in_array(
            $type,
            [
                Variable::TYPE_INTEGER,
                Variable::TYPE_STRING,
                Variable::TYPE_ARRAY,
                Variable::TYPE_BOOLEAN,
                Variable::TYPE_FLOAT,
                Variable::TYPE_NULL,
                Variable::TYPE_ENUM_CASE,
                Variable::TYPE_OBJECT,
            ],
            true
        );
    }

    /**
     * @param Op\Terminal\StaticVar $terminal
     */
    protected function tryFoldFunctionStaticDefaultSlot(Op\Terminal $terminal, Block $block): ?int
    {
        if (null === $terminal->defaultVar) {
            return null;
        }
        // Operand\Variable must not fold via unwrapCfgLiteralOperand (name → string "x") —
        // that mis-accepted `static $a = $param` as compile-time string on 8.2 (#22923).
        if ($this->functionStaticInitOperandReferencesLocal($terminal->defaultVar)) {
            return null;
        }
        // Share param-default folding (scalar/array literals, const fetch, unary, …) — Zend
        // zend_compile_static_variables() binds literals at compile time (#2286, #9351).
        $pseudo = new Op\Expr\Param(
            new Operand\Literal(''),
            new Op\Type\Mixed_(),
            false,
            false,
            $terminal->defaultVar,
            $terminal->defaultBlock
        );

        return $this->tryFoldParamDefaultSlot($pseudo, $block);
    }

    protected function tryBuildCompileTimeArrayFromExpr(
        Op\Expr\Array_ $expr,
        ?Block $block = null,
        array $defaultBlockChildren = [],
        bool $materializeEnumCase = false
    ): ?Variable
    {
        $unpackFlags = property_exists($expr, 'unpack') ? $expr->unpack : [];
        $byRefFlags = property_exists($expr, 'byRef') ? $expr->byRef : [];
        foreach ($byRefFlags as $refFlag) {
            if (!empty($refFlag)) {
                return null;
            }
        }
        $ht = new HashTable();
        $n = \count($expr->values);
        for ($i = 0; $i < $n; ++$i) {
            if (!empty($unpackFlags[$i])) {
                $spreadVm = $this->compileTimeVariableFromCfgArrayElement(
                    $expr->values[$i],
                    $block,
                    $defaultBlockChildren,
                    $materializeEnumCase
                );
                if (null === $spreadVm || !$spreadVm->is(Variable::TYPE_ARRAY)) {
                    return null;
                }
                $ht->spreadFrom($spreadVm->toArray());

                continue;
            }
            $valueVm = $this->compileTimeVariableFromCfgArrayElement(
                $expr->values[$i],
                $block,
                $defaultBlockChildren,
                $materializeEnumCase
            );
            if (null === $valueVm) {
                return null;
            }
            $keyOp = $expr->keys[$i] ?? null;
            if (null === $keyOp) {
                $ht->append($valueVm);
                continue;
            }
            if ($keyOp instanceof Operand\NullOperand) {
                $ht->append($valueVm);
                continue;
            }
            if ($keyOp instanceof Operand\Literal && null === $keyOp->value) {
                $ht->update('', $valueVm);
                continue;
            }
            $keyVm = $this->vmVariableFromCfgLiteralOperand($keyOp);
            if (null === $keyVm && null !== $block && [] !== $defaultBlockChildren) {
                $keyVm = $this->tryFoldCompileTimeOperandDefault(
                    $keyOp,
                    $block,
                    $defaultBlockChildren,
                    $materializeEnumCase
                );
            }
            if (null === $keyVm) {
                return null;
            }
            if ($keyVm->is(Variable::TYPE_INTEGER) || $keyVm->is(Variable::TYPE_FLOAT)) {
                $ht->updateIndex($keyVm->toInt(), $valueVm);
            } elseif ($keyVm->is(Variable::TYPE_STRING)) {
                $ht->update($keyVm->toString(), $valueVm);
            } elseif ($keyVm->is(Variable::TYPE_BOOLEAN)) {
                $ht->updateIndex($keyVm->toBool() ? 1 : 0, $valueVm);
            } elseif ($keyVm->is(Variable::TYPE_NULL)) {
                $ht->update('', $valueVm);
            } else {
                return null;
            }
        }
        $vmArray = new Variable(Variable::TYPE_ARRAY);
        $vmArray->array($ht);

        return $vmArray;
    }

    protected function compileTimeVariableFromCfgArrayElement(
        Operand $operand,
        ?Block $block = null,
        array $defaultBlockChildren = [],
        bool $materializeEnumCase = false
    ): ?Variable {
        $vm = $this->vmVariableFromCfgLiteralOperand($operand);
        if (null !== $vm) {
            return $vm;
        }
        if (null !== $block && [] !== $defaultBlockChildren) {
            $vm = $this->tryFoldCompileTimeOperandDefault(
                $operand,
                $block,
                $defaultBlockChildren,
                $materializeEnumCase
            );
            if (null !== $vm) {
                return $vm;
            }
        }
        $nested = $this->unwrapCfgArrayExprOperand($operand);
        if (null !== $nested) {
            return $this->tryBuildCompileTimeArrayFromExpr(
                $nested,
                $block,
                $defaultBlockChildren,
                $materializeEnumCase
            );
        }

        return null;
    }

    protected function unwrapCfgArrayExprOperand(Operand $operand): ?Op\Expr\Array_
    {
        while ($operand instanceof Operand\Temporary && null !== $operand->original) {
            $operand = $operand->original;
        }

        return $operand instanceof Op\Expr\Array_ ? $operand : null;
    }

    protected function vmVariableFromCfgLiteralOperand(Operand $operand): ?Variable
    {
        // Named CVs / BoundVariable($this) unwrap to Literal(name) via unwrapCfgLiteralOperand —
        // that is the variable *name*, not a compile-time value. Folding it registers string
        // constants on the CV slot (e.g. const "this" on $this) so call-arg reads see a string
        // instead of the object (#28049, #28038, #22923).
        if (null !== Block::resolveVariableName($operand)) {
            return null;
        }
        $literal = $this->unwrapCfgLiteralOperand($operand);
        if (null === $literal) {
            return null;
        }
        $mappedType = Variable::mapFromType($literal->type ?? Type::mixed());
        if (Variable::TYPE_UNDEFINED === $mappedType) {
            if (\is_int($literal->value)) {
                $mappedType = Variable::TYPE_INTEGER;
            } elseif (\is_float($literal->value)) {
                $mappedType = Variable::TYPE_FLOAT;
            } elseif (\is_string($literal->value)) {
                $mappedType = Variable::TYPE_STRING;
            } elseif (\is_bool($literal->value)) {
                $mappedType = Variable::TYPE_BOOLEAN;
            } elseif (null === $literal->value) {
                $mappedType = Variable::TYPE_NULL;
            }
        }
        $return = new Variable($mappedType);
        switch ($mappedType) {
            case Variable::TYPE_STRING:
                $return->string($literal->value, true);
                break;
            case Variable::TYPE_INTEGER:
                $return->int($literal->value);
                break;
            case Variable::TYPE_FLOAT:
                $return->float($literal->value);
                break;
            case Variable::TYPE_BOOLEAN:
                $return->bool($literal->value);
                break;
            case Variable::TYPE_NULL:
                break;
            default:
                return null;
        }

        return $return;
    }

    protected function unwrapCfgLiteralOperand(Operand $operand): ?Operand\Literal
    {
        while ($operand instanceof Operand\Temporary && null !== $operand->original) {
            $operand = $operand->original;
        }
        while ($operand instanceof Operand\Variable) {
            $operand = $operand->name;
            while ($operand instanceof Operand\Temporary && null !== $operand->original) {
                $operand = $operand->original;
            }
        }

        return $operand instanceof Operand\Literal ? $operand : null;
    }

    /**
     * Scope slot for the local alias created by `global $name` (#3413).
     *
     * php-cfg may pass writeVariable(Literal('x')) rather than a Variable operand.
     */
    protected function compileGlobalImportSlot(Operand $var, string $globalName, Block $block): int
    {
        if ($var instanceof Operand\Variable) {
            return $block->getVarSlot($var, false);
        }
        $nameLiteral = new Operand\Literal($globalName);
        $nameLiteral->type = Type::string();
        $local = new Operand\Variable($nameLiteral);

        return $block->getVarSlot($local, false);
    }

    protected function resolveSimpleVariableName(Operand $var): string
    {
        while ($var instanceof Temporary) {
            if (null === $var->original) {
                break;
            }
            $var = $var->original;
        }
        if ($var instanceof Operand\Literal && is_string($var->value)) {
            return $var->value;
        }
        if (!$var instanceof Operand\Variable) {
            $this->throwCompileLogic('Expected a simple variable operand');
        }
        $name = $var->name;
        while ($name instanceof Temporary) {
            if (null === $name->original) {
                break;
            }
            $name = $name->original;
        }
        if ($name instanceof Operand\Literal && is_string($name->value)) {
            return $name->value;
        }

        $this->throwCompileLogic('Expected a simple variable name');
    }

    /**
     * @return ?array{0: int, 1: ?int}
     */
    protected function resolveCoalesceIssetTarget(Operand $operand, Block $block): ?array
    {
        $fetch = $this->findCoalesceArrayDimFetch($operand, $block);
        if (null !== $fetch) {
            return $this->resolveIssetTargetFromArrayDimFetch($fetch, $block);
        }
        $propFetch = $this->findCoalescePropertyFetch($operand, $block);
        if (null !== $propFetch) {
            return $this->resolveIssetTargetFromPropertyFetch($propFetch, $block);
        }
        $staticPropFetch = $this->findCoalesceStaticPropertyFetch($operand, $block);
        if (null !== $staticPropFetch) {
            return $this->resolveIssetTargetFromStaticPropertyFetch($staticPropFetch, $block);
        }
        if (null !== $this->unwrapVariableOperand($operand)) {
            return $this->resolveIssetTarget($operand, $block);
        }

        return null;
    }

    /**
     * @return ?Op\Expr\ArrayDimFetch
     */
    /**
     * php-cfg emits PropertyFetch before Empty_; recover operand when Empty_.expr is cleared (#4701, #6829).
     */
    private function recoverEmptyExprOperand(Op\Expr\Empty_ $expr, Block $block): ?Operand
    {
        if (null !== $expr->expr) {
            return $expr->expr;
        }
        foreach ($block->orig->children as $child) {
            if ($child instanceof Op\Expr\PropertyFetch && $this->isPropertyFetchOnlyEmptyVar($child, $expr, $block)) {
                return $child->result;
            }
            if ($child instanceof Op\Expr\StaticPropertyFetch && $this->isStaticPropertyFetchOnlyEmptyVar($child, $expr, $block)) {
                return $child->result;
            }
            if ($child instanceof Op\Expr\ArrayDimFetch && $this->isArrayDimFetchOnlyEmptyVar($child, $expr, $block)) {
                return $child->result;
            }
        }
        $funcCallFetch = $this->recoverEmptyPropertyFetchForFuncCallArg($expr, $block);
        if (null !== $funcCallFetch) {
            return $funcCallFetch;
        }

        return null;
    }

    /**
     * PropertyFetch hoisted before FuncCall(empty($obj->prop)) when php-cfg omits Empty_ stmt (#8901).
     */
    private function recoverEmptyPropertyFetchForFuncCallArg(Op\Expr\Empty_ $expr, Block $block): ?Operand
    {
        if (null === $block->orig) {
            return null;
        }
        $children = $block->orig->children;
        foreach ($children as $i => $child) {
            if (!$this->isInlineExprCallArgConsumer($child) || !$this->funcCallArgReferencesEmpty($child, $expr)) {
                continue;
            }
            for ($j = $i - 1; $j >= 0; --$j) {
                $prev = $children[$j];
                if ($prev instanceof Op\Expr\PropertyFetch && $this->emptyExprDependsOnOperand($expr, $prev->result, $block)) {
                    return $prev->result;
                }
                if ($prev === $expr) {
                    continue;
                }
                if ($prev instanceof Op\Expr && $this->isInlineExprCallArgProducer($prev)) {
                    continue;
                }
                break;
            }
        }

        return null;
    }

    private function funcCallArgReferencesEmpty(Op $call, Op\Expr\Empty_ $empty): bool
    {
        if (!property_exists($call, 'args') || !is_array($call->args)) {
            return false;
        }
        foreach ($call->args as $arg) {
            if ($arg instanceof Operand\Temporary && $arg->original === $empty) {
                return true;
            }
            if ($this->operandsReferToSameVariable($arg, $empty->result)) {
                return true;
            }
        }

        return false;
    }

    private function emptyExprDependsOnOperand(Op\Expr\Empty_ $expr, Operand $operand, Block $block): bool
    {
        $target = $this->unaryExprOperandForRead($expr, $block) ?? $expr->expr;
        if (null === $target) {
            return false;
        }
        if ($target === $operand) {
            return true;
        }

        return $this->operandsReferToSameVariable($target, $operand);
    }

    /**
     * @return ?Op\Expr\Empty_
     */
    private function findEmptyExprForCallArg(Operand $arg, Block $block): ?Op\Expr\Empty_
    {
        $empty = $this->unwrapEmptyExpr($arg);
        if (null !== $empty) {
            return $empty;
        }
        if (null === $block->orig) {
            return null;
        }
        foreach ($block->orig->children as $child) {
            if ($child instanceof Op\Expr\Empty_ && $this->operandsReferToSameVariable($child->result, $arg)) {
                return $child;
            }
        }
        $callSite = $this->findCfgCallSiteForArg($block->orig->children, $arg);
        if (null === $callSite) {
            return null;
        }
        [$callOp, $argIndex] = $callSite;
        if (!property_exists($callOp, 'args') || !is_array($callOp->args)) {
            return null;
        }
        $callArg = $callOp->args[$argIndex] ?? null;
        if (null === $callArg) {
            return null;
        }

        return $this->unwrapEmptyExpr($callArg);
    }

    /**
     * @return ?Op\Expr\Empty_
     */
    private function unwrapEmptyExpr(Operand $operand): ?Op\Expr\Empty_
    {
        if ($operand instanceof Op\Expr\Empty_) {
            return $operand;
        }
        if ($operand instanceof Operand\Temporary) {
            if ($operand->original instanceof Op\Expr\Empty_) {
                return $operand->original;
            }
            if (null !== $operand->original) {
                return $this->unwrapEmptyExpr($operand->original);
            }
        }

        return null;
    }

    /**
     * FuncCall(empty($obj->prop)) — compile hoisted Empty_ when php-cfg left the arg slot dead (#8901).
     */
    private function compileHoistedEmptyCallArg(Operand $arg, Block $block): ?int
    {
        $empty = $this->findEmptyExprForCallArg($arg, $block);
        if (null === $empty) {
            return null;
        }
        if (!$this->emptyExprLoweringEmitted($block, $empty)) {
            foreach ($this->compileExpr($empty, $block) as $op) {
                $block->addOpCode($op);
            }
        }

        return $this->compileOperand($empty->result, $block, true);
    }

    /**
     * php-cfg dead call-arg temps for hoisted isset()/empty() — map to producer result slot (#11498).
     *
     * Sibling isset()/empty() before another expression in the same array literal must not steal
     * that call's literal/CV args (#25188).
     */
    private function resolveHoistedIssetOrEmptyCallArgSlot(
        Operand $arg,
        Block $block,
        ?Op $cfgCallOp,
        int $argIndex
    ): ?int {
        if (null === $cfgCallOp || null === $block->orig) {
            return null;
        }
        $producer = $this->findHoistedIssetOrEmptyProducerForCallArg($block, $cfgCallOp, $argIndex);
        if (null === $producer) {
            return null;
        }
        $callArg = $cfgCallOp->args[$argIndex] ?? $arg;
        $argIsProducerResult = $this->operandsReferToSameVariable($producer->result, $callArg);
        $argIsDeadTemp = $this->callArgIsDeadInlineTemporary($callArg);
        if (!$argIsDeadTemp && !$argIsProducerResult) {
            // [isset($a['x']), array_key_exists('x', $a)] — preceding Isset_ is a sibling array
            // element, not this call's arg; keep LITERAL/CV wiring (#25188).
            return null;
        }
        if (
            $argIsDeadTemp
            && !$argIsProducerResult
            && !$this->issetOrEmptyProducerIsImmediateCallPrelude($producer, $cfgCallOp, $block)
        ) {
            // isset() && … as call arg — php-cfg dead temp is && merge, not hoisted Isset_ (#10704).
            return null;
        }
        if ($producer instanceof Op\Expr\Isset_ && 1 === count($producer->vars)) {
            $nullsafeChain = $this->collectNullsafePropertyFetchChain($producer->vars[0], $block);
            if ([] !== $nullsafeChain) {
                $existingSlot = $block->slotForOperand($producer->result);
                if (null !== $existingSlot) {
                    return $existingSlot;
                }
            }
        }
        if ($producer instanceof Op\Expr\Empty_) {
            $nullsafeChain = $this->collectNullsafePropertyFetchChainForEmpty($producer, $block);
            if ([] !== $nullsafeChain) {
                $existingSlot = $block->slotForOperand($producer->result);
                if (null !== $existingSlot) {
                    return $existingSlot;
                }
            }
        }
        if ($producer instanceof Op\Expr\Isset_ && !$this->issetExprLoweringEmitted($block, $producer)) {
            foreach ($this->compileExpr($producer, $block) as $op) {
                $block->addOpCode($op);
            }
        }
        if ($producer instanceof Op\Expr\Empty_ && !$this->emptyExprLoweringEmitted($block, $producer)) {
            foreach ($this->compileExpr($producer, $block) as $op) {
                $block->addOpCode($op);
            }
        }

        return $this->slotForEmittedIssetOrEmptyProducer($block, $producer)
            ?? $this->compileOperand($producer->result, $block, true);
    }

    /**
     * @return Op\Expr\Isset_|Op\Expr\Empty_|null
     */
    private function findHoistedIssetOrEmptyProducerForCallArg(
        Block $block,
        Op $cfgCallOp,
        int $argIndex
    ): ?Op\Expr {
        $callIndex = null;
        foreach ($block->orig->children as $i => $child) {
            if ($child === $cfgCallOp) {
                $callIndex = $i;
                break;
            }
        }
        if (null === $callIndex) {
            return null;
        }
        $producers = $this->precedingInlineCallArgProducersBeforeCfgOp($block->orig->children, $cfgCallOp);
        $callArgs = property_exists($cfgCallOp, 'args') && is_array($cfgCallOp->args) ? $cfgCallOp->args : [];
        if (\count($producers) === \count($callArgs) && isset($producers[$argIndex])) {
            $candidate = $producers[$argIndex];
            if ($candidate instanceof Op\Expr\Isset_ || $candidate instanceof Op\Expr\Empty_) {
                return $candidate;
            }
        }
        $matched = $this->matchInlineCallArgProducer($producers, $callArgs, $argIndex, $cfgCallOp);
        if ($matched instanceof Op\Expr\Isset_ || $matched instanceof Op\Expr\Empty_) {
            return $matched;
        }
        $hoisted = [];
        for ($i = $callIndex - 1; $i >= 0; --$i) {
            $child = $block->orig->children[$i];
            if ($child instanceof Op\Expr\Isset_ || $child instanceof Op\Expr\Empty_) {
                array_unshift($hoisted, $child);
                continue;
            }
            if ($child instanceof Op\Expr\ConstFetch) {
                continue;
            }
            break;
        }
        $producer = $hoisted[$argIndex] ?? null;

        return ($producer instanceof Op\Expr\Isset_ || $producer instanceof Op\Expr\Empty_) ? $producer : null;
    }

    /**
     * var_dump(isset(['a'=>1]['a'])) — php-cfg dead arg temp ≠ Isset_.result (#16462).
     */
    private function issetOrEmptyProducerIsImmediateCallPrelude(
        Op\Expr $producer,
        Op $cfgCallOp,
        Block $block
    ): bool {
        if (null === $block->orig) {
            return false;
        }
        $callIndex = null;
        foreach ($block->orig->children as $i => $child) {
            if ($child === $cfgCallOp) {
                $callIndex = $i;
                break;
            }
        }
        if (null === $callIndex || $callIndex < 1) {
            return false;
        }
        for ($i = $callIndex - 1; $i >= 0; --$i) {
            $child = $block->orig->children[$i];
            if ($child instanceof Op\Expr\Isset_ || $child instanceof Op\Expr\Empty_) {
                return $child === $producer;
            }
            if ($child instanceof Op\Expr\ArrayDimFetch) {
                continue;
            }
            if ($child instanceof Op\Expr\ConstFetch || $child instanceof Op\Expr\ClassConstFetch) {
                continue;
            }
            break;
        }

        return false;
    }

    /**
     * Recover lowered isset()/empty() result slots when php-cfg dead arg temps omit dataflow (#11498).
     */
    private function slotForEmittedIssetOrEmptyProducer(Block $block, Op\Expr $producer): ?int
    {
        $slot = $block->slotForOperand($producer->result);
        if (null !== $slot) {
            return $slot;
        }
        if ($producer instanceof Op\Expr\Isset_) {
            for ($i = \count($block->opCodes) - 1; $i >= 0; --$i) {
                $op = $block->opCodes[$i];
                if (OpCode::TYPE_ISSET === $op->type) {
                    return $op->arg1;
                }
            }
        }
        if ($producer instanceof Op\Expr\Empty_) {
            for ($i = \count($block->opCodes) - 1; $i >= 0; --$i) {
                $op = $block->opCodes[$i];
                if (OpCode::TYPE_EMPTY === $op->type
                    || OpCode::TYPE_EMPTY_OBJECT_PROPERTY === $op->type
                    || OpCode::TYPE_EMPTY_STATIC_PROPERTY === $op->type
                    || OpCode::TYPE_EMPTY_DIMENSION === $op->type) {
                    return $op->arg1;
                }
            }
        }

        return null;
    }

    private function emptyExprLoweringEmitted(Block $block, Op\Expr\Empty_ $empty): bool
    {
        $slot = $block->slotForOperand($empty->result);
        if (null === $slot) {
            return false;
        }
        foreach ($block->opCodes as $op) {
            if ($op->arg1 !== $slot) {
                continue;
            }
            if (OpCode::TYPE_EMPTY === $op->type
                || OpCode::TYPE_EMPTY_OBJECT_PROPERTY === $op->type
                || OpCode::TYPE_EMPTY_STATIC_PROPERTY === $op->type
                || OpCode::TYPE_EMPTY_DIMENSION === $op->type) {
                return true;
            }
        }

        return false;
    }

    private function issetExprLoweringEmitted(Block $block, Op\Expr\Isset_ $expr): bool
    {
        $slot = $block->slotForOperand($expr->result);
        if (null === $slot) {
            return false;
        }
        foreach ($block->opCodes as $op) {
            if ($op->arg1 !== $slot) {
                continue;
            }
            if (OpCode::TYPE_ISSET === $op->type) {
                return true;
            }
        }

        return false;
    }

    /**
     * php-cfg may clear Empty_/BooleanNot->expr after SSA phi replaceWith; recover read operand (#6829).
     */
    private function unaryExprOperandForRead(Op\Expr $expr, Block $block): ?Operand
    {
        if (null !== $expr->expr) {
            return $expr->expr;
        }
        if ($expr instanceof Op\Expr\Empty_) {
            return $this->recoverEmptyExprOperand($expr, $block);
        }
        if ($expr instanceof Op\Expr\BooleanNot) {
            return $this->recoverBooleanNotExprOperand($expr, $block);
        }

        return null;
    }

    private function compileUnaryExprReadOperand(Op\Expr $expr, Block $block): ?int
    {
        $operand = $this->unaryExprOperandForRead($expr, $block);

        return null !== $operand ? $this->compileOperand($operand, $block, true) : null;
    }

    /**
     * BooleanNot.expr cleared while JumpIf still uses result — find negated operand (#6829).
     */
    private function recoverBooleanNotExprOperand(Op\Expr\BooleanNot $expr, Block $block): ?Operand
    {
        $func = $block->func;
        if (null === $func?->cfg) {
            return null;
        }
        $line = $expr->getLine();
        $nearest = null;
        $nearestLine = -1;
        $walk = function ($node) use (&$walk, $line, &$nearest, &$nearestLine): void {
            if ($node instanceof Op\Expr\Assign && $node->getLine() <= $line && $node->getLine() > $nearestLine) {
                $nearestLine = $node->getLine();
                $nearest = $node->var;
            }
            if ($node instanceof CfgBlock) {
                foreach ($node->children as $child) {
                    $walk($child);
                }
            }
            if ($node instanceof Op\Stmt\JumpIf) {
                $walk($node->if);
                $walk($node->else);
            }
        };
        $walk($func->cfg);

        return $nearest;
    }

    protected function findCoalesceArrayDimFetch(?Operand $operand, Block $block): ?Op\Expr\ArrayDimFetch
    {
        if (null === $operand) {
            return null;
        }
        $direct = $this->unwrapArrayDimFetch($operand);
        if (null !== $direct) {
            return $direct;
        }
        foreach ($block->orig->children as $child) {
            if ($child instanceof Op\Expr\ArrayDimFetch && $child->result === $operand) {
                return $child;
            }
        }

        return null;
    }

    /**
     * @return ?Op\Expr\PropertyFetch
     */
    protected function findCoalescePropertyFetch(?Operand $operand, Block $block): ?Op\Expr\PropertyFetch
    {
        if (null === $operand) {
            return null;
        }
        $direct = $this->unwrapPropertyFetch($operand);
        if (null !== $direct) {
            return $direct;
        }
        $candidates = [$operand];
        $seen = [];
        while ([] !== $candidates) {
            $current = array_shift($candidates);
            if (isset($seen[spl_object_id($current)])) {
                continue;
            }
            $seen[spl_object_id($current)] = true;
            foreach ($block->orig->children as $child) {
                if ($child instanceof Op\Expr\PropertyFetch && $child->result === $current) {
                    return $child;
                }
            }
            if ($current instanceof Temporary && null !== $current->original) {
                $candidates[] = $current->original;
            }
        }

        return null;
    }

    /**
     * @return ?Op\Expr\StaticPropertyFetch
     */
    protected function findCoalesceStaticPropertyFetch(?Operand $operand, Block $block): ?Op\Expr\StaticPropertyFetch
    {
        if (null === $operand) {
            return null;
        }
        $direct = $this->unwrapStaticPropertyFetch($operand);
        if (null !== $direct) {
            return $direct;
        }
        $candidates = [$operand];
        $seen = [];
        while ([] !== $candidates) {
            $current = array_shift($candidates);
            if (isset($seen[spl_object_id($current)])) {
                continue;
            }
            $seen[spl_object_id($current)] = true;
            foreach ($block->orig->children as $child) {
                if ($child instanceof Op\Expr\StaticPropertyFetch && $child->result === $current) {
                    return $child;
                }
            }
            if ($current instanceof Temporary && null !== $current->original) {
                $candidates[] = $current->original;
            }
        }

        return null;
    }

    /**
     * @return array{0: int, 1: ?int}
     */
    protected function resolveIssetTargetFromPropertyFetch(Op\Expr\PropertyFetch $fetch, Block $block): array
    {
        return [
            $this->compileOperand($fetch->var, $block, true),
            $this->compileOperand($fetch->name, $block, true),
        ];
    }

    /**
     * @return array{0: int, 1: ?int}
     */
    protected function resolveIssetTargetFromStaticPropertyFetch(
        Op\Expr\StaticPropertyFetch $fetch,
        Block $block
    ): array {
        return [
            $this->compileOperand($fetch->class, $block, true),
            $this->compileStaticPropertyNameSlot($fetch->name, $fetch->class, $block),
        ];
    }

    /**
     * @return array{0: int, 1: ?int}
     */
    protected function resolveIssetTargetFromArrayDimFetch(Op\Expr\ArrayDimFetch $fetch, Block $block): array
    {
        return [
            $this->compileOperand($fetch->var, $block, true),
            null !== $fetch->dim ? $this->compileOperand($fetch->dim, $block, true) : null,
        ];
    }

    protected function makeIssetOpCode(
        int $resultSlot,
        int $containerSlot,
        ?int $dimSlot,
        bool $issetOnProperty
    ): OpCode {
        $op = new OpCode(OpCode::TYPE_ISSET, $resultSlot, $containerSlot, $dimSlot);
        $op->issetOnProperty = $issetOnProperty;

        return $op;
    }

    protected function unwrapVariableOperand(Operand $operand): ?Operand\Variable
    {
        while ($operand instanceof Temporary) {
            if ($operand->original instanceof Operand\Variable) {
                return $operand->original;
            }
            if (null === $operand->original) {
                return null;
            }
            $operand = $operand->original;
        }
        if ($operand instanceof Operand\Variable) {
            return $operand;
        }

        return null;
    }

    /**
     * isset($a, $b, …) with short-circuit evaluation (PHP semantics).
     * Returns the block where compilation should continue.
     */
    protected function compileIssetMulti(Op\Expr\Isset_ $expr, Block $block): Block
    {
        $resultSlot = $this->compileOperand($expr->result, $block, false);
        $falseSlot = $this->compileBoolConstant($block, false);
        $endBlock = new Block($block->orig);
        $endBlock->inheritUndefinedLocals = true;
        $endBlock->inheritScopeFrom($block);
        $falseBlock = new Block($block->orig);
        $falseBlock->inheritUndefinedLocals = true;
        $falseBlock->inheritScopeFrom($block);
        $falseBlock->addOpCode(new OpCode(
            OpCode::TYPE_ASSIGN,
            $resultSlot,
            $resultSlot,
            $falseSlot
        ));
        $falseJump = new OpCode(OpCode::TYPE_JUMP);
        $falseJump->block1 = $endBlock;
        $falseBlock->addOpCode($falseJump);
        $endBlock->parents[] = $falseBlock;

        $current = $block;
        $vars = $expr->vars;
        $last = count($vars) - 1;
        foreach ($vars as $i => $var) {
            $this->assertIssetVariableOperand($var, $block);
            $propFetch = $this->findCoalescePropertyFetch($var, $block);
            $staticPropFetch = null !== $propFetch
                ? null
                : $this->findCoalesceStaticPropertyFetch($var, $block);
            $dimFetch = null !== $propFetch || null !== $staticPropFetch
                ? null
                : $this->findCoalesceArrayDimFetch($var, $block);
            [$containerSlot, $dimSlot] = null !== $propFetch
                ? $this->resolveIssetTargetFromPropertyFetch($propFetch, $current)
                : (null !== $staticPropFetch
                    ? $this->resolveIssetTargetFromStaticPropertyFetch($staticPropFetch, $current)
                    : (null !== $dimFetch
                        ? $this->resolveIssetTargetFromArrayDimFetch($dimFetch, $current)
                        : $this->resolveIssetTarget($var, $current)));
            $checkSlot = $resultSlot;
            if ($i < $last) {
                $checkSlot = $this->compileBoolTemporary($current);
            }
            if (null === $containerSlot) {
                $varSlot = $this->compileOperand($var, $current, true);
                $current->addOpCode(new OpCode(OpCode::TYPE_ISSET, $checkSlot, $varSlot, null));
            } else {
                $issetOp = $this->makeIssetOpCode(
                    $checkSlot,
                    $containerSlot,
                    $dimSlot,
                    null !== $propFetch
                );
                if (null !== $staticPropFetch) {
                    $issetOp->issetOnStaticProperty = true;
                }
                $current->addOpCode($issetOp);
            }
            if ($i < $last) {
                $next = new Block($block->orig);
                $next->inheritUndefinedLocals = true;
                $next->inheritScopeFrom($current);
                $jump = new OpCode(OpCode::TYPE_JUMPIF, $checkSlot);
                $jump->block1 = $next;
                $jump->block2 = $falseBlock;
                $next->parents[] = $current;
                $falseBlock->parents[] = $current;
                $current->addOpCode($jump);
                $current = $next;
            }
        }

        $doneJump = new OpCode(OpCode::TYPE_JUMP);
        $doneJump->block1 = $endBlock;
        $current->addOpCode($doneJump);
        $endBlock->parents[] = $current;

        return $endBlock;
    }

    protected function compileBoolTemporary(Block $block): int
    {
        $operand = new Temporary;
        $operand->type = Type::bool();
        // JIT assignOperandValue skips operands with empty usages (#99 coalesce branches).
        $operand->usages[] = $operand;

        return $block->getVarSlot($operand, false);
    }

    protected function compileBoolConstant(Block $block, bool $value): int
    {
        $var = new Variable(Variable::TYPE_BOOLEAN);
        $var->bool($value);
        $operand = new Operand\Temporary;
        $operand->type = Type::bool();

        return $block->registerConstant($operand, $var);
    }

    /**
     * Normal try/catch completion must run finally before merge; php-cfg jumps straight to end (#2114, #195).
     */
    private function rewriteMergeJumpsToFinally(Block $source, Block $merge, Block $finally): void
    {
        for ($i = 0; $i < $source->nOpCodes; ++$i) {
            $op = $source->opCodes[$i];
            if (OpCode::TYPE_JUMP === $op->type && $op->block1 === $merge) {
                $op->block1 = $finally;
            }
        }
    }

    /**
     * Try/catch merge blocks from php-cfg may include later sibling try/catch in the same end
     * block. JIT pre-lowers merge at beginTry via compileIncludedAtEntry; nested TYPE_TRY in
     * that merge corrupts LLVM EH basic blocks (#4041). Split so merge is prefix-only + JUMP.
     *
     * When the nested TYPE_TRY is at index 0 (two sequential try/catch, nothing between), still
     * split into an empty merge prefix that JUMP's to the nested try — otherwise the first
     * catch falls into the second try's EH and the second catch sees the first exception (#23930).
     */
    private function splitMergeBeforeNestedTry(Block $merge): Block
    {
        $splitAt = null;
        for ($i = 0; $i < $merge->nOpCodes; ++$i) {
            $type = $merge->opCodes[$i]->type;
            if (
                OpCode::TYPE_TRY === $type
                || OpCode::TYPE_CATCH === $type
                || OpCode::TYPE_FINALLY === $type
            ) {
                $splitAt = $i;
                break;
            }
        }
        if (null === $splitAt) {
            return $merge;
        }
        $tailOps = \array_slice($merge->opCodes, $splitAt);
        $merge->opCodes = \array_slice($merge->opCodes, 0, $splitAt);
        $merge->nOpCodes = \count($merge->opCodes);
        $tail = $merge->fragmentForOpcodes($tailOps);
        $tail->orig = $merge->orig;
        $tail->inheritUndefinedLocals = $merge->inheritUndefinedLocals;
        $jump = new OpCode(OpCode::TYPE_JUMP);
        $jump->block1 = $tail;
        $merge->addOpCode($jump);

        return $merge;
    }

    /**
     * php-cfg TryCatch emits a Stmt_Jump into the try body; TYPE_TRY already enters it (#2084).
     */
    private function isRedundantTryEntryJump(Block $block, Block $target): bool
    {
        for ($i = $block->nOpCodes - 1; $i >= 0; --$i) {
            $op = $block->opCodes[$i];
            if (OpCode::TYPE_CATCH === $op->type || OpCode::TYPE_FINALLY === $op->type) {
                continue;
            }
            if (OpCode::TYPE_TRY === $op->type) {
                return $op->block1 === $target;
            }

            break;
        }

        return false;
    }

    protected function encodeCatchTypeList(array $types): string
    {
        $encoded = [];
        foreach ($types as $name) {
            // Intersection arms arrive as a single `A&B` member from php-cfg (#28205).
            if (str_contains($name, '&')) {
                $parts = [];
                foreach (explode('&', $name) as $part) {
                    $parts[] = strtolower(ltrim($part, '\\'));
                }
                $encoded[] = implode('&', $parts);
            } else {
                $encoded[] = strtolower(ltrim($name, '\\'));
            }
        }

        return implode('|', $encoded);
    }

    /**
     * php-cfg catch vars are registered on the handler block; the catch body may use
     * a distinct operand for the same name (#195, #2084, #3445).
     */
    protected function resolveCatchVarSlot(Block $compiledCatch, ?Operand $catchVar): ?int
    {
        if (null === $catchVar) {
            return null;
        }
        $slot = $compiledCatch->slotForOperand($catchVar);
        if (null !== $slot) {
            return $slot;
        }
        if (null !== $this->resolveCatchVariableName($catchVar)) {
            // Catch body may reference $e only from nested try blocks (#195, #2084).
            return $compiledCatch->getVarSlot($catchVar, false);
        }

        return null;
    }

    protected function resolveCatchVariableName(?Operand $catchVar): ?string
    {
        while ($catchVar instanceof Operand\Temporary && null !== $catchVar->original) {
            $catchVar = $catchVar->original;
        }
        if (!$catchVar instanceof Operand\Variable) {
            return null;
        }
        $nameOp = $catchVar->name;
        while ($nameOp instanceof Operand\Temporary && null !== $nameOp->original) {
            $nameOp = $nameOp->original;
        }
        if ($nameOp instanceof Literal && is_string($nameOp->value)) {
            return $nameOp->value;
        }

        return null;
    }

    private function slotForActiveCatchVariable(?Operand $operand): ?int
    {
        if ([] === $this->activeCatchVarSlotsByName || null === $operand) {
            return null;
        }
        $name = $this->resolveCatchVariableName($operand);
        if (null !== $name) {
            $slot = $this->activeCatchVarSlotsByName[strtolower($name)] ?? null;
            if (null !== $slot) {
                return $slot;
            }
        }
        $root = Block::cfgVarRoot($operand);
        if (null === $root) {
            return null;
        }
        foreach ($this->activeCatchVarRoots as $catchRoot) {
            if ($catchRoot === $root) {
                $catchName = $this->resolveCatchVariableName($catchRoot);
                if (null === $catchName) {
                    return null;
                }

                return $this->activeCatchVarSlotsByName[strtolower($catchName)] ?? null;
            }
        }

        return null;
    }

    /**
     * @param Op\Expr|Operand $expr
     *
     * @return array{0: int, 1: ?int}
     */
    protected function resolveIssetTarget($expr, Block $block): array
    {
        if ($expr instanceof Op\Expr\ArrayDimFetch) {
            return $this->resolveIssetTargetFromArrayDimFetch($expr, $block);
        }
        if ($expr instanceof Op\Expr\PropertyFetch) {
            return [
                $this->compileOperand($expr->var, $block, true),
                $this->compileOperand($expr->name, $block, true),
            ];
        }
        if ($expr instanceof Operand) {
            $fetch = $this->unwrapArrayDimFetch($expr);
            if (null !== $fetch) {
                return [
                    $this->compileOperand($fetch->var, $block, true),
                    $this->compileOperand($fetch->dim, $block, true),
                ];
            }
            foreach ($block->orig->children as $child) {
                if ($child instanceof Op\Expr\PropertyFetch && $child->result === $expr) {
                    return [
                        $this->compileOperand($child->var, $block, true),
                        $this->compileOperand($child->name, $block, true),
                    ];
                }
            }
            $canonical = $this->unwrapVariableOperand($expr);

            return [$this->compileOperand(null !== $canonical ? $canonical : $expr, $block, true), null];
        }

        $this->throwCompileLogic('Unsupported isset target: ' . (is_object($expr) ? $expr->getType() : gettype($expr)));
    }

    /**
     * Reject `$arr[]` in read context — Zend compile fatal (#12303, zend_language_parser.y).
     */
    protected function rejectArrayEmptyOffsetRead(Op\Expr\ArrayDimFetch $fetch, Block $block): void
    {
        if (!$this->isArrayAppendDim($fetch->dim)) {
            return;
        }
        if ($this->isArrayDimFetchForWrite($fetch, $block)) {
            return;
        }
        $this->throwCompileError(self::ARRAY_EMPTY_OFFSET_READ_COMPILE_ERROR);
    }

    /** True for `$arr[]` append syntax — php-cfg uses {@see NullOperand}, not PHP null (#12303). */
    protected function isArrayAppendDim(?Operand $dim): bool
    {
        // Plain null dim means php-cfg lost the index operand (comma-for `$a[$i]` in for-init, #1492).
        return $dim instanceof NullOperand;
    }

    /**
     * True when the fetch result is only used as a write lvalue (assign, unset, or ++/--; issue #103, #1224, #6798).
     * Nested write through a dimension ($obj[$k][] = $v) also requires write fetch on the outer dim (#3446).
     */
    protected function isArrayDimFetchForWrite(Op\Expr\ArrayDimFetch $fetch, Block $block): bool
    {
        foreach ($fetch->result->usages as $usage) {
            if ($usage instanceof Op\Expr\Assign && $usage->var === $fetch->result) {
                continue;
            }
            // AssignRef RHS needs FETCH_DIM_W for reference acquisition (#7441, zend_execute.c).
            if (
                $usage instanceof Op\Expr\AssignRef
                && ($usage->var === $fetch->result || $usage->expr === $fetch->result)
            ) {
                continue;
            }
            // `yield $arr[$i]` from `function &gen()` needs the live element (#25877).
            if ($this->arrayDimFetchUsedAsByRefYieldValue($fetch, $usage, $block)) {
                continue;
            }
            // `[&$s[$i]]` — by-ref array element must FETCH_DIM_W so string offsets raise (#21910).
            if (
                $usage instanceof Op\Expr\Array_
                && $this->arrayLiteralHasByRefElementOperand($usage, $fetch->result)
            ) {
                continue;
            }
            if ($usage instanceof Op\Terminal\Unset_ && $this->unsetTerminalUsesOperand($usage, $fetch->result)) {
                continue;
            }
            if ($this->isIncDecUsingOperand($usage, $fetch->result)) {
                continue;
            }
            // AssignOp ($s[$i] += 1) expands to BinaryOp(left=fetch) + Assign(var=fetch) (#22897).
            if ($this->isAssignOpBinaryUsingDimFetch($usage, $fetch, $block)) {
                continue;
            }
            if (
                $usage instanceof Op\Expr\ArrayDimFetch
                && $usage->var === $fetch->result
                && $this->isArrayDimFetchForWrite($usage, $block)
            ) {
                return true;
            }
            if ($this->arrayDimFetchUsedAsByRefCallArg($fetch, $usage, $block)) {
                continue;
            }

            return false;
        }
        if (!empty($fetch->result->usages)) {
            return true;
        }
        // php-cfg often leaves operand->usages empty; fall back to the next stmt in this block.
        $children = $block->orig->children;
        foreach ($children as $i => $child) {
            if ($child !== $fetch) {
                continue;
            }
            if ($i + 1 >= count($children)) {
                break;
            }
            $next = $children[$i + 1];

            if ($next instanceof Op\Expr\Assign && $next->var === $fetch->result) {
                return true;
            }
            if (
                $next instanceof Op\Expr\AssignRef
                && ($next->var === $fetch->result || $next->expr === $fetch->result)
            ) {
                return true;
            }
            // php-cfg: ArrayDimFetch then Yield from function &gen() (#25877).
            if ($this->arrayDimFetchUsedAsByRefYieldValue($fetch, $next, $block)) {
                return true;
            }
            // php-cfg: ArrayDimFetch then Expr_Array with byRef element (#21910).
            if (
                $next instanceof Op\Expr\Array_
                && $this->arrayLiteralHasByRefElementOperand($next, $fetch->result)
            ) {
                return true;
            }
            if ($next instanceof Op\Terminal\Unset_ && $this->unsetTerminalUsesOperand($next, $fetch->result)) {
                return true;
            }
            if ($this->isIncDecUsingOperand($next, $fetch->result)) {
                return true;
            }
            // AssignOp: ArrayDimFetch; BinaryOp; Assign back to fetch (#22897).
            if (
                $next instanceof Op\Expr\BinaryOp
                && $this->isAssignOpPatternFollowingDimFetch($fetch, $next, $children, $i)
            ) {
                return true;
            }
            if (
                $next instanceof Op\Expr\ArrayDimFetch
                && $next->var === $fetch->result
                && $this->isArrayDimFetchForWrite($next, $block)
            ) {
                return true;
            }
            if ($this->arrayDimFetchPrecedesByRefBuiltinCall($fetch, $next, $block, $i, $children)) {
                return true;
            }

            return false;
        }

        return false;
    }

    /**
     * php-cfg expands AssignOp to BinaryOp(left=dim) + Assign(var=dim); ??= stays read (#22897).
     *
     * The trailing Assign often is absent from operand->usages (only BinaryOp is listed).
     */
    private function isAssignOpBinaryUsingDimFetch($usage, Op\Expr\ArrayDimFetch $fetch, Block $block): bool
    {
        if (!$usage instanceof Op\Expr\BinaryOp) {
            return false;
        }
        // Zend allows ??= on string offsets (no assign-op Error).
        if ($usage instanceof Op\Expr\BinaryOp\Coalesce) {
            return false;
        }
        if ($usage->left !== $fetch->result) {
            return false;
        }
        foreach ($fetch->result->usages as $u) {
            if (
                $u instanceof Op\Expr\Assign
                && $u->var === $fetch->result
                && $u->expr === $usage->result
            ) {
                return true;
            }
        }
        if (null === $block->orig) {
            return false;
        }
        foreach ($block->orig->children as $child) {
            if (
                $child instanceof Op\Expr\Assign
                && $child->var === $fetch->result
                && $child->expr === $usage->result
            ) {
                return true;
            }
        }

        return false;
    }

    /**
     * @param list<Op> $children
     */
    private function isAssignOpPatternFollowingDimFetch(
        Op\Expr\ArrayDimFetch $fetch,
        Op\Expr\BinaryOp $bin,
        array $children,
        int $fetchIndex
    ): bool {
        if ($bin instanceof Op\Expr\BinaryOp\Coalesce) {
            return false;
        }
        if ($bin->left !== $fetch->result) {
            return false;
        }
        if ($fetchIndex + 2 >= \count($children)) {
            return false;
        }
        $assign = $children[$fetchIndex + 2];

        return $assign instanceof Op\Expr\Assign
            && $assign->var === $fetch->result
            && $assign->expr === $bin->result;
    }

    /**
     * sscanf('%d', $a[0]) — php-cfg dead arg temps; dim fetch immediately precedes call (#4512).
     */
    private function arrayDimFetchPrecedesByRefBuiltinCall(
        Op\Expr\ArrayDimFetch $fetch,
        Op $maybeCall,
        Block $block,
        int $fetchChildIndex,
        array $children
    ): bool {
        if (!$maybeCall instanceof Op\Expr\FuncCall && !$maybeCall instanceof Op\Expr\NsFuncCall) {
            return false;
        }
        $callIndex = $fetchChildIndex + 1;
        if ($callIndex >= \count($children) || $children[$callIndex] !== $maybeCall) {
            return false;
        }
        $calleeName = $this->funcCallExprCalleeName($maybeCall);
        if (null === $calleeName) {
            return false;
        }
        /** @var list<Op\Expr\ArrayDimFetch> $dimFetches */
        $dimFetches = [];
        for ($j = $fetchChildIndex; $j >= 0; --$j) {
            $child = $children[$j];
            if ($child instanceof Op\Expr\ArrayDimFetch) {
                array_unshift($dimFetches, $child);
                continue;
            }
            if ($child instanceof Op\Expr\ConstFetch || $child instanceof Op\Expr\ClassConstFetch) {
                continue;
            }
            break;
        }
        if ([] === $dimFetches) {
            return false;
        }
        $dimFetchIndex = array_search($fetch, $dimFetches, true);
        if (false === $dimFetchIndex) {
            return false;
        }
        $callArgs = property_exists($maybeCall, 'args') && is_array($maybeCall->args)
            ? $maybeCall->args
            : [];
        $argIndex = (int) $dimFetchIndex;
        if (\count($dimFetches) < \count($callArgs)) {
            $nonEmbeddedArgIndices = [];
            foreach ($callArgs as $idx => $callArg) {
                if (null !== $callArg && !$this->isEmbeddedCallLiteralArg($callArg)) {
                    $nonEmbeddedArgIndices[] = $idx;
                }
            }
            if (!isset($nonEmbeddedArgIndices[$dimFetchIndex])) {
                return false;
            }
            $argIndex = (int) $nonEmbeddedArgIndices[$dimFetchIndex];
        }

        return $this->callArgRequiresByRef($calleeName, $argIndex, null, $block);
    }

    /**
     * yield $arr[$i] from function &gen() — FETCH_DIM_W so foreach as &$v writeback hits the element (#25877).
     */
    private function arrayDimFetchUsedAsByRefYieldValue(
        Op\Expr\ArrayDimFetch $fetch,
        Op $usage,
        Block $block
    ): bool {
        if (!$usage instanceof Op\Expr\Yield_) {
            return false;
        }
        if ($usage->value !== $fetch->result) {
            return false;
        }

        return $this->cfgFunctionReturnsByReference($block);
    }

    /**
     * `return $this->prop` from `function &name()` needs FETCH_OBJ_W (#29456, zend_execute.c).
     */
    private function propertyFetchUsedAsByRefReturnValue(
        Op\Expr\PropertyFetch $fetch,
        Op $usage,
        Block $block
    ): bool {
        if (!$usage instanceof Op\Terminal\Return_) {
            return false;
        }
        if ($usage->expr !== $fetch->result) {
            return false;
        }

        return $this->cfgFunctionReturnsByReference($block);
    }

    /**
     * `yield $this->prop` from `function &gen()` needs the live property cell (#29456).
     */
    private function propertyFetchUsedAsByRefYieldValue(
        Op\Expr\PropertyFetch $fetch,
        Op $usage,
        Block $block
    ): bool {
        if (!$usage instanceof Op\Expr\Yield_) {
            return false;
        }
        if ($usage->value !== $fetch->result) {
            return false;
        }

        return $this->cfgFunctionReturnsByReference($block);
    }

    /** True when the enclosing CFG func is declared `function &name()` (FLAG_RETURNS_REF). */
    private function cfgFunctionReturnsByReference(Block $block): bool
    {
        $decl = $block->func ?? null;

        return null !== $decl
            && (($decl->flags ?? 0) & \PHPCfg\Func::FLAG_RETURNS_REF) !== 0;
    }

    /** @deprecated alias — FLAG_RETURNS_REF covers yield-by-ref and return-by-ref */
    private function cfgFunctionYieldsByReference(Block $block): bool
    {
        return $this->cfgFunctionReturnsByReference($block);
    }

    /**
     * sscanf('%d', $a[0]) — by-ref builtin args need FETCH_DIM_W (#4512, zend_execute.c ZEND_SEND_REF).
     */
    private function arrayDimFetchUsedAsByRefCallArg(
        Op\Expr\ArrayDimFetch $fetch,
        Op $usage,
        Block $block
    ): bool {
        if (!$usage instanceof Op\Expr\FuncCall && !$usage instanceof Op\Expr\NsFuncCall) {
            return false;
        }
        if (!property_exists($usage, 'args') || !is_array($usage->args)) {
            return false;
        }
        $calleeName = $this->funcCallExprCalleeName($usage);
        if (null === $calleeName) {
            return false;
        }
        foreach ($usage->args as $argIndex => $callArg) {
            if (
                null === $callArg
                || (
                    $callArg !== $fetch->result
                    && !$this->operandsReferToSameVariable($callArg, $fetch->result)
                )
            ) {
                continue;
            }
            if ($this->callArgRequiresByRef($calleeName, (int) $argIndex, $callArg, $block)) {
                return true;
            }
        }

        return false;
    }

    /**
     * bump($obj->prop) — by-ref call args need FETCH_OBJ_W (#25301, zend_execute.c ZEND_SEND_REF).
     */
    private function propertyFetchUsedAsByRefCallArg(
        Op\Expr\PropertyFetch $fetch,
        Op $usage,
        Block $block
    ): bool {
        if (!$usage instanceof Op\Expr\FuncCall && !$usage instanceof Op\Expr\NsFuncCall) {
            return false;
        }
        if (!property_exists($usage, 'args') || !is_array($usage->args)) {
            return false;
        }
        $calleeName = $this->funcCallExprCalleeName($usage);
        if (null === $calleeName) {
            return false;
        }
        $argIndex = $this->propertyFetchByRefCallArgIndex($fetch, $usage, $block);
        if (null === $argIndex) {
            return false;
        }

        return $this->callArgRequiresByRef($calleeName, $argIndex, null, $block);
    }

    /**
     * @return ?int call arg index when $fetch is a by-ref actual (operand temps may differ, #25301).
     */
    private function propertyFetchByRefCallArgIndex(
        Op\Expr\PropertyFetch $fetch,
        Op\Expr\FuncCall|Op\Expr\NsFuncCall $call,
        ?Block $block = null,
        ?array $children = null
    ): ?int {
        if (!property_exists($call, 'args') || !is_array($call->args)) {
            return null;
        }
        foreach ($call->args as $argIndex => $callArg) {
            if (
                null !== $callArg
                && (
                    $callArg === $fetch->result
                    || $this->operandsReferToSameVariable($callArg, $fetch->result)
                )
            ) {
                return (int) $argIndex;
            }
        }
        if (null === $children && null !== $block?->orig) {
            $children = $block->orig->children;
        }
        if (null === $children) {
            return null;
        }
        $fetchIndex = null;
        foreach ($children as $i => $child) {
            if ($child === $fetch) {
                $fetchIndex = $i;
                break;
            }
        }
        if (null === $fetchIndex) {
            return null;
        }
        /** @var list<Op\Expr\PropertyFetch> $propFetches */
        $propFetches = [];
        for ($j = $fetchIndex; $j >= 0; --$j) {
            $child = $children[$j];
            if ($child instanceof Op\Expr\PropertyFetch) {
                array_unshift($propFetches, $child);
                continue;
            }
            if ($child instanceof Op\Expr\ConstFetch || $child instanceof Op\Expr\ClassConstFetch) {
                continue;
            }
            break;
        }
        if ([] === $propFetches) {
            return null;
        }
        $propFetchIndex = array_search($fetch, $propFetches, true);
        if (false === $propFetchIndex) {
            return null;
        }
        $callIndex = $fetchIndex + 1;
        if ($callIndex >= \count($children) || $children[$callIndex] !== $call) {
            return null;
        }
        $callArgs = $call->args;
        $argIndex = (int) $propFetchIndex;
        if (\count($propFetches) < \count($callArgs)) {
            $nonEmbeddedArgIndices = [];
            foreach ($callArgs as $idx => $callArg) {
                if (null !== $callArg && !$this->isEmbeddedCallLiteralArg($callArg)) {
                    $nonEmbeddedArgIndices[] = $idx;
                }
            }
            if (!isset($nonEmbeddedArgIndices[$propFetchIndex])) {
                return null;
            }
            $argIndex = (int) $nonEmbeddedArgIndices[$propFetchIndex];
        }

        return $argIndex;
    }

    /**
     * php-cfg: PropertyFetch immediately precedes by-ref FuncCall when usages are empty (#25301).
     *
     * @param list<Op> $children
     */
    private function propertyFetchPrecedesByRefCall(
        Op\Expr\PropertyFetch $fetch,
        Op $maybeCall,
        Block $block,
        int $fetchChildIndex,
        array $children
    ): bool {
        if (!$maybeCall instanceof Op\Expr\FuncCall && !$maybeCall instanceof Op\Expr\NsFuncCall) {
            return false;
        }
        $callIndex = $fetchChildIndex + 1;
        if ($callIndex >= \count($children) || $children[$callIndex] !== $maybeCall) {
            return false;
        }
        $calleeName = $this->funcCallExprCalleeName($maybeCall);
        if (null === $calleeName) {
            return false;
        }
        $argIndex = $this->propertyFetchByRefCallArgIndex($fetch, $maybeCall, $block, $children);
        if (null === $argIndex) {
            return false;
        }

        return $this->callArgRequiresByRef($calleeName, $argIndex, null, $block);
    }

    /**
     * True when property fetch is only used as write/ref lvalue (assign, AssignRef, unset, ++/--; #13559).
     */
    protected function isPropertyFetchForWrite(Op\Expr\PropertyFetch $fetch, Block $block): bool
    {
        if ($this->forcePropertyFetchForWrite > 0) {
            return true;
        }
        foreach ($fetch->result->usages as $usage) {
            if ($usage instanceof Op\Expr\Assign && $usage->var === $fetch->result) {
                continue;
            }
            if (
                $usage instanceof Op\Expr\AssignRef
                && ($usage->var === $fetch->result || $usage->expr === $fetch->result)
            ) {
                continue;
            }
            if ($usage instanceof Op\Terminal\Unset_ && $this->unsetTerminalUsesOperand($usage, $fetch->result)) {
                continue;
            }
            if ($this->isIncDecUsingOperand($usage, $fetch->result)) {
                continue;
            }
            if ($this->propertyFetchUsedAsByRefCallArg($fetch, $usage, $block)) {
                continue;
            }
            // `return $this->prop` / `yield $this->prop` from `&method` (#29456).
            if ($this->propertyFetchUsedAsByRefReturnValue($fetch, $usage, $block)) {
                continue;
            }
            if ($this->propertyFetchUsedAsByRefYieldValue($fetch, $usage, $block)) {
                continue;
            }
            // $obj->prop[] = must read through get hook first; dim write uses FETCH not FETCH_W (#6775, #19171).
            if (
                $usage instanceof Op\Expr\ArrayDimFetch
                && $usage->var === $fetch->result
                && $this->isArrayDimFetchForWrite($usage, $block)
            ) {
                continue;
            }

            return false;
        }
        if (!empty($fetch->result->usages)) {
            if ($this->propertyFetchOnlyUsedAsDimWriteContainer($fetch, $block)) {
                return false;
            }

            return true;
        }
        $children = $block->orig->children;
        foreach ($children as $i => $child) {
            if ($child !== $fetch) {
                continue;
            }
            if ($i + 1 >= count($children)) {
                break;
            }
            $next = $children[$i + 1];

            if ($next instanceof Op\Expr\Assign && $next->var === $fetch->result) {
                return true;
            }
            if (
                $next instanceof Op\Expr\AssignRef
                && ($next->var === $fetch->result || $next->expr === $fetch->result)
            ) {
                return true;
            }
            if ($next instanceof Op\Terminal\Unset_ && $this->unsetTerminalUsesOperand($next, $fetch->result)) {
                return true;
            }
            if ($this->isIncDecUsingOperand($next, $fetch->result)) {
                return true;
            }
            if ($this->propertyFetchPrecedesByRefCall($fetch, $next, $block, $i, $children)) {
                return true;
            }
            if ($this->propertyFetchUsedAsByRefReturnValue($fetch, $next, $block)) {
                return true;
            }
            if ($this->propertyFetchUsedAsByRefYieldValue($fetch, $next, $block)) {
                return true;
            }
            // $obj->prop[] = — read fetch + dim write container (#6775, #19171).
            if (
                $next instanceof Op\Expr\ArrayDimFetch
                && $next->var === $fetch->result
                && $this->isArrayDimFetchForWrite($next, $block)
            ) {
                return false;
            }

            return false;
        }

        return false;
    }

    /** True when every usage of the property fetch is $obj->prop[…] = write (#6775, #19171). */
    private function propertyFetchOnlyUsedAsDimWriteContainer(Op\Expr\PropertyFetch $fetch, Block $block): bool
    {
        if ([] === $fetch->result->usages) {
            return false;
        }
        foreach ($fetch->result->usages as $usage) {
            if (
                $usage instanceof Op\Expr\ArrayDimFetch
                && $usage->var === $fetch->result
                && $this->isArrayDimFetchForWrite($usage, $block)
            ) {
                continue;
            }

            return false;
        }

        return true;
    }

    /**
     * @param Op\Node $usage
     */
    private function isIncDecUsingOperand($usage, Operand $operand): bool
    {
        if (
            !$usage instanceof Op\Expr\PostInc
            && !$usage instanceof Op\Expr\PreInc
            && !$usage instanceof Op\Expr\PostDec
            && !$usage instanceof Op\Expr\PreDec
        ) {
            return false;
        }
        $write = $usage->write ?? $usage->read;

        return $usage->read === $operand || $write === $operand;
    }

    /**
     * php-cfg Expr::result temporaries omit ->original; match list-destruct fetch by result (#3799).
     */
    protected function findArrayDimFetchForResult(Operand $result, Block $block): ?Op\Expr\ArrayDimFetch
    {
        if (null === $block->orig) {
            return null;
        }
        foreach ($block->orig->children as $child) {
            if ($child instanceof Op\Expr\ArrayDimFetch && $child->result === $result) {
                return $child;
            }
        }
        // php-cfg may allocate a distinct FuncCall arg temp whose sole writer is the dim
        // fetch (`f([1,2][0])` — arg !== ArrayDimFetch->result) (#29522).
        $writer = $result->ops[0] ?? null;
        if ($writer instanceof Op\Expr\ArrayDimFetch) {
            return $writer;
        }

        return null;
    }

    /**
     * php-cfg Expr::result temporaries omit ->original; match inline array literal RHS (#3799).
     */
    protected function findArrayExprForResult(Operand $result, Block $block): ?Op\Expr\Array_
    {
        foreach ($block->orig->children as $child) {
            if ($child instanceof Op\Expr\Array_ && $child->result === $result) {
                return $child;
            }
        }

        return null;
    }

    /**
     * php-cfg may lower inline Expr_Array / Expr_New results and call/ctor args to distinct
     * temporaries (`f(['a' => 1])`, `new C(['x'])`, `g(new C('x'))`) (#8561).
     *
     * @return ?string producer slot to pass to TYPE_ARG_SEND instead of the empty arg slot
     */
    /**
     * php-cfg hoists enum `case` ClassConstFetch before inline Expr_Array call args (#5721).
     */
    private function findInlineArrayProducerForCallArg(
        Operand $arg,
        Block $block,
        ?Op $cfgCallOp = null,
        ?int $knownArgIndex = null
    ): ?Op\Expr\Array_
    {
        $cfgChildren = $this->inlineCallArgProducerCfgChildren($block);
        if ([] === $cfgChildren && null === $block->orig) {
            return null;
        }
        $callSite = $this->findCfgCallSiteForArg($cfgChildren, $arg, $cfgCallOp);
        if (null === $callSite && null !== $cfgCallOp && null !== $knownArgIndex) {
            $callSite = [$cfgCallOp, $knownArgIndex];
        }
        if (null === $callSite) {
            return null;
        }
        [$callOp, $argIndex] = $callSite;
        if (!property_exists($callOp, 'args') || !is_array($callOp->args)) {
            return null;
        }
        $namedMergeCallArg = $callOp->args[$argIndex] ?? $arg;
        if (
            $namedMergeCallArg instanceof Operand
            && null !== Block::resolveVariableName($namedMergeCallArg)
            && !$this->callArgIsDeadInlineTemporary($namedMergeCallArg)
            && \in_array(
                $this->resolveCfgFuncCallName($callOp),
                ['array_merge', 'array_merge_recursive', 'array_replace', 'array_replace_recursive'],
                true
            )
        ) {
            // $a = [...]; array_replace_recursive($a, $b) — read assign slots, not trailing hoisted Array_ (#18571).
            return null;
        }
        if ('array_combine' === $this->resolveCfgFuncCallName($callOp)) {
            $combineProducers = $this->precedingInlineCallArgProducersBeforeCfgOp($cfgChildren, $callOp);
            $combineMatch = $this->matchArrayCombineInlineProducers($combineProducers, $argIndex);
            if ($combineMatch instanceof Op\Expr\Array_) {
                return $combineMatch;
            }
            if (
                $combineMatch instanceof Op\Expr\FuncCall
                || $combineMatch instanceof Op\Expr\NsFuncCall
            ) {
                // array_combine(array_keys(...), [...]) — nested FuncCall arg, not stmt-before Array_ (#15857).
                return null;
            }
        }
        if ('substr_replace' === $this->resolveCfgFuncCallName($callOp)) {
            $substrReplaceProducers = $this->precedingInlineCallArgProducersBeforeCfgOp($block->orig->children, $callOp);
            $substrReplaceMatch = $this->matchInlineArrayProducersToArrayCallArgs(
                $substrReplaceProducers,
                $callOp->args,
                $argIndex
            );
            if ($substrReplaceMatch instanceof Op\Expr\Array_) {
                return $substrReplaceMatch;
            }
        }
        if (
            'proc_open' === $this->resolveCfgFuncCallName($callOp)
            && \is_array($callOp->args)
        ) {
            $hoisted = $this->procOpenHoistedInlineArrayForArg($callOp, $argIndex, $block);
            if ($hoisted instanceof Op\Expr\Array_) {
                return $hoisted;
            }
            $procOpenProducers = $this->precedingInlineCallArgProducersBeforeCfgOp($cfgChildren, $callOp);
            $arrayProducers = array_values(array_filter(
                $procOpenProducers,
                static fn (Op\Expr $producer): bool => $producer instanceof Op\Expr\Array_
            ));
            if (0 === $argIndex) {
                $commandArg = $callOp->args[0] ?? null;
                if ($commandArg instanceof Operand) {
                    $embeddedCommand = $this->unwrapArrayLiteralExpr($commandArg);
                    if ($embeddedCommand instanceof Op\Expr\Array_) {
                        return $embeddedCommand;
                    }
                }
            }
            if (\in_array($argIndex, [0, 1], true) && [] !== $arrayProducers) {
                $matched = $this->matchInlineArrayProducersToArrayCallArgs(
                    $procOpenProducers,
                    $callOp->args,
                    $argIndex
                );
                if ($matched instanceof Op\Expr\Array_) {
                    return $matched;
                }
            }
            if (1 === $argIndex && [] !== $arrayProducers) {
                $outer = $this->matchOutermostNestedInlineArrayProducerForCallArg(
                    $procOpenProducers,
                    $arrayProducers,
                    $argIndex,
                    \count($callOp->args)
                );
                if ($outer instanceof Op\Expr\Array_) {
                    return $outer;
                }
            }
        }
        $callIndex = null;
        foreach ($cfgChildren as $i => $child) {
            if ($child === $callOp) {
                $callIndex = $i;
                break;
            }
        }
        if (null !== $callIndex) {
            $prev = $cfgChildren[$callIndex - 1] ?? null;
            if ($prev instanceof Op\Expr\ArrayDimFetch) {
                $positionalCallArg = $callOp->args[$argIndex] ?? $arg;
                if (
                    null !== $prev->result
                    && null !== $positionalCallArg
                    && $this->operandsReferToSameVariable($prev->result, $positionalCallArg)
                ) {
                    return null;
                }
            }
            for ($i = $callIndex - 1; $i >= 0; --$i) {
                $child = $cfgChildren[$i];
                if ($child instanceof Op\Expr\FuncCall || $child instanceof Op\Expr\NsFuncCall) {
                    break;
                }
                if ($child instanceof Op\Expr\BinaryOp\Plus) {
                    // Plus immediately precedes the call — wire TYPE_ARG_SEND to Plus.result (#10490, #12763).
                    return null;
                }
                if ($child instanceof Op\Expr\Array_) {
                    $callArgProbe = $callOp->args[$argIndex] ?? $arg;
                    // var_export([array_any([], fn), array_all([], fn)]) — stmt-before Array_ (#14516).
                    // new C([...]) in param/static defaultBlocks: php-cfg often leaves the ctor arg
                    // as inferred unknown/mixed while Array_.result is int[] (#22390, #8561).
                    // var_export([...new ArrayIterator([...])]) — unpack Array_ is inferred unknown
                    // while an earlier ctor Array_ sits before New_; bind stmt-before (#24645).
                    // Do not apply the New_ fallback to typed null/scalar dead temps — that steals
                    // the trailing Array_ for `new C(null, [...])` (#22770).
                    $deadTempWantsArray = $this->callArgIsDeadInlineTemporary($callArgProbe)
                        && (
                            $this->callArgOperandExpectsArrayProducer($callArgProbe)
                            || $this->callArgIsDeadUnknownOrMixedTemporary($callArgProbe)
                            || $this->newCtorDeadTempMayBindStmtBeforeArray(
                                $callArgProbe,
                                $callOp,
                                $argIndex,
                                $block
                            )
                        );
                    if (
                        $i === $callIndex - 1
                        && (
                            $this->operandsReferToSameVariable($child->result, $callArgProbe)
                            || $this->operandsReferToSameVariable($child->result, $arg)
                            || (
                                $deadTempWantsArray
                                && !$this->inlineArrayLiteralStmtBeforeOverriddenBySiblingCallProducer(
                                    $callOp,
                                    $argIndex,
                                    $block
                                )
                            )
                        )
                    ) {
                        // array_map(null, [[..]]) — stmt-before Array_ is haystack arg #1, not null callback (#15976).
                        if (
                            0 === $argIndex
                            && $this->arrayMapNullCallbackPrecedesInlineHaystack($callOp, $block)
                        ) {
                            continue;
                        }
                        // array_merge((object)[...], [...]) — trailing Array_ is arg #1, not arg #0 (#15858).
                        if (
                            0 === $argIndex
                            && $this->callArgIsDeadInlineTemporary($callArgProbe)
                            && $this->callArgOperandExpectsArrayProducer($callArgProbe)
                            && $this->inlineCallArgZeroFedByHoistedCastProducer($cfgChildren, $callOp)
                        ) {
                            continue;
                        }

                        return $child;
                    }
                    if (
                        $this->operandsReferToSameVariable($child->result, $arg)
                        && $this->callArgOperandExpectsArrayProducer($arg)
                    ) {
                        return $child;
                    }
                    continue;
                }
            }
        }
        $producers = $this->precedingInlineCallArgProducersBeforeCfgOp($cfgChildren, $callOp);
        if ($this->producersIncludeInlineArrayUnionPlus($producers)) {
            // Array union — Plus.result is the call arg, not a hoisted Array_ (#10490, #13787).
            return null;
        }
        if (
            ($this->callIncludesNamedParameter($callOp) || null !== $this->callArgName($callOp->args[$argIndex] ?? $arg))
            && isset($callOp->args[$argIndex])
        ) {
            $namedCallArg = $callOp->args[$argIndex];
            foreach ($producers as $candidate) {
                if (
                    $candidate instanceof Op\Expr\Array_
                    && null !== $candidate->result
                    && $this->operandsReferToSameVariable($candidate->result, $namedCallArg)
                    && $this->callArgOperandExpectsArrayProducer($namedCallArg)
                ) {
                    return $candidate;
                }
            }
            if ($this->callArgIsDeadInlineTemporary($namedCallArg)) {
                $unassigned = $this->findUnassignedInlineArrayProducerForDeadCallArg(
                    $producers,
                    $callOp,
                    $argIndex,
                    $block
                );
                if (
                    $this->inlineCallArgProducerUsesExprResultSlot($unassigned)
                    && $unassigned instanceof Op\Expr\Array_
                    && $this->callArgOperandExpectsArrayProducer($namedCallArg)
                ) {
                    return $unassigned;
                }
            }
        }
        $positionalCallArg = $callOp->args[$argIndex] ?? $arg;
        if (
            $this->callArgIsDeadInlineTemporary($positionalCallArg)
            && $this->callArgOperandExpectsArrayProducer($positionalCallArg)
        ) {
            // array_combine(array_keys(...), [...]) — sibling FuncCall feeds arg #0, not trailing Array_ (#15558, #15857).
            $arrayCombinePair = 'array_combine' === $this->resolveCfgFuncCallName($callOp)
                && 2 === \count($callOp->args ?? [])
                ? $this->matchArrayCombineInlineProducers($producers, $argIndex)
                : null;
            if (
                $arrayCombinePair instanceof Op\Expr\FuncCall
                || $arrayCombinePair instanceof Op\Expr\NsFuncCall
            ) {
                return null;
            }
            if ($arrayCombinePair instanceof Op\Expr\Array_) {
                return $arrayCombinePair;
            }
            // array_merge((object)[...], [...]) — Cast feeds arg #0, not trailing Array_ (#15207, #15858).
            if (
                0 === $argIndex
                && \in_array(
                    $this->resolveCfgFuncCallName($callOp),
                    [
                        'array_merge',
                        'array_merge_recursive',
                        'array_replace',
                        'array_replace_recursive',
                        'array_diff',
                        'array_intersect',
                        'array_diff_key',
                        'array_intersect_key',
                    ],
                    true
                )
            ) {
                foreach ($producers as $producer) {
                    if ($producer instanceof Op\Expr\Cast) {
                        return null;
                    }
                }
            }
            $directUnary = $this->matchDirectResultInlineCallArgProducer($producers, $positionalCallArg);
            if ($directUnary instanceof Op\Expr\Cast) {
                return null;
            }
            // array_reverse([...], true) — nested FuncCall feeds the dead temp, not hoisted Array_ (#14042).
            $directCall = $this->matchDirectResultInlineCallArgProducer($producers, $positionalCallArg);
            if (
                $directCall instanceof Op\Expr\FuncCall
                || $directCall instanceof Op\Expr\NsFuncCall
                || $directCall instanceof Op\Expr\StaticCall
                || $directCall instanceof Op\Expr\MethodCall
            ) {
                if (
                    'array_combine' === $this->resolveCfgFuncCallName($callOp)
                    && 0 === $argIndex
                    && null !== $this->matchArrayCombineInlineProducers($producers, $argIndex)
                ) {
                    return null;
                }
                if ($this->callArgOperandExpectsArrayProducer($positionalCallArg)) {
                    // array_slice([..], array_search(...)) — sibling FuncCall prelude must not block Array_ (#13684).
                    $nestedTrailing = $this->splitNestedArrayLiteralChainWithTrailingProducers($producers);
                    if (null !== $nestedTrailing) {
                        [$arrayChain, $trailing] = $nestedTrailing;
                        if (1 + \count($trailing) === \count($callOp->args) && 0 === $argIndex) {
                            $outer = $arrayChain[\count($arrayChain) - 1] ?? null;
                            if ($outer instanceof Op\Expr\Array_) {
                                return $outer;
                            }
                        }
                    }
                    $arrayProducers = array_values(array_filter(
                        $producers,
                        static fn (Op\Expr $p): bool => $p instanceof Op\Expr\Array_
                    ));
                    if ([] !== $arrayProducers && 0 === $argIndex) {
                        if (
                            'array_keys' === $this->resolveCfgFuncCallName($callOp)
                            && !$this->callArgIsCoalesceMergeProducer($positionalCallArg, $block, $callOp, $argIndex)
                        ) {
                            $keysArray = $this->inlineArrayProducerForArrayKeysDeadCallArg(
                                $positionalCallArg,
                                $block,
                                $callOp
                            );
                            if ($keysArray instanceof Op\Expr\Array_) {
                                return $keysArray;
                            }
                        }
                        if ('array_combine' === $this->resolveCfgFuncCallName($callOp)) {
                            $combineMatch = $this->matchArrayCombineInlineProducers($producers, $argIndex);
                            if ($combineMatch instanceof Op\Expr\FuncCall || $combineMatch instanceof Op\Expr\NsFuncCall) {
                                return null;
                            }
                        }
                        if (
                            \in_array(
                                strtolower($this->resolveCfgFuncCallName($callOp) ?? ''),
                                ['array_merge', 'array_merge_recursive', 'array_replace', 'array_replace_recursive'],
                                true
                            )
                            && \count($callOp->args ?? []) >= 2
                        ) {
                            $mergeProducers = $this->arrayMergeFamilyInlineProducersForCfgCall($cfgChildren, $callOp);
                            $mergeMapped = $this->matchArrayMergeFuncCallAndArrayInlineProducers($mergeProducers, $argIndex);
                            if (null === $mergeMapped) {
                                $mergeMapped = $this->matchArrayMergeFamilyFullInlineCallArgProducer(
                                    $mergeProducers,
                                    $argIndex,
                                    \count($callOp->args ?? []),
                                    $callOp->args ?? []
                                );
                            }
                            if (
                                $mergeMapped instanceof Op\Expr\FuncCall
                                || $mergeMapped instanceof Op\Expr\NsFuncCall
                            ) {
                                return null;
                            }
                            if ($mergeMapped instanceof Op\Expr\Array_) {
                                return $mergeMapped;
                            }
                        }
                        return $arrayProducers[\count($arrayProducers) - 1];
                    }
                }
                $embedded = $this->unwrapArrayLiteralExpr($positionalCallArg);
                if (null === $embedded) {
                    $embeddedProducer = $this->findCfgProducerExprForOperand($positionalCallArg);
                    if ($embeddedProducer instanceof Op\Expr\Array_) {
                        $embedded = $embeddedProducer;
                    }
                }
                if ($embedded instanceof Op\Expr\Array_) {
                    return $embedded;
                }

                if ($this->inlineCallArgProducerFeedsCallArgOp($directCall, $callOp, $positionalCallArg)) {
                    return null;
                }

                return null;
            }
            if (
                \in_array(
                    $this->resolveCfgFuncCallName($callOp),
                    [
                        'array_merge',
                        'array_merge_recursive',
                        'array_replace',
                        'array_replace_recursive',
                    ],
                    true
                )
                && \count($callOp->args ?? []) >= 2
            ) {
                $mergeProducers = $this->arrayMergeFamilyInlineProducersForCfgCall($cfgChildren, $callOp);
                $mergeMapped = $this->matchArrayMergeFamilyFullInlineCallArgProducer(
                    $mergeProducers,
                    $argIndex,
                    \count($callOp->args ?? []),
                    $callOp->args ?? []
                );
                if ($mergeMapped instanceof Op\Expr\Array_) {
                    return $mergeMapped;
                }
            }
            $unassigned = $this->findUnassignedInlineArrayProducerForDeadCallArg(
                $producers,
                $callOp,
                $argIndex,
                $block
            );
            if ($unassigned instanceof Op\Expr\Array_) {
                return $unassigned;
            }
            if (0 === $argIndex) {
                $nestedTrailing = $this->splitNestedArrayLiteralChainWithTrailingProducers($producers);
                if (null !== $nestedTrailing) {
                    [$arrayChain, $trailing] = $nestedTrailing;
                    if (
                        1 + \count($trailing) === \count($callOp->args)
                        && !$this->arrayMapNullCallbackPrecedesInlineHaystack($callOp, $block)
                        && !($trailing[0] ?? null) instanceof Op\Expr\New_
                    ) {
                        $outer = $arrayChain[\count($arrayChain) - 1] ?? null;
                        if ($outer instanceof Op\Expr\Array_) {
                            return $outer;
                        }
                    }
                }
                $arrayProducers = array_values(array_filter(
                    $producers,
                    static fn (Op\Expr $p): bool => $p instanceof Op\Expr\Array_
                ));
                if ([] !== $arrayProducers && !$this->arrayMapNullCallbackPrecedesInlineHaystack($callOp, $block)) {
                    if (
                        'array_combine' === $this->resolveCfgFuncCallName($callOp)
                        && 0 === $argIndex
                    ) {
                        $combineMatch = $this->matchArrayCombineInlineProducers($producers, $argIndex);
                        if ($combineMatch instanceof Op\Expr\FuncCall || $combineMatch instanceof Op\Expr\NsFuncCall) {
                            return null;
                        }
                    }
                    // attachIterator(new ArrayIterator([...]), …) — Array_ feeds inner ctor, not arg #0 (#13342, #13685).
                    $lastArray = $arrayProducers[\count($arrayProducers) - 1];
                    $lastIdx = array_search($lastArray, $producers, true);
                    if (
                        false !== $lastIdx
                        && ($producers[$lastIdx + 1] ?? null) instanceof Op\Expr\New_
                    ) {
                        return null;
                    }
                    return $arrayProducers[\count($arrayProducers) - 1];
                }
            }
        }
        $producer = $this->matchInlineCallArgProducer($producers, $callOp->args, $argIndex, $callOp, $block);
        if ($producer instanceof Op\Expr\Array_) {
            $producerIdx = array_search($producer, $producers, true);
            if (
                false !== $producerIdx
                && ($producers[$producerIdx + 1] ?? null) instanceof Op\Expr\New_
            ) {
                return null;
            }
            if (0 === $argIndex && !$this->callIncludesNamedParameter($callOp)) {
                $arrayProducers = array_values(array_filter(
                    $producers,
                    static fn (Op\Expr $p): bool => $p instanceof Op\Expr\Array_
                ));
                if (
                    \count($arrayProducers) >= 2
                    && $this->producersAreNestedArrayLiteralChain($arrayProducers)
                    && $this->arrayProducersFormNestedChain($arrayProducers)
                ) {
                    return $arrayProducers[\count($arrayProducers) - 1];
                }
            }

            $callArg = $callOp->args[$argIndex] ?? $arg;
            if (
                null !== $callArg
                && !$this->callArgOperandExpectsArrayProducer($callArg)
            ) {
                $outerArray = $this->matchOutermostNestedInlineArrayProducerForArgZero(
                    $producers,
                    $argIndex,
                    \count($callOp->args),
                    \count($producers)
                );
                if (null !== $outerArray) {
                    return $outerArray;
                }
                // var_export(current([1,2]), true) — arg #0 is FuncCall result, not ephemeral Array_ (#10654).
                return null;
            }

            return $producer;
        }

        $callArg = $callOp->args[$argIndex] ?? $arg;
        if ($callArg instanceof Operand && $this->callArgOperandExpectsArrayProducer($callArg)) {
            $embedded = $this->unwrapArrayLiteralExpr($callArg);
            if (null === $embedded) {
                $embeddedProducer = $this->findCfgProducerExprForOperand($callArg);
                if ($embeddedProducer instanceof Op\Expr\Array_) {
                    $embedded = $embeddedProducer;
                }
            }
            if ($embedded instanceof Op\Expr\Array_) {
                return $embedded;
            }
        }

        return null;
    }

    /**
     * php-cfg dead call-arg temps for named parameters — map to hoisted Array_ not assigned to a named local (#11170).
     *
     * @param list<Op\Expr> $producers
     */
    private function findUnassignedInlineArrayProducerForDeadCallArg(
        array $producers,
        Op $callOp,
        int $argIndex,
        Block $block
    ): ?Op\Expr {
        if (!property_exists($callOp, 'args') || !is_array($callOp->args)) {
            return null;
        }
        $deadArrayArgIndices = [];
        foreach ($callOp->args as $idx => $callArg) {
            if (!$this->callArgIsDeadInlineTemporary($callArg) || $this->isEmbeddedCallLiteralArg($callArg)) {
                continue;
            }
            if ($this->callArgOperandExpectsArrayProducer($callArg)) {
                $deadArrayArgIndices[] = (int) $idx;
            }
        }
        $positionAmongDeadArrays = array_search($argIndex, $deadArrayArgIndices, true);
        if (false === $positionAmongDeadArrays) {
            return null;
        }
        $unassigned = [];
        foreach ($producers as $producer) {
            if (!$producer instanceof Op\Expr\Array_) {
                continue;
            }
            if ($this->inlineProducerAssignedToNamedLocalBeforeCall($producer, $callOp, $block)) {
                continue;
            }
            $unassigned[] = $producer;
        }
        if ([] === $unassigned) {
            return null;
        }
        if (1 === \count($deadArrayArgIndices)) {
            $immediate = $this->inlineArrayProducerImmediatelyBeforeCfgCall($callOp, $block);
            if ($immediate instanceof Op\Expr\Array_) {
                return $immediate;
            }

            return $unassigned[\count($unassigned) - 1];
        }
        // Nested / sibling inline Array_ chains — flat unassigned[] index is wrong (#12729, #12730).
        $matched = $this->matchInlineCallArgProducer($producers, $callOp->args, $argIndex, $callOp, $block);
        if (
            $matched instanceof Op\Expr\FuncCall
            || $matched instanceof Op\Expr\NsFuncCall
            || $matched instanceof Op\Expr\StaticCall
            || $matched instanceof Op\Expr\MethodCall
            || $matched instanceof Op\Expr\Cast
        ) {
            return $matched;
        }
        if ($this->inlineCallArgProducerUsesExprResultSlot($matched)) {
            return $matched;
        }

        return $unassigned[$positionAmongDeadArrays] ?? null;
    }

    /** Hoisted inline call-arg producers whose Expr::result is the callee operand (#10490, #12763). */
    private function inlineCallArgProducerUsesExprResultSlot(?Op\Expr $matched): bool
    {
        return $matched instanceof Op\Expr\Cast
            || $matched instanceof Op\Expr\BooleanNot
            || $matched instanceof Op\Expr\BitwiseNot
            || $matched instanceof Op\Expr\Array_
            || $matched instanceof Op\Expr\BinaryOp\Plus
            || $matched instanceof Op\Expr\BinaryOp\Concat
            || $this->isComparisonInlineCallArgProducer($matched);
    }

    /**
     * Hoisted Array_ preludes followed by Plus — inline array union call arg (#10490, #13787).
     *
     * @param list<Op\Expr> $producers
     */
    private function producersIncludeInlineArrayUnionPlus(array $producers): bool
    {
        $seenArray = false;
        foreach ($producers as $producer) {
            if ($producer instanceof Op\Expr\Array_) {
                $seenArray = true;
            } elseif ($seenArray && $producer instanceof Op\Expr\BinaryOp\Plus) {
                return true;
            }
        }

        return false;
    }

    /** True when hoisted producers before $callOp include array union / concat (#12763, re-#10578). */
    private function precedingInlineCallArgHasPlusOrConcatProducer(array $cfgChildren, Op $callOp): bool
    {
        foreach ($this->precedingInlineCallArgProducersBeforeCfgOp($cfgChildren, $callOp) as $producer) {
            if ($producer instanceof Op\Expr\BinaryOp\Plus
                || $producer instanceof Op\Expr\BinaryOp\Concat
            ) {
                return true;
            }
        }

        return false;
    }

    /**
     * Dead php-cfg call-arg temps that expect hoisted Array_ producers (#11586, #12730).
     *
     * @param Op\Expr\FuncCall|Op\Expr\NsFuncCall|Op $callOp
     */
    private function countDeadArrayInlineCallArgs(Op $callOp): int
    {
        if (!property_exists($callOp, 'args') || !is_array($callOp->args)) {
            return 0;
        }
        $count = 0;
        foreach ($callOp->args as $callArg) {
            if (!$this->callArgIsDeadInlineTemporary($callArg) || $this->isEmbeddedCallLiteralArg($callArg)) {
                continue;
            }
            if ($this->callArgOperandExpectsArrayProducer($callArg)) {
                ++$count;
            }
        }

        return $count;
    }

    /**
     * Named `command: [...]` style dead temps — last hoisted Array_ between call and prior Assign (#11170).
     */
    private function resolveNamedDeadTempArrayCallArgSlot(Op $callOp, Block $block): ?string
    {
        if (null === $block->orig) {
            return null;
        }
        $children = $block->orig->children;
        $callIndex = null;
        foreach ($children as $i => $child) {
            if ($child === $callOp) {
                $callIndex = $i;
                break;
            }
        }
        if (null === $callIndex) {
            return null;
        }
        $lastArray = null;
        for ($i = $callIndex - 1; $i >= 0; --$i) {
            $child = $children[$i];
            if ($child instanceof Op\Expr\Assign || $child instanceof Op\Expr\AssignRef) {
                break;
            }
            if ($child instanceof Op\Expr\Array_) {
                $lastArray = $child;
            }
        }
        if (null === $lastArray) {
            return null;
        }
        if (null === $block->slotForOperand($lastArray->result)) {
            foreach ($this->compileExpr($lastArray, $block) as $op) {
                $block->addOpCode($op);
            }
        }
        $slot = $block->slotForOperand($lastArray->result);

        return null !== $slot ? (string) $slot : null;
    }

    private function inlineProducerAssignedToNamedLocalBeforeCall(
        Op\Expr $producer,
        Op $callOp,
        Block $block
    ): bool {
        if (null === $block->orig || null === $producer->result) {
            return false;
        }
        $children = $block->orig->children;
        $producerIndex = null;
        $callIndex = null;
        foreach ($children as $i => $child) {
            if ($child === $producer) {
                $producerIndex = $i;
            }
            if ($child === $callOp) {
                $callIndex = $i;
            }
        }
        if (null === $producerIndex || null === $callIndex || $producerIndex >= $callIndex) {
            return false;
        }
        for ($i = $producerIndex + 1; $i < $callIndex; ++$i) {
            $stmt = $children[$i];
            if (
                $stmt instanceof Op\Expr\Assign
                && $this->operandsReferToSameVariable($stmt->expr, $producer->result)
                && $this->isNamedVariableOperand($stmt->var)
            ) {
                return true;
            }
        }

        return false;
    }

    /** Dead php-cfg call-arg temp whose inferred type is array-shaped (incl. `string[]`, #11170). */
    private function callArgOperandExpectsArrayProducer(Operand $callArg): bool
    {
        $root = $this->unwrapOperandChain($callArg);
        if (null === $root->type || !method_exists($root->type, 'toString')) {
            return false;
        }
        $repr = $root->type->toString();
        if ('array' === $repr) {
            return true;
        }
        if (str_ends_with($repr, '[]')) {
            return true;
        }
        // Union/intersection builtins (proc_open array|string, etc.) may pass inline Expr_Array (#13734).
        return (bool) preg_match('/\barray\b/', $repr);
    }

    /**
     * Dead ctor arg with unknown/mixed (or absent) type — #22390 `new C([...])` defaults.
     * Typed null/int/… must not use the stmt-before Array_ fallback (#22770).
     */
    private function callArgIsDeadUnknownOrMixedTemporary(Operand $callArg): bool
    {
        if (!$this->callArgIsDeadInlineTemporary($callArg)) {
            return false;
        }
        $root = $this->unwrapOperandChain($callArg);
        if (null === $root->type || !method_exists($root->type, 'toString')) {
            return true;
        }
        $repr = $root->type->toString();

        return \in_array($repr, ['unknown', 'mixed'], true);
    }

    /**
     * Whether a New_ dead arg may bind the immediate stmt-before Array_ (#22390).
     * Rejects typed non-array temps and args whose multi-arg producer match is not Array_ (#22770).
     */
    private function newCtorDeadTempMayBindStmtBeforeArray(
        Operand $callArg,
        Op $callOp,
        int $argIndex,
        Block $block
    ): bool {
        if (!$callOp instanceof Op\Expr\New_ || !$this->callArgIsDeadUnknownOrMixedTemporary($callArg)) {
            return false;
        }
        if (null === $block->orig || !\is_array($callOp->args) || \count($callOp->args) < 2) {
            return true;
        }
        $producers = $this->precedingInlineCallArgProducersBeforeCfgOp($block->orig->children, $callOp);
        if (\count($producers) < 2) {
            return true;
        }
        $matched = $this->matchInlineCallArgProducer(
            $producers,
            $callOp->args,
            $argIndex,
            $callOp,
            $block
        );

        return !$matched instanceof Op\Expr || $matched instanceof Op\Expr\Array_;
    }

    /**
     * Dead call-arg temp whose php-cfg type is unknown/mixed, fed by stmt-before Array_ of
     * ClassConstFetch values (enum cases). Typed int[]/string[] arrays already hit
     * {@see callArgOperandExpectsArrayProducer()}; enum-case arrays stay inferred:unknown so
     * ARG_SEND would otherwise steal the first ClassConstFetch (#19786).
     */
    private function callArgIsDeadUntypedInlineArrayOfClassConst(
        Operand $callArg,
        Op $cfgCallOp,
        Block $block,
        int $argIndex
    ): bool {
        if (!$this->callArgIsDeadInlineTemporary($callArg)) {
            return false;
        }
        if ($this->callArgOperandExpectsArrayProducer($callArg)) {
            return false;
        }
        $root = $this->unwrapOperandChain($callArg);
        if (null !== $root->type && method_exists($root->type, 'toString')) {
            $repr = $root->type->toString();
            if (!\in_array($repr, ['unknown', 'mixed'], true)) {
                return false;
            }
        }
        // Prefer the stmt-before Array_; with sibling flat literals the ClassConstFetch array
        // may be earlier (call_user_func_array([A::class, 'm'], [...]) — #27139).
        $array = $this->inlineArrayProducerImmediatelyBeforeCfgCall($cfgCallOp, $block);
        if (
            (!$array instanceof Op\Expr\Array_ || !$this->arrayLiteralHasClassConstFetchValue($array))
            && null !== $block->orig
        ) {
            $array = null;
            foreach ($this->precedingInlineCallArgProducersBeforeCfgOp(
                $block->orig->children,
                $cfgCallOp
            ) as $producer) {
                if (
                    $producer instanceof Op\Expr\Array_
                    && $this->arrayLiteralHasClassConstFetchValue($producer)
                ) {
                    $array = $producer;
                    break;
                }
            }
        }
        if (!$array instanceof Op\Expr\Array_ || !$this->arrayLiteralHasClassConstFetchValue($array)) {
            return false;
        }
        $argc = \count($cfgCallOp->args ?? []);
        if (1 === $argc) {
            return 0 === $argIndex;
        }
        if (null === $block->orig) {
            return false;
        }
        // Multi-arg: ClassConstFetch mapped to this arg is an Array_ element ⇒ arg is the Array_
        // (json_encode([E::A]); f([E::A], E::B) arg0). Bare E::A arg keeps ClassConstFetch wiring.
        // Trailing-enum ordinal fallback can also map that same array-element fetch onto a later
        // dead ConstFetch temp (http_build_query([E::A], '', '&', PHP_QUERY_RFC3986) — #23702);
        // only arg #0 is the enum-case array in that case.
        $fetches = $this->precedingCallArgClassConstFetchesBeforeCfgOp(
            $block->orig->children,
            $cfgCallOp,
            $block
        );
        $fetch = $this->precedingClassConstFetchForCallArgIndex($cfgCallOp, $argIndex, $fetches);
        if (!$fetch instanceof Op\Expr\ClassConstFetch || null === $fetch->result) {
            return 0 === $argIndex;
        }
        foreach ($array->values as $value) {
            if (null !== $value && $this->operandsReferToSameVariable($value, $fetch->result)) {
                return 0 === $argIndex;
            }
        }

        return false;
    }

    /** @param Op\Expr\Array_ $array */
    private function arrayLiteralHasClassConstFetchValue(Op\Expr\Array_ $array): bool
    {
        foreach ($array->values as $value) {
            if (null === $value) {
                continue;
            }
            $candidates = [$value, $this->unwrapOperandChain($value)];
            foreach ($candidates as $operand) {
                foreach ($operand->ops ?? [] as $op) {
                    if ($op instanceof Op\Expr\ClassConstFetch) {
                        return true;
                    }
                }
            }
        }

        return false;
    }

    /**
     * Dedicated array-producer ARG_SEND resolution — haystack-family builtins only (#15612, #14134).
     *
     * Skips mb_detect_order([...]) and other mutators that take a single inline array operand.
     * Multi-array set ops (array_diff/intersect/merge) wire every hoisted array operand (#15947).
     */
    private function shouldUseArrayProducerCallArgResolution(?Op $cfgCallOp, int $argIndex, ?string $calleeName): bool
    {
        if (null === $cfgCallOp || $argIndex < 0) {
            return false;
        }
        $callee = strtolower($calleeName ?? $this->resolveCfgFuncCallName($cfgCallOp) ?? '');

        if (\in_array($callee, [
            'in_array',
            'array_search',
            'array_key_exists',
            'key_exists',
            'array_column',
        ], true)) {
            return $argIndex >= 1;
        }

        return \in_array($callee, [
            'array_combine',
            'array_merge',
            'array_merge_recursive',
            'array_replace',
            'array_replace_recursive',
            'array_diff',
            'array_intersect',
            'array_diff_key',
            'array_intersect_key',
            'array_intersect_assoc',
            'array_diff_assoc',
            'array_udiff',
            'array_uintersect',
            'array_udiff_assoc',
            'array_uintersect_assoc',
            'array_udiff_uassoc',
            'array_uintersect_uassoc',
            'array_diff_uassoc',
            'array_intersect_uassoc',
            'array_diff_ukey',
            'array_intersect_ukey',
        ], true);
    }

    /** Dead array temp that needs haystack-family producer wiring (#15612), not embedded literal (#14134). */
    private function callArgUsesHaystackFamilyArrayProducerResolution(
        ?Op $cfgCallOp,
        int $argIndex,
        ?string $calleeName,
        Operand $arg
    ): bool {
        if ($this->callArgUnpack($arg)) {
            return false;
        }

        return $this->callArgIsDeadInlineTemporary($arg)
            && $this->callArgOperandExpectsArrayProducer($arg)
            && $this->shouldUseArrayProducerCallArgResolution($cfgCallOp, $argIndex, $calleeName);
    }

    /** Haystack-family dead inline temp — prefer dim-fetch / array producer slots over echo concat (#17000). */
    private function callArgIsDeadInlineHaystackFamilySlot(
        ?Op $cfgCallOp,
        int $argIndex,
        ?string $calleeName,
        Operand $arg
    ): bool {
        if ($this->callArgUnpack($arg)) {
            return false;
        }

        return null !== $cfgCallOp
            && $this->shouldUseArrayProducerCallArgResolution($cfgCallOp, $argIndex, $calleeName)
            && $this->callArgIsDeadInlineTemporary($arg);
    }

    /**
     * Stmt-level ?? must not supply slots for literal / hoisted scalar call args (#9225, #10380).
     */
    private function isCallArgUnrelatedToPriorStmtCoalesce(Operand $callArg): bool
    {
        if ($callArg instanceof Operand\Literal || $this->isEmbeddedCallLiteralArg($callArg)) {
            return true;
        }
        // php-cfg clones stmt-level ?? call-arg temps from inner ConstFetch/null operands (#11801).
        $cfgClone = $callArg instanceof Operand\Temporary;
        $root = $this->unwrapOperandChain($callArg);
        if ($root instanceof Op\Expr\ConstFetch) {
            $name = $this->staticNameFromOperand($root->name);
            if (null !== $name) {
                $lookup = strtolower($name);
                if (\in_array($lookup, ['true', 'false'], true)) {
                    return true;
                }
                if ('null' === $lookup) {
                    return !$cfgClone;
                }
                if (!$cfgClone && \PHPCompiler\ext\standard\StdlibConstants::hasCoreIntByName($lookup)) {
                    return true;
                }
            }
        }
        $vm = $this->vmVariableFromCfgLiteralOperand($callArg);
        if (null !== $vm && \in_array($vm->type, [
            Variable::TYPE_BOOLEAN,
            Variable::TYPE_INTEGER,
            Variable::TYPE_NULL,
        ], true)) {
            return !$cfgClone;
        }

        return false;
    }

    /** header() replace/response_code must not reuse stmt-level ?? slots (#1887, 005-SessionsWeb). */
    private function headerScalarCallArgMustUseDirectOperand(?string $calleeName, int $argIndex): bool
    {
        if (null === $calleeName || $argIndex < 1) {
            return false;
        }

        return 'header' === strtolower(ltrim($calleeName, '\\'));
    }

    /**
     * @return ?Op\Expr\BinaryOp\Coalesce
     */
    private function findCoalesceStmtForCallArg(Operand $arg, Block $block): ?Op\Expr\BinaryOp\Coalesce
    {
        foreach ($this->findEmbeddedCoalesces($arg) as $coalesce) {
            return $coalesce;
        }
        if (null === $block->orig) {
            return null;
        }
        foreach ($block->orig->children as $child) {
            if (
                $child instanceof Op\Expr\BinaryOp\Coalesce
                && ($child->result === $arg || $this->operandsReferToSameVariable($child->result, $arg))
            ) {
                if (!$this->isCallArgUnrelatedToPriorStmtCoalesce($arg)) {
                    return $child;
                }
            }
        }
        // php-cfg clones call-arg temps from stmt Coalesce result (#8766, #8902).
        foreach ($block->orig->children as $i => $child) {
            if (
                !($child instanceof Op\Expr\FuncCall || $child instanceof Op\Expr\NsFuncCall)
                || !property_exists($child, 'args')
                || !is_array($child->args)
            ) {
                continue;
            }
            $argMatches = false;
            $matchedCallArg = null;
            foreach ($child->args as $callArg) {
                if ($callArg === $arg || $this->operandsReferToSameVariable($callArg, $arg)) {
                    $argMatches = true;
                    $matchedCallArg = $callArg;
                    $root = $this->unwrapOperandChain($callArg);
                    if ($root instanceof Op\Expr\BinaryOp\Coalesce) {
                        return $root;
                    }
                    break;
                }
            }
            if (!$argMatches) {
                continue;
            }
            // Literal / unrelated call args must not pick up a prior stmt-level ?? (#9225, 009-FastCGIWeb).
            if (null !== $matchedCallArg && $this->isCallArgUnrelatedToPriorStmtCoalesce($matchedCallArg)) {
                continue;
            }
            for ($j = $i - 1; $j >= 0; --$j) {
                $prev = $block->orig->children[$j];
                if ($prev instanceof Op\Expr\BinaryOp\Coalesce) {
                    // php-cfg clones call-arg temps from stmt Coalesce.result (#8766, #8902, #9479).
                    if ($j === $i - 1) {
                        $ordinalCoalesce = $this->findStmtCoalesceForOrdinalCallArg(
                            $child,
                            $matchedCallArg,
                            $block
                        );
                        if (null !== $ordinalCoalesce) {
                            return $ordinalCoalesce;
                        }

                        return $prev;
                    }
                    if (
                        null !== $matchedCallArg
                        && (
                            $prev->result === $matchedCallArg
                            || $this->operandsReferToSameVariable($prev->result, $matchedCallArg)
                            || $this->operandsReferToSameVariable($prev->left, $matchedCallArg)
                        )
                    ) {
                        return $prev;
                    }
                    // php-cfg may lower later call-arg producers (e.g. var_export(..., true)) between ?? and FuncCall (#11601).
                    if ($this->onlyInlineCallArgProducersBetweenIndices($block->orig->children, $j, $i)) {
                        // Stmt-level ?? feeds arg #0 only; trailing hoisted true/false/null are unrelated (#13789).
                        $firstArg = $child->args[0] ?? null;
                        $feedsFirstArg = null === $matchedCallArg
                            || (
                                null !== $firstArg
                                && (
                                    $firstArg === $matchedCallArg
                                    || $this->operandsReferToSameVariable($firstArg, $matchedCallArg)
                                    || $this->operandsReferToSameVariable($prev->result, $matchedCallArg)
                                )
                            );
                        $feedsHaystackArg = false;
                        if (!$feedsFirstArg && null !== $matchedCallArg) {
                            $calleeLc = strtolower($this->resolveCfgFuncCallName($child) ?? '');
                            if (\in_array($calleeLc, ['in_array', 'array_search', 'array_key_exists'], true)) {
                                $haystackArg = $child->args[1] ?? null;
                                $feedsHaystackArg = null !== $haystackArg
                                    && $this->callArgOperandExpectsArrayProducer($haystackArg)
                                    && (
                                        $haystackArg === $matchedCallArg
                                        || $this->operandsReferToSameVariable($haystackArg, $matchedCallArg)
                                    );
                            }
                        }
                        if ($feedsFirstArg || $feedsHaystackArg) {
                            return $prev;
                        }
                    }
                    break;
                }
                if (
                    $prev instanceof Op\Expr\Assign
                    && $j > 0
                ) {
                    $maybeCoalesce = $block->orig->children[$j - 1];
                    if (
                        $maybeCoalesce instanceof Op\Expr\BinaryOp\Coalesce
                        && $this->isCoalesceAssignTail($prev, $maybeCoalesce)
                    ) {
                        // ??= expression value before call — php-cfg inserts Assign between Coalesce and FuncCall (#5337, #10898).
                        return $maybeCoalesce;
                    }
                }
                if ($prev instanceof Op\Expr\FuncCall || $prev instanceof Op\Expr\NsFuncCall) {
                    break;
                }
                if (!$prev instanceof Op\Expr || !$this->isInlineExprCallArgProducer($prev)) {
                    break;
                }
            }
        }

        return null;
    }

    /**
     * Nullsafe lowering splits CFG blocks; result slot lives on TYPE_NULLSAFE (#9732, #9171).
     *
     * @param Op\Expr\NullsafePropertyFetch|Op\Expr\NullsafeMethodCall $nullsafe
     */
    private function slotForNullsafeResult(Block $block, Op\Expr $nullsafe): ?int
    {
        $nullsafeId = spl_object_id($nullsafe);
        if (isset($this->nullsafeResultSlots[$nullsafeId])) {
            return $this->nullsafeResultSlots[$nullsafeId];
        }
        $slot = $block->slotForOperand($nullsafe->result);
        if (null !== $slot) {
            return $slot;
        }
        $seen = [];
        $queue = [$block];
        while ([] !== $queue) {
            $current = array_shift($queue);
            $id = spl_object_id($current);
            if (isset($seen[$id])) {
                continue;
            }
            $seen[$id] = true;
            foreach ($current->opCodes as $op) {
                if (OpCode::TYPE_NULLSAFE === $op->type) {
                    return $op->arg1;
                }
            }
            foreach ($current->parents as $parent) {
                $queue[] = $parent;
            }
        }

        return null;
    }

    private function slotForCoalesceResult(Block $block, Op\Expr\BinaryOp\Coalesce $coalesce): ?int
    {
        $coalesceId = spl_object_id($coalesce);
        if (isset($this->coalesceAssignLvalues[$coalesceId])) {
            $lvalueSlot = $block->slotForOperand($this->coalesceAssignLvalues[$coalesceId]);
            if (null !== $lvalueSlot) {
                return $lvalueSlot;
            }
        }
        if (isset($this->coalesceResultSlots[$coalesceId])) {
            return $this->coalesceResultSlots[$coalesceId];
        }
        $slot = $block->slotForOperand($coalesce->result);
        if (null !== $slot) {
            return $slot;
        }
        $seen = [];
        $queue = [$block];
        while ([] !== $queue) {
            $current = array_shift($queue);
            $id = spl_object_id($current);
            if (isset($seen[$id])) {
                continue;
            }
            $seen[$id] = true;
            foreach ($current->opCodes as $op) {
                if (OpCode::TYPE_COALESCE === $op->type) {
                    return $op->arg1;
                }
            }
            foreach ($current->parents as $parent) {
                $queue[] = $parent;
            }
        }

        return null;
    }

    private function compileCallArgCoalesceSlot(
        Operand $arg,
        Block $block,
        ?Op $cfgCallOp = null,
        ?int $argIndex = null
    ): ?int {
        if ($this->isCallArgUnrelatedToPriorStmtCoalesce($arg)) {
            return null;
        }
        if (
            null !== $cfgCallOp
            && null !== $argIndex
            && $this->headerScalarCallArgMustUseDirectOperand(
                $this->funcCallExprCalleeName($cfgCallOp),
                $argIndex
            )
        ) {
            return null;
        }
        if (
            null !== $cfgCallOp
            && null !== $argIndex
            && is_array($cfgCallOp->args ?? null)
            && isset($cfgCallOp->args[$argIndex])
            && $this->isCallArgUnrelatedToPriorStmtCoalesce($cfgCallOp->args[$argIndex])
        ) {
            return null;
        }
        $coalesce = $this->findCoalesceStmtForCallArg($arg, $block);
        if (null === $coalesce) {
            return null;
        }
        $coalesceSlot = $this->slotForCoalesceResult($block, $coalesce);
        if (null === $coalesceSlot) {
            $this->compileCoalesce($coalesce, $block);
            $coalesceSlot = $this->slotForCoalesceResult($block, $coalesce);
        }

        return $coalesceSlot;
    }

    private function resolvePropertyFetchCoalesceCallArgSlot(
        Op\Expr\PropertyFetch $producer,
        Op $callOp,
        Operand $arg,
        Block $block,
        ?int $argIndex = null
    ): ?int {
        if (!property_exists($callOp, 'args') || !is_array($callOp->args)) {
            return null;
        }
        foreach ($callOp->args as $callArg) {
            foreach ($this->findEmbeddedCoalesces($callArg) as $coalesce) {
                if ($this->findCoalescePropertyFetch($coalesce->left, $block) !== $producer) {
                    continue;
                }
                $coalesceSlot = $this->slotForCoalesceResult($block, $coalesce);
                if (null === $coalesceSlot) {
                    $this->compileCoalesce($coalesce, $block);
                    $coalesceSlot = $this->slotForCoalesceResult($block, $coalesce);
                }
                if (null !== $coalesceSlot) {
                    return $coalesceSlot;
                }
            }
            $root = $this->unwrapOperandChain($callArg);
            if (
                $root instanceof Op\Expr\BinaryOp\Coalesce
                && $this->findCoalescePropertyFetch($root->left, $block) === $producer
            ) {
                $coalesceSlot = $this->slotForCoalesceResult($block, $root);
                if (null === $coalesceSlot) {
                    $this->compileCoalesce($root, $block);
                    $coalesceSlot = $this->slotForCoalesceResult($block, $root);
                }
                if (null !== $coalesceSlot) {
                    return $coalesceSlot;
                }
            }
        }
        $coalesceStmt = $this->findCoalesceStmtForCallArg($arg, $block);
        if (
            null !== $coalesceStmt
            && $this->findCoalescePropertyFetch($coalesceStmt->left, $block) === $producer
        ) {
            return $this->compileCallArgCoalesceSlot($arg, $block, $callOp, $argIndex);
        }

        return null;
    }

    private function resolveArrayDimFetchCoalesceCallArgSlot(
        Op\Expr\ArrayDimFetch $producer,
        Op $callOp,
        Operand $arg,
        Block $block,
        ?int $argIndex = null
    ): ?int {
        if (!property_exists($callOp, 'args') || !is_array($callOp->args)) {
            return null;
        }
        foreach ($callOp->args as $callArg) {
            foreach ($this->findEmbeddedCoalesces($callArg) as $coalesce) {
                if ($this->findCoalesceArrayDimFetch($coalesce->left, $block) !== $producer) {
                    continue;
                }
                $coalesceSlot = $this->slotForCoalesceResult($block, $coalesce);
                if (null === $coalesceSlot) {
                    $this->compileCoalesce($coalesce, $block);
                    $coalesceSlot = $this->slotForCoalesceResult($block, $coalesce);
                }
                if (null !== $coalesceSlot) {
                    return $coalesceSlot;
                }
            }
            $root = $this->unwrapOperandChain($callArg);
            if (
                $root instanceof Op\Expr\BinaryOp\Coalesce
                && $this->findCoalesceArrayDimFetch($root->left, $block) === $producer
            ) {
                $coalesceSlot = $this->slotForCoalesceResult($block, $root);
                if (null === $coalesceSlot) {
                    $this->compileCoalesce($root, $block);
                    $coalesceSlot = $this->slotForCoalesceResult($block, $root);
                }
                if (null !== $coalesceSlot) {
                    return $coalesceSlot;
                }
            }
        }
        $coalesceStmt = $this->findCoalesceStmtForCallArg($arg, $block);
        if (
            null !== $coalesceStmt
            && $this->findCoalesceArrayDimFetch($coalesceStmt->left, $block) === $producer
        ) {
            return $this->compileCallArgCoalesceSlot($arg, $block, $callOp, $argIndex);
        }

        return null;
    }

    /**
     * @param list<Operand> $args
     */
    private function lowerEmbeddedCoalesceCallArgs(array $args, Block $block): void
    {
        foreach ($args as $arg) {
            foreach ($this->findEmbeddedCoalesces($arg) as $coalesce) {
                if (null === $this->slotForCoalesceResult($block, $coalesce)) {
                    $this->compileCoalesce($coalesce, $block);
                }
            }
            $stmtCoalesce = $this->findCoalesceStmtForCallArg($arg, $block);
            if (
                null !== $stmtCoalesce
                && null === $this->slotForCoalesceResult($block, $stmtCoalesce)
            ) {
                $this->compileCoalesce($stmtCoalesce, $block);
            }
        }
    }

    private function findInlineExprCallArgProducerSlot(Operand $arg, Block $block, ?Op $cfgCallOp = null): ?string
    {
        if (null === $block->orig) {
            return null;
        }
        $callSite = $this->findCfgCallSiteForArg($block->orig->children, $arg, $cfgCallOp);
        if (null === $callSite) {
            return null;
        }
        [$callOp, $argIndex] = $callSite;
        if (!property_exists($callOp, 'args') || !is_array($callOp->args)) {
            return null;
        }
        $callArg = $callOp->args[$argIndex] ?? null;
        if ($this->callArgIsDeadInlineTemporary($callArg)) {
            $immediatePropertySlot = $this->slotForImmediatePropertyOrMethodFetchBeforeCfgCall($block, $callOp);
            if (null !== $immediatePropertySlot) {
                return $immediatePropertySlot;
            }
        }
        if ($this->headerScalarCallArgMustUseDirectOperand($this->funcCallExprCalleeName($callOp), $argIndex)) {
            return null;
        }
        // Statement-level side-effect calls before f($local) are not inline arg producers (#11093, #11375).
        $namedLocalSlot = $this->namedLocalCallArgSlotIfBound($arg, $block, $callOp, $argIndex);
        if (null !== $namedLocalSlot) {
            return $namedLocalSlot;
        }
        // php-cfg may lower a boolean-producing inline Expr (e.g. `===`) to a distinct arg temp with
        // no dataflow edge, leaving the arg slot empty. Prefer the immediately preceding binary op
        // producer when its inferred type matches the arg (#9030).
        $callIndex = null;
        foreach ($block->orig->children as $i => $child) {
            if ($child === $callOp) {
                $callIndex = $i;
                break;
            }
        }
        if (null !== $callIndex && $callIndex > 0) {
            $producers = $this->precedingInlineCallArgProducersBeforeCfgOp($block->orig->children, $callOp);
            $arrayProducerCount = 0;
            foreach ($producers as $producer) {
                if ($producer instanceof Op\Expr\Array_) {
                    ++$arrayProducerCount;
                }
            }
            $funcCallProducerCount = 0;
            foreach ($producers as $producer) {
                if ($producer instanceof Op\Expr\FuncCall || $producer instanceof Op\Expr\NsFuncCall
                    || $producer instanceof Op\Expr\MethodCall || $producer instanceof Op\Expr\StaticCall) {
                    ++$funcCallProducerCount;
                }
            }
            if (
                null !== $cfgCallOp
                && $this->hasSiblingMultiArgInlineCallProducers($block, $callOp)
                && $this->callArgIsDeadInlineTemporary($callOp->args[$argIndex] ?? null)
                && !$this->nestedFuncCallFeedsDeadInlineCallArgZero($block, $callOp, $argIndex)
            ) {
                // var_dump(f(), g()) after an earlier sibling chain — ordinal wiring is resolveSiblingInlineCallArgProducerSlot (#16254).
                return null;
            }
            if ($arrayProducerCount >= 2 || $funcCallProducerCount >= 2
                || null !== $this->splitLeadingConstFetchWithArrayLiteralCallArg($producers)
                || null !== $this->splitLeadingConstFetchWithFuncCallCallArg($producers)
                || $this->producersAreSiblingCallWithHoistedScalarConstFetch($producers)
                || $this->producersAreSiblingArithmeticWithHoistedScalarConstFetch($producers)
                || $this->producersAreSiblingCallWithHoistedEnumConstFetch($producers)
                || $this->producersIncludeUnaryOffsetWithConstWhence($producers)) {
                $matched = null;
                if (
                    $this->callIncludesNamedParameter($callOp)
                    && isset($callOp->args[$argIndex])
                    && $this->callArgIsDeadInlineTemporary($callOp->args[$argIndex])
                ) {
                    $matched = $this->findUnassignedInlineArrayProducerForDeadCallArg(
                        $producers,
                        $callOp,
                        $argIndex,
                        $block
                    );
                }
                if (!$matched instanceof Op\Expr) {
                    $matched = $this->matchInlineCallArgProducer($producers, $callOp->args, $argIndex, $callOp, $block);
                }
                if ($matched instanceof Op\Expr\Array_) {
                    $outerArray = $this->matchOutermostNestedInlineArrayProducerForArgZero(
                        $producers,
                        $argIndex,
                        \count($callOp->args),
                        \count($producers)
                    );
                    if (null !== $outerArray) {
                        $matched = $outerArray;
                    }
                }
                if ($matched instanceof Op\Expr) {
                    if (null === $block->slotForOperand($matched->result)) {
                        foreach ($this->compileExpr($matched, $block) as $op) {
                            $block->addOpCode($op);
                        }
                    }
                    $slot = $this->slotForInlineCallArgProducerResult(
                        $block,
                        $matched,
                        $callOp,
                        $block->orig->children
                    );
                    if (null !== $slot) {
                        return $slot;
                    }
                }
            }
            // array_reverse([...], true) hoists Array_/ConstFetch preludes — still one nested FuncCall (#14042).
            if (1 === $funcCallProducerCount) {
                $matched = $this->matchInlineCallArgProducer($producers, $callOp->args, $argIndex, $callOp, $block);
                if ($matched instanceof Op\Expr\FuncCall || $matched instanceof Op\Expr\NsFuncCall
                    || $matched instanceof Op\Expr\StaticCall || $matched instanceof Op\Expr\MethodCall) {
                    $producerIndex = null;
                    foreach ($block->orig->children as $i => $child) {
                        if ($child === $matched) {
                            $producerIndex = $i;
                            break;
                        }
                    }
                    if (
                        null !== $producerIndex
                        && null !== $callIndex
                        && $this->statementLevelFuncCallBeforeHoistedSiblingChain(
                            $producerIndex,
                            $callIndex,
                            $block->orig->children
                        )
                    ) {
                        $matched = null;
                    }
                    if (
                        null !== $matched
                        && null !== $producerIndex
                        && null !== $callIndex
                        && $this->isAdjacentNestedFuncCallProducer($matched, $callOp, $producerIndex, $callIndex)
                    ) {
                        $slot = $this->slotForNestedFuncCallArrayConsumerProducer(
                            $block,
                            $matched,
                            $callOp,
                            $producerIndex,
                            $argIndex
                        );
                        if (null === $slot) {
                            $slot = $block->slotForOperand($matched->result);
                        }
                        if (null === $slot) {
                            foreach ($this->compileExpr($matched, $block) as $op) {
                                $block->addOpCode($op);
                            }
                            $slot = $this->slotForNestedFuncCallArrayConsumerProducer(
                                $block,
                                $matched,
                                $callOp,
                                $producerIndex,
                                $argIndex
                            ) ?? $block->slotForOperand($matched->result);
                        }
                        if (null !== $slot) {
                            return (string) $slot;
                        }
                    }
                }
            }
            if ($this->callIncludesNamedParameter($callOp) && [] !== $producers) {
                $matched = $this->matchInlineCallArgProducer($producers, $callOp->args, $argIndex, $callOp, $block);
                if ($matched instanceof Op\Expr) {
                    if (null === $block->slotForOperand($matched->result)) {
                        foreach ($this->compileExpr($matched, $block) as $op) {
                            $block->addOpCode($op);
                        }
                    }
                    $slot = $block->slotForOperand($matched->result);
                    if (null !== $slot) {
                        return (string) $slot;
                    }
                }
            }
            $ownProducer = $this->inlineProducerForHoistedCallArgIndex(
                $block->orig->children,
                $callOp,
                $callIndex,
                (int) $argIndex
            );
            if (null !== $ownProducer) {
