            $cfgChildren = $block->orig->children;
        }
        if ([] === $cfgChildren) {
            return null;
        }
        $callIndex = null;
        foreach ($cfgChildren as $i => $child) {
            if ($child === $cfgCallOp) {
                $callIndex = $i;
                break;
            }
        }
        if (!is_int($callIndex)) {
            return null;
        }
        $arrayCount = 0;
        for ($i = 0; $i < $callIndex; ++$i) {
            if (($cfgChildren[$i] ?? null) instanceof Op\Expr\Array_) {
                ++$arrayCount;
            }
        }
        if ($arrayCount < 1) {
