        }
        $stmtBefore = $this->inlineArrayProducerImmediatelyBeforeCfgCall($cfgCallOp, $block);
        if ($stmtBefore instanceof Op\Expr\Array_) {
            $stmtOrdinal = 0;
            for ($i = 0; $i < $callIndex; ++$i) {
                $child = $cfgChildren[$i] ?? null;
                if ($child instanceof Op\Expr\Array_) {
                    if ($child === $stmtBefore) {
