        }
        $offset = 0;
        for ($i = 0; $i < $cfgStart; ++$i) {
            if (($cfgChildren[$i] ?? null) instanceof Op\Expr\Array_) {
                ++$offset;
            }
        }

        return $offset;
    }

    /** Nth TYPE_INIT_ARRAY in pending emits + block — hoisted sibling array_keys() preludes (#16418). */
