            return null;
        }
        $cfgChildren = $this->inlineCallArgProducerCfgChildren($block);
        if ([] === $cfgChildren) {
            return null;
        }
        $callIndex = null;
        foreach ($cfgChildren as $i => $child) {
            if ($child === $callOp) {
                $callIndex = $i;
                break;
            }
        }
        if (null === $callIndex || $callIndex < 1) {
            return null;
        }
        for ($probe = $callIndex - 1; $probe >= 0; --$probe) {
            $prev = $cfgChildren[$probe] ?? null;
