        }
        if ($first >= $consumerIndex) {
            return null;
        }
        $firstChild = $cfgChildren[$first] ?? null;
        if (!$this->isSiblingInlineCallProducerExpr($firstChild)) {
            return null;
        }
        if (
            $this->stmtLevelNamedFuncCallPrecedesNestedInlineCallArgChain(
                $first,
                $consumerIndex,
                $cfgChildren
            )
        ) {
            ++$first;
            if ($first >= $consumerIndex) {
                return null;
            }
            $firstChild = $cfgChildren[$first] ?? null;
            if (!$this->isSiblingInlineCallProducerExpr($firstChild)) {
                return null;
            }
        }
        $consumer = $cfgChildren[$consumerIndex] ?? null;
        // fileperms(); sprintf('%o', …); substr(…, -N) — skip nested-only producers (#13616).
        while ($first + 1 < $consumerIndex && $consumer instanceof Op\Expr) {
            $chainChild = $cfgChildren[$first] ?? null;
            $nextChild = $cfgChildren[$first + 1] ?? null;
            $consumerArgCount = (
                property_exists($consumer, 'args')
                && is_array($consumer->args)
            ) ? \count($consumer->args) : 0;
            if (
                $chainChild instanceof Op\Expr
                && ($nextChild instanceof Op\Expr\FuncCall || $nextChild instanceof Op\Expr\NsFuncCall)
                && $this->isAdjacentNestedFuncCallProducer($chainChild, $nextChild, $first, $first + 1)
                && ($consumerIndex - $first) > $consumerArgCount
            ) {
                // array_intersect(f(g()), f(g())) — dual outer producers; do not skip past first f() (#16050, #16031).
                if (
                    $this->isSiblingMultiArgInlineCallConsumer($consumer)
                    && $consumerArgCount >= 2
                    && property_exists($consumer, 'args')
                    && \is_array($consumer->args)
                ) {
                    $outer = $this->outerSiblingInlineFuncCallProducers($first, $consumerIndex, $cfgChildren);
                    $hoistedArgCount = 0;
                    foreach ($consumer->args as $consumerArg) {
                        if (null !== $consumerArg && !$this->isEmbeddedCallLiteralArg($consumerArg)) {
                            ++$hoistedArgCount;
                        }
                    }
                    if (\count($outer) === $hoistedArgCount && $hoistedArgCount >= 2) {
                        break;
                    }
                }
                ++$first;
                continue;
            }
            break;
        }

        $consumer = $cfgChildren[$consumerIndex] ?? null;
        if ($this->isSiblingMultiArgInlineCallConsumer($consumer)) {
            $contiguousFirst = $this->firstContiguousHoistedFuncCallProducerForMultiArgConsumer(
                $consumerIndex,
                $consumer,
                $cfgChildren
            );
            if (null !== $contiguousFirst && $contiguousFirst < $first) {
                $hoistedArgCount = 0;
                if (property_exists($consumer, 'args') && \is_array($consumer->args)) {
                    foreach ($consumer->args as $consumerArg) {
                        if (null !== $consumerArg && !$this->isEmbeddedCallLiteralArg($consumerArg)) {
                            ++$hoistedArgCount;
                        }
                    }
                }
                if ($hoistedArgCount >= 2) {
                    $outerFromFirst = \count(
                        $this->outerSiblingInlineFuncCallProducers($first, $consumerIndex, $cfgChildren)
                    );
                    $outerFromContiguous = \count(
                        $this->outerSiblingInlineFuncCallProducers($contiguousFirst, $consumerIndex, $cfgChildren)
                    );
                    if (
                        $outerFromContiguous === $hoistedArgCount
                        && $outerFromFirst !== $hoistedArgCount
                    ) {
                        $first = $contiguousFirst;
                    }
                }
            }
        }

        return $first;
    }

    /**
     * var_dump(strlen($s), substr($s, 0, 2)) — N stmt-level FuncCalls before a multi-arg consumer (#16254).
     *
     * php-cfg hoists each arg producer as a sibling; statementLevelFuncCallBeforeHoistedSiblingChain would
     * otherwise trim strlen when substr sits between it and var_dump.
     *
     * @param list<Op> $cfgChildren
     */
    private function firstContiguousHoistedFuncCallProducerForMultiArgConsumer(
        int $consumerIndex,
        Op $consumer,
        array $cfgChildren
    ): ?int {
        if (
            !$this->isSiblingMultiArgInlineCallConsumer($consumer)
            || !property_exists($consumer, 'args')
            || !\is_array($consumer->args)
            || \count($consumer->args) < 2
        ) {
            return null;
        }
        $hoistedArgs = [];
        foreach ($consumer->args as $argIndex => $callArg) {
            if (null === $callArg || $this->isEmbeddedCallLiteralArg($callArg)) {
                continue;
            }
            if ($this->isByRefNamedCallArgExcludedFromSiblingProducerWiring($consumer, (int) $argIndex, $callArg)) {
                continue;
            }
            $hoistedArgs[] = $callArg;
        }
        if (
            \count($hoistedArgs) < 2
            || !$this->callArgsAreDistinctInlineTemporaries($hoistedArgs)
        ) {
            return null;
        }
        $hoistedArgCount = \count($hoistedArgs);
        $first = $consumerIndex - $hoistedArgCount;
        if ($first < 0) {
            return null;
        }
        for ($j = $first; $j < $consumerIndex; ++$j) {
            $child = $cfgChildren[$j] ?? null;
            if ($child instanceof Op\Expr\ConstFetch || $child instanceof Op\Expr\ClassConstFetch) {
                continue;
            }
            if ($child instanceof Op\Expr\Array_) {
                continue;
            }
            if ($this->isUnaryInlineSiblingCallArgExpr($child)) {
                continue;
            }
            if ($child instanceof Op\Expr\ArrowFunction
                || $child instanceof Op\Expr\Closure
                || $child instanceof Op\Expr\FirstClassCallable) {
                continue;
            }
            if ($child instanceof Op\Expr\New_ || $child instanceof Op\Expr\Clone_) {
                continue;
            }
            if ($child instanceof Op\Expr\Isset_ || $child instanceof Op\Expr\Empty_) {
                continue;
            }
            if (
                $child instanceof Op\Expr\PropertyFetch
                && $this->isPropertyFetchOnlyIssetVar($child, $cfgChildren[$j + 1] ?? null)
            ) {
                continue;
            }
            if (
                $child instanceof Op\Expr\ArrayDimFetch
                && $this->isArrayDimFetchOnlyIssetVar($child, $cfgChildren[$j + 1] ?? null)
            ) {
                continue;
            }
            if (
                $child instanceof Op\Expr\StaticPropertyFetch
                && $this->isStaticPropertyFetchOnlyIssetVar($child, $cfgChildren[$j + 1] ?? null)
            ) {
                continue;
            }
            if (!$this->isSiblingInlineCallProducerExpr($child)) {
                return null;
            }
        }
        $outer = $this->outerSiblingInlineFuncCallProducers($first, $consumerIndex, $cfgChildren);
        if (\count($outer) !== $hoistedArgCount) {
            return null;
        }

        return $first;
    }

    /** True when php-cfg hoisted ≥2 sibling FuncCall producers before a multi-arg consumer (#13671). */
    private function hasSiblingMultiArgInlineCallProducers(Block $block, Op $cfgCallOp): bool
    {
        if (null === $block->orig || !property_exists($cfgCallOp, 'args') || !is_array($cfgCallOp->args)) {
            return false;
        }
        if (\count($cfgCallOp->args) < 2) {
            return false;
        }
        $callIndex = $this->cfgCallOpIndex($block, $cfgCallOp);
        if (null === $callIndex) {
            return false;
        }
        $firstSibling = $this->firstSiblingInlineFuncCallProducerIndexImpl($callIndex, $block->orig->children);
        if (null === $firstSibling) {
            return false;
        }

        return ($callIndex - $firstSibling) >= 2;
    }

    /**
     * True when php-cfg hoisted ≥2 sibling inline New_ producers before a multi-arg ctor (#17524, re-#15124).
     * Trailing ClassConstFetch/ConstFetch/scalar option preludes are skipped (#19731, #19738).
     */
    private function hasSiblingMultiArgInlineNewProducers(Block $block, Op $cfgCallOp): bool
    {
        if (null === $block->orig || !property_exists($cfgCallOp, 'args') || !is_array($cfgCallOp->args)) {
            return false;
        }
        $args = $cfgCallOp->args;
        if (\count($args) < 2) {
            return false;
        }
        $siblingNews = $this->siblingInlineNewProducersBeforeCfgOp($block, $cfgCallOp);
        $newCount = \count($siblingNews);

        return $newCount >= 2 && $newCount <= \count($args);
    }

    /**
     * Positional sibling inline New_ → multi-arg ctor/call (#17524, re-#15124 / #14483).
     * Allows trailing ClassConstFetch/ConstFetch/scalar options after New_ producers (#19731, #19738).
     * Nested `new Outer(new Mid(new Inner), Mode::C)` must not map Mid/Inner onto the mode
     * arg or Outer arg #0 by ordinal alone — require the New_ to feed that call arg (#22007, #19770).
     *
     * @param list<Op\Expr> $producers
     * @param list<Operand|null> $callArgs
     */
    private function matchSiblingInlineNewCallArgProducer(
        array $producers,
        array $callArgs,
        int $argIndex
    ): ?Op\Expr\New_ {
        $producerCount = \count($producers);
        $argCount = \count($callArgs);
        if ($producerCount < 2) {
            return null;
        }
        foreach ($producers as $producer) {
            if (!$producer instanceof Op\Expr\New_) {
                return null;
            }
        }
        if ($producerCount < $argCount) {
            // new DatePeriod(new DateTime(...), new DateInterval(...), new DateTime(...), INCLUDE_END_DATE)
            for ($i = $producerCount; $i < $argCount; ++$i) {
                if ($this->callArgIsNewExpression($callArgs[$i] ?? null)) {
                    return null;
                }
            }
        } elseif ($producerCount !== $argCount) {
            return null;
        }
        if ($argIndex >= $producerCount) {
            return null;
        }
        $callArg = $callArgs[$argIndex] ?? null;
        if (null === $callArg || !$this->callArgIsDeadInlineTemporary($callArg)) {
            return null;
        }
        $matched = $producers[$argIndex] ?? null;
        if (!$matched instanceof Op\Expr\New_) {
            return null;
        }
        // Nested New_ chain (ParentIterator(RecursiveArrayIterator)) ≠ parallel sibling args (#22007).
        return $this->inlineNewProducerFeedsCallArg($matched, $callArg) ? $matched : null;
    }

    /**
     * Sibling inline New_ stmts immediately before $cfgCallOp (#17524).
     * Skips trailing ClassConstFetch/ConstFetch and scalar/flag option preludes
     * (#19731, #19735, #19738) — bitwise, arithmetic, unary, and casts.
     *
     * @return list<Op\Expr\New_>
     */
    private function siblingInlineNewProducersBeforeCfgOp(Block $block, Op $cfgCallOp): array
    {
        if (null === $block->orig || !property_exists($cfgCallOp, 'args') || !is_array($cfgCallOp->args)) {
            return [];
        }
        $callIndex = $this->cfgCallOpIndex($block, $cfgCallOp);
        if (null === $callIndex) {
            return [];
        }
        $producers = [];
        for ($i = $callIndex - 1; $i >= 0 && \count($producers) < \count($cfgCallOp->args); --$i) {
            $child = $block->orig->children[$i] ?? null;
            if ($this->isTrailingInlineNewCtorOptionPrelude($child)) {
                continue;
            }
            if (!$child instanceof Op\Expr\New_) {
                break;
            }
            array_unshift($producers, $child);
        }

        return $producers;
    }

    /**
     * Scalar / flag option prelude between sibling New_ args and outer ctor (#19731, #19738).
     * e.g. DatePeriod::INCLUDE_END_DATE, EXCLUDE_START_DATE|INCLUDE_END_DATE, or 1+2 / 1<<2 / -1.
     */
    private function isTrailingInlineNewCtorOptionPrelude(?Op $child): bool
    {
        if ($child instanceof Op\Expr\ConstFetch || $child instanceof Op\Expr\ClassConstFetch) {
            return true;
        }
        if (
            $child instanceof Op\Expr\UnaryMinus
            || $child instanceof Op\Expr\UnaryPlus
            || $child instanceof Op\Expr\BitwiseNot
            || $child instanceof Op\Expr\Cast
        ) {
            return true;
        }

        return $this->isArithmeticInlineCallArgProducer($child);
    }

    private function cfgCallOpIndex(Block $block, Op $cfgCallOp): ?int
    {
        if (null === $block->orig) {
            return null;
        }
        $callIndex = array_search($cfgCallOp, $block->orig->children, true);
        if (\is_int($callIndex)) {
            return $callIndex;
        }
        if (!property_exists($cfgCallOp, 'result') || null === $cfgCallOp->result) {
            return null;
        }
        foreach ($block->orig->children as $i => $child) {
            if (
                ($child instanceof Op\Expr\FuncCall || $child instanceof Op\Expr\NsFuncCall)
                && null !== $child->result
                && (
                    $child->result === $cfgCallOp->result
                    || $this->operandsReferToSameVariable($child->result, $cfgCallOp->result)
                )
            ) {
                return $i;
            }
        }

        return null;
    }

    /**
     * var_dump(f(), g()) at cfg index — hoisted sibling consumer, not an EXEC_RETURN emitter (#16254).
     *
     * @param list<Op> $cfgChildren
     */
    private function isMultiArgSiblingInlineCallConsumerAt(int $callIndex, array $cfgChildren): bool
    {
        $consumer = $cfgChildren[$callIndex] ?? null;
        if (!$consumer instanceof Op\Expr\FuncCall && !$consumer instanceof Op\Expr\NsFuncCall) {
            return false;
        }
        if (!\is_array($consumer->args ?? null) || \count($consumer->args) < 2) {
            return false;
        }
        $firstSibling = $this->firstSiblingInlineFuncCallProducerIndex($callIndex, $cfgChildren);
        if (null === $firstSibling) {
            return false;
        }

        return ($callIndex - $firstSibling) >= 2;
    }

    /** substr($s, 0, 2) hoisted sibling — trailing embedded literals add one EXEC_RETURN (#16254). */
    private function extraExecReturnOrdinalsForInlineFuncCallProducer(Op $child): int
    {
        if (!$child instanceof Op\Expr\FuncCall && !$child instanceof Op\Expr\NsFuncCall) {
            return 0;
        }
        if (!\is_array($child->args ?? null)) {
            return 0;
        }
        foreach ($child->args as $i => $arg) {
            if ($i > 0 && $this->isEmbeddedCallLiteralArg($arg)) {
                return 1;
            }
        }

        return 0;
    }

    /**
     * True when every CFG child between $fromExclusive and $toExclusive is true/false/null ConstFetch
     * (or ClassConstFetch). Used for importNode(...->item(0), true) chain deferral (#25702).
     *
     * @param list<Op> $cfgChildren
     */
    private function onlyScalarConstFetchPreludesBetween(
        int $fromExclusive,
        int $toExclusive,
        array $cfgChildren
    ): bool {
        if ($fromExclusive + 1 >= $toExclusive) {
            // Adjacent — not a ConstFetch-prelude pattern (require at least one scalar) (#25702).
            return false;
        }
        $sawScalar = false;
        for ($k = $fromExclusive + 1; $k < $toExclusive; ++$k) {
            $mid = $cfgChildren[$k] ?? null;
            if ($mid instanceof Op\Expr\ConstFetch) {
                $name = $this->staticNameFromOperand($mid->name);
                if (
                    null === $name
                    || !\in_array(strtolower($name), ['true', 'false', 'null'], true)
                ) {
                    return false;
                }
                $sawScalar = true;
                continue;
            }
            if ($mid instanceof Op\Expr\ClassConstFetch) {
                $sawScalar = true;
                continue;
            }

            return false;
        }

        return $sawScalar;
    }

    /**
     * Whether a MethodCall before trailing true/false/null ConstFetch actually feeds the multi-arg
     * consumer (live result usage or dead-temp call arg) — #25702 / #26458.
     *
     * Bare statement MethodCalls such as {@code $r->appendChild($a)} before
     * {@code $r->insertBefore($b, null)} share the ConstFetch-null CFG shape but must not be
     * treated as sibling arg producers (that deferred the append and dropped prior children).
     */
    private function methodCallFeedsMultiArgConsumerAcrossScalarConstFetch(
        Op\Expr\MethodCall $producer,
        Op $consumer
    ): bool {
        if (!\is_array($consumer->args ?? null) || \count($consumer->args) < 2) {
            return false;
        }
        if (null === $producer->result) {
            return false;
        }
        if (!empty($producer->result->usages)) {
            foreach ($producer->result->usages as $usage) {
                if ($usage === $consumer) {
                    return true;
                }
            }
        }
        // Dead-temp leaf (importNode(...->item(0), true) — #25702). php-cfg may use distinct
        // result/arg temporaries, so also accept a non-scalar-ConstFetch dead temp when this
        // MethodCall is the leaf before the ConstFetch prelude. Skip true/false/null ConstFetch
        // temps — those are not feeds from a prior stmt MethodCall such as appendChild (#26458).
        $sawNonScalarDeadTemp = false;
        foreach ($consumer->args as $arg) {
            if (!$this->callArgIsDeadInlineTemporary($arg)) {
                continue;
            }
            if ($this->callArgTemporaryIsHoistedTrueFalseNullConstFetch($arg)) {
                continue;
            }
            if ($this->operandsReferToSameVariable($producer->result, $arg)) {
                return true;
            }
            $sawNonScalarDeadTemp = true;
        }

        return $sawNonScalarDeadTemp && empty($producer->result->usages);
    }

    /** True when a call-arg Temporary is the hoisted true/false/null ConstFetch prelude (#26458). */
    private function callArgTemporaryIsHoistedTrueFalseNullConstFetch(?Operand $arg): bool
    {
        if (!$arg instanceof Operand\Temporary) {
            return false;
        }
        foreach ($arg->ops ?? [] as $embedded) {
            if (!$embedded instanceof Op\Expr\ConstFetch) {
                continue;
            }
            $name = $this->staticNameFromOperand($embedded->name);
            if (null !== $name && \in_array(strtolower($name), ['true', 'false', 'null'], true)) {
                return true;
            }
        }

        return false;
    }

    /**
     * php-cfg `var_dump($g(), $g())` hoists sibling FuncCall stmts before the consumer (#9463, #10981).
     * Compile each producer once with its own EXEC_RETURN slot before ARG_SEND wiring.
     */
    private function ensureDeferredSiblingInlineCallArgProducersCompiled(Block $block, Op $cfgCallOp): void
    {
        if (null === $block->orig || !property_exists($cfgCallOp, 'args') || !is_array($cfgCallOp->args)) {
            return;
        }
        $argCount = \count($cfgCallOp->args);
        $callIndex = null;
        foreach ($block->orig->children as $i => $child) {
            if ($child === $cfgCallOp) {
                $callIndex = $i;
                break;
            }
        }
        if (null === $callIndex) {
            return;
        }
        $cfgChildren = $block->orig->children;
        if (
            $argCount < 2
            && !(
                1 === $argCount
                && $callIndex >= 2
                && ($cfgChildren[$callIndex - 2] ?? null) instanceof Op\Expr
                && $this->isIifeHoistedFuncCallArgProducer(
                    $cfgChildren[$callIndex - 2],
                    $cfgCallOp,
                    $callIndex - 2,
                    $callIndex,
                    $cfgChildren
                )
            )
        ) {
            return;
        }
        if ($this->isSubstrNestedSprintfUnaryMinusPattern($cfgCallOp, $callIndex, $cfgChildren)) {
            $this->ensureSideEffectsBeforeSubstrNestedSprintfCompiled($block, $callIndex, $cfgChildren);
        }
        $firstSibling = $this->firstSiblingInlineFuncCallProducerIndex($callIndex, $block->orig->children);
        if (null === $firstSibling) {
            if (
                1 === $argCount
                && $callIndex >= 2
            ) {
                $producerIndex = $callIndex - 2;
                $producer = $cfgChildren[$producerIndex] ?? null;
                if (
                    $producer instanceof Op\Expr
                    && $this->isIifeHoistedFuncCallArgProducer(
                        $producer,
                        $cfgCallOp,
                        $producerIndex,
                        $callIndex,
                        $cfgChildren
                    )
                    && null === $block->slotForOperand($producer->result)
                ) {
                    $this->ensureStatementLevelSideEffectsBeforeChainStartCompiled(
                        $block,
                        $producerIndex,
                        $cfgChildren
                    );
                    $emitOps = [];
                    $prevForce = $this->forceDeferredSiblingCallReturnSlot;
                    $this->forceDeferredSiblingCallReturnSlot = true;
                    try {
                        foreach ($this->compileExpr($producer, $block) as $op) {
                            $emitOps[] = $op;
                        }
                    } finally {
                        $this->forceDeferredSiblingCallReturnSlot = $prevForce;
                    }
                    foreach ($emitOps as $op) {
                        $block->addOpCode($op);
                    }
                }
            }

            return;
        }
        $arrayPreludeChain = $this->siblingFuncCallChainHasArrayPrelude(
            $firstSibling,
            $callIndex,
            $block->orig->children
        );
        $siblingFuncCount = $this->countSiblingInlineFuncCallProducers(
            $firstSibling,
            $callIndex,
            $block->orig->children
        );
        if ($siblingFuncCount < 2) {
            // json_decode(str_repeat(...), true, 512, JSON_THROW_ON_ERROR) — lone hoisted FuncCall (#12009, #15441).
            $producers = $this->precedingInlineCallArgProducersBeforeCfgOp(
                $block->orig->children,
                $cfgCallOp
            );
            foreach ($producers as $producer) {
                $isFuncProducer = $producer instanceof Op\Expr\FuncCall
                    || $producer instanceof Op\Expr\NsFuncCall;
                $isMethodProducer = $producer instanceof Op\Expr\MethodCall
                    || $producer instanceof Op\Expr\StaticCall;
                if (!$isFuncProducer && !$isMethodProducer) {
                    continue;
                }
                if ($isFuncProducer && 'define' === strtolower($this->resolveCfgFuncCallName($producer) ?? '')) {
                    continue;
                }
                if ($isFuncProducer && $this->funcCallExprHasByRefMutatingSideEffects($producer)) {
                    continue;
                }
                $producerIndex = array_search($producer, $block->orig->children, true);
                if (!is_int($producerIndex)) {
                    continue;
                }
                if (
                    !$this->isNestedCallArgProducerSeparatedByConsumerLiteralPreludes(
                        $producer,
                        $cfgCallOp,
                        $producerIndex,
                        $callIndex,
                        $block->orig->children
                    )
                    && !$this->isIifeHoistedFuncCallArgProducer(
                        $producer,
                        $cfgCallOp,
                        $producerIndex,
                        $callIndex,
                        $block->orig->children
                    )
                    && !$this->isSiblingMultiArgFuncCallProducer(
                        $producer,
                        $cfgCallOp,
                        $producerIndex,
                        $callIndex,
                        $block->orig->children
                    )
                ) {
                    continue;
                }
                if (null !== $block->slotForOperand($producer->result)) {
                    break;
                }
                $this->ensureStatementLevelSideEffectsBeforeChainStartCompiled(
                    $block,
                    $producerIndex,
                    $block->orig->children
                );
                $emitOps = [];
                $prevForce = $this->forceDeferredSiblingCallReturnSlot;
                $this->forceDeferredSiblingCallReturnSlot = true;
                try {
                    foreach ($this->compileExpr($producer, $block) as $op) {
                        $emitOps[] = $op;
                    }
                } finally {
                    $this->forceDeferredSiblingCallReturnSlot = $prevForce;
                }
                foreach ($emitOps as $op) {
                    $block->addOpCode($op);
                }
                break;
            }

            return;
        }
        if ($this->callHasOnlyTrailingHoistedScalarConstFetchArgs($cfgCallOp, $block)) {
            return;
        }
        $contiguousFirst = $this->firstContiguousSiblingMultiArgProducerIndex(
            $callIndex,
            $cfgCallOp,
            $block->orig->children
        );
        if (null === $contiguousFirst) {
            $contiguousFirst = $firstSibling;
        } elseif ($arrayPreludeChain) {
            // array_diff_assoc(array_keys(), array_keys()) — Array_ between siblings, not a chain break (#16418).
            $contiguousFirst = $firstSibling;
        }
        $cfgChildren = $block->orig->children;
        // Include dead-temp MethodCall producers (createElement) that precede the contiguous
        // sibling chain for multi-arg MethodCall consumers (#25563).
        if (null !== $contiguousFirst) {
            for ($j = $contiguousFirst - 1; $j >= 0; --$j) {
                $prior = $cfgChildren[$j] ?? null;
                if (
                    $prior instanceof Op\Expr\MethodCall
                    && $this->methodCallDeadTempFeedsLaterMultiArgMethodCallInOps(
                        $prior,
                        $cfgChildren,
                        $j
                    )
                ) {
                    $contiguousFirst = $j;
                    continue;
                }
                break;
            }
        }
        $this->ensureStatementLevelSideEffectsBeforeChainStartCompiled(
            $block,
            $contiguousFirst,
            $cfgChildren
        );
        $execReturnCountAtChainStart = 0;
        foreach ($block->opCodes as $op) {
            if (OpCode::TYPE_FUNCCALL_EXEC_RETURN === $op->type && null !== $op->arg1) {
                ++$execReturnCountAtChainStart;
            }
        }
        for ($j = $contiguousFirst; $j < $callIndex; ++$j) {
            $producer = $cfgChildren[$j] ?? null;
            if (!$producer instanceof Op\Expr) {
                continue;
            }
            if (
                ($producer instanceof Op\Expr\FuncCall || $producer instanceof Op\Expr\NsFuncCall)
                && $this->funcCallExprHasByRefMutatingSideEffects($producer)
            ) {
                continue;
            }
            $isSib = $this->isSiblingMultiArgFuncCallProducer(
                $producer,
                $cfgCallOp,
                $j,
                $callIndex,
                $cfgChildren
            );
            $isCreate = $producer instanceof Op\Expr\MethodCall
                && $this->methodCallDeadTempFeedsLaterMultiArgMethodCallInOps(
                    $producer,
                    $cfgChildren,
                    $j
                );
            // Leaf MethodCall before trailing true/false/null ConstFetch multi-arg consumer (#25702).
            // Must feed the consumer (live usage or dead-temp arg) — not prior stmts like
            // appendChild before insertBefore($x, null) (#26458).
            if (
                !$isSib
                && $producer instanceof Op\Expr\MethodCall
                && $this->onlyScalarConstFetchPreludesBetween($j, $callIndex, $cfgChildren)
                && $this->isSiblingMultiArgInlineCallConsumer($cfgCallOp)
                && $this->methodCallFeedsMultiArgConsumerAcrossScalarConstFetch($producer, $cfgCallOp)
            ) {
                $isSib = true;
            }
            // Receiver MethodCall feeding a later MethodCall whose result feeds this consumer
            // (importNode(...->item(0), true) — #25702). Do not hoist getElements→item→appendChild()
            // statement chains ahead of a following multi-arg FuncCall (#25949, re-#23514/#25842).
            if (
                !$isSib
                && !$isCreate
                && $producer instanceof Op\Expr\MethodCall
                && null !== $producer->result
            ) {
                for ($k = $j + 1; $k < $callIndex; ++$k) {
                    $later = $cfgChildren[$k] ?? null;
                    if (
                        !($later instanceof Op\Expr\MethodCall)
                        || !property_exists($later, 'var')
                        || null === $later->var
                        || !$this->operandsReferToSameVariable($producer->result, $later->var)
                        || null === $later->result
                        || empty($later->result->usages)
                    ) {
                        continue;
                    }
                    foreach ($later->result->usages as $laterUsage) {
                        if ($laterUsage === $cfgCallOp) {
                            $isSib = true;
                            break 2;
                        }
                    }
                }
            }
            if (!$isSib && !$isCreate) {
                continue;
            }
            $siblingOrdinal = $this->siblingInlineFuncCallProducerOrdinal(
                $j,
                $contiguousFirst,
                $cfgChildren,
                $callIndex
            );
            $execReturnCountNow = 0;
            foreach ($block->opCodes as $op) {
                if (OpCode::TYPE_FUNCCALL_EXEC_RETURN === $op->type && null !== $op->arg1) {
                    ++$execReturnCountNow;
                }
            }
            if ($execReturnCountNow >= $execReturnCountAtChainStart + $siblingOrdinal + 1) {
                continue;
            }
            $emitOps = [];
            $prevForce = $this->forceDeferredSiblingCallReturnSlot;
            $this->forceDeferredSiblingCallReturnSlot = true;
            try {
                foreach ($this->compileExpr($producer, $block) as $op) {
                    $emitOps[] = $op;
                }
            } finally {
                $this->forceDeferredSiblingCallReturnSlot = $prevForce;
            }
            foreach ($emitOps as $op) {
                $block->addOpCode($op);
            }
        }
    }

    /**
     * hold(); in_array(..., ['a','b'], true) — stmt-level UDF then hoisted Array_ prelude only (#15422, #15609).
     *
     * @param list<Op> $cfgChildren
     */
    private function priorStmtLevelCallSeparatedByHoistedArrayPreludeOnly(
        int $producerIndex,
        int $consumerIndex,
        array $cfgChildren
    ): bool {
        if ($producerIndex >= $consumerIndex - 1) {
            return false;
        }
        $producer = $cfgChildren[$producerIndex] ?? null;
        if (!$producer instanceof Op\Expr\FuncCall && !$producer instanceof Op\Expr\NsFuncCall) {
            return false;
        }
        $consumer = $cfgChildren[$consumerIndex] ?? null;
        if (!$consumer instanceof Op\Expr\FuncCall && !$consumer instanceof Op\Expr\NsFuncCall) {
            return false;
        }
        if ($this->inlineCallArgProducerFeedsConsumer($producer, $consumer)) {
            return false;
        }
        // in_array(id('x'), ['x'], true) — dead-temp nested FuncCall + Array_/ConstFetch prelude
        // must EXEC_RETURN; do not treat as stmt-level void (#28891, re-#16013).
        if (
            $producer instanceof Op\Expr
            && (
                $this->isNestedCallArgProducerForConsumer(
                    $producer,
                    $consumer,
                    $producerIndex,
                    $consumerIndex,
                    $cfgChildren
                )
                || $this->isNestedCallArgProducerSeparatedByConsumerLiteralPreludes(
                    $producer,
                    $consumer,
                    $producerIndex,
                    $consumerIndex,
                    $cfgChildren
                )
            )
        ) {
            return false;
        }
        $hasArrayPrelude = false;
        for ($j = $producerIndex + 1; $j < $consumerIndex; ++$j) {
            $mid = $cfgChildren[$j] ?? null;
            if ($mid instanceof Op\Expr\Array_) {
                $hasArrayPrelude = true;
                continue;
            }
            if ($mid instanceof Op\Expr\ConstFetch || $mid instanceof Op\Expr\ClassConstFetch) {
                continue;
            }
            if ($this->isUnaryInlineSiblingCallArgExpr($mid)) {
                continue;
            }
            if ($this->isSiblingInlineCallProducerExpr($mid)) {
                return false;
            }

            return false;
        }

        return $hasArrayPrelude;
    }

    /** Void stmt-level call before hoisted Array_ consumer args — skip EXEC_RETURN slot (#15609). */
    private function stmtLevelVoidCallBeforeHoistedArrayConsumerPrelude(?Op $cfgCallOp, Block $block): bool
    {
        if (null === $cfgCallOp || null === $block->orig) {
            return false;
        }
        if (!$cfgCallOp instanceof Op\Expr\FuncCall && !$cfgCallOp instanceof Op\Expr\NsFuncCall) {
            return false;
        }
        $callIndex = null;
        foreach ($block->orig->children as $i => $child) {
            if ($child === $cfgCallOp) {
                $callIndex = $i;
                break;
            }
        }
        if (null === $callIndex) {
            return false;
        }
        $cfgChildren = $block->orig->children;
        for ($j = $callIndex + 1; $j < \count($cfgChildren); ++$j) {
            $next = $cfgChildren[$j] ?? null;
            if ($next instanceof Op\Expr\FuncCall || $next instanceof Op\Expr\NsFuncCall) {
                $callee = $this->resolveCfgFuncCallName($next);
                if (!\in_array(strtolower($callee ?? ''), ['in_array', 'array_search', 'array_key_exists'], true)) {
                    return false;
                }

                return $this->priorStmtLevelCallSeparatedByHoistedArrayPreludeOnly(
                    $callIndex,
                    $j,
                    $cfgChildren
                );
            }
            if ($next instanceof Op\Expr\Array_
                || $next instanceof Op\Expr\ConstFetch
                || $next instanceof Op\Expr\ClassConstFetch
                || $this->isUnaryInlineSiblingCallArgExpr($next)
            ) {
                continue;
            }

            return false;
        }

        return false;
    }

    /**
     * array_udiff(array_keys(...), array_keys(...), 'strcmp') after prior u* stmts — scan local array_keys (#16045).
     *
     * @param list<OpCode> $emitOps
     */
    private function resolveTrailingComparatorArrayKeysArgSlot(
        Block $block,
        Op $cfgCallOp,
        int $argIndex,
        int $callIndex,
        array &$emitOps = []
    ): ?int {
        if (null === $block->orig || !property_exists($cfgCallOp, 'args') || !\is_array($cfgCallOp->args)) {
            return null;
        }
        $callbackArgIndex = \count($cfgCallOp->args) - 1;
        if ($argIndex >= $callbackArgIndex) {
            return null;
        }
        $funcArgIndex = 0;
        $targetFuncArgIndex = null;
        foreach ($cfgCallOp->args as $i => $callArg) {
            if ($i >= $callbackArgIndex) {
                break;
            }
            if (
                $this->isEmbeddedCallLiteralArg($callArg)
                || $this->callArgIsDeadInlineTemporary($callArg)
            ) {
                if ($i === $argIndex) {
                    $targetFuncArgIndex = $funcArgIndex;
                    break;
                }
                ++$funcArgIndex;
            }
        }
        if (null === $targetFuncArgIndex) {
            return null;
        }
        $neededKeyCount = 0;
        foreach ($cfgCallOp->args as $i => $callArg) {
            if ($i >= $callbackArgIndex) {
                break;
            }
            if (
                $this->isEmbeddedCallLiteralArg($callArg)
                || $this->callArgIsDeadInlineTemporary($callArg)
            ) {
                ++$neededKeyCount;
            }
        }
        if ($neededKeyCount < 1) {
            return null;
        }
        $keysProducers = [];
        $cfgChildren = $block->orig->children;
        for ($j = $callIndex - 1; $j >= 0; --$j) {
            if (\count($keysProducers) >= $neededKeyCount) {
                break;
            }
            $child = $cfgChildren[$j] ?? null;
            if (
                ($child instanceof Op\Expr\FuncCall || $child instanceof Op\Expr\NsFuncCall)
                && 'array_keys' === strtolower($this->resolveCfgFuncCallName($child) ?? '')
            ) {
                array_unshift($keysProducers, $child);
                continue;
            }
            if ($child instanceof Op\Expr\Array_
                || $child instanceof Op\Expr\ConstFetch
                || $child instanceof Op\Expr\ClassConstFetch
                || $this->isUnaryInlineSiblingCallArgExpr($child)
                || $child instanceof Op\Expr\Assign
                || $child instanceof Op\Expr\AssignRef
            ) {
                continue;
            }
            if (
                ($child instanceof Op\Expr\FuncCall || $child instanceof Op\Expr\NsFuncCall)
                && $this->builtinUsesTrailingComparatorCallback($this->resolveCfgFuncCallName($child))
            ) {
                break;
            }
            break;
        }
        $producer = $keysProducers[$targetFuncArgIndex] ?? null;
        if (!$producer instanceof Op\Expr\FuncCall && !$producer instanceof Op\Expr\NsFuncCall) {
            return null;
        }
        // Compile every deferred sibling array_keys() before resolving slots — per-arg compile
        // leaves exec-return ordinals short for arg #0 (#16300, re-#14021).
        $prevForce = $this->forceDeferredSiblingCallReturnSlot;
        $this->forceDeferredSiblingCallReturnSlot = true;
        try {
            foreach ($keysProducers as $keysProducer) {
                if (
                    !($keysProducer instanceof Op\Expr\FuncCall || $keysProducer instanceof Op\Expr\NsFuncCall)
                    || null !== $block->slotForOperand($keysProducer->result)
                ) {
                    continue;
                }
                foreach ($this->compileExpr($keysProducer, $block) as $op) {
                    $emitOps[] = $op;
                }
            }
        } finally {
            $this->forceDeferredSiblingCallReturnSlot = $prevForce;
        }
        $operandSlot = $block->slotForOperand($producer->result);
        if (null !== $operandSlot) {
            return (int) $operandSlot;
        }
        $keysExecOrdinal = $this->slotForSiblingInlineFuncCallProducerExecReturnOrdinal(
            $block,
            $targetFuncArgIndex
        );
        if (null !== $keysExecOrdinal) {
            return $keysExecOrdinal;
        }
        $slot = $this->slotForInlineCallArgProducerResult($block, $producer, $cfgCallOp, $cfgChildren);

        return null !== $slot ? (int) $slot : null;
    }

    /**
     * php-cfg `f(g(), h())` — map arg N to the Nth sibling hoisted FuncCall producer (#9463, #10917).
     */
    private function resolveSiblingInlineCallArgProducerSlot(
        Block $block,
        Op $cfgCallOp,
        int $argIndex,
        array &$emitOps = []
    ): ?int {
        if (null === $block->orig || !property_exists($cfgCallOp, 'args') || !is_array($cfgCallOp->args)) {
            return null;
        }
        $argCount = \count($cfgCallOp->args);
        if ($argCount < 2 || $argIndex >= $argCount) {
            return null;
        }
        $callArg = $cfgCallOp->args[$argIndex] ?? null;
        if (
            $callArg instanceof Operand
            && $this->isByRefNamedCallArgExcludedFromSiblingProducerWiring($cfgCallOp, $argIndex, $callArg)
        ) {
            return null;
        }
        if ($this->callArgHasHoistedConstPrelude($cfgCallOp, $argIndex, $block)) {
            return null;
        }
        if ($callArg instanceof Operand) {
            $hoistedScalarSlot = $this->tryFoldHoistedBoolNullLiteralCallArg(
                $callArg,
                $block,
                $cfgCallOp,
                $argIndex
            );
            if (null !== $hoistedScalarSlot) {
                return $hoistedScalarSlot;
            }
        }
        $callIndex = null;
        foreach ($block->orig->children as $i => $child) {
            if ($child === $cfgCallOp) {
                $callIndex = $i;
                break;
            }
        }
        if (null === $callIndex) {
            return null;
        }
        $consumerName = $this->resolveCfgFuncCallName($cfgCallOp);
        if ($this->builtinUsesTrailingComparatorCallback($consumerName)) {
            $trailingKeysSlot = $this->resolveTrailingComparatorArrayKeysArgSlot(
                $block,
                $cfgCallOp,
                $argIndex,
                $callIndex,
                $emitOps
            );
            if (null !== $trailingKeysSlot) {
                return $trailingKeysSlot;
            }
        }
        $callbackArgIndex = $this->inlineClosureArrayPairCallbackArgIndex($consumerName);
        if ($callbackArgIndex >= 0 && 2 === $argCount) {
            $hasCallbackProducer = false;
            $hasHaystackFuncCall = false;
            for ($j = $callIndex - 1; $j >= 0; --$j) {
                $scan = $block->orig->children[$j] ?? null;
                if ($scan instanceof Op\Expr\ArrowFunction
                    || $scan instanceof Op\Expr\Closure
                    || $scan instanceof Op\Expr\FirstClassCallable) {
                    $hasCallbackProducer = true;
                }
                if ($scan instanceof Op\Expr\FuncCall || $scan instanceof Op\Expr\NsFuncCall) {
                    $hasHaystackFuncCall = true;
                }
            }
            if ($hasCallbackProducer && $hasHaystackFuncCall) {
                return null;
            }
        }
        $firstSibling = $this->firstSiblingInlineFuncCallProducerIndex($callIndex, $block->orig->children);
        if (null === $firstSibling) {
            if ($this->builtinUsesTrailingComparatorCallback($consumerName)) {
                return $this->resolveTrailingComparatorArrayKeysArgSlot(
                    $block,
                    $cfgCallOp,
                    $argIndex,
                    $callIndex,
                    $emitOps
                );
            }

            return null;
        }
        $outerSlot = $this->outerSiblingInlineCallArgProducerSlot($block, $cfgCallOp, $argIndex, $emitOps);
        if (null !== $outerSlot) {
            return (int) $outerSlot;
        }
        $arrayPreludeChain = $this->siblingFuncCallChainHasArrayPrelude(
            $firstSibling,
            $callIndex,
            $block->orig->children
        );
        if ($arrayPreludeChain) {
            $producerIndex = $this->siblingInlineFuncCallProducerIndexAtOrdinal(
                $argIndex,
                $firstSibling,
                $callIndex,
                $block->orig->children
            );
            if (null === $producerIndex) {
                $funcProducerCount = $this->countSiblingInlineFuncCallProducers(
                    $firstSibling,
                    $callIndex,
                    $block->orig->children
                );
                if ($argIndex >= $funcProducerCount) {
                    $preludeOrdinal = $argIndex - $funcProducerCount;
                    $seenPrelude = -1;
                    for ($j = $firstSibling + 1; $j < $callIndex; ++$j) {
                        $scan = $block->orig->children[$j] ?? null;
                        if (!$scan instanceof Op\Expr || $this->isSiblingInlineCallProducerExpr($scan)) {
                            continue;
                        }
                        if (
                            $scan instanceof Op\Expr\ConstFetch
                            || $scan instanceof Op\Expr\ClassConstFetch
                            || $scan instanceof Op\Expr\Array_
                        ) {
                            ++$seenPrelude;
                            if ($seenPrelude === $preludeOrdinal) {
                                if (null === $block->slotForOperand($scan->result)) {
                                    foreach ($this->compileExpr($scan, $block) as $op) {
                                        $emitOps[] = $op;
                                    }
                                }
                                $preludeSlot = $block->slotForOperand($scan->result);
                                if (null !== $preludeSlot) {
                                    return (string) $preludeSlot;
                                }
                            }
                        }
                    }
                }

                return null;
            }
            if (
                'array_pad' === strtolower($consumerName ?? '')
                && $this->priorStmtLevelCallSeparatedByHoistedArrayPreludeOnly(
                    $producerIndex,
                    $callIndex,
                    $block->orig->children
                )
            ) {
                return null;
            }
        } else {
            $producerIndex = null;
            for ($j = $firstSibling; $j < $callIndex; ++$j) {
                $scan = $block->orig->children[$j] ?? null;
                if (!$this->isSiblingInlineCallProducerExpr($scan) || !$scan instanceof Op\Expr) {
                    continue;
                }
                $targetArg = $this->siblingMultiArgFuncCallProducerTargetArgIndex(
                    $j,
                    $callIndex,
                    $block->orig->children
                );
                if (
                    $targetArg === $argIndex
                    && $this->isSiblingMultiArgFuncCallProducer(
                        $scan,
                        $cfgCallOp,
                        $j,
                        $callIndex,
                        $block->orig->children
                    )
                ) {
                    $producerIndex = $j;
                    break;
                }
            }
            if (null === $producerIndex) {
                $outerSlot = $this->outerSiblingInlineCallArgProducerSlot($block, $cfgCallOp, $argIndex, $emitOps);
                if (null !== $outerSlot) {
                    return (int) $outerSlot;
                }
                $siblingCount = $callIndex - $firstSibling;
                if ($siblingCount < 2 || $argIndex >= $siblingCount) {
                    return null;
                }
                $producerIndex = $firstSibling + $argIndex;
            }
        }
        $producer = $block->orig->children[$producerIndex] ?? null;
        if (!$this->isSiblingInlineCallProducerExpr($producer)) {
            return null;
        }
        if (!$this->isSiblingMultiArgFuncCallProducer(
            $producer,
            $cfgCallOp,
            $producerIndex,
            $callIndex,
            $block->orig->children
        )) {
            return null;
        }
        if ($this->siblingMultiArgFuncCallProducerTargetArgIndex(
            $producerIndex,
            $callIndex,
            $block->orig->children
        ) !== $argIndex) {
            return null;
        }
        $execReturnSlot = null;
        if (
            null !== $block->orig
            && (
                $producer instanceof Op\Expr\FuncCall
                || $producer instanceof Op\Expr\NsFuncCall
            )
        ) {
            $execReturnSlot = $this->slotForInlineFuncCallProducerExecReturnByCfgIndex(
                $block,
                $producerIndex,
                $block->orig->children
            );
        }
        if (
            null === $execReturnSlot
            && null !== $block->orig
            && (
                $producer instanceof Op\Expr\FuncCall
                || $producer instanceof Op\Expr\NsFuncCall
            )
        ) {
            $execReturnSlot = $this->slotForSiblingInlineCallProducerExecReturnByExpr(
                $block,
                $producer,
                $cfgCallOp,
                $block->orig->children
            );
        }
        // var_export($o->m(), true) — MethodCall EXEC_RETURN ordinal drifts past ctor NEW (#10778, #16794).
        if (
            $producer instanceof Op\Expr\MethodCall
            || $producer instanceof Op\Expr\StaticCall
        ) {
            if (null === $block->slotForOperand($producer->result)) {
                $prevForce = $this->forceDeferredSiblingCallReturnSlot;
                $this->forceDeferredSiblingCallReturnSlot = true;
                try {
                    foreach ($this->compileExpr($producer, $block) as $op) {
                        $emitOps[] = $op;
                    }
                } finally {
                    $this->forceDeferredSiblingCallReturnSlot = $prevForce;
                }
            }
            if (null !== $block->orig) {
                $methodExecSlot = $this->slotForSiblingMethodCallProducerExecReturn(
                    $block,
                    $producer,
                    $cfgCallOp,
                    $block->orig->children
                );
                if (null !== $methodExecSlot) {
                    return (int) $methodExecSlot;
                }
            }
            $operandSlot = $block->slotForOperand($producer->result);
            if (null !== $operandSlot) {
                return (int) $operandSlot;
            }
        }
        if (
            null === $execReturnSlot
            && (
                $producer instanceof Op\Expr\FuncCall
                || $producer instanceof Op\Expr\NsFuncCall
            )
        ) {
            $prevForce = $this->forceDeferredSiblingCallReturnSlot;
            $this->forceDeferredSiblingCallReturnSlot = true;
            try {
                foreach ($this->compileExpr($producer, $block) as $op) {
                    $emitOps[] = $op;
                }
            } finally {
                $this->forceDeferredSiblingCallReturnSlot = $prevForce;
            }
            if (
                null !== $block->orig
                && (
                    $producer instanceof Op\Expr\FuncCall
                    || $producer instanceof Op\Expr\NsFuncCall
                )
            ) {
                $execReturnSlot = $this->slotForInlineFuncCallProducerExecReturnByCfgIndex(
                    $block,
                    $producerIndex,
                    $block->orig->children
                );
            }
            if (null === $execReturnSlot && null !== $block->orig) {
                $execReturnSlot = $this->slotForSiblingInlineCallProducerExecReturnByExpr(
                    $block,
                    $producer,
                    $cfgCallOp,
                    $block->orig->children
                );
            }
        }
        if (null !== $execReturnSlot) {
            return (string) $execReturnSlot;
        }
        if ([] === $emitOps && $this->siblingConsumerHasTrailingByRefNamedLocal($cfgCallOp)) {
            $byRefNamedArg = $cfgCallOp->args[$argIndex] ?? null;
            if (
                !(
                    $byRefNamedArg instanceof Operand
                    && $this->isByRefNamedCallArgExcludedFromSiblingProducerWiring(
                        $cfgCallOp,
                        $argIndex,
                        $byRefNamedArg
                    )
                )
            ) {
                $execReturnSlot = $this->slotForSiblingInlineFuncCallProducerExecReturnOrdinal(
                    $block,
                    (int) $argIndex
                );
                if (null !== $execReturnSlot) {
                    return (string) $execReturnSlot;
                }
            }
        }

        return $block->slotForOperand($producer->result);
    }

    /**
     * similar_text($a, $b, $p) / preg_match(..., $m) — trailing by-ref named local (#15476).
     */
    private function siblingConsumerHasTrailingByRefNamedLocal(Op $cfgCallOp): bool
    {
        if (
            !($cfgCallOp instanceof Op\Expr\FuncCall || $cfgCallOp instanceof Op\Expr\NsFuncCall)
            || !property_exists($cfgCallOp, 'args')
            || !\is_array($cfgCallOp->args)
        ) {
            return false;
        }
        $argCount = \count($cfgCallOp->args);
        if ($argCount < 2) {
            return false;
        }
        for ($i = $argCount - 1; $i >= 0; --$i) {
            $arg = $cfgCallOp->args[$i] ?? null;
            if (!($arg instanceof Operand)) {
                break;
            }
            if ($this->isByRefNamedCallArgExcludedFromSiblingProducerWiring($cfgCallOp, $i, $arg)) {
                return true;
            }
            if (!$this->isEmbeddedCallLiteralArg($arg)) {
                return false;
            }
        }

        return false;
    }

    /**
     * Outer hoisted producer for a multi-arg dead inline call arg — CFG sibling order (#15488, #16280).
     *
     * @param list<Op> $cfgChildren
     */
    private function outerSiblingInlineCallArgProducerForArgIndex(
        Op $cfgCallOp,
        int $argIndex,
        int $firstSibling,
        int $callIndex,
        array $cfgChildren
    ): ?Op\Expr {
        if (!\is_array($cfgCallOp->args ?? null)) {
            return null;
        }
        $argCount = \count($cfgCallOp->args);
        $outer = $this->outerSiblingInlineFuncCallProducers($firstSibling, $callIndex, $cfgChildren);
        if (\count($outer) >= $argCount) {
            $outer = \array_slice($outer, -$argCount);
        }
        if (\count($outer) !== $argCount || $argIndex >= $argCount) {
            return null;
        }
        $callArg = $cfgCallOp->args[$argIndex] ?? null;
        if ($callArg instanceof Operand) {
            $direct = $this->matchDirectResultInlineCallArgProducer($outer, $callArg);
            if ($direct instanceof Op\Expr) {
                return $direct;
            }
        }
        $deadInlineTempCount = 0;
        foreach ($cfgCallOp->args as $deadArg) {
            if ($this->callArgIsDeadInlineTemporary($deadArg)) {
                ++$deadInlineTempCount;
            }
        }
        if ($deadInlineTempCount !== $argCount) {
            return null;
        }
        $leadingEmbedded = 0;
        foreach ($cfgCallOp->args as $embeddedArg) {
            if ($this->isEmbeddedCallLiteralArg($embeddedArg)) {
                ++$leadingEmbedded;
                continue;
            }
            break;
        }
        $outerOrdinal = $argIndex - $leadingEmbedded;
        if ($outerOrdinal < 0 || !isset($outer[$outerOrdinal])) {
            return null;
        }
        $outerProducer = $outer[$outerOrdinal];
        if (!$outerProducer instanceof Op\Expr) {
            return null;
        }

        return $outerProducer;
    }

    /**
     * FUNCCALL_EXEC_RETURN / operand slot for outer hoisted producer of a dead inline call arg (#16280).
     *
     * @param list<OpCode> $emitOps
     */
    private function outerSiblingInlineCallArgProducerExecReturnSlot(
        Block $block,
        Op $cfgCallOp,
        int $argIndex,
        ?array &$emitOps = null
    ): ?string {
        if (null === $block->orig || !\is_array($cfgCallOp->args ?? null)) {
            return null;
        }
        $callIndex = array_search($cfgCallOp, $block->orig->children, true);
        if (!\is_int($callIndex)) {
            return null;
        }
        $firstSibling = $this->firstSiblingInlineFuncCallProducerIndex($callIndex, $block->orig->children);
        if (null === $firstSibling) {
            return null;
        }
        $outerProducer = $this->outerSiblingInlineCallArgProducerForArgIndex(
            $cfgCallOp,
            $argIndex,
            $firstSibling,
            $callIndex,
            $block->orig->children
        );
        if (!$outerProducer instanceof Op\Expr || null === $outerProducer->result) {
            return null;
        }
        if (null === $block->slotForOperand($outerProducer->result)) {
            $prevForce = $this->forceDeferredSiblingCallReturnSlot;
            $this->forceDeferredSiblingCallReturnSlot = true;
            try {
                foreach ($this->compileExpr($outerProducer, $block) as $op) {
                    if (null !== $emitOps) {
                        $emitOps[] = $op;
                    } else {
                        $block->addOpCode($op);
                    }
                }
            } finally {
                $this->forceDeferredSiblingCallReturnSlot = $prevForce;
            }
        }
        $operandSlot = $block->slotForOperand($outerProducer->result);
        if (null !== $operandSlot) {
            return (string) $operandSlot;
        }
        $execReturn = $this->slotForInlineCallArgProducerResult(
            $block,
            $outerProducer,
            $cfgCallOp,
            $block->orig->children
        );

        return null !== $execReturn ? $execReturn : null;
    }

    /**
     * Nth hoisted sibling FuncCall producer's final EXEC_RETURN slot (#15476, #15848).
     */
    private function slotForSiblingInlineFuncCallProducerExecReturnOrdinal(Block $block, int $producerOrdinal): ?int
    {
        if ($producerOrdinal < 0) {
            return null;
        }
        $execReturnSlots = [];
        foreach ($block->opCodes as $op) {
            if (OpCode::TYPE_FUNCCALL_EXEC_RETURN === $op->type && null !== $op->arg1) {
                $execReturnSlots[] = (int) $op->arg1;
            }
        }
        if ($producerOrdinal >= \count($execReturnSlots)) {
            return null;
        }

        return $execReturnSlots[$producerOrdinal];
    }

    /**
     * @param list<OpCode> $pendingNestedProducerOps
     */
    private function slotForSiblingInlineFuncCallProducerExecReturnOrdinalWithPending(
        Block $block,
        int $producerOrdinal,
        array $pendingNestedProducerOps = []
    ): ?int {
        if ($producerOrdinal < 0) {
            return null;
        }
        $execReturnSlots = [];
        foreach ($block->opCodes as $op) {
            if (OpCode::TYPE_FUNCCALL_EXEC_RETURN === $op->type && null !== $op->arg1) {
                $execReturnSlots[] = (int) $op->arg1;
            }
        }
        foreach ($pendingNestedProducerOps as $op) {
            if (OpCode::TYPE_FUNCCALL_EXEC_RETURN === $op->type && null !== $op->arg1) {
                $execReturnSlots[] = (int) $op->arg1;
            }
        }
        if ($producerOrdinal >= \count($execReturnSlots)) {
            return null;
        }

        return $execReturnSlots[$producerOrdinal];
    }

    /** Last emitted FUNCCALL_EXEC_RETURN for a literal callee name (emission order, not cfg index). */
    private function slotForLastEmittedFuncCallExecReturnByName(Block $block, string $calleeName): ?string
    {
        $needle = strtolower($calleeName);
        $slot = null;
        $pending = false;
        foreach ($block->opCodes as $op) {
            if (OpCode::TYPE_FUNCCALL_INIT === $op->type) {
                $initName = $this->resolveCompileTimeStringSlot((int) $op->arg1, $block);
                $pending = $needle === strtolower($initName ?? '');
            }
            if (OpCode::TYPE_FUNCCALL_EXEC_RETURN === $op->type && null !== $op->arg1) {
                if ($pending) {
                    $slot = (string) $op->arg1;
                }
                $pending = false;
            }
        }

        return $slot;
    }

    /**
     * substr(f(...), -N) — nested FuncCall haystack cfg index + callee name (#10673, #16451, #17572).
     *
     * @param list<Op> $cfgChildren
     *
     * @return array{0: int, 1: string}|null
     */
    private function substrNestedHaystackFuncCallAtUnaryMinusPattern(
        Op $cfgCallOp,
        int $callIndex,
        array $cfgChildren
    ): ?array {
        if (
            'substr' !== strtolower($this->resolveInlineCallArgFuncName($cfgCallOp) ?? '')
            || !\is_array($cfgCallOp->args ?? null)
            || \count($cfgCallOp->args) < 2
            || $callIndex < 2
            || $this->isEmbeddedCallLiteralArg($cfgCallOp->args[0] ?? null)
        ) {
            return null;
        }
        if (!$this->isUnaryInlineSiblingCallArgExpr($cfgChildren[$callIndex - 1] ?? null)) {
            return null;
        }
        $probeIndex = $callIndex - 2;
        while ($probeIndex >= 0) {
            $skip = $cfgChildren[$probeIndex] ?? null;
            if ($skip instanceof Op\Expr\ConstFetch || $skip instanceof Op\Expr\ClassConstFetch) {
                --$probeIndex;
                continue;
            }
            break;
        }
        $producerOp = $cfgChildren[$probeIndex] ?? null;
        if (!($producerOp instanceof Op\Expr\FuncCall || $producerOp instanceof Op\Expr\NsFuncCall)) {
            return null;
        }
        $calleeName = $this->resolveCfgFuncCallName($producerOp);
        if (null === $calleeName || '' === $calleeName) {
            return null;
        }
        if (
            !$this->isNestedCallArgProducerForConsumer(
                $producerOp,
                $cfgCallOp,
                $probeIndex,
                $callIndex,
                $cfgChildren
            )
            || 0 !== $this->siblingMultiArgFuncCallProducerTargetArgIndex(
                $probeIndex,
                $callIndex,
                $cfgChildren
            )
        ) {
            return null;
        }

        return [$probeIndex, $calleeName];
    }

    /**
     * substr(sprintf('%o', fileperms($path)), -N) — UnaryMinus offset + nested FuncCall haystack (#16451, #16480).
     *
     * @param list<Op> $cfgChildren
     */
    private function isSubstrNestedSprintfUnaryMinusPattern(
        Op $cfgCallOp,
        int $callIndex,
        array $cfgChildren
    ): bool {
        return null !== $this->substrNestedHaystackFuncCallAtUnaryMinusPattern(
            $cfgCallOp,
            $callIndex,
            $cfgChildren
        );
    }

    /**
     * @param list<Op> $cfgChildren
     */
    private function slotForSubstrNestedHaystackFuncCallExecReturn(
        Block $block,
        int $probeIndex,
        string $calleeName,
        array $cfgChildren
    ): ?string {
        return $this->slotForLastEmittedFuncCallExecReturnByName($block, $calleeName)
            ?? $this->slotForInlineFuncCallProducerExecReturnByCfgIndex(
                $block,
                $probeIndex,
                $cfgChildren
            )
            ?? $this->slotForLastEmittedInlineCallResultBeforePendingFuncCall($block);
    }

    /**
     * FUNCCALL_EXEC_RETURN slots emitted before a hoisted sibling FuncCall chain (e.g. `new` ctor).
     *
     * @param list<Op> $cfgChildren
     */
    private function execReturnOrdinalBaseBeforeSiblingInlineFuncCallChain(
        int $firstSibling,
        array $cfgChildren,
        ?int $consumerIndex = null
    ): int {
        $base = 0;
        for ($j = 0; $j < $firstSibling; ++$j) {
            $child = $cfgChildren[$j] ?? null;
            if (!$child instanceof Op\Expr) {
                continue;
            }
            if ($child instanceof Op\Expr\New_) {
                ++$base;
                continue;
            }
            if ($child instanceof Op\Expr\FuncCall || $child instanceof Op\Expr\NsFuncCall) {
                ++$base;
                continue;
            }
            if (
                $child instanceof Op\Expr\MethodCall
                || $child instanceof Op\Expr\NullsafeMethodCall
                || $child instanceof Op\Expr\StaticCall
            ) {
                if ($child instanceof Op\Expr\MethodCall && $this->methodCallHasStatementLevelSideEffects($child)) {
                    continue;
                }
                // Prior loadXML()-style MethodCalls compile as EXEC_NORETURN — do not inflate
                // the EXEC_RETURN ordinal base used for sibling MethodCall arg producers (#21182).
                if (
                    $child instanceof Op\Expr\MethodCall
                    && !$this->methodCallInlineProducerSuppliesCallArgValue($child)
                ) {
                    continue;
                }
                $method = $this->staticNameFromOperand($child->name);
                if (null === $method || !$this->methodCallIsKnownVoidReturn($method)) {
                    ++$base;
                }
            }
        }

        return $base;
    }

    /**
     * FUNCCALL_EXEC_RETURN slot for a hoisted inline FuncCall by cfg child index (#15488, #15475).
     *
     * @param list<Op> $cfgChildren
     */
    private function slotForInlineFuncCallProducerExecReturnByCfgIndex(
        Block $block,
        int $producerIndex,
        array $cfgChildren
    ): ?int {
        if ($producerIndex < 0 || $producerIndex >= \count($cfgChildren)) {
            return null;
        }
        $producer = $cfgChildren[$producerIndex] ?? null;
        if (
            !$producer instanceof Op\Expr\FuncCall
            && !$producer instanceof Op\Expr\NsFuncCall
        ) {
            return null;
        }
        for ($consumerIndex = $producerIndex + 1, $n = \count($cfgChildren); $consumerIndex < $n; ++$consumerIndex) {
            $consumer = $cfgChildren[$consumerIndex] ?? null;
            if (!$this->isSiblingMultiArgInlineCallConsumer($consumer)) {
                continue;
            }
            if (!\is_array($consumer->args ?? null) || \count($consumer->args) < 2) {
                continue;
            }
            $firstSibling = $this->firstSiblingInlineFuncCallProducerIndex($consumerIndex, $cfgChildren);
            if (
                null === $firstSibling
                || $producerIndex < $firstSibling
                || $producerIndex >= $consumerIndex
            ) {
                continue;
            }
            if (!$this->isSiblingMultiArgFuncCallProducer(
                $producer,
                $consumer,
                $producerIndex,
                $consumerIndex,
                $cfgChildren
            )) {
                continue;
            }
            $siblingOrdinal = $this->siblingInlineFuncCallProducerOrdinal(
                $producerIndex,
                $firstSibling,
                $cfgChildren,
                $consumerIndex
            );
            $legacyBase = $this->execReturnOrdinalBaseBeforeSiblingInlineFuncCallChain(
                $firstSibling,
                $cfgChildren,
                $consumerIndex
            );
            $chainProducerCount = $this->countSiblingInlineFuncCallProducers(
                $firstSibling,
                $consumerIndex,
                $cfgChildren
            );
            $execReturnCount = 0;
            foreach ($block->opCodes as $op) {
                if (OpCode::TYPE_FUNCCALL_EXEC_RETURN === $op->type && null !== $op->arg1) {
                    ++$execReturnCount;
                }
            }
            if ($this->forceDeferredSiblingCallReturnSlot) {
                // Deferred chain compile emits the next EXEC_RETURN in order (#16254).
                $execOrdinal = $execReturnCount;
            } else {
                $execOrdinal = $execReturnCount - $chainProducerCount + $siblingOrdinal;
            }

            return $this->slotForSiblingInlineFuncCallProducerExecReturnOrdinal($block, $execOrdinal);
        }
        $funcCallOrdinal = 0;
        for ($j = 0; $j <= $producerIndex; ++$j) {
            $child = $cfgChildren[$j] ?? null;
            if (!$child instanceof Op\Expr\FuncCall && !$child instanceof Op\Expr\NsFuncCall) {
                continue;
            }
            if ($this->builtinUsesTrailingComparatorCallback($this->resolveCfgFuncCallName($child))) {
                continue;
            }
            if ($this->siblingInlineFuncCallSkipsExecReturnOrdinal($child, $j, $cfgChildren)) {
                continue;
            }
            if ($j === $producerIndex) {
                // New_ and prior MethodCall/StaticCall also emit FUNCCALL_EXEC_RETURN; omitting
                // them maps array_keys(get_object_vars($o)) onto an earlier implode/string slot
                // after $o->m() in the same block (#26770, related #21981/#25812).
                $nonFuncCallExecBase = 0;
                for ($k = 0; $k < $producerIndex; ++$k) {
                    $prior = $cfgChildren[$k] ?? null;
                    if ($prior instanceof Op\Expr\New_) {
                        ++$nonFuncCallExecBase;
                        continue;
                    }
                    if (
                        $prior instanceof Op\Expr\MethodCall
                        || $prior instanceof Op\Expr\NullsafeMethodCall
                        || $prior instanceof Op\Expr\StaticCall
                    ) {
                        if (
                            $prior instanceof Op\Expr\MethodCall
                            && $this->methodCallHasStatementLevelSideEffects($prior)
                        ) {
                            continue;
                        }
                        if (
                            $prior instanceof Op\Expr\MethodCall
                            && !$this->methodCallInlineProducerSuppliesCallArgValue($prior)
                        ) {
                            continue;
                        }
                        $method = $this->staticNameFromOperand($prior->name);
                        if (null === $method || !$this->methodCallIsKnownVoidReturn($method)) {
                            ++$nonFuncCallExecBase;
                        }
                    }
                }

                return $this->slotForSiblingInlineFuncCallProducerExecReturnOrdinal(
                    $block,
                    $funcCallOrdinal + $nonFuncCallExecBase
                );
            }
            ++$funcCallOrdinal;
        }

        return null;
    }

    /**
     * Result slot for a hoisted sibling FuncCall producer — prefer FUNCCALL_EXEC_RETURN (#16029).
     *
     * @param list<Op> $cfgChildren
     */
    private function slotForSiblingInlineCallProducerExecReturnByExpr(
        Block $block,
        Op\Expr $producer,
        Op $consumer,
        array $cfgChildren
    ): ?int {
        $producerIndex = array_search($producer, $cfgChildren, true);
        $consumerIndex = array_search($consumer, $cfgChildren, true);
        if (!is_int($producerIndex) || !is_int($consumerIndex)) {
            return null;
        }
        $firstSibling = $this->firstSiblingInlineFuncCallProducerIndex($consumerIndex, $cfgChildren);
        if (null === $firstSibling || $producerIndex < $firstSibling || $producerIndex >= $consumerIndex) {
            return null;
        }
        if (!$this->isSiblingInlineCallProducerExpr($producer)) {
            return null;
        }
        if (
            $producer instanceof Op\Expr\FuncCall
            || $producer instanceof Op\Expr\NsFuncCall
        ) {
            $byCfgIndex = $this->slotForInlineFuncCallProducerExecReturnByCfgIndex(
                $block,
                $producerIndex,
                $cfgChildren
            );
            if (null !== $byCfgIndex) {
                return $byCfgIndex;
            }
        }
        $producerOrdinal = $this->siblingInlineFuncCallProducerOrdinal(
            $producerIndex,
            $firstSibling,
            $cfgChildren,
            $consumerIndex
        );
        $chainProducerCount = $this->countSiblingInlineFuncCallProducers(
            $firstSibling,
            $consumerIndex,
            $cfgChildren
        );
        $execReturnCount = 0;
        foreach ($block->opCodes as $op) {
            if (OpCode::TYPE_FUNCCALL_EXEC_RETURN === $op->type && null !== $op->arg1) {
                ++$execReturnCount;
            }
        }
        if ($this->forceDeferredSiblingCallReturnSlot) {
            $execOrdinal = $execReturnCount;
        } elseif (
            $producer instanceof Op\Expr\MethodCall
            || $producer instanceof Op\Expr\StaticCall
        ) {
            $legacyBase = $this->execReturnOrdinalBaseBeforeSiblingInlineFuncCallChain(
                $firstSibling,
                $cfgChildren,
                $consumerIndex
            );
            $execOrdinal = $legacyBase + $producerOrdinal;
        } else {
            $execOrdinal = $execReturnCount - $chainProducerCount + $producerOrdinal;
        }

        return $this->slotForSiblingInlineFuncCallProducerExecReturnOrdinal($block, $execOrdinal);
    }

    /**
     * Inline call-arg producer result — EXEC_RETURN when hoisted siblings drifted operand slots (#16029).
     *
     * @param list<Op> $cfgChildren
     */
    /**
     * is_array(file(..., FILE_* | FILE_*)) — dead arg temp may alias bitmask OR, not file() result (#10474).
     */
    private function slotForNestedFuncCallArrayConsumerProducer(
        Block $block,
        Op\Expr $producer,
        Op $consumer,
        int $producerIndex,
        int $argIndex
    ): ?string {
        if (
            !($producer instanceof Op\Expr\FuncCall || $producer instanceof Op\Expr\NsFuncCall)
            || !property_exists($consumer, 'args')
            || !\is_array($consumer->args)
        ) {
            return null;
        }
        $callArg = $consumer->args[$argIndex] ?? null;
        if (
            !$callArg instanceof Operand
            || !$this->callArgOperandExpectsArrayProducer($callArg)
        ) {
            return null;
        }
        if (null === $block->orig) {
            return null;
        }
        $execReturn = $this->slotForSiblingInlineCallProducerExecReturnByExpr(
            $block,
            $producer,
            $consumer,
            $block->orig->children
        );
        if (null !== $execReturn) {
            return (string) $execReturn;
        }
        $execReturn = $this->slotForInlineFuncCallProducerExecReturnByCfgIndex(
            $block,
            $producerIndex,
            $block->orig->children
        );
        if (null !== $execReturn) {
            return (string) $execReturn;
        }
        if (
            $this->isAdjacentNestedFuncCallProducer(
                $producer,
                $consumer,
                $producerIndex,
                array_search($consumer, $block->orig->children, true) ?: -1
            )
        ) {
            $recent = $this->slotForLastEmittedInlineCallResultBeforePendingFuncCall($block);
            if (null !== $recent) {
                return (string) $recent;
            }
        }

        return $this->slotForInlineCallArgProducerResult(
            $block,
            $producer,
            $consumer,
            $block->orig->children
        );
    }

    private function slotForInlineCallArgProducerResult(
        Block $block,
        Op\Expr $producer,
        ?Op $consumer = null,
        ?array $cfgChildren = null
    ): ?string {
        if (
            null !== $consumer
            && null !== $cfgChildren
            && ($producer instanceof Op\Expr\MethodCall || $producer instanceof Op\Expr\StaticCall)
        ) {
            $methodSlot = $this->slotForSiblingMethodCallProducerExecReturn(
                $block,
                $producer,
                $consumer,
                $cfgChildren
            );
            if (null !== $methodSlot) {
                return $methodSlot;
            }
        }
        if (null !== $consumer && null !== $cfgChildren) {
            $execReturn = $this->slotForSiblingInlineCallProducerExecReturnByExpr(
                $block,
                $producer,
                $consumer,
                $cfgChildren
            );
            if (null !== $execReturn) {
                return (string) $execReturn;
            }
        }
        if ($producer instanceof Op\Expr\NullsafePropertyFetch) {
            $nullsafeSlot = $this->slotForNullsafeResult($block, $producer);
            if (null !== $nullsafeSlot) {
                return (string) $nullsafeSlot;
            }
        }
        $operandSlot = $block->slotForOperand($producer->result);

        return null !== $operandSlot ? (string) $operandSlot : null;
    }

    /**
     * var_export(Color::tryFrom(), true) / var_export($o->m(), true) — match INIT→EXEC_RETURN pair (#18164, #17767).
     *
     * @param list<OpCode> $pendingOps
     */
    private function slotForMethodOrStaticCallInitFollowingExecReturn(
        Block $block,
        Op\Expr $producer,
        array $pendingOps = []
    ): ?string {
        if (
            !$producer instanceof Op\Expr\MethodCall
            && !$producer instanceof Op\Expr\StaticCall
        ) {
            return null;
        }
        $methodName = $this->staticNameFromOperand($producer->name);
        if (null === $methodName) {
            return null;
        }
        $initType = $producer instanceof Op\Expr\StaticCall
            ? OpCode::TYPE_STATICCALL_INIT
            : OpCode::TYPE_METHODCALL_INIT;
        $needle = strtolower($methodName);
        // Pair each cfg MethodCall producer with its own EXEC_RETURN — dead operand slots
        // reuse across repeated same-named calls (#18183, #18184).
        $producerOrdinal = 0;
        if (null !== $block->orig) {
            foreach ($block->orig->children as $child) {
                if ($child === $producer) {
                    break;
                }
                if ($child instanceof Op\Expr\MethodCall || $child instanceof Op\Expr\StaticCall) {
                    $priorName = $this->staticNameFromOperand($child->name);
                    if (null !== $priorName && $needle === strtolower($priorName)) {
                        ++$producerOrdinal;
                    }
                }
            }
        }
        $ops = array_merge($block->opCodes, $pendingOps);
        $seenInit = 0;
        foreach ($ops as $i => $op) {
            if ($initType !== $op->type || null === $op->arg2) {
                continue;
            }
            $name = $this->resolveCompileTimeStringSlot((int) $op->arg2, $block);
            if ($needle !== strtolower($name ?? '')) {
                continue;
            }
            if ($seenInit !== $producerOrdinal) {
                ++$seenInit;
                continue;
            }
            for ($j = $i + 1, $n = \count($ops); $j < $n; ++$j) {
                $scan = $ops[$j];
                if (OpCode::TYPE_FUNCCALL_EXEC_RETURN === $scan->type && null !== $scan->arg1) {
                    return (string) $scan->arg1;
                }
                if (OpCode::TYPE_FUNCCALL_INIT === $scan->type) {
                    break;
                }
            }
            ++$seenInit;
        }

        return null;
    }

    /**
     * Pair METHODCALL_INIT → EXEC_RETURN by callee name and embedded literal args (#21901).
     *
     * When php-cfg emits createElement('y') before createElement('x') (RTL), ordinal pairing
     * by same-named MethodCall alone binds the wrong EXEC_RETURN. Matching the ARG_SEND
     * literal(s) after INIT (Nth occurrence in CFG) disambiguates.
     */
    private function slotForMethodOrStaticCallInitFollowingExecReturnMatchingArgs(
        Block $block,
        Op\Expr $producer
    ): ?string {
        if (
            !$producer instanceof Op\Expr\MethodCall
            && !$producer instanceof Op\Expr\StaticCall
        ) {
            return null;
        }
        $methodName = $this->staticNameFromOperand($producer->name);
        if (null === $methodName) {
            return null;
        }
        $needle = strtolower($methodName);
        $expectedArgLiterals = [];
        if (property_exists($producer, 'args') && \is_array($producer->args)) {
            foreach ($producer->args as $producerArg) {
                if ($producerArg instanceof Operand\Literal) {
                    $expectedArgLiterals[] = (string) $producerArg->value;
                } else {
                    return $this->slotForMethodOrStaticCallInitFollowingExecReturn($block, $producer);
                }
            }
        }
        $occurrence = 0;
        if (null !== $block->orig) {
            foreach ($block->orig->children as $child) {
                if ($child === $producer) {
                    break;
                }
                if (
                    !($child instanceof Op\Expr\MethodCall || $child instanceof Op\Expr\StaticCall)
                ) {
                    continue;
                }
                $priorName = $this->staticNameFromOperand($child->name);
                if (null === $priorName || $needle !== strtolower($priorName)) {
                    continue;
                }
                if (!property_exists($child, 'args') || !\is_array($child->args)) {
                    continue;
                }
                $priorLiterals = [];
                $allLiteral = true;
                foreach ($child->args as $priorArg) {
                    if ($priorArg instanceof Operand\Literal) {
                        $priorLiterals[] = (string) $priorArg->value;
                    } else {
                        $allLiteral = false;
                        break;
                    }
                }
                if ($allLiteral && $priorLiterals === $expectedArgLiterals) {
                    ++$occurrence;
                }
            }
        }
        $initType = $producer instanceof Op\Expr\StaticCall
            ? OpCode::TYPE_STATICCALL_INIT
            : OpCode::TYPE_METHODCALL_INIT;
        $ops = $block->opCodes;
        $seenMatch = 0;
        foreach ($ops as $i => $op) {
            if ($initType !== $op->type || null === $op->arg2) {
                continue;
            }
            $name = $this->resolveCompileTimeStringSlot((int) $op->arg2, $block);
            if ($needle !== strtolower($name ?? '')) {
                continue;
            }
            $argLiterals = [];
            $execSlot = null;
            for ($j = $i + 1, $n = \count($ops); $j < $n; ++$j) {
                $scan = $ops[$j];
                if (OpCode::TYPE_ARG_SEND === $scan->type && null !== $scan->arg1) {
                    $lit = $this->resolveCompileTimeStringSlot((int) $scan->arg1, $block);
                    if (null !== $lit) {
                        $argLiterals[] = $lit;
                    }
                    continue;
                }
                if (OpCode::TYPE_FUNCCALL_EXEC_RETURN === $scan->type && null !== $scan->arg1) {
                    $execSlot = (string) $scan->arg1;
                    break;
                }
                if (
                    OpCode::TYPE_FUNCCALL_INIT === $scan->type
                    || OpCode::TYPE_METHODCALL_INIT === $scan->type
                    || OpCode::TYPE_STATICCALL_INIT === $scan->type
                ) {
                    break;
                }
            }
            if (null === $execSlot || $argLiterals !== $expectedArgLiterals) {
                continue;
            }
            if ($seenMatch === $occurrence) {
                return $execSlot;
            }
            ++$seenMatch;
        }

        return null;
    }

    /**
     * var_export(..., true) — hoisted ConstFetch true may not be emitted before ARG_SEND rewire (#18164).
     */
    private function slotForVarExportHoistedReturnTruePrelude(Block $block, Op $cfgCallOp): ?string
    {
        if (null === $block->orig) {
            return null;
        }
        foreach ($this->hoistedPreludeProducersImmediatelyBeforeCall($cfgCallOp, $block) as $prelude) {
            if (!$prelude instanceof Op\Expr\ConstFetch) {
                continue;
            }
            $name = $this->staticNameFromOperand($prelude->name);
            if ('true' !== strtolower($name ?? '')) {
                continue;
            }
            if (null === $block->slotForOperand($prelude->result)) {
                foreach ($this->compileExpr($prelude, $block) as $op) {
                    $block->addOpCode($op);
                }
            }
            $slot = $block->slotForOperand($prelude->result);

            return null !== $slot ? (string) $slot : null;
        }

        return null;
    }

    /**
     * var_export(INF, true) twice — hoisted scalar ConstFetch (INF/NAN/…) is arg #0, not prior var_export EXEC_RETURN (#18426).
     *
     * @param list<OpCode> $emitOps
     */
    private function slotForVarExportHoistedScalarConstArgZero(
        Block $block,
        Op $cfgCallOp,
        array &$emitOps = []
    ): ?string {
        if (null === $block->orig || !\is_array($cfgCallOp->args ?? null)) {
            return null;
        }
        $callArg = $cfgCallOp->args[0] ?? null;
        if (!$this->callArgIsDeadInlineTemporary($callArg)) {
            return null;
        }
        $preludes = $this->hoistedPreludeProducersImmediatelyBeforeCall($cfgCallOp, $block);
        while ([] !== $preludes) {
            $tail = $preludes[\count($preludes) - 1];
            if ($tail instanceof Op\Expr\ConstFetch) {
                $tailName = strtolower($this->staticNameFromOperand($tail->name) ?? '');
                if (\in_array($tailName, ['true', 'false', 'null'], true)) {
                    array_pop($preludes);
                    continue;
                }
            }
            break;
        }
        if ([] === $preludes) {
            return null;
        }
        $argZeroPrelude = $preludes[\count($preludes) - 1];
        if (
            $argZeroPrelude instanceof Op\Expr\UnaryMinus
            || $argZeroPrelude instanceof Op\Expr\UnaryPlus
        ) {
            if (null === $block->slotForOperand($argZeroPrelude->result)) {
                foreach ($this->compileExpr($argZeroPrelude, $block) as $op) {
                    if ([] !== $emitOps) {
                        $emitOps[] = $op;
                    } else {
                        $block->addOpCode($op);
                    }
                }
            }
            $slot = $block->slotForOperand($argZeroPrelude->result);

            return null !== $slot ? (string) $slot : null;
        }
        if (!$argZeroPrelude instanceof Op\Expr\ConstFetch) {
            return null;
        }
        $name = strtolower($this->staticNameFromOperand($argZeroPrelude->name) ?? '');
        if (\in_array($name, ['true', 'false', 'null'], true)) {
            return null;
        }
        if (null === $block->slotForOperand($argZeroPrelude->result)) {
            foreach ($this->compileExpr($argZeroPrelude, $block) as $op) {
                if ([] !== $emitOps) {
                    $emitOps[] = $op;
                } else {
                    $block->addOpCode($op);
                }
            }
        }
        $slot = $block->slotForOperand($argZeroPrelude->result);
        if (null === $slot) {
            $slot = $this->slotForRecentConstFetchNamedLiteral($block, $name);
        }

        return null !== $slot ? (string) $slot : null;
    }

    /** Recent TYPE_CONST_FETCH for a global literal name (dead-temp vs hoisted-result drift, #18426). */
    private function slotForRecentConstFetchNamedLiteral(Block $block, string $literalName): ?string
    {
        $needle = strtolower($literalName);
        $i = \count($block->opCodes) - 1;
        while ($i >= 0 && OpCode::TYPE_FUNCCALL_INIT === $block->opCodes[$i]->type) {
            --$i;
        }
        for (; $i >= 0; --$i) {
            $op = $block->opCodes[$i];
            if (OpCode::TYPE_FUNCCALL_INIT === $op->type) {
                break;
            }
            if (OpCode::TYPE_CONST_FETCH !== $op->type || null === $op->arg1 || null === $op->arg2) {
                continue;
            }
            $resolved = null;
            if (\is_string($op->arg2)) {
                $resolved = strtolower($op->arg2);
            } elseif (\is_int($op->arg2)) {
                $const = $block->constants[$op->arg2] ?? null;
                if (null !== $const && Variable::TYPE_STRING === $const->type) {
                    $resolved = strtolower($const->toString());
                } else {
                    $resolved = strtolower($this->resolveCompileTimeStringSlot($op->arg2, $block) ?? '');
                }
            }
            if ('' === $resolved) {
                continue;
            }

            return $needle === $resolved ? (string) $op->arg1 : null;
        }

        return null;
    }

    /**
     * var_export($it->current(), true) — MethodCall EXEC_RETURN ordinal uses legacy base (#13901, #17251).
     *
     * @param list<Op> $cfgChildren
     */
    private function slotForSiblingMethodCallProducerExecReturn(
        Block $block,
        Op\Expr $producer,
        Op $consumer,
        array $cfgChildren
    ): ?string {
        if (
            !$producer instanceof Op\Expr\MethodCall
            && !$producer instanceof Op\Expr\StaticCall
        ) {
            return null;
        }
        // Pair METHODCALL_INIT → EXEC_RETURN by callee name. Ordinal EXEC_RETURN indexing
        // drifts when prior stmts (loadXML) are EXEC_NORETURN but still inflate legacyBase
        // — bare $d->documentElement->replaceChild(createElement, item) (#21182).
        $paired = $this->slotForMethodOrStaticCallInitFollowingExecReturn($block, $producer);
        if (null !== $paired) {
            return $paired;
        }
        $producerIndex = array_search($producer, $cfgChildren, true);
        $consumerIndex = array_search($consumer, $cfgChildren, true);
        if (!is_int($producerIndex) || !is_int($consumerIndex)) {
            return null;
        }
        $firstSibling = $this->firstSiblingInlineFuncCallProducerIndex($consumerIndex, $cfgChildren);
        if (null === $firstSibling || $producerIndex < $firstSibling || $producerIndex >= $consumerIndex) {
            return null;
        }
        $producerOrdinal = $this->siblingInlineFuncCallProducerOrdinal(
            $producerIndex,
            $firstSibling,
            $cfgChildren
        );
        $legacyBase = $this->execReturnOrdinalBaseBeforeSiblingInlineFuncCallChain(
            $firstSibling,
            $cfgChildren,
            $consumerIndex
        );
        $execSlot = $this->slotForSiblingInlineFuncCallProducerExecReturnOrdinal(
            $block,
            $legacyBase + $producerOrdinal
        );

        return null !== $execSlot ? (string) $execSlot : null;
    }

    /**
     * Hoisted ConstFetch immediately before a multi-arg consumer — map dead temps to literal slots (#16272, #13829).
     *
     * @param list<OpCode> $emitOps
     */
    private function slotForImmediateConstFetchPreludeCallArg(
        Block $block,
        Op $cfgCallOp,
        int $argIndex,
        array &$emitOps = []
    ): ?string {
        if (null === $block->orig || !\is_array($cfgCallOp->args ?? null)) {
            return null;
        }
        $callArg = $cfgCallOp->args[$argIndex] ?? null;
        if (!$this->callArgIsDeadInlineTemporary($callArg)) {
            return null;
        }
        // in_array('x', g(), true) — immediate ConstFetch is strict, not haystack (#16265).
        if (
            \in_array(strtolower($this->resolveCfgFuncCallName($cfgCallOp) ?? ''), ['in_array', 'array_search'], true)
            && 1 === $argIndex
            && $this->callArgOperandExpectsArrayProducer($callArg)
        ) {
            return null;
        }
        $hoistedScalarSlot = $this->tryFoldHoistedBoolNullLiteralCallArg(
            $callArg,
            $block,
            $cfgCallOp,
            $argIndex
        );
        if (null !== $hoistedScalarSlot) {
            return (string) $hoistedScalarSlot;
        }

        $callIndex = array_search($cfgCallOp, $block->orig->children, true);
        if (!\is_int($callIndex) || $callIndex < 1) {
            return null;
        }
        $immediatePrelude = $block->orig->children[$callIndex - 1] ?? null;
        if (
            !($immediatePrelude instanceof Op\Expr\ConstFetch || $immediatePrelude instanceof Op\Expr\ClassConstFetch)
            || null === $immediatePrelude->result
        ) {
            return null;
        }
        if (null === $block->slotForOperand($immediatePrelude->result)) {
            foreach ($this->compileExpr($immediatePrelude, $block) as $op) {
                if ([] !== $emitOps) {
                    $emitOps[] = $op;
                } else {
                    $block->addOpCode($op);
                }
            }
        }
        $constSlot = $block->slotForOperand($immediatePrelude->result);
        $callArg = $cfgCallOp->args[$argIndex] ?? null;
        if (
            $immediatePrelude instanceof Op\Expr\ClassConstFetch
            && null !== $callArg
            && null !== $constSlot
            && (
                $immediatePrelude->result === $callArg
                || $this->operandsReferToSameVariable($immediatePrelude->result, $callArg)
            )
        ) {
            // method_exists(I::class, 'm') after earlier stmts — hoisted ::class is arg #0 (#9486).
            return (string) $constSlot;
        }
        if (
            0 === $argIndex
            && $immediatePrelude instanceof Op\Expr\ConstFetch
            && (
                null !== $this->nestedFuncCallProducerBeforeTrailingConstFetchPreludes(
                    $cfgCallOp,
                    $callIndex,
                    $block->orig->children
                )
                || null !== $this->nonConstInlineProducerBeforeTrailingScalarConstFetchPreludes(
                    $callIndex,
                    $block->orig->children
                )
            )
        ) {
            // var_export(g(), true) / importNode($doc->documentElement, true) — trailing ConstFetch is not arg #0 (#11272, #16318).
            return null;
        }
        if (
            0 === $argIndex
            && null !== $callArg
            && $this->callArgOperandExpectsArrayProducer($callArg)
            && !($immediatePrelude instanceof Op\Expr\Array_)
        ) {
            // array_pad([E::A], N, E::B) — immediate ClassConstFetch is pad value, not haystack (#8883).
            return null;
        }
        if (
            0 === $argIndex
            && 'array_pad' === strtolower($this->resolveCfgFuncCallName($cfgCallOp) ?? '')
            && !($immediatePrelude instanceof Op\Expr\Array_)
        ) {
            return null;
        }
        if (
            0 === $argIndex
            && 'extract' === strtolower($this->resolveCfgFuncCallName($cfgCallOp) ?? '')
            && !($immediatePrelude instanceof Op\Expr\Array_)
        ) {
            return null;
        }

        return null !== $constSlot ? (string) $constSlot : null;
    }

    /**
     * var_dump($g(), $g()) — ARG_SEND must use FUNCCALL_EXEC_RETURN slots, not drifted operand temps (#16029).
     */
    private function finalSiblingInlineCallArgSendSlot(
        Block $block,
        Op $cfgCallOp,
        int $argIndex
    ): ?string {
        if (null === $block->orig || !\is_array($cfgCallOp->args ?? null) || \count($cfgCallOp->args) < 2) {
            return null;
        }
        if (
            1 === $argIndex
            && 'substr' === strtolower($this->resolveInlineCallArgFuncName($cfgCallOp, null) ?? '')
        ) {
            $callIndex = array_search($cfgCallOp, $block->orig->children, true);
            if (\is_int($callIndex)) {
                $cfgChildren = $block->orig->children;
                for ($j = $callIndex - 1; $j >= 0; --$j) {
                    $scan = $cfgChildren[$j] ?? null;
                    if (
                        ($scan instanceof Op\Expr\FuncCall || $scan instanceof Op\Expr\NsFuncCall)
                        && $this->isNestedCallArgProducerForConsumer($scan, $cfgCallOp, $j, $callIndex, $cfgChildren)
                        && 0 === $this->siblingMultiArgFuncCallProducerTargetArgIndex($j, $callIndex, $cfgChildren)
                    ) {
                        return null;
                    }
                }
            }
        }
        $callArg = $cfgCallOp->args[$argIndex] ?? null;
        if (!$this->callArgIsDeadInlineTemporary($callArg)) {
            return null;
        }
        $constPreludeSlot = $this->slotForImmediateConstFetchPreludeCallArg($block, $cfgCallOp, $argIndex);
        if (null !== $constPreludeSlot) {
            return $constPreludeSlot;
        }
        $callIndex = array_search($cfgCallOp, $block->orig->children, true);
        if (!\is_int($callIndex)) {
            return null;
        }
        $firstSibling = $this->firstSiblingInlineFuncCallProducerIndex($callIndex, $block->orig->children);
        if (null === $firstSibling) {
            return null;
        }
        $argCount = \count($cfgCallOp->args);
        $deadInlineTempCount = 0;
        foreach ($cfgCallOp->args as $callArg) {
            if ($this->callArgIsDeadInlineTemporary($callArg)) {
                ++$deadInlineTempCount;
            }
        }
        $outer = $this->outerSiblingInlineFuncCallProducers(
            $firstSibling,
            $callIndex,
            $block->orig->children
        );
        if (\count($outer) >= $argCount) {
            $outer = \array_slice($outer, -$argCount);
        }
        if (
            \count($outer) === $argCount
            && $deadInlineTempCount === $argCount
        ) {
            $outerSlot = $this->outerSiblingInlineCallArgProducerExecReturnSlot($block, $cfgCallOp, $argIndex);
            if (null !== $outerSlot) {
                return $outerSlot;
            }
        }
        $siblingFuncCount = $this->countSiblingInlineFuncCallProducers(
            $firstSibling,
            $callIndex,
            $block->orig->children
        );
        if ($siblingFuncCount < 2) {
            $nestedSlot = $this->resolveAdjacentNestedFuncCallArgSlot($block, $cfgCallOp, $argIndex);
            if (null !== $nestedSlot) {
                return $nestedSlot;
            }

            return null;
        }
        if ($this->callIncludesNamedParameter($cfgCallOp)) {
            return null;
        }
        for ($j = $firstSibling; $j < $callIndex; ++$j) {
            $between = $block->orig->children[$j] ?? null;
            if ($between instanceof Op\Expr\Array_) {
                return null;
            }
        }
        $leadingEmbedded = 0;
        foreach ($cfgCallOp->args as $embeddedArg) {
            if ($this->isEmbeddedCallLiteralArg($embeddedArg)) {
                ++$leadingEmbedded;
                continue;
            }
            break;
        }
        // array_intersect(f(g()), f(g())) — map args to outer f() EXEC_RETURN slots, not inner g() (#15488, #16031).
        $outerSlot = $this->outerSiblingInlineCallArgProducerSlot($block, $cfgCallOp, $argIndex);
        if (null !== $outerSlot) {
            return $outerSlot;
        }
        // probe('label', in_array(..., g(), true)) — one hoisted arg maps to adjacent callee, not firstSibling (#16253).
        if (1 === $deadInlineTempCount && $callIndex > 0) {
            $adjacentIndex = $callIndex - 1;
            while ($adjacentIndex >= 0) {
                $adjacentSkip = $block->orig->children[$adjacentIndex] ?? null;
                if ($adjacentSkip instanceof Op\Expr\ConstFetch || $adjacentSkip instanceof Op\Expr\ClassConstFetch) {
                    --$adjacentIndex;
                    continue;
                }
                break;
            }
            $adjacentProducer = $block->orig->children[$adjacentIndex] ?? null;
            if (
                ($adjacentProducer instanceof Op\Expr\FuncCall || $adjacentProducer instanceof Op\Expr\NsFuncCall)
                && $this->isAdjacentNestedFuncCallProducer(
                    $adjacentProducer,
                    $cfgCallOp,
                    $adjacentIndex,
                    $callIndex
                )
            ) {
                $adjacentTargetArg = $this->siblingMultiArgFuncCallProducerTargetArgIndex(
                    $adjacentIndex,
                    $callIndex,
                    $block->orig->children
                );
                if (null === $adjacentTargetArg) {
                    $adjacentTargetArg = $leadingEmbedded;
                }
                if ($adjacentTargetArg === $argIndex) {
                    $adjacentExecReturn = $this->slotForInlineFuncCallProducerExecReturnByCfgIndex(
                        $block,
                        $adjacentIndex,
                        $block->orig->children
                    );
                    if (null !== $adjacentExecReturn) {
                        return (string) $adjacentExecReturn;
                    }
                }
            }
        }
        // substr(sprintf('%o', fileperms($path)), -N) — arg #0 is adjacent nested sprintf, not ordinal-0 fileperms (#16451, #16480).
        if ('substr' === strtolower($this->resolveInlineCallArgFuncName($cfgCallOp, null) ?? '')) {
            $adjacentNestedSlot = $this->resolveAdjacentNestedFuncCallArgSlot($block, $cfgCallOp, $argIndex);
            if (null !== $adjacentNestedSlot) {
                return $adjacentNestedSlot;
            }
        }
        // replaceWith($d->createElement('x'), 'txt', $d->createElement('y')) — when an embedded
        // literal sits between MethodCall producers, map by non-embedded dead-temp ordinal (#21901).
        $hasEmbeddedLiteralArg = false;
        foreach ($cfgCallOp->args as $scanArg) {
            if ($this->isEmbeddedCallLiteralArg($scanArg)) {
                $hasEmbeddedLiteralArg = true;
                break;
            }
        }
        if ($hasEmbeddedLiteralArg) {
            $nonEmbeddedDeadIndices = [];
            foreach ($cfgCallOp->args as $i => $scanArg) {
                if (
                    $scanArg instanceof Operand
                    && $this->callArgIsDeadInlineTemporary($scanArg)
                    && !$this->isEmbeddedCallLiteralArg($scanArg)
                ) {
                    $nonEmbeddedDeadIndices[] = (int) $i;
                }
            }
            $producerOrdinal = array_search($argIndex, $nonEmbeddedDeadIndices, true);
            if (false === $producerOrdinal) {
                return null;
            }
            $producerOrdinal = (int) $producerOrdinal;
        } else {
            $producerOrdinal = $argIndex - $leadingEmbedded;
        }
        if ($producerOrdinal < 0 || $producerOrdinal >= $siblingFuncCount) {
            return null;
        }
        $producerIndex = $this->siblingInlineFuncCallProducerIndexAtOrdinal(
            $producerOrdinal,
            $firstSibling,
            $callIndex,
            $block->orig->children
        );
        if (null === $producerIndex) {
            return null;
        }
        $producer = $block->orig->children[$producerIndex] ?? null;
        if (!$producer instanceof Op\Expr || !$this->isSiblingInlineCallProducerExpr($producer)) {
            return null;
        }
        $targetArgForProducer = $this->siblingMultiArgFuncCallProducerTargetArgIndex(
            $producerIndex,
            $callIndex,
            $block->orig->children
        );
        if (null !== $targetArgForProducer && $targetArgForProducer !== $argIndex) {
            return null;
        }
        if (
            $hasEmbeddedLiteralArg
            && ($producer instanceof Op\Expr\MethodCall || $producer instanceof Op\Expr\StaticCall)
        ) {
            $methodSlot = $this->slotForMethodOrStaticCallInitFollowingExecReturnMatchingArgs(
                $block,
                $producer
            );
            if (null !== $methodSlot) {
                return $methodSlot;
            }
        }
        $execReturn = $this->slotForInlineFuncCallProducerExecReturnByCfgIndex(
            $block,
            $producerIndex,
            $block->orig->children
        );
        if (null === $execReturn) {
            $chainProducerCount = $this->countSiblingInlineFuncCallProducers(
                $firstSibling,
                $callIndex,
                $block->orig->children
            );
            $execReturnCount = 0;
            foreach ($block->opCodes as $op) {
                if (OpCode::TYPE_FUNCCALL_EXEC_RETURN === $op->type && null !== $op->arg1) {
                    ++$execReturnCount;
                }
            }
            if ($this->forceDeferredSiblingCallReturnSlot) {
                $execOrdinal = $execReturnCount;
            } else {
                $execOrdinal = $execReturnCount - $chainProducerCount + $producerOrdinal;
            }
            $execReturn = $this->slotForSiblingInlineFuncCallProducerExecReturnOrdinal($block, $execOrdinal);
        }

        return null !== $execReturn ? (string) $execReturn : null;
    }

    /**
     * var_export(C::__set_state([]), true) — compile nested StaticCall/MethodCall before ARG_SEND (#11896).
     *
     * @param list<OpCode> $emitOps
     */
    private function slotForVarExportNestedInlineCallArg(
        Block $block,
        Op $cfgCallOp,
        int $argIndex,
        array &$emitOps = []
    ): ?int {
        if (0 !== $argIndex || 'var_export' !== $this->resolveCfgFuncCallName($cfgCallOp)) {
            return null;
        }
        if (null === $block->orig) {
            return null;
        }
        $callIndex = null;
        foreach ($block->orig->children as $i => $child) {
            if ($child === $cfgCallOp) {
                $callIndex = $i;
                break;
            }
        }
        if (null === $callIndex || $callIndex < 1) {
            return null;
        }
        $callArg = $cfgCallOp->args[$argIndex] ?? null;
        if (!$callArg instanceof Operand) {
            return null;
        }
        $stmtBefore = $block->orig->children[$callIndex - 1] ?? null;
        if (
            $stmtBefore instanceof Op\Expr\BinaryOp\Plus
            && 0 === $argIndex
            && $this->callArgIsDeadInlineTemporary($callArg)
        ) {
            $plusSlot = $block->slotForOperand($stmtBefore->result);
            if (null === $plusSlot) {
                foreach ($this->compileExpr($stmtBefore, $block) as $op) {
                    $emitOps[] = $op;
                }
                $plusSlot = $block->slotForOperand($stmtBefore->result);
            }

            return null !== $plusSlot ? (int) $plusSlot : null;
        }
        if (
            $stmtBefore instanceof Op\Expr\Array_
            && $this->callArgIsDeadInlineTemporary($callArg)
            && (
                $this->callArgOperandExpectsArrayProducer($callArg)
                || $this->callArgIsDeadUnknownOrMixedTemporary($callArg)
            )
        ) {
            // Prefer INIT_ARRAY after last FUNCCALL_EXEC_RETURN so nested ctor Array_
            // (`new ArrayIterator([1,2,3])` inside `[...$it]`) is not re-sent (#24645).
            $arraySlot = $this->slotForInitArrayBeforeCurrentFunccall($block)
                ?? $block->slotForOperand($stmtBefore->result);
            if (null === $arraySlot) {
                foreach ($this->compileArrayLiteral($stmtBefore, $block) as $op) {
                    $emitOps[] = $op;
                }
                $arraySlot = $this->slotForInitArrayBeforeCurrentFunccall($block)
                    ?? $block->slotForOperand($stmtBefore->result)
                    ?? $this->slotForRecentInitArrayCallArg($block);
            }

            return null !== $arraySlot ? (int) $arraySlot : null;
        }
        if (
            ($stmtBefore instanceof Op\Expr\ConstFetch || $stmtBefore instanceof Op\Expr\ClassConstFetch)
            && 0 === $argIndex
            && $this->callArgIsDeadInlineTemporary($callArg)
        ) {
            // var_export($expr, true|false) — hoisted return flag is not arg #0 (#26702, #17895).
            $skipReturnFlagConst = false;
            if (
                $stmtBefore instanceof Op\Expr\ConstFetch
                && \is_array($cfgCallOp->args ?? null)
                && \count($cfgCallOp->args) >= 2
            ) {
                $flagName = strtolower($this->staticNameFromOperand($stmtBefore->name) ?? '');
                if (\in_array($flagName, ['true', 'false'], true)) {
                    $skipReturnFlagConst = true;
                }
            }
            if (!$skipReturnFlagConst) {
                // define('ARR', …); var_export(ARR) — ConstFetch prelude, not define() bool return (#17872).
                $constSlot = $block->slotForOperand($stmtBefore->result);
                if (null === $constSlot) {
                    foreach ($this->compileExpr($stmtBefore, $block) as $op) {
                        $emitOps[] = $op;
                    }
                    $constSlot = $block->slotForOperand($stmtBefore->result);
                }

                return null !== $constSlot ? (int) $constSlot : null;
            }
        }
        $candidate = null;
        for ($i = $callIndex - 1; $i >= 0; --$i) {
            $child = $block->orig->children[$i];
            if ($child instanceof Op\Expr\ConstFetch || $child instanceof Op\Expr\ClassConstFetch) {
                continue;
            }
            if ($child instanceof Op\Expr\Array_) {
                // var_export([strlen('x'), …]) — stmt-before Array_ feeds arg #0, not hoisted element call (#15783, #10733, #16067).
                // Also accept unknown/mixed dead temps for spread arrays (#24645).
                if (
                    $i === $callIndex - 1
                    && (
                        $this->callArgOperandExpectsArrayProducer($callArg)
                        || $this->callArgIsDeadUnknownOrMixedTemporary($callArg)
                    )
                    && (
                        (null !== $child->result && $this->operandsReferToSameVariable($child->result, $callArg))
                        || $this->callArgIsDeadInlineTemporary($callArg)
                    )
                ) {
                    $candidate = $child;
                    break;
                }
                continue;
            }
            if ($this->isSiblingInlineCallProducerExpr($child)) {
                $stmtBefore = $block->orig->children[$callIndex - 1] ?? null;
                if (
                    $stmtBefore instanceof Op\Expr\Array_
                    && $this->callArgIsDeadInlineTemporary($callArg)
                    && (
                        $this->callArgOperandExpectsArrayProducer($callArg)
                        || $this->callArgIsDeadUnknownOrMixedTemporary($callArg)
                    )
                ) {
                    $candidate = $stmtBefore;
                    break;
                }
                $candidate = $child;
                break;
            }
            // var_export(require_once $f[, true]) — Include_/Eval_ feeds arg #0 (#25852, #21938).
            if (
                ($child instanceof Op\Expr\Include_ || $child instanceof Op\Expr\Eval_)
                && $this->callArgIsDeadInlineTemporary($callArg)
            ) {
                $candidate = $child;
                break;
            }
            // var_export($text->data) / var_export(!$o, true) — expression prelude after skipped true/false (#17540, #26702).
            if (
                $this->callArgIsDeadInlineTemporary($callArg)
                && $this->isImmediateVarExportExpressionPrelude($child)
            ) {
                $candidate = $child;
                break;
            }
            break;
        }
        if (!$candidate instanceof Op\Expr || null === $candidate->result) {
            return null;
        }
        $feedsCallArg = $this->inlineCallArgProducerFeedsCallArgOp($candidate, $cfgCallOp, $callArg)
            || (
                $this->callArgIsDeadInlineTemporary($callArg)
                && (
                    (
                        $candidate instanceof Op\Expr\Array_
                        && $this->callArgOperandExpectsArrayProducer($callArg)
                    )
                    || $candidate instanceof Op\Expr\StaticCall
                    || $candidate instanceof Op\Expr\FuncCall
                    || $candidate instanceof Op\Expr\NsFuncCall
                    || $candidate instanceof Op\Expr\MethodCall
                    || $candidate instanceof Op\Expr\Include_
                    || $candidate instanceof Op\Expr\Eval_
                    || $this->isImmediateVarExportExpressionPrelude($candidate)
                )
            );
        if (!$feedsCallArg) {
            return null;
        }
        if ($candidate instanceof Op\Expr\Array_) {
            $arraySlot = $block->slotForOperand($candidate->result);
            if (null === $arraySlot) {
                foreach ($this->compileArrayLiteral($candidate, $block) as $op) {
                    $emitOps[] = $op;
                }
                $arraySlot = $block->slotForOperand($candidate->result)
                    ?? $this->slotForRecentInitArrayCallArg($block);
            }

            return null !== $arraySlot ? (int) $arraySlot : null;
        }
        if (null === $block->slotForOperand($candidate->result)) {
            $prevForce = $this->forceDeferredSiblingCallReturnSlot;
            $this->forceDeferredSiblingCallReturnSlot = true;
            try {
                foreach ($this->compileExpr($candidate, $block) as $op) {
                    $emitOps[] = $op;
                }
            } finally {
                $this->forceDeferredSiblingCallReturnSlot = $prevForce;
            }
        }

        return $block->slotForOperand($candidate->result);
    }

    /**
     * Hoisted current()/key()/… before a consumer — wire arg to FuncCall result, not ephemeral Array_ (#10654).
     */
    private function slotForHoistedArrayPointerBuiltinCallArg(
        Block $block,
        ?Op $cfgCallOp,
        int $argIndex,
        Operand $arg
    ): ?string {
        if (null === $cfgCallOp || null === $block->orig) {
            return null;
        }
        $callArg = $cfgCallOp->args[$argIndex] ?? $arg;
        if (!$this->callArgIsDeadInlineTemporary($callArg)) {
            return null;
        }
        $producers = $this->precedingInlineCallArgProducersBeforeCfgOp($block->orig->children, $cfgCallOp);
        foreach ($producers as $producer) {
            if (!($producer instanceof Op\Expr\FuncCall || $producer instanceof Op\Expr\NsFuncCall)) {
                continue;
            }
            $fn = $this->resolveCfgFuncCallName($producer);
            if (null === $fn || !ReferencableCheck::allowsEphemeralArrayLiteralByRef($fn)) {
                continue;
            }
            if (null === $producer->result || !$this->operandsReferToSameVariable($producer->result, $callArg)) {
                continue;
            }
            $slot = $block->slotForOperand($producer->result);
            if (null === $slot) {
                foreach ($this->compileExpr($producer, $block) as $op) {
                    $block->addOpCode($op);
                }
                $slot = $block->slotForOperand($producer->result);
            }

            return null !== $slot ? (string) $slot : null;
        }

        return null;
    }

    /**
     * strtotime('next Monday', strtotime('...')) — adjacent nested FuncCall feeds trailing arg (#10838).
     */
    /**
     * array_merge(array_keys($src), ['b']) — trailing inline Array_ must not reuse nested FuncCall slot (#13704).
     *
     * @param list<OpCode> $pendingSends
     */
    private function resolveArrayMergeTrailingInlineArrayCallArgSlot(
        Block $block,
        Op $cfgCallOp,
        int $argIndex,
        Operand $arg,
        array &$pendingSends
    ): ?string {
        if (1 !== $argIndex || !property_exists($cfgCallOp, 'args') || !\is_array($cfgCallOp->args)) {
            return null;
        }
        if (null === $block->orig) {
            return null;
        }
        $producers = $this->precedingInlineCallArgProducersBeforeCfgOp($block->orig->children, $cfgCallOp);
        $callArg = $cfgCallOp->args[$argIndex] ?? $arg;
        // array_merge(['a'=>1], array_keys(...)) — arg #1 is sibling FuncCall, not any Array_ (#13775).
        $mergePair = $this->matchArrayMergeFuncCallAndArrayInlineProducers($producers, $argIndex);
        if ($mergePair instanceof Op\Expr\FuncCall || $mergePair instanceof Op\Expr\NsFuncCall) {
            return null;
        }
        foreach ($producers as $producer) {
            if (
                ($producer instanceof Op\Expr\FuncCall || $producer instanceof Op\Expr\NsFuncCall)
                && null !== $producer->result
                && (
                    $producer->result === $callArg
                    || $this->operandsReferToSameVariable($producer->result, $callArg)
                )
            ) {
                // array_merge([...], array_keys(...)) — arg #1 is nested FuncCall, not trailing Array_ (#13760).
                return null;
            }
        }
        $hasNestedFuncCall = false;
        foreach ($producers as $producer) {
            if ($producer instanceof Op\Expr\FuncCall || $producer instanceof Op\Expr\NsFuncCall) {
                $hasNestedFuncCall = true;
                break;
            }
        }
        // array_merge([1], [2]) — sibling flat Array_ literals use normal producer matching (#10093).
        if (!$hasNestedFuncCall) {
            return null;
        }
        $mergeMapped = $this->matchArrayMergeFuncCallAndArrayInlineProducers($producers, $argIndex);
        if ($mergeMapped instanceof Op\Expr\FuncCall || $mergeMapped instanceof Op\Expr\NsFuncCall) {
            // array_merge(['a'=>1], array_keys(...)) — arg #1 is nested FuncCall (#13760, #13775).
            return null;
        }
        $trailingArray = null;
        foreach ($producers as $producer) {
            if ($producer instanceof Op\Expr\Array_) {
                $trailingArray = $producer;
            }
        }
        if (!$trailingArray instanceof Op\Expr\Array_) {
            $callArg = $cfgCallOp->args[$argIndex] ?? $arg;
            if ($this->isEmbeddedCallLiteralArg($callArg)) {
                return (string) $this->compileOperand($callArg, $block, true);
            }

            return null;
        }
        if (null === $block->slotForOperand($trailingArray->result)) {
            foreach ($this->compileExpr($trailingArray, $block) as $op) {
                $pendingSends[] = $op;
            }
        }
        $slot = $block->slotForOperand($trailingArray->result);

        return null !== $slot ? (string) $slot : null;
    }

    /**
     * array_combine() with sibling inline producers — FuncCall+Array_ or Array_+Array_ (#13776, #10214).
     *
     * @param list<Op\Expr> $producers
     */
    private function matchArrayCombineInlineProducers(array $producers, int $argIndex): ?Op\Expr
    {
        if ($argIndex < 0 || $argIndex > 1) {
            return null;
        }
        $arrayProducers = [];
        $funcProducer = null;
        $funcPos = null;
        foreach ($producers as $pi => $producer) {
            if ($producer instanceof Op\Expr\FuncCall || $producer instanceof Op\Expr\NsFuncCall) {
                $funcProducer = $producer;
                $funcPos = $pi;
            } elseif ($producer instanceof Op\Expr\Array_) {
                $arrayProducers[] = $producer;
            }
        }
        if (2 === \count($producers) && 2 === \count($arrayProducers) && null === $funcProducer) {
            return $arrayProducers[$argIndex];
        }
        if (2 === \count($producers) && null !== $funcProducer && 1 === \count($arrayProducers)) {
            return 0 === $argIndex ? $funcProducer : $arrayProducers[0];
        }
        // array_combine(array_keys(['a'=>1,'b'=>2]), [10,20]) — inner Array_ + FuncCall + trailing Array_ (#15558, #13776).
        // array_combine($k, [10,20]) after $k=array_keys(...) — trailing values Array_, not haystack (#16295).
        if (null !== $funcProducer && null !== $funcPos && \count($producers) >= 3) {
            if (0 === $argIndex) {
                return $funcProducer;
            }
            $arrayProducers = array_values(array_filter(
                $producers,
                static fn (Op\Expr $producer): bool => $producer instanceof Op\Expr\Array_
            ));
            if ([] !== $arrayProducers) {
                return $arrayProducers[\count($arrayProducers) - 1];
            }

            return null;
        }

        return null;
    }

    /**
     * array_combine($k, […]) — sibling array_keys EXEC_RETURN must not steal inline values arg (#16295).
     */
    private function arrayCombineSkipsSiblingFuncExecArgSlot(
        Op $cfgCallOp,
        int $argIndex,
        ?Block $block = null
    ): bool {
        if (
            'array_combine' !== $this->resolveCfgFuncCallName($cfgCallOp)
            || 1 !== $argIndex
            || !property_exists($cfgCallOp, 'args')
            || !\is_array($cfgCallOp->args)
        ) {
            return false;
        }
        $valuesArg = $cfgCallOp->args[1] ?? null;
        $keysArg = $cfgCallOp->args[0] ?? null;

        return !$this->callArgIsDeadInlineTemporary($keysArg)
            && $this->callArgIsDeadInlineTemporary($valuesArg)
            && $this->callArgOperandExpectsArrayProducer($valuesArg);
    }

    /**
     * array_merge() with one hoisted FuncCall and one sibling Array_ producer (#12450, #13704, #13760).
     *
     * @param list<Op\Expr> $producers
     */
    private function matchArrayMergeFuncCallAndArrayInlineProducers(array $producers, int $argIndex): ?Op\Expr
    {
        if (2 !== \count($producers)) {
            return null;
        }
        $funcIdx = null;
        $arrayIdx = null;
        foreach ($producers as $pi => $producer) {
            if ($producer instanceof Op\Expr\FuncCall || $producer instanceof Op\Expr\NsFuncCall) {
                $funcIdx = $pi;
            } elseif ($producer instanceof Op\Expr\Array_) {
                $arrayIdx = $pi;
            }
        }
        if (null === $funcIdx || null === $arrayIdx || $funcIdx === $arrayIdx) {
            return null;
        }
        if ($arrayIdx < $funcIdx) {
            return 0 === $argIndex ? $producers[$arrayIdx] : $producers[$funcIdx];
        }

        return 0 === $argIndex ? $producers[$funcIdx] : $producers[$arrayIdx];
    }

    /**
     * array_merge(['a'=>1], array_keys(['b'=>2])) — producer scan stops at nested array_keys
     * and omits the leading base Array_; prepend it before the nested FuncCall chain (#13759).
     *
     * @param list<Op\Expr> $producers
     * @return list<Op\Expr>
     */
    private function augmentArrayMergeFamilyInlineProducers(array $cfgChildren, Op $callOp, array $producers): array
    {
        if ([] === $producers) {
            return $producers;
        }
        $callIndex = null;
        foreach ($cfgChildren as $i => $child) {
            if ($child === $callOp) {
                $callIndex = $i;
                break;
            }
        }
        if (null === $callIndex) {
            return $producers;
        }
        for ($i = $callIndex - 1; $i >= 0; --$i) {
            $child = $cfgChildren[$i];
            if (
                ($child instanceof Op\Expr\FuncCall || $child instanceof Op\Expr\NsFuncCall)
                && \in_array($child, $producers, true)
            ) {
                $innerArray = $cfgChildren[$i - 1] ?? null;
                if (
                    $innerArray instanceof Op\Expr\Array_
                    && $this->isInlineExprCallArgProducer($innerArray)
                ) {
                    for ($j = $i - 2; $j >= 0; --$j) {
                        $prev = $cfgChildren[$j];
                        if (!$prev instanceof Op\Expr || !$this->isInlineExprCallArgProducer($prev)) {
                            break;
                        }
                        if ($prev instanceof Op\Expr\Array_) {
                            if (!\in_array($prev, $producers, true)) {
                                array_unshift($producers, $prev);
                            }
                            break 2;
                        }
                    }
                }
                break;
            }
        }

        return $producers;
    }

    /**
     * @param list<Op\Expr> $producers
     * @return list<Op\Expr>
     */
    private function arrayMergeFamilyInlineProducersForCfgCall(array $cfgChildren, Op $callOp): array
    {
        return $this->augmentArrayMergeFamilyInlineProducers(
            $cfgChildren,
            $callOp,
            $this->precedingInlineCallArgProducersBeforeCfgOp($cfgChildren, $callOp)
        );
    }

    /**
     * Map consecutive hoisted Array_ producers to array-shaped call args by order (#10094, #10808).
     *
     * When every call arg is a dead temp and Array_ producer count matches arity, also treat
     * unknown/mixed dead temps as array args — ClassConstFetch inside `[A::class, 'm']` leaves
     * the callable temp untyped so type-only matching bound `$args` to the first Array_ (#27139).
     *
     * @param list<Op\Expr> $producers
     * @param list<Operand> $callArgs
     */
    private function matchInlineArrayProducersToArrayCallArgs(
        array $producers,
        array $callArgs,
        int $argIndex
    ): ?Op\Expr {
        $arrayProducers = array_values(array_filter(
            $producers,
            static fn (Op\Expr $producer): bool => $producer instanceof Op\Expr\Array_
        ));
        if ([] === $arrayProducers) {
            return null;
        }
        $arrayArgIndices = [];
        foreach ($callArgs as $i => $arg) {
            if (null !== $arg && $this->callArgOperandExpectsArrayProducer($arg)) {
                $arrayArgIndices[] = $i;
            }
        }
        // Sibling flat Array_ literals with equal arity — include unknown dead temps (#27139, #12730).
        if (
            \count($arrayProducers) >= 2
            && \count($arrayProducers) === \count($callArgs)
            && \count($arrayArgIndices) < \count($arrayProducers)
            && !$this->arrayProducersFormNestedChain($arrayProducers)
        ) {
            $allDeadTemps = true;
            foreach ($callArgs as $arg) {
                if (null === $arg || !$this->callArgIsDeadInlineTemporary($arg)) {
                    $allDeadTemps = false;
                    break;
                }
            }
            if ($allDeadTemps) {
                $arrayArgIndices = [];
                foreach ($callArgs as $i => $arg) {
                    if (
                        null !== $arg
                        && (
                            $this->callArgOperandExpectsArrayProducer($arg)
                            || $this->callArgIsDeadUnknownOrMixedTemporary($arg)
                        )
                    ) {
                        $arrayArgIndices[] = $i;
                    }
                }
            }
        }
        $position = array_search($argIndex, $arrayArgIndices, true);
        if (false === $position || !isset($arrayProducers[$position])) {
            return null;
        }
        if (1 === \count($arrayArgIndices) && \count($arrayProducers) >= 2) {
            $outer = $arrayProducers[\count($arrayProducers) - 1];
            foreach (\array_slice($arrayProducers, 0, -1) as $inner) {
                foreach ($outer->values as $value) {
                    if (null !== $value && $this->operandsReferToSameVariable($value, $inner->result)) {
                        return $outer;
                    }
                }
            }
            // id(['b']) inside array_merge(['a'], id(['b'])) — preceding producers include the
            // outer call's Array_; sole array arg binds to the nearest producer (#28891).
            return $outer;
        }

        return $arrayProducers[$position];
    }

    /**
     * array_merge* inline hoisted Array_ roots — flat siblings, nested chains, folded first arg (#10230, #15979).
     *
     * @param list<Op\Expr> $mergeProducers
     * @param list<Operand> $callArgs
     */
    private function matchArrayMergeFamilyFullInlineCallArgProducer(
        array $mergeProducers,
        int $argIndex,
        int $mergeArgCount,
        array $callArgs = []
    ): ?Op\Expr {
        $leadingNested = $this->matchLeadingNestedInlineArrayMergeFamilyCallArgProducer(
            $mergeProducers,
            $argIndex,
            $mergeArgCount
        );
        if (null !== $leadingNested) {
            return $leadingNested;
        }
        $mapped = $this->matchArrayMergeFamilyInlineCallArgProducer($mergeProducers, $argIndex);
        if (null === $mapped) {
            $mapped = $this->matchSiblingNestedArrayLiteralCallArgProducer(
                $mergeProducers,
                $argIndex,
                $mergeArgCount
            );
        }
        if (null === $mapped && [] !== $callArgs) {
            $mapped = $this->matchFoldedFirstNestedSiblingArrayLiteralCallArgProducer(
                $mergeProducers,
                $argIndex,
                $mergeArgCount,
                $callArgs
            );
        }

        return $mapped;
    }

    /**
     * array_merge(array_keys($src), ['b']) — nested FuncCall + trailing Array_, optional stmt Array_ (#15551).
     * array_merge_recursive(['a'=>1], ['a'=>2]) — sibling flat Array_ literals (#15552).
     *
     * @param list<Op\Expr> $producers
     */
    private function matchArrayMergeFamilyInlineCallArgProducer(array $producers, int $argIndex): ?Op\Expr
    {
        if (2 === \count($producers)) {
            $pair = $this->matchArrayMergeFuncCallAndArrayInlineProducers($producers, $argIndex);
            if (null !== $pair) {
                return $pair;
            }
        }
        $funcProducer = null;
        $funcPos = null;
        $arrayProducers = [];
        foreach ($producers as $pi => $producer) {
            if ($producer instanceof Op\Expr\FuncCall || $producer instanceof Op\Expr\NsFuncCall) {
                $funcProducer = $producer;
                $funcPos = $pi;
            } elseif ($producer instanceof Op\Expr\Array_) {
                $arrayProducers[] = $producer;
            }
        }
        if (null !== $funcProducer && null !== $funcPos && [] !== $arrayProducers) {
            $firstArrayPos = null;
            foreach ($producers as $pi => $producer) {
                if ($producer instanceof Op\Expr\Array_) {
                    $firstArrayPos = $pi;
                    break;
                }
            }
            if (null !== $firstArrayPos && $firstArrayPos < $funcPos) {
                return match ($argIndex) {
                    0 => $producers[$firstArrayPos],
                    1 => $funcProducer,
                    default => null,
                };
            }
            if (0 === $argIndex) {
                return $funcProducer;
            }
            for ($j = $funcPos + 1, $n = \count($producers); $j < $n; ++$j) {
                if ($producers[$j] instanceof Op\Expr\Array_) {
                    return $producers[$j];
                }
            }

            return null;
        }
        if (
            \count($arrayProducers) === 2
            && 2 === \count($producers)
            && null === $funcProducer
        ) {
            return $producers[$argIndex] ?? null;
        }

        return null;
    }

    /**
     * array_map(null, [[..]]) — null ConstFetch is callback arg #0, not a nested-call prelude (#9143, #15976).
     */
    private function arrayMapNullCallbackPrecedesInlineHaystack(?Op $callOp, ?Block $block): bool
    {
        return null !== $callOp
            && null !== $block
            && 'array_map' === strtolower($this->resolveCfgFuncCallName($callOp) ?? '')
            && null !== $this->arrayMapNullCallbackProducerBeforeCfgCall($callOp, $block);
    }

    /**
     * array_map(null, null, …) / array_map(null, [[..]]) — inline null ConstFetch preludes in CFG order (#9143, #16226).
     *
     * @return list<Op\Expr\ConstFetch>
     */
    private function arrayMapInlineNullConstFetchProducersBeforeCfgCall(Op $cfgCallOp, Block $block): array
    {
        if (null === $block->orig) {
            return [];
        }
        $callbackArg = $cfgCallOp->args[0] ?? null;
        if ($this->isEmbeddedCallLiteralArg($callbackArg)) {
            return [];
        }
        $leadingCallback = $this->leadingCallbackFirstInlineProducerBeforeCfgCall($cfgCallOp, $block);
        if ($leadingCallback instanceof Op\Expr\ArrowFunction
            || $leadingCallback instanceof Op\Expr\Closure
            || $leadingCallback instanceof Op\Expr\FirstClassCallable) {
            return [];
        }
        $callIndex = null;
        foreach ($block->orig->children as $i => $child) {
            if ($child === $cfgCallOp) {
                $callIndex = $i;
                break;
            }
        }
        if (null === $callIndex) {
            return [];
        }
        $nulls = [];
        for ($i = $callIndex - 1; $i >= 0; --$i) {
            $child = $block->orig->children[$i];
            if ($child instanceof Op\Expr\ConstFetch) {
                $constName = $this->staticNameFromOperand($child->name);
                if (null !== $constName && 'null' === strtolower($constName)) {
                    array_unshift($nulls, $child);
                    continue;
                }
            }
            if ($child instanceof Op\Expr\Array_) {
                continue;
            }
            if (!$child instanceof Op\Expr || !$this->isInlineExprCallArgProducer($child)) {
                break;
            }
        }

        return $nulls;
    }

    /**
     * array_map(null, [[..]]) — hoisted null ConstFetch precedes nested Array_ preludes (#9143).
     */
    private function arrayMapNullCallbackProducerBeforeCfgCall(Op $cfgCallOp, Block $block): ?Op\Expr\ConstFetch
    {
        $nulls = $this->arrayMapInlineNullConstFetchProducersBeforeCfgCall($cfgCallOp, $block);
        $first = $nulls[0] ?? null;

        return $first instanceof Op\Expr\ConstFetch ? $first : null;
    }

    /**
     * array_map(null, null, [..]) — inline null haystack operand, not zip Array_ (#16226).
     */
    private function arrayMapInlineNullHaystackProducerForArgIndex(
        Op $cfgCallOp,
        Block $block,
        int $argIndex
    ): ?Op\Expr\ConstFetch {
        if ($argIndex < 1 || !property_exists($cfgCallOp, 'args') || !is_array($cfgCallOp->args)) {
            return null;
        }
        $callArg = $cfgCallOp->args[$argIndex] ?? null;
        if (!$callArg instanceof Operand || $this->isEmbeddedCallLiteralArg($callArg)) {
            return null;
        }
        if ($this->callArgOperandExpectsArrayProducer($callArg)) {
            return null;
        }
        $nullProducers = $this->arrayMapInlineNullConstFetchProducersBeforeCfgCall($cfgCallOp, $block);
        if (\count($nullProducers) < 2) {
            return null;
        }
        $nullHaystackOrdinal = 0;
        for ($i = 1; $i < $argIndex; ++$i) {
            $prior = $cfgCallOp->args[$i] ?? null;
            if (!$prior instanceof Operand || $this->isEmbeddedCallLiteralArg($prior)) {
                continue;
            }
            if (!$this->callArgOperandExpectsArrayProducer($prior)) {
                ++$nullHaystackOrdinal;
            }
        }
        $targetIndex = 1 + $nullHaystackOrdinal;
        $candidate = $nullProducers[$targetIndex] ?? null;

        return $candidate instanceof Op\Expr\ConstFetch ? $candidate : null;
    }

    /**
     * php-cfg array_intersect(f(g()), f(g())) — map arg N to outer hoisted producer slot (#15488).
     */
    private function outerSiblingInlineCallArgProducerSlot(
        Block $block,
        Op $cfgCallOp,
        int $argIndex,
        ?array &$emitOps = null
    ): ?string {
        if (null === $block->orig || !property_exists($cfgCallOp, 'args') || !is_array($cfgCallOp->args)) {
            return null;
        }
        $argCount = \count($cfgCallOp->args);
        if ($argCount < 2 || $argIndex >= $argCount) {
            return null;
        }
        $callIndex = null;
        foreach ($block->orig->children as $i => $child) {
            if ($child === $cfgCallOp) {
                $callIndex = $i;
                break;
            }
        }
        if (null === $callIndex) {
            return null;
        }
        $firstSibling = $this->firstSiblingInlineFuncCallProducerIndex($callIndex, $block->orig->children);
        if (null === $firstSibling) {
            return null;
        }
        $outer = $this->outerSiblingInlineFuncCallProducers(
            $firstSibling,
            $callIndex,
            $block->orig->children
        );
        $embeddedArgCount = 0;
        $deadInlineTempCount = 0;
        $hoistedArgCount = 0;
        foreach ($cfgCallOp->args as $hoistedArg) {
            if (null !== $hoistedArg && $this->isEmbeddedCallLiteralArg($hoistedArg)) {
                ++$embeddedArgCount;
                continue;
            }
            if ($this->callArgIsDeadInlineTemporary($hoistedArg)) {
                ++$deadInlineTempCount;
            }
            if (null !== $hoistedArg) {
                ++$hoistedArgCount;
            }
        }
        if (\count($outer) === $argCount && ($embeddedArgCount === $argCount || $deadInlineTempCount === $argCount)) {
            // array_intersect(f(g()), f(g())) — hoisted outer producers only (#15488).
            $hoistedArgCount = $argCount;
        }
        if (\count($outer) !== $hoistedArgCount || \count($outer) !== $argCount) {
            return null;
        }
        if (\count($outer) >= $callIndex - $firstSibling) {
            return null;
        }
        $hoistedOrdinal = null;
        $seen = 0;
        foreach ($cfgCallOp->args as $i => $hoistedArg) {
            if (null !== $hoistedArg && !$this->isEmbeddedCallLiteralArg($hoistedArg)) {
                if ($i === $argIndex) {
                    $hoistedOrdinal = $seen;
                    break;
                }
                ++$seen;
            }
        }
        if (null === $hoistedOrdinal) {
            return null;
        }
        $outerProducer = $outer[$hoistedOrdinal] ?? null;
        if (!$outerProducer instanceof Op\Expr || null === $outerProducer->result) {
            return null;
        }
        if (
            $outerProducer instanceof Op\Expr\FuncCall
            || $outerProducer instanceof Op\Expr\NsFuncCall
        ) {
            if (null === $block->slotForOperand($outerProducer->result)) {
                $prevForce = $this->forceDeferredSiblingCallReturnSlot;
                $this->forceDeferredSiblingCallReturnSlot = true;
                try {
                    foreach ($this->compileExpr($outerProducer, $block) as $op) {
                        if (null !== $emitOps) {
                            $emitOps[] = $op;
                        } else {
                            $block->addOpCode($op);
                        }
                    }
                } finally {
                    $this->forceDeferredSiblingCallReturnSlot = $prevForce;
                }
            }
        }
        $operandSlot = $block->slotForOperand($outerProducer->result);
        if (null !== $operandSlot) {
            $outerProducerIndexForOperand = array_search($outerProducer, $block->orig->children, true);
            $prevProducer = is_int($outerProducerIndexForOperand) && $outerProducerIndexForOperand > 0
                ? ($block->orig->children[$outerProducerIndexForOperand - 1] ?? null)
                : null;
            // array_intersect(f(g()), f(g())) — operand slot beats ordinal EXEC_RETURN when emission order drifts (#16427).
            // in_array/array_search before var_dump — EXEC_RETURN ordinals must win (#9390, #17317).
            if (
                ($outerProducer instanceof Op\Expr\FuncCall || $outerProducer instanceof Op\Expr\NsFuncCall)
                && !$this->funcCallExprLiteralCalleeAllowedAsHoistedProducer($outerProducer)
                && !\in_array(
                    strtolower($this->resolveCfgFuncCallName($outerProducer) ?? ''),
                    ['in_array', 'array_search', 'array_key_exists', 'key_exists'],
                    true
                )
                && ($prevProducer instanceof Op\Expr\FuncCall || $prevProducer instanceof Op\Expr\NsFuncCall)
                && is_int($outerProducerIndexForOperand)
                && $this->isAdjacentNestedFuncCallProducer(
                    $prevProducer,
                    $outerProducer,
                    $outerProducerIndexForOperand - 1,
                    $outerProducerIndexForOperand
                )
            ) {
                return (string) $operandSlot;
            }
        }
        $outerProducerIndex = array_search($outerProducer, $block->orig->children, true);
        if (
            is_int($outerProducerIndex)
            && (
                $outerProducer instanceof Op\Expr\FuncCall
                || $outerProducer instanceof Op\Expr\NsFuncCall
            )
        ) {
            $execReturn = $this->slotForInlineFuncCallProducerExecReturnByCfgIndex(
                $block,
                $outerProducerIndex,
                $block->orig->children
            );
            if (null !== $execReturn) {
                return (string) $execReturn;
            }
        }
        $execReturn = $this->slotForSiblingInlineCallProducerExecReturnByExpr(
            $block,
            $outerProducer,
            $cfgCallOp,
            $block->orig->children
        );
        if (null !== $execReturn) {
            return (string) $execReturn;
        }
        $slot = $block->slotForOperand($outerProducer->result);

        return null !== $slot ? (string) $slot : null;
    }

    /**
     * Map dead inline ?: call-arg temps to the innermost ?: merge phi slots for this call (#15816, #22732).
     *
     * php-cfg writes Phi into Temporary->ops for ?: args and ConstFetch for trailing true/false/null.
     * Only Phi-written args consume ternary merge phi slots — counting all dead temps made
     * `f(cond ? a : b, true)` fail the phiSlots>=deadTempCount guard (#22732).
     */
    private function resolveNestedTernaryMergeCallArgSlot(
        Block $block,
        ?Op $cfgCallOp,
        int $argIndex,
        Operand $arg
    ): ?string {
        if (null === $cfgCallOp || !property_exists($cfgCallOp, 'args') || !\is_array($cfgCallOp->args)) {
            return null;
        }
        if (!$this->callArgIsDeadInlineTemporary($arg) || !$this->callArgTemporaryIsPhiWritten($arg)) {
            return null;
        }
        $phiArgIndexes = [];
        foreach ($cfgCallOp->args as $i => $callArg) {
            if (
                $callArg instanceof Operand
                && $this->callArgIsDeadInlineTemporary($callArg)
                && $this->callArgTemporaryIsPhiWritten($callArg)
            ) {
                $phiArgIndexes[] = (int) $i;
            }
        }
        if ([] === $phiArgIndexes) {
            return null;
        }
        // Multi-?: call args (#15816) or mixed ?: + scalar ConstFetch (#22732) both need remapping.
        // Lone single-arg ?: already wires via compileOperand — only engage when a sibling dead temp
        // (ConstFetch / another Phi) shares the call, matching the historic deadTempCount>=2 gate.
        if (1 === \count($phiArgIndexes)) {
            $siblingDeadTemp = false;
            foreach ($cfgCallOp->args as $i => $callArg) {
                if ((int) $i === $phiArgIndexes[0]) {
                    continue;
                }
                if ($callArg instanceof Operand && $this->callArgIsDeadInlineTemporary($callArg)) {
                    $siblingDeadTemp = true;
                    break;
                }
            }
            if (!$siblingDeadTemp) {
                return null;
            }
        }
        $phiSlots = [];
        foreach ($this->ternaryMergePhiRhsSlots as $mergeCfg) {
            $phi = $this->ternaryMergePhiRhsSlots[$mergeCfg];
            if (null !== $phi) {
                $phiSlots[] = $phi;
            }
        }
        $phiSlots = array_values(array_unique($phiSlots));
        $phiArgCount = \count($phiArgIndexes);
        if (\count($phiSlots) < $phiArgCount) {
            return null;
        }
        $phiSlots = \array_slice($phiSlots, -$phiArgCount);
        $ordinal = \array_search($argIndex, $phiArgIndexes, true);
        if (false === $ordinal || $ordinal >= \count($phiSlots)) {
            return null;
        }

        return (string) $phiSlots[$ordinal];
    }

    /** php-cfg Temporary written by a Phi — ?: / short-circuit merge result (#22732). */
    private function callArgTemporaryIsPhiWritten(?Operand $arg): bool
    {
        if (null === $arg) {
            return false;
        }
        foreach ($arg->ops ?? [] as $embedded) {
            if ($embedded instanceof Op\Phi) {
                return true;
            }
        }

        return false;
    }

    /** php-cfg Temporary written by a hoisted true/false/null ConstFetch (#22732). */
    private function callArgTemporaryIsScalarConstFetchWritten(?Operand $arg): bool
    {
        if (null === $arg) {
            return false;
        }
        foreach ($arg->ops ?? [] as $embedded) {
            if (!$embedded instanceof Op\Expr\ConstFetch) {
                continue;
            }
            $name = $this->staticNameFromOperand($embedded->name);
            if (null !== $name && \in_array(strtolower($name), ['true', 'false', 'null'], true)) {
                return true;
            }
        }

        return false;
    }


    /**
     * Sole writer on a dead call-arg temp — Array_ / ConstFetch / ClassConstFetch (#25337).
     *
     * When a sibling arg is ?: Phi-written, JumpIf merge prebind can make compileOperand
     * resolve the non-Phi temp to the ternary phi slot (array_merge([1], $x?[2]:[3]),
     * twoway(FLAG, 'C'?:'D')). Prefer the embedded writer instead.
     */
    private function soleEmbeddedWriterOnCallArgTemp(?Operand $arg): ?Op\Expr
    {
        if (null === $arg || !$this->callArgIsDeadInlineTemporary($arg)) {
            return null;
        }
        if ($this->callArgTemporaryIsPhiWritten($arg)) {
            return null;
        }
        $ops = $arg->ops ?? [];
        if (1 !== \count($ops) || !($ops[0] instanceof Op\Expr)) {
            return null;
        }
        $writer = $ops[0];
        if (
            $writer instanceof Op\Expr\Array_
            || $writer instanceof Op\Expr\ConstFetch
            || $writer instanceof Op\Expr\ClassConstFetch
        ) {
            return $writer;
        }

        return null;
    }

    /** True when another dead call arg on this call is ?: Phi-written (#25337). */
    private function cfgCallHasPhiWrittenDeadTempSibling(Op $cfgCallOp, int $argIndex): bool
    {
        if (!property_exists($cfgCallOp, 'args') || !\is_array($cfgCallOp->args)) {
            return false;
        }
        foreach ($cfgCallOp->args as $i => $candidate) {
            if ((int) $i === $argIndex || !($candidate instanceof Operand)) {
                continue;
            }
            if (
                $this->callArgIsDeadInlineTemporary($candidate)
                && $this->callArgTemporaryIsPhiWritten($candidate)
            ) {
                return true;
            }
        }

        return false;
    }

    /**
     * Wire non-Phi dead temps beside ?: to their sole embedded writer slot (#25337).
     *
     * @param list<OpCode> $emitOps
     */
    private function resolveNonPhiSiblingOfTernaryCallArgSlot(
        Block $block,
        Op $cfgCallOp,
        int $argIndex,
        Operand $arg,
        array &$emitOps
    ): ?string {
        if (!$this->cfgCallHasPhiWrittenDeadTempSibling($cfgCallOp, $argIndex)) {
            return null;
        }
        $writer = $this->soleEmbeddedWriterOnCallArgTemp($arg);
        if (null === $writer || null === $writer->result) {
            return null;
        }
        $ternaryPhiSlots = [];
        foreach ($this->ternaryMergePhiRhsSlots as $mergeCfg) {
            $phi = $this->ternaryMergePhiRhsSlots[$mergeCfg];
            if (null !== $phi) {
                $ternaryPhiSlots[(string) $phi] = true;
            }
        }
        if ($writer instanceof Op\Expr\Array_) {
            $slot = $block->slotForOperand($writer->result);
            // Prebind may alias the Array_ result onto the ternary phi — emit a fresh INIT_ARRAY.
            if (null === $slot || isset($ternaryPhiSlots[(string) $slot])) {
                $arrayOps = $this->compileArrayLiteral($writer, $block);
                if ([] !== $arrayOps) {
                    $emitOps = array_merge($emitOps, $arrayOps);
                }
                $slot = $this->slotFromInitArrayLiteralOps($arrayOps)
                    ?? $block->slotForOperand($writer->result);
            }

            return null !== $slot ? (string) $slot : null;
        }
        if ($writer instanceof Op\Expr\ConstFetch) {
            $folded = $this->tryFoldGlobalConstFetch($writer);
            if (null !== $folded) {
                return (string) $block->registerConstant(new Operand\Temporary(), $folded);
            }
        }
        $slot = $block->slotForOperand($writer->result);
        if (null !== $slot && !isset($ternaryPhiSlots[(string) $slot])) {
            return (string) $slot;
        }
        foreach ($this->compileExpr($writer, $block) as $op) {
            $emitOps[] = $op;
        }
        $slot = $block->slotForOperand($writer->result);
        if (null !== $slot && !isset($ternaryPhiSlots[(string) $slot])) {
            return (string) $slot;
        }

        return null;
    }

    /**
     * Hoisted ConstFetch wired to this positional arg must keep its slot (#15833).
     * probe('label', in_array(..., g(), true)) — ConstFetch feeds inner callee, not outer (#14237).
     */
    private function shouldRemapHoistedConstFetchToAdjacentNestedCall(
        Op\Expr $matched,
        Op $cfgCallOp,
        int $argIndex,
        ?Block $block = null
    ): bool {
        if (!$matched instanceof Op\Expr\ConstFetch) {
            return true;
        }
        if (!property_exists($cfgCallOp, 'args') || !\is_array($cfgCallOp->args)) {
            return true;
        }
        $callArg = $cfgCallOp->args[$argIndex] ?? null;
        if (
            null !== $callArg
            && null !== $matched->result
            && $this->operandsReferToSameVariable($matched->result, $callArg)
        ) {
            return false;
        }
        if (null !== $block && null !== $block->orig) {
            $producers = $this->precedingInlineCallArgProducersBeforeCfgOp($block->orig->children, $cfgCallOp);
            $split = $this->splitLeadingConstFetchWithFuncCallCallArg($producers);
            if (null !== $split) {
                [$constFetch] = $split;
                if ($matched === $constFetch) {
                    $nonEmbeddedArgIndices = [];
                    foreach ($cfgCallOp->args as $i => $candidate) {
                        if (!$this->isEmbeddedCallLiteralArg($candidate)) {
                            $nonEmbeddedArgIndices[] = (int) $i;
                        }
                    }
                    if (0 === array_search($argIndex, $nonEmbeddedArgIndices, true)) {
                        return false;
                    }
                }
            }
        }

        return true;
    }

    /**
     * date_sunrise(time(), SUNFUNCS_RET_*, …) / date_sun_info(strtotime(...), lat, -lon) — hoisted FuncCall + prelude slots (#13749, #11070, #11336).
     */
    private function wireDateSunFuncHoistedCallArgSlot(Block $block, Op $cfgCallOp, int $argIndex): ?string
    {
        if (null === $block->orig) {
            return null;
        }
        $callee = strtolower($this->resolveCfgFuncCallName($cfgCallOp) ?? '');
        $isDateSunInfo = 'date_sun_info' === $callee;
        if (!\in_array($callee, ['date_sunrise', 'date_sunset', 'date_sun_info'], true)) {
            return null;
        }
        if (0 === $argIndex) {
            $callIndex = null;
            foreach ($block->orig->children as $i => $child) {
                if ($child === $cfgCallOp) {
                    $callIndex = $i;
                    break;
                }
            }
            if (null === $callIndex) {
                return null;
            }
            for ($i = $callIndex - 1; $i >= 0; --$i) {
                $child = $block->orig->children[$i];
                if ($child instanceof Op\Expr\Assign) {
                    return null;
                }
                if (!$child instanceof Op\Expr\FuncCall && !$child instanceof Op\Expr\NsFuncCall) {
                    continue;
                }
                $producerName = strtolower($this->resolveCfgFuncCallName($child) ?? '');
                if (!\in_array($producerName, ['time', 'gmmktime', 'strtotime'], true)) {
                    return null;
                }
                $producerIndex = $i;
                $execReturn = $this->slotForSiblingInlineCallProducerExecReturnByExpr(
                    $block,
                    $child,
                    $cfgCallOp,
                    $block->orig->children
                );
                if (null !== $execReturn) {
                    return (string) $execReturn;
                }
                $execReturn = $this->slotForInlineFuncCallProducerExecReturnByCfgIndex(
                    $block,
                    $producerIndex,
                    $block->orig->children
                );
                if (null !== $execReturn) {
                    return (string) $execReturn;
                }
                $operandSlot = $block->slotForOperand($child->result);
                if (null !== $operandSlot) {
                    return (string) $operandSlot;
                }
                if (null === $block->slotForOperand($child->result)) {
                    $prevForce = $this->forceDeferredSiblingCallReturnSlot;
                    $this->forceDeferredSiblingCallReturnSlot = true;
                    try {
                        foreach ($this->compileExpr($child, $block) as $op) {
                            $block->addOpCode($op);
                        }
                    } finally {
                        $this->forceDeferredSiblingCallReturnSlot = $prevForce;
                    }
                }
                $execReturn = $this->slotForSiblingInlineCallProducerExecReturnByExpr(
                    $block,
                    $child,
                    $cfgCallOp,
                    $block->orig->children
                );
                if (null !== $execReturn) {
                    return (string) $execReturn;
                }
                $execReturn = $this->slotForInlineFuncCallProducerExecReturnByCfgIndex(
                    $block,
                    $producerIndex,
                    $block->orig->children
                );
                if (null !== $execReturn) {
                    return (string) $execReturn;
                }
                $operandSlot = $block->slotForOperand($child->result);

                return null !== $operandSlot ? (string) $operandSlot : null;
            }

            return null;
        }
        $longitudeArgIndex = $isDateSunInfo ? 2 : 3;
        if ($longitudeArgIndex === $argIndex) {
            foreach ($this->hoistedPreludeProducersImmediatelyBeforeCall($cfgCallOp, $block) as $prelude) {
                if (!$prelude instanceof Op\Expr\UnaryMinus && !$prelude instanceof Op\Expr\UnaryPlus) {
                    continue;
                }
                $existing = $block->slotForOperand($prelude->result);
                if (null !== $existing) {
                    return (string) $existing;
                }
                $folded = $this->tryFoldUnaryLiteralDefault($prelude);
                if (null === $folded) {
                    continue;
                }

                return (string) $block->registerConstant($prelude->result, $folded);
            }

            return null;
        }
        if ($isDateSunInfo || 1 !== $argIndex) {
            return null;
        }
        foreach ($this->hoistedPreludeProducersImmediatelyBeforeCall($cfgCallOp, $block) as $prelude) {
            if (!$prelude instanceof Op\Expr\ConstFetch) {
                continue;
            }
            $name = strtolower($this->staticNameFromOperand($prelude->name) ?? '');
            if (!str_starts_with($name, 'sunfuncs_ret_')) {
                continue;
            }
            $existing = $block->slotForOperand($prelude->result);
            if (null !== $existing) {
                return (string) $existing;
            }
            $folded = $this->tryFoldGlobalConstFetch($prelude);
            if (null === $folded) {
                continue;
            }

            return (string) $block->registerConstant($prelude->result, $folded);
        }

        return null;
    }

    /**
     * array_splice($a, -N, $len, null) — UnaryMinus offset + null replacement (#16328, #10589).
     *
     * @param list<OpCode> $emitOps
     */
    private function wireArraySpliceUnaryOffsetReplacementCallArgSlot(
        Block $block,
        Op $cfgCallOp,
        int $argIndex,
        array &$emitOps = []
    ): ?string {
        if (null === $block->orig) {
            return null;
        }
        if ('array_splice' !== strtolower($this->resolveCfgFuncCallName($cfgCallOp) ?? '')) {
            return null;
        }
        if (!\is_array($cfgCallOp->args ?? null) || \count($cfgCallOp->args) < 4) {
            return null;
        }
        $producers = $this->precedingInlineCallArgProducersBeforeCfgOp($block->orig->children, $cfgCallOp);
        $target = $this->matchArraySpliceUnaryOffsetReplacementProducers(
            $producers,
            $argIndex,
            \count($cfgCallOp->args),
            'array_splice'
        );
        if (!$target instanceof Op\Expr) {
            return null;
        }
        if ($target instanceof Op\Expr\ConstFetch) {
            $folded = $this->tryFoldGlobalConstFetch($target);
            if (null !== $folded) {
                return (string) $block->registerConstant(new Operand\Temporary(), $folded);
            }
        } elseif ($target instanceof Op\Expr\UnaryMinus || $target instanceof Op\Expr\UnaryPlus) {
            $folded = $this->tryFoldUnaryLiteralDefault($target);
            if (null !== $folded) {
                return (string) $block->registerConstant(new Operand\Temporary(), $folded);
            }
        }
        $slot = $block->slotForOperand($target->result);
        if (null === $slot) {
            foreach ($this->compileExpr($target, $block) as $op) {
                $emitOps[] = $op;
            }
            $slot = $block->slotForOperand($target->result);
        }

        return null !== $slot ? (string) $slot : null;
    }

