        $sends = $producerOps;
        foreach ($args as $argIndex => $arg) {
            $nameSlot = $this->callArgNameSlot($arg, $block);
            $valueSlot = 0 === (int) $argIndex ? (string) $assignSlot : (string) $callbackSlot;
            $sends[] = new OpCode(OpCode::TYPE_ARG_SEND, $valueSlot, $nameSlot, null);
        }

