        }
        $callback = $block->orig->children[$callIndex - 1] ?? null;
        if (
            !$callback instanceof Op\Expr\ArrowFunction
            && !$callback instanceof Op\Expr\Closure
            && !$callback instanceof Op\Expr\FirstClassCallable
