            }
            if (null === $valueSlot) {
                $valueSlot = $this->compileOperand($arg, $block, true);
            }
            $sends[] = new OpCode(
                OpCode::TYPE_ARG_SEND,
                $valueSlot,
                $this->callArgNameSlot($arg, $block),
                $this->callArgUnpack($arg) ? 1 : null
            );
        }

        return array_merge($producerOps, $sends);
    }

