                            $valueSlot = (string) $callbackSlot;
                        }
                    } elseif (
                        null !== $producerOrdinal
                        && $producerOrdinal < $chainProducerCount
                        && null === $valueSlot
                        && !$this->callArgHasHoistedConstPrelude($cfgCallOp, (int) $argIndex, $block)
                    ) {
                        $execReturnCount = 0;
                        foreach ($block->opCodes as $op) {
                            if (OpCode::TYPE_FUNCCALL_EXEC_RETURN === $op->type && null !== $op->arg1) {
                                ++$execReturnCount;
                            }
                        }
                        $execOrdinal = $execReturnCount - $chainProducerCount + $producerOrdinal;
                        $forcedSiblingSlot = $this->slotForSiblingInlineFuncCallProducerExecReturnOrdinal(
                            $block,
                            $execOrdinal
                        );
                        if (null !== $forcedSiblingSlot) {
                            $valueSlot = (string) $forcedSiblingSlot;
                        }
                    }
                }
                $forcedSiblingSlot = $this->finalSiblingInlineCallArgSendSlot($block, $cfgCallOp, (int) $argIndex);
                if (null === $forcedSiblingSlot) {
                    $forcedSiblingOps = [];
                    $forcedSiblingSlot = $this->resolveSiblingInlineCallArgProducerSlot(
                        $block,
                        $cfgCallOp,
                        (int) $argIndex,
                        $forcedSiblingOps
                    );
                    if ([] !== $forcedSiblingOps) {
                        $sends = array_merge($sends, $forcedSiblingOps);
                    }
                }
                if (null !== $forcedSiblingSlot) {
                    if (
                        0 === (int) $argIndex
                        && (
                            $inlineArrayLiteralArgWired
                            || $this->arrayMergeFamilyLeadingInlineArrayArgUsesHoistedArray($cfgCallOp, (int) $argIndex, $block)
                        )
                    ) {
                        if (null === $valueSlot) {
                            $mergeProducers = $this->arrayMergeFamilyInlineProducersForCfgCall(
                                $block->orig->children,
                                $cfgCallOp
                            );
                            $leadingMapped = $this->matchArrayMergeFamilyFullInlineCallArgProducer(
                                $mergeProducers,
                                0,
                                \count($cfgCallOp->args ?? []),
                                is_array($cfgCallOp->args ?? null) ? $cfgCallOp->args : []
                            );
                            if ($leadingMapped instanceof Op\Expr\Array_) {
                                $leadingSlot = $block->slotForOperand($leadingMapped->result)
                                    ?? $this->slotForInitArrayOrdinal($block, 0, $sends);
                                if (null !== $leadingSlot) {
                                    $valueSlot = (string) $leadingSlot;
                                }
                            }
                        }
                    } elseif (
                        null === $valueSlot
                        && null === $constPreludeSlot
                        && !$this->callArgHasHoistedConstPrelude($cfgCallOp, (int) $argIndex, $block)
                    ) {
                        $valueSlot = (string) $forcedSiblingSlot;
                    }
                }
            }
            if (
                null !== $cfgCallOp
                && null !== $block->orig
                && \in_array(
                    strtolower($this->resolveCfgFuncCallName($cfgCallOp) ?? ''),
                    ['array_intersect', 'array_diff', 'array_intersect_key', 'array_diff_key'],
                    true
                )
                && $this->countDeadArrayInlineCallArgs($cfgCallOp) >= 2
            ) {
                $multiOuterExec = $this->outerSiblingInlineCallArgProducerExecReturnSlot(
                    $block,
                    $cfgCallOp,
                    (int) $argIndex
                );
                if (null !== $multiOuterExec) {
                    $valueSlot = $multiOuterExec;
                }
            }
            $literalProbe = ($cfgCallOp->args[(int) $argIndex] ?? null) ?? $arg;
            if ($this->isEmbeddedCallLiteralArg($literalProbe)) {
                // Must run after sibling/adjacent wiring — do not alias prior EXEC_RETURN (#16254, array_slice #10229).
                $valueSlot = (string) $this->freshLiteralConstantSlot($literalProbe, $block);
            }
            $sendProbe = $literalProbe;
            $sendName = Block::resolveVariableName($sendProbe);
            if (null !== $sendName && '' !== $sendName) {
                $paramSlot = $block->paramSlotForName($sendName);
                if (null !== $paramSlot) {
                    $valueSlot = (string) $this->finalizeOperandSlotForAccess($block, $paramSlot, true);
                }
            }
            $postSuppressAssignSlot = $this->slotForPostErrorSuppressAssignNamedLocalCallArg($sendProbe, $block);
            if (null !== $postSuppressAssignSlot) {
                $valueSlot = (string) $postSuppressAssignSlot;
            }
            // substr(sprintf('%o', fileperms($path)), -N) — adjacent nested wiring must not clobber named path locals (#13636, #16055).
            $sendNamedLocalSlot = $this->namedLocalCallArgSlotIfBound(
                $sendProbe,
                $block,
                $cfgCallOp,
                (int) $argIndex
            ) ?? $this->slotForNamedLocalFromAssignVarOperand($sendProbe, $block);
            if (null !== $sendNamedLocalSlot) {
                if (
                    $this->callArgIsDeadInlineTemporary($sendProbe)
                    && null !== $valueSlot
                    && null !== $cfgCallOp
                    && \count($cfgCallOp->args ?? []) >= 2
                    && $this->hasSiblingMultiArgInlineCallProducers($block, $cfgCallOp)
                ) {
                    // Keep sibling/nested EXEC_RETURN wiring — do not remap dead temps to $path locals (#16480).
                } else {
                    $sendNamedAssignDest = $block->slotForNamedAssignDest($sendProbe);
                    $valueSlot = null !== $sendNamedAssignDest
                        ? $this->resolveNamedAssignCallArgSlot(
                            $block,
                            (int) $sendNamedAssignDest,
                            $calleeName,
                            (int) $argIndex,
                            $sendProbe
                        )
                        : (string) $this->finalizeOperandSlotForAccess($block, (int) $sendNamedLocalSlot, true);
                }
            }
            // probe('label', in_array(...)) — lone nested callee EXEC_RETURN, not strict/haystack operand (#16312).
            if (
                null !== $cfgCallOp
                && null !== $block->orig
                && \is_array($cfgCallOp->args ?? null)
                && $this->callArgIsDeadInlineTemporary($sendProbe)
            ) {
                $deadTempCount = 0;
                foreach ($cfgCallOp->args as $deadArg) {
                    if ($this->callArgIsDeadInlineTemporary($deadArg)) {
                        ++$deadTempCount;
                    }
                }
                if (1 === $deadTempCount) {
                    $callIndex = array_search($cfgCallOp, $block->orig->children, true);
                    if (\is_int($callIndex) && $callIndex > 0) {
                        $adjacentIndex = $callIndex - 1;
                        while ($adjacentIndex >= 0) {
                            $skip = $block->orig->children[$adjacentIndex] ?? null;
                            if ($skip instanceof Op\Expr\ConstFetch || $skip instanceof Op\Expr\ClassConstFetch) {
                                --$adjacentIndex;
                                continue;
                            }
                            break;
                        }
                        $adjacent = $block->orig->children[$adjacentIndex] ?? null;
                        if (
                            ($adjacent instanceof Op\Expr\FuncCall || $adjacent instanceof Op\Expr\NsFuncCall)
                            && $this->isAdjacentNestedFuncCallProducer(
                                $adjacent,
                                $cfgCallOp,
                                $adjacentIndex,
                                $callIndex
                            )
                        ) {
                            $singleNestedExec = $this->slotForLastPendingInlineCallResultBeforeFuncCallInit($sends)
                                ?? $this->slotForLastEmittedInlineCallResultBeforePendingFuncCall($block);
                            if (null !== $singleNestedExec) {
                                $valueSlot = (string) $singleNestedExec;
                            }
                        }
                    }
                }
            }
            if (
                null !== $cfgCallOp
                && null !== $block->orig
                && 0 === (int) $argIndex
                && 'array_pad' === strtolower($this->resolveCfgFuncCallName($cfgCallOp) ?? '')
                && $this->callArgIsDeadInlineTemporary($sendProbe)
            ) {
                $padHaystackSlot = $this->slotForInitArrayOrdinal($block, 0, $sends);
                if (null !== $padHaystackSlot) {
                    $valueSlot = $padHaystackSlot;
                    $inlineArrayLiteralArgWired = true;
                }
            }
            if (
                null !== $cfgCallOp
                && null !== $block->orig
                && 0 === (int) $argIndex
                && \in_array(
                    strtolower($this->resolveCfgFuncCallName($cfgCallOp) ?? ''),
                    ['array_merge', 'array_merge_recursive', 'array_replace', 'array_replace_recursive'],
                    true
                )
                && null === $valueSlot
                && $this->arrayMergeHasLeadingInlineArrayBeforeArrayKeysSibling($block, $cfgCallOp)
            ) {
                $leadingMergeFinalSlot = $this->slotForInitArrayOrdinal($block, 0, $sends);
                if (null !== $leadingMergeFinalSlot) {
                    $valueSlot = $leadingMergeFinalSlot;
                    $inlineArrayLiteralArgWired = true;
                }
            }
            if (
                null !== $cfgCallOp
                && null !== $block->orig
                && $this->callArgIsDeadInlineTemporary($sendProbe)
                && $this->callArgUsesHaystackFamilyArrayProducerResolution(
                    $cfgCallOp,
                    (int) $argIndex,
                    $calleeName,
                    $sendProbe
                )
                && !(
                    0 === (int) $argIndex
                    && \in_array(
                        strtolower($this->resolveCfgFuncCallName($cfgCallOp) ?? ''),
                        ['array_merge', 'array_merge_recursive', 'array_replace', 'array_replace_recursive'],
                        true
                    )
                    && null !== $this->matchArrayMergeFuncCallAndArrayInlineProducers(
                        $this->arrayMergeFamilyInlineProducersForCfgCall($block->orig->children, $cfgCallOp),
                        0
                    )
                )
            ) {
                $haystackSiblingEmit = [];
                $haystackExecSlot = $this->resolveSiblingInlineCallArgProducerSlot(
                    $block,
                    $cfgCallOp,
                    (int) $argIndex,
                    $haystackSiblingEmit
                );
                if (null !== $haystackExecSlot) {
                    if (
                        0 === (int) $argIndex
                        && \in_array(
                            strtolower($this->resolveCfgFuncCallName($cfgCallOp) ?? ''),
                            ['array_merge', 'array_merge_recursive', 'array_replace', 'array_replace_recursive'],
                            true
                        )
                        && $inlineArrayLiteralArgWired
                        && null !== $valueSlot
                    ) {
                        // array_merge(['a'=>1], array_keys(...)) — arg #0 stays on leading INIT_ARRAY (#13760, #16418).
                    } else {
                        $valueSlot = (string) $haystackExecSlot;
                    }
                }
            }
            if (null !== $cfgCallOp && null !== $block->orig) {
                $finalIssetEmptySlot = $this->resolveHoistedIssetOrEmptyCallArgSlot(
                    $arg,
                    $block,
                    $cfgCallOp,
                    (int) $argIndex
                );
                if (null !== $finalIssetEmptySlot) {
                    $valueSlot = (string) $finalIssetEmptySlot;
                } else {
                    $inlineLiteralDimSlot = $this->resolveInlineArrayLiteralDimFetchCallArgSlot(
                        $block,
                        $cfgCallOp,
                        (int) $argIndex
                    );
                    if (null !== $inlineLiteralDimSlot) {
                        $valueSlot = $inlineLiteralDimSlot;
                    }
                }
            }
            if (
                null !== $cfgCallOp
                && null !== $block->orig
                && 'substr' === strtolower($this->resolveInlineCallArgFuncName($cfgCallOp, $calleeName) ?? '')
            ) {
                $nestedExecSlot = $this->wireSubstrNestedSprintfCallArgSlot($block, $cfgCallOp, (int) $argIndex, $calleeName)
                    ?? $this->resolveAdjacentNestedFuncCallArgSlot(
                        $block,
                        $cfgCallOp,
                        (int) $argIndex
                    ) ?? $this->finalSiblingInlineCallArgSendSlot($block, $cfgCallOp, (int) $argIndex);
                if (null !== $nestedExecSlot) {
                    $valueSlot = $nestedExecSlot;
                }
            }
            if (
                null !== $cfgCallOp
                && $this->isEmbeddedCallLiteralArg($cfgCallOp->args[(int) $argIndex] ?? null)
            ) {
                $valueSlot = $this->compileOperand($cfgCallOp->args[(int) $argIndex], $block, true);
            } elseif (null !== $cfgCallOp && null !== $block->orig) {
                $unaryTailSlot = $this->slotForImmediateUnaryHoistedCallArg(
                    $block,
                    $cfgCallOp,
                    (int) $argIndex,
                    $calleeName
                );
                if (null !== $unaryTailSlot) {
                    $valueSlot = $unaryTailSlot;
                }
            }
            if (
                null !== $cfgCallOp
                && 0 === (int) $argIndex
                && \in_array(
                    strtolower($this->resolveCfgFuncCallName($cfgCallOp) ?? ''),
                    ['is_array', 'count', 'array_keys'],
                    true
                )
            ) {
                $arrayBuiltinArg = $cfgCallOp->args[0] ?? $arg;
                if ($arrayBuiltinArg instanceof Operand && $this->callArgIsDeadInlineTemporary($arrayBuiltinArg)) {
                    $namedLocalSlot = $this->namedLocalCallArgSlotIfBound(
                        $arrayBuiltinArg,
                        $block,
                        $cfgCallOp,
                        (int) $argIndex
                    ) ?? $this->slotForNamedLocalFromAssignVarOperand($arrayBuiltinArg, $block);
                    if (null !== $namedLocalSlot) {
                        $valueSlot = (string) $this->finalizeOperandSlotForAccess($block, (int) $namedLocalSlot, true);
                    } else {
                        $nestedFileSlot = null;
                        $callIndex = $this->cfgCallOpIndex($block, $cfgCallOp);
                        if (\is_int($callIndex) && $callIndex > 0 && null !== $block->orig) {
                            $immediate = $block->orig->children[$callIndex - 1] ?? null;
                            if (
                                ($immediate instanceof Op\Expr\FuncCall || $immediate instanceof Op\Expr\NsFuncCall)
                                && $this->isNestedCallArgProducerForConsumer(
                                    $immediate,
                                    $cfgCallOp,
                                    $callIndex - 1,
                                    $callIndex,
                                    $block->orig->children
                                )
                            ) {
                                $nestedFileSlot = $this->slotForInlineFuncCallProducerExecReturnByCfgIndex(
                                    $block,
                                    $callIndex - 1,
                                    $block->orig->children
                                );
                            }
                        }
                        $nestedFileSlot ??= $this->resolveAdjacentNestedFuncCallArgSlot(
                            $block,
                            $cfgCallOp,
                            (int) $argIndex
                        );
                        if (null !== $nestedFileSlot) {
                            $valueSlot = (string) $nestedFileSlot;
                        }
                    }
                }
            }
            if (null !== $cfgCallOp && !$this->isEmbeddedCallLiteralArg($arg)) {
                $pendingDimFetchSlot = null;
                if (null !== $dimFetchSlot) {
                    // stream_set_blocking($pipes[1], false) — dim-fetch slot is arg #0 only (#18186).
                    $pendingDimFetchSlot = $this->lastPendingCallArgArrayDimFetchSlot($block, $sends);
                    if (null === $pendingDimFetchSlot) {
                        $pendingDimFetchSlot = $this->pendingCallArgArrayDimFetchSlot($block, $sends, 0);
                    }
                } elseif ($this->callArgIsDeadInlineHaystackFamilySlot(
                    $cfgCallOp,
                    (int) $argIndex,
                    $calleeName,
                    $arg
                )) {
                    $pendingDimFetchSlot = $this->pendingCallArgArrayDimFetchSlot($block, $sends, 0);
                }
                if (null !== $pendingDimFetchSlot) {
                    $immediatePropertySlot = $this->slotForImmediatePropertyOrMethodFetchBeforeCfgCall(
                        $block,
                        $cfgCallOp,
                        false
                    );
                    // The pending scan returns the LAST dim-fetch read, which belongs to the trailing
                    // argument. Applying it to every index made t2($r['a'], $r['b']) send $r['b'] twice
                    // (#23354). Earlier arguments keep the per-index slot resolved above; the override
                    // still runs when nothing else produced one, so it stays a fallback.
                    if (
                        null === $immediatePropertySlot
                        && (
                            null === $valueSlot
                            || (int) $argIndex === $this->trailingNonEmbeddedCallArgIndex($cfgCallOp)
                        )
                    ) {
                        $valueSlot = (string) $pendingDimFetchSlot;
                    }
                }
            }
            if (
                null !== $cfgCallOp
                && null !== $block->orig
            ) {
                $comparisonSlot = $this->slotForComparisonPreludeDeadInlineCallArg(
                    $block,
                    $cfgCallOp,
                    (int) $argIndex,
                    $sends
                );
                if (null !== $comparisonSlot) {
                    $valueSlot = $comparisonSlot;
                }
            }
            if (
                null !== $cfgCallOp
                && null !== $block->orig
                && \in_array(
                    strtolower($this->resolveCfgFuncCallName($cfgCallOp) ?? ''),
                    ['array_merge', 'array_merge_recursive', 'array_replace', 'array_replace_recursive'],
                    true
                )
            ) {
                $mergeForcedSlot = $this->finalizeArrayMergeFamilyCallArgSlot(
                    $block,
                    $cfgCallOp,
                    (int) $argIndex,
                    $sends
                );
                if (null !== $mergeForcedSlot) {
                    $valueSlot = $mergeForcedSlot;
                }
            }
            if (null !== $cfgCallOp) {
                $leadingConstFuncPreludeEmit = [];
                $leadingConstFuncPreludeSlot = $this->finalizeLeadingConstFetchFuncCallPreludeCallArgSlot(
                    $block,
                    $cfgCallOp,
                    (int) $argIndex,
                    $leadingConstFuncPreludeEmit
                );
                if ([] !== $leadingConstFuncPreludeEmit) {
                    $sends = array_merge($sends, $leadingConstFuncPreludeEmit);
                }
                if (null !== $leadingConstFuncPreludeSlot) {
                    $valueSlot = $leadingConstFuncPreludeSlot;
                }
            }
            if (null !== $cfgCallOp) {
                $immediatePropertySlot = $this->slotForImmediatePropertyOrMethodFetchBeforeCfgCall(
                    $block,
                    $cfgCallOp,
                    false
                );
                if (
                    null !== $immediatePropertySlot
                    && $this->callArgIsDeadInlineTemporary($callArgOperand ?? $arg)
                ) {
                    $valueSlot = $immediatePropertySlot;
                }
            }
            $syncedFinalArgSlot = $this->resolveSyncedCoalesceFuncCallArgSlot($callArgOperand ?? $arg);
            if (null !== $syncedFinalArgSlot) {
                $valueSlot = (string) $syncedFinalArgSlot;
            }
            if (
                null !== $cfgCallOp
                && 0 === (int) $argIndex
                && 'var_export' === strtolower($this->resolveCfgFuncCallName($cfgCallOp) ?? '')
                && $this->callArgIsDeadInlineTemporary($cfgCallOp->args[0] ?? null)
                && null !== $block->orig
            ) {
                $hoistedScalarArgSlot = $this->slotForVarExportHoistedScalarConstArgZero(
                    $block,
                    $cfgCallOp,
                    $sends
                );
                if (null !== $hoistedScalarArgSlot) {
                    $valueSlot = $hoistedScalarArgSlot;
                }
            }
            if (null !== $cfgCallOp && null !== $block->orig) {
                $bitmaskArgProbe = $cfgCallOp->args[(int) $argIndex] ?? $arg;
                $bitmaskSlot = $this->tryResolveInlineBitmaskCallArgSlot(
                    $bitmaskArgProbe,
                    $block,
                    $sends,
                    $cfgCallOp,
                    (int) $argIndex
                );
                if (null === $bitmaskSlot) {
                    $trailingBitmaskArgIndex = $this->trailingNonEmbeddedCallArgIndex($cfgCallOp);
                    $bitmaskCallIndex = array_search($cfgCallOp, $block->orig->children, true);
                    if (\is_int($bitmaskCallIndex) && $bitmaskCallIndex > 0) {
                        $bitmaskImmediate = $block->orig->children[$bitmaskCallIndex - 1] ?? null;
                        if ($bitmaskImmediate instanceof Op\Expr\Assign) {
                            $hoistedRhs = $bitmaskCallIndex > 1
                                ? ($block->orig->children[$bitmaskCallIndex - 2] ?? null)
                                : null;
                            if (
                                $hoistedRhs instanceof Op\Expr\BinaryOp\BitwiseOr
                                || $hoistedRhs instanceof Op\Expr\BinaryOp\BitwiseAnd
                                || $hoistedRhs instanceof Op\Expr\BinaryOp\BitwiseXor
                            ) {
                                $bitmaskImmediate = $hoistedRhs;
                            } else {
                                $bitmaskImmediate = $bitmaskImmediate->expr;
                            }
                        }
                        if (
                            (int) $argIndex === $trailingBitmaskArgIndex
                            && (
                                $bitmaskImmediate instanceof Op\Expr\BinaryOp\BitwiseOr
                                || $bitmaskImmediate instanceof Op\Expr\BinaryOp\BitwiseAnd
                                || $bitmaskImmediate instanceof Op\Expr\BinaryOp\BitwiseXor
                            )
                            && (
                                $this->callArgIsDeadInlineTemporary($bitmaskArgProbe)
                                || $this->callArgIsAssignInCallOperand($bitmaskArgProbe)
                            )
                            && !$this->callArgOperandExpectsArrayProducer($bitmaskArgProbe)
                        ) {
                            $namedDest = $this->slotForHoistedAssignInCallNamedDest($block, $cfgCallOp);
                            if (null !== $namedDest) {
                                $bitmaskSlot = $namedDest;
                            } elseif (null === $block->slotForOperand($bitmaskImmediate->result)) {
                                foreach ($this->compileExpr($bitmaskImmediate, $block) as $op) {
                                    $sends[] = $op;
                                }
                                $bitmaskSlot = $block->slotForOperand($bitmaskImmediate->result);
                            } else {
                                $bitmaskSlot = $block->slotForOperand($bitmaskImmediate->result);
                            }
                        }
                    }
                }
                if (
                    null !== $bitmaskSlot
                    && (int) $argIndex === $this->trailingNonEmbeddedCallArgIndex($cfgCallOp)
                ) {
                    $valueSlot = (string) $bitmaskSlot;
                }
            }
            if (null !== $nullLiteralCallArgSlot) {
                $valueSlot = $nullLiteralCallArgSlot;
            }
            // Last word to the exact argument->producer link (#23354). Every heuristic above resolves
            // a hoisted argument from the statement before the call, which is only ever the TRAILING
            // argument's producer; php-cfg records the real producer as the argument temporary's sole
            // writer, so this is the one mapping that is right by construction rather than by shape.
            $exactSlot = $this->exactHoistedCallArgProducerSlot($block, $cfgCallOp, (int) $argIndex, $sends);
            if (null !== $exactSlot) {
                $valueSlot = $exactSlot;
            }
            // Bare named locals ($x as call arg): CV assign-dest must win over later heuristics
            // that re-bind the call-site clone Temporary to a fresh empty slot (#23893, re-#23354).
            $bareLocalProbe = ($cfgCallOp->args[(int) $argIndex] ?? null) ?? $arg;
            if (
                $bareLocalProbe instanceof Operand
                && null !== Block::resolveVariableName($bareLocalProbe)
                && !$this->callArgIsDeadInlineTemporary($bareLocalProbe)
            ) {
                $bareNamedDest = $block->slotForNamedAssignDest($bareLocalProbe);
                if (null !== $bareNamedDest) {
                    $valueSlot = $this->resolveNamedAssignCallArgSlot(
                        $block,
                        (int) $bareNamedDest,
                        $calleeName,
                        (int) $argIndex,
                        $bareLocalProbe
                    );
                } elseif (null === $valueSlot) {
                    $valueSlot = $this->compileOperand($bareLocalProbe, $block, true);
                }
            }
            // [...new ArrayIterator([...])] as call arg: nested ctor Array_ slot may win over
            // the spread INIT_ARRAY that sits after FUNCCALL_EXEC_RETURN (#24645).
            $callArgProbeFinal = ($cfgCallOp->args[(int) $argIndex] ?? null) ?? $arg;
            if (
                null !== $cfgCallOp
                && $callArgProbeFinal instanceof Operand
                && $this->callArgIsDeadInlineTemporary($callArgProbeFinal)
                && (
                    $this->callArgOperandExpectsArrayProducer($callArgProbeFinal)
                    || $this->callArgIsDeadUnknownOrMixedTemporary($callArgProbeFinal)
                )
            ) {
                $spreadResultSlot = $this->slotForArraySpreadResultAfterLastExecReturn($block, $sends);
                if (null !== $spreadResultSlot) {
                    $valueSlot = $spreadResultSlot;
                }
            }
            // array_merge([1], $x ? [2] : [3]) / twoway(FLAG, 'C' ?: 'D') — non-Phi sibling of
            // ?: must keep Array_/ConstFetch writer slot, not the merge phi (#25337).
            if (null !== $cfgCallOp && \is_array($cfgCallOp->args ?? null)) {
                $ternarySiblingProbe = $cfgCallOp->args[(int) $argIndex] ?? $arg;
                if ($ternarySiblingProbe instanceof Operand) {
                    $ternarySiblingSlot = $this->resolveNonPhiSiblingOfTernaryCallArgSlot(
                        $block,
                        $cfgCallOp,
                        (int) $argIndex,
                        $ternarySiblingProbe,
                        $sends
                    );
                    if (null !== $ternarySiblingSlot) {
                        $valueSlot = $ternarySiblingSlot;
                    }
                }
            }
            $sends[] = new OpCode(OpCode::TYPE_ARG_SEND, $valueSlot, $nameSlot, $unpackFlag);
        }

        return $sends;
    }

    /**
     * in_array()/array_search() haystack — last hoisted Array_ when array_slice also hoists one (#13684, #16084).
     */
    private function matchInlineArraySearchHaystackProducer(array $producers, Operand $haystackArg): ?Op\Expr
    {
        // $arr['k'] ?? [] inline — coalesce merge slot, not ?? RHS empty Array_ (#17980, re-#17000).
        if ([] !== $this->findEmbeddedCoalesces($haystackArg)) {
            return null;
        }
        $arrayProducers = array_values(array_filter(
            $producers,
            static fn (Op\Expr $producer): bool => $producer instanceof Op\Expr\Array_
        ));
        if ([] === $arrayProducers) {
            return null;
        }
        foreach ($arrayProducers as $producer) {
            if ($this->operandsReferToSameVariable($producer->result, $haystackArg)) {
                return $producer;
            }
        }

        return $arrayProducers[\count($arrayProducers) - 1];
    }

    /**
     * substr(sprintf('%o', fileperms($path)), -N) — haystack is nested sprintf EXEC_RETURN (#16451, #16480).
     */
    private function wireSubstrNestedSprintfCallArgSlot(
        Block $block,
        Op $cfgCallOp,
        int $argIndex,
        ?string $calleeName = null
    ): ?string {
        if (
            0 !== $argIndex
            || 'substr' !== strtolower($this->resolveInlineCallArgFuncName($cfgCallOp, $calleeName) ?? '')
            || null === $block->orig
        ) {
            return null;
        }
        $callIndex = array_search($cfgCallOp, $block->orig->children, true);
        if (!\is_int($callIndex) || $callIndex < 1) {
            return null;
        }
        $cfgChildren = $block->orig->children;
        for ($j = $callIndex - 1; $j >= 0; --$j) {
            $scan = $cfgChildren[$j] ?? null;
            if (
                !($scan instanceof Op\Expr\FuncCall || $scan instanceof Op\Expr\NsFuncCall)
                || !$this->isNestedCallArgProducerForConsumer($scan, $cfgCallOp, $j, $callIndex, $cfgChildren)
                || 0 !== $this->siblingMultiArgFuncCallProducerTargetArgIndex($j, $callIndex, $cfgChildren)
            ) {
                continue;
            }
            $nestedName = $this->resolveCfgFuncCallName($scan) ?? '';

            return $this->slotForSubstrNestedHaystackFuncCallExecReturn(
                $block,
                $j,
                $nestedName,
                $cfgChildren
            );
        }
        $nestedHaystack = $this->substrNestedHaystackFuncCallAtUnaryMinusPattern(
            $cfgCallOp,
            $callIndex,
            $cfgChildren
        );
        if (null === $nestedHaystack) {
            return null;
        }

        return $this->slotForSubstrNestedHaystackFuncCallExecReturn(
            $block,
            $nestedHaystack[0],
            $nestedHaystack[1],
            $cfgChildren
        );
    }

    /**
     * array_slice([..], array_search(...)) — outer Array_ + nested int offset (#13684).
     */
    private function resolveArraySliceInlineCallArgSlot(
        Block $block,
        ?Op $cfgCallOp,
        int $argIndex,
        Operand $arg,
        array &$emitOps = []
    ): ?string {
        if (
            null === $cfgCallOp
            || 'array_slice' !== $this->resolveCfgFuncCallName($cfgCallOp)
            || $this->callIncludesNamedParameter($cfgCallOp)
            || !\is_array($cfgCallOp->args ?? null)
            || \count($cfgCallOp->args) < 2
            || null === $block->orig
        ) {
            return null;
        }
        $producers = $this->precedingInlineCallArgProducersBeforeCfgOp(
            $block->orig->children,
            $cfgCallOp
        );
        if (0 === $argIndex) {
            $haystackArg = $cfgCallOp->args[0] ?? $arg;
            if (
                !$haystackArg instanceof Operand
                || !$this->callArgOperandExpectsArrayProducer($haystackArg)
            ) {
                return null;
            }
            $arrayProducers = array_values(array_filter(
                $producers,
                static fn (Op\Expr $producer): bool => $producer instanceof Op\Expr\Array_
            ));
            if ([] === $arrayProducers) {
                return null;
            }
            $arrayExpr = $arrayProducers[0];
            $existingSlot = $block->slotForOperand($arrayExpr->result);
            if (null !== $existingSlot) {
                return (string) $existingSlot;
            }
            $arrayOps = $this->compileArrayLiteral($arrayExpr, $block);
            if ([] !== $arrayOps) {
                foreach ($arrayOps as $op) {
                    $emitOps[] = $op;
                }
            }
            $initSlot = $this->slotFromInitArrayLiteralOps($arrayOps);

            return (string) (
                $initSlot
                ?? $this->firstInitArraySlotInBlock($block)
                ?? '0'
            );
        }
        if (1 !== $argIndex) {
            return null;
        }
        $offsetArg = $cfgCallOp->args[1] ?? $arg;
        // array_slice($b, 1, -2) — embedded literal offset must not steal prior EXEC_RETURN (#10229, #10579).
        if ($this->isEmbeddedCallLiteralArg($offsetArg)) {
            return null;
        }
        if (!$this->callArgIsDeadInlineTemporary($offsetArg)) {
            return null;
        }
        for ($scan = \count($block->opCodes) - 1; $scan >= 0; --$scan) {
            $scanOp = $block->opCodes[$scan];
            if (OpCode::TYPE_FUNCCALL_INIT === $scanOp->type) {
                break;
            }
            if (OpCode::TYPE_FUNCCALL_EXEC_RETURN === $scanOp->type && null !== $scanOp->arg1) {
                return (string) $scanOp->arg1;
            }
        }

        return null;
    }

    /**
     * proc_open(['cmd'], $desc, $pipes, null, ['K'=>'V']) — map command/null/env preludes (#9389, #13734).
     * Three-arg inline nested descriptor_spec uses outermost INIT_ARRAY slot (#11485, #11300).
     */
    private function resolveProcOpenInlineCallArgSlot(
        Block $block,
        ?Op $cfgCallOp,
        int $argIndex,
        array $pendingSends = [],
    ): ?string {
        if (
            null === $cfgCallOp
            || 'proc_open' !== $this->resolveCfgFuncCallName($cfgCallOp)
            || $this->callIncludesNamedParameter($cfgCallOp)
            || !\is_array($cfgCallOp->args ?? null)
        ) {
            return null;
        }
        $argCount = \count($cfgCallOp->args);
        if ($argCount >= 3 && $argCount < 5) {
            if (0 === $argIndex) {
                return $this->resolveProcOpenInlineArrayCallArgSlot($block, $cfgCallOp, $argIndex);
            }
            if (1 === $argIndex) {
                $descriptorArg = $cfgCallOp->args[1] ?? null;
                if (
                    $descriptorArg instanceof Operand
                    && $this->callArgIsDeadInlineTemporary($descriptorArg)
                    && $this->callArgOperandExpectsArrayProducer($descriptorArg)
                ) {
                    return $this->resolveInlineArrayProducerSlotBeforeCfgCall($cfgCallOp, $block)
                        ?? $this->resolveOutermostInitArraySlotBeforePendingFuncCall($block, $pendingSends);
                }

                return null;
            }

            return null;
        }
        if ($argCount < 5) {
            return null;
        }

        return match ($argIndex) {
            0, 4 => $this->resolveProcOpenInlineArrayCallArgSlot($block, $cfgCallOp, $argIndex),
            3 => $this->resolveProcOpenNullCwdCallArgSlot($block, $cfgCallOp, $pendingSends),
            default => null,
        };
    }

    /** proc_open inline command/env array literals — map cfg arg operand, not block INIT_ARRAY scan (#16203). */
    private function resolveProcOpenInlineArrayCallArgSlot(Block $block, Op $cfgCallOp, int $argIndex): ?string
    {
        $arrayExpr = $this->procOpenHoistedInlineArrayForArg($cfgCallOp, $argIndex, $block);
        if (!$arrayExpr instanceof Op\Expr\Array_) {
            $callArg = $cfgCallOp->args[$argIndex] ?? null;
            if ($callArg instanceof Operand) {
                $embedded = $this->unwrapArrayLiteralExpr($callArg);
                $arrayExpr = $embedded instanceof Op\Expr\Array_ ? $embedded : null;
            }
        }

        return $this->slotForInlineArrayExpr($block, $arrayExpr);
    }

    /**
     * php-cfg hoists proc_open(['cmd'], …, null, ['K'=>'V']) preludes as sibling stmts (#9389, #16203).
     * Trailing group before the call: command Array_, optional null ConstFetch, env Array_.
     */
    private function procOpenHoistedInlineArrayForArg(Op $callOp, int $argIndex, Block $block): ?Op\Expr\Array_
    {
        if (null === $block->orig || !\is_array($callOp->args ?? null) || \count($callOp->args) < 5) {
            return null;
        }
        if (!\in_array($argIndex, [0, 4], true)) {
            return null;
        }
        $children = $block->orig->children;
        $callIndex = null;
        foreach ($children as $i => $child) {
            if ($child === $callOp) {
                $callIndex = $i;
                break;
            }
        }
        if (null === $callIndex) {
            return null;
        }
        $trail = [];
        for ($i = $callIndex - 1; $i >= 0; --$i) {
            $child = $children[$i];
            if ($child instanceof Op\Expr\Array_) {
                array_unshift($trail, $child);
                continue;
            }
            if ($child instanceof Op\Expr\ConstFetch) {
                $name = $this->staticNameFromOperand($child->name);
                if ('null' === $name) {
                    array_unshift($trail, $child);
                    continue;
                }
            }
            if ($child instanceof Op\Expr\Assign) {
                break;
            }
            break;
        }
        $arrays = array_values(array_filter(
            $trail,
            static fn (Op\Expr $expr): bool => $expr instanceof Op\Expr\Array_
        ));
        if (0 === $argIndex) {
            return $arrays[0] ?? null;
        }

        return [] !== $arrays ? $arrays[\count($arrays) - 1] : null;
    }

    /** @param list<OpCode> $pendingSends */
    private function resolveProcOpenNullCwdCallArgSlot(Block $block, ?Op $cfgCallOp, array $pendingSends): ?string
    {
        if (null !== $cfgCallOp && null !== $block->orig) {
            $children = $block->orig->children;
            $callIndex = null;
            foreach ($children as $i => $child) {
                if ($child === $cfgCallOp) {
                    $callIndex = $i;
                    break;
                }
            }
            if (null !== $callIndex) {
                for ($i = $callIndex - 1; $i >= 0; --$i) {
                    $child = $children[$i];
                    if ($child instanceof Op\Expr\ConstFetch && 'null' === $this->staticNameFromOperand($child->name)) {
                        $slot = $block->slotForOperand($child->result);

                        return null !== $slot ? (string) $slot : null;
                    }
                    if ($child instanceof Op\Expr\Array_) {
                        continue;
                    }
                    if ($child instanceof Op\Expr\Assign) {
                        break;
                    }
                    break;
                }
            }
        }
        for ($i = \count($pendingSends) - 1; $i >= 0; --$i) {
            $op = $pendingSends[$i];
            if (OpCode::TYPE_CONST_FETCH !== $op->type || null === $op->arg2) {
                continue;
            }
            $const = $block->constants[$op->arg2] ?? null;
            if (null !== $const && 'null' === $const->toString()) {
                return (string) $op->arg1;
            }
        }

        return null;
    }

    private function slotForInlineArrayExpr(Block $block, ?Op\Expr\Array_ $arrayExpr): ?string
    {
        if (!$arrayExpr instanceof Op\Expr\Array_) {
            return null;
        }
        if (null === $block->slotForOperand($arrayExpr->result)) {
            foreach ($this->compileArrayLiteral($arrayExpr, $block) as $op) {
                $block->addOpCode($op);
            }
        }
        $slot = $block->slotForOperand($arrayExpr->result);

        return null !== $slot ? (string) $slot : null;
    }

    /** Outermost hoisted Array_ stmt immediately before a cfg FuncCall (#11485). */
    private function resolveInlineArrayProducerSlotBeforeCfgCall(Op $callOp, Block $block): ?string
    {
        $arrayExpr = $this->inlineArrayProducerImmediatelyBeforeCfgCall($callOp, $block);
        if (!$arrayExpr instanceof Op\Expr\Array_) {
            return null;
        }
        if (null === $block->slotForOperand($arrayExpr->result)) {
            foreach ($this->compileExpr($arrayExpr, $block) as $op) {
                $block->addOpCode($op);
            }
        }
        $slot = $block->slotForOperand($arrayExpr->result);

        return null !== $slot ? (string) $slot : null;
    }

    /**
     * Outermost inline Array_ producer for nested literal call args (descriptor_spec, etc.) (#11485).
     *
     * @param list<Op\Expr> $producers
     * @param list<Op\Expr\Array_> $arrayProducers
     */
    private function matchOutermostNestedInlineArrayProducerForCallArg(
        array $producers,
        array $arrayProducers,
        int $argIndex,
        int $argCount
    ): ?Op\Expr\Array_ {
        if ([] === $arrayProducers) {
            return null;
        }
        $nestedTrailing = $this->splitNestedArrayLiteralChainWithTrailingProducers($producers);
        if (null !== $nestedTrailing) {
            [$arrayChain, $trailing] = $nestedTrailing;
            if (1 + \count($trailing) === $argCount && $argIndex < \count($arrayChain)) {
                $outer = $arrayChain[\count($arrayChain) - 1] ?? null;

                return $outer instanceof Op\Expr\Array_ ? $outer : null;
            }
        }
        if (
            \count($arrayProducers) >= 2
            && $this->producersAreNestedArrayLiteralChain($arrayProducers)
            && $this->arrayProducersFormNestedChain($arrayProducers)
        ) {
            $outer = $arrayProducers[\count($arrayProducers) - 1];

            return $outer instanceof Op\Expr\Array_ ? $outer : null;
        }

        return $arrayProducers[\count($arrayProducers) - 1];
    }

    /**
     * Last-chance ARG_SEND slots for filter_input() hoisted ConstFetch / nested options (#15194).
     *
     * @param list<OpCode> $pendingSends
     */
    private function finalizeFilterInputCallArgSlot(
        Block $block,
        ?Op $cfgCallOp,
        int $argIndex,
        array &$pendingSends = []
    ): ?string {
        if (null === $cfgCallOp || null === $block->orig) {
            return null;
        }
        if ('filter_input' !== strtolower($this->resolveCfgFuncCallName($cfgCallOp) ?? '')) {
            return null;
        }
        if (3 === $argIndex) {
            $optionsArg = $cfgCallOp->args[3] ?? null;
            if (
                $optionsArg instanceof Operand
                && $this->callArgIsDeadInlineTemporary($optionsArg)
                && $this->callArgOperandExpectsArrayProducer($optionsArg)
            ) {
                return $this->resolveOutermostInitArraySlotBeforePendingFuncCall($block, $pendingSends);
            }

            return null;
        }
        if (0 !== $argIndex && 2 !== $argIndex) {
            return null;
        }
        $hoisted = [];
        $callIndex = null;
        foreach ($block->orig->children as $i => $child) {
            if ($child === $cfgCallOp) {
                $callIndex = $i;
                break;
            }
        }
        if (null === $callIndex) {
            return null;
        }
        for ($i = $callIndex - 1; $i >= 0; --$i) {
            $child = $block->orig->children[$i];
            if ($child instanceof Op\Expr\ConstFetch) {
                array_unshift($hoisted, $child);
                continue;
            }
            if ($child instanceof Op\Expr\Array_) {
                continue;
            }
            if ($child instanceof Op\Expr\Assign) {
                break;
            }
            break;
        }
        $constFetches = array_values(array_filter(
            $hoisted,
            static fn (Op\Expr $producer): bool => $producer instanceof Op\Expr\ConstFetch
        ));
        $target = match ($argIndex) {
            0 => $constFetches[0] ?? null,
            2 => $constFetches[1] ?? ($constFetches[0] ?? null),
            default => null,
        };
        if (!$target instanceof Op\Expr\ConstFetch) {
            return null;
        }
        $folded = $this->tryFoldGlobalConstFetch($target);
        if (null !== $folded) {
            return (string) $block->registerConstant(new Operand\Temporary(), $folded);
        }
        $slot = $block->slotForOperand($target->result);
        if (null !== $slot) {
            return (string) $slot;
        }
        foreach ($this->compileExpr($target, $block) as $op) {
            $pendingSends[] = $op;
        }
        $slot = $block->slotForOperand($target->result);

        return null !== $slot ? (string) $slot : null;
    }

    /**
     * Last keyed INIT_ARRAY slot for nested inline array call args (#11485).
     *
     * @param list<OpCode> $pendingSends
     */
    private function resolveOutermostInitArraySlotBeforePendingFuncCall(
        Block $block,
        array $pendingSends = []
    ): ?string {
        $outerSlot = null;
        foreach ($block->opCodes as $op) {
            if (OpCode::TYPE_INIT_ARRAY === $op->type && null !== $op->arg1 && null !== $op->arg3) {
                $outerSlot = (string) $op->arg1;
            }
        }
        if (null !== $outerSlot) {
            return $outerSlot;
        }
        $scanOps = array_merge($block->opCodes, $pendingSends);
        for ($i = \count($scanOps) - 1; $i >= 0; --$i) {
            $op = $scanOps[$i];
            if (OpCode::TYPE_INIT_ARRAY === $op->type && null !== $op->arg1) {
                return (string) $op->arg1;
            }
        }

        return null;
    }

    /**
     * Nth FUNCCALL_EXEC_RETURN slot including pending call-arg producer ops (#16097).
     *
     * @param list<OpCode> $pendingOps
     */
    private function slotForFuncCallExecReturnOrdinal(
        Block $block,
        int $producerOrdinal,
        array $pendingOps = []
    ): ?string {
        if ($producerOrdinal < 0) {
            return null;
        }
        $execReturnSlots = [];
        foreach (array_merge($block->opCodes, $pendingOps) as $op) {
            if (OpCode::TYPE_FUNCCALL_EXEC_RETURN === $op->type && null !== $op->arg1) {
                $execReturnSlots[] = (string) $op->arg1;
            }
        }

        return $execReturnSlots[$producerOrdinal] ?? null;
    }

    /**
     * Last-chance ARG_SEND slot for array_merge*(array_keys(...), [...]) sibling producers (#12450, #13704, #17781).
     *
     * @param list<OpCode> $sends
     */
    private function finalizeArrayMergeFamilyCallArgSlot(
        Block $block,
        Op $cfgCallOp,
        int $argIndex,
        array &$sends
    ): ?string {
        $callee = strtolower($this->resolveCfgFuncCallName($cfgCallOp) ?? '');
        if (!\in_array(
            $callee,
            ['array_merge', 'array_merge_recursive', 'array_replace', 'array_replace_recursive'],
            true
        )) {
            return null;
        }
        if (\count($cfgCallOp->args ?? []) < 2 || null === $block->orig) {
            return null;
        }
        $producers = $this->arrayMergeFamilyInlineProducersForCfgCall(
            $block->orig->children,
            $cfgCallOp
        );
        $matched = $this->matchArrayMergeFamilyFullInlineCallArgProducer(
            $producers,
            $argIndex,
            \count($cfgCallOp->args ?? []),
            $cfgCallOp->args ?? []
        );
        if (null === $matched) {
            $matched = $this->matchArrayMergeFuncCallAndArrayInlineProducers($producers, $argIndex);
        }
        if (!$matched instanceof Op\Expr) {
            return null;
        }
        if ($matched instanceof Op\Expr\FuncCall || $matched instanceof Op\Expr\NsFuncCall) {
            $funcOrdinal = 0;
            foreach ($producers as $producer) {
                if ($producer === $matched) {
                    break;
                }
                if ($producer instanceof Op\Expr\FuncCall || $producer instanceof Op\Expr\NsFuncCall) {
                    ++$funcOrdinal;
                }
            }
            $execSlot = $this->slotForFuncCallExecReturnOrdinal($block, $funcOrdinal, $sends);
            if (null !== $execSlot) {
                return $execSlot;
            }
            if (null === $block->slotForOperand($matched->result)) {
                foreach ($this->compileExpr($matched, $block) as $op) {
                    $sends[] = $op;
                }
            }
            $execSlot = $this->slotForFuncCallExecReturnOrdinal($block, $funcOrdinal, $sends);
            if (null !== $execSlot) {
                return $execSlot;
            }
            $slot = $block->slotForOperand($matched->result);
            if (null !== $slot) {
                return (string) $slot;
            }

            return null;
        }
        if (null === $block->slotForOperand($matched->result)) {
            if ($matched instanceof Op\Expr\Array_) {
                foreach ($this->compileArrayLiteral($matched, $block) as $op) {
                    $sends[] = $op;
                }
            } else {
                foreach ($this->compileExpr($matched, $block) as $op) {
                    $sends[] = $op;
                }
            }
        }
        $slot = $block->slotForOperand($matched->result);
        if (null !== $slot) {
            return (string) $slot;
        }

        return null;
    }

    /**
     * Last-chance ARG_SEND slot for array_combine() nested array_keys() + trailing Array_ (#15558, #15857).
     *
     * @param list<OpCode> $sends
     */
    private function finalizeArrayCombineCallArgSlot(
        Block $block,
        Op $cfgCallOp,
        int $argIndex,
        array &$sends
    ): ?string {
        if (2 !== \count($cfgCallOp->args ?? []) || null === $block->orig) {
            return null;
        }
        $producers = $this->precedingInlineCallArgProducersBeforeCfgOp(
            $block->orig->children,
            $cfgCallOp
        );
        $matched = $this->matchArrayCombineInlineProducers($producers, $argIndex);
        if (!$matched instanceof Op\Expr) {
            return null;
        }
        if ($matched instanceof Op\Expr\FuncCall || $matched instanceof Op\Expr\NsFuncCall) {
            $funcOrdinal = 0;
            foreach ($producers as $producer) {
                if ($producer === $matched) {
                    break;
                }
                if ($producer instanceof Op\Expr\FuncCall || $producer instanceof Op\Expr\NsFuncCall) {
                    ++$funcOrdinal;
                }
            }
            $execSlot = $this->slotForFuncCallExecReturnOrdinal($block, $funcOrdinal, $sends);
            if (null !== $execSlot) {
                return $execSlot;
            }
            if (null === $block->slotForOperand($matched->result)) {
                foreach ($this->compileExpr($matched, $block) as $op) {
                    $sends[] = $op;
                }
            }
            $execSlot = $this->slotForFuncCallExecReturnOrdinal($block, $funcOrdinal, $sends);
            if (null !== $execSlot) {
                return $execSlot;
            }
            $slot = $block->slotForOperand($matched->result);
            if (null !== $slot) {
                return (string) $slot;
            }

            return null;
        }
        if (null === $block->slotForOperand($matched->result)) {
            foreach ($this->compileExpr($matched, $block) as $op) {
                $sends[] = $op;
            }
        }
        if ($matched instanceof Op\Expr\Array_) {
            $ordinalSlot = $this->slotForArrayCombineSiblingInitArray(
                $block,
                $producers,
                $argIndex,
                $sends
            );
            if (null !== $ordinalSlot) {
                return $ordinalSlot;
            }
            $byArgSlot = $this->slotForArrayCombineInitArrayByArgIndex($block, $cfgCallOp, $argIndex, $sends);
            if (null !== $byArgSlot) {
                return $byArgSlot;
            }
        }
        $slot = $block->slotForOperand($matched->result);
        if (null !== $slot) {
            return (string) $slot;
        }

        return null;
    }

    /**
     * array_combine() with inline array literals — map arg index to INIT_ARRAY ordinal (#16080).
     *
     * @param list<OpCode> $pendingSends
     */
    private function slotForArrayCombineInitArrayByArgIndex(
        Block $block,
        Op $cfgCallOp,
        int $argIndex,
        array $pendingSends
    ): ?string {
        if (2 !== \count($cfgCallOp->args ?? [])) {
            return null;
        }
        foreach ($cfgCallOp->args as $callArg) {
            if (
                null === $callArg
                || !$this->callArgIsDeadInlineTemporary($callArg)
                || !$this->callArgOperandExpectsArrayProducer($callArg)
            ) {
                return null;
            }
        }
        $initSlots = $this->initArraySlotsForCurrentFunccall($block, $pendingSends);
        if (\count($initSlots) <= $argIndex) {
            return null;
        }

        return $initSlots[$argIndex];
    }

    /**
     * array_combine([...], [...]) — map arg index to sibling INIT_ARRAY slot (#16080, #10214).
     *
     * @param list<OpCode> $pendingSends
     */
    private function slotForArrayCombineSiblingInitArray(
        Block $block,
        array $producers,
        int $argIndex,
        array $pendingSends
    ): ?string {
        $matched = $this->matchArrayCombineInlineProducers($producers, $argIndex);
        if (!$matched instanceof Op\Expr\Array_) {
            return null;
        }
        $arrayProducers = array_values(array_filter(
            $producers,
            static fn (Op\Expr $producer): bool => $producer instanceof Op\Expr\Array_
        ));
        if (2 !== \count($arrayProducers)) {
            return null;
        }
        $ordinal = array_search($matched, $arrayProducers, true);
        if (false === $ordinal) {
            return null;
        }
        $initSlots = $this->initArraySlotsForCurrentFunccall($block, $pendingSends);

        return $initSlots[$ordinal] ?? null;
    }

    /**
     * Last-chance ARG_SEND slot for array_column() inline nested haystack + hoisted null (#15914).
     *
     * @param list<OpCode> $sends
     */
    private function finalizeArrayColumnCallArgSlot(
        Block $block,
        Op $cfgCallOp,
        int $argIndex,
        array &$sends
    ): ?string {
        $producers = $this->precedingInlineCallArgProducersBeforeCfgOp(
            $block->orig->children,
            $cfgCallOp
        );
        $callArgs = $cfgCallOp->args ?? [];
        $matched = $this->matchArrayColumnNestedHaystackTrailingProducers(
            $producers,
            $callArgs,
            $argIndex,
            $cfgCallOp
        );
        // array_column([['n'=>'a'], …], 'n') — nested haystack without trailing null (#13703, #15960).
        if (!$matched instanceof Op\Expr && 0 === $argIndex) {
            $matched = $this->matchFoldedFirstNestedSiblingArrayLiteralCallArgProducer(
                $producers,
                $argIndex,
                \count($callArgs),
                $callArgs
            );
            if (null === $matched) {
                $matched = $this->matchSoleNestedInlineArrayHaystackProducer(
                    $producers,
                    $callArgs,
                    $argIndex
                );
            }
            if (null === $matched) {
                $matched = $this->inlineArrayProducerImmediatelyBeforeCfgCall($cfgCallOp, $block);
            }
        }
        if (!$matched instanceof Op\Expr) {
            return null;
        }
        if (null === $block->slotForOperand($matched->result)) {
            foreach ($this->compileExpr($matched, $block) as $op) {
                $sends[] = $op;
            }
        }
        $slot = $block->slotForOperand($matched->result);

        return null !== $slot ? (string) $slot : null;
    }

    /**
     * array_column([[..]], null, 'x') / array_column([[..]], 'name', null) — nested haystack + null (#15914).
     *
     * @param list<Op\Expr> $producers
     * @param list<Operand> $callArgs
     */
    private function matchArrayColumnNestedHaystackTrailingProducers(
        array $producers,
        array $callArgs,
        int $argIndex,
        ?Op $cfgCallOp
    ): ?Op\Expr {
        $nestedTrailing = $this->splitNestedArrayLiteralChainWithTrailingProducers($producers);
        if (null === $nestedTrailing) {
            return null;
        }
        [$arrayChain, $trailing] = $nestedTrailing;
        if (0 === $argIndex) {
            return $arrayChain[\count($arrayChain) - 1];
        }
        if ($this->isEmbeddedCallLiteralArg($callArgs[$argIndex] ?? null)) {
            return null;
        }
        $nullFetch = null;
        foreach ($trailing as $producer) {
            if (!$producer instanceof Op\Expr\ConstFetch) {
                continue;
            }
            $name = $this->staticNameFromOperand($producer->name);
            if (null !== $name && 'null' === strtolower($name)) {
                $nullFetch = $producer;
                break;
            }
        }
        if (null === $nullFetch) {
            return null;
        }
        $nullTarget = $this->arrayColumnNullPreludeArgIndex($cfgCallOp);
        if (null !== $nullTarget && $argIndex === $nullTarget) {
            return $nullFetch;
        }
        if ($argIndex === \count($callArgs) - 1) {
            return $nullFetch;
        }

        return null;
    }

    /**
     * Hoisted null ConstFetch before array_column() maps to column_key or index_key (#4306, #9305, #10535).
     */
    private function arrayColumnNullPreludeArgIndex(?Op $cfgCallOp): ?int
    {
        if (null === $cfgCallOp || !\is_array($cfgCallOp->args ?? null)) {
            return null;
        }
        $args = $cfgCallOp->args;
        $argc = \count($args);
        if (2 === $argc) {
            return 1;
        }
        if (3 !== $argc) {
            return null;
        }
        $columnEmbedded = $this->isEmbeddedCallLiteralArg($args[1] ?? null);
        $indexEmbedded = $this->isEmbeddedCallLiteralArg($args[2] ?? null);
        if ($columnEmbedded && !$indexEmbedded) {
            return 2;
        }
        if (!$columnEmbedded && $indexEmbedded) {
            return 1;
        }

        return null;
    }

    /**
     * Named locals after ?: echo must not be remapped to merge-phi producer temps (#9487).
     */
    private function namedLocalCallArgSlotIfBound(
        Operand $arg,
        Block $block,
        ?Op $cfgCallOp = null,
        ?int $argIndex = null
    ): ?string {
        $probe = $arg;
        if (null !== $cfgCallOp && is_array($cfgCallOp->args ?? null) && isset($cfgCallOp->args[(int) $argIndex])) {
            $probe = $cfgCallOp->args[(int) $argIndex];
        }
        $name = Block::resolveVariableName($probe);
        if (null === $name || '' === $name) {
            $root = Block::cfgVarRoot($probe);
            if ($root instanceof CfgVariable) {
                $name = Block::resolveVariableName($root);
            }
        }
        if (null === $name || '' === $name) {
            $assignedNamed = $this->slotForNamedLocalFromAssignVarOperand($probe, $block);
            if (null !== $assignedNamed) {
                return (string) $assignedNamed;
            }
            return null;
        }
        $namedSlot = $block->slotIndexForVariableName($name);
        if (null === $namedSlot || !$block->isNamedVariableSlot((int) $namedSlot)) {
            return null;
        }

        return (string) $namedSlot;
    }

    /**
     * php-cfg may wire a later named local read to a preceding call's dead result temp (#9074).
     */
    private function preferNamedLocalCallArgSlot(
        Operand $arg,
        Block $block,
        ?string $valueSlot,
        ?string $calleeName = null
    ): ?string
    {
        if (null === $valueSlot) {
            return null;
        }
        $assignedNamed = $this->slotForNamedLocalFromAssignVarOperand($arg, $block);
        if (null !== $assignedNamed) {
            return (string) $assignedNamed;
        }
        if (
            $this->callArgOperandIsClosureValue($arg, $block)
            && !$this->isNamedVariableOperand($arg)
            && null === $this->namedLocalCallArgSlotIfBound($arg, $block)
        ) {
            return $valueSlot;
        }
        $name = Block::resolveVariableName($arg);
        if (null === $name || '' === $name) {
            $root = Block::cfgVarRoot($arg);
            if ($root instanceof CfgVariable) {
                $name = Block::resolveVariableName($root);
            }
        }
        if (null === $name || '' === $name) {
            return $valueSlot;
        }
        if (null !== $calleeName && $name === $calleeName) {
            return $valueSlot;
        }
        // php-cfg dead temps for hoisted scalar ConstFetch / Cast preludes (#9140, #10143).
        if (\in_array(strtolower($name), ['true', 'false', 'null', 'nan', 'inf'], true)) {
            return $valueSlot;
        }
        $namedSlot = $block->slotIndexForVariableName($name);
        if (null === $namedSlot) {
            return $valueSlot;
        }
        if (!$block->isNamedVariableSlot((int) $namedSlot)) {
            return $valueSlot;
        }
        if ((int) $namedSlot === (int) $valueSlot) {
            return $valueSlot;
        }
        // Inline producer temp must not replace an unbound named local (#9973, #9924).
        // Function-local statics bind via TYPE_DECLARE_FUNCTION_STATIC, not ASSIGN (#28038).
        if (
            !$this->blockHasAssignToSlot($block, (int) $namedSlot)
            && !$this->blockHasAssignToSlotInParentBlocks($block, (int) $namedSlot)
            && !$this->blockHasFunctionStaticDeclareToSlot($block, (int) $namedSlot)
        ) {
            return $valueSlot;
        }

        return $namedSlot;
    }

    /**
     * `$path = __DIR__ . '/x'; f($path)` — bind the named local when Concat is inlined (#9973).
     *
     * @return list<OpCode>
     */
    private function tryEmitAdjacentAssignForInlineCallArg(
        Operand $arg,
        ?string $valueSlot,
        Block $block,
        ?Op $cfgCallOp,
        int $argIndex
    ): array {
        if (null === $valueSlot || null === $cfgCallOp || null === $block->orig) {
            return [];
        }
        if (!property_exists($cfgCallOp, 'args') || !is_array($cfgCallOp->args)) {
            return [];
        }
        $callArg = $cfgCallOp->args[$argIndex] ?? null;
        if (null === $callArg || !$this->operandsReferToSameVariable($arg, $callArg)) {
            return [];
        }
        $children = $block->orig->children;
        $prev = null;
        foreach ($children as $i => $child) {
            if (
                !($child instanceof Op\Expr\FuncCall || $child instanceof Op\Expr\NsFuncCall)
                || !property_exists($child, 'args')
                || !is_array($child->args)
            ) {
                continue;
            }
            if ($child !== $cfgCallOp) {
                $sameCall = false;
                if (
                    property_exists($cfgCallOp, 'name')
                    && property_exists($child, 'name')
                    && $this->operandsReferToSameVariable($child->name, $cfgCallOp->name)
                ) {
                    $sameCall = true;
                }
                if (!$sameCall) {
                    continue;
                }
            }
            $siteArg = $child->args[$argIndex] ?? null;
            if (null === $siteArg || !$this->operandsReferToSameVariable($siteArg, $callArg)) {
                continue;
            }
            $prev = $children[$i - 1] ?? null;
            break;
        }
        if (!$prev instanceof Op\Expr\Assign || !$this->operandsReferToSameVariable($prev->var, $callArg)) {
            return [];
        }
        $destSlot = $block->getVarSlot($prev->var, false);
        // List destruct assigns compile in the parent block; skip merge-block phi bind (#10807).
        if (!$this->blockHasAssignToSlot($block, (int) $destSlot)) {
            return [];
        }

        $rhsSlot = (int) $valueSlot;
        if ($rhsSlot === (int) $destSlot) {
            // `$path = 'a' . 'b'` — CONCAT already wrote into destSlot; self-sync would clobber (#16281).
            if ($this->assignAdjacentToBinaryExprProducer($block, $prev)) {
                return [];
            }
            $exprSlot = $block->slotForOperand($prev->expr);
            if (null !== $exprSlot && (int) $exprSlot !== (int) $destSlot) {
                $rhsSlot = (int) $exprSlot;
            } else {
                // Reassigned locals (e.g. $f = fopen after fclose($f)) — use latest ASSIGN RHS (#16271).
                foreach ($block->opCodes as $op) {
                    if (OpCode::TYPE_ASSIGN === $op->type && (int) $op->arg2 === (int) $destSlot) {
                        $rhsSlot = (int) $op->arg3;
                    }
                }
            }
            if ($rhsSlot === (int) $destSlot) {
                return [];
            }
        }

        // `$a = ['k'=>1]; array_values($a)` — an identical dest←rhs ASSIGN already exists.
        // Emitting a second free()+store delrefs the HT and empties string-key walks under
        // thin AOT (#27545 / re-#27212). Peer: skip when CONCAT already wrote dest (#16281).
        foreach ($block->opCodes as $op) {
            if (
                OpCode::TYPE_ASSIGN === $op->type
                && (int) $op->arg2 === (int) $destSlot
                && (int) $op->arg3 === (int) $rhsSlot
            ) {
                return [];
            }
        }

        return [new OpCode(
            OpCode::TYPE_ASSIGN,
            $this->compileOperand($prev->result, $block, false),
            $destSlot,
            $rhsSlot
        )];
    }

    /** `$x = 'a' . 'b'; f($x)` — CFG places BinaryOp immediately before Assign (#16281). */
    private function assignAdjacentToBinaryExprProducer(Block $block, Op\Expr\Assign $assign): bool
    {
        if (null === $block->orig) {
            return false;
        }
        $assignIndex = null;
        foreach ($block->orig->children as $i => $child) {
            if ($child === $assign) {
                $assignIndex = $i;
                break;
            }
        }
        if (null === $assignIndex || $assignIndex < 1) {
            return false;
        }

        $prev = $block->orig->children[$assignIndex - 1];

        return $prev instanceof Op\Expr\BinaryOp || $prev instanceof Op\Expr\ConcatList;
    }

    /**
     * `$ini = "flag = $v"; parse_ini_string($ini)` inside loops — dest must not alias ConcatList temp (#18442).
     *
     * @param-out int $destSlot
     * @param-out int $rhsSlot
     */
    private function reconcileEncapsedConcatListAssignSlots(
        Op\Expr\Assign $assign,
        Block $block,
        int &$destSlot,
        int &$rhsSlot
    ): void {
        $concat = $this->concatListProducerFromAssignExpr($assign->expr);
        if (null === $concat || null === $concat->result) {
            return;
        }
        $producerSlot = $block->slotForOperand($concat->result);
        if (null === $producerSlot) {
            return;
        }
        $producerSlot = (int) $producerSlot;
        $rhsSlot = $producerSlot;
        if ((int) $destSlot === $producerSlot) {
            $name = Block::resolveVariableName($assign->var);
            $cvSlot = null !== $name ? $block->slotIndexForVariableName($name) : null;
            if (null === $cvSlot || (int) $cvSlot === $producerSlot) {
                $cvSlot = $block->forceFreshVarSlot($assign->var);
            }
            $destSlot = (int) $cvSlot;
        }
    }

    /** @return ?Op\Expr\ConcatList */
    private function concatListProducerFromAssignExpr(Operand $expr): ?Op\Expr\ConcatList
    {
        $unwrap = $expr;
        while ($unwrap instanceof Operand\Temporary && null !== $unwrap->original) {
            $unwrap = $unwrap->original;
        }
        if ($unwrap instanceof Op\Expr\ConcatList) {
            return $unwrap;
        }

        return $this->unwrapConcatListExpr($expr);
    }

    private function blockHasAssignToSlot(Block $block, int $destSlot): bool
    {
        foreach ($block->opCodes as $op) {
            if (OpCode::TYPE_ASSIGN === $op->type && (int) $op->arg2 === $destSlot) {
                return true;
            }
        }

        return false;
    }

    /** Function-local `static $x` binds the CV via DECLARE_FUNCTION_STATIC (#28038). */
    private function blockHasFunctionStaticDeclareToSlot(Block $block, int $destSlot): bool
    {
        foreach ($block->opCodes as $op) {
            if (OpCode::TYPE_DECLARE_FUNCTION_STATIC === $op->type && (int) $op->arg1 === $destSlot) {
                return true;
            }
        }

        return false;
    }

    /** Parent CFG blocks (list destruct merge) may hold the assign lowering (#10807). */
    private function blockHasAssignToSlotInParentBlocks(Block $block, int $destSlot, array $visited = []): bool
    {
        foreach ($block->parents as $parent) {
            if (!$parent instanceof Block) {
                continue;
            }
            $id = spl_object_id($parent);
            if (isset($visited[$id])) {
                continue;
            }
            $visited[$id] = true;
            if ($this->blockHasAssignToSlot($parent, $destSlot)) {
                return true;
            }
            if ($this->blockHasAssignToSlotInParentBlocks($parent, $destSlot, $visited)) {
                return true;
            }
        }

        return false;
    }

    /**
     * By-ref named locals are real CV operands, not hoisted inline FuncCall producers (#15476, #13714).
     */
    private function isByRefNamedCallArgExcludedFromSiblingProducerWiring(
        Op $consumer,
        int $argIndex,
        Operand $arg
    ): bool {
        if (!$this->isNamedVariableOperand($arg)) {
            return false;
        }
        if (!$consumer instanceof Op\Expr\FuncCall && !$consumer instanceof Op\Expr\NsFuncCall) {
            return false;
        }
        $calleeName = $this->funcCallExprCalleeName($consumer);
        if (null === $calleeName) {
            return false;
        }

        return $this->callArgRequiresByRef($calleeName, $argIndex, $arg);
    }

    private function callArgRequiresByRef(string $calleeName, int $argIndex, ?Operand $arg = null, ?Block $block = null): bool
    {
        if ('array_multisort' === strtolower($calleeName)) {
            if (null !== $arg && null !== $block && $this->isArrayMultisortSortFlagOperand($arg, $block)) {
                return false;
            }

            return true;
        }
        $lc = strtolower($calleeName);
        if (isset($this->userFunctionParamByRef[$lc][$argIndex])) {
            return true;
        }
        if (\in_array($argIndex, BuiltinByRefParams::forFunction($calleeName), true)) {
            return true;
        }
        $variadicFrom = BuiltinByRefParams::variadicByRefFromIndex($calleeName);

        return null !== $variadicFrom && $argIndex >= $variadicFrom;
    }

    /**
     * array_multisort() SORT_* / Sorting enum operands are by-value (#9481, ext/standard/array.c).
     */
    private function isArrayMultisortSortFlagOperand(Operand $arg, Block $block): bool
    {
        if ($this->operandLooksLikeArrayMultisortSortFlag($arg)) {
            return true;
        }
        $slot = $this->tryFoldCallArgCompileTimeValue($arg, $block, 'array_multisort', null);
        if (null === $slot || !isset($block->constants[$slot])) {
            return false;
        }
        $const = $block->constants[$slot];
        if (Variable::TYPE_INTEGER !== $const->type) {
            return false;
        }
        $val = $const->toInt();
        $masked = $val & ~\PHPCompiler\ext\standard\StdlibConstants::SORT_FLAG_CASE;

        return \in_array($masked, [
            \PHPCompiler\ext\standard\StdlibConstants::SORT_ASC,
            \PHPCompiler\ext\standard\StdlibConstants::SORT_DESC,
            \PHPCompiler\ext\standard\StdlibConstants::SORT_REGULAR,
            \PHPCompiler\ext\standard\StdlibConstants::SORT_NUMERIC,
            \PHPCompiler\ext\standard\StdlibConstants::SORT_STRING,
            \PHPCompiler\ext\standard\StdlibConstants::SORT_NATURAL,
            \PHPCompiler\ext\standard\StdlibConstants::SORT_LOCALE_STRING,
        ], true) || 0 !== ($val & \PHPCompiler\ext\standard\StdlibConstants::SORT_FLAG_CASE);
    }

    /** SORT_* / Sorting enum operands in array_multisort() are by-value (#9481). */
    private function operandLooksLikeArrayMultisortSortFlag(Operand $arg): bool
    {
        if ($arg instanceof Op\Expr\ConstFetch) {
            $name = $this->staticNameFromOperand($arg->name);
            if (null !== $name && str_starts_with(strtoupper($name), 'SORT_')) {
                return true;
            }
        }
        if ($arg instanceof Op\Expr\ClassConstFetch) {
            $class = $this->staticNameFromOperand($arg->class);
            if (null !== $class && 0 === strcasecmp(ltrim($class, '\\'), 'Sorting')) {
                return true;
            }
        }

        return false;
    }

    /**
     * Resolve a compile-time global function name from a php-cfg FuncCall/NsFuncCall expr.
     */
    private function funcCallExprCalleeName(Op\Expr $call): ?string
    {
        if ($call instanceof Op\Expr\FuncCall || $call instanceof Op\Expr\NsFuncCall) {
            return $this->staticNameFromOperand($call->name);
        }

        return null;
    }

    /**
     * Statement-level VM builtins that take by-ref args must compile eagerly — deferring as
     * sibling inline producers drops mutations (natcasesort + array_values + implode, #12732).
     */
    private function funcCallExprHasByRefMutatingSideEffects(Op $op): bool
    {
        if (!$op instanceof Op\Expr\FuncCall && !$op instanceof Op\Expr\NsFuncCall) {
            return false;
        }
        $calleeName = $this->funcCallExprCalleeName($op);
        if (null === $calleeName) {
            return false;
        }
        if ([] !== BuiltinByRefParams::forFunction($calleeName)) {
            return true;
        }

        $variadicFrom = BuiltinByRefParams::variadicByRefFromIndex($calleeName);
        if (null !== $variadicFrom) {
            if (
                property_exists($op, 'args')
                && \is_array($op->args)
                && \count($op->args) <= $variadicFrom
            ) {
                return false;
            }

            return true;
        }

        return false;
    }

    /**
     * True when $arg is passed by reference to a VM builtin in $call (issue #9074).
     */
    private function funcCallExprByRefArgMatchesOperand(Op\Expr $call, Operand $arg): bool
    {
        if (
            !($call instanceof Op\Expr\FuncCall || $call instanceof Op\Expr\NsFuncCall)
            || !property_exists($call, 'args')
            || !is_array($call->args)
        ) {
            return false;
        }
        $calleeName = $this->funcCallExprCalleeName($call);
        if (null === $calleeName) {
            return false;
        }
        foreach (BuiltinByRefParams::forFunction($calleeName) as $idx) {
            if (!isset($call->args[$idx])) {
                continue;
            }
            if ($this->operandsReferToSameVariable($call->args[$idx], $arg)) {
                return true;
            }
        }
        $variadicFrom = BuiltinByRefParams::variadicByRefFromIndex($calleeName);
        if (null === $variadicFrom) {
            return false;
        }
        $n = \count($call->args);
        for ($i = $variadicFrom; $i < $n; ++$i) {
            if (!isset($call->args[$i])) {
                continue;
            }
            if (
                'array_multisort' === strtolower($calleeName)
                && $this->operandLooksLikeArrayMultisortSortFlag($call->args[$i])
            ) {
                continue;
            }
            if ($this->operandsReferToSameVariable($call->args[$i], $arg)) {
                return true;
            }
        }

        return false;
    }

    private function callArgUnpack(Operand $arg): bool
    {
        return property_exists($arg, 'callArgUnpack') && true === $arg->callArgUnpack;
    }

    /**
     * Zend zend_compile.c: positional-after-named, unpack ordering (#4299, #4663).
     * Duplicate named params are deferred to runtime (zend_execute.c, #16652).
     *
     * @param list<Operand> $args
     */
    private function validateCallArgOrder(array $args): void
    {
        $hadNamed = false;
        $hadUnpack = false;
        foreach ($args as $arg) {
            $argName = $this->callArgName($arg);
            $isNamed = null !== $argName;
            $isUnpack = $this->callArgUnpack($arg);
            if ($isUnpack && $hadNamed) {
                $this->throwCompileError('Cannot use argument unpacking after named arguments');
            }
            if (!$isNamed && !$isUnpack && $hadNamed) {
                $this->throwCompileError('Cannot use positional argument after named argument');
            }
            if (!$isNamed && !$isUnpack && $hadUnpack) {
                $this->throwCompileError('Cannot use positional argument after argument unpacking');
            }
            if ($isNamed) {
                $hadNamed = true;
            }
            if ($isUnpack) {
                $hadUnpack = true;
            }
        }
    }

    private function callArgName(Operand $arg): ?string
    {
        if (property_exists($arg, 'callArgName') && null !== $arg->callArgName) {
            $name = $arg->callArgName;

            return is_string($name) && '' !== $name ? $name : null;
        }

        return null;
    }

    /**
     * CFG call argument expression for hoisted producer wiring (#16057, #18410).
     */
    private function cfgCallArgOperand(?Op $cfgCallOp, int $argIndex, $loopArg): ?Operand
    {
        if (null !== $cfgCallOp && property_exists($cfgCallOp, 'args') && is_array($cfgCallOp->args)) {
            $cfgArg = $cfgCallOp->args[$argIndex] ?? null;
            if ($cfgArg instanceof Operand) {
                return $cfgArg;
            }
        }
        if ($loopArg instanceof Operand) {
            return $loopArg;
        }

        return null;
    }

    /**
     * Constant slot for TYPE_ARG_SEND named-parameter label (#11052, #12018).
     */
    private function callArgNameSlot(Operand $arg, Block $block): ?string
    {
        $argName = $this->callArgName($arg);
        if (null === $argName) {
            return null;
        }
        $nameOp = new Operand\Literal($argName);
        $nameOp->type = Type::string();
        $nameVar = new Variable(Variable::TYPE_STRING);
        $nameVar->string($argName);

        return $block->registerConstant($nameOp, $nameVar);
    }

    /**
     * True when any call operand carries a php-cfg named-parameter label (#11052, #11105).
     */
    private function callIncludesNamedParameter(?Op $cfgCallOp): bool
    {
        if (null === $cfgCallOp || !property_exists($cfgCallOp, 'args') || !is_array($cfgCallOp->args)) {
            return false;
        }
        foreach ($cfgCallOp->args as $arg) {
            if ($arg instanceof Operand && null !== $this->callArgName($arg)) {
                return true;
            }
        }

        return false;
    }

    /**
     * Resolve enum `case` fetches feeding array literals — emit runtime CLASS_CONST_FETCH (#5636).
     *
     * @return list<OpCode>
     */
    protected function compileRuntimeEnumCaseFetchOpsForArrayElement(
        Operand $valueOperand,
        Block $block,
        Op\Expr\Array_ $arrayExpr,
        int $elementIndex
    ): array {
        $fetch = $this->findEnumCaseClassConstFetchForArrayElement(
            $valueOperand,
            $block,
            $arrayExpr,
            $elementIndex
        );
        if (null === $fetch) {
            return [];
        }
        $valueSlot = $this->compileOperand($valueOperand, $block, true);
        $op = new OpCode(
            OpCode::TYPE_CLASS_CONST_FETCH,
            $valueSlot,
            $this->compileOperand($fetch->class, $block, true),
            $this->compileOperand($fetch->name, $block, true)
        );
        $this->assignSourceMetadata($op, $fetch);

        return [$op];
    }

    private function findEnumCaseClassConstFetchForArrayElement(
        Operand $valueOperand,
        Block $block,
        Op\Expr\Array_ $arrayExpr,
        int $elementIndex,
        bool $forKeyOperand = false
    ): ?Op\Expr\ClassConstFetch {
        $root = $this->unwrapOperandChain($valueOperand);
        if ($root instanceof Op\Expr\ClassConstFetch
            && $this->isCompileTimeEnumCaseClassConstFetch($root, $block)
        ) {
            return $root;
        }
        if (null !== $block->orig) {
            foreach ($block->orig->children as $child) {
                if (!$child instanceof Op\Expr\Array_
                    || !$this->operandsReferToSameVariable($child->result, $arrayExpr->result)
                ) {
                    continue;
                }
                $fetches = $this->precedingClassConstFetchesBeforeCfgOp($block->orig->children, $child);
                $fetches = $this->dropCallArgEnumFetchesBeforeInlineArray($fetches, $child, $block);
                $fetch = $fetches[$elementIndex] ?? null;
                if ($fetch instanceof Op\Expr\ClassConstFetch
                    && $this->isCompileTimeEnumCaseClassConstFetch($fetch, $block)
                ) {
                    if ($this->operandsReferToSameVariable($fetch->result, $valueOperand)) {
                        return $fetch;
                    }
                    // php-cfg may drop the fetch result and leave a literal case-name element
                    // (e.g. `E::A; [ "A", ... ]`) — still treat as enum case fetch (#9039).
                    if ($valueOperand instanceof Operand\Literal && \is_string($valueOperand->value)) {
                        $constName = $this->staticNameFromOperand($fetch->name);
                        if (null !== $constName && $constName === $valueOperand->value) {
                            return $fetch;
                        }
                    }
                    // php-cfg may drop the fetch result and leave a literal backing scalar key
                    // (e.g. `E::A; [ E::A => 1 ]` lowered to key Literal(1)) — recover the enum case fetch (#9024).
                    // Scalar array values must not alias enum backing (#8930, #16316).
                    if ($forKeyOperand
                        && $valueOperand instanceof Operand\Literal
                        && (\is_int($valueOperand->value) || \is_string($valueOperand->value))
                    ) {
                        // Enum-as-key recovery requires key/value literals to match (both the backing scalar).
                        // `[1 => E::B]` / `[1 => 2]` must keep the numeric key (#8930).
                        $elementValue = $arrayExpr->values[$elementIndex] ?? null;
                        if (!$elementValue instanceof Operand\Literal
                            || $elementValue->value !== $valueOperand->value
                        ) {
                            break;
                        }
                        $className = $this->staticNameFromOperand($fetch->class);
                        $constName = $this->staticNameFromOperand($fetch->name);
                        if (null !== $className && null !== $constName) {
                            $lcClass = $this->resolveDefaultClassConstScope($className, $block);
                            $lcConst = ClassConstName::key($constName);
                            $stored = null !== $lcClass
                                ? ($this->compileTimeClassConsts[$lcClass][$lcConst] ?? null)
                                : null;
                            if (null !== $stored) {
                                $stored = $stored->resolveIndirect();
                                $backing = null;
                                if (Variable::TYPE_ENUM_CASE === $stored->type) {
                                    $backing = $stored->toEnumCase()->backingValue->resolveIndirect();
                                } elseif (Variable::TYPE_OBJECT === $stored->type && EnumCaseSupport::isEnumCase($stored->toObject())) {
                                    $backing = $stored->toObject()->enumCaseValue?->resolveIndirect();
                                }
                                if (null !== $backing) {
                                    if (\is_int($valueOperand->value) && Variable::TYPE_INTEGER === $backing->type
                                        && $backing->toInt() === $valueOperand->value
                                    ) {
                                        return $fetch;
                                    }
                                    if (\is_string($valueOperand->value) && Variable::TYPE_STRING === $backing->type
                                        && $backing->toString() === $valueOperand->value
                                    ) {
                                        return $fetch;
                                    }
                                }
                            }
                        }
                    }
                }
                // Hoisted enum fetches may be fewer than mixed scalar/case elements (#16316).
                foreach ($fetches as $fetch) {
                    if (!$fetch instanceof Op\Expr\ClassConstFetch
                        || !$this->isCompileTimeEnumCaseClassConstFetch($fetch, $block)
                    ) {
                        continue;
                    }
                    if ($this->operandsReferToSameVariable($fetch->result, $valueOperand)) {
                        return $fetch;
                    }
                }

                break;
            }
        }

        return null;
    }

    /**
     * in_array(E::A, [1, 2], true) — hoisted needle fetch must not poison int haystack elements (#9888).
     *
     * @param list<Op\Expr\ClassConstFetch> $fetches
     *
     * @return list<Op\Expr\ClassConstFetch>
     */
    private function dropCallArgEnumFetchesBeforeInlineArray(
        array $fetches,
        Op\Expr\Array_ $arrayExpr,
        Block $block
    ): array {
        if ([] === $fetches || null === $block->orig) {
            return $fetches;
        }
        $children = $block->orig->children;
        $arrayIndex = null;
        foreach ($children as $i => $child) {
            if ($child === $arrayExpr) {
                $arrayIndex = $i;
                break;
            }
        }
        if (null === $arrayIndex || $arrayIndex <= 0) {
            return $fetches;
        }
        $preArray = $children[$arrayIndex - 1] ?? null;
        if (!$preArray instanceof Op\Expr\ClassConstFetch) {
            return $fetches;
        }
        for ($i = $arrayIndex + 1, $n = \count($children); $i < $n; ++$i) {
            $next = $children[$i];
            if ($next instanceof Op\Expr\ConstFetch) {
                continue;
            }
            if (!($next instanceof Op\Expr\FuncCall || $next instanceof Op\Expr\NsFuncCall)) {
                return $fetches;
            }
            $callArg0 = $next->args[0] ?? null;
            if ($preArray === ($fetches[0] ?? null)
                && $this->callArgUsesHoistedEnumPreludeSlot($callArg0)
            ) {
                return \array_values(\array_filter(
                    $fetches,
                    static fn (Op\Expr $fetch): bool => $fetch !== $preArray
                ));
            }

            return $fetches;
        }

        return $fetches;
    }

    private function isCompileTimeEnumCaseClassConstFetch(
        Op\Expr\ClassConstFetch $fetch,
        Block $block
    ): bool {
        $className = $this->staticNameFromOperand($fetch->class);
        $constName = $this->staticNameFromOperand($fetch->name);
        if (null === $className || null === $constName) {
            return false;
        }
        $lcClass = $this->resolveDefaultClassConstScope($className, $block);
        if (null === $lcClass) {
            return false;
        }

        return $this->isCompileTimeEnumCaseConstantMember($lcClass, ClassConstName::key($constName));
    }

    /**
     * Fold array element operands, including php-cfg dead ClassConstFetch preludes (#5636).
     */
    protected function tryFoldArrayElementCompileTimeValue(
        Operand $valueOperand,
        Block $block,
        Op\Expr\Array_ $arrayExpr,
        int $elementIndex
    ): ?int {
        $fetch = $this->findEnumCaseClassConstFetchForArrayElement(
            $valueOperand,
            $block,
            $arrayExpr,
            $elementIndex
        );
        if (null !== $fetch) {
            $vm = $this->tryFoldClassConstFetchDefault($fetch, $block, true);
            if (null !== $vm) {
                return $block->registerConstant($valueOperand, $vm);
            }
        }

        return $this->tryFoldCallArgCompileTimeValue($valueOperand, $block);
    }

    /**
     * @return list<OpCode>
     */
    protected function compileArrayLiteral(Op\Expr\Array_ $expr, Block $block): array
    {
        $result = $this->compileOperand($expr->result, $block, false);
        if (empty($expr->values)) {
            return [new OpCode(OpCode::TYPE_INIT_ARRAY, $result)];
        }

        $return = [];
        $started = false;
        $unpackFlags = property_exists($expr, 'unpack') ? $expr->unpack : [];
        $byRefFlags = property_exists($expr, 'byRef') ? $expr->byRef : [];
        for ($i = 0, $n = count($expr->values); $i < $n; ++$i) {
            if (!empty($unpackFlags[$i])) {
                // Zend compile-time IS_CONST unpack of non-array → uncatchable Fatal
                // (zend_compile.c); runtime variables throw catchable Error (#27952).
                $spreadOperand = $expr->values[$i];
                if ($this->isCompileTimeNonTraversableArrayUnpackOperand($spreadOperand)) {
                    $sourceFile = $expr->getFile() ?: ($this->debugLastPhaseInputFile ?? 'unknown');
                    throw new CompileFatal(
                        $sourceFile,
                        max(1, $expr->getLine()),
                        $this->arrayUnpackNonTraversableCompileMessage($spreadOperand)
                    );
                }
                if (!$started) {
                    $return[] = new OpCode(OpCode::TYPE_INIT_ARRAY, $result);
                    $started = true;
                }
                $return[] = new OpCode(
                    OpCode::TYPE_ARRAY_SPREAD,
                    $result,
                    $this->compileOperand($spreadOperand, $block, true),
                    max(0, $expr->getLine())
                );
                continue;
            }

            if (!empty($byRefFlags[$i])) {
                // Reference cells must bind the live lvalue; deferred rematerialization snapshots
                // copy hooked property reads and break set-hook ref writes (#6426, #17353).
                $prefetchOps = $this->compileRuntimeEnumCaseFetchOpsForArrayElement(
                    $expr->values[$i],
                    $block,
                    $expr,
                    $i,
                    !empty($byRefFlags[$i]),
                );
                if ([] !== $prefetchOps) {
                    $valueSlot = $prefetchOps[0]->arg1;
                    $return = array_merge($return, $prefetchOps);
                    $propFetch = null;
                } else {
                    $valueExpr = $expr->values[$i];
                    $propFetch = $this->resolvePropertyFetchForArrayLiteralRef($valueExpr, $block);
                    if (null !== $propFetch) {
                        $valueTemp = new Operand\Temporary();
                        $valueSlot = $block->getVarSlot($valueTemp, false);
                    } else {
                        $valueSlot = $this->compileOperand($valueExpr, $block, true);
                    }
                }
            } else {
                $prefetchOps = $this->compileRuntimeEnumCaseFetchOpsForArrayElement(
                    $expr->values[$i],
                    $block,
                    $expr,
                    $i
                );
                if ([] !== $prefetchOps) {
                    $valueSlot = $prefetchOps[0]->arg1;
                    $return = array_merge($return, $prefetchOps);
                } else {
                    [$rematerializeOps, $valueSlot] = $this->compileDeferredArrayLiteralElementValue(
                        $expr->values[$i],
                        $block,
                        $expr,
                        $i
                    );
                    if ([] !== $rematerializeOps) {
                        $return = array_merge($return, $rematerializeOps);
                    }
                }
            }
            $keyOperand = $expr->keys[$i];
            $keyFetch = $this->findEnumCaseClassConstFetchForArrayElement(
                $keyOperand,
                $block,
                $expr,
                $i,
                true
            );
            if (null !== $keyFetch) {
                $keyTemp = new Operand\Temporary();
                $keySlot = $block->getVarSlot($keyTemp, false);
                $keyOp = new OpCode(
                    OpCode::TYPE_CLASS_CONST_FETCH,
                    $keySlot,
                    $this->compileOperand($keyFetch->class, $block, true),
                    $this->compileOperand($keyFetch->name, $block, true)
                );
                $this->assignSourceMetadata($keyOp, $keyFetch);
                $return[] = $keyOp;
            } else {
                $keySlot = $this->compileOperand($keyOperand, $block, true);
            }
            if (!empty($byRefFlags[$i])) {
                if (!$started) {
                    $return[] = new OpCode(OpCode::TYPE_INIT_ARRAY, $result);
                    $started = true;
                }
                $elemTemp = new Operand\Temporary();
                $elemSlot = $block->getVarSlot($elemTemp, false);
                $return[] = new OpCode(
                    OpCode::TYPE_ARRAY_DIM_FETCH_WRITE,
                    $elemSlot,
                    $result,
                    $keySlot instanceof Operand\NullOperand ? null : $keySlot
                );
                if (null !== $propFetch) {
                    ++$this->forcePropertyFetchForWrite;
                    $propWrite = new OpCode(
                        OpCode::TYPE_PROPERTY_FETCH_WRITE,
                        $valueSlot,
                        $this->compileOperand($propFetch->var, $block, true),
                        $this->compileOperand($propFetch->name, $block, true)
                    );
                    $this->assignSourceMetadata($propWrite, $propFetch);
                    $return[] = $propWrite;
                    --$this->forcePropertyFetchForWrite;
                }
                $return[] = new OpCode(
                    OpCode::TYPE_ASSIGN_REF,
                    $elemSlot,
                    $valueSlot
                );
                continue;
            }
            if (!$started) {
                $return[] = new OpCode(OpCode::TYPE_INIT_ARRAY, $result, $valueSlot, $keySlot);
                $started = true;
            } else {
                $return[] = new OpCode(OpCode::TYPE_ADD_ARRAY_ELEMENT, $result, $valueSlot, $keySlot);
            }
        }

        return $return;
    }

    /**
     * StaticCall lowering — mirror compileFuncCall arg partitioning (#23848, re-#17697).
     *
     * Nested StaticCall/FuncCall producers inside args must emit before outer STATICCALL_INIT,
     * same as FUNCCALL_INIT in {@see compileFuncCall()}.
     *
     * @param list<Op\Expr\Argument|Op\Expr\VariadicPlaceholder> $args
     *
     * @return list<OpCode>
     */
    protected function compileStaticCallOpcodes(
        OpCode $init,
        array $args,
        Operand $result,
        Block $block,
        int $startLine = 0,
        ?Op $cfgCallOp = null,
        ?string $calleeName = null
    ): array {
        $initPrependedBeforeArgConstFetch = false;
        if (!$this->inlineNestedProducerOpsInArgSends) {
            $initPrependedBeforeArgConstFetch = $this->prependFuncCallInitBeforeTrailingArgConstFetches(
                $block,
                $init
            );
        }
        $argSends = $this->compileCallArgSends($args, $block, $calleeName, $cfgCallOp);
        if (
            !$initPrependedBeforeArgConstFetch
            && !$this->inlineNestedProducerOpsInArgSends
        ) {
            $initPrependedBeforeArgConstFetch = $this->prependFuncCallInitBeforeTrailingArgConstFetches(
                $block,
                $init
            );
        }
        [$nestedProducerOps, $outerArgSends] = $this->partitionNestedInlineCallArgProducerOps($argSends);
        $this->rewireArrayBuiltinAdjacentFuncCallArgSendSlots(
            $outerArgSends,
            $nestedProducerOps,
            $block,
            $cfgCallOp,
            $calleeName
        );
        $this->rewireInlineArithmeticBranchCallArgSendSlots($outerArgSends, $nestedProducerOps, $block, $cfgCallOp);
        $this->rewireSiblingMultiArgInlineCallArgSendSlots($outerArgSends, $block, $cfgCallOp, $nestedProducerOps);
        $this->rewireNestedMethodCallHoistedClassConstOuterCallArgSendSlots(
            $outerArgSends,
            $block,
            $cfgCallOp,
            $nestedProducerOps
        );
        $this->rewireHoistedClassConstPreludeCallArgSendSlots($outerArgSends, $block, $cfgCallOp, $nestedProducerOps);
        $this->rewireRegisterShutdownFunctionClosureEnumCallArgSendSlots(
            $outerArgSends,
            $block,
            $cfgCallOp,
            $nestedProducerOps
        );
        $this->rewireSubstrNestedSprintfArgSendSlots($outerArgSends, $block, $cfgCallOp, $calleeName);
        $this->rewireArrayKeysInlineInitArrayArgSendSlots(
            $outerArgSends,
            $block,
            $cfgCallOp,
            $calleeName,
            array_merge($nestedProducerOps, $outerArgSends)
        );
        $this->rewireArrayCombineInlineArgSendSlots($outerArgSends, $block, $argSends, $calleeName, $cfgCallOp);
        $this->rewirePregReplaceCallbackArrayPatternMapArgSendSlots($outerArgSends, $block, $cfgCallOp, $argSends);
        $this->rewireVarExportNestedInlineCallArgSendSlots($outerArgSends, $nestedProducerOps, $block, $cfgCallOp, $calleeName);
        $this->rewireVarExportComparisonReturnFlagCallArgSendSlots(
            $outerArgSends,
            $nestedProducerOps,
            $block,
            $cfgCallOp,
            $calleeName
        );
        $this->rewireIsArrayNestedFileCallArgSendSlots($outerArgSends, $nestedProducerOps, $block, $cfgCallOp, $calleeName);
        $this->rewireInlineBitmaskTrailingCallArgSendSlots($outerArgSends, $nestedProducerOps, $block, $cfgCallOp);
        $this->rewireNamedLocalBeforeInlineBitmaskCallArgSendSlots($outerArgSends, $block, $cfgCallOp);
        $return = [];
        foreach ($outerArgSends as $send) {
            if (OpCode::TYPE_ASSIGN === $send->type) {
                $return[] = $send;
            }
        }
        foreach ($nestedProducerOps as $op) {
            $return[] = $op;
        }
        if (!$initPrependedBeforeArgConstFetch) {
            $return[] = $init;
        }
        foreach ($outerArgSends as $send) {
            if (OpCode::TYPE_ASSIGN !== $send->type) {
                $return[] = $send;
            }
        }
        $return[] = $this->compileStaticCallExecOpcode($result, $block, $startLine, $cfgCallOp);

        return $return;
    }

    /**
     * StaticCall exec opcode — nested StaticCall arg producers need EXEC_RETURN like FuncCall (#23848).
     */
    protected function compileStaticCallExecOpcode(
        Operand $result,
        Block $block,
        int $startLine = 0,
        ?Op $cfgCallOp = null
    ): OpCode {
        $exec = $this->compileFuncCallExecOpcode($result, $block, $startLine, $cfgCallOp);
        if (
            OpCode::TYPE_FUNCCALL_EXEC_NORETURN === $exec->type
            && (
                $this->callResultFeedsInlineCallArg($result, $block)
                || $this->nestedLiteralPreludeInlineCallProducerNeedsReturnSlot($cfgCallOp, $block)
                || $this->siblingInlineCallArgProducerNeedsReturnSlot($cfgCallOp, $block)
            )
        ) {
            return new OpCode(
                OpCode::TYPE_FUNCCALL_EXEC_RETURN,
                $this->compileOperand($result, $block, false),
                $startLine > 0 ? $startLine : null
            );
        }

        return $exec;
    }

    protected function compileMethodCallOpcodes(
        ?int $receiver,
        ?int $methodName,
        array $args,
        Operand $result,
        Block $block,
        int $startLine = 0,
        ?Op $cfgCallOp = null,
        bool $objectCallInvoke = false
    ): array {
        $argSends = $this->compileCallArgSends($args, $block, null, $cfgCallOp);
        [$nestedProducerOps, $outerArgSends] = $this->partitionNestedInlineCallArgProducerOps($argSends);
        $this->rewireInlineArithmeticBranchCallArgSendSlots($outerArgSends, $nestedProducerOps, $block, $cfgCallOp);
        // replaceChild(createElement(...), getElementsByTagName(...)->item(0)) — nested MethodCall
        // producers must run before INIT so they do not clobber the outer pending call (#25563).
        // Note: rewireSiblingMultiArgInlineCallArgSendSlots is FuncCall-oriented and can steal
        // createElement's EXEC_RETURN in favor of getElementsByTagName for MethodCall consumers;
        // mixed PropertyFetch+MethodCall ARG_SEND wiring in compileCallArgSends handles DOM cases.
        $return = [];
        foreach ($outerArgSends as $send) {
            if (OpCode::TYPE_ASSIGN === $send->type) {
                $return[] = $send;
            }
        }
        foreach ($nestedProducerOps as $op) {
            $return[] = $op;
        }
        $init = new OpCode(
            OpCode::TYPE_METHODCALL_INIT,
            $receiver,
            $methodName
        );
        // `$obj(...)` → `__invoke`: Zend object-call handler skips visibility (#26438).
        $init->objectCallInvoke = $objectCallInvoke;
        $return[] = $init;
        foreach ($outerArgSends as $send) {
            if (OpCode::TYPE_ASSIGN !== $send->type) {
                $return[] = $send;
            }
        }
        $return[] = $this->compileFuncCallExecOpcode($result, $block, $startLine, $cfgCallOp);

        return $return;
    }

    protected function compileFuncCallExecOpcode(
        Operand $result,
        Block $block,
        int $startLine = 0,
        ?Op $cfgCallOp = null
    ): OpCode {
        $line = $startLine > 0 ? $startLine : null;
        if ($this->stmtLevelVoidCallBeforeHoistedArrayConsumerPrelude($cfgCallOp, $block)) {
            return new OpCode(
                OpCode::TYPE_FUNCCALL_EXEC_NORETURN,
                $line
            );
        }
        if (
            $this->forceDeferredSiblingCallReturnSlot
            || $this->callNeedsReturnSlot($result, $block, $cfgCallOp)
            || $this->cfgCallOpImmediatelyVoidDiscarded($cfgCallOp, $block)
            || $this->siblingInlineCallArgProducerNeedsReturnSlot($cfgCallOp, $block)
            || $this->outerSiblingInlineFuncCallProducerNeedsReturnSlot($cfgCallOp, $block)
            || $this->hoistedSiblingFeedsLaterMultiArgConsumer($cfgCallOp, $block)
            || $this->methodCallDeadTempFeedsLaterMultiArgMethodCall($cfgCallOp, $block)
            || $this->inlineClosurePairHaystackFuncCallNeedsReturnSlot($cfgCallOp, $block)
            || $this->isAdjacentOuterHoistedFuncCallBeforeMultiArgConsumer($cfgCallOp, $block)
            || $this->nestedLiteralPreludeInlineCallProducerNeedsReturnSlot($cfgCallOp, $block)
            || $this->cfgCallIsHoistedArrayKeysForArrayCombine($cfgCallOp, $block)
            || $this->cfgCallImmediatelyFeedsAdjacentConsumer($cfgCallOp, $block)
        ) {
            return new OpCode(
                OpCode::TYPE_FUNCCALL_EXEC_RETURN,
                $this->compileOperand($result, $block, false),
                $line
            );
        }

        return new OpCode(
            OpCode::TYPE_FUNCCALL_EXEC_NORETURN,
            $line
        );
    }

    /**
     * php-cfg `var_dump($g(), $g())` hoists sibling FuncCall producers with dead arg temps (#9463, #10981).
     * Each producer must FUNCCALL_EXEC_RETURN into its result slot before the outer call sends args.
     *
     * @param list<Op> $cfgChildren
     */
    private function siblingInlineCallArgProducerNeedsReturnSlot(?Op $cfgCallOp, Block $block): bool
    {
        if (
            null === $cfgCallOp
            || null === $block->orig
            || !$this->isSiblingInlineCallProducerExpr($cfgCallOp)
        ) {
            return false;
        }
        $cfgChildren = $block->orig->children;
        foreach ($cfgChildren as $consumerIndex => $consumer) {
            if (!$this->isInlineExprCallArgConsumer($consumer)) {
                continue;
            }
            if (!property_exists($consumer, 'args') || !is_array($consumer->args) || \count($consumer->args) < 2) {
                if (
                    property_exists($consumer, 'args')
                    && \is_array($consumer->args)
                    && 1 === \count($consumer->args)
                ) {
                    $iifeProducerIndex = array_search($cfgCallOp, $cfgChildren, true);
                    if (
                        \is_int($iifeProducerIndex)
                        && $cfgCallOp instanceof Op\Expr
                        && $this->isIifeHoistedFuncCallArgProducer(
                            $cfgCallOp,
                            $consumer,
                            $iifeProducerIndex,
                            $consumerIndex,
                            $cfgChildren
                        )
                    ) {
                        return true;
                    }
                }
                continue;
            }
            $firstSibling = $this->firstSiblingInlineFuncCallProducerIndex($consumerIndex, $cfgChildren);
            foreach ($cfgChildren as $producerIndex => $producer) {
                if ($producer !== $cfgCallOp || !$producer instanceof Op\Expr) {
                    continue;
                }
                if ($this->isNestedCallArgProducerSeparatedByConsumerLiteralPreludes(
                    $producer,
                    $consumer,
                    $producerIndex,
                    $consumerIndex,
                    $cfgChildren
                )) {
                    return true;
                }
                // substr(sprintf(...), -N) — lone hoisted FuncCall + UnaryMinus offset (#10673, #13801).
                if ($this->isSiblingMultiArgFuncCallProducer(
                    $producer,
                    $consumer,
                    $producerIndex,
                    $consumerIndex,
                    $cfgChildren
                )) {
                    return true;
                }
                if (
                    null === $firstSibling
                    || $this->countSiblingInlineFuncCallProducers($firstSibling, $consumerIndex, $cfgChildren) < 2
                ) {
                    continue;
                }
                // Multi-sibling chain (MethodCall + FuncCall around ArrayDimFetch) (#28821).
                return true;
            }
        }

        return false;
    }

    /**
     * php-cfg array_intersect(f(g()), f(g())) — outer hoisted producers need EXEC_RETURN (#15488).
     */
    private function outerSiblingInlineFuncCallProducerNeedsReturnSlot(?Op $cfgCallOp, Block $block): bool
    {
        if (!$cfgCallOp instanceof Op\Expr || null === $block->orig) {
            return false;
        }
        $cfgChildren = $block->orig->children;
        $producerIndex = array_search($cfgCallOp, $cfgChildren, true);
        if (!is_int($producerIndex)) {
            return false;
        }
        for ($consumerIndex = $producerIndex + 1, $n = \count($cfgChildren); $consumerIndex < $n; ++$consumerIndex) {
            $consumer = $cfgChildren[$consumerIndex] ?? null;
            if (!$this->isSiblingMultiArgInlineCallConsumer($consumer)) {
                continue;
            }
            if (!property_exists($consumer, 'args') || !\is_array($consumer->args) || \count($consumer->args) < 2) {
                continue;
            }
            $firstSibling = $this->firstSiblingInlineFuncCallProducerIndex($consumerIndex, $cfgChildren);
            if (null === $firstSibling || $firstSibling > $producerIndex) {
                continue;
            }
            $outer = $this->outerSiblingInlineFuncCallProducers($firstSibling, $consumerIndex, $cfgChildren);
            $hoistedArgCount = 0;
            foreach ($consumer->args as $callArg) {
                if (null !== $callArg && !$this->isEmbeddedCallLiteralArg($callArg)) {
                    ++$hoistedArgCount;
                }
            }
            if (\count($outer) !== $hoistedArgCount) {
                continue;
            }
            foreach ($outer as $outerProducer) {
                if ($outerProducer === $cfgCallOp) {
                    return true;
                }
            }
        }

        return false;
    }

    /**
     * createElement(...) before replaceChild(..., getElementsByTagName(...)->item(0)) — php-cfg marks
     * the MethodCall result as a dead temp (empty usages), so the usual sibling-producer predicates
     * miss it and EXEC_NORETURN drops the new node (#25563).
     *
     * Restricted to {@code create*} factory MethodCalls: a bare empty-usages MethodCall before a
     * multi-arg consumer also matches statement {@code loadXML} ahead of
     * {@code importNode(getElementsByTagName()->item(), true)}, which then drops the load and leaves
     * {@code documentElement} null (#25605, re-#20284).
     *
     * @param list<Op> $ops
     */
    private function methodCallDeadTempFeedsLaterMultiArgMethodCallInOps(
        Op\Expr\MethodCall $producer,
        array $ops,
        int $producerIndex
    ): bool {
        if ($this->methodCallHasStatementLevelSideEffects($producer)) {
            return false;
        }
        if (null !== $producer->result && !empty($producer->result->usages)) {
            return false;
        }
        // Only DOM/document factory creates are inline dead-temp args for multi-arg MethodCalls
        // (#25563). loadXML/loadHTML/etc. are statement-level even when their bool result is unused
        // (#25605).
        if (!$this->methodCallIsDeadTempCreateFactory($producer)) {
            return false;
        }
        $opCount = \count($ops);
        for ($j = $producerIndex + 1; $j < $opCount; ++$j) {
            $next = $ops[$j] ?? null;
            if ($next instanceof Op\Expr\MethodCall || $next instanceof Op\Expr\StaticCall) {
                if (!\is_array($next->args ?? null) || \count($next->args) < 2) {
                    continue;
                }
                $deadTempCount = 0;
                foreach ($next->args as $arg) {
                    if ($this->callArgIsDeadInlineTemporary($arg)) {
                        ++$deadTempCount;
                    }
                }
                if ($deadTempCount >= 2) {
                    return true;
                }
                continue;
            }
            if (
                $next instanceof Op\Expr\PropertyFetch
                || $next instanceof Op\Expr\NullsafePropertyFetch
                || $next instanceof Op\Expr\ConstFetch
                || $next instanceof Op\Expr\ClassConstFetch
                || $next instanceof Op\Expr\FuncCall
                || $next instanceof Op\Expr\NsFuncCall
                || $this->isUnaryInlineSiblingCallArgExpr($next)
            ) {
                continue;
            }
            if ($next instanceof Op && $this->isSiblingInlineCallProducerExpr($next)) {
                continue;
            }
            break;
        }

        return false;
    }

    /**
     * createElement / createTextNode / … — dead-temp factories that feed multi-arg MethodCalls (#25563).
     * Not loadXML / query methods (#25605).
     */
    private function methodCallIsDeadTempCreateFactory(Op\Expr\MethodCall $call): bool
    {
        $method = $this->staticNameFromOperand($call->name);
        if (null === $method) {
            return false;
        }

        return str_starts_with(strtolower($method), 'create');
    }

    /** Block-scoped wrapper for {@see methodCallDeadTempFeedsLaterMultiArgMethodCallInOps} (#25563). */
    private function methodCallDeadTempFeedsLaterMultiArgMethodCall(?Op $cfgCallOp, Block $block): bool
    {
        if (!$cfgCallOp instanceof Op\Expr\MethodCall || null === $block->orig) {
            return false;
        }
        $cfgChildren = $block->orig->children;
        $producerIndex = array_search($cfgCallOp, $cfgChildren, true);
        if (!\is_int($producerIndex)) {
            return false;
        }

        return $this->methodCallDeadTempFeedsLaterMultiArgMethodCallInOps(
            $cfgCallOp,
            $cfgChildren,
            $producerIndex
        );
    }

    /**
     * php-cfg var_dump(strlen($s), substr($s, 0, 2)) — hoisted sibling producers need EXEC_RETURN (#16254).
     */
    private function hoistedSiblingFeedsLaterMultiArgConsumer(?Op $cfgCallOp, Block $block): bool
    {
        if (
            !$cfgCallOp instanceof Op\Expr\FuncCall
            && !$cfgCallOp instanceof Op\Expr\NsFuncCall
        ) {
            return false;
        }
        if (null === $block->orig) {
            return false;
        }
        $cfgChildren = $block->orig->children;
        $producerIndex = array_search($cfgCallOp, $cfgChildren, true);
        if (!\is_int($producerIndex)) {
            return false;
        }
        for ($consumerIndex = $producerIndex + 1, $n = \count($cfgChildren); $consumerIndex < $n; ++$consumerIndex) {
            $consumer = $cfgChildren[$consumerIndex] ?? null;
            if (!$this->isSiblingMultiArgInlineCallConsumer($consumer)) {
                continue;
            }
            if (!\is_array($consumer->args ?? null) || \count($consumer->args) < 2) {
                continue;
            }
            if ($this->isSiblingMultiArgFuncCallProducer(
                $cfgCallOp,
                $consumer,
                $producerIndex,
                $consumerIndex,
                $cfgChildren
            )) {
                return true;
            }
        }

        return false;
    }

    /**
     * array_filter(explode(...), fn(...)) — hoisted haystack FuncCall before callback-at-arg-1 consumer (#17948).
     */
    private function inlineClosurePairHaystackFuncCallNeedsReturnSlot(?Op $cfgCallOp, Block $block): bool
    {
        if (
            !$cfgCallOp instanceof Op\Expr\FuncCall
            && !$cfgCallOp instanceof Op\Expr\NsFuncCall
        ) {
            return false;
        }
        if (null === $block->orig) {
            return false;
        }
        $cfgChildren = $block->orig->children;
        $producerIndex = array_search($cfgCallOp, $cfgChildren, true);
        if (!\is_int($producerIndex)) {
            return false;
        }
        for ($consumerIndex = $producerIndex + 1, $n = \count($cfgChildren); $consumerIndex < $n; ++$consumerIndex) {
            $consumer = $cfgChildren[$consumerIndex] ?? null;
            if (!$this->isSiblingMultiArgInlineCallConsumer($consumer)) {
                continue;
            }
            $consumerName = $this->resolveCfgFuncCallName($consumer);
            if (1 !== $this->inlineClosureArrayPairCallbackArgIndex($consumerName)) {
                continue;
            }
            if (!\is_array($consumer->args ?? null) || \count($consumer->args) < 2) {
                continue;
            }
            $hasCallbackBetween = false;
            for ($j = $producerIndex + 1; $j < $consumerIndex; ++$j) {
                $mid = $cfgChildren[$j] ?? null;
                if ($mid instanceof Op\Expr\ArrowFunction
                    || $mid instanceof Op\Expr\Closure
                    || $mid instanceof Op\Expr\FirstClassCallable) {
                    $hasCallbackBetween = true;
                    break;
                }
            }
            if (!$hasCallbackBetween) {
                continue;
            }
            $haystack = $this->trailingInlineFuncCallHaystackBeforeCfgCall($consumer, $block);
            if ($haystack === $cfgCallOp) {
                return true;
            }
        }

        return false;
    }

    /**
     * php-cfg f(g()) hoisted before multi-arg consumer — outer f needs EXEC_RETURN (#15488).
     */
    private function isAdjacentOuterHoistedFuncCallBeforeMultiArgConsumer(?Op $cfgCallOp, Block $block): bool
    {
        if (
            !$cfgCallOp instanceof Op\Expr\FuncCall
            && !$cfgCallOp instanceof Op\Expr\NsFuncCall
        ) {
            return false;
        }
        if (null === $block->orig) {
            return false;
        }
        $cfgChildren = $block->orig->children;
        $producerIndex = array_search($cfgCallOp, $cfgChildren, true);
        if (!is_int($producerIndex) || $producerIndex < 1) {
            return false;
        }
        $inner = $cfgChildren[$producerIndex - 1] ?? null;
        if (
            !$inner instanceof Op\Expr\FuncCall
            && !$inner instanceof Op\Expr\NsFuncCall
        ) {
            return false;
        }
        if (!$this->isAdjacentNestedFuncCallProducer($inner, $cfgCallOp, $producerIndex - 1, $producerIndex)) {
            return false;
        }
        for ($consumerIndex = $producerIndex + 1, $n = \count($cfgChildren); $consumerIndex < $n; ++$consumerIndex) {
            $consumer = $cfgChildren[$consumerIndex] ?? null;
            if (!$this->isSiblingMultiArgInlineCallConsumer($consumer)) {
                continue;
            }
            if (!property_exists($consumer, 'args') || !\is_array($consumer->args) || \count($consumer->args) < 2) {
                continue;
            }

            return true;
        }

        return false;
    }

    /**
     * php-cfg `json_decode(str_repeat(...), true, 512, JSON_THROW_ON_ERROR)` — hoisted FuncCall
     * before ConstFetch literal preludes must EXEC_RETURN (#12009, #15441).
     */
    private function nestedLiteralPreludeInlineCallProducerNeedsReturnSlot(?Op $cfgCallOp, Block $block): bool
    {
        if (!$cfgCallOp instanceof Op\Expr || null === $block->orig) {
            return false;
        }
        $cfgChildren = $block->orig->children;
        $producerIndex = null;
        foreach ($cfgChildren as $i => $child) {
            if ($child === $cfgCallOp) {
                $producerIndex = $i;
                break;
            }
        }
        if (null === $producerIndex) {
            return false;
        }
        for ($i = $producerIndex + 1, $n = \count($cfgChildren); $i < $n; ++$i) {
            $consumer = $cfgChildren[$i];
            if (
                $consumer instanceof Op\Expr\ConstFetch
                || $consumer instanceof Op\Expr\ClassConstFetch
                || $consumer instanceof Op\Expr\Array_
            ) {
                continue;
            }
            if ($this->isUnaryInlineSiblingCallArgExpr($consumer)) {
                continue;
            }
            if (!$this->isInlineExprCallArgConsumer($consumer)) {
                return false;
            }

            return $this->isNestedCallArgProducerSeparatedByConsumerLiteralPreludes(
                $cfgCallOp,
                $consumer,
                $producerIndex,
                $i,
                $cfgChildren
            );
        }

        return false;
    }

    private function cfgCallIsHoistedArrayKeysForArrayCombine(?Op $cfgCallOp, Block $block): bool
    {
        if (null === $cfgCallOp || null === $block->orig) {
            return false;
        }
        if (!$cfgCallOp instanceof Op\Expr\FuncCall && !$cfgCallOp instanceof Op\Expr\NsFuncCall) {
            return false;
        }
        if ('array_keys' !== $this->resolveCfgFuncCallName($cfgCallOp)) {
            return false;
        }
        foreach ($block->orig->children as $child) {
            if (!$child instanceof Op\Expr\FuncCall && !$child instanceof Op\Expr\NsFuncCall) {
                continue;
            }
            if ('array_combine' !== $this->resolveCfgFuncCallName($child)) {
                continue;
            }
            $producers = $this->precedingInlineCallArgProducersBeforeCfgOp($block->orig->children, $child);
            $matched = $this->matchInlineCallArgProducer(
                $producers,
                $child->args ?? [],
                0,
                $child,
                $block,
                'array_combine'
            );
            if ($matched === $cfgCallOp) {
                return true;
            }
        }

        return false;
    }

    /**
     * php-cfg `take('a', fseek(...), 0)` — adjacent hoisted producer needs EXEC_RETURN (#13451).
     */
    private function cfgCallImmediatelyFeedsAdjacentConsumer(?Op $cfgCallOp, Block $block): bool
    {
        if (null === $cfgCallOp || null === $block->orig) {
            return false;
        }
        $cfgChildren = $block->orig->children;
        $producerIndex = null;
        foreach ($cfgChildren as $i => $child) {
            if ($child === $cfgCallOp) {
                $producerIndex = $i;
                break;
            }
        }
        if (null === $producerIndex) {
            return false;
        }
        if (!$cfgCallOp instanceof Op\Expr) {
            return false;
        }
        $consumerIndex = $producerIndex + 1;
        $consumer = $cfgChildren[$consumerIndex] ?? null;
        if (
            null !== $consumer
            && $this->isInlineExprCallArgConsumer($consumer)
            && $this->isAdjacentNestedFuncCallProducer(
                $cfgCallOp,
                $consumer,
                $producerIndex,
                $consumerIndex
            )
        ) {
            return true;
        }

        return $this->siblingFuncCallFeedsVarExportConsumer($cfgCallOp, $block, $producerIndex)
            || $this->siblingMethodCallFeedsVarExportConsumer($cfgCallOp, $block, $producerIndex)
            || $this->hoistedProducerFeedsConsumerThroughLiteralGap($cfgCallOp, $block);
    }

    /**
     * php-cfg `in_array('x', g(), true)` — lone hoisted FuncCall before literal prelude + consumer (#15438, #13507).
     *
     * @param list<Op> $cfgChildren
     */
    private function nearestHoistedFuncCallProducerBeforeConsumer(int $consumerIndex, array $cfgChildren): ?int
    {
        for ($i = $consumerIndex - 1; $i >= 0; --$i) {
            $child = $cfgChildren[$i] ?? null;
            if (
                $child instanceof Op\Expr\ConstFetch
                || $child instanceof Op\Expr\ClassConstFetch
                || $child instanceof Op\Expr\Array_
            ) {
                continue;
            }
            if ($child instanceof Op\Expr\FuncCall || $child instanceof Op\Expr\NsFuncCall) {
                return $i;
            }

            break;
        }

        return null;
    }

    /**
     * php-cfg hoists zero-arg builtins before multi-arg consumers with ConstFetch preludes (#15438, #13507).
     */
    private function hoistedProducerFeedsConsumerThroughLiteralGap(Op $cfgCallOp, Block $block): bool
    {
        if (!$cfgCallOp instanceof Op\Expr || null === $block->orig) {
            return false;
        }
        $cfgChildren = $block->orig->children;
        $producerIndex = null;
        foreach ($cfgChildren as $i => $child) {
            if ($child === $cfgCallOp) {
                $producerIndex = $i;
                break;
            }
        }
        if (null === $producerIndex) {
            return false;
        }
        for ($i = $producerIndex + 1, $n = \count($cfgChildren); $i < $n; ++$i) {
            $child = $cfgChildren[$i];
            if (
                $child instanceof Op\Expr\ConstFetch
                || $child instanceof Op\Expr\ClassConstFetch
                || $child instanceof Op\Expr\Array_
                // insertBefore($d->createElement('x'), $r->lastChild) — PropertyFetch between (#19719).
                || $child instanceof Op\Expr\PropertyFetch
                || $child instanceof Op\Expr\NullsafePropertyFetch
            ) {
                continue;
            }
            if ($this->isUnaryInlineSiblingCallArgExpr($child)) {
                continue;
            }
            if (!$this->isInlineExprCallArgConsumer($child)) {
                return false;
            }
            if (!property_exists($child, 'args') || !\is_array($child->args)) {
                return false;
            }
            $producers = $this->precedingInlineCallArgProducersBeforeCfgOp($cfgChildren, $child);
            foreach ($child->args as $argIndex => $callArg) {
                if (!$this->callArgIsDeadInlineTemporary($callArg)) {
                    continue;
                }
                $matched = $this->matchInlineCallArgProducer(
                    $producers,
                    $child->args,
                    (int) $argIndex,
                    $child,
                    $block
                );
                if ($matched === $cfgCallOp) {
                    return true;
                }
            }

            return false;
        }

        return false;
    }

    /**
     * php-cfg `var_export(key($a), true)` hoists key() sibling; ConstFetch `true` may sit between (#13829).
     */
    private function siblingFuncCallFeedsVarExportConsumer(Op $cfgCallOp, Block $block, int $producerIndex): bool
    {
        if (!$this->isSiblingInlineCallProducerExpr($cfgCallOp)) {
            return false;
        }
        $cfgChildren = $block->orig->children;
        for ($i = $producerIndex + 1, $n = \count($cfgChildren); $i < $n; ++$i) {
            $child = $cfgChildren[$i];
            if (
                $child instanceof Op\Expr\ConstFetch
                || $child instanceof Op\Expr\ClassConstFetch
                || $child instanceof Op\Expr\Array_
            ) {
                continue;
            }
            if (
                !$child instanceof Op\Expr\FuncCall
                && !$child instanceof Op\Expr\NsFuncCall
            ) {
                return false;
            }
            if ('var_export' !== $this->resolveCfgFuncCallName($child)) {
                return false;
            }
            $callArg = $child->args[0] ?? null;

            return null !== $callArg && $this->callArgIsDeadInlineTemporary($callArg);
        }

        return false;
    }

    /**
     * php-cfg `var_export($it->current(), true)` hoists MethodCall sibling; ConstFetch `true` may sit between (#13901).
     */
    private function siblingMethodCallFeedsVarExportConsumer(Op $cfgCallOp, Block $block, int $producerIndex): bool
    {
        if (!$cfgCallOp instanceof Op\Expr\MethodCall && !$cfgCallOp instanceof Op\Expr\StaticCall) {
            return false;
        }
        $cfgChildren = $block->orig->children;
        for ($i = $producerIndex + 1, $n = \count($cfgChildren); $i < $n; ++$i) {
            $child = $cfgChildren[$i];
            if (
                $child instanceof Op\Expr\ConstFetch
                || $child instanceof Op\Expr\ClassConstFetch
                || $child instanceof Op\Expr\Array_
            ) {
                continue;
            }
            if (
                !$child instanceof Op\Expr\FuncCall
                && !$child instanceof Op\Expr\NsFuncCall
            ) {
                return false;
            }
            if ('var_export' !== $this->resolveCfgFuncCallName($child)) {
                return false;
            }
            $callArg = $child->args[0] ?? null;

            return null !== $callArg && $this->callArgIsDeadInlineTemporary($callArg);
        }

        return false;
    }

    /**
     * php-cfg splits `(void) f()` into adjacent FuncCall + Cast_Void with distinct SSA temps (#9779).
     * Use EXEC_RETURN so #[\NoDiscard] sees an intentional discard (Zend zend_execute.c).
     */
    private function cfgCallOpImmediatelyVoidDiscarded(?Op $cfgCallOp, Block $block): bool
    {
        if (null === $cfgCallOp || null === $block->orig) {
            return false;
        }
        $ops = $block->orig->children;
        $count = \count($ops);
        for ($i = 0; $i < $count - 1; ++$i) {
            if ($ops[$i] !== $cfgCallOp) {
                continue;
            }

            return $ops[$i + 1] instanceof Op\Expr\Cast\Void_;
        }

        return false;
    }

    /**
     * Hoisted inline nested FuncCall producers compile into $argSends — emit them before outer INIT (#13636).
     *
     * @param list<OpCode> $argSends
     *
     * @return array{0: list<OpCode>, 1: list<OpCode>}
     */
    private function partitionNestedInlineCallArgProducerOps(array $argSends): array
    {
        $nested = [];
        $outer = [];
        $count = \count($argSends);
        for ($i = 0; $i < $count; ++$i) {
            $op = $argSends[$i];
            if (!$this->isInlineCallArgProducerInitOpcode($op)) {
                $outer[] = $op;
                continue;
            }
            $depth = 1;
            $chunk = [$op];
            ++$i;
            while ($i < $count && $depth > 0) {
                $inner = $argSends[$i];
                $chunk[] = $inner;
                if ($this->isInlineCallArgProducerInitOpcode($inner)) {
                    ++$depth;
                } elseif ($this->isInlineCallArgProducerExecOpcode($inner)) {
                    --$depth;
                }
                ++$i;
            }
            --$i;
            foreach ($chunk as $nestedOp) {
                $nested[] = $nestedOp;
            }
        }

        return [$nested, $outer];
    }

    /**
     * array_diff_assoc(array_keys(), array_keys()) — deferred sibling batch may miswire INIT_ARRAY ordinal (#16418).
     *
     * @param list<OpCode> $outerArgSends
     */
    private function rewireArrayKeysInlineInitArrayArgSendSlots(
        array &$outerArgSends,
        Block $block,
        ?Op $cfgCallOp,
        ?string $calleeName,
        array $pendingOps = []
    ): void {
        if (null === $cfgCallOp || 'array_keys' !== strtolower($calleeName ?? $this->resolveCfgFuncCallName($cfgCallOp) ?? '')) {
            return;
        }
        $callArg = $cfgCallOp->args[0] ?? null;
        if (!$callArg instanceof Operand) {
            return;
        }
        if (
            !$this->callArgIsDeadInlineTemporary($callArg)
            || !$this->callArgOperandExpectsArrayProducer($callArg)
            || $this->callArgIsCoalesceMergeProducer($callArg, $block, $cfgCallOp, 0)
        ) {
            return;
        }
        if ($this->callArgIsCoalesceMergeProducer($callArg, $block, $cfgCallOp, 0)) {
            // array_keys(f()[k] ?? []) — keep coalesce merge slot, not ?? RHS INIT_ARRAY (#16127, re-#16435).
            return;
        }
        // array_keys(array_flip([...])) / array_keys($ao->getArrayCopy()) — adjacent call result
        // feeds arg #0; do not steal nested INIT_ARRAY (#21981, #25812).
        if (null !== $block->orig) {
            $callIndex = array_search($cfgCallOp, $block->orig->children, true);
            if (\is_int($callIndex) && $callIndex > 0) {
                $adjacentIndex = $callIndex - 1;
                while ($adjacentIndex >= 0) {
                    $skip = $block->orig->children[$adjacentIndex] ?? null;
                    if ($skip instanceof Op\Expr\ConstFetch || $skip instanceof Op\Expr\ClassConstFetch) {
                        --$adjacentIndex;
                        continue;
                    }
                    if ($this->isUnaryInlineSiblingCallArgExpr($skip)) {
                        --$adjacentIndex;
                        continue;
                    }
                    break;
                }
                $adjacent = $block->orig->children[$adjacentIndex] ?? null;
                if (
                    $adjacent instanceof Op\Expr\FuncCall
                    || $adjacent instanceof Op\Expr\NsFuncCall
                    || $adjacent instanceof Op\Expr\MethodCall
                    || $adjacent instanceof Op\Expr\StaticCall
                    // array_keys((array)$ao) — Cast result already wired; do not steal ctor INIT_ARRAY (#28822).
                    || $adjacent instanceof Op\Expr\Cast
                ) {
                    return;
                }
            }
        }
        $correctOrdinal = $this->inlineArrayKeysHoistedArrayOrdinal($block, $cfgCallOp);
        $correctSlot = null !== $correctOrdinal
            ? $this->slotForInitArrayOrdinal($block, $correctOrdinal, $pendingOps)
            : null;
        if (null === $correctSlot) {
            $correctSlot = $this->slotForInitArrayProducerBeforeCfgCall(
                $block,
                $cfgCallOp,
                $this->inlineArrayProducerForArrayKeysDeadCallArg($callArg, $block, $cfgCallOp),
                $pendingOps
            );
        }
        if (null === $correctSlot) {
            return;
        }
        foreach ($outerArgSends as $send) {
            if (OpCode::TYPE_ARG_SEND !== $send->type) {
                continue;
            }
            $send->arg1 = $correctSlot;

            return;
        }
    }

    /**
     * decoct(fileperms($f) & 0777) on CFG branch blocks — ARG_SEND must use the AND dest (#15902).
     *
     * Only when the arithmetic producer immediately precedes this call. A sibling
     * `get(Box::Y)+1` leaves TYPE_PLUS in the merge block; the next `get(Box::Z)` must
     * keep its ClassConstFetch slot, not steal the plus result (#26990).
     *
     * @param list<OpCode> $outerArgSends
     * @param list<OpCode> $nestedProducerOps
     */
    private function rewireInlineArithmeticBranchCallArgSendSlots(
        array &$outerArgSends,
        array $nestedProducerOps,
        Block $block,
        ?Op $cfgCallOp
    ): void {
        if ((!$block->inheritUndefinedLocals && !$block->arrowAutoCapture) || null === $cfgCallOp) {
            return;
        }
        $callArg = $cfgCallOp->args[0] ?? null;
        if (
            1 !== \count($cfgCallOp->args ?? [])
            || !$this->callArgIsDeadInlineTemporary($callArg)
            || $this->callArgIsCoalesceMergeProducer($callArg, $block, $cfgCallOp, 0)
        ) {
            return;
        }
        // Intervening ClassConstFetch/ConstFetch before this call — not decoct(expr&mask) (#26990).
        if (!$this->cfgCallImmediatelyConsumesPrecedingArithmetic($block, $cfgCallOp)) {
            return;
        }
        $dest = $this->slotForRecentInlineArithmeticCallArg(
            $block,
            array_merge($nestedProducerOps, $outerArgSends)
        );
        if (null === $dest) {
            return;
        }
        foreach ($outerArgSends as $send) {
            if (OpCode::TYPE_ARG_SEND === $send->type) {
                $send->arg1 = $dest;
            }
        }
    }

    /**
     * True when the CFG child immediately before $cfgCallOp is an arithmetic/bitwise
     * producer feeding that call (#15902 decoct; negative for #26990 ClassConstFetch).
     */
    private function cfgCallImmediatelyConsumesPrecedingArithmetic(Block $block, Op $cfgCallOp): bool
    {
        $callIndex = $this->cfgCallOpIndex($block, $cfgCallOp);
        if (!\is_int($callIndex) || $callIndex < 1 || null === $block->orig) {
            return false;
        }
        $prev = $block->orig->children[$callIndex - 1] ?? null;

        return $this->isArithmeticInlineCallArgProducer($prev);
    }

    /**
     * substr(sprintf('%o', fileperms($path)), -N) after stmt-level calls — haystack ARG_SEND (#16451, #16480).
     *
     * @param list<OpCode> $outerArgSends
     * @param list<OpCode> $pendingNestedProducerOps
     */
    private function rewireSubstrNestedSprintfArgSendSlots(
        array &$outerArgSends,
        Block $block,
        ?Op $cfgCallOp,
        ?string $calleeName = null
    ): void {
        if (null === $cfgCallOp || null === $block->orig) {
            return;
        }
        if (!\is_array($cfgCallOp->args ?? null) || \count($cfgCallOp->args) < 2) {
            return;
        }
        if ('substr' !== strtolower($this->resolveInlineCallArgFuncName($cfgCallOp, $calleeName) ?? '')) {
            return;
        }
        $callIndex = $this->cfgCallOpIndex($block, $cfgCallOp);
        if (!\is_int($callIndex)) {
            return;
        }
        $cfgChildren = $block->orig->children;
        $nestedHaystack = $this->substrNestedHaystackFuncCallAtUnaryMinusPattern(
            $cfgCallOp,
            $callIndex,
            $cfgChildren
        );
        if (null === $nestedHaystack) {
            return;
        }
        $haystackSlot = $this->slotForSubstrNestedHaystackFuncCallExecReturn(
            $block,
            $nestedHaystack[0],
            $nestedHaystack[1],
            $cfgChildren
        );
        if (null === $haystackSlot) {
            return;
        }
        $offsetOp = $cfgChildren[$callIndex - 1] ?? null;
        $argSendIndex = 0;
        foreach ($outerArgSends as $send) {
            if (OpCode::TYPE_ARG_SEND !== $send->type) {
                continue;
            }
            if (0 === $argSendIndex) {
                $send->arg1 = $haystackSlot;
            } elseif (
                1 === $argSendIndex
                && $offsetOp instanceof Op\Expr\UnaryMinus
            ) {
                $inner = $offsetOp->expr ?? null;
                if ($inner instanceof Operand\Literal && is_numeric($inner->value)) {
                    $negated = is_int($inner->value) ? -(int) $inner->value : -(float) $inner->value;
                    $send->arg1 = (string) $this->freshLiteralConstantSlot(
                        new Operand\Literal($negated),
                        $block
                    );
                }
            }
            ++$argSendIndex;
        }
    }

    /**
     * tempnam(sys_get_temp_dir(), E::A) — nested FuncCall EXEC_RETURN is arg #0; enum ClassConstFetch is arg #1 (#10303, #16558).
     *
     * @param list<OpCode> $outerArgSends
     * @param list<OpCode> $pendingNestedProducerOps
     */
    private function rewireNestedFuncCallEnumPrefixCallArgSendSlots(
        array &$outerArgSends,
        Block $block,
        Op $cfgCallOp,
        array $pendingNestedProducerOps = []
    ): void {
        if (null === $block->orig || 2 !== \count($cfgCallOp->args ?? [])) {
            return;
        }
        $callIndex = $this->cfgCallOpIndex($block, $cfgCallOp);
        if (!\is_int($callIndex) || $callIndex < 2) {
            return;
        }
        $nestedCall = $block->orig->children[$callIndex - 2] ?? null;
        $enumFetch = $block->orig->children[$callIndex - 1] ?? null;
        if (
            !($nestedCall instanceof Op\Expr\FuncCall || $nestedCall instanceof Op\Expr\NsFuncCall)
            || !$enumFetch instanceof Op\Expr\ClassConstFetch
            || !$this->nestedFuncCallProducerSeparatedBySkippablePreludesOnly(
                $callIndex - 2,
                $callIndex,
                $block->orig->children
            )
        ) {
            return;
        }
        $execReturnCount = 0;
        foreach ($block->opCodes as $op) {
            if (OpCode::TYPE_FUNCCALL_EXEC_RETURN === $op->type && null !== $op->arg1) {
                ++$execReturnCount;
            }
        }
        foreach ($pendingNestedProducerOps as $op) {
            if (OpCode::TYPE_FUNCCALL_EXEC_RETURN === $op->type && null !== $op->arg1) {
                ++$execReturnCount;
            }
        }
        $execSlot = $this->slotForSiblingInlineFuncCallProducerExecReturnOrdinalWithPending(
            $block,
            max(0, $execReturnCount - 1),
            $pendingNestedProducerOps
        );
        if (null === $execSlot) {
            $execSlot = $block->slotForOperand($nestedCall->result);
        }
        $enumSlot = $block->slotForOperand($enumFetch->result);
        if (null === $enumSlot) {
            foreach ($this->compileExpr($enumFetch, $block) as $op) {
                $block->addOpCode($op);
            }
            $enumSlot = $block->slotForOperand($enumFetch->result);
        }
        if (null === $execSlot || null === $enumSlot) {
            return;
        }
        $argIndex = 0;
        foreach ($outerArgSends as $send) {
            if (OpCode::TYPE_ARG_SEND !== $send->type) {
                continue;
            }
            if (0 === $argIndex) {
                $send->arg1 = (string) $execSlot;
            } elseif (1 === $argIndex) {
                $send->arg1 = (string) $enumSlot;
            }
            ++$argIndex;
        }
    }

    /**
     * count($ref->getAttributes(...)) — wire MethodCall EXEC_RETURN into the outer ARG_SEND (#21867, #22693).
     *
     * Covers filtered getAttributes(Foo::class) (hoisted ClassConstFetch prelude) and bare
     * getAttributes() (no prelude). Without this, ARG_SEND keeps an earlier dead temp (often a
     * prior ::class string / null) and count() TypeErrors on null.
     *
     * @param list<OpCode> $outerArgSends
     * @param list<OpCode> $pendingNestedProducerOps
     */
    private function rewireNestedMethodCallHoistedClassConstOuterCallArgSendSlots(
        array &$outerArgSends,
        Block $block,
        ?Op $cfgCallOp,
        array $pendingNestedProducerOps = []
    ): void {
        if (null === $cfgCallOp || null === $block->orig) {
            return;
        }
        if (!\is_array($cfgCallOp->args ?? null) || 1 !== \count($cfgCallOp->args)) {
            return;
        }
        $callArg = $cfgCallOp->args[0] ?? null;
        if (!$this->callArgIsDeadInlineTemporary($callArg)) {
            return;
        }
        $callIndex = $this->cfgCallOpIndex($block, $cfgCallOp);
        if (!\is_int($callIndex) || $callIndex < 1) {
            return;
        }
        $producer = $block->orig->children[$callIndex - 1] ?? null;
        if (
            !$producer instanceof Op\Expr\MethodCall
            && !$producer instanceof Op\Expr\StaticCall
        ) {
            return;
        }
        // Filtered form: ClassConstFetch immediately before MethodCall feeds the method arg.
        // If the outer dead temp is that ClassConstFetch result, wiring is already correct.
        if ($callIndex >= 2) {
            $prelude = $block->orig->children[$callIndex - 2] ?? null;
            if (
                $prelude instanceof Op\Expr\ClassConstFetch
                && $callArg instanceof Operand
                && $this->operandsReferToSameVariable($prelude->result, $callArg)
            ) {
                return;
            }
        }
        $execSlot = $this->slotForMethodOrStaticCallInitFollowingExecReturn(
            $block,
            $producer,
            $pendingNestedProducerOps
        );
        if (null === $execSlot) {
            $execSlot = $this->slotForSiblingMethodCallProducerExecReturn(
                $block,
                $producer,
                $cfgCallOp,
                $block->orig->children
            );
        }
        if (null === $execSlot) {
            return;
        }
        foreach ($outerArgSends as $send) {
            if (OpCode::TYPE_ARG_SEND !== $send->type) {
                continue;
            }
            $send->arg1 = (string) $execSlot;

            return;
        }
    }

    /**
     * var_dump(f(), g()) after an earlier sibling chain — map ARG_SEND to chain EXEC_RETURN slots (#16254).
     *
     * @param list<OpCode> $outerArgSends
     */
    private function rewireSiblingMultiArgInlineCallArgSendSlots(
        array &$outerArgSends,
        Block $block,
        ?Op $cfgCallOp,
        array $pendingNestedProducerOps = []
    ): void {
        if (null === $cfgCallOp || null === $block->orig) {
            return;
        }
        if (!\is_array($cfgCallOp->args ?? null) || \count($cfgCallOp->args) < 2) {
            return;
        }
        $callIndex = $this->cfgCallOpIndex($block, $cfgCallOp);
        if (!\is_int($callIndex)) {
            return;
        }
        $cfgChildren = $block->orig->children;
        if ($this->isSubstrNestedSprintfUnaryMinusPattern($cfgCallOp, $callIndex, $cfgChildren)) {
            return;
        }
        $firstSibling = $this->firstContiguousSiblingMultiArgProducerIndex(
            $callIndex,
            $cfgCallOp,
            $cfgChildren
        );
        if (!\is_int($firstSibling)) {
            $firstSibling = $this->firstSiblingInlineFuncCallProducerIndexImpl(
                $callIndex,
                $cfgChildren
            );
        }
        if (!\is_int($firstSibling) || ($callIndex - $firstSibling) < 2) {
            return;
        }
        $chainProducerCount = $this->countContiguousSiblingMultiArgProducers(
            $firstSibling,
            $callIndex,
            $cfgCallOp,
            $cfgChildren
        );
        if ($chainProducerCount < 2) {
            if (!$this->nestedFuncCallFeedsDeadInlineCallArgZero($block, $cfgCallOp, 0)) {
                return;
            }
            $this->rewireNestedFuncCallEnumPrefixCallArgSendSlots(
                $outerArgSends,
                $block,
                $cfgCallOp,
                $pendingNestedProducerOps
            );

            return;
        }
        $execReturnCount = 0;
        foreach ($block->opCodes as $op) {
            if (OpCode::TYPE_FUNCCALL_EXEC_RETURN === $op->type && null !== $op->arg1) {
                ++$execReturnCount;
            }
        }
        foreach ($pendingNestedProducerOps as $op) {
            if (OpCode::TYPE_FUNCCALL_EXEC_RETURN === $op->type && null !== $op->arg1) {
                ++$execReturnCount;
            }
        }
        $argIndex = 0;
        $callbackArgIndex = $this->inlineClosureArrayPairCallbackArgIndex(
            $this->resolveCfgFuncCallName($cfgCallOp)
        );
        foreach ($outerArgSends as $send) {
            if (OpCode::TYPE_ARG_SEND !== $send->type) {
                continue;
            }
            if (
                $callbackArgIndex >= 0
                && $argIndex === $callbackArgIndex
                && null !== $this->leadingCallbackFirstInlineProducerBeforeCfgCall($cfgCallOp, $block)
            ) {
                // array_map(intval(...), str_split(str_repeat(...))) — keep FCC slot, not haystack EXEC_RETURN (#16279).
                ++$argIndex;
                continue;
            }
            if (
                0 === $argIndex
                && 1 === $callbackArgIndex
                && 2 === \count($cfgCallOp->args ?? [])
            ) {
                $trailingHaystack = $this->trailingInlineFuncCallHaystackBeforeCfgCall($cfgCallOp, $block);
                if (
                    $trailingHaystack instanceof Op\Expr\FuncCall
                    || $trailingHaystack instanceof Op\Expr\NsFuncCall
                ) {
                    // array_filter(str_split(...), …) after a prior filter+var_dump — bind haystack
                    // EXEC_RETURN explicitly; sibling ordinal steals var_dump (#27344 / #15490).
                    $haystackSlot = $block->slotForOperand($trailingHaystack->result);
                    if (null === $haystackSlot) {
                        $haystackIndex = array_search($trailingHaystack, $cfgChildren, true);
                        $haystackSlot = \is_int($haystackIndex)
                            ? $this->slotForInlineFuncCallProducerExecReturnByCfgIndex(
                                $block,
                                $haystackIndex,
                                $cfgChildren
                            )
                            : null;
                    }
                    if (null !== $haystackSlot) {
                        $send->arg1 = (string) $haystackSlot;
                    }
                    ++$argIndex;
                    continue;
                }
            }
            $hoistedPrelude = $this->hoistedPreludeProducerForCallArgIndex($cfgCallOp, $argIndex, $block);
            if (
                $hoistedPrelude instanceof Op\Expr\ConstFetch
                || $hoistedPrelude instanceof Op\Expr\ClassConstFetch
            ) {
                // setlocale(LC_ALL, null) after earlier setlocale stmts — keep hoisted LC_* / null prelude (#10177).
                ++$argIndex;
                continue;
            }
            if ($this->callArgHasHoistedConstPrelude($cfgCallOp, $argIndex, $block)) {
                ++$argIndex;
                continue;
            }
            if ($this->opcodeSlotIsHoistedConstPrelude($block, $send->arg1, $pendingNestedProducerOps)) {
                ++$argIndex;
                continue;
            }
            $multiArgCallArg = $cfgCallOp->args[$argIndex] ?? null;
            if (!$this->callArgIsDeadInlineTemporary($multiArgCallArg)) {
                ++$argIndex;
                continue;
            }
            if (
                'var_export' === strtolower($this->resolveCfgFuncCallName($cfgCallOp) ?? '')
                && $multiArgCallArg instanceof Operand
                && $this->isCallArgDirectArrayDimFetch($multiArgCallArg)
            ) {
                ++$argIndex;
                continue;
            }
            $preludeSlot = $this->slotForImmediateConstFetchPreludeCallArg($block, $cfgCallOp, $argIndex);
            if (null !== $preludeSlot) {
                $send->arg1 = (string) $preludeSlot;
                ++$argIndex;
                continue;
            }
            $producerIndex = null;
            for ($j = $firstSibling; $j < $callIndex; ++$j) {
                $scan = $cfgChildren[$j] ?? null;
                if (!$scan instanceof Op\Expr) {
                    continue;
                }
                $feedsArg = $this->isSiblingMultiArgFuncCallProducer(
                    $scan,
                    $cfgCallOp,
                    $j,
                    $callIndex,
                    $cfgChildren
                ) || $this->isNestedCallArgProducerForConsumer(
                    $scan,
                    $cfgCallOp,
                    $j,
                    $callIndex,
                    $cfgChildren
                );
                if (!$feedsArg) {
                    continue;
                }
                if (
                    $this->siblingMultiArgFuncCallProducerTargetArgIndex(
                        $j,
                        $callIndex,
                        $cfgChildren
                    ) === $argIndex
                ) {
                    $producerIndex = $j;
                    break;
                }
            }
            if (!\is_int($producerIndex)) {
                ++$argIndex;
                continue;
            }
            $consumerName = $this->resolveCfgFuncCallName($cfgCallOp);
            $callbackArgIndex = $this->inlineClosureArrayPairCallbackArgIndex($consumerName);
            $leadingCallback = $this->leadingCallbackFirstInlineProducerBeforeCfgCall($cfgCallOp, $block);
            if (
                $callbackArgIndex >= 0
                && 2 === \count($cfgCallOp->args ?? [])
                && $argIndex === $callbackArgIndex
                && ($leadingCallback instanceof Op\Expr\ArrowFunction
                    || $leadingCallback instanceof Op\Expr\Closure
                    || $leadingCallback instanceof Op\Expr\FirstClassCallable)
            ) {
                // array_map(intval(...), str_split(...)) — keep FCC/closure send slot (#15487, #16279).
                ++$argIndex;
                continue;
            }
            $siblingOrdinal = $this->siblingInlineFuncCallProducerOrdinal(
                $producerIndex,
                $firstSibling,
                $block->orig->children
            );
            $execOrdinal = $execReturnCount - $chainProducerCount + $siblingOrdinal;
            $slot = $this->slotForSiblingInlineFuncCallProducerExecReturnOrdinalWithPending(
                $block,
                $execOrdinal,
                $pendingNestedProducerOps
            );
            if (null !== $slot) {
                $send->arg1 = (string) $slot;
            }
            ++$argIndex;
        }
    }

    /**
     * Map dead inline call-arg temps to hoisted UnaryMinus/ConstFetch preludes before the callee (#16523).
     */
    private function hoistedDeadInlinePreludeProducerForCallArgIndex(Op $callOp, int $argIndex, Block $block): ?Op\Expr
    {
        if (!property_exists($callOp, 'args') || !\is_array($callOp->args)) {
            return null;
        }
        $callArg = $callOp->args[$argIndex] ?? null;
        if (!$this->callArgIsDeadInlineTemporary($callArg)) {
            return null;
        }
        if ($this->callArgOperandExpectsArrayProducer($callArg)) {
            return null;
        }
        $preludes = $this->hoistedPreludeProducersImmediatelyBeforeCall($callOp, $block);
        if ([] === $preludes) {
            return null;
        }
        $deadInlineArgCount = 0;
        foreach ($callOp->args as $deadArg) {
            if ($this->isEmbeddedCallLiteralArg($deadArg)) {
                continue;
            }
            if ($this->callArgIsDeadInlineTemporary($deadArg)) {
                ++$deadInlineArgCount;
            }
        }
        // in_array('x', g(), true) — hoisted FuncCall between trailing ConstFetch and consumer (#16540).
        if ($deadInlineArgCount !== \count($preludes)) {
            return null;
        }
        $preludeOrdinal = 0;
        foreach ($callOp->args as $i => $deadArg) {
            if ($this->isEmbeddedCallLiteralArg($deadArg)) {
                continue;
            }
            if (!$this->callArgIsDeadInlineTemporary($deadArg)) {
                continue;
            }
            if ($deadArg instanceof Operand && $this->callArgOperandExpectsArrayProducer($deadArg)) {
                continue;
            }
            if ($i === $argIndex) {
                $prelude = $preludes[$preludeOrdinal] ?? null;
                if (
                    ($prelude instanceof Op\Expr\ConstFetch || $prelude instanceof Op\Expr\ClassConstFetch)
                    && $callArg instanceof Operand
                    && $this->callArgOperandExpectsArrayProducer($callArg)
                    && null !== $block->orig
                ) {
                    // in_array('x', get_declared_classes(), true) — strict ConstFetch is not haystack (#16540, re-#16312).
                    $producers = $this->precedingInlineCallArgProducersBeforeCfgOp($block->orig->children, $callOp);
                    $matched = $this->matchInlineCallArgProducer($producers, $callOp->args, $argIndex, $callOp, $block);
                    if (
                        $matched instanceof Op\Expr\FuncCall
                        || $matched instanceof Op\Expr\NsFuncCall
                        || $matched instanceof Op\Expr\StaticCall
                        || $matched instanceof Op\Expr\MethodCall
                    ) {
                        return $matched;
                    }

                    return null;
                }

                return $prelude instanceof Op\Expr ? $prelude : null;
            }
            ++$preludeOrdinal;
        }

        return null;
    }

    /**
     * Hoisted ConstFetch/ClassConstFetch immediately before a call feeds a dead inline arg (#10177).
     */
    private function callArgHasHoistedConstPrelude(Op $cfgCallOp, int $argIndex, Block $block): bool
    {
        if ('setlocale' !== strtolower($this->resolveCfgFuncCallName($cfgCallOp) ?? '')) {
            return false;
        }
        if (!property_exists($cfgCallOp, 'args') || !\is_array($cfgCallOp->args)) {
            return false;
        }
        $preludes = $this->hoistedPreludeProducersImmediatelyBeforeCall($cfgCallOp, $block);
        if ([] === $preludes) {
            $preludes = $this->hoistedPreludeProducersBeforeAssignStmt($cfgCallOp, $block);
        }
        if ([] === $preludes) {
            return false;
        }
        $preludeOrdinal = 0;
        foreach ($cfgCallOp->args as $i => $callArg) {
            if ($this->isEmbeddedCallLiteralArg($callArg)) {
                continue;
            }
            if (!$this->callArgIsDeadInlineTemporary($callArg)) {
                continue;
            }
            if ($i === $argIndex) {
                $prelude = $preludes[$preludeOrdinal] ?? null;

                return $prelude instanceof Op\Expr\ConstFetch
                    || $prelude instanceof Op\Expr\ClassConstFetch;
            }
            ++$preludeOrdinal;
        }

        return false;
    }

    /**
     * ARG_SEND already wired to hoisted ConstFetch — do not replace with sibling EXEC_RETURN (#10177).
     *
     * @param list<OpCode> $pendingNestedProducerOps
     */
    private function opcodeSlotIsHoistedConstPrelude(
        Block $block,
        int|string|null $slot,
        array $pendingNestedProducerOps = []
    ): bool {
        if (null === $slot) {
            return false;
        }
        $slot = (string) $slot;
        foreach (array_merge($block->opCodes, $pendingNestedProducerOps) as $op) {
            if (
                (OpCode::TYPE_CONST_FETCH === $op->type || OpCode::TYPE_CLASS_CONST_FETCH === $op->type)
                && (string) $op->arg1 === $slot
            ) {
                return true;
            }
        }

        return false;
    }

    /**
     * method_exists(I::class, 'm') after earlier stmts — sibling rewire must not steal hoisted ::class slot (#9486).
     *
     * @param list<OpCode> $outerArgSends
     * @param list<OpCode> $pendingNestedProducerOps
     */
    /**
     * register_shutdown_function(fn(...), E::A) — Closure + enum case hoisted siblings (#5751).
     *
     * @param list<OpCode> $outerArgSends
     * @param list<OpCode> $pendingNestedProducerOps
     */
    private function rewireRegisterShutdownFunctionClosureEnumCallArgSendSlots(
        array &$outerArgSends,
        Block $block,
        ?Op $cfgCallOp,
        array $pendingNestedProducerOps = []
    ): void {
        if (null === $cfgCallOp || null === $block->orig) {
            return;
        }
        if ('register_shutdown_function' !== $this->resolveCfgFuncCallName($cfgCallOp)) {
            return;
        }
        if (!\is_array($cfgCallOp->args ?? null) || 2 !== \count($cfgCallOp->args)) {
            return;
        }
        $callIndex = $this->cfgCallOpIndex($block, $cfgCallOp);
        if (!\is_int($callIndex) || $callIndex < 2) {
            return;
        }
        $closureExpr = $block->orig->children[$callIndex - 2] ?? null;
        $enumExpr = $block->orig->children[$callIndex - 1] ?? null;
        if (!($closureExpr instanceof Op\Expr\Closure || $closureExpr instanceof Op\Expr\ArrowFunction)) {
            return;
        }
        if (!$enumExpr instanceof Op\Expr\ClassConstFetch) {
            return;
        }
        $closureSlot = $block->slotForOperand($closureExpr->result);
        $enumSlot = $block->slotForOperand($enumExpr->result);
        if (null === $closureSlot) {
            foreach ($pendingNestedProducerOps as $op) {
                if (OpCode::TYPE_CLOSURE === $op->type) {
                    $closureSlot = (string) $op->arg1;
                    break;
                }
            }
        }
        if (null === $enumSlot) {
            foreach ($pendingNestedProducerOps as $op) {
                if (OpCode::TYPE_CLASS_CONST_FETCH === $op->type) {
                    $enumSlot = (string) $op->arg1;
                    break;
                }
            }
        }
        if (null === $closureSlot || null === $enumSlot) {
            return;
        }
        $argIndex = 0;
        foreach ($outerArgSends as $send) {
            if (OpCode::TYPE_ARG_SEND !== $send->type) {
                continue;
            }
            $send->arg1 = 0 === $argIndex ? $closureSlot : $enumSlot;
            ++$argIndex;
        }
    }

    private function rewireHoistedClassConstPreludeCallArgSendSlots(
        array &$outerArgSends,
        Block $block,
        ?Op $cfgCallOp,
        array $pendingNestedProducerOps = []
    ): void {
        if (null === $cfgCallOp || null === $block->orig) {
            return;
        }
        if (!\is_array($cfgCallOp->args ?? null) || [] === $cfgCallOp->args) {
            return;
        }
        $callIndex = array_search($cfgCallOp, $block->orig->children, true);
        if (!\is_int($callIndex) || $callIndex < 1) {
            return;
        }
        $prelude = $block->orig->children[$callIndex - 1] ?? null;
        if (!$prelude instanceof Op\Expr\ClassConstFetch) {
            return;
        }
        if ($this->nestedFuncCallFeedsDeadInlineCallArgZero($block, $cfgCallOp, 0)) {
            return;
        }
        $callArg = $cfgCallOp->args[0] ?? null;
        if (!$this->callArgIsDeadInlineTemporary($callArg)) {
            return;
        }
        if (
            null !== $callArg
            && !$this->operandsReferToSameVariable($prelude->result, $callArg)
        ) {
            // array_pad([E::A], N, E::B) / extract([...], FLAGS, Prefix::A) — immediate ClassConstFetch is not arg #0 (#8883, #16041).
            // preg_replace_callback_array([...], E::CASE) — enum prelude feeds arg #1 (#5859).
            return;
        }
        if (
            'preg_replace_callback_array' === $this->resolveCfgFuncCallName($cfgCallOp)
            && \is_int($callIndex)
            && $callIndex >= 2
            && ($block->orig->children[$callIndex - 2] ?? null) instanceof Op\Expr\Array_
        ) {
            return;
        }
        if (null === $block->slotForOperand($prelude->result)) {
            foreach ($this->compileExpr($prelude, $block) as $op) {
                $block->addOpCode($op);
            }
        }
        $preludeSlot = $block->slotForOperand($prelude->result);
        if (null === $preludeSlot) {
            foreach ($pendingNestedProducerOps as $op) {
                if (OpCode::TYPE_CLASS_CONST_FETCH === $op->type) {
                    $preludeSlot = (string) $op->arg1;
                    break;
                }
            }
        }
        if (null === $preludeSlot) {
            return;
        }
        $argIndex = 0;
        foreach ($outerArgSends as $send) {
            if (OpCode::TYPE_ARG_SEND !== $send->type) {
                continue;
            }
            if (0 === $argIndex) {
                $send->arg1 = (string) $preludeSlot;
            }
            ++$argIndex;
        }
    }

    /**
     * preg_replace_callback_array(['/pat/' => $cb], E::CASE) — pattern Array_ is arg #0, enum case arg #1 (#5859, #9072).
     *
     * @param list<OpCode> $outerArgSends
     * @param list<OpCode> $allArgSends
     */
    private function rewirePregReplaceCallbackArrayPatternMapArgSendSlots(
        array &$outerArgSends,
        Block $block,
        ?Op $cfgCallOp,
        array $allArgSends = []
    ): void {
        if (null === $cfgCallOp || null === $block->orig) {
            return;
        }
        if ('preg_replace_callback_array' !== $this->resolveCfgFuncCallName($cfgCallOp)) {
            return;
        }
        if (2 !== \count($cfgCallOp->args ?? [])) {
            return;
        }
        $callIndex = $this->cfgCallOpIndex($block, $cfgCallOp);
        if (!\is_int($callIndex) || $callIndex < 2) {
            return;
        }
        $patternMap = $block->orig->children[$callIndex - 2] ?? null;
        $subjectPrelude = $block->orig->children[$callIndex - 1] ?? null;
        if (!$patternMap instanceof Op\Expr\Array_) {
            return;
        }
        if (!$subjectPrelude instanceof Op\Expr\ClassConstFetch) {
            return;
        }
        $initSlot = null;
        foreach (array_merge($block->opCodes, $allArgSends) as $op) {
            if (OpCode::TYPE_INIT_ARRAY === $op->type && null !== $op->arg1) {
                $initSlot = (string) $op->arg1;
            }
        }
        if (null === $initSlot) {
            $initSlot = $block->slotForOperand($patternMap->result);
            if (null !== $initSlot) {
                $initSlot = (string) $initSlot;
            }
        }
        $enumSlot = $block->slotForOperand($subjectPrelude->result);
        if (null === $enumSlot) {
            foreach ($this->compileExpr($subjectPrelude, $block) as $op) {
                $block->addOpCode($op);
            }
            $enumSlot = $block->slotForOperand($subjectPrelude->result);
        }
        if (null === $initSlot || null === $enumSlot) {
            return;
        }
        $argIndex = 0;
        foreach ($outerArgSends as &$send) {
            if (OpCode::TYPE_ARG_SEND !== $send->type) {
                continue;
            }
            if (0 === $argIndex) {
                $send->arg1 = $initSlot;
            } elseif (1 === $argIndex) {
                $send->arg1 = (string) $enumSlot;
            }
            ++$argIndex;
        }
        unset($send);
    }

    /**
     * array_combine([...], [...]) — ARG_SEND must map to sibling INIT_ARRAY slots, not recent-init (#16080, #10214, #17629).
     *
     * @param list<OpCode> $outerArgSends
     * @param list<OpCode> $allArgSends
     */
    private function rewireArrayCombineInlineArgSendSlots(
        array &$outerArgSends,
        Block $block,
        array $allArgSends,
        ?string $calleeName,
        ?Op $cfgCallOp
    ): void {
        if (null === $cfgCallOp || 2 !== \count($cfgCallOp->args ?? [])) {
            return;
        }
        $calleeLower = strtolower($calleeName ?? $this->resolveCfgFuncCallName($cfgCallOp) ?? '');
        if ('array_combine' !== $calleeLower) {
            return;
        }
        if (null === $block->orig) {
            return;
        }
        foreach ($this->precedingInlineCallArgProducersBeforeCfgOp(
            $block->orig->children,
            $cfgCallOp
        ) as $producer) {
            if ($producer instanceof Op\Expr\FuncCall || $producer instanceof Op\Expr\NsFuncCall) {
                // array_combine(array_keys(...), [...]) — nested FuncCall feeds arg #0 (#16097).
                return;
            }
        }
        foreach ($cfgCallOp->args as $callArg) {
            if (
                null === $callArg
                || !$this->callArgIsDeadInlineTemporary($callArg)
                || !$this->callArgOperandExpectsArrayProducer($callArg)
            ) {
                return;
            }
        }
        $initSlots = $this->initArraySlotsForCurrentFunccall($block, $allArgSends);
        if (\count($initSlots) > 2) {
            // [] === array_combine([], []) — comparison lhs Array_ shares the post-call INIT_ARRAY window (#17629).
            $initSlots = \array_slice($initSlots, -2);
        }
        if (\count($initSlots) < 2) {
            return;
        }
        $sendOrdinal = 0;
        foreach ($outerArgSends as &$send) {
            if (OpCode::TYPE_ARG_SEND !== $send->type) {
                continue;
            }
            if (isset($initSlots[$sendOrdinal])) {
                $send->arg1 = $initSlots[$sendOrdinal];
            }
            ++$sendOrdinal;
        }
        unset($send);
    }

    /**
     * var_export(array_keys([null => 1], null), true) — arg #0 must use nested FUNCCALL_EXEC_RETURN, not INIT_ARRAY (#16107).
     *
     * @param list<OpCode> $outerArgSends
     * @param list<OpCode> $nestedProducerOps
     */
    private function rewireVarExportNestedInlineCallArgSendSlots(
        array &$outerArgSends,
        array $nestedProducerOps,
        Block $block,
        ?Op $cfgCallOp,
        ?string $calleeName = null
    ): void {
        $callee = strtolower($calleeName ?? $this->resolveCfgFuncCallName($cfgCallOp) ?? '');
        if ('var_export' !== $callee || null === $cfgCallOp) {
            return;
        }
        $callArg = $cfgCallOp->args[0] ?? null;
        if (
            !$callArg instanceof Operand
            || !$this->callArgIsDeadInlineTemporary($callArg)
            || $this->inlineArrayProducerImmediatelyBeforeCfgCall($cfgCallOp, $block) instanceof Op\Expr\Array_
        ) {
            return;
        }
        if ($this->callArgIsNullLiteral($callArg, $cfgCallOp, 0, $block)) {
            return;
        }
        $pendingDimFetchSlot = $this->lastPendingCallArgArrayDimFetchSlot(
            $block,
            array_merge($nestedProducerOps, $outerArgSends)
        );
        if (null !== $pendingDimFetchSlot) {
            // var_export(empty($a['x']['y'])) / isset(...) — quiet dim-fetch prelude must not steal arg #0 (#21991).
            if (null !== $block->orig) {
                $issetEmptyProducer = $this->findHoistedIssetOrEmptyProducerForCallArg($block, $cfgCallOp, 0);
                if (null !== $issetEmptyProducer) {
                    return;
                }
                // var_export($u[0] === $u[1]) — Identical feeds arg #0, not trailing ArrayDimFetch rhs (#12082).
                $comparisonProducer = $this->matchBooleanBinaryOpInlineCallArgProducer(
                    $this->precedingInlineCallArgProducersBeforeCfgOp(
                        $block->orig->children,
                        $cfgCallOp
                    ),
                    $callArg
                );
                if (null !== $comparisonProducer) {
                    return;
                }
                // var_export((string)$xml['a']) — Cast feeds arg #0; dim-fetch is the Cast operand (#25339).
                // Skip trailing true/false return-flag ConstFetch so two-arg form still sees the Cast.
                $callIndex = array_search($cfgCallOp, $block->orig->children, true);
                if (\is_int($callIndex) && $callIndex > 0) {
                    $probeIndex = $callIndex - 1;
                    while ($probeIndex >= 0) {
                        $probe = $block->orig->children[$probeIndex] ?? null;
                        if ($probe instanceof Op\Expr\ConstFetch) {
                            $flagName = strtolower($this->staticNameFromOperand($probe->name) ?? '');
                            if (\in_array($flagName, ['true', 'false'], true)) {
                                --$probeIndex;
                                continue;
                            }
                        }
                        break;
                    }
                    $castPrelude = $block->orig->children[$probeIndex] ?? null;
                    if ($castPrelude instanceof Op\Expr\Cast) {
                        return;
                    }
                }
            }
            $trueSlot = null;
            foreach (array_reverse(array_merge($block->opCodes, $nestedProducerOps, $outerArgSends)) as $op) {
                if (OpCode::TYPE_FUNCCALL_INIT === $op->type) {
                    break;
                }
                if (OpCode::TYPE_CONST_FETCH !== $op->type || null === $op->arg2) {
                    continue;
                }
                $name = $this->resolveCompileTimeStringSlot((int) $op->arg2, $block);
                if ('true' === strtolower($name ?? '')) {
                    $trueSlot = $op->arg1;
                    break;
                }
            }
            $sendOrdinal = 0;
            foreach ($outerArgSends as &$send) {
                if (OpCode::TYPE_ARG_SEND !== $send->type) {
                    continue;
                }
                if (0 === $sendOrdinal) {
                    $send->arg1 = (string) $pendingDimFetchSlot;
                } elseif (1 === $sendOrdinal && null !== $trueSlot) {
                    $send->arg1 = (string) $trueSlot;
                }
                ++$sendOrdinal;
            }
            unset($send);

            return;
        }
        if ($this->isCallArgDirectArrayDimFetch($callArg)) {
            $dimSlot = $this->lastPendingCallArgArrayDimFetchSlot($block, $nestedProducerOps);
            if (null !== $dimSlot) {
                $sendOrdinal = 0;
                foreach ($outerArgSends as &$send) {
                    if (OpCode::TYPE_ARG_SEND !== $send->type) {
                        continue;
                    }
                    if (0 === $sendOrdinal) {
                        $send->arg1 = (string) $dimSlot;
                    }
                    ++$sendOrdinal;
                }
                unset($send);
            }

            return;
        }
        if (null !== $block->orig) {
            $callIndex = array_search($cfgCallOp, $block->orig->children, true);
            if (\is_int($callIndex) && $callIndex > 0) {
                $stmtBefore = $block->orig->children[$callIndex - 1] ?? null;
                $hoistedNullFeedsSoleArg = $stmtBefore instanceof Op\Expr\ConstFetch
                    && $this->constFetchIsNull($stmtBefore)
                    && \is_array($cfgCallOp->args ?? null)
                    && 1 === \count($cfgCallOp->args)
                    && $this->callArgIsDeadInlineTemporary($cfgCallOp->args[0] ?? null);
                if (
                    ($stmtBefore instanceof Op\Expr\ConstFetch || $stmtBefore instanceof Op\Expr\ClassConstFetch)
                    && (
                        null === $this->nonConstInlineProducerBeforeTrailingScalarConstFetchPreludes(
                            $callIndex,
                            $block->orig->children
                        )
                        || $hoistedNullFeedsSoleArg
                    )
                ) {
                    // var_export($expr, true|false) — hoisted return flag is not arg #0 (#17895, #17251).
                    $skipConstEarlyReturn = false;
                    if (
                        \is_array($cfgCallOp->args ?? null)
                        && \count($cfgCallOp->args) >= 2
                        && $stmtBefore instanceof Op\Expr\ConstFetch
                    ) {
                        $name = $this->staticNameFromOperand($stmtBefore->name);
                        if (\in_array(strtolower($name ?? ''), ['true', 'false'], true)) {
                            $skipConstEarlyReturn = true;
                        }
                    }
                    if (!$skipConstEarlyReturn) {
                        $constSlot = $block->slotForOperand($stmtBefore->result);
                        if (null === $constSlot) {
                            foreach (array_reverse(array_merge($block->opCodes, $nestedProducerOps)) as $op) {
                                if (OpCode::TYPE_CONST_FETCH !== $op->type || null === $op->arg1) {
                                    continue;
                                }
                                $constSlot = $op->arg1;
                                break;
                            }
                        }
                        if (null !== $constSlot) {
                            foreach ($outerArgSends as &$send) {
                                if (OpCode::TYPE_ARG_SEND !== $send->type) {
                                    continue;
                                }
                                $send->arg1 = (string) $constSlot;
                                break;
                            }
                            unset($send);

                            return;
                        }
                    }
                }
            }
        }
        $execSlot = null;
        if (null !== $block->orig) {
            $callIndex = array_search($cfgCallOp, $block->orig->children, true);
            if (\is_int($callIndex) && $callIndex > 0) {
                $probeIndex = $callIndex - 1;
                while ($probeIndex >= 0) {
                    $probe = $block->orig->children[$probeIndex] ?? null;
                    if ($probe instanceof Op\Expr\ConstFetch || $probe instanceof Op\Expr\ClassConstFetch) {
                        --$probeIndex;
                        continue;
                    }
                    break;
                }
                $producer = $block->orig->children[$probeIndex] ?? null;
                // var_export($named === $pos) — comparison feeds arg #0, not prior fgets EXEC_RETURN (#11052, #17277).
                if ($this->isComparisonInlineCallArgProducer($producer)) {
                    return;
                }
                // var_export(isset($obj->p), true) / empty(...) — bool from TYPE_ISSET/EMPTY, not stale EXEC_RETURN (#17555).
                if ($producer instanceof Op\Expr\Isset_ || $producer instanceof Op\Expr\Empty_) {
                    return;
                }
                // var_export(require_once $f, true) — Include_/Eval_ result, not prior getmypid EXEC_RETURN (#25852).
                if ($producer instanceof Op\Expr\Include_ || $producer instanceof Op\Expr\Eval_) {
                    return;
                }
                // var_export($text->data) / var_export(JSON_HEX_TAG | JSON_HEX_AMP) — expression prelude feeds arg #0, not stale FuncCall EXEC_RETURN (#17540, #17562).
                $producerExpr = $producer instanceof Op\Expr\Assign ? $producer->expr : $producer;
                if ($this->isImmediateVarExportExpressionPrelude($producerExpr)) {
                    return;
                }
                // var_export("{$c}") / var_export("a{$c}b") — ConcatList already lowered via
                // tryResolveEncapsedConcatListCallArgSlot; do not steal prior New_ EXEC_RETURN (#26489 / #13466).
                // Keep this check out of isImmediateVarExportExpressionPrelude: that helper's other
                // callers compileExpr() the prelude, and ConcatList is not an Expr compile path.
                if (
                    $producerExpr instanceof Op\Expr\ConcatList
                    || $producerExpr instanceof Op\Expr\BinaryOp\Concat
                ) {
                    return;
                }
                if ($producer instanceof Op\Expr\MethodCall || $producer instanceof Op\Expr\StaticCall) {
                    if (null === $block->slotForOperand($producer->result)) {
                        $prevForce = $this->forceDeferredSiblingCallReturnSlot;
                        $this->forceDeferredSiblingCallReturnSlot = true;
                        try {
                            foreach ($this->compileExpr($producer, $block) as $op) {
                                $block->addOpCode($op);
                            }
                        } finally {
                            $this->forceDeferredSiblingCallReturnSlot = $prevForce;
                        }
                    }
                    $pairedExec = $this->slotForMethodOrStaticCallInitFollowingExecReturn(
                        $block,
                        $producer,
                        $nestedProducerOps
                    );
                    if (null !== $pairedExec) {
                        $execSlot = $pairedExec;
                    } else {
                        $operandSlot = $block->slotForOperand($producer->result);
                        if (null !== $operandSlot) {
                            $execSlot = (string) $operandSlot;
                        } else {
                            $execSlot = $this->slotForSiblingMethodCallProducerExecReturn(
                                $block,
                                $producer,
                                $cfgCallOp,
                                $block->orig->children
                            );
                        }
                    }
                } elseif ($producer instanceof Op\Expr\ArrayDimFetch) {
                    $producers = $this->precedingInlineCallArgProducersBeforeCfgOp(
                        $block->orig->children,
                        $cfgCallOp
                    );
                    $chainedDimFetch = $this->matchChainedArrayDimFetchInlineCallArgProducer($producers, 0);
                    if ($chainedDimFetch instanceof Op\Expr\ArrayDimFetch && null !== $chainedDimFetch->result) {
                        $dimSlot = $block->slotForOperand($chainedDimFetch->result);
                        if (null === $dimSlot) {
                            $dimFetches = array_values(array_filter(
                                $producers,
                                static fn (Op\Expr $p): bool => $p instanceof Op\Expr\ArrayDimFetch
                            ));
                            if (
                                \count($dimFetches) >= 2
                                && $this->arrayDimFetchesFormProducerChain($dimFetches)
                            ) {
                                $dimSlot = $this->pendingCallArgArrayDimFetchSlot(
                                    $block,
                                    array_merge($block->opCodes, $nestedProducerOps),
                                    \count($dimFetches) - 1
                                );
                            }
                        }
                        if (null !== $dimSlot) {
                            $execSlot = (string) $dimSlot;
                        }
                    }
                } elseif ($producer instanceof Op\Expr\FuncCall || $producer instanceof Op\Expr\NsFuncCall) {
                    $operandSlot = $block->slotForOperand($producer->result);
                    if (null !== $operandSlot) {
                        $execSlot = (string) $operandSlot;
                    } else {
                        $execSlot = $this->slotForInlineFuncCallProducerExecReturnByCfgIndex(
                            $block,
                            $probeIndex,
                            $block->orig->children
                        );
                    }
                }
            }
        }
        if (null === $execSlot) {
            $execSlot = $this->slotForLastPendingInlineCallResultBeforeFuncCallInit($nestedProducerOps);
        }
        if (null === $execSlot) {
            $execSlot = $this->slotForLastEmittedInlineCallResultBeforePendingFuncCall($block);
        }
        if (null === $execSlot) {
            return;
        }
        $initSlots = [];
        foreach (array_merge($block->opCodes, $nestedProducerOps) as $op) {
            if (OpCode::TYPE_INIT_ARRAY === $op->type && null !== $op->arg1) {
                $initSlots[] = $op->arg1;
            }
        }
        $trueSlot = null;
        foreach (array_reverse(array_merge($block->opCodes, $nestedProducerOps)) as $op) {
            if (OpCode::TYPE_FUNCCALL_INIT === $op->type) {
                break;
            }
            if (OpCode::TYPE_CONST_FETCH !== $op->type || null === $op->arg2) {
                continue;
            }
            $name = $this->resolveCompileTimeStringSlot((int) $op->arg2, $block);
            if ('true' === strtolower($name ?? '')) {
                $trueSlot = $op->arg1;
                break;
            }
        }
        if (null === $trueSlot) {
            $trueSlot = $this->slotForVarExportHoistedReturnTruePrelude($block, $cfgCallOp);
        }
        $sendOrdinal = 0;
        foreach ($outerArgSends as &$send) {
            if (OpCode::TYPE_ARG_SEND !== $send->type) {
                continue;
            }
            if (0 === $sendOrdinal) {
                $hoistedScalarArgSlot = $this->slotForVarExportHoistedScalarConstArgZero($block, $cfgCallOp);
                if (null !== $hoistedScalarArgSlot) {
                    // var_export(INF, true) twice — arg #0 is hoisted INF/NAN, not prior var_export EXEC_RETURN (#18426).
                    $send->arg1 = $hoistedScalarArgSlot;
                } elseif ([] !== $initSlots && \in_array($send->arg1, $initSlots, true)) {
                    $send->arg1 = $execSlot;
                } elseif (null !== $trueSlot && (string) $send->arg1 === (string) $trueSlot) {
                    // var_export($it->current(), true) / var_export(f(), true) — arg #0 is producer EXEC_RETURN (#17251).
                    $send->arg1 = $execSlot;
                } elseif (
                    null === $hoistedScalarArgSlot
                    && $callArg instanceof Operand
                    && $this->callArgIsDeadInlineTemporary($callArg)
                    && (string) $send->arg1 !== (string) $execSlot
                ) {
                    // var_export($g->valid(), true) after prior var_export — dead arg temp must not reuse stale EXEC_RETURN (#17520).
                    $send->arg1 = $execSlot;
                } elseif (null === $hoistedScalarArgSlot && (string) $send->arg1 !== (string) $execSlot) {
                    // var_export($g2->current(), true) after earlier var_export — sibling MethodCall EXEC_RETURN (#18183).
                    $send->arg1 = $execSlot;
                }
            } elseif (1 === $sendOrdinal && null !== $trueSlot && (string) $send->arg1 === (string) $execSlot) {
                $send->arg1 = $trueSlot;
            }
            ++$sendOrdinal;
        }
        unset($send);
    }

    /**
     * file_put_contents($f, 'a', FILE_APPEND | LOCK_EX) — trailing dead-temp arg must use BitwiseOr dest (#18523).
     *
     * @param list<OpCode> $outerArgSends
     * @param list<OpCode> $nestedProducerOps
     */
    private function rewireInlineBitmaskTrailingCallArgSendSlots(
        array &$outerArgSends,
        array $nestedProducerOps,
        Block $block,
        ?Op $cfgCallOp
    ): void {
        if (null === $cfgCallOp || null === $block->orig || !\is_array($cfgCallOp->args ?? null)) {
            return;
        }
        $callIndex = $this->cfgCallOpIndex($block, $cfgCallOp);
        if (!\is_int($callIndex) || $callIndex < 1) {
            return;
        }
        $immediate = $block->orig->children[$callIndex - 1] ?? null;
        if ($immediate instanceof Op\Expr\Assign) {
            $hoistedRhs = $callIndex > 1 ? ($block->orig->children[$callIndex - 2] ?? null) : null;
            if (
                $hoistedRhs instanceof Op\Expr\BinaryOp\BitwiseOr
                || $hoistedRhs instanceof Op\Expr\BinaryOp\BitwiseAnd
                || $hoistedRhs instanceof Op\Expr\BinaryOp\BitwiseXor
            ) {
                $immediate = $hoistedRhs;
            } else {
                $immediate = $immediate->expr;
            }
        }
        if (
            !$immediate instanceof Op\Expr\BinaryOp\BitwiseOr
            && !$immediate instanceof Op\Expr\BinaryOp\BitwiseAnd
            && !$immediate instanceof Op\Expr\BinaryOp\BitwiseXor
        ) {
            return;
        }
        $nonEmbeddedArgIndices = [];
        foreach ($cfgCallOp->args as $i => $candidateArg) {
            if (null !== $candidateArg && !$this->isEmbeddedCallLiteralArg($candidateArg)) {
                $nonEmbeddedArgIndices[] = (int) $i;
            }
        }
        $trailingArgIndex = $nonEmbeddedArgIndices[\count($nonEmbeddedArgIndices) - 1] ?? null;
        if (null === $trailingArgIndex) {
            return;
        }
        $trailingArg = $cfgCallOp->args[$trailingArgIndex] ?? null;
        $assignInCallBitmask = ($block->orig->children[$callIndex - 1] ?? null) instanceof Op\Expr\Assign;
        if (
            !$assignInCallBitmask
            && (
                !$this->callArgIsDeadInlineTemporary($trailingArg)
                || $this->callArgOperandExpectsArrayProducer($trailingArg)
            )
        ) {
            return;
        }
        if ($assignInCallBitmask && $this->callArgOperandExpectsArrayProducer($trailingArg)) {
            return;
        }
        $bitmaskSlot = $this->slotForHoistedAssignInCallNamedDest($block, $cfgCallOp);
        if (null === $bitmaskSlot && null !== $immediate->result) {
            $bitmaskSlot = $block->slotForOperand($immediate->result);
            if (null !== $bitmaskSlot) {
                $bitmaskSlot = (string) $bitmaskSlot;
            }
        }
        if (null === $bitmaskSlot) {
            foreach (array_reverse(array_merge($nestedProducerOps, $block->opCodes, $outerArgSends)) as $op) {
                if (
                    OpCode::TYPE_BITWISE_OR === $op->type
                    || OpCode::TYPE_BITWISE_AND === $op->type
                    || OpCode::TYPE_BITWISE_XOR === $op->type
                ) {
                    if (null !== $op->arg1) {
                        $bitmaskSlot = (string) $op->arg1;
                        break;
                    }
                }
            }
        }
        if (null === $bitmaskSlot) {
            return;
        }
        if ($assignInCallBitmask) {
            for ($i = \count($outerArgSends) - 1; $i >= 0; --$i) {
                $send = $outerArgSends[$i];
                if (OpCode::TYPE_ARG_SEND !== $send->type) {
                    continue;
                }
                $send->arg1 = $bitmaskSlot;

                return;
            }

            return;
        }
        $argSendOrdinal = 0;
        foreach ($outerArgSends as $send) {
            if (OpCode::TYPE_ARG_SEND !== $send->type) {
                continue;
            }
            if ($argSendOrdinal === $trailingArgIndex) {
                $send->arg1 = $bitmaskSlot;

                return;
            }
            ++$argSendOrdinal;
        }
    }

    /**
     * is_array(file(..., FILE_* | FILE_*)) / count(file(...)) — arg #0 must use adjacent FUNCCALL_EXEC_RETURN,
     * not the hoisted bitmask OR slot (#10474).
     *
     * @param list<OpCode> $outerArgSends
     * @param list<OpCode> $nestedProducerOps
     */
    private function rewireArrayBuiltinAdjacentFuncCallArgSendSlots(
        array &$outerArgSends,
        array $nestedProducerOps,
        Block $block,
        ?Op $cfgCallOp,
        ?string $calleeName = null
    ): void {
        $callee = strtolower($calleeName ?? $this->resolveCfgFuncCallName($cfgCallOp) ?? '');
        if (!\in_array($callee, ['is_array', 'count', 'array_keys'], true) || null === $cfgCallOp || null === $block->orig) {
            return;
        }
        if (!\is_array($cfgCallOp->args ?? null) || 1 !== \count($cfgCallOp->args)) {
            return;
        }
        $callArg = $cfgCallOp->args[0] ?? null;
        if (!$callArg instanceof Operand || !$this->callArgIsDeadInlineTemporary($callArg)) {
            return;
        }
        $callIndex = array_search($cfgCallOp, $block->orig->children, true);
        if (!\is_int($callIndex) || $callIndex < 1) {
            return;
        }
        $adjacentIndex = $callIndex - 1;
        while ($adjacentIndex >= 0) {
            $skip = $block->orig->children[$adjacentIndex] ?? null;
            if ($skip instanceof Op\Expr\ConstFetch || $skip instanceof Op\Expr\ClassConstFetch) {
                --$adjacentIndex;
                continue;
            }
            if ($this->isUnaryInlineSiblingCallArgExpr($skip)) {
                --$adjacentIndex;
                continue;
            }
            break;
        }
        $adjacent = $block->orig->children[$adjacentIndex] ?? null;
        if (!(
            $adjacent instanceof Op\Expr\FuncCall
            || $adjacent instanceof Op\Expr\NsFuncCall
            || $adjacent instanceof Op\Expr\MethodCall
            || $adjacent instanceof Op\Expr\StaticCall
        )) {
            return;
        }
        $execSlot = $this->slotForSiblingInlineCallProducerExecReturnByExpr(
            $block,
            $adjacent,
            $cfgCallOp,
            $block->orig->children
        );
        if (null === $execSlot) {
            $execSlot = $this->slotForLastPendingInlineCallResultBeforeFuncCallInit($nestedProducerOps)
                ?? $this->slotForLastEmittedInlineCallResultBeforePendingFuncCall($block);
        }
        if (null === $execSlot) {
            return;
        }
        foreach ($outerArgSends as &$send) {
            if (OpCode::TYPE_ARG_SEND === $send->type) {
                $send->arg1 = (string) $execSlot;
                break;
            }
        }
        unset($send);
    }

    private function isInlineCallArgProducerInitOpcode(OpCode $op): bool
    {
        return OpCode::TYPE_FUNCCALL_INIT === $op->type
            || OpCode::TYPE_STATICCALL_INIT === $op->type
            || OpCode::TYPE_METHODCALL_INIT === $op->type;
    }

    private function isInlineCallArgProducerExecOpcode(OpCode $op): bool
    {
        return OpCode::TYPE_FUNCCALL_EXEC_RETURN === $op->type
            || OpCode::TYPE_FUNCCALL_EXEC_NORETURN === $op->type;
    }

    /**
     * json_encode($s, JSON_HEX_* | …) — arg #0 is a named local; bitmask preludes must not replace value ARG_SEND (#10956).
     *
     * @param list<OpCode> $outerArgSends
     */
    private function rewireNamedLocalBeforeInlineBitmaskCallArgSendSlots(
        array &$outerArgSends,
        Block $block,
        ?Op $cfgCallOp
    ): void {
        if (null === $cfgCallOp || null === $block->orig || \count($cfgCallOp->args ?? []) < 2) {
            return;
        }
        $valueArg = $cfgCallOp->args[0] ?? null;
        if (!$valueArg instanceof Operand || $this->callArgIsDeadInlineTemporary($valueArg)) {
            return;
        }
        if (!$this->cfgCallPrecededByInlineBitmaskProducer($cfgCallOp, $block)) {
            return;
        }
        $namedSlot = $this->namedLocalCallArgSlotIfBound($valueArg, $block, $cfgCallOp, 0)
            ?? $this->slotForNamedLocalFromAssignVarOperand($valueArg, $block);
        if (null === $namedSlot) {
            $operandSlot = $block->slotForOperand($valueArg);
            if (null === $operandSlot) {
                return;
            }
            $namedSlot = (int) $operandSlot;
        }
        $wired = (string) $this->finalizeOperandSlotForAccess($block, (int) $namedSlot, true);
        $argSendOrdinal = 0;
        foreach ($outerArgSends as &$send) {
            if (OpCode::TYPE_ARG_SEND !== $send->type) {
                continue;
            }
            if (0 === $argSendOrdinal) {
                $send->arg1 = $wired;

                return;
            }
            ++$argSendOrdinal;
        }
        unset($send);
    }

    private function cfgCallPrecededByInlineBitmaskProducer(Op $cfgCallOp, Block $block): bool
    {
        $callIndex = $this->cfgCallOpIndex($block, $cfgCallOp);
        if (!\is_int($callIndex) || $callIndex < 1) {
            return false;
        }
        $immediate = $block->orig->children[$callIndex - 1] ?? null;
        if ($immediate instanceof Op\Expr\Assign) {
            $hoistedRhs = $callIndex > 1 ? ($block->orig->children[$callIndex - 2] ?? null) : null;
            if (
                $hoistedRhs instanceof Op\Expr\BinaryOp\BitwiseOr
                || $hoistedRhs instanceof Op\Expr\BinaryOp\BitwiseAnd
                || $hoistedRhs instanceof Op\Expr\BinaryOp\BitwiseXor
            ) {
                $immediate = $hoistedRhs;
            } else {
                $immediate = $immediate->expr;
            }
        }

        return $immediate instanceof Op\Expr\BinaryOp\BitwiseOr
            || $immediate instanceof Op\Expr\BinaryOp\BitwiseAnd
            || $immediate instanceof Op\Expr\BinaryOp\BitwiseXor;
    }

    /**
     * is_array(file(...)) / count(file(...)) — ARG_SEND must use nested file() EXEC_RETURN, not bitmask OR (#10474).
     *
     * @param list<OpCode> $outerArgSends
     * @param list<OpCode> $nestedProducerOps
     */
    private function rewireIsArrayNestedFileCallArgSendSlots(
        array &$outerArgSends,
        array $nestedProducerOps,
        Block $block,
        ?Op $cfgCallOp,
        ?string $calleeName = null
    ): void {
        $callee = strtolower($calleeName ?? $this->resolveCfgFuncCallName($cfgCallOp) ?? '');
        if (!\in_array($callee, ['is_array', 'count'], true) || null === $cfgCallOp || null === $block->orig) {
            return;
        }
        $callArg = $cfgCallOp->args[0] ?? null;
        if (!$callArg instanceof Operand || !$this->callArgIsDeadInlineTemporary($callArg)) {
            return;
        }
        $callIndex = $this->cfgCallOpIndex($block, $cfgCallOp);
        if (!\is_int($callIndex) || $callIndex < 1) {
            return;
        }
        $immediate = $block->orig->children[$callIndex - 1] ?? null;
        if (!$immediate instanceof Op\Expr\FuncCall && !$immediate instanceof Op\Expr\NsFuncCall) {
            return;
        }
        if ('file' !== strtolower($this->resolveCfgFuncCallName($immediate) ?? '')) {
            return;
        }
        $execSlot = $this->slotForLastInlineFuncCallExecReturn($block, $nestedProducerOps);
        if (null === $execSlot) {
            return;
        }
        foreach ($outerArgSends as &$send) {
            if (OpCode::TYPE_ARG_SEND !== $send->type) {
                continue;
            }
            if ((string) $send->arg1 !== (string) $execSlot) {
                $send->arg1 = $execSlot;
            }
            break;
        }
        unset($send);
    }

    /**
     * var_export($expr !== false, true) — arg #0 is compare result, arg #1 is return flag only (#17250, #17277).
     *
     * @param list<OpCode> $outerArgSends
     * @param list<OpCode> $nestedProducerOps
     */
    private function rewireVarExportComparisonReturnFlagCallArgSendSlots(
        array &$outerArgSends,
        array $nestedProducerOps,
        Block $block,
        ?Op $cfgCallOp,
        ?string $calleeName = null
    ): void {
        if ('var_export' !== strtolower($calleeName ?? $this->resolveCfgFuncCallName($cfgCallOp) ?? '')) {
            return;
        }
        if (
            null === $cfgCallOp
            || null === $block->orig
            || !\is_array($cfgCallOp->args ?? null)
            || \count($cfgCallOp->args) < 2
        ) {
            return;
        }
        $callIndex = $this->cfgCallOpIndex($block, $cfgCallOp);
        if (!\is_int($callIndex) || $callIndex < 2) {
            return;
        }
        $returnFlagExpr = $block->orig->children[$callIndex - 1] ?? null;
        if (!$this->isHoistedScalarConstFetchImmediatelyBeforeCall($returnFlagExpr)) {
            return;
        }
        $comparisonExpr = $block->orig->children[$callIndex - 2] ?? null;
        if (
            !$this->isComparisonInlineCallArgProducer($comparisonExpr)
            || !$comparisonExpr instanceof Op\Expr
            || null === $comparisonExpr->result
            || !$returnFlagExpr instanceof Op\Expr\ConstFetch
            || null === $returnFlagExpr->result
        ) {
            return;
        }
        $comparisonSlot = $this->slotForInlineExprResultInProducerOps(
            $comparisonExpr,
            $block,
            $nestedProducerOps
        );
        $returnSlot = $this->slotForInlineExprResultInProducerOps(
            $returnFlagExpr,
            $block,
            $nestedProducerOps
        );
        if (null === $comparisonSlot || null === $returnSlot) {
            return;
        }
        $sendOrdinal = 0;
        foreach ($outerArgSends as &$send) {
            if (OpCode::TYPE_ARG_SEND !== $send->type) {
                continue;
            }
            $send->arg1 = 0 === $sendOrdinal ? $comparisonSlot : $returnSlot;
            ++$sendOrdinal;
            if ($sendOrdinal >= 2) {
                break;
            }
        }
        unset($send);
    }

    /**
     * @param list<OpCode> $producerOps
     */
    private function slotForInlineExprResultInProducerOps(
        Op\Expr $expr,
        Block $block,
        array $producerOps
    ): ?string {
        $mapped = $block->slotForOperand($expr->result);
        if (null !== $mapped) {
            return (string) $mapped;
        }
        $leftSlot = null;
        $rightSlot = null;
        if ($expr instanceof Op\Expr\BinaryOp) {
            $leftSlot = null !== $expr->left ? $block->slotForOperand($expr->left) : null;
            $rightSlot = null !== $expr->right ? $block->slotForOperand($expr->right) : null;
        }
        foreach ($producerOps as $op) {
            if ($expr instanceof Op\Expr\ConstFetch && OpCode::TYPE_CONST_FETCH === $op->type) {
                if ((string) $op->arg1 === (string) $block->slotForOperand($expr->result)) {
                    return (string) $op->arg1;
                }
            }
            if ($this->isComparisonInlineCallArgProducer($expr)) {
                $compareTypes = [
                    OpCode::TYPE_IDENTICAL,
                    OpCode::TYPE_NOT_IDENTICAL,
                    OpCode::TYPE_EQUAL,
                    OpCode::TYPE_NOT_EQUAL,
                    OpCode::TYPE_SPACESHIP,
                    OpCode::TYPE_SMALLER,
                    OpCode::TYPE_GREATER,
                    OpCode::TYPE_SMALLER_OR_EQUAL,
                    OpCode::TYPE_GREATER_OR_EQUAL,
                ];
                if (!\in_array($op->type, $compareTypes, true)) {
                    continue;
                }
                if (null !== $leftSlot && (string) $op->arg2 !== (string) $leftSlot) {
                    continue;
                }
                if (null !== $rightSlot && (string) $op->arg3 !== (string) $rightSlot) {
                    continue;
                }

                return (string) $op->arg1;
            }
        }

        return null;
    }

    protected function compileFuncCall(
        ?int $name,
        array $args,
        Operand $result,
        Block $block,
        int $startLine = 0,
        ?Op $cfgCallOp = null
    ): array
    {
        $folded = $this->tryCompileDefineAsGlobalConst($name, $args, $result, $block);
        if (null !== $folded) {
            return $folded;
        }

        $isDynamicCallee = null !== $cfgCallOp
            && ($cfgCallOp instanceof Op\Expr\FuncCall || $cfgCallOp instanceof Op\Expr\NsFuncCall)
            && $this->funcCallExprUsesVariableCallee($cfgCallOp);

        // Do not fold ForbiddenWhenDynamic names — keep the dynamic flag observable (#23591).
        $foldedName = $this->tryFoldVariableFunctionName($name, $block);
        if (
            null !== $foldedName
            && $isDynamicCallee
            && null !== ($foldedStr = $this->resolveCompileTimeStringSlot($foldedName, $block))
            && VariableFunctionCall::isForbiddenWhenDynamic($foldedStr)
        ) {
            $foldedName = null;
        }
        $callName = $foldedName ?? $name;
        $calleeName = $this->resolveCompileTimeStringSlot($callName, $block)
            ?? ($name !== null ? $this->resolveCompileTimeStringSlot($name, $block) : null);

        $this->lowerEmbeddedCoalesceCallArgs($args, $block);

        $init = new OpCode(
            OpCode::TYPE_FUNCCALL_INIT,
            $callName,
            $startLine > 0 ? $startLine : null
        );
        $init->funcCallDynamic = $isDynamicCallee;
        if (null !== $cfgCallOp) {
            $this->assignSourceMetadata($init, $cfgCallOp);
        }

        $skipPrependForHaystackFamilyDimFetch = false;
        if (null !== $cfgCallOp && \is_array($cfgCallOp->args ?? null)) {
            foreach ($cfgCallOp->args as $argIndex => $callArg) {
                if (!$callArg instanceof Operand) {
                    continue;
                }
                if ($this->callArgIsDeadInlineHaystackFamilySlot(
                    $cfgCallOp,
                    (int) $argIndex,
                    $calleeName,
                    $callArg
                )) {
                    $skipPrependForHaystackFamilyDimFetch = true;
                    break;
                }
            }
        }

        // var_export(fdiv(...), true) — sibling FuncCall producer must INIT/EXEC before consumer (#5471, #4633).
        // Scope to var_export only — broad skip breaks in_array dim-fetch haystack in echo ternary chains (re-#17000, #17851).
        $skipPrependForSiblingFuncProducer = false;
        if (
            null !== $cfgCallOp
            && null !== $block->orig
            && 'var_export' === strtolower($this->resolveCfgFuncCallName($cfgCallOp) ?? '')
        ) {
            $consumerCfgIndex = array_search($cfgCallOp, $block->orig->children, true);
            if (\is_int($consumerCfgIndex)) {
                $skipPrependForSiblingFuncProducer = null !== $this->firstSiblingInlineFuncCallProducerIndex(
                    $consumerCfgIndex,
                    $block->orig->children
                );
            }
        }
        $initPrependedBeforeArgConstFetch = false;
        $skipPrependForExplodeLeadingConstFunc = null !== $cfgCallOp
            && 'explode' === strtolower($this->resolveCfgFuncCallName($cfgCallOp) ?? '')
            && null !== $this->leadingConstFetchFuncCallPreludeBeforeCfgCall($cfgCallOp, $block);
        // date_sunrise()/date_sunset() hoisted strtotime + SUNFUNCS_RET_* ConstFetch — producer INIT must run first (#17937).
        $skipPrependForDateSunFunc = null !== $cfgCallOp
            && \in_array(
                strtolower($this->resolveCfgFuncCallName($cfgCallOp) ?? ''),
                ['date_sunrise', 'date_sunset', 'date_sun_info'],
                true
            );
        if (
            !$skipPrependForSiblingFuncProducer
            && !$skipPrependForHaystackFamilyDimFetch
            && !$skipPrependForExplodeLeadingConstFunc
            && !$skipPrependForDateSunFunc
        ) {
            $initPrependedBeforeArgConstFetch = $this->prependFuncCallInitBeforeTrailingArgConstFetches(
                $block,
                $init
            );
        }

        $argSends = $this->compileCallArgSends($args, $block, $calleeName, $cfgCallOp);
        $argSends = $this->rewriteCallArgSendsForArraySpreadResult($argSends, $block, $cfgCallOp);
        // Hoisted call-arg ConstFetch lands on $block during compileCallArgSends — prepend INIT now (#17697).
        if (
            !$initPrependedBeforeArgConstFetch
            && !$skipPrependForSiblingFuncProducer
            && !$skipPrependForHaystackFamilyDimFetch
            && !$skipPrependForExplodeLeadingConstFunc
            && !$skipPrependForDateSunFunc
        ) {
            $initPrependedBeforeArgConstFetch = $this->prependFuncCallInitBeforeTrailingArgConstFetches(
                $block,
                $init
            );
        }
        [$nestedProducerOps, $outerArgSends] = $this->partitionNestedInlineCallArgProducerOps($argSends);
        $this->rewireArrayBuiltinAdjacentFuncCallArgSendSlots(
            $outerArgSends,
            $nestedProducerOps,
            $block,
            $cfgCallOp,
            $calleeName
        );
        $this->rewireInlineArithmeticBranchCallArgSendSlots($outerArgSends, $nestedProducerOps, $block, $cfgCallOp);
        $this->rewireSiblingMultiArgInlineCallArgSendSlots($outerArgSends, $block, $cfgCallOp, $nestedProducerOps);
        $this->rewireNestedMethodCallHoistedClassConstOuterCallArgSendSlots(
            $outerArgSends,
            $block,
            $cfgCallOp,
            $nestedProducerOps
        );
        $this->rewireHoistedClassConstPreludeCallArgSendSlots($outerArgSends, $block, $cfgCallOp, $nestedProducerOps);
        $this->rewireRegisterShutdownFunctionClosureEnumCallArgSendSlots(
            $outerArgSends,
            $block,
            $cfgCallOp,
            $nestedProducerOps
        );
        $this->rewireSubstrNestedSprintfArgSendSlots($outerArgSends, $block, $cfgCallOp, $calleeName);
        $this->rewireArrayKeysInlineInitArrayArgSendSlots(
            $outerArgSends,
            $block,
            $cfgCallOp,
            $calleeName,
            array_merge($nestedProducerOps, $outerArgSends)
        );
        $this->rewireArrayCombineInlineArgSendSlots($outerArgSends, $block, $argSends, $calleeName, $cfgCallOp);
        $this->rewirePregReplaceCallbackArrayPatternMapArgSendSlots($outerArgSends, $block, $cfgCallOp, $argSends);
        $this->rewireVarExportNestedInlineCallArgSendSlots($outerArgSends, $nestedProducerOps, $block, $cfgCallOp, $calleeName);
        $this->rewireVarExportComparisonReturnFlagCallArgSendSlots(
            $outerArgSends,
            $nestedProducerOps,
            $block,
            $cfgCallOp,
            $calleeName
        );
        $this->rewireIsArrayNestedFileCallArgSendSlots($outerArgSends, $nestedProducerOps, $block, $cfgCallOp, $calleeName);
        $this->rewireInlineBitmaskTrailingCallArgSendSlots($outerArgSends, $nestedProducerOps, $block, $cfgCallOp);
        $this->rewireNamedLocalBeforeInlineBitmaskCallArgSendSlots($outerArgSends, $block, $cfgCallOp);
        $return = [];
        foreach ($outerArgSends as $send) {
            if (OpCode::TYPE_ASSIGN === $send->type) {
                $return[] = $send;
            }
        }
        foreach ($nestedProducerOps as $op) {
            $return[] = $op;
        }
        // php-src resolves callee before evaluating call args (#17697); hoisted nested FuncCall
        // producers (ensureDeferredSiblingInlineCallArgProducersCompiled) must run first (#17708).
        if (!$initPrependedBeforeArgConstFetch) {
            $return[] = $init;
        }
        foreach ($outerArgSends as $send) {
            if (OpCode::TYPE_ASSIGN !== $send->type) {
                $return[] = $send;
            }
        }
        $return[] = $this->compileFuncCallExecOpcode($result, $block, $startLine, $cfgCallOp);
        return $return;
    }

    /**
     * Fold $fn = 'name'; $fn(...) to a literal callee when the name is a compile-time string (#56).
     *
     * Follows TYPE_ASSIGN chains so first-class callables (`strlen(...)`, `C::m(...)`, #1363) fold too.
     */
    protected function tryFoldVariableFunctionName(?int $nameSlot, Block $block): ?int
    {
        if (null === $nameSlot) {
            return null;
        }
        $name = $this->resolveCompileTimeStringSlot($nameSlot, $block);
        if (null === $name) {
            return null;
        }
        $lit = new Literal($name);
        $lit->type = Type::string();

        return $this->compileOperand($lit, $block, true);
    }

    /**
     * Resolve a scope slot to a compile-time string via constants or assign chains (#1363).
     */
    protected function resolveCompileTimeStringSlot(int $slot, Block $block, array &$visited = []): ?string
    {
        if (isset($visited[$slot])) {
            return null;
        }
        $visited[$slot] = true;
        if (isset($block->constants[$slot])) {
            $const = $block->constants[$slot];
            if (Variable::TYPE_STRING !== $const->type) {
                return null;
            }

            return $const->toString();
        }
        foreach ($block->opCodes as $op) {
            if (OpCode::TYPE_ASSIGN !== $op->type || $op->arg2 !== $slot) {
                continue;
            }
            $resolved = $this->resolveCompileTimeStringSlot((int) $op->arg3, $block, $visited);
            if (null !== $resolved) {
                return $resolved;
            }
        }

        foreach ($block->parents as $parent) {
            if (!$parent instanceof Block) {
                continue;
            }
            $resolved = $this->resolveCompileTimeStringSlot($slot, $parent, $visited);
            if (null !== $resolved) {
                return $resolved;
            }
        }

        return null;
    }

    /**
     * Lower define('NAME', literal) to compile-time global constant registration (issue #204).
     *
     * @return list<OpCode>|null
     */
    protected function tryCompileDefineAsGlobalConst(
        ?int $name,
        array $args,
        Operand $result,
        Block $block
    ): ?array {
        if (null === $name) {
            return null;
        }
        $nameOp = $block->getOperand($name);
        if (!$nameOp instanceof Operand\Literal || 'define' !== $nameOp->value) {
            return null;
        }
        if (count($args) < 2 || count($args) > 3) {
            return null;
        }
        $constNameArg = $args[0];
        $valueArg = $args[1];
        if (!$constNameArg instanceof Operand\Literal || !$valueArg instanceof Operand\Literal) {
            return null;
        }
        if (Variable::TYPE_STRING !== Variable::mapFromType($constNameArg->type)) {
            return null;
        }
        $caseInsensitiveSlot = null;
        if (3 === count($args)) {
            $caseInsensitiveArg = $args[2];
            if (!$caseInsensitiveArg instanceof Operand\Literal) {
                return null;
            }
            if (Variable::TYPE_BOOLEAN !== Variable::mapFromType($caseInsensitiveArg->type)) {
                return null;
            }
            $caseInsensitiveSlot = $this->compileOperand($caseInsensitiveArg, $block, true);
            if (!isset($block->constants[$caseInsensitiveSlot])) {
                return null;
            }
        }
        $constNameSlot = $this->compileOperand($constNameArg, $block, true);
        $valueSlot = $this->compileOperand($valueArg, $block, true);
        if (!isset($block->constants[$constNameSlot], $block->constants[$valueSlot])) {
            return null;
        }
        $constName = $block->constants[$constNameSlot]->toString();
        if ('' === $constName || str_contains($constName, '::')) {
            return null;
        }
        $this->storeCompileTimeGlobalConst($constName, $block->constants[$valueSlot]);
        $ops = [new OpCode(
            OpCode::TYPE_DECLARE_GLOBAL_CONST,
            $constNameSlot,
            $valueSlot,
            $caseInsensitiveSlot
        )];
        if (!empty($result->usages)) {
            $trueVar = new Variable(Variable::TYPE_BOOLEAN);
            $trueVar->bool(true);
            $trueOperand = new Temporary;
            $trueOperand->type = Type::bool();
            $trueSlot = $block->registerConstant($trueOperand, $trueVar);
            $ops[] = new OpCode(
                OpCode::TYPE_ASSIGN,
                $this->compileOperand($result, $block, false),
                $this->compileOperand($result, $block, false),
                $trueSlot
            );
        }

        return $ops;
    }

    /**
     * Literal includes read caller locals by name; php-cfg may mark those assigns dead (#568).
     */
    private function markCallerLocalsUsedByLiteralInclude(string $path, Block $block): void
    {
        if (!is_file($path)) {
            return;
        }
        $code = file_get_contents($path);
        if (false === $code || '' === $code) {
            return;
        }
        foreach ($block->scopedOperands() as $operand) {
            $name = OperandName::resolve($operand);
            if (null === $name || Superglobals::isSuperglobalName($name)) {
                continue;
            }
            if (!preg_match('/\\$'.preg_quote($name, '/').'\\b/', $code)) {
                continue;
            }
            if ($operand instanceof Temporary && [] === $operand->usages) {
                $operand->usages[] = $operand;
            }
        }
    }

    /**
     * True when a Plus/Minus(read, 1) + Assign(write) pair is lowered ++/-- (#3469).
     *
     * php-cfg uses dedicated PostInc/PreInc/PostDec/PreDec ops (#3552), not Plus+Assign.
     * AssignOp ($x += 1 / $x -= 1) shares the Plus(var,1)+Assign shape and must not set
     * {@see OpCode::$isIncDec} — bool compound assign promotes to int, ++/-- does not (#7340).
     */
    private function isIncDecBinaryOp(Op\Expr\BinaryOp $expr): bool
    {
        return false;
    }

    private function operandsSameBaseVariable(?Operand $left, ?Operand $right): bool
    {
        $leftName = $this->baseVariableName($left);
        $rightName = $this->baseVariableName($right);
        if (null === $leftName || null === $rightName) {
            return false;
        }

        return $leftName === $rightName;
    }

    private function baseVariableName(?Operand $operand): ?string
    {
        while ($operand instanceof Temporary && $operand->original instanceof Operand) {
            $operand = $operand->original;
        }
        if ($operand instanceof BoundVariable && $operand->name instanceof Literal && is_string($operand->name->value)) {
            return $operand->name->value;
        }
        if ($operand instanceof CfgVariable && $operand->name instanceof Literal && is_string($operand->name->value)) {
            return $operand->name->value;
        }

        return null;
    }

    /**
     * Zend zend_compile.c: assignment to $this is a compile-time fatal (#4865).
     *
     * @return never
     */
    protected function rejectThisReassignment(?Operand $var): void
    {
        if (null === $var) {
            return;
        }
        if ('this' === $this->baseVariableName($var)) {
            $this->throwCompileError('Cannot re-assign $this');
        }
    }

    /**
     * Zend zend_compile.c: acquiring a reference to $GLOBALS is a compile-time fatal (#15627).
     *
     * @return never
     */
    protected function rejectGlobalsReferenceAcquisition(?Operand $expr): void
    {
        if (null === $expr) {
            return;
        }
        if ('GLOBALS' === $this->baseVariableName($expr)) {
            $this->throwCompileError('Cannot acquire reference to $GLOBALS');
        }
    }

    /**
     * Zend zend_compile.c: unset($this) is a compile-time fatal (#5436).
     *
     * @return never
     */
    protected function rejectThisUnset($expr): void
    {
        if (!$expr instanceof Operand) {
            return;
        }
        if ('this' === $this->unsetTargetVariableName($expr)) {
            $this->throwCompileError('Cannot unset $this');
        }
    }

    private function unsetTargetVariableName(Operand $expr): ?string
    {
        $name = $this->baseVariableName($expr);
        if (null !== $name) {
            return $name;
        }
        $var = $this->unwrapVariableOperand($expr);
        if (null !== $var && $var->name instanceof Literal && is_string($var->name->value)) {
            return $var->name->value;
        }

        return null;
    }

    /**
     * Zend zend_compile.c: nullsafe ?-> in l-value position is a compile-time fatal (#5323).
     *
     * @param Op[] $ops
     */
    private function isNullsafePropertyFetchInWriteContext(array $ops, int $index): bool
    {
        $fetch = $ops[$index] ?? null;
        if (!$fetch instanceof Op\Expr\NullsafePropertyFetch) {
            return false;
        }

        return $this->operandUsedInWriteContext($ops, $index + 1, $fetch->result);
    }

    /**
     * Zend zend_compile.c: &$nullsafeChain is a distinct compile fatal from write-context (#26638).
     *
     * php-cfg hoists NullsafePropertyFetch / NullsafeMethodCall before AssignRef; the result may
     * feed AssignRef.expr directly or via PropertyFetch / ArrayDimFetch / further nullsafe hops.
     *
     * @param Op[] $ops
     */
    private function isNullsafeOperandUsedAsAssignRefRhs(array $ops, int $startIndex, Operand $operand): bool
    {
        for ($j = $startIndex, $count = count($ops); $j < $count; ++$j) {
            $op = $ops[$j];
            if ($op instanceof Op\Expr\AssignRef && $this->operandsChainEqual($op->expr, $operand)) {
                return true;
            }
            if ($op instanceof Op\Expr\NullsafePropertyFetch
                && $this->operandsChainEqual($op->var, $operand)) {
                return $this->isNullsafeOperandUsedAsAssignRefRhs($ops, $j + 1, $op->result);
            }
            if ($op instanceof Op\Expr\PropertyFetch
                && $this->operandsChainEqual($op->var, $operand)) {
                return $this->isNullsafeOperandUsedAsAssignRefRhs($ops, $j + 1, $op->result);
            }
            if ($op instanceof Op\Expr\ArrayDimFetch
                && $this->operandsChainEqual($op->var, $operand)) {
                return $this->isNullsafeOperandUsedAsAssignRefRhs($ops, $j + 1, $op->result);
            }
        }

        return false;
    }

    /**
     * Zend zend_compile.c: Cannot take reference of a nullsafe chain (#26638).
     */
    protected function rejectNullsafeReferenceAcquisition(?Operand $expr, ?Block $block = null): void
    {
        if (null === $expr) {
            return;
        }
        if ($this->rvalueContainsNullsafeChain($expr, $block)) {
            $this->throwCompileError('Cannot take reference of a nullsafe chain');
        }
    }

    /**
     * True when AssignRef RHS resolves to a ?-> property/method (or chain thereof).
     */
    protected function rvalueContainsNullsafeChain(?Operand $operand, ?Block $block = null): bool
    {
        if (null === $operand) {
            return false;
        }
        while ($operand instanceof Temporary) {
            if ($operand->original instanceof Op\Expr\NullsafePropertyFetch
                || $operand->original instanceof Op\Expr\NullsafeMethodCall) {
                return true;
            }
            if ($operand->original instanceof Op\Expr\ArrayDimFetch) {
                return $this->rvalueContainsNullsafeChain($operand->original->var, $block);
            }
            if ($operand->original instanceof Op\Expr\PropertyFetch) {
                return $this->rvalueContainsNullsafeChain($operand->original->var, $block);
            }
            if (null === $operand->original) {
                break;
            }
            $operand = $operand->original;
        }
        if ($operand instanceof Op\Expr\NullsafePropertyFetch
            || $operand instanceof Op\Expr\NullsafeMethodCall) {
            return true;
        }
        if ($operand instanceof Op\Expr\PropertyFetch || $operand instanceof Op\Expr\ArrayDimFetch) {
            return $this->rvalueContainsNullsafeChain($operand->var, $block);
        }
        if (null !== $block && null !== $block->orig) {
            if ($this->operandIsNullsafePropertyFetchResult($operand, $block->orig->children)
                || $this->operandIsNullsafeMethodCallResult($operand, $block->orig->children)) {
                return true;
            }
            $propFetch = $this->findPropertyFetchForResult($operand, $block);
            if (null !== $propFetch) {
                return $this->rvalueContainsNullsafeChain($propFetch->var, $block);
            }
        }

        return false;
    }

    /**
     * @param Op[] $ops
     */
    private function operandIsNullsafeMethodCallResult(?Operand $operand, array $ops): bool
    {
        if (null === $operand) {
            return false;
        }
        foreach ($ops as $child) {
            if (!$child instanceof Op\Expr\NullsafeMethodCall) {
                continue;
            }
            if ($this->operandsChainEqual($child->result, $operand)) {
                return true;
            }
        }

        return false;
    }

    /**
     * @param Op[] $ops
     */
    private function operandUsedInWriteContext(array $ops, int $startIndex, Operand $operand): bool
    {
        for ($j = $startIndex, $count = count($ops); $j < $count; ++$j) {
            $op = $ops[$j];
            if ($this->isDirectWriteUseOfOperand($op, $operand)) {
                return true;
            }
            if ($op instanceof Op\Expr\NullsafePropertyFetch
                && $this->operandsChainEqual($op->var, $operand)) {
                return $this->operandUsedInWriteContext($ops, $j + 1, $op->result);
            }
            // Chained write: $a?->b->x = / ++ — PropertyFetch sits between nullsafe and assign (#25560).
            if ($op instanceof Op\Expr\PropertyFetch
                && $this->operandsChainEqual($op->var, $operand)) {
                return $this->operandUsedInWriteContext($ops, $j + 1, $op->result);
            }
            if ($op instanceof Op\Expr\ArrayDimFetch
                && $this->operandsChainEqual($op->var, $operand)) {
                return $this->operandUsedInWriteContext($ops, $j + 1, $op->result);
            }
            if ($op instanceof Op\Expr\BinaryOp\Coalesce
                && $this->operandsChainEqual($op->left, $operand)
                && $j + 1 < $count
                && $ops[$j + 1] instanceof Op\Expr\Assign
                && $this->isCoalesceAssignTail($ops[$j + 1], $op)
                && $this->operandsChainEqual($ops[$j + 1]->var, $op->left)) {
                return true;
            }
        }

        return false;
    }

    private function isDirectWriteUseOfOperand(Op $op, Operand $operand): bool
    {
        if ($op instanceof Op\Expr\Assign && $this->operandsChainEqual($op->var, $operand)) {
            return true;
        }
        if ($op instanceof Op\Expr\AssignRef && $this->operandsChainEqual($op->var, $operand)) {
            return true;
        }
        if ($op instanceof Op\Terminal\Unset_) {
            foreach ($op->exprs as $var) {
                if ($this->operandsChainEqual($var, $operand)) {
                    return true;
                }
                $target = $var;
                while ($target instanceof Temporary) {
                    if ($this->operandsChainEqual($target, $operand)) {
                        return true;
                    }
                    if (null === $target->original) {
                        break;
                    }
                    $target = $target->original;
                }
            }

            return false;
        }
        if ($op instanceof Op\Expr\PostInc
            || $op instanceof Op\Expr\PreInc
            || $op instanceof Op\Expr\PostDec
            || $op instanceof Op\Expr\PreDec) {
            $write = $op->write ?? $op->read;

            return $this->operandsChainEqual($write, $operand);
        }

        return false;
    }

    /**
     * php-cfg result temps for Expr ops do not chain `original` back to the producer (#5323).
     *
     * @param Op[] $ops
     */
    private function operandIsNullsafePropertyFetchResult(?Operand $operand, array $ops): bool
    {
        if (null === $operand) {
            return false;
        }
        foreach ($ops as $child) {
            if (!$child instanceof Op\Expr\NullsafePropertyFetch) {
                continue;
            }
            if ($this->operandsChainEqual($child->result, $operand)) {
                return true;
            }
        }

        return false;
    }

    protected function lvalueContainsNullsafePropertyFetch(?Operand $operand, ?Block $block = null): bool
    {
        if (null === $operand) {
            return false;
        }
        while ($operand instanceof Temporary) {
            if ($operand->original instanceof Op\Expr\NullsafePropertyFetch) {
                return true;
            }
            if ($operand->original instanceof Op\Expr\ArrayDimFetch) {
                return $this->lvalueContainsNullsafePropertyFetch($operand->original->var, $block);
            }
            if ($operand->original instanceof Op\Expr\PropertyFetch) {
                return $this->lvalueContainsNullsafePropertyFetch($operand->original->var, $block);
            }
            if (null === $operand->original) {
                break;
            }
            $operand = $operand->original;
        }
        if ($operand instanceof Op\Expr\NullsafePropertyFetch) {
            return true;
        }
        if ($operand instanceof Op\Expr\PropertyFetch) {
            return $this->lvalueContainsNullsafePropertyFetch($operand->var, $block);
        }
        if ($operand instanceof Op\Expr\ArrayDimFetch) {
            return $this->lvalueContainsNullsafePropertyFetch($operand->var, $block);
        }
        if (null !== $block && null !== $block->orig) {
            if ($this->operandIsNullsafePropertyFetchResult($operand, $block->orig->children)) {
                return true;
            }
            // php-cfg result temps omit `original`; resolve PropertyFetch producer for chains (#25560).
            $propFetch = $this->findPropertyFetchForResult($operand, $block);
            if (null !== $propFetch) {
                return $this->lvalueContainsNullsafePropertyFetch($propFetch->var, $block);
            }
        }

        return false;
    }

    /**
     * Zend zend_compile.c: nullsafe ?-> in l-value position is a compile-time fatal (#5323).
     *
     * @return never
     */
    protected function rejectNullsafeInWriteContext(?Operand $var, ?Block $block = null): void
    {
        if ($this->lvalueContainsNullsafePropertyFetch($var, $block)) {
            $this->throwCompileError("Can't use nullsafe operator in write context");
        }
        if (null !== $block && null !== $block->orig && null !== $var) {
            $dimFetch = $this->unwrapArrayDimFetch($var);
            if (null !== $dimFetch
                && $this->operandIsNullsafePropertyFetchResult($dimFetch->var, $block->orig->children)) {
                $this->throwCompileError("Can't use nullsafe operator in write context");
            }
        }
    }

    /**
     * Zend zend_compile.c: list spread assign withheld on 8.4.0-dev reference profile (#6936, #17182).
     *
     * @param Op[] $ops
     */
    private function rejectListDestructuringSpreadAssignProfile(array $ops, int $start, ?Block $block = null): void
    {
        $end = $this->listDestructGroupEndIndex($ops, $start, $block);
        for ($i = $start; $i <= $end; ++$i) {
            if (!$this->isListSpreadAssignOp($ops[$i])) {
                continue;
            }
            if (!CompilerVersion::supportsListDestructuringSpreadAssign()) {
                $this->throwListSpreadAssignUnsupportedFatal($ops[$i]);
            }
            if (!$this->isListDestructSpreadTail($ops, $i, $block)) {
                $this->throwListSpreadAssignUnsupportedFatal($ops[$i]);
            }
        }
    }

    private function rejectListSpreadAssignExpr(Op\Expr\Assign $expr): void
    {
        if (CompilerVersion::supportsListDestructuringSpreadAssign()) {
            return;
        }
        $this->throwListSpreadAssignUnsupportedFatal($expr);
    }

    /**
     * @param Op\Expr\Assign $spread
     *
     * @return never
     */
    private function throwListSpreadAssignUnsupportedFatal(Op\Expr\Assign $spread): void
    {
        $sourceFile = $spread->getFile() ?? '';
        if ('' === $sourceFile) {
            $sourceFile = 'unknown';
        }
        throw new CompileFatal(
            $sourceFile,
            max(1, $spread->getLine()),
            'Spread operator is not supported in assignments'
        );
    }

    /**
     * Zend zend_compile_list_assign — destructuring slots with default-value expressions compile-fatal (#14325).
     *
     * php-cfg lowers `[$a = 1] = $rhs` to dim fetch + assign($a, default) + assign($aTemp, fetch).
     *
     * @param Op[] $ops
     *
     * @return never
     */
    private function rejectListDestructDefaultValueSlotsInOps(array $ops): void
    {
        $count = count($ops);
        for ($i = 0; $i < $count; ++$i) {
            $op = $ops[$i];
            if (!$op instanceof Op\Expr\ArrayDimFetch || $i + 1 >= $count) {
                continue;
            }
            $defaultInit = $ops[$i + 1];
            if (!$defaultInit instanceof Op\Expr\Assign || $defaultInit->expr === $op->result) {
                continue;
            }
            if (!$this->isNamedVariableOperand($defaultInit->var)) {
                continue;
            }
            if ($i + 2 < $count && $ops[$i + 2] instanceof Op\Expr\Assign) {
                $chain = $ops[$i + 2];
                if (
                    $chain->expr === $op->result
                    && $this->unwrapOperandChain($chain->var) === $this->unwrapOperandChain($defaultInit->result)
                ) {
                    $this->throwListDestructNonWritableWriteFatalFromOp($defaultInit);
                }
            }
        }
    }

    /**
     * Zend zend_compile.c: list()/[] slots must target writable lvalues (#6691, #7286, #12498).
     *
     * Scan every assign in the destructuring group — php-cfg may emit New/PropertyFetch between
     * the RHS dim fetch and Assign so dim-fetch walking alone misses slots.
     *
     * @param Op[] $ops
     *
     * @return never
     */
    private function rejectListDestructNonWritableWriteTargets(array $ops, int $start, int $end, Block $block): void
    {
        for ($i = $start; $i <= $end; ++$i) {
            $op = $ops[$i];
            if (!$op instanceof Op\Expr\Assign && !$op instanceof Op\Expr\AssignRef) {
                continue;
            }
            if (!$this->assignIsListDestructSlotTarget($op->var, $block)) {
                continue;
            }
            $this->rejectThisReassignment($op->var);
            $this->rejectNullsafeInWriteContext($op->var, $block);
            if (
                !$this->lvalueIsWritableListDestructTarget($op->var, $block)
                || $this->lvalueContainsNewExpr($op->var, $block)
            ) {
                $this->throwListDestructNonWritableWriteFatalFromOp($op);
            }
        }
    }

    /**
     * True when an assign in a list-destruct group writes a slot, not an SSA read temp (#12602).
     */
    private function assignIsListDestructSlotTarget(Operand $var, ?Block $block = null): bool
    {
        if ($var instanceof Operand\Literal) {
            return true;
        }
        if ($var instanceof Op\Expr\ConstFetch || $var instanceof Op\Expr\ClassConstFetch) {
            return true;
        }
        if ($this->isNamedVariableOperand($var)) {
            return true;
        }
        if (null !== $this->unwrapPropertyFetch($var) || null !== $this->unwrapStaticPropertyFetch($var)) {
            return true;
        }
        if (null !== $this->unwrapArrayDimFetch($var)) {
            return true;
        }
        if ($var instanceof Operand\Variable && null !== $block) {
            $producer = $this->findListDestructWriteTargetProducer($var, $block);
            if (null !== $producer) {
                if ($producer instanceof Op\Expr\ArrayDimFetch) {
                    return false;
                }

                return $this->isListDestructWriteTargetPreludeOp($producer);
            }
        }

        return false;
    }

    /**
     * Writable list-destruct slot: variable, property/static-property, or dim fetch on writable base.
     */
    protected function lvalueIsWritableListDestructTarget(?Operand $var, ?Block $block = null): bool
    {
        if (null === $var) {
            return false;
        }
        if ($var instanceof Operand\Temporary && null !== $var->original) {
            return $this->lvalueIsWritableListDestructTarget($var->original, $block);
        }
        if ($var instanceof Op\Expr\ConstFetch || $var instanceof Op\Expr\ClassConstFetch) {
            return false;
        }
        if ($var instanceof Operand\Literal) {
            return false;
        }
        $dimFetch = $this->unwrapArrayDimFetch($var);
        if (null !== $dimFetch) {
            if (null !== $block && $this->operandDerivesFromNew($dimFetch->var, $block)) {
                return false;
            }

            return $this->lvalueIsWritableListDestructTarget($dimFetch->var, $block);
        }
        $propFetch = $this->unwrapPropertyFetch($var);
        if (null !== $propFetch) {
            if (null !== $block && $this->operandDerivesFromNew($propFetch->var, $block)) {
                return false;
            }

            return $this->lvalueIsWritableListDestructTarget($propFetch->var, $block);
        }
        if (null !== $this->unwrapStaticPropertyFetch($var)) {
            return true;
        }
        if (null !== $block) {
            $dimFetch = $this->findArrayDimFetchForResult($var, $block);
            if (null !== $dimFetch) {
                if ($this->operandDerivesFromNew($dimFetch->var, $block)) {
                    return false;
                }

                return $this->lvalueIsWritableListDestructTarget($dimFetch->var, $block);
            }
            $propFetch = $this->findPropertyFetchForResult($var, $block);
            if (null !== $propFetch) {
                if ($this->operandDerivesFromNew($propFetch->var, $block)) {
                    return false;
                }

                return $this->lvalueIsWritableListDestructTarget($propFetch->var, $block);
            }
            if (null !== $this->findStaticPropertyFetchForAssign($var, $block)) {
                return true;
            }
        }
        if ($var instanceof Operand\Variable) {
            if ($this->isNamedVariableOperand($var)) {
                return true;
            }
            if (null !== $block) {
                $producer = $this->findListDestructWriteTargetProducer($var, $block);
                if (null !== $producer) {
                    return $this->listDestructWriteTargetProducerIsWritable($producer, $block);
                }
            }

            return false;
        }

        return false;
    }

    /**
     * php-cfg may bind list slots to inline producer temps (ConstFetch, FuncCall, …) (#12498).
     */
    protected function findListDestructWriteTargetProducer(Operand $var, Block $block): ?Op\Expr
    {
        if (null === $block->orig) {
            return null;
        }
        $root = $this->unwrapOperandChain($var);
        foreach ($block->orig->children as $child) {
            if (!$child instanceof Op\Expr) {
                continue;
            }
            if ($this->unwrapOperandChain($child->result) === $root) {
                return $child;
            }
        }

        return null;
    }

    protected function listDestructWriteTargetProducerIsWritable(Op\Expr $producer, Block $block): bool
    {
        if ($producer instanceof Op\Expr\ConstFetch || $producer instanceof Op\Expr\ClassConstFetch) {
            return false;
        }
        if (
            $producer instanceof Op\Expr\FuncCall
            || $producer instanceof Op\Expr\MethodCall
            || $producer instanceof Op\Expr\StaticCall
            || $producer instanceof Op\Expr\New_
        ) {
            return false;
        }
        if ($producer instanceof Op\Expr\BinaryOp) {
            return false;
        }
        if ($producer instanceof Op\Expr\UnaryMinus || $producer instanceof Op\Expr\UnaryPlus) {
            return false;
        }
        if ($producer instanceof Op\Expr\Array_) {
            return false;
        }
        if ($producer instanceof Op\Expr\ArrayDimFetch) {
            if ($this->operandDerivesFromNew($producer->var, $block)) {
                return false;
            }

            return $this->lvalueIsWritableListDestructTarget($producer->var, $block);
        }
        if ($producer instanceof Op\Expr\PropertyFetch) {
            if ($this->operandDerivesFromNew($producer->var, $block)) {
                return false;
            }

            return $this->lvalueIsWritableListDestructTarget($producer->var, $block);
        }
        if ($producer instanceof Op\Expr\StaticPropertyFetch) {
            return true;
        }

        return true;
    }

    /**
     * @return never
     */
    private function throwListDestructNonWritableWriteFatalFromOp(Op $op): void
    {
        $sourceFile = $op->getFile() ?? '';
        if ('' === $sourceFile) {
            $sourceFile = 'unknown';
        }
        throw new CompileFatal(
            $sourceFile,
            max(1, $op->getLine()),
            'Assignments can only happen to writable values'
        );
    }

    /**
     * @return never
     */
    private function throwListDestructNonWritableWriteFatal(Op\Expr\Assign $assign): void
    {
        $this->throwListDestructNonWritableWriteFatalFromOp($assign);
    }

    /**
     * File-scope `const` names registered during this compile unit (#6935).
     */
    protected function operandIsCompileTimeGlobalConstFetch(?Operand $operand, ?Block $block = null): bool
    {
        if (null === $operand) {
            return false;
        }
        $root = $this->unwrapOperandChain($operand);
        if ($root instanceof Op\Expr\ConstFetch) {
            $name = $this->staticNameFromOperand($root->name);
            if (null === $name) {
                return false;
            }

            return isset($this->compileTimeGlobalConsts[strtolower($name)]);
        }
        if (null === $block || null === $block->orig) {
            return false;
        }
        foreach ($block->orig->children as $child) {
            if (!$child instanceof Op\Expr\ConstFetch) {
                continue;
            }
            if ($this->unwrapOperandChain($child->result) !== $root) {
                continue;
            }
            $name = $this->staticNameFromOperand($child->name);
            if (null === $name) {
                continue;
            }
            if (isset($this->compileTimeGlobalConsts[strtolower($name)])) {
                return true;
            }
        }

        return false;
    }

    /**
     * Class `const` names registered during this compile unit (#5409).
     */
    protected function operandIsCompileTimeClassConstFetch(?Operand $operand, ?Block $block = null): bool
    {
        if (null === $operand || null === $block) {
            return false;
        }
        $root = $this->unwrapOperandChain($operand);
        if ($root instanceof Op\Expr\ClassConstFetch) {
            return $this->compileTimeClassConstFetchRegistered($root, $block);
        }
        if (null === $block->orig) {
            return false;
        }
        foreach ($block->orig->children as $child) {
            if (!$child instanceof Op\Expr\ClassConstFetch) {
                continue;
            }
            if ($this->unwrapOperandChain($child->result) !== $root) {
                continue;
            }
            if ($this->compileTimeClassConstFetchRegistered($child, $block)) {
                return true;
            }
        }

        return false;
    }

    protected function compileTimeClassConstFetchRegistered(
        Op\Expr\ClassConstFetch $fetch,
        Block $block,
    ): bool {
        $className = $this->staticNameFromOperand($fetch->class);
        $constName = $this->staticNameFromOperand($fetch->name);
        if (null === $className || null === $constName || 'class' === strtolower($constName)) {
            return false;
        }
        $lcClass = $this->resolveDefaultClassConstScope($className, $block);
        if (null === $lcClass) {
            return false;
        }

        return isset($this->compileTimeClassConsts[$lcClass][ClassConstName::key($constName)])
            && ClassConstName::matchesDeclared(
                $constName,
                $this->compileTimeClassConstNames[$lcClass][ClassConstName::key($constName)] ?? null
            );
    }

    protected function operandIsCompileTimeConstFetch(?Operand $operand, ?Block $block = null): bool
    {
        return $this->operandIsCompileTimeGlobalConstFetch($operand, $block)
            || $this->operandIsCompileTimeClassConstFetch($operand, $block);
    }

    /**
     * Any ConstFetch / ClassConstFetch (registered or not).
     *
     * Zend rejects dim/prop write and assign-by-ref on constant fetches as
     * "temporary expression in write context" even when the name is undefined
     * or only exists via runtime define() (#5409, #26488). Registration in
     * compileTimeGlobalConsts must not gate this — #17676 correctly stopped
     * seeding define() array values for folding, which regressed write-context.
     */
    protected function operandIsConstOrClassConstFetch(?Operand $operand, ?Block $block = null): bool
    {
        if (null === $operand) {
            return false;
        }
        $root = $this->unwrapOperandChain($operand);
        if ($root instanceof Op\Expr\ConstFetch || $root instanceof Op\Expr\ClassConstFetch) {
            return true;
        }
        if (null === $block || null === $block->orig) {
            return false;
        }
        foreach ($block->orig->children as $child) {
            if (!$child instanceof Op\Expr\ConstFetch && !$child instanceof Op\Expr\ClassConstFetch) {
                continue;
            }
            if ($this->unwrapOperandChain($child->result) === $root) {
                return true;
            }
        }

        return false;
    }

    /**
     * Zend zend_compile.c: mutating a const/class-const array is a compile-time fatal (#6935, #5409, #26488).
     */
    protected function lvalueContainsGlobalConstFetch(?Operand $operand, ?Block $block = null): bool
    {
        if (null === $operand || null === $block) {
            return false;
        }
        if ($operand instanceof Operand\Temporary && null !== $operand->original) {
            if ($operand->original instanceof Op\Expr\PropertyFetch) {
                /** @var Op\Expr\PropertyFetch $propFetch */
                $propFetch = $operand->original;
                if ($this->operandIsConstOrClassConstFetch($propFetch->var, $block)) {
                    return true;
                }

                return $this->lvalueContainsGlobalConstFetch($propFetch->var, $block);
            }
            if ($operand->original instanceof Op\Expr\ArrayDimFetch) {
                /** @var Op\Expr\ArrayDimFetch $dimFetch */
                $dimFetch = $operand->original;
                if ($this->operandIsConstOrClassConstFetch($dimFetch->var, $block)) {
                    return true;
                }

                return $this->lvalueContainsGlobalConstFetch($dimFetch->var, $block);
            }

            return $this->lvalueContainsGlobalConstFetch($operand->original, $block);
        }
        if (null !== $block->orig) {
            $propFetch = $this->findPropertyFetchForResult($operand, $block);
            if (null !== $propFetch) {
                if ($this->operandIsConstOrClassConstFetch($propFetch->var, $block)) {
                    return true;
                }

                return $this->lvalueContainsGlobalConstFetch($propFetch->var, $block);
            }
            $dimFetch = $this->findArrayDimFetchForResult($operand, $block);
            if (null !== $dimFetch) {
                if ($this->operandIsConstOrClassConstFetch($dimFetch->var, $block)) {
                    return true;
                }

                return $this->lvalueContainsGlobalConstFetch($dimFetch->var, $block);
            }
        }

        return $this->operandIsConstOrClassConstFetch($operand, $block);
    }

    /**
     * Resolve Zend-shaped file/line for temporary write-context fatals (#29769 / #27718).
     *
     * @return array{0: string, 1: int}
     */
    protected function resolveWriteContextFatalSite(?Operand $var, ?Block $block, ?Op $siteOp = null): array
    {
        $file = '';
        $line = 0;
        if (null !== $siteOp) {
            $file = (string) ($siteOp->getFile() ?? '');
            $line = (int) $siteOp->getLine();
        }
        if (
            ('' === $file || $line <= 0)
            && $var instanceof Operand\Temporary
            && $var->original instanceof Op
        ) {
            if ('' === $file) {
                $file = (string) ($var->original->getFile() ?? '');
            }
            if ($line <= 0) {
                $line = (int) $var->original->getLine();
            }
        }
        if (('' === $file || $line <= 0) && null !== $block && null !== $block->orig) {
            foreach ($block->orig->children as $child) {
                if (!$child instanceof Op) {
                    continue;
                }
                $matches = false;
                if ($child instanceof Op\Expr\Assign || $child instanceof Op\Expr\AssignRef) {
                    $matches = null !== $var && (
                        $child->var === $var
                        || $this->operandsReferToSameVariable($child->var, $var)
                    );
                } elseif ($child instanceof Op\Expr\ArrayDimFetch || $child instanceof Op\Expr\PropertyFetch) {
                    $matches = null !== $var && (
                        $child->result === $var
                        || $this->operandsReferToSameVariable($child->result, $var)
                    );
                }
                if (!$matches) {
                    continue;
                }
                if ('' === $file) {
                    $file = (string) ($child->getFile() ?? '');
                }
                if ($line <= 0) {
                    $line = (int) $child->getLine();
                }
                if ('' !== $file && $line > 0) {
                    break;
                }
            }
        }
        if ('' === $file && null !== $block) {
            $file = $block->scriptPath();
        }
        if ('' === $file) {
            $file = $this->debugLastPhaseInputFile ?? 'unknown';
        }
        if ('' === $file) {
            $file = 'unknown';
        }

        return [$file, max(1, $line)];
    }

    /**
     * Zend-shaped temporary write-context compile fatal (not parseAndCompile wrapper) (#29769).
     *
     * @return never
     */
    protected function throwWriteContextCompileFatal(
        string $message,
        ?Operand $var = null,
        ?Block $block = null,
        ?Op $siteOp = null,
    ): void {
        [$file, $line] = $this->resolveWriteContextFatalSite($var, $block, $siteOp);
        $this->throwCompileError($message, $file, $line);
    }

    /**
     * @return never
     */
    protected function rejectGlobalConstInWriteContext(?Operand $var, ?Block $block = null, ?Op $siteOp = null): void
    {
        if (!$this->lvalueContainsGlobalConstFetch($var, $block)) {
            return;
        }
        $this->throwWriteContextCompileFatal(
            'Cannot use temporary expression in write context',
            $var,
            $block,
            $siteOp,
        );
    }

    /**
     * True when $operand is an inline Op\Expr\Array_ result (php-cfg may omit ->original).
     */
    protected function operandIsArrayLiteral(?Operand $operand, ?Block $block = null): bool
    {
        if (null === $operand) {
            return false;
        }
        if (null !== $this->unwrapArrayLiteralExpr($operand)) {
            return true;
        }
        if (null === $block) {
            return false;
        }

        return null !== $this->findArrayExprForResult($operand, $block);
    }

    /**
     * Zend zend_compile.c: dim/append/unset on an array literal is a temporary write (#29247).
     *
     * Function-return dims remain writable (f()[0] = …); only inline Expr_Array bases are rejected.
     */
    protected function lvalueContainsArrayLiteral(?Operand $operand, ?Block $block = null): bool
    {
        if (null === $operand || null === $block) {
            return false;
        }
        if ($operand instanceof Operand\Temporary && null !== $operand->original) {
            if ($operand->original instanceof Op\Expr\PropertyFetch) {
                $propFetch = $operand->original;
                if ($this->operandIsArrayLiteral($propFetch->var, $block)) {
                    return true;
                }

                return $this->lvalueContainsArrayLiteral($propFetch->var, $block);
            }
            if ($operand->original instanceof Op\Expr\ArrayDimFetch) {
                $dimFetch = $operand->original;
                if ($this->operandIsArrayLiteral($dimFetch->var, $block)) {
                    return true;
                }

                return $this->lvalueContainsArrayLiteral($dimFetch->var, $block);
            }

            return $this->lvalueContainsArrayLiteral($operand->original, $block);
        }
        if (null !== $block->orig) {
            $propFetch = $this->findPropertyFetchForResult($operand, $block);
            if (null !== $propFetch) {
                if ($this->operandIsArrayLiteral($propFetch->var, $block)) {
                    return true;
                }

                return $this->lvalueContainsArrayLiteral($propFetch->var, $block);
            }
            $dimFetch = $this->findArrayDimFetchForResult($operand, $block);
            if (null !== $dimFetch) {
                if ($this->operandIsArrayLiteral($dimFetch->var, $block)) {
                    return true;
                }

                return $this->lvalueContainsArrayLiteral($dimFetch->var, $block);
            }
        }

        return $this->operandIsArrayLiteral($operand, $block);
    }

    /**
     * @return never
     */
    protected function rejectArrayLiteralInWriteContext(?Operand $var, ?Block $block = null, ?Op $siteOp = null): void
    {
        if (!$this->lvalueContainsArrayLiteral($var, $block)) {
            return;
        }
        $this->throwWriteContextCompileFatal(
            'Cannot use temporary expression in write context',
            $var,
            $block,
            $siteOp,
        );
    }

    /**
     * Shared write-context guards for Assign / unset / FETCH_*_W (incl. by-ref call args) (#29522).
     *
     * Function-return dims remain writable (f(g()[0]) when g returns by value) — only temporary
     * array literals / new / const / bare call returns are rejected.
     */
    protected function rejectTemporaryExpressionInWriteContext(?Operand $var, ?Block $block = null, ?Op $siteOp = null): void
    {
        $this->rejectNewExprInWriteContext($var, $block, null, null, $siteOp);
        $this->rejectArrayLiteralInWriteContext($var, $block, $siteOp);
        $this->rejectGlobalConstInWriteContext($var, $block, $siteOp);
        $this->rejectCallReturnInWriteContext($var, $block, $siteOp);
    }

    /**
     * Zend zend_compile.c: SEND_REF of temporary lit-dim / new-prop / const is illegal (#29522).
     *
     * Function-return dims remain allowed (f(g()[0])); do not call rejectCallReturnInWriteContext.
     */
    protected function rejectTemporaryByRefCallArg(?Operand $arg, ?Block $block = null, ?Op $siteOp = null): void
    {
        $this->rejectNewExprInWriteContext($arg, $block, null, null, $siteOp);
        $this->rejectArrayLiteralInWriteContext($arg, $block, $siteOp);
        $this->rejectGlobalConstInWriteContext($arg, $block, $siteOp);
    }

    /**
     * Zend zend_compile.c: assigning to a property/offset of a `new` temporary is illegal (#6691).
     */
    protected function lvalueContainsNewExpr(?Operand $operand, ?Block $block = null): bool
    {
        if (null === $operand || null === $block) {
            return false;
        }
        if ($operand instanceof Operand\Temporary && null !== $operand->original) {
            if ($operand->original instanceof Op\Expr\PropertyFetch) {
                $propFetch = $operand->original;
                if ($this->operandDerivesFromNew($propFetch->var, $block)) {
                    return true;
                }

                return $this->lvalueContainsNewExpr($propFetch->var, $block);
            }
            if ($operand->original instanceof Op\Expr\ArrayDimFetch) {
                $dimFetch = $operand->original;
                if ($this->operandDerivesFromNew($dimFetch->var, $block)) {
                    return true;
                }

                return $this->lvalueContainsNewExpr($dimFetch->var, $block);
            }

            return $this->lvalueContainsNewExpr($operand->original, $block);
        }
        if (null !== $block->orig) {
            $propFetch = $this->findPropertyFetchForResult($operand, $block);
            if (null !== $propFetch) {
                if ($this->operandDerivesFromNew($propFetch->var, $block)) {
                    return true;
                }

                return $this->lvalueContainsNewExpr($propFetch->var, $block);
            }
            $dimFetch = $this->findArrayDimFetchForResult($operand, $block);
            if (null !== $dimFetch) {
                if ($this->operandDerivesFromNew($dimFetch->var, $block)) {
                    return true;
                }

                return $this->lvalueContainsNewExpr($dimFetch->var, $block);
            }
        }

        return $this->operandDerivesFromNew($operand, $block);
    }

    /**
     * @return never
     */
    protected function rejectNewExprInWriteContext(
        ?Operand $var,
        ?Block $block = null,
        ?Operand $assignExpr = null,
        ?Op $assignOp = null,
        ?Op $siteOp = null,
    ): void {
        if (!$this->lvalueContainsNewExpr($var, $block)) {
            return;
        }
        $site = $siteOp ?? $assignOp;
        if (null !== $assignExpr && null !== $block && null !== $this->findArrayDimFetchForResult($assignExpr, $block)) {
            if ($assignOp instanceof Op\Expr\Assign) {
                $this->throwListDestructNonWritableWriteFatal($assignOp);
            }
            $this->throwWriteContextCompileFatal(
                'Assignments can only happen to writable values',
                $var,
                $block,
                $site,
            );
        }
        $this->throwWriteContextCompileFatal(
            'Cannot use temporary expression in write context',
            $var,
            $block,
            $site,
        );
    }

    /**
     * True when $op is a call whose return may not be used as a write target (zend_compile.c).
     */
    protected function isCallReturnWriteExpr(Op $op): bool
    {
        return $op instanceof Op\Expr\MethodCall
            || $op instanceof Op\Expr\StaticCall
            || $op instanceof Op\Expr\NullsafeMethodCall
            || $op instanceof Op\Expr\FuncCall
            || $op instanceof Op\Expr\NsFuncCall;
    }

    /**
     * Direct call-result lvalue only — dim/prop of a call return remain writable (#26436).
     */
    protected function findDirectCallReturnForWriteOperand(?Operand $operand, ?Block $block): ?Op\Expr
    {
        if (null === $operand || null === $block || null === $block->orig) {
            return null;
        }
        if (
            $operand instanceof Operand\Temporary
            && null !== $operand->original
            && $operand->original instanceof Op
            && $this->isCallReturnWriteExpr($operand->original)
        ) {
            return $operand->original;
        }
        foreach ($block->orig->children as $child) {
            if (!$child instanceof Op\Expr || !$this->isCallReturnWriteExpr($child)) {
                continue;
            }
            if ($child->result === $operand) {
                return $child;
            }
            if ($this->operandsReferToSameVariable($child->result, $operand)) {
                return $child;
            }
        }

        return null;
    }

    /**
     * Zend zend_compile.c: method/function call results are illegal write targets (#26436).
     *
     * @return never
     */
    protected function rejectCallReturnInWriteContext(?Operand $var, ?Block $block = null, ?Op $siteOp = null): void
    {
        $call = $this->findDirectCallReturnForWriteOperand($var, $block);
        if (null === $call) {
            return;
        }
        $site = $siteOp ?? $call;
        if (
            $call instanceof Op\Expr\FuncCall
            || $call instanceof Op\Expr\NsFuncCall
        ) {
            $this->throwWriteContextCompileFatal(
                "Can't use function return value in write context",
                $var,
                $block,
                $site,
            );
        }
        $this->throwWriteContextCompileFatal(
            "Can't use method return value in write context",
            $var,
            $block,
            $site,
        );
    }

}
